P.entries["item:filled-red-waterskin"] = {n="Odre Vermelho Cheio",s="O Odre Vermelho Cheio contém água pura de nascente retirada do poço da aldeia na Serraria Tarren. Coletar essa água pura em meio às ruínas devastadas sob o controle dos Renegados serve como uma provação vital para jovens xamãs que buscam comunhão com os espíritos da água.",h="O Odre Vermelho Cheio contém água pura de nascente retirada do poço da aldeia na Serraria Tarren.",kw={"salma","call of water","odre vermelho vazio","odre vermelho cheio","sapta","xamã","serraria tarren"},ang={["class:Shaman"]="Carregar essa água testa a habilidade de um xamã de encontrar e honrar o equilíbrio vivificante até mesmo nos cantos mais decadentes e tristes do mundo.",["faction:Horde"]="Visitar a Serraria Tarren leva os jovens campeões de Kalimdor ao coração da luta dos Renegados contra as forças da Aliança pelos Reinos do Leste."},sec={{t="Um Farol em Terras Devastadas",b="Ao treinar xamãs nos caminhos da água, a eremita Salma, nos Sertões, envia iniciados em uma longa jornada até a Serraria Tarren, no Contraforte de Eira dos Montes. Em meio à decadência e aos mortos, o poço central da cidade milagrosamente puxa água pura e límpida da nascente. Salma considera esse vestígio sagrado em uma terra profanada como um emblema de espírito perseverante — traçando um paralelo entre a nascente incorrupta e a determinação duradoura do Chefe Guerreiro Thrall diante de profundas adversidades. Coletar essa amostra prova a reverência do iniciado pela pureza da água, a despeito do ambiente hostil."}},faq={{q="O que há dentro do Odre Vermelho Cheio?",a="Ele contém água pura e límpida de nascente, retirada diretamente do poço público no centro da Serraria Tarren.",al={"que água tem nele","água de serraria tarren","conteúdo do odre vermelho"}},{q="Por que Salma quer água da Serraria Tarren?",a="Salma considera a nascente fresca da cidade um vestígio milagroso de pureza sobrevivendo em meio à decadência dos Renegados. Ela precisa dessa amostra sagrada como ingrediente para preparar a sapta necessária para os testes de água de um xamã.",al={"por que serraria tarren","por que salma precisa disso","propósito do odre vermelho"}},{q="Como o poço permanece limpo em uma cidade de mortos-vivos?",a="Ninguém sabe; a nascente de alguma forma permaneceu intocada pela praga ao seu redor. Salma observa que os Renegados que habitam a Serraria Tarren talvez nem reconheçam ou deem valor à pureza do vestígio sagrado em seu meio.",al={"por que o poço não está arruinado","o poço de serraria tarren está envenenado","poço sagrado de serraria tarren"}},{q="Qual a relação de Thrall com esta missão?",a="Salma compara o poço limpo que sobrevive em uma cidade em ruínas a Thrall, que suportou imenso sofrimento e cativeiro, mas emergiu forte e intocado para guiar o povo órfico por tempos sombrios.",al={"comparação com thrall","por que mencionar thrall"}}},fx={c913c28c={q="De onde vem o Odre Vermelho Cheio?",a="Você o obtém carregando um Odre Vermelho Vazio — fornecido a você por Salma nos Sertões — até o Contraforte de Eira dos Montes e retirando água pura do poço da vila em Serraria Tarren. Salma lembra do poço como uma bolsa surpreendente de água fresca de nascente que persiste no meio de um assentamento dos Renegados.",al={"origem do odre vermelho cheio","onde conseguir o odre vermelho cheio","quem fez o odre vermelho cheio"}}},fp="20,170,26.516.0,40.105.0,43.150.0,47.181.0,37.180.0"}
P.entries["item:filled-soul-gem"] = {n="Joia de Alma Plena",s="Nimboya pede que você leve a Gema Anímica até Grom'gol, onde seu povo aguarda o retorno de Yennikan.",h="Nimboya pede que você leve a Gema Anímica até Grom'gol, onde seu povo aguarda o retorno de Yennikan.",kw={"joia de alma plena","grom'gol","kin'weelay","olho da mente","nimboya","gema anímica","yennikan","zanzil"},sec={{t="Uma alma restaurada",b="Nas Ruínas de Aboraz, no Cabo do Espinhaço, a Gema Anímica é colocada sobre a cabeça de Yennikan para capturar sua alma. Leve a Joia de Alma Plena a Nimboya, em Grom'gol, onde seu povo aguarda o retorno dele."}},faq={{q="O que é a Joia de Alma Plena?",a="A Joia de Alma Plena contém a alma de Yennikan, capturada com a Gema Anímica nas Ruínas de Aboraz.",al={"joia preenchida","gema anímica com yennikan","o que há na joia"}},{q="Quem é Yennikan?",a="Yennikan é membro da tribo de Nimboya e está sob o domínio de Zanzil the Outcast.",al={"história de yennikan","quem é yennikan","yennikan"}},{q="Para onde levo a joia?",a="Leve a Joia de Alma Plena até Nimboya, em Grom'gol.",al={"para onde vai a joia","onde levar a joia","joia de nimboya"}},{q="Como a Gema Anímica foi criada?",a="Kin'weelay transformou o Olho da Mente em uma Gema Anímica, capaz de capturar a alma de Yennikan.",al={"gema do olho da mente","como preencher a gema anímica","receita de gema anímica"}}},fp="15,92,15.196.0,28.95.1,15.83.0,24.49.0,26.82.1"}
P.entries["item:filled-tainted-ooze-jar"] = {n="Jarra de Gosma Maculada Cheia",s="Uma Jarra de Gosma Maculada Cheia contém gosma viscosa e maculada recolhida diretamente dos restos de gosmas que vagam pelas florestas corrompidas de Selva Maleva. Protegidas em jarras de contenção especializadas, essas amostras são levadas para Altaforja para apoiar teorias radicais sobre a origem da vida em Azeroth.",h="Uma Jarra de Gosma Maculada Cheia contém gosma viscosa e maculada recolhida diretamente dos restos de gosmas...",kw={"liga dos exploradores","selva maleva","altaforja","laris vagarroda","real sociedade de boticários","visgo","gosma maculada"},ang={["faction:Alliance"]="Batedores da Aliança monitoram de perto a Sociedade Real dos Boticários dos Renegados; compreender por que a Cidade Baixa colhe visgo pelos continentes é uma prioridade crucial de inteligência.",["race:Gnome"]="Para os refugiados gnômicos que vivem em Altaforja, contribuições científicas inovadoras para a Liga dos Exploradores são vitais para provar seu valor e retribuir a hospitalidade dos anões após a tragédia de Gnomeregan."},sec={{t="Visgo da Floresta Corrompida",b="As gosmas maculadas que vagam pelo norte de Kalimdor carregam a corrupção profunda e duradoura de Selva Maleva. Coletá-las requer contenção cuidadosa com o uso de jarras fornecidas por pesquisadores gnômicos. Embora a maioria dos viajantes evite completamente essas criaturas nocivas, coletar essas amostras fornece material raro para a filosofia natural e o estudo biológico longe das florestas assoladas."},{t="A Grande Teoria de Vagarroda",b="As amostras são reunidas em nome de Laris Vagarroda, um ambicioso estudioso gnomo baseado na Liga dos Exploradores em Altaforja. Vagarroda é fascinado pela natureza onipresente dos visgos e percebeu que a Sociedade Real dos Boticários dos Renegados também tem demonstrado um interesse ativo neles. Desafiando o ceticismo acadêmico geral, ele teoriza que visgos e gosmas podem ser secreções primordiais ligadas à própria criação de Azeroth. Obter essas amostras é a sua tentativa de provar seu valor entre os estudiosos anões após a trágica queda de Gnomeregan."}},faq={{q="O que há dentro de uma Jarra de Gosma Maculada Cheia?",a="Ela contém uma amostra fresca e capturada, retirada dos restos de uma Gosma Maculada derrotada e nativa de Selva Maleva, selada dentro de uma jarra de coleta gnômica.",al={"o que há na jarra","conteúdo da jarra de gosma maculada","o que é gosma maculada"}},{q="Quem deseja essas amostras de gosma?",a="Laris Vagarroda, um pesquisador gnomo que trabalha junto à Liga dos Exploradores no Hall of Explorers em Altaforja, as solicita para avançar seus estudos de história natural.",al={"quem pega a gosma","missão de laris vagarroda","quem quer gosma maculada"}},{q="Por que Laris Vagarroda está estudando gosmas?",a="Vagarroda observou a Sociedade Real dos Boticários coletando amostras de visgo e decidiu desvendar a natureza deles primeiro. Ele tem uma teoria não convencional de que as gosmas são secreções primordiais conectadas à criação de Azeroth e espera consolidar sua reputação científica em Altaforja.",al={"por que estudar visgo","teoria do visgo de vagarroda","por que o gnomo quer gosma"}},{q="Onde essas amostras são coletadas?",a="Elas são coletadas em Selva Maleva ao derrotar Gosmas Maculadas e usar uma jarra de contenção vazia em seus restos.",al={"onde encontrar gosma maculada","local da jarra de gosma maculada","onde encher a jarra"}}},fx={["297c9c04"]={q="De onde vem uma Jarra de Gosma Maculada Cheia e quem a fez?",a="A jarra em si é fornecida pelo pesquisador gnomo Laris Vagarroda em Altaforja, que cria recipientes de vidro vazios especializados para coletar espécimes voláteis com segurança. Ela só fica cheia depois que um aventureiro mata uma gosma maculada nas florestas corrompidas da Selva Maleva e usa a jarra para raspar remanescentes dos restos gelatinosos da criatura.",al={"origem da jarra de gosma maculada","quem fez a jarra de gosma maculada","de onde vêm as jarras de gosma maculada"}}},fp="23,137,27.291.0,25.431.0,41.136.0,29.148.0,39.233.0,34.115.0"}
P.entries["item:filled-tourmaline-phial"] = {n="Frasco de Turmalina Cheio",s="O Frasco de Turmalina Cheio contém águas encantadas retiradas do poço da lua que margeia as Águas de Arlithrien, no sul de Teldrassil. Coletada a pedido de Corithras Lunafúria, a água serve como parte de um esforço para monitorar a saúde e o equilíbrio da crescente Árvore do Mundo.",h="O Frasco de Turmalina Cheio contém águas encantadas retiradas do poço da lua que margeia as Águas de...",kw={"corithras lunafúria","crown of the earth","frasco de turmalina cheio","gnarlpine","poço da lua","águas de arlithrien","teldrassil","frasco de turmalina"},ang={["class:Druid"]="Para os druidas, carregar o frasco toca diretamente no controverso legado do Arquidruida Fandral Guenelmo, que insistiu no plantio de Teldrassil durante a ausência inexplicada de Shan'do Tempesfúria.",["race:NightElf"]="As águas do poço da lua são uma fonte vital espiritual essencial para os kaldorei, tornando a corrupção dos bosques Gnarlpine ao redor um presságio profundamente perturbador para seu novo lar."},sec={{t="Águas de Arlithrien",b="O Frasco de Turmalina é preparado especificamente para retirar água do poço da lua localizado a sudeste de The Road to Darnassus, nas margens das Águas de Arlithrien. Coletar água deste santuário tornou-se repleto de perigo devido à agressão repentina dos ursobolgas Gnarlpine, vizinhos pacíficos que se deterioraram rapidamente em uma loucura violenta. Corithras Lunafúria encarrega viajantes de desafiar os bosques hostis para proteger esta água, com o objetivo de diagnosticar a corrupção cada vez mais profunda que perturba a terra."},{t="As Raízes de Teldrassil",b="Trazer o frasco de volta para Dolanaar faz com que Corithras Lunafúria reflita sobre a gênese dos galhos acima. Após o desaparecimento de Shan'do Malfurion Tempesfúria, o Arquidruida Fandral Guenelmo reuniu o Círculo dos Anciãos do outro lado do mar, em Costa Negra, para plantar Teldrassil na esperança de recuperar sua imortalidade perdida. As águas transportadas dentro do frasco adornado refletem o estado desse experimento sagrado — uma ambição agora maculada por uma enfermidade inexplicável que se espalha tanto em feras quanto em ursobolgas."}},faq={{q="Para que serve o Frasco de Turmalina Cheio?",a="É um recipiente encantado de água de poço da lua solicitado por Corithras Lunafúria em Dolanaar. Ele coleta águas de poços da lua por toda Teldrassil para estudar a disseminação da corrupção e explicar a história da Árvore do Mundo a defensores recém-chegados.",al={"uso do frasco de turmalina cheio","propósito do frasco de turmalina","por que encher o frasco"}},{q="Onde fica o poço da lua do Frasco de Turmalina?",a="O poço da lua fica a sudeste do portão principal de Darnassus, situado ao longo das margens das Águas de Arlithrien, no sudoeste de Teldrassil. A área é fortemente disputada por furiosos ursobolgas Gnarlpine.",al={"onde encher o frasco de turmalina","poço da lua das águas de arlithrien","localização do poço de arlithrien"}},{q="Por que os ursobolgas perto do poço da lua estão atacando?",a="Os ursobolgas Gnarlpine, outrora homens-urso pacíficos que viviam ao lado dos elfos noturnos, foram vítimas de uma corrupção insidiosa que aflige Teldrassil. Sua súbita decadência em violência cega é um dos vários sintomas que assolam a jovem Árvore do Mundo.",al={"por que os gnarlpine estão enlouquecidos","hostilidade dos ursobolgas em arlithrien","gnarlpine enlouquecidos"}},{q="Quem é Corithras Lunafúria?",a="Corithras Lunafúria é um erudito e zelador elfo noturno estabelecido em Dolanaar. Ele guia jovens aventureiros pelo rito conhecido como Crown of the Earth, ensinando-os sobre a história dos elfos noturnos, o plantio de Teldrassil e o desaparecimento de Malfurion Tempesfúria.",al={"papel de corithras","corithras dolanaar"}}},fx={b07aae52={q="De onde vem o Frasco de Turmalina Cheio?",a="O recipiente em si é fornecido por Corithras Lunafúria em Dolanaar. Você cria o frasco cheio levando-o para o sudeste de Darnassus, até o poço da lua que fica às margens das Águas de Arlithrien, e retirando água diretamente da bacia em meio aos furbolgs Gnarlpine agitados que rondam o local.",al={"origem do frasco de turmalina cheio","de onde veio o frasco de turmalina cheio"}},c83d83e7={q="Por que Corithras Lunafúria quer o Frasco de Turmalina Cheio?",a="Corithras Lunafúria coleta as águas dos vários poços da lua de Teldrassil para avaliar e preservar a vitalidade espiritual da jovem Árvore do Mundo. À medida que a corrupção se infiltra nos galhos e enlouquece os furbolgs Gnarlpine nativos, coletar e examinar a água de todos os galhos ajuda os druidas a manter seu equilíbrio sagrado e entender o que assola seu lar.",al={"por que corithras quer o frasco","propósito do frasco de turmalina cheio","por que coletar água do poço da lua"}},["360c6167"]={q="O que é o Frasco de Turmalina Cheio?",a="É um frasco de turmalina vazio preenchido com as águas sagradas e luminescentes do poço da lua perto das Águas de Arlithrien em Teldrassil. Os druidas elfos noturnos usam frascos esculpidos de minerais distintos para colher água pura de poço da lua por toda a ilha, mantendo cada amostra distinta para seus ritos sagrados e a purificação da terra.",al={"o que é o frasco de turmalina cheio","item frasco de turmalina cheio"}}},fp="23,170,20.383.0,23.411.1,45.258.0,55.170.0,49.195.0,26.256.0"}
P.entries["item:filled-vessel"] = {n="Recipiente Cheio",s="O Recipiente Cheio contém águas purificadas retiradas dos vários poços lunares sagrados de Teldrassil. Confiado a mensageiros por Corithras Lunafúria em Dolanaar, ele é entregue ao Arquidruida Fandral Guenelmo em Darnassus para auxiliar em seu estudo sobre as enfermidades da Árvore do Mundo.",h="O Recipiente Cheio contém águas purificadas retiradas dos vários poços lunares sagrados de Teldrassil.",kw={"enclave cenariano","corithras lunafúria","coroa da terra","darnassus","fandral guenelmo","recipiente cheio","água do poço lunar","teldrassil"},ang={["class:Druid"]="Para os iniciados Cenarianos, entregar este recipiente marca sua primeira incumbência oficial para o Arquidruida Fandral Guenelmo, testemunhando de perto a fragilidade ecológica enfrentada por Teldrassil.",["race:NightElf"]="As águas dos poços lunares em seu interior representam os alentos sagrados do novo lar dos kaldorei, mesclando a magia de Eluna com o crescimento incerto da Árvore do Mundo não abençoada."},sec={{t="Uma Confluência de Águas Sagradas",b="Teldrassil foi plantada sem as bênçãos dos Grandes Aspectos, Alexstrasza e Nozdormu, deixando seus imensos galhos vulneráveis a corrupções inesperadas, feras estranhas e tribos de fúrbolgs enlouquecidos. Na tentativa de monitorar e purificar os galhos em crescimento, acólitos elfos noturnos são enviados para coletar amostras de água de poços lunares situados por toda a copa. Corithras Lunafúria reúne esses frascos coletados em um único Recipiente Cheio, enviando-o para a capital. A mistura serve como uma amostra vital da vitalidade de Teldrassil para o Arquidruida Fandral Guenelmo, que trabalha incansavelmente no Enclave Cenariano para descobrir um remédio para as imperfeições que assolam a Grande Árvore."}},faq={{q="O que há dentro do Recipiente Cheio?",a="O recipiente contém água coletada de vários poços lunares espalhados por Teldrassil, reunida em um único frasco por Corithras Lunafúria em Dolanaar.",al={"conteúdo do recipiente","que água é esta","o que há no recipiente"}},{q="Quem precisa do Recipiente Cheio?",a="O Recipiente Cheio é levado ao Arquidruida Fandral Guenelmo, que reside no topo do Enclave Cenariano em Darnassus.",al={"a quem entregar o recipiente cheio","para onde vai o recipiente","entrega do recipiente cheio"}},{q="Por que Fandral Guenelmo precisa dessas amostras de água?",a="Teldrassil não possui as bênçãos tradicionais dos aspectos dragônicos, fazendo com que corrupções estranhas, fauna agressiva e fúrbolgs enlouquecidos assolem seus galhos. Guenelmo estuda essas águas misturadas para diagnosticar as falhas da árvore e buscar um remédio para suas aflições.",al={"por que guenelmo quer água","propósito da água do poço lunar de guenelmo","por que coletar água do poço lunar"}},{q="Quem preparou o recipiente?",a="Corithras Lunafúria, um elfo noturno baseado em Dolanaar, despeja os frascos coletados por jovens aventureiros dentro do recipiente antes de enviá-los para Darnassus.",al={"quem fez o recipiente cheio","quem dá o recipiente cheio","recipiente cheio de corithras"}}},fp="13,194,29.537.0,33.132.0,28.103.0,51.239.0,24.136.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="A Final Clue to Sanders' Treasure é uma nota manchada de uísque encontrada dentro de uma jarra velha na costa de Cerro Oeste. Ela fornece as instruções finais deixadas pelo falecido pirata Captain Sanders, guiando saqueadores diretamente para o mar aberto para recuperar seu espólio enterrado.",h="A Final Clue to Sanders' Treasure é uma nota manchada de uísque encontrada dentro de uma jarra velha na costa...",kw={"captain sanders","baú","pista","pirata","tesouro","cerro oeste","jarra de uísque"},ang={["class:Rogue"]="Seguir o enigma encharcado de uísque de um pirata morto rumo ao mar aberto é trabalho clássico de canalha, provando que o litoral de Cerro Oeste guarda despojos que vão além dos bolsos dos Defias."},sec={{t="As Palavras de Despedida de um Marinheiro",b="Exalando um cheiro forte de bebidas alcoólicas, este pergaminho borrado marca o fim da intrincada trilha de pistas do Captain Sanders por Cerro Oeste. O falecido bucaneiro, conhecido por deixar instruções enigmáticas ao longo do litoral, escondeu sua última nota no fundo de uma velha jarra de uísque junto à costa. As instruções são rudes, porém diretas: siga para o oeste em direção às ondas do oceano a partir do local da garrafa, enfrentando a arrebentação fria até alcançar uma rocha solitária em alto-mar, onde seu baú marítimo reforçado com ferro aguarda."}},faq={{q="O que diz a pista final?",a="Apesar da tinta escorrida e do forte odor de uísque, a nota instrui o leitor a olhar para o oeste a partir da jarra de uísque, marchar diretamente para as águas costeiras e nadar para o oeste rumo ao mar até alcançar uma pequena ilha em alto-mar onde o baú do tesouro está escondido.",al={"texto da pista","o que está escrito na pista","instruções de sanders"}},{q="Onde esta pista foi encontrada?",a="A pista estava enfiada dentro de uma velha jarra de uísque localizada perto da costa oeste de Cerro Oeste, colocada ali como o terceiro passo na trilha de pistas espalhadas do Captain Sanders.",al={"onde encontro a pista final","localização da jarra velha","localização da pista"}},{q="Quem foi o Captain Sanders?",a="O Captain Sanders era um capitão do mar e pirata cujos pertences e mapas do tesouro foram parar na costa de Cerro Oeste. Embora o próprio Sanders tenha encontrado seu fim, ele deixou para trás uma sequência de notas e marcos escondidos pelo interior que levam ao seu tesouro pirata.",al={"quem é o captain sanders","história do pirata sanders","quem escondeu o tesouro"}},{q="Para onde esta pista leva afinal?",a="A nota instrui você a nadar para o oeste a partir da costa de Cerro Oeste até uma ilha solitária em alto-mar, onde o baú marítimo enferrujado do Captain Sanders repousa com seu saque enterrado.",al={"onde fica o baú","ilha de sanders","localização da ilha"}}},fx={ed69490f={q="O que é o Final Clue to Sanders' Treasure?",a="É um pedaço de papel desgastado, retirado da velha jarra de uísque do Capitão Sanders ao longo da costa de Cerro Oeste. Com um leve cheiro de bebidas alcoólicas e tinta borrada pela umidade, este bilhete marca o ponto culminante de uma caça ao tesouro deixada pelo falecido capitão pirata, oferecendo as últimas direções necessárias para descobrir seu tesouro enterrado.",al={"o que é o final clue to sanders treasure","identidade da pista final","o que é esta pista"}},["0f7c35ef"]={q="De onde vem o Final Clue to Sanders' Treasure e quem o fez?",a="A pista foi escrita pelo próprio Capitão Sanders e selada dentro de uma jarra velha ao lado do moinho de vento isolado nos penhascos marítimos de Cerro Oeste. O capitão pirata a escondeu como a última etapa de um rastro elaborado pela costa, garantindo que apenas alguém determinado o suficiente para seguir suas marcas espalhadas chegaria ao seu espólio escondido.",al={"quem fez a pista final","de onde veio a pista final","origem da pista final"}},["9095866c"]={q="Por que alguém quer o Final Clue to Sanders' Treasure?",a="Qualquer um que siga o rastro do Capitão Sanders busca seu espólio pirata perdido há muito tempo. Embora as pistas anteriores levassem de um ponto de referência da costa a outro, este bilhete final direciona explicitamente quem o encontra para além das praias de Cerro Oeste e para o mar aberto, diretamente para a ilha solitária onde o baú do capitão espera.",al={"por que querer a pista final","por que encontrar a pista final","propósito da pista final"}}},fp="31,150,24.332.0,29.113.0,26.121.0,24.197.0,37.107.0"}
P.entries["item:final-message-to-the-wildhammer"] = {n="Mensagem Final para os Martelo Feroz",s="A Mensagem Final para os Martelo Feroz é uma lança que Joho'sér Mujik'ka envia da Aldeia Revatusco ao Ninho da Águia. Sua exibição macabra pretende mostrar aos anões Martelo Feroz que os trolls estão falando sério.",h="A Mensagem Final para os Martelo Feroz é uma lança que Joho'sér Mujik'ka envia da Aldeia Revatusco ao Ninho...",kw={"ninho da águia","mensagem final","penas de grifo","joho'sér mujik'ka","aldeia revatusco","lança","poço","martelo feroz"},ang={["faction:Alliance"]="Para a Aliança, a lança é uma ameaça direta fincada no coração do Ninho da Águia, entre os anões Martelo Feroz.",["race:Troll"]="Como troll, você leva a ameaça de Joho'sér Mujik'ka até o Ninho da Águia, onde ele espera que os anões Martelo Feroz vejam a força da Aldeia Revatusco."},sec={{t="Uma lança para o Ninho da Águia",b="Na Aldeia Revatusco, nas Terras Agrestes, Joho'sér Mujik'ka entrega a você uma lança ensanguentada, envolta em penas de grifo. Ele quer que você a finque perto do poço no centro do Ninho da Águia, onde os anões Martelo Feroz vão vê-la. A mensagem é direta, e Joho'sér espera que você volte com vida."}},faq={{q="O que é a Mensagem Final para os Martelo Feroz?",a="É uma lança ensanguentada, envolta em penas de grifo, enviada por Joho'sér Mujik'ka ao Ninho da Águia.",al={"mensagem final","lança dos martelo feroz","mensagem de joho'sér"}},{q="Quem entrega a lança a você?",a="Joho'sér Mujik'ka entrega a lança a você na Aldeia Revatusco, nas Terras Agrestes.",al={"quem é joho'sér","quem entrega a lança","troll que entrega a lança"}},{q="Para onde vai a lança?",a="Joho'sér quer que você a finque perto do poço no centro do Ninho da Águia.",al={"onde fincar a lança","poço do ninho da águia","onde fica a mensagem"}},{q="Por que enviar uma lança ensanguentada?",a="Joho'sér quer que os anões Martelo Feroz vejam que os trolls estão falando sério.",al={"por que a lança","o que significa","trolls estão falando sério"}},{q="O que acontece quando você a coloca lá?",a="Falstad Martelo Feroz grita quando você coloca a lança, e você fica marcado para PvP.",al={"grito de falstad","colocar a mensagem","reação dos martelo feroz"}}},fp="31,193,22.278.0,44.93.0,24.73.0,24.67.0,24.71.0,31.78.0"}
P.entries["item:fine-crab-chunks"] = {n="Pedaços Delicados de Caranguejo",s="Pedaços Delicados de Caranguejo são cortes nobres de carne obtidos dos crustáceos costeiros que vagam pelas praias de Costa Negra. Altamente valorizados por sua versatilidade culinária, eles são procurados por habitantes locais da costa e pescadores famintos que desejam preparar uma infinidade de pratos de frutos do mar.",h="Pedaços Delicados de Caranguejo são cortes nobres de carne obtidos dos crustáceos costeiros que vagam pelas...",kw={"auberdine","caranguejo","costa negra","encrusted tide crawler","pedaços delicados de caranguejo","frutos do mar","gubber blump","reef crawler"},ang={["faction:Alliance"]="Abastecer os moradores do cais de Auberdine ajuda a sustentar o frágil posto avançado da Aliança em meio aos perigos sombrios de Costa Negra.",["profession:Cooking"]="Qualquer aspirante a chef do litoral apreciará a paixão enciclopédica de Gubber Blump por caranguejo, abrangendo sopas, saladas, temperos com pimenta e iguarias regionais como o caranguejo surpresa de Altaforja."},sec={{t="Frutos do mar",b="A costa enevoada e recortada de Costa Negra está repleta de crustáceos rastejantes, especificamente Reef Crawlers e Encrusted Tide Crawlers. Enquanto muitos viajantes veem essas criaturas encouraçadas da orla como pragas ou ameaças agressivas à beira da água, gastrônomos empreendedores consideram sua carne um dos melhores tesouros da costa. Os cortes nobres extraídos dessas criaturas rendem pedaços ricos e macios que se prestam a praticamente qualquer método de cozimento imaginável, desde fervura e grelha até fritura por imersão e ensopados saborosos."}},faq={{q="Quais criaturas fornecem Pedaços Delicados de Caranguejo?",a="Eles são obtidos de Reef Crawlers e Encrusted Tide Crawlers que vagam pelas praias rochosas e águas rasas de maré de Costa Negra.",al={"onde caem pedaços delicados de caranguejo","quais caranguejos dropam pedaços","fonte de carne de caranguejo"}},{q="Quem quer Pedaços Delicados de Caranguejo em Costa Negra?",a="Gubber Blump, um pescador entusiasmado que fica nas docas de Auberdine, procura por esses cortes nobres. Um ávido amante de frutos do mar, ele os valoriza para um elaborado repertório de pratos caseiros de caranguejo.",al={"quem precisa de pedaços delicados de caranguejo","quem entrega pedaços de caranguejo","caranguejo de gubber blump"}},{q="Você pode preparar isso em refeições de verdade?",a="Embora esses pedaços crus específicos sirvam principalmente como um suprimento coletado para Gubber Blump, e não como ingrediente direto de receitas de criação, a tradição culinária local trata a carne de caranguejo como extremamente versátil — adequada para assar, fazer churrasco, ferver, grelhar, fritar e misturar em saladas ou ensopados.",al={"dá para cozinhar pedaços delicados de caranguejo","o que fazer com pedaços delicados de caranguejo","receitas de caranguejo"}}},fx={a1097ca6={q="O que são Pedaços Delicados de Caranguejo?",a="Pedaços Delicados de Caranguejo são cortes nobres de carne extraídos dos caranguejos robustos ao longo da costa enevoada de Costa Negra. Valorizados por sua maciez e versatilidade, são considerados pelos entusiastas locais como o verdadeiro fruto do mar, adequados para quase qualquer preparo imaginável.",al={"o que são pedaços delicados de caranguejo","conhecimento sobre pedaços delicados de caranguejo","o que é carne de caranguejo fina"}},["09afcf23"]={q="De onde vêm os Pedaços Delicados de Caranguejo?",a="Esses bocados seletos são colhidos diretamente dos crustáceos selvagens que rondam a costa de Costa Negra, particularmente os Rastejadores de Recife e Rastejadores das Marés Incrustados. Eles não são criados por mãos mortais, mas cortados frescos das criaturas que prosperam na arrebentação fria.",al={"de onde vêm os pedaços delicados de caranguejo","fonte dos pedaços delicados de caranguejo","origem dos pedaços delicados de caranguejo"}},["1943045a"]={q="Por que Gubber Blump quer Pedaços Delicados de Caranguejo?",a="Gubber Blump, um pescador excêntrico estacionado nos cais de Auberdine, é totalmente obcecado por carne de caranguejo. Preso com sua vara de pescar, ele depende de viajantes para coletar pedaços frescos para que possa preparar uma variedade infinita de receitas à base de caranguejo, desde pratos assados e grelhados até saladas de caranguejo e ensopados.",al={"por que gubber quer pedaços de caranguejo","quem quer pedaços delicados de caranguejo","por que coletar pedaços delicados de caranguejo"}}},fp="16,131,16.217.0,38.116.0,40.91.0,40.174.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="Pelagem de Espreitaluna Fina",s="Uma Pelagem de Espreitaluna Fina é a pele espessa e imaculada retirada dos predadores espreitalunas mais maduros que vagam pelo sul de Costa Negra. Terenthis de Auberdine usa essas peles valiosas para tecer um manto encantado que permite aos que realizam buscas passar despercebidos pelas feras hostis dos bosques.",h="Uma Pelagem de Espreitaluna Fina é a pele espessa e imaculada retirada dos predadores espreitalunas mais...",kw={"auberdine","costa negra","pelagem de espreitaluna fina","matriarca","espreitaluna","reprodutor","terenthis","volcor","rio crenado"},ang={["class:Hunter"]="Perseguir os reprodutores e as matriarcas perto do Rio Crenado testa as habilidades de rastreamento de um caçador contra alguns dos predadores mais ferozes do litoral de Kalimdor.",["race:NightElf"]="Os elfos noturnos respeitam a ferocidade sagrada dos espreitalunas, tirando suas peles apenas por extrema necessidade para ajudar parentes caídos como Volcor."},sec={{t="Peles dos Líderes da Matilha",b="Enquanto espreitalunas comuns rondam pelas florestas cobertas de névoa de Costa Negra, apenas os reprodutores e as matriarcas espreitalunas mais velhos possuem pelagens densas e saudáveis o bastante para render uma pele fina. Esses poderosos felinos selvagens estabelecem territórios ao longo do Rio Crenado e mais ao sul, em direção às fronteiras de Vale Gris, onde caçam com paciência letal."},{t="Um Manto de Enganação",b="Juntar essas peles não é uma mera caça a troféus. Terenthis pede cinco pelagens intactas para confeccionar uma vestimenta encantada para viajantes em busca do elfo noturno desaparecido Volcor. Quando tecidas e vinculadas com magia da natureza, as pelagens formam um manto de ocultamento que envolve seu usuário em uma ilusão, atenuando sua presença para a vida selvagem de Costa Negra desde que ele evite ações agressivas."}},faq={{q="Quais criaturas concedem uma Pelagem de Espreitaluna Fina?",a="Apenas os líderes maduros das matilhas de espreitalunas concedem essas pelagens — especificamente reprodutores espreitalunas e matriarcas espreitalunas. Espreitalunas mais jovens ou comuns não possuem a qualidade de pele necessária.",al={"o que saqueia pelagem de espreitaluna fina","onde conseguir pelagem de espreitaluna","quais felinos têm pelagens"}},{q="Onde os espreitalunas maduros podem ser encontrados?",a="Esses formidáveis felinos selvagens habitam o sul de Costa Negra, principalmente perto das margens do Rio Crenado e mais ao sul ao longo da estrada da floresta em direção a Vale Gris.",al={"onde estão os reprodutores e matriarcas","localização do reprodutor espreitaluna","localização da matriarca espreitaluna"}},{q="Por que Terenthis precisa dessas pelagens?",a="Terenthis usa cinco das pelagens para criar um manto encantado. Esse manto é imbuído de magia projetada para ocultar um socorrista das feras predadoras enquanto procura pelo elfo noturno desaparecido Volcor.",al={"para que servem as pelagens","por que coletar pelagens de espreitaluna","missão de pelagem de terenthis"}},{q="O manto finalizado torna você completamente invisível?",a="O manto projeta uma delicada ilusão natural que afasta feras, mas ela é frágil. Terenthis adverte que fazer muito além de falar com outros perturbará o encantamento e dissipará o disfarce.",al={"como o manto funciona","limites da ilusão do manto","manto quebra furtividade"}}},fx={["399f6830"]={q="O que é uma Pelagem de Espreitaluna Fina?",a="Uma Pelagem de Espreitaluna Fina é a pele nobre colhida dos pais e matriarcas espreitaluna maduros que vagam pelas áreas selvagens de Costa Negra. Esses formidáveis gatos noturnos possuem pelos espessos e flexíveis, capazes de reter encantamentos naturais delicados, tornando suas pelagens muito mais valorizadas e duráveis do que o pelo de espécimes mais jovens.",al={"pelagem de espreitaluna fina","o que é a pelagem de espreitaluna","pelagem fina"}},e53e751f={q="De onde vem uma Pelagem de Espreitaluna Fina?",a="Essas pelagens vêm naturalmente dos maiores espreitaluna adultos que rondam as costas e florestas de Costa Negra, particularmente perto do Rio Crenado e mais ao sul em direção à fronteira de Vale Gris. Apenas pais e matriarcas espreitaluna totalmente crescidos produzem peles espessas e saudáveis o suficiente para serem consideradas pelagens finas.",al={"onde conseguir pelagem de espreitaluna fina","fonte da pelagem de espreitaluna","quem deixa cair pelagem de espreitaluna fina"}}},fp="21,164,25.300.0,20.277.1,45.128.0,43.119.0,36.164.0,54.174.0"}
P.entries["item:fire-tar"] = {n="Piche Ígneo",s="O Piche Ígneo é uma substância volátil coletada por conjuradores quiljavali do tipo Razormane por todos os Sertões orientais. Para os xamãs da Horda, ele serve como um componente ritual crucial usado para preparar a Sapta do Fogo, que concede comunhão espiritual com o elemento do fogo.",h="O Piche Ígneo é uma substância volátil coletada por conjuradores quiljavali do tipo Razormane por todos os...",kw={"call of fire","sapta do fogo","piche ígneo","quiljavali","razormane","totem xamânico","telf joolam","sertões"},ang={["class:Shaman"]="Coletar Piche Ígneo marca um rito de passagem essencial, ensinando você a buscar ressonância elemental no mundo para preparar a Sapta do Fogo e conquistar seu Totem do Fogo.",["faction:Horde"]="Adquirir Piche Ígneo leva jovens aventureiros da Horda para fora de Durotar e através do Rio Furiaustral em direção aos Sertões, confrontando as agressivas tribos Razormane."},sec={{t="Uma Concoção dos Razormane",b="Carregado quase exclusivamente por quiljavalis Razormane conjuradores — incluindo seus geomantes, místicos e tecelões de espinhos — o Piche Ígneo é uma substância alquímica sintonizada com as chamas. Embora as tribos eriçadas dos Sertões a usem para sua própria magia e rituais rudes, instrutores xamânicos a reconhecem como um reagente mundano essencial capaz de preencher a lacuna entre os sentidos mortais e a fúria elemental bruta."},{t="O Caminho para o Totem do Fogo",b="Quando jovens xamãs orcs e trolls são enviados a Telf Joolam, empoleirado no alto dos penhascos de Durotar, eles recebem a tarefa de forjar seu Totem do Fogo. Telf precisa de dois elementos-chave ligados ao calor e às chamas para preparar uma Sapta do Fogo: um Bornal de Reagentes roubado de cultistas da Lâmina Ardente e Piche Ígneo colhido dos Razormane. Beber a mistura resultante permite que o xamã atravesse o véu e perceba os espíritos elementais do fogo esperando por eles no topo dos picos próximos."}},faq={{q="Para que o Piche Ígneo é usado?",a="O Piche Ígneo é um ingrediente ritual necessário levado ao xamã eremita Telf Joolam em Durotar. Combinado com reagentes da Lâmina Ardente, ele é preparado na Sapta do Fogo — uma poção que permite que um xamã veja e comungue com espíritos do fogo para conquistar seu Totem do Fogo.",al={"uso do piche ígneo","o que o piche ígneo faz","por que preciso de piche ígneo"}},{q="Quem carrega Piche Ígneo?",a="Ele é carregado por quiljavalis conjuradores da tribo Razormane nos Sertões orientais, como Geomantes, Místicos, Tecelões de Espinhos e Buscadores de Água Razormane.",al={"quem deixa cair piche ígneo","criaturas com piche ígneo","onde conseguir piche ígneo"}},{q="Por que os xamãs precisam de ingredientes ligados a conjuradores hostis?",a="As Saptas requerem componentes físicos profundamente saturados com o elemento correspondente. Como tanto os conjuradores Razormane quanto os bruxos da Lâmina Ardente canalizam calor intenso e chamas destrutivas, seus materiais do cotidiano já estão embebidos na essência ígnea necessária para despertar a visão elemental de um xamã.",al={"por que piche de quiljavali","por que bruxos e quiljavalis"}},{q="Onde Telf Joolam prepara a Sapta do Fogo?",a="Telf Joolam reside em um penhasco alto com vista para os rochedos de Durotar, perto do caminho entre Monte Navalha e os Sertões. Lá, ele instrui iniciantes sobre como equilibrar a natureza destrutiva e criativa das chamas.",al={"onde está telf joolam","entregar piche ígneo"}}},fx={["1e4fc5f4"]={q="O que é Piche Ígneo?",a="Piche Ígneo é uma substância volátil e elemental carregada por conjuradores entre os quilboars Presa-cerda nos Sertões. Impregnado com a essência fundamental do fogo, este piche pungente é valorizado por praticantes de magia elemental por sua afinidade natural com as chamas.",al={"o que é piche ígneo","informações sobre piche ígneo","descreva piche ígneo"}},["006bd002"]={q="De onde vem o Piche Ígneo e quem o faz?",a="O Piche Ígneo é coletado dos conjuradores quilboars Presa-cerda que habitam os Sertões orientais, incluindo seus geomantes, místicos e tecelões de espinhos. Telf Joolam pede aos iniciados que o tragam como um componente para sua sapta do fogo.",al={"quem faz piche ígneo","origem do piche ígneo","de onde vem o piche ígneo"}}},fp="8,178,29.274.0,26.361.0,26.196.0,21.147.0,61.243.0,43.215.0"}
P.entries["item:firebeard-s-head"] = {n="Firebeard's Head",s="Firebeard’s Head é a prova exigida pelo mandado de Andre Firebeard no Porto de Bondebico. A lei do porto permite que a cabeça dele o represente no julgamento.",h="Firebeard’s Head é a prova exigida pelo mandado de Andre Firebeard no Porto de Bondebico.",kw={"andre firebeard","cabeça de firebeard","geringontzan","pirata","chefe de segurança silvadágua","porto de bondebico","tanaris","procurado"},sec={{t="Um Mandado Vinculante",b="Chefe de Segurança Silvadágua aceita a cabeça de Andre Firebeard como representante dele na audiência. O mandado acusa o pirata de crimes contra Steamwheedle e Geringontzan. Quando você leva a cabeça ao porto, Silvadágua considera o contrato cumprido e oferece pagamento pelo seu serviço."}},faq={{q="Por que o mandado pede a cabeça dele?",a="O mandado diz que a cabeça de Andre Firebeard pode representá-lo se ele estiver morto ou não puder comparecer à audiência. Chefe de Segurança Silvadágua a aceita no Porto de Bondebico.",al={"mandado pela cabeça de andre","por que a cabeça dele","cabeça de firebeard"}},{q="Quem é Andre Firebeard?",a="Andre Firebeard é um pirata procurado por crimes contra Steamwheedle e Geringontzan.",al={"andre firebeard","pirata firebeard","quem é andre"}},{q="Quem fica com Firebeard’s Head?",a="Chefe de Segurança Silvadágua fica com a cabeça de Andre Firebeard no Porto de Bondebico.",al={"quem quer a cabeça","cabeça de silvadágua","onde levar a cabeça de andre"}},{q="Onde fica o Porto de Bondebico?",a="O Porto de Bondebico fica na costa de Tanaris. O mandado de Andre Firebeard está afixado lá.",al={"localização de steamwheedle","porto de tanaris","onde fica o porto"}}},fp="16,157,17.284.0,38.172.0,23.81.0,29.80.0,27.92.0"}
P.entries["item:fizzle-s-claw"] = {n="Garra do Bulho",s="A Garra do Bulho é a mão decepada do bruxo goblin Fizzle Darkstorm. Tirada de seu acampamento no Desfiladeiro do Trovão, ela serve como prova física para os comandantes da Horda em Monte Navalha de que um perigoso conspirador da Lâmina Ardente foi morto.",h="A Garra do Bulho é a mão decepada do bruxo goblin Fizzle Darkstorm.",kw={"lâmina ardente","dark storms","durotar","fizzle darkstorm","garra do bulho","orgnil chaganalma","monte navalha","desfiladeiro do trovão"},ang={["class:Warlock"]="Fizzle Darkstorm usou artes vis para servir à subversiva Lâmina Ardente, voltando seus talentos sombrios para a rebelião direta contra a Horda.",["faction:Horde"]="Apresentar a garra do Bulho a Monte Navalha demonstra um compromisso contínuo em purificar Durotar das seitas sombrias que ameaçam a frágil segurança da jovem nação."},sec={{t="Um Troféu Sombrio",b="Orgnil Chaganalma, encarregado de erradicar seitas sombrias que ameaçavam a terra natal dos orcs, identificou Fizzle Darkstorm como um instigador espalhando corrupção no Desfiladeiro do Trovão. A exigência pela garra do Bulho não era mero selvagerismo, mas uma necessidade prática: a Horda exige provas irrefutáveis quando um bruxo secreto que opera sob o estandarte da Lâmina Ardente é eliminado."},{t="A Ameaça no Desfiladeiro do Trovão",b="O Desfiladeiro do Trovão fica logo a noroeste de Monte Navalha, tornando a presença cultista de Bulho um perigo iminente para os territórios vizinhos. Ao decepar a garra do goblin e levá-la de volta a Monte Navalha, os batedores da Horda confirmaram que os rituais do bruxo e suas tentativas de estabelecer uma base para a Lâmina Ardente haviam sido frustrados."}},faq={{q="A quem pertence esta garra?",a="A garra pertencia a Fizzle Darkstorm, um traiçoeiro bruxo goblin afiliado à seita sombria conhecida como a Lâmina Ardente.",al={"quem é bulho","fizzle darkstorm","dono da garra"}},{q="Por que Orgnil Chaganalma quer a Garra do Bulho?",a="Orgnil Chaganalma precisa de uma prova definitiva da morte de Bulho. A Lâmina Ardente opera a partir das sombras, portanto apresentar a garra do bruxo goblin confirma que essa ameaça específica a Durotar foi expurgada permanentemente.",al={"por que precisa da garra","garra orgnil chaganalma","prova de morte"}},{q="Onde a garra foi encontrada?",a="Ela é tirada de Fizzle Darkstorm em seu acampamento escondido no Desfiladeiro do Trovão, um cânion localizado a noroeste de Monte Navalha em Durotar.",al={"localização de bulho","onde fica bulho","garra desfiladeiro do trovão"}},{q="O que a Lâmina Ardente está fazendo em Durotar?",a="A Lâmina Ardente é uma seita sinistra que busca minar a nova terra natal dos orcs por meio de corrupção demoníaca, feitiçaria sombria e agitação civil. Bruxos como Bulho estabelecem acampamentos ocultos para espalhar o caos pela região.",al={"lâmina ardente durotar","por que há cultistas no desfiladeiro do trovão"}}},fx={["0fb0af8e"]={q="O que é a Garra do Bulho?",a="A Garra do Bulho é a mão decepada de Fizzle Tempestade Sombria, um bruxo goblin traiçoeiro alinhado ao culto da Lâmina Ardente. Ela serve como prova física macabra de sua morte para Orgnil Chaganalma em Monte Navalha, confirmando que o líder do culto que causava problemas no Desfiladeiro do Trovão foi eliminado permanentemente.",al={"o que é a garra do bulho","item garra do bulho","identidade da garra do bulho"}}},fp="13,177,13.277.0,27.251.0,29.90.0,44.151.0,25.101.0,43.199.0"}
P.entries["item:flagongut-s-fossil"] = {n="Fóssil do Pançacheia",s="O Fóssil do Pançacheia é um espécime antigo recuperado dos sítios de escavação do Pantanal. Confiado à Liga dos Exploradores dos anões, ele guarda segredos latentes que o Arqueólogo Pançacheia busca decifrar usando uma relíquia misteriosa conhecida como Pedra de Relu.",h="O Fóssil do Pançacheia é um espécime antigo recuperado dos sítios de escavação do Pantanal.",kw={"escavação","explorers' league","pançacheia","fóssil","relu","pedra de relu","pantanal","whelgar"},ang={["faction:Alliance"]="Proteger os artefatos do sítio de escavação arruinado de Whelgar impede que a valiosa história seja destruída por feras selvagens ou saqueada por forças hostis no pântano.",["race:Dwarf"]="Para os exploradores anões, fósseis como o de Pançacheia não são meras curiosidades; eles são elos físicos com o passado antigo que a Liga dos Exploradores se dedica a desenterrar."},sec={{t="Escavação e Estudo",b="Desenterrado como parte das expedições dos anões por Khaz Modan, este antigo fóssil representa mais do que apenas pedra petrificada. O Arqueólogo Pançacheia acredita que ele guarda poderes esquecidos ligados à profunda antiguidade do mundo, comparáveis a artefatos encontrados do outro lado do mar, em Costa Negra. Para mantê-lo seguro durante os estudos regionais, o fóssil foi guardado pelo Prospector Whelgar em seu sítio de escavação nas colinas do sul do Pantanal."},{t="Despertando a Relíquia",b="Quando Pançacheia descobriu a Pedra de Relu, ele percebeu que ela era a chave de decifração necessária para desvendar os mistérios do fóssil. No entanto, uma emboscada de raptores malhados na estrada fez com que a pedra fosse perdida. Para finalmente liberar o espécime, Pançacheia precisa que aventureiros recuperem o fóssil da escavação de Whelgar e resgatem a pedra engolida da fauna do Pantanal."}},faq={{q="O que é o Fóssil do Pançacheia?",a="É um antigo espécime arqueológico recuperado do Pantanal, mantido para análise pela Liga dos Exploradores dos anões a fim de revelar segredos do passado remoto do mundo.",al={"o que é o fóssil","história do fóssil do pançacheia"}},{q="Onde o fóssil está localizado?",a="Ele está localizado na caverna no topo do Sítio de Escavação de Whelgar, aninhado nas montanhas do sul do Pantanal, guardado pelos raptores malhados que invadiram a escavação.",al={"localização do fóssil","onde fica o fóssil do pançacheia","caverna do fóssil de whelgar"}},{q="Por que Pançacheia precisa que ele seja devolvido?",a="Pançacheia acredita que, em conjunto com a Pedra de Relu, ele pode decifrar os segredos mágicos latentes do fóssil e comparar sua natureza com descobertas semelhantes feitas em Kalimdor.",al={"por que pançacheia quer o fóssil","o que pançacheia fará com ele"}},{q="Como ele está conectado a Costa Negra?",a="Pançacheia vê um paralelo entre este espécime do Pantanal e o fóssil encontrado pelo Prospector Trilheiro do outro lado do mar, em Costa Negra, acreditando que a Pedra de Relu possa despertar o poder em ambas as relíquias.",al={"conexão com costa negra","fóssil do trilheiro"}}},fp="18,180,20.293.0,19.257.1,27.144.0,28.155.0,36.158.0,33.180.0"}
P.entries["item:flatland-cougar-femur"] = {n="Fêmur de Puma das Estepes",s="Um Fêmur de Puma das Estepes é um osso denso da coxa retirado dos pumas predadores que rondam as relvas douradas de Mulgore. Ele serve como um componente vital em um remédio popular tradicional dos taurens, usado para combater infecções letais e venenosas.",h="Um Fêmur de Puma das Estepes é um osso denso da coxa retirado dos pumas predadores que rondam as relvas...",kw={"aldeia casco sangrento","fêmur","puma das estepes","maur clamachuva","mazzranache","mulgore"},ang={["class:Hunter"]="Rastrear pumas das estepes exige olhos atentos através da vegetação oscilante de Mulgore, testando a habilidade de um jovem caçador de abater com precisão outro predador.",["race:Tauren"]="Para os taurens de Mulgore, caçar o puma das estepes é tanto uma prova de vigilância quanto uma fonte de materiais vitais usados em remédios tradicionais das planícies."},sec={{t="Um Remédio para uma Mordida Venenosa",b="O puma das estepes é um dos predadores nativos mais perigosos de Mulgore, camuflando-se perfeitamente na vegetação seca até saltar sobre presas desavisadas. Embora caçadores frequentemente coletem peles e garras de puma para couparia e troféus, seus ossos pesados e ricos em medula possuem valor prático na medicina regional. Quando Maur Clamachuva, um tauren da Aldeia Casco Sangrento, sofreu um ferimento venenoso causado pelo monstruoso strider rosa Mazzranache, ele solicitou com urgência um fêmur de puma juntamente com partes de outras feras locais. O osso é triturado ou fervido para extrair suas propriedades potentes, formando um cataplasma antitoxina capaz de extrair a febre e o veneno necrótico de uma mordida infeccionada."}},faq={{q="Para que é usado o Fêmur de Puma das Estepes?",a="O fêmur é usado por Maur Clamachuva na Aldeia Casco Sangrento para preparar um remédio de emergência. Maur foi mordido pelo famoso plainstrider Mazzranache e precisa da medula e do osso para preparar uma antitoxina antes que o veneno virulento da criatura o mate.",al={"uso do fêmur de puma","para que serve este osso","missão do fêmur"}},{q="Onde você obtém um Fêmur de Puma das Estepes?",a="Ele é obtido de pumas das estepes que vagam pelas planícies centrais e do sul de Mulgore, normalmente encontrados rondando perto das encostas e percorrendo a relva alta ao redor da Aldeia Casco Sangrento.",al={"onde encontrar o fêmur","localização do fêmur de puma","quais criaturas dropam"}},{q="Por que Maur Clamachuva precisaria especificamente de um osso de puma?",a="Herboristas e xamãs taurens utilizam com frequência os ossos densos e a medula de animais predadores em bálsamos e tinturas tradicionais. Acredita-se que a força e a resiliência dos predadores alfa de Mulgore forneçam a base restauradora necessária para neutralizar toxinas potentes.",al={"por que osso de puma","por que o fêmur"}},{q="Quem é Maur Clamachuva?",a="Maur Clamachuva é um tauren residente da Aldeia Casco Sangrento. Depois de vagar pelas planícies, ele se deparou com Mazzranache, um strider lendário que seu avô enfrentou outrora, e mal conseguiu escapar com uma mordida infeccionada e venenosa no ombro.",al={"maur clamachuva","quem precisa do osso"}}},fx={cc87b9fc={q="O que é um Fêmur de Puma das Estepes?",a="É um osso da perna robusto colhido dos pumas das estepes predatórios que vagam pelas planícies de Mulgore. Densos e resilientes, ossos como esses são frequentemente procurados por curandeiros e xamãs tribais para preparar pomadas tradicionais, cataplasmas e remédios medicinais.",al={"o que é fêmur de puma das estepes","item fêmur de puma das estepes","o que é o fêmur de puma"}},["47eeaceb"]={q="De onde vem um Fêmur de Puma das Estepes?",a="É obtido diretamente de pumas das estepes, os predadores ágeis nativos das pastagens de Mulgore. Diferente de ferramentas criadas ou poções preparadas, este é um troféu natural cru coletado por caçadores que rastreiam as feras selvagens pelos Morros Ondulantes.",al={"origem do fêmur de puma das estepes","onde conseguir fêmur de puma das estepes","quem deixa cair fêmur de puma"}}},fp="21,172,28.545.0,43.216.0,44.178.0,58.226.0,23.224.0"}
P.entries["item:flatland-prowler-claw"] = {n="Garra de Predador das Estepes",s="Uma Garra de Predador das Estepes é obtida dos perigosos predadores felinos que espreitam as planícies verdejantes de Mulgore. Para os aspirantes a caçadores, recolher essas garras serve como um rito de passagem tradicional, demonstrando astúcia e determinação marcial aos anciãos de Penhasco do Trovão.",h="Uma Garra de Predador das Estepes é obtida dos perigosos predadores felinos que espreitam as planícies...",kw={"predador das estepes","garra de predador das estepes","platô dos caçadores","melor casco de pedra","mulgore","skorn nuvem branca","a senda do caçador","penhasco do trovão"},ang={["class:Hunter"]="Derrubar predadores furtivos testa a percepção de campo de um caçador, tornando essas garras um símbolo de respeito conquistado entre os atiradores reunidos no Platô dos Caçadores de Penhasco do Trovão.",["race:Tauren"]="Para os taurens, a caçada é uma tradição espiritual honrada, e apresentar as garras de um astuto predador das planícies marca os primeiros passos de um iniciado para servir a tribo como rastreador."},sec={{t="A Prova do Caçador",b="Os predadores das estepes estão entre os carnívoros mais astutos e territoriais que percorrem as planícies varridas pelo vento de Mulgore. Velozes e peritos em emboscar presas na relva alta, eles representam uma ameaça real aos viajantes e um teste digno para jovens caçadores. Coletar suas garras afiadas não é apenas uma tarefa de sobrevivência, mas uma tradição reconhecida. Skorn Nuvem Branca aconselha andarilhos promissores a colher esses troféus para apresentá-los a Melor Casco de Pedra no alto do Platô dos Caçadores de Penhasco do Trovão, provando que possuem a determinação e a habilidade de campo necessárias para seguir A senda do caçador."}},faq={{q="Para que servem as Garras de Predador das Estepes?",a="Elas servem como uma demonstração física de perícia e coragem. Jovens caçadores levam quatro dessas garras a Melor Casco de Pedra no Platô dos Caçadores em Penhasco do Trovão para provar que estão prontos para trilhar O caminho do caçador.",al={"uso da garra de predador","por que pegar garras de predador","garras a senda do caçador"}},{q="Quem pede para você coletá-las?",a="O experiente caçador Skorn Nuvem Branca orienta rastreadores promissores a coletar garras dos predadores de Mulgore como prova antes de se apresentarem a Melor Casco de Pedra.",al={"quem quer garras de predador","doador da missao garras de predador"}},{q="Por que os predadores das estepes são considerados uma caça adequada?",a="Os predadores das estepes são carnívoros resistentes, furtivos e astutos, nativos das planícies de Mulgore. Rastrear e derrotar com sucesso predadores tão alertas prova que o aspirante a caçador possui a paciência e os instintos de combate exigidos pela tradição dos taurens.",al={"por que predadores das estepes","predadores sao perigosos"}}},fx={cc11ac90={q="O que é uma Garra de Predador das Estepes?",a="É uma garra colhida de um predador das estepes, um dos gatos selvagens predatórios que vagam pelas planícies gramadas de Mulgore. Entre os caçadores tauren, apresentar essas garras serve como prova tangível da astúcia, paciência e proeza de rastreamento emergente de um jovem caçador.",al={"garra de predador das estepes","o que é garra de predador"}},a7640831={q="De onde vêm as Garras de Predador das Estepes?",a="Essas garras vêm diretamente dos predadores das estepes selvagens que espreitam as pastagens varridas pelo vento de Mulgore. Em vez de serem criadas ou fabricadas, elas devem ser colhidas limpas por um caçador após rastrear e derrotar as feras ágeis na natureza.",al={"onde conseguir garras de predador","como as garras de predador são obtidas"}},b4c8d82b={q="Por que alguém quer Garras de Predador das Estepes?",a="Skorn Nuvem Branca orienta aspirantes a viajantes a coletar essas garras para provar seu valor a Melor Casco de Pedra no topo da Elevação do Caçador em Penhasco do Trovão. A caça é uma das honras mais altas na cultura tauren, e oferecer as garras de predadores tão resistentes e astutos demonstra que você possui a habilidade e o espírito em desenvolvimento necessários para trilhar o caminho do caçador.",al={"por que coletar garras de predador","quem precisa de garras de predador","por que melor casco de pedra quer garras"}}},fp="21,138,16.457.0,41.189.0,29.129.0,52.196.0"}
P.entries["item:foreman-s-blackjack"] = {n="Cassetete do Encarregado",s="O Cassetete do Encarregado é uma clava pesada envolta em couro, emprestada a novos recrutas da Horda no Vale das Provações. Feitores a entregam como uma ferramenta disciplinar cotidiana para acordar peões adormecidos e impor o ritmo extenuante do início da construção de Durotar.",h="O Cassetete do Encarregado é uma clava pesada envolta em couro, emprestada a novos recrutas da Horda no Vale...",kw={"cassetete","durotar","cassetete do encarregado","peões preguiçosos","peao","thazzril","vale das provações"},ang={["faction:Horde"]="O cassetete destaca o esforço prático e implacável necessário para domar Durotar, onde colonizar uma terra inóspita exige que cada trabalhador atue sem parar.",["race:Orc"]="Para jovens orcs que entram no Vale das Provações, empunhar o cassetete oferece uma lição precoce sobre a hierarquia da Horda: aqueles sem a força ou o espírito de um guerreiro são relegados ao trabalho braçal e mantidos na linha pela força."},sec={{t="Uma Ferramenta do Trabalho Órquico",b="Construir um novo lar no deserto acidentado de Durotar exige estoques imensos de madeira, e o trabalho recai diretamente sobre os ombros dos peões da Horda. No Vale das Provações, o Encarregado Thazz'ril depende do Cassetete do Encarregado para manter as equipes de trabalho em movimento. Em vez de desferir golpes letais, este porrete pesado foi feito para dar um despertar impactante aos trabalhadores flagrados cochilando sob a sombra das árvores do vale. Ele serve como um lembrete severo da vida de peão na nova Horda: extenuante, sem glamour e supervisionada com mão de ferro."}},faq={{q="Para que serve o Cassetete do Encarregado?",a="Os feitores entregam o cassetete a jovens aventureiros para disciplinar peões adormecidos por todo o Vale das Provações. Golpear um peão que está tirando uma soneca faz com que ele acorde sobressaltado e volte imediatamente a cortar e carregar madeira.",al={"uso do cassetete","por que usar cassetete","porrete de peao"}},{q="A quem pertence este cassetete?",a="Ele pertence ao Encarregado Thazz'ril, o feitor de trabalho posicionado no Vale das Provações que supervisiona a coleta de madeira bruta para o jovem assentamento órquico.",al={"quem da o cassetete","dono do cassetete do encarregado"}},{q="Por que os peões continuam dormindo no trabalho?",a="Os peões orcs trabalham em turnos implacáveis e exaustivos colhendo madeira sob o sol inclemente de Durotar. Sempre que encontram sombra sob as árvores esparsas do vale, a exaustão os domina, levando a frequentes cochilos não autorizados.",al={"por que os peoes sao preguicosos","peoes preguicosos dormindo"}},{q="Posso ficar com o cassetete depois de terminar a tarefa?",a="Não. O feitor exige que a ferramenta seja devolvida imediatamente assim que os preguiçosos forem disciplinados, garantindo que ela permaneça à mão para que futuros feitores possam cumprir as cotas de trabalho.",al={"ficar com cassetete","posso ficar com o cassetete do encarregado"}}},fx={["4e7ef009"]={q="O que é o Cassetete do Encarregado?",a="O Cassetete do Encarregado é um bastão pesado envolto em couro carregado pelo Encarregado Thazz'ril no Vale das Provações. É uma ferramenta de disciplina nada glamorosa, projetada não para infligir ferimentos graves na guerra, mas para desferir um golpe agudo e doloroso que faz os trabalhadores adormecidos voltarem a ficar de pé.",al={"o que é o cassetete","item cassetete do encarregado","o que é o cassetete do encarregado"}},["9e33a4a7"]={q="Por que o Encarregado Thazz'ril quer o cassetete de volta?",a="O Encarregado Thazz'ril depende do cassetete para comandar suas equipes de trabalho no Vale das Provações. Sem ele, ele tem pouco poder para forçar os peões exaustos e desmotivados a continuar cortando e carregando madeira para a Horda. Assim que você tiver ajudado a colocar os trabalhadores de volta às suas funções, ele espera que sua ferramenta essencial seja devolvida.",al={"por que devolver o cassetete","por que thazzril precisa do cassetete","por que querer o cassetete"}}},fp="19,184,22.379.0,41.186.0,24.173.0,48.178.0,50.137.0"}
P.entries["item:forged-steel-bars"] = {n="Barras de Aço Forjado",s="Barras de Aço Forjado são lingotes de metal refinado pertencentes ao ferreiro orc Thun'grim Olhafogo. Roubadas por javatuscos Razormane oportunistas durante um ataque noturno, elas servem como prova da determinação de um guerreiro em recuperar bens roubados nos Sertões.",h="Barras de Aço Forjado são lingotes de metal refinado pertencentes ao ferreiro orc Thun'grim Olhafogo.",kw={"sertões","aço forjado","barras de aço forjado","baú de ferro","razormane","baú de ferro roubado","thun'grim olhafogo"},ang={["class:Warrior"]="Recuperar o aço roubado de Thun'grim comprova a habilidade de um guerreiro em rastrear ladrões e enfrentar perigosos bandos de javatuscos em troca de armamentos personalizados.",["profession:Blacksmithing"]="As barras refinadas evidenciam o contraste entre a sucata tribal rudimentar e o aço de qualidade forjado por ferreiros treinados da Horda."},sec={{t="Metal Roubado",b="Barras de Aço Forjado representam material de ferraria de alta qualidade pertencente ao ferreiro orc com deficiência visual Thun'grim Olhafogo, que mantém um acampamento no norte dos Sertões. Aproveitando-se da visão fraca de Thun'grim, os javatuscos Razormane locais distraíram o ferreiro com grunhidos e bufos enquanto ladrões escapavam com um baú de ferro contendo os lingotes. Sem habilidades na forja de aço fino, os javatuscos abandonaram o recipiente fechado perto de uma carroça em ruínas em seu acampamento a noroeste, deixando as barras intactas para guerreiros resgatarem."}},faq={{q="Quem é o dono destas barras de aço forjado?",a="Elas pertencem a Thun'grim Olhafogo, um armeiro e forjador de armas orc que vive em um acampamento no norte dos Sertões.",al={"quem é o dono das barras","aço de thungrim","de quem é este aço"}},{q="Por que os javatuscos as roubaram?",a="Os javatuscos Razormane atacaram o acampamento de Thun'grim simplesmente para saquear seus objetos de valor. Sabendo que o ferreiro sofria de problemas de visão, eles o provocaram e distraíram enquanto outros membros da tribo fugiam com seu baú de ferro.",al={"por que roubar aço","motivo dos javatuscos","roubo dos razormane"}},{q="Os javatuscos usaram o aço?",a="Não. Como Thun'grim esperava, os Razormanes não tinham o conhecimento metalúrgico nem a habilidade para trabalhar um aço tão finamente refinado. O baú permaneceu fechado e abandonado ao lado de uma carroça quebrada em seu acampamento.",al={"os javatuscos forjaram algo","o que os javatuscos fizeram com o aço"}},{q="O que Thun'grim oferecerá em troca delas?",a="Em troca de enfrentar os acampamentos dos javatuscos e devolver todas as barras, Thun'grim recompensa aspirantes a guerreiro com uma arma forjada.",al={"recompensa de aço forjado","o que eu ganho pelo aço"}}},fx={["4e666297"]={q="O que são as Barras de Aço Forjado?",a="Estas barras são um estoque de metal refinado de alta qualidade pertencente ao ferreiro Thun'grim Firegaze. Mantidas trancadas em um baú de ferro em seu acampamento, elas representam materiais finos destinados à forja de armas resistentes. Embora estejam em bruto e não transformadas em armas acabadas, seu trabalho artesanal supera em muito a sucata bruta típica dos Sertões.",al={"o que são barras de aço forjado","informações sobre barras de aço forjado","barras de aço roubadas"}}},fp="17,144,12.419.0,33.114.0,32.173.0,31.136.0,45.110.0"}
P.entries["item:forked-mudrock-tongue"] = {n="Forked Mudrock Tongue"}
P.entries["item:fragments-of-rok-alim"] = {n="Fragmentos de Rok'Alim",s="Fragmentos de Rok'Alim são os restos de pedra despedaçados de um elemental da terra primordial que vaga pelos cânions de Mil Agulhas. Levados a Dorn Espreitaprados na Gruta Velha, eles servem como prova física irrefutável de que um guerreiro superou um terror ancestral em combate singular.",h="Fragmentos de Rok'Alim são os restos de pedra despedaçados de um elemental da terra primordial que vaga pelos...",kw={"dorn espreitaprados","elemental","fragmentos","moedor","rok'alim","teste de força","mil agulhas","gruta velha"},ang={["class:Shaman"]="Rok'Alim representa um antigo espírito da terra vinculado ao mundo muito antes dos pactos xamânicos modernos, tornando sua natureza inflexível um estudo intrigante sobre a tenacidade elemental pura.",["race:Tauren"]="Superar vestígios resistentes do passado primordial de Azeroth alinha-se estreitamente com as tradições taurens de testar harmonia, fortitude e força pessoal contra os perigos mais formidáveis da terra."},sec={{t="Vestígios de um Poder Ancestral",b="Embora a maioria dos elementais tenha desaparecido de Azeroth após o banimento dos Deuses Antigos, um punhado possuía poder bruto suficiente para perdurar na superfície sem ser evocado por magia mortal. Rok'Alim, o Moedor é um desses sobreviventes, vagando pelas planuras dos cânions ao sul da via principal. Os centauros locais o conhecem pelos estrondos trovejantes de seus punhos de pedra pulverizando qualquer um tolo o bastante para cruzar seu caminho. Abater esse vestígio vivo do mundo primordial rende pedaços pontiagudos de rocha densa e animada — um troféu digno de provar uma destreza física inigualável."},{t="A Prova de Poder",b="Para o eremita tauren Dorn Espreitaprados, recuperar os fragmentos é o componente decisivo do Teste de força. Como parte de uma série de ritos espirituais e marciais realizados no alto da Gruta Velha, a provação exige que um iniciado enfrente uma entidade de força bruta implacável. Entregar os escombros castigados de Rok'Alim prova que um aventureiro possui a bravura e a força física necessárias para sobreviver aos perigos mais severos de Kalimdor."}},faq={{q="O que são os Fragmentos de Rok'Alim?",a="São os restos de pedra despedaçados de Rok'Alim, o Moedor, um antigo elemental da terra que ronda os cânions a noroeste de Mil Agulhas. Eles servem como prova da derrota do elemental.",al={"fragmentos de rokalim","o que sao fragmentos de rokalim","pedra de rokalim"}},{q="Quem quer esses fragmentos de pedra?",a="Dorn Espreitaprados, um tauren concedente de missões que reside na Gruta Velha, no alto dos penhascos dos cânions de Mil Agulhas, pede os fragmentos para concluir o Teste de força.",al={"quem aceita fragmentos de rokalim","entregar fragmentos de rokalim","missao de dorn espreitaprados"}},{q="Por que Rok'Alim é importante?",a="Diferente da maioria dos elementais modernos, que precisam ser conjurados por magos mortais, Rok'Alim permaneceu no mundo desde a era dos Deuses Antigos. As tribos de centauros nos cânions lhe deram o epíteto de 'o Moedor' devido ao estrondo trovejante de seus punhos esmagando suas presas.",al={"por que rokalim e especial","historia de rokalim","quem e rokalim o moedor"}},{q="Onde Rok'Alim é encontrado?",a="Rok'Alim vaga pela bacia noroeste de Mil Agulhas, perambulando ao sul da estrada principal da região, entre os pináculos de arenito.",al={"localizacao de rokalim","encontrar rokalim o moedor","onde rokalim surge"}}},fx={ab6946f8={q="De onde vêm os Fragmentos de Rok'Alim?",a="Estes fragmentos são pedaços estilhaçados de Rok'Alim, o Golpeador, um enorme elemental da terra que vaga pelo chão do cânion a noroeste das Mil Agulhas. Diferente dos elementais conjurados por conjuradores mortais, Rok'Alim é um sobrevivente antigo da era dos Deuses Antigos, possuindo poder inato suficiente para permanecer ligado ao mundo mesmo após a queda de seus mestres. Eles não foram criados por mãos mortais, mas quebrados diretamente de sua forma de pedra viva.",al={"origem dos fragmentos de rokalim","de onde vêm os fragmentos de rokalim","quem fez os fragmentos de rokalim"}}},fp="21,180,28.394.0,18.321.0,35.174.0,32.159.0,28.236.0,24.112.0"}
P.entries["item:frostwolf-banner"] = {n="Estandarte dos Lobo do Gelo",s="O Estandarte dos Lobo do Gelo é um estandarte tribal escondido nas profundezas da Caverna Garragreste, no Vale Alterac. Os iniciados da Horda são enviados para recuperá-lo como um rito de passagem ancestral para despertar seu espírito de batalha e conquistar sua primeira insígnia do clã.",h="O Estandarte dos Lobo do Gelo é um estandarte tribal escondido nas profundezas da Caverna Garragreste, no...",kw={"vale alterac","estandarte dos lobo do gelo","gnolls","insígnia","proving grounds","mestre guerreiro laggrond","caverna garragreste"},ang={["faction:Horde"]="Recuperar este estandarte marca o batismo de sangue formal e a iniciação de um guerreiro no lendário Clã Lobo do Gelo sob a liderança do Mestre Guerreiro Laggrond.",["race:Orc"]="Para os orcs, recuperar um estandarte de clã perdido de gnolls selvagens honra o legado do Clã Lobo do Gelo e a herança ancestral de Thrall nas Montanhas de Alterac."},sec={{t="Um Rito de Passagem",b="Para guerreiros da Horda que chegam ao Vale Alterac, reivindicar uma posição verdadeira entre o Clã Lobo do Gelo começa com uma prova de determinação. O Mestre Guerreiro Laggrond envia novos recrutas para o sul, adentrando os corredores úmidos e hostis da Caverna Garragreste, um covil infestado de gnolls territoriais. Alcançar o estandarte escondido em suas profundezas e devolvê-lo intacto demonstra coragem, provando que a fúria de batalha do guerreiro despertou e garantindo-lhe a insígnia de iniciado dos Lobo do Gelo."}},faq={{q="Por que o Estandarte dos Lobo do Gelo está dentro de uma caverna de gnolls?",a="O Mestre Guerreiro Laggrond e o clã propositalmente tratam a localização do estandarte na Caverna Garragreste como um teste de iniciação. Aventure-se no território dos gnolls força os novos combatentes a abandonar a complacência, enfrentar o perigo e despertar seu espírito de batalha.",al={"por que o estandarte está em garragreste","gnolls têm o estandarte","localização do estandarte dos lobo do gelo"}},{q="A quem entrego o Estandarte dos Lobo do Gelo?",a="O estandarte deve ser devolvido ao Mestre Guerreiro Laggrond no Vale Alterac. Apresentá-lo formalmente a ele acolhe um iniciado nas fileiras dos Lobo do Gelo e concede uma insígnia de prestígio.",al={"quem quer o estandarte dos lobo do gelo","entrega da missão do estandarte","estandarte de laggrond"}},{q="Por que o estandarte parece incomum para um brasão dos Lobo do Gelo?",a="Embora reconhecido por Laggrond como um estandarte de provação do clã, suas marcas visuais lembram insígnias tribais mais antigas, incluindo símbolos associados aos primeiros clãs orcos da antiga Horda.",al={"símbolo do martelo do crepúsculo no estandarte","estandarte parece errado","design do estandarte dos lobo do gelo"}}},fx={cf6c63b1={q="O que é o Estandarte dos Lobo do Gelo?",a="O Estandarte dos Lobo do Gelo é um estandarte tribal que representa o Clã Lobo do Gelo no Vale Alterac. Embora seu brasão estampado se assemelhe estranhamente à iconografia ancestral do clã, em vez de seu emblema habitual, ele permanece um símbolo honrado da presença e autoridade do clã no vale congelado.",al={"o que é o estandarte dos lobo do gelo","lore do estandarte dos lobo do gelo","sobre o estandarte dos lobo do gelo"}},["518ec450"]={q="Por que o Mestre Guerreiro Laggrond quer que o Estandarte dos Lobo do Gelo seja recuperado?",a="O Mestre Guerreiro Laggrond exige que todos os recém-chegados que buscam lutar ao lado dos Lobo do Gelo no Vale Alterac passem por um rito de batalha. Recuperar o estandarte das profundezas da Caverna Garragreste, infestada de gnolls, prova sua coragem, despertando seu espírito guerreiro e lhe garantindo uma insígnia de iniciado entre o clã.",al={"por que recuperar o estandarte dos lobo do gelo","por que laggrond quer o estandarte","propósito do estandarte dos lobo do gelo"}}},fp="16,187,17.384.0,48.208.0,40.160.0,57.196.0"}
P.entries["item:frozen-ectoplasm"] = {n="Frozen Ectoplasm",s="Mux Zoamana precisa de Ectoplasma Congelado dos espíritos inquietos dos Altaneiros de Hibérnia. É uma das três substâncias espectrais que ele busca para seu trabalho com os mortos.",h="Mux Zoamana precisa de Ectoplasma Congelado dos espíritos inquietos dos Altaneiros de Hibérnia.",kw={"altaneiros angustiados","ectoplasma","destilador ectoplásmico","ectoplasma congelado","hunting for ectoplasm","mux zoamana","altaneiros sofredores","hibérnia"},ang={["profession:Engineering"]="Como engenheiro, você talvez reconheça o Destilador Ectoplásmico de Mux como o aparelho que ele usa para coletar substâncias espectrais."},sec={{t="Espíritos do Inverno",b="Perto do lago de Hibérnia, Altaneiros Angustiados e Sofredores deixam Ectoplasma Congelado. Mux Zoamana pede que você o colete com um Destilador Ectoplásmico, junto com Ectoplasma Calcinado de Silithus e Ectoplasma Estável das Terras Pestilentas Orientais. Ele espera que as três substâncias o ajudem a alcançar almas que ainda não partiram por completo deste mundo."}},faq={{q="Onde encontro Ectoplasma Congelado?",a="Altaneiros Angustiados e Sofredores perto do lago em Hibérnia deixam Ectoplasma Congelado.",al={"localização do ectoplasma congelado","onde encontrar ectoplasma congelado","ectoplasma em hibérnia"}},{q="Para que serve o Ectoplasma Congelado?",a="Mux Zoamana precisa dele para Hunting for Ectoplasm, que exige três tipos de ectoplasma coletados com um Destilador Ectoplásmico.",al={"uso do ectoplasma congelado","para que serve","finalidade do ectoplasma"}},{q="Quem quer Ectoplasma Congelado?",a="Mux Zoamana em Geringontzan quer Ectoplasma Congelado, além de Ectoplasma Calcinado e Estável.",al={"ectoplasma do mux","quem precisa dele","mux zoamana"}},{q="Por que Mux quer ectoplasma?",a="Mux espera usar as energias sobrenaturais do ectoplasma para alcançar almas que ainda não partiram por completo deste mundo.",al={"por que ectoplasma","plano de mux","alcançar almas"}},{q="Que espíritos deixam Ectoplasma Congelado?",a="Os espíritos dos Altaneiros Angustiados e Sofredores de Hibérnia deixam Ectoplasma Congelado.",al={"origem do ectoplasma","ectoplasma dos altaneiros","espíritos que deixam ectoplasma congelado"}}},fp="16,166,14.350.0,33.94.0,29.134.0,27.96.0,28.112.0,36.85.0"}
P.entries["item:full-leaden-collection-phial"] = {n="Coletor de Chumbo Cheio",s="Um frasco pesado, revestido de chumbo e cheio de precipitação radioativa irradiada coletada dos troggs que infestam Gnomeregan. O inventor Ozzie Mudavolt solicitou esta amostra perigosa na esperança de sintetizar uma cura para gnomos leprosos irradiados — ou talvez preparar um rum perigosamente potente.",h="Um frasco pesado, revestido de chumbo e cheio de precipitação radioativa irradiada coletada dos troggs que...",kw={"coletor de chumbo cheio","gnogaína","gnomeregan","trogg irradiado","kharanos","frasco de coleta de chumbo","gnomo leproso","ozzie mudavolt"},ang={["profession:Engineering"]="O invólucro de chumbo demonstra os protocolos de segurança gnômicos padrão ao manusear precipitações tóxicas e voláteis para testes de laboratório.",["race:Gnome"]="Para os gnomos exilados em Dun Morogh, carregar esta amostra tóxica é um lembrete sombrio do desastre que envenenou seu lar ancestral, mas representa uma esperança desesperada de recuperar seus parentes corrompidos."},sec={{t="Uma Mistura Tóxica",b="O revestimento de chumbo deste frasco de coleta é essencial para proteger quem o carrega da volátil precipitação verde que satura Gnomeregan. A precipitação teve origem quando os conselheiros do Grão-mecânico Meqqatorque inundaram os corredores inferiores com radiação tóxica para deter os troggs invasores, uma catástrofe que, em vez disso, corrompeu tanto os troggs quanto os gnomos sobreviventes em horrores enlouquecidos e irradiados. Ao coletar resíduos fluidos diretamente de Invasores e Saqueadores Irradiados, aventureiros destemidos fornecem aos engenhoqueiros refugiados, como Ozzie Mudavolt e Razzle Molavivaz em Kharanos, os materiais brutos necessários para testar remédios."},{t="Cura ou Mistura",b="Enquanto Gnoarn continua obcecado em reconquistar a cidade, Ozzie Mudavolt aborda o problema da precipitação com a frenética experimentação gnômica. Ozzie busca usar o líquido recolhido no frasco para tratar um gnomo leproso aprisionado — enquanto espera, simultaneamente, que a mistura possa reverter sua própria calvície. A linha entre um antídoto milagroso e uma bebida altamente volátil permanece perigosamente tênue na ciência de laboratório dos gnomos."}},faq={{q="Por que o frasco é feito de chumbo?",a="O revestimento de chumbo impede que a intensa precipitação radioativa coletada dos troggs contaminados de Gnomeregan adoeça ou mate o portador que a transporta de volta a Kharanos.",al={"por que frasco de chumbo","por que frasco chumbo","proposito do frasco de coleta de chumbo"}},{q="Quem deseja este fluido irradiado?",a="Ozzie Mudavolt, um pesquisador gnomo que atua em Kharanos, precisa da precipitação radioativa para testar uma cura para gnomos afligidos pela lepra, auxiliado por Razzle Molavivaz.",al={"quem precisa do frasco","missao ozzie mudavolt","quem entrega gnogaina"}},{q="De onde vem a radiação no frasco?",a="O resíduo verde brilhante é extraído diretamente de Invasores Irradiados e Saqueadores Irradiados, troggs que rondam os corredores corrompidos que levam a Gnomeregan.",al={"como encher o frasco","localizacao troggs irradiados","origem brilho verde"}},{q="Ozzie realmente cura os gnomos leprosos com isso?",a="Os experimentos de Ozzie são caóticos e incertos. Sua mistura visa curar um gnomo leproso capturado e recuperar seu próprio cabelo, mas a ciência gnômica frequentemente exige testes repetidos e amostras refinadas antes de obter resultados seguros e consistentes.",al={"a cura funciona","resultado da gnogaina","gnomo leproso e curado"}}},fx={["32cc4509"]={q="O que é o Coletor de Chumbo Cheio?",a="É um frasco pesado, revestido de chumbo e cheio de resíduos radioativos verdes e brilhantes, coletados diretamente dos troggs contaminados que infestam Gnomeregan. O revestimento espesso de chumbo impede que os resíduos radioativos perigosos envenenem quem o carrega.",al={"o que é coletor de chumbo","coletor de chumbo cheio","o que é este frasco"}}},fp="28,161,12.485.0,18.331.1,30.195.0,32.163.0,48.145.0,50.226.0"}
P.entries["item:fungal-spores"] = {n="Esporos de Fungos",s="Esporos de Fungos são colhidos de cogumelos carregados que crescem ao redor dos estranhos oásis dos Sertões. Imbuídos com as misteriosas energias vitais dessas águas, eles são muito valorizados pelos pesquisadores da Real Sociedade de Boticários em busca de reagentes potentes para suas misturas químicas.",h="Esporos de Fungos são colhidos de cogumelos carregados que crescem ao redor dos estranhos oásis dos Sertões.",kw={"boticário hermógenes","sociedade dos boticários","sertões","encruzilhada","os charcos esquecidos","esporos de fungos","cogumelo carregado","oásis das águas claras","o oásis estagnado"},ang={["profession:Herbalism"]="Botânicos e coletores notarão as dramáticas mudanças fisiológicas nesses cogumelos causadas pelas águas vivificantes e transformadoras dos oásis dos Sertões.",["race:Undead"]="A Real Sociedade de Boticários valoriza reagentes regionais únicos para impulsionar suas pesquisas, e os fungos mutantes de Kalimdor oferecem uma alternativa atraente à flora empesteada de Lordaeron."},sec={{t="Vitalidade dos Oásis",b="Pelos plainos áridos dos Sertões, oásis esmeraldinos como os Charcos Esquecidos, o Oásis das Águas Claras e o Oásis Estagnado pulsam com uma vitalidade incomum. A água faz mais do que meramente matar a sede; ela ativamente acelera, altera e revigora a flora e a fauna ao redor. Cogumelos que crescem pelas margens úmidas tornam-se inchados e pesados de esporos que carregam esse potencial de crescimento concentrado e volátil. Para os naturalistas, trata-se de uma curiosidade ecológica; para a Real Sociedade de Boticários, é um espécime botânico de primeira linha aguardando militarização ou refinamento."},{t="Alquimia dos Renegados",b="Boticários estacionados no exterior, como o Boticário Hermógenes na Encruzilhada, colhem constantemente reagentes locais exóticos para enviar de volta aos seus laboratórios ou compartilhar com colegas distantes como a Boticária Zaqueia no Penhasco do Trovão. A fisiologia alterada dos esporos os torna especialmente valiosos para o preparo de soluções químicas potentes. Os Renegados valorizam esses espécimes precisamente porque suas propriedades naturais já foram transformadas pelas misteriosas forças que brotam sob o solo de Kalimdor."}},faq={{q="Onde esses esporos são encontrados?",a="Esporos de Fungos são colhidos de cogumelos carregados que crescem pelas margens dos principais oásis dos Sertões: os Charcos Esquecidos, o Oásis das Águas Claras e o Oásis Estagnado.",al={"locais dos esporos","onde encontrar esporos de fungos","locais de cogumelos carregados"}},{q="Por que os Renegados têm interesse neles?",a="Os esporos estão imbuídos com as energias vitais alteradas e vibrantes dos oásis. O Boticário Hermógenes os utiliza para preparar misturas alquímicas potentes para a Real Sociedade de Boticários e para sua colega, a Boticária Zaqueia no Penhasco do Trovão.",al={"por que hermógenes quer esporos","uso dos esporos pelo boticário","para que servem os esporos"}},{q="Por que os cogumelos ao redor dos oásis crescem tanto?",a="As águas dos oásis dos Sertões possuem uma força vital incomum que revigora e sofre mutações na flora e fauna circunvizinhas, fazendo com que os fungos pelas margens inchem com esporos potentes e alterados.",al={"por que os cogumelos sofrem mutação","efeito da água do oásis","mistério do oásis"}},{q="Quem pede pelos esporos?",a="O Boticário Hermógenes, um alquimista Renegado estacionado na Encruzilhada nos Sertões, incumbe aventureiros de colher os esporos para suas pesquisas.",al={"quem precisa de esporos de fungos","quem dá a missão dos esporos","boticário hermógenes"}}},fx={["3c4c96db"]={q="O que são estes Fungal Spores?",a="Estes são esporos potentes coletados dos cogumelos carregados que brotam ao redor dos oásis dos Sertões, como o The Forgotten Pools. Nutridos pelas energias vitais estranhas e alteradas que fluem pelas águas do oásis, os fungos produzem esporos imbuídos de propriedades biológicas incomuns que intrigam os alquimistas.",al={"o que são fungal spores","informações sobre fungal spores","o que são os esporos"}},["02f1bc1b"]={q="Por que o Boticário Hermógenes quer os Fungal Spores?",a="O Boticário Hermógenes na Encruzilhada busca os esporos para a Real Sociedade de Boticários. Ele considera as propriedades alteradas dos fungos do oásis particularmente úteis para preparar uma mistura experimental, que ele pretende entregar ao seu associado, Apothecary Zamah, no Penhasco do Trovão.",al={"por que hermógenes quer os esporos","por que querer fungal spores","quem precisa de fungal spores"}}},fp="13,178,21.429.0,16.379.0,29.151.0,40.200.0,52.133.0,24.104.0"}
P.entries["item:furen-s-instructions"] = {n="Instruções de Furen",s="Instruções de Furen é um pergaminho manuscrito entregue pelo mestre armeiro Furen Barbalonga em Ventobravo. Ele detalha os reagentes raros e perigosos necessários para forjar uma armadura de malha temperada pelo fogo para guerreiros promissores da Aliança.",h="Instruções de Furen é um pergaminho manuscrito entregue pelo mestre armeiro Furen Barbalonga em Ventobravo.",kw={"chifre calcinado","fire hardened mail","furen barbalonga","instruções de furen","chifre galvanizado","urzal dos tuscos","presa de aranha calcinada","cordilheira das torres de pedra","ampola de flogisto","pantanal"},ang={["class:Warrior"]="Esta lista de verificação representa um rito de passagem para guerreiros da Aliança em transição para armaduras pesadas de malha, exigindo provações contra feras ferozes e javatuscos vis.",["profession:Blacksmithing"]="A receita exótica de Furen demonstra como mestres ferreiros combinam reagentes de feras e raras destilações alquímicas para temperar armaduras além do forjamento mundano comum."},sec={{t="As Exigências de um Mestre Ferreiro",b="Furen Barbalonga não entrega armaduras excepcionais levianamente. Já tendo testado a determinação de um guerreiro com tarefas de ferraria mais simples, o artesão anão se oferece para forjar um conjunto de malha extraordinariamente resistente, desde que o aventureiro busque os componentes raros por conta própria. Para garantir que nada seja esquecido, Furen fornece esta lista de verificação detalhada, enviando seu pupilo através de continentes em uma árdua caça ao tesouro."},{t="Componentes Exóticos",b="As instruções descrevem uma jornada perigosa que abrange tanto os Reinos do Leste quanto Kalimdor. Criar os elos endurecidos requer dezenas de presas de aranha chamuscadas das cavernas úmidas do Pantanal, chifres colhidos de quimeras cuspidoras de fogo nos penhascos da Cordilheira das Torres de Pedra e um cobiçado Chifre Galvanizado da própria matriarca das quimeras. O catalisador alquímico final é uma ampola de flogisto volátil, guardada nas profundezas do bastião dos javatuscos no Urzal dos Tuscos."}},faq={{q="O que é Instruções de Furen?",a="É uma lista de verificação escrita entregue a guerreiros da Aliança pelo ferreiro Furen Barbalonga em Ventobravo. Ela descreve os materiais exóticos específicos necessários para forjar um conjunto de armadura Fire Hardened Mail.",al={"instruções de furen","o que são as instruções de furen","lista de furen"}},{q="Quem é Furen Barbalonga?",a="Furen Barbalonga é um mestre armeiro anão estabelecido no Distrito dos Anões de Ventobravo. Ele se especializa em testar guerreiros experientes e criar equipamentos de proteção duráveis para eles.",al={"quem é furen","furen barbalonga","furen ventobravo"}},{q="De onde vêm os materiais da lista?",a="A lista envia os guerreiros para longe: presas de aranha chamuscadas são obtidas de aranhas no Pantanal, chifres carbonizados e um Chifre Galvanizado são caçados de quimeras na Cordilheira das Torres de Pedra, e uma Ampola de Flogisto deve ser tomada de Roogug no Urzal dos Tuscos.",al={"onde encontro os itens","localizações dos materiais de furen","materiais na lista de furen"}},{q="O que Furen forja com esses materiais?",a="Assim que todos os reagentes perigosos e as instruções são devolvidos a ele, Furen usa seus segredos de ferraria para forjar uma peça especializada de armadura Fire Hardened Mail para o guerreiro.",al={"qual armadura furen faz","recompensa fire hardened mail","recompensa de criação de furen"}}},fx={["82702a01"]={q="De onde vieram as Instruções de Furen e quem as criou?",a="Furen Barbalonga, um habilidoso ferreiro anão que trabalha em Ventobravo, escreveu este documento pessoalmente. Conhecendo os segredos para criar uma armadura de malha excepcional, ele escreveu este registro detalhado para descrever os componentes raros necessários em todo o mundo, para que um guerreiro ambicioso saiba exatamente o que procurar.",al={"quem escreveu as instruções de furen","de onde vêm as instruções de furen","origem das instruções de furen"}},["42eefba8"]={q="Por que as Instruções de Furen são importantes?",a="As instruções servem como seu guia para uma árdua caça ao tesouro por Kalimdor e pelos Reinos do Leste. Furen exige que você as mantenha à mão enquanto coleta presas chamuscadas, chifres de quimera e flogisto alquímico, garantindo que você traga exatamente os reagentes de que ele precisa para forjar uma armadura endurecida pelo fogo.",al={"por que preciso das instruções de furen","por que as instruções de furen são procuradas","propósito das instruções de furen"}}},fp="20,106,24.279.0,17.410.0,29.161.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="Notas de Furen",s="As Notas de Furen são fólios escritos que contêm as percepções metalúrgicas e de forja de armaduras descobertas por Furen Barbalonga em Ventobravo. Redigidas após forjar equipamentos de proteção resistentes para guerreiros veteranos, elas são despachadas por toda a Aliança para aprimorar as técnicas de outros artesãos.",h="As Notas de Furen são fólios escritos que contêm as percepções metalúrgicas e de forja de armaduras...",kw={"ferraria","distrito dos anões","furen","furen barbalonga","notas de furen","grimand elmore","cronomorfus espanafuso","mathiel"},ang={["class:Warrior"]="Estas notas são redigidas diretamente como resultado de suas provações de armadura de classe em Ventobravo, servindo como prova das inovações práticas nascidas das suas necessidades de combate na linha de frente.",["profession:Blacksmithing"]="Os fólios representam a troca contínua de conhecimentos especializados em forja de armaduras entre artesãos anões, elfos e gnomos por toda a Aliança."},sec={{t="As Descobertas de um Mestre",b="Quando Furen Barbalonga conclui a rigorosa forja de armamentos especializados de guerreiro no Distrito dos Anões de Ventobravo, ele compila em notas escritas os métodos e avanços que descobriu pelo caminho. A metalurgia dos anões está em constante evolução, e Furen faz várias cópias desses tratados para que seus colegas possam replicar e expandir suas descobertas. Os documentos registram avanços práticos na têmpera, no reforço e na moldagem de armaduras contra golpes letais de combate."},{t="Despachadas por Toda a Aliança",b="Furen distribui suas notas para contatos de confiança nas redes de artesãos da Aliança. Embora mestres locais como Grimand Elmore possam desdenhar de receber ensinamentos de um colega que afirmam ter instruído, o valor dessas percepções não pode ser ignorado. Cópias são até mesmo levadas através do Grande Oceano para artesãos elfos noturnos, como Mathiel no Terraço dos Guerreiros em Darnassus, aproximando tradições ancestrais distintas por meio de uma necessidade marcial em comum."}},faq={{q="O que está contido nas Notas de Furen?",a="As notas contêm descrições escritas de técnicas de forja de armaduras e descobertas metalúrgicas desenvolvidas por Furen Barbalonga enquanto moldava armaduras personalizadas para guerreiros experientes.",al={"o que são as notas de furen","o que há nas notas de furen","conteúdo das notas de furen"}},{q="Quem é Furen Barbalonga?",a="Furen Barbalonga é um mestre anão armeiro estabelecido no Distrito dos Anões de Ventobravo, conhecido por guiar guerreiros em ascensão e forjar equipamentos de guerra defensivos especializados.",al={"quem escreveu isto","quem é furen","furen barbalonga"}},{q="Por que Grimand Elmore fica irritado com as notas?",a="Grimand Elmore é um ferreiro de armas e armaduras ferozmente orgulhoso, que afirma ter ensinado a Furen tudo o que o anão sabe. Embora furioso com a insinuação de que seu antigo aluno possa lhe ensinar algo novo, Grimand ainda admite que as técnicas descritas nas notas valem a pena ser testadas.",al={"por que grimand está irritado","reação de grimand elmore","grimand orgulhoso"}},{q="Quem recebe cópias das Notas de Furen?",a="Furen envia cópias de seus escritos para colegas de confiança por toda a Aliança, incluindo o ferreiro de armas Grimand Elmore em Ventobravo, o ferreiro elfo noturno Mathiel em Darnassus e o ferreiro gnomo Cronomorfus Espanafuso em Altaforja.",al={"quem recebe as notas de furen","para onde vão as notas","entregar notas de furen"}},{q="Como Mathiel reage às notas?",a="Ao contrário dos rudes ferreiros de Ventobravo, Mathiel — um ferreiro elfo noturno encontrado no Terraço dos Guerreiros em Darnassus — acolhe o conhecimento anão com entusiasmo aberto, considerando as descobertas de Furen uma grande revelação e uma honra de integrar ao seu próprio trabalho.",al={"reação de mathiel","mathiel darnassus","o que mathiel acha"}}},fx={["224f803f"]={q="Por que alguém quer as Notas de Furen?",a="As notas documentam técnicas de forja inovadoras que Furen Barbalonga desenvolveu enquanto forjava armaduras especializadas de guerreiro. Ferreiros de toda a Aliança — como Mathiel em Darnassus e Grimand Elmore em Ventobravo — podem obter conhecimentos metalúrgicos valiosos com elas. Até mesmo artesãos céticos quanto à habilidade de Furen, como Elmore, reconhecem ideias inovadoras nelas que estão ansiosos para testar em suas próprias bigornas.",al={"por que ferreiros querem as notas de furen","valor das notas de furen","por que compartilhar as notas de furen"}}},fp="13,223,22.332.0,30.350.0,39.157.0,23.146.0,50.205.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="Escritura do Taturana",s="A Escritura do Taturana é o título legal de propriedade pertencente ao Fazendeiro Theodore Taturana e sua esposa Verna sobre suas terras em Cerro Oeste. Roubada por bandidos Défias para servir como modelo na falsificação de reivindicações de terras, ela representa a situação precária do povo honesto expulso de seus lares por todo o reino.",h="A Escritura do Taturana é o título legal de propriedade pertencente ao Fazendeiro Theodore Taturana e sua...",kw={"escritura","defias","fazenda","taturana","theodore","verna","carroca","cerro oeste"},ang={["faction:Alliance"]="Devolver a escritura traz um pequeno consolo aos súditos desabrigados e abandonados pela escassez militar do reino.",["race:Human"]="O roubo de simples títulos de propriedade destaca o quanto os Défias comprometeram profundamente a ordem civil nos territórios vizinhos de Ventobravo."},sec={{t="Terras Roubadas e Reivindicações Falsificadas",b="Assinado por Theodore Taturana e coassinado por sua esposa Verna, este papel estabelece a posse sobre a fazenda da família em Cerro Oeste. Quando A Irmandade Défias tomou a região, salteadores expulsaram o casal e levaram o documento com eles para a Floresta de Elwynn. Anotações rascunhadas no verso revelam que os ladrões pretendiam usar o pergaminho oficial como modelo para falsificar escrituras legais de outras propriedades. Despojados de seu lar e sustento, os Taturana foram forçados a pegar a estrada, ficando encalhados perto da fronteira quando sua carroça quebrou."}},faq={{q="Por que os Défias roubaram a escritura?",a="Anotações feitas no verso do pergaminho revelam que os capangas Défias pretendiam estudar o selo autêntico e as assinaturas para falsificar suas próprias escrituras, legitimando a posse de propriedades tomadas por todo o Cerro Oeste.",al={"por que roubar escritura","por que bandidos queriam escritura","objetivo da escritura dos defias"}},{q="A quem pertence esta escritura?",a="A escritura pertence legalmente ao Fazendeiro Theodore Taturana e sua esposa Verna, dois proprietários rurais de Cerro Oeste que foram hostilizados e expulsos de sua fazenda por foras da lei.",al={"quem e dono da escritura do taturana","quem e taturana","de quem e esta escritura"}},{q="Onde os Taturana podem ser encontrados?",a="O casal pode ser encontrado logo na entrada de Cerro Oeste, ao longo da estrada principal vinda da Floresta de Elwynn, ilhados ao lado de sua carroça quebrada.",al={"onde estao os taturana","localizacao do fazendeiro taturana","onde devolver escritura"}},{q="Por que os Taturana ainda se importam com a escritura se fugiram?",a="Embora os Taturana admitam que Cerro Oeste se tornou perigoso demais para pessoas honestas, manter a prova legal de posse oferece a única esperança de recuperarem suas terras se a paz for restaurada.",al={"por que querem escritura de volta","os taturana vao voltar"}}},fx={["4593623b"]={q="De onde vem a Furlbrow's Deed e quem a fez?",a="A escritura é um título de terra oficial para uma extensão de terras agrícolas em Cerro Oeste, assinado por Theodore Furlbrow e coassinado por sua esposa, Vera Taturana. Ele estabelecia sua propriedade legítima sobre sua fazenda familiar antes que os bandidos da The Defias Brotherhood os extorquissem e a roubassem de suas mãos.",al={"origem da escritura de furlbrow","quem fez a escritura de furlbrow","de onde veio a escritura"}}},fp="15,205,29.380.0,34.129.0,29.121.0,33.116.0,60.150.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="Relógio de Bolso do Taturana",s="O Relógio de Bolso do Taturana é uma estimada relíquia de família que pertence ao Fazendeiro Taturana de Cerro Oeste. Dado a ele pelo pai de sua esposa, Verna, no dia de seu casamento, o relógio foi abandonado às pressas quando bandidos Défias tomaram sua fazenda de abóboras.",h="O Relógio de Bolso do Taturana é uma estimada relíquia de família que pertence ao Fazendeiro Taturana de...",kw={"benny blaanco","defias","fazendeiro taturana","relógio de bolso do taturana","herança esquecida","vera taturana","guarda-roupa","cerro oeste"},ang={["faction:Alliance"]="Ajudar os Taturana a recuperar sua relíquia perdida é um lembrete contundente de como a coroa de Ventobravo falhou completamente em proteger os dedicados fazendeiros de Cerro Oeste do banditismo organizado."},sec={{t="Uma Lembrança nas Ruínas",b="Quando arruaceiros Défias invadiram o Furlbrow Pumpkin Patch, o Fazendeiro Taturana e sua esposa, Verna, foram forçados a abandonar sua propriedade no meio da noite. Na fuga desesperada, o fazendeiro deixou para trás um precioso relógio de bolso, dado a ele como presente de casamento por seu sogro. A relíquia permaneceu guardada dentro de um guarda-roupa na casa de fazenda tomada, vigiada por degoladores liderados por Benny Blaanco. Para o casal desalojado que acampa à beira da estrada, recuperar o relógio representa preservar um dos poucos fragmentos de sua antiga vida que os foras da lei não destruíram."}},faq={{q="Por que o relógio de bolso é tão importante para o Fazendeiro Taturana?",a="O relógio foi dado ao Fazendeiro Taturana pelo pai de Verna no dia de seu casamento. Tendo perdido suas terras, casa e sustento para A Irmandade Défias, o relógio é a última posse de profundo valor sentimental que restou ao casal.",al={"por que taturana quer seu relogio","importancia relogio taturana","quem deu o relogio para taturana"}},{q="Onde o relógio de bolso está guardado?",a="O relógio foi deixado dentro de um guarda-roupa na casa de fazenda dos Taturana, localizada entre os campos de abóbora a oeste da estrada principal onde os Taturana estão atualmente ilhados.",al={"onde fica o relogio de bolso","localizacao guarda-roupa taturana","como encontrar o relogio"}},{q="Quem está vigiando o relógio?",a="A casa de fazenda abandonada foi dominada pel'A Irmandade Défias, especificamente pelo bandido Benny Blaanco e seu bando, que rondam bem perto do guarda-roupa.",al={"quem esta com o relogio de taturana","guarda do relogio cerro oeste","benny blaanco relogio"}},{q="Os Défias roubaram o relógio diretamente?",a="Não. Quando os bandidos invadiram a plantação de abóboras, os Taturana fugiram em tamanho pânico que o fazendeiro simplesmente esqueceu de pegá-lo. Ele permaneceu escondido dentro do guarda-roupa do quarto enquanto a fazenda era tomada.",al={"os defias saquearam o relogio","o relogio foi roubado"}}},fx={["42b91745"]={q="O que é o Relógio de Bolso do Taturana?",a="É uma herança de família estimada que pertence ao Fazendeiro Taturana. O relógio foi dado a ele pelo pai de sua esposa, Vera, como um presente no dia do casamento deles. Quando a The Defias Brotherhood invadiu sua fazenda de abóboras, o casal teve que fugir para salvar suas vidas no meio da noite, deixando inadvertidamente o precioso relógio para trás em seu guarda-roupa.",al={"o que é o relógio de furlbrow","relógio de bolso do furlbrow","relógio de bolso do fazendeiro furlbrow"}},ba43cdcd={q="De onde vem o Relógio de Bolso do Taturana e quem o fabricou?",a="O relógio pertencia originalmente ao pai de Vera Taturana, que o presenteou ao Fazendeiro Taturana no dia do casamento do casal. O artesão específico ou a cidade de sua fabricação são desconhecidos, mas para os agricultores desalojados, ele representa um dos poucos símbolos duradouros de sua família e vida anterior antes que os Defias os expulsassem de suas terras.",al={"quem fez o relógio de bolso do furlbrow","onde furlbrow conseguiu o relógio","origem do relógio de bolso do furlbrow"}}},fp="23,161,23.356.0,56.202.0,31.136.0,26.107.0,40.219.0"}
P.entries["item:gadrin-s-parchment"] = {n="Gadrin's Parchment",s="O Pergaminho de Gadrin é lido em Shadra'Alor, nas Terras Agrestes. Suas palavras invocam Shadra, cujo veneno o Boticário Lindolfo busca na Serraria Tarren.",h="O Pergaminho de Gadrin é lido em Shadra'Alor, nas Terras Agrestes.",kw={"boticário lindolfo","gadrin","pergaminho de gadrin","terras agrestes","pergaminho","shadra","shadra'alor","veneno","witherbark"},sec={{t="Em Shadra'Alor",b="Nas profundezas do reino Witherbark, o Pergaminho de Gadrin é lido no altar de Shadra'Alor. Suas palavras invocam Shadra, a deusa-aranha. O Boticário Lindolfo busca seu veneno na Serraria Tarren."}},faq={{q="O que o Pergaminho de Gadrin faz?",a="O Pergaminho de Gadrin é lido em Shadra'Alor para invocar Shadra, a deusa-aranha.",al={"para que serve o pergaminho","uso do pergaminho de gadrin"}},{q="Onde devo ler o pergaminho?",a="Leia o Pergaminho de Gadrin no altar de Shadra'Alor, nas profundezas do reino Witherbark, nas Terras Agrestes.",al={"onde usar o pergaminho","localização do altar de shadra"}},{q="Quem é Shadra?",a="Shadra é a deusa-aranha invocada ao ler o Pergaminho de Gadrin em Shadra'Alor.",al={"shadra aranha","deusa-aranha"}},{q="Quem quer o veneno de Shadra?",a="O Boticário Lindolfo, na Serraria Tarren, busca o veneno de Shadra.",al={"para quem é o veneno","veneno para lindolfo"}}},fp="18,137,14.182.0,32.75.0,30.101.0,14.79.0,25.53.0"}
P.entries["item:gaea-seed"] = {n="Semente de Gaia",s="Sementes de Gaia são caroços resistentes de plantas encontrados ao longo da margem da água do Lago Mirkfallon, na Cordilheira das Torres de Pedra. Valorizadas por xamãs taurens, elas são imbuídas com bênçãos elementais para ajudar a revitalizar áreas devastadas pela guerra e pela indústria.",h="Sementes de Gaia são caroços resistentes de plantas encontrados ao longo da margem da água do Lago...",kw={"vale carbonizado","ciclo de renascimento","mãe-terra","semente de gaia","lago mirkfallon","cordilheira das torres de pedra","retiro rocha do sol","tammra campo de vento"},ang={["class:Shaman"]="As sementes representam uma restauração prática da terra, demonstrando como os rituais xamânicos e a bênção da Mãe-terra podem acelerar o crescimento natural em ambientes danificados.",["race:Tauren"]="Para os taurens do Retiro Rocha do Sol, cultivar Sementes de Gaia é uma obrigação sagrada para curar o equilíbrio da terra perturbado por guerras externas e pela exploração madeireira."},sec={{t="Recipientes de Renovação",b="As Sementes de Gaia são nativas da Cordilheira das Torres de Pedra, surgindo naturalmente ou crescendo ao redor das margens do Lago Mirkfallon. Embora tenham uma aparência modesta — lembrando pequenos cocos fibrosos —, elas carregam uma resiliência inerente. À medida que a exploração industrial e os conflitos deixam cicatrizes na Cordilheira das Torres de Pedra, praticantes xamânicos veem essas sementes como condutores vitais para curar a terra ferida."},{t="Bênçãos da Mãe-terra",b="No Retiro Rocha do Sol, a xamã tauren Tammra Campo de Vento colhe Sementes de Gaia para combater a destruição que se espalha pelos picos. Por meio de cânticos tradicionais e rituais elementais, os xamãs imbuem essas cascas dormentes com a bênção da Mãe-terra. Essa infusão espiritual acelera drasticamente seu crescimento natural, transformando sementes simples em mudas resistentes capazes de criar raízes em solo estéril e calcinado, como o Vale Carbonizado."}},faq={{q="Onde as Sementes de Gaia são encontradas?",a="As Sementes de Gaia são encontradas espalhadas ao longo da costa do Lago Mirkfallon, situado nas montanhas ao norte do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra.",al={"localização da semente de gaia","onde encontrar sementes de gaia","como obter semente de gaia"}},{q="Para que são usadas as Sementes de Gaia?",a="Tammra Campo de Vento as coleta no Retiro Rocha do Sol para realizar uma bênção elemental. Uma vez imbuídas de poder xamânico, as sementes são usadas para restaurar a vida vegetal em áreas devastadas como o Vale Carbonizado.",al={"propósito da semente de gaia","por que coletar sementes de gaia","o que tammra faz com sementes de gaia"}},{q="Por que os xamãs precisam imbuir as sementes?",a="A terra em partes da Cordilheira das Torres de Pedra foi severamente degradada pelo fogo, pela guerra e pela extração de madeira. Canalizar o poder da Mãe-terra para as sementes acelera sua germinação e as fortalece o suficiente para crescerem em solo hostil e arruinado.",al={"por que abençoar as sementes","magia xamânica de semente de gaia"}},{q="Como são as Sementes de Gaia?",a="Elas ficam perto da margem da água ao redor do Lago Mirkfallon e se parecem com cascas ou cocos pequenos, marrons e arredondados caídos na margem.",al={"aparência da semente de gaia","como identificar sementes de gaia"}}},fx={["0f706426"]={q="O que é uma Semente de Gaia?",a="Uma Semente de Gaia é um núcleo de vida resistente, semelhante a um coco, nativo da Cordilheira das Torres de Pedra. Abençoadas com resiliência natural, essas sementes contêm um potencial vegetativo potente que os xamãs tauren utilizam por meio das bênçãos da Mãe Terra para trazer crescimento restaurador a terras marcadas pela ganância industrial e pela guerra.",al={"o que são sementes de gaia","informações sobre semente de gaia","o que é uma semente de gaia"}},e9a7441d={q="De onde vem uma Semente de Gaia?",a="As Sementes de Gaia são maravilhas botânicas naturais encontradas apenas ao longo da margem do Lago Mirkfallon, aninhadas no alto da Cordilheira das Torres de Pedra, ao norte do Retiro Rocha do Sol. Elas não são criadas por mãos mortais, mas sim dons naturais da Mãe Terra, florescendo naturalmente ao redor das margens do lago.",al={"quem fez a semente de gaia","origem da semente de gaia","de onde vêm as sementes de gaia"}},["3509f4c5"]={q="Por que Tammra Campo de Vento quer Sementes de Gaia?",a="Tammra Campo de Vento, uma xamã no Retiro Rocha do Sol, busca Sementes de Gaia para curar a região selvagem marcada da Cordilheira das Torres de Pedra. O desmatamento contínuo e os combates devastaram a região, particularmente a terra chamuscada do Vale Carbonizado. Ao coletar essas sementes, ela pode canalizar a bênção da Mãe Terra e seu poder xamânico nelas, acelerando seu crescimento para repovoar a terra arruinada.",al={"por que coletar sementes de gaia","quem quer sementes de gaia","por que alguém quer semente de gaia"}}},fp="9,162,18.243.0,28.359.1,27.103.0,29.172.0,39.167.0,29.103.0"}
P.entries["item:gaffer-jack"] = {n="Deschanfrador",s="Um Deschanfrador é um componente de engenharia especializado usado para ajustes mecânicos complexos, como afinar pinos de suporte. Um caixote deles foi perdido por descuido sob as ondas na costa de Auberdine pelo excêntrico inventor gnomo Xafetim Manigiro durante sua viagem pelo mar.",h="Um Deschanfrador é um componente de engenharia especializado usado para ajustes mecânicos complexos, como...",kw={"auberdine","costa negra","pesca","deschanfrador","altaforja","pinos de suporte","xafetim manigiro"},ang={["profession:Engineering"]="Outros engenhoqueiros reconhecerão a imensa frustração de perder peças proprietárias como os deschanfradores, sem os quais mecanismos delicados como os pinos de suporte não podem ser calibrados.",["race:Gnome"]="Trocar a agitação de Altaforja por uma vida tranquila em Auberdine pode parecer incomum para um gnomo, mas perder um caixote inteiro de peças essenciais pela borda de um navio após beber demais é algo totalmente típico."},sec={{t="Perdido no Mar",b="Buscando paz e sossego longe do barulho das forjas e das tavernas barulhentas de Altaforja, o engenhoqueiro gnomo Xafetim Manigiro comprou passagem a bordo de um navio com destino a Auberdine. Tendo bebido um pouco além da conta durante a viagem oceânica, Xafetim se atrapalhou e deixou cair um recipiente inteiro de deschanfradores pela amurada. Esses pequenos fixadores mecânicos afundaram nas águas costeiras enevoadas de Costa Negra, deixando-o desamparado e sem as peças vitais necessárias para afinar seus pinos de suporte."},{t="Resgate Submerso",b="Como os deschanfradores foram derramados na arrebentação ao longo da costa, eles ocasionalmente prendem nos anzóis de pescadores pacientes que lançam suas linhas nas águas costeiras de Costa Negra. Recuperar esses componentes perdidos permite que Xafetim monte suas engenhocas bizarras, embora dragar pequenas ferragens de metal de mar aberto continue sendo uma prova tanto de paciência extraordinária quanto de pura sorte."}},faq={{q="Para que serve um Deschanfrador?",a="De acordo com o engenhoqueiro gnomo Xafetim Manigiro, os deschanfradores são componentes essenciais de engenharia necessários para afinar pinos de suporte para suas invenções experimentais.",al={"para que serve deschanfrador","o que faz um deschanfrador","uso do deschanfrador"}},{q="Como eles foram parar no oceano ao redor de Auberdine?",a="Xafetim Manigiro pegou um navio dos Reinos do Leste em busca de paz e sossego longe de Altaforja. Durante a viagem, ele bebeu demais e acidentalmente deixou seu caixote de deschanfradores cair pela amurada nas águas de Costa Negra.",al={"por que ha deschanfradores na agua","quem derrubou os deschanfradores","deschanfrador perdido"}},{q="Quem quer a recuperação dos Deschanfradores?",a="Xafetim Manigiro, um excêntrico inventor gnomo hospedado na cidade portuária de Auberdine, precisa que oito deles sejam devolvidos para continuar construindo suas estranhas invenções.",al={"quem precisa de deschanfradores","onde entregar deschanfrador","quem aceita deschanfradores"}},{q="Onde os Deschanfradores podem ser encontrados?",a="Eles estão submersos ao longo da costa de Costa Negra, repousando no leito marinho onde os pescadores ocasionalmente os fisgam enquanto pescam na arrebentação costeira.",al={"onde conseguir deschanfradores","como achar deschanfradores","localizacao do deschanfrador"}}},fx={["1164a7e3"]={q="O que é um Deschanfrador?",a="Um Deschanfrador é um componente de engenharia especializado usado por inventores como Xafetim Manigiro. Especificamente, Xafetim depende deles para ajustar corretamente seus pinos de stintle, tornando-os uma parte indispensável de seu kit de ferramentas de invenção.",al={"o que é um deschanfrador","lore sobre deschanfradores","o que são deschanfradores"}}},fp="11,130,11.333.0,14.253.0,31.95.0,51.206.0,33.152.0,32.112.0"}
P.entries["item:gahz-ridian-detector"] = {n="Gahz'ridian Detector",s="O Gahz'ridian Detector foi criado por Marlon Catarrebite para encontrar ornamentos em Tanaris. Ele o ajuda a reunir material para seus estudos sobre as esculturas feitas pelos trolls.",h="O Gahz'ridian Detector foi criado por Marlon Catarrebite para encontrar ornamentos em Tanaris.",kw={"pilar partido","ruínas de lunaleste","gahz'ridian","gahz'ridian detector","ornamento de gahz'ridian","gahz'rilla","marlon catarrebite","ruínas de lunassul","tanaris"},sec={{t="Uma busca no deserto",b="Marlon Catarrebite criou o Gahz'ridian Detector para ajudar a localizar ornamentos feitos de Gahz'ridian. Há muito tempo, os trolls moldaram esses ornamentos à imagem de Gahz'rilla, a quem veneravam como uma divindade. As esculturas estão espalhadas por Tanaris, e muitas ficam perto do Pilar Partido, das Ruínas de Lunaleste e das Ruínas de Lunassul."}},faq={{q="Quem criou o Gahz'ridian Detector?",a="Marlon Catarrebite, cientista e caçador de tesouros em Tanaris, inventou o Gahz'ridian Detector.",al={"quem criou o detector","aparelho de marlon","inventor do detector"}},{q="O que o detector encontra?",a="O Gahz'ridian Detector ajuda a localizar ornamentos feitos de Gahz'ridian, um material que recebeu o nome de Gahz'rilla.",al={"o que o detector encontra","encontrar gahz'ridian","função do detector"}},{q="Quem criou os ornamentos de Gahz'ridian?",a="Os trolls que viveram em Tanaris esculpiram os ornamentos de Gahz'ridian há muito tempo.",al={"quem criou os ornamentos","esculturas dos trolls","origem dos ornamentos"}},{q="Por que os ornamentos têm a forma de Gahz'rilla?",a="Os ornamentos foram inspirados em Gahz'rilla, uma hidra que os trolls veneravam como uma divindade.",al={"por que ornamentos de gahz'rilla","esculturas de hidra","ídolo de gahz'rilla"}},{q="Onde posso encontrar ornamentos de Gahz'ridian?",a="Os ornamentos de Gahz'ridian estão espalhados por Tanaris, especialmente perto do Pilar Partido, das Ruínas de Lunaleste e das Ruínas de Lunassul.",al={"onde ficam os ornamentos","locais de gahz'ridian","ornamentos em tanaris"}}},fp="20,184,15.304.0,34.98.0,28.105.0,35.75.0,45.86.0,39.114.0"}
P.entries["item:gahz-ridian-ornament"] = {n="Gahz'ridian Ornament",s="Os ornamentos de Gahz'ridian são relíquias entalhadas espalhadas por Tanaris. Marlon Catarrebite os estuda em busca de pistas sobre os trolls que viveram aqui.",h="Os ornamentos de Gahz'ridian são relíquias entalhadas espalhadas por Tanaris.",kw={"pilar partido","detector","ruínas de lunaleste","gahz'ridian","gahz'rilla","marlon catarrebite","ornamento","ruínas de lunassul","tanaris","trolls"},sec={{t="Relíquias entalhadas",b="Marlon Catarrebite procura ornamentos de Gahz'ridian por Tanaris. Ele diz que os trolls que outrora ocuparam este deserto os entalharam à semelhança de Gahz'rilla, a hidra que veneravam. Os ornamentos são feitos de uma substância que Marlon chama de Gahz'ridian, nomeada em homenagem àquela criatura reverenciada. Ele já reuniu alguns e quer mais para seus estudos."}},faq={{q="O que são ornamentos de Gahz'ridian?",a="Os ornamentos de Gahz'ridian são entalhes feitos pelos trolls que viveram em Tanaris. Eles retratam Gahz'rilla, uma hidra que os trolls veneravam.",al={"gahz'ridian","o que é gahz'ridian","significado de ornamento"}},{q="Quem quer os ornamentos?",a="Marlon Catarrebite, cientista e caçador de tesouros em Tanaris, quer ornamentos de Gahz'ridian para seus estudos.",al={"quem quer gahz'ridian","ornamentos de marlon","onde levar ornamentos"}},{q="Onde posso encontrar ornamentos de Gahz'ridian?",a="Os ornamentos estão espalhados por Tanaris, com muitos nas proximidades do Pilar Partido, das Ruínas de Lunaleste e das Ruínas de Lunassul.",al={"locais de gahz'ridian","onde ficam os ornamentos","ruínas de gahz'ridian"}},{q="O que é Gahz'rilla?",a="Gahz'rilla é uma hidra que os trolls de Tanaris veneravam como uma divindade. Os ornamentos são entalhados à sua semelhança.",al={"significado de gahz'rilla","deus hidra","divindade troll"}},{q="Para que serve o detector?",a="Marlon Catarrebite inventou o Gahz'ridian Detector para ajudar a encontrar os ornamentos espalhados por Tanaris.",al={"detector de gahz'ridian","localizador de ornamentos","como encontrar gahz'ridian"}}},fp="20,142,13.341.0,31.135.0,24.108.0,39.112.0,19.108.0,25.106.0"}
P.entries["item:gallywix-s-head"] = {n="Cabeça do Gallywix",s="A Cabeça do Gallywix é um troféu decepado tirado do Grand Foreman Puzik Gallywix, um supervisor da Empreendimentos S.A. que atuava no Charco de Lodo, nos Sertões. Ela serve como a macabra prova de execução exigida pela The Shattered Hand, a camarilha secreta de ladinos sediada em Orgrimmar.",h="A Cabeça do Gallywix é um troféu decepado tirado do Grand Foreman Puzik Gallywix, um supervisor da...",kw={"sertões","gallywix","orgrimmar","puzik","the shattered hand","shenthul","charco de lodo","empreendimentos s.a."},ang={["class:Rogue"]="Recuperar a Cabeça do Gallywix comprova a capacidade letal de um ladino em infiltração secreta, furtividade e assassinato direcionado em nome da The Shattered Hand.",["faction:Horde"]="Eliminar líderes da Empreendimentos S.A. como Gallywix refreia as incursões industriais predatórias que ameaçam as fronteiras dos Sertões e de Durotar."},sec={{t="Uma Terrível Prova de Eliminação",b="O Grand Foreman Puzik Gallywix coordenava operações a partir da torre da Empreendimentos S.A. ao norte do Charco de Lodo. Após surgirem notícias de que a Empreendimentos S.A. planejava algo em grande escala, a The Shattered Hand enviou agentes para desmantelar totalmente a instalação. Obter a cabeça de Puzik Gallywix serve como prova absoluta para Shenthul em Orgrimmar de que o supervisor foi executado, assegurando o prestígio do ladino dentro da guilda."},{t="A Incursão ao Charco de Lodo",b="A missão de obter a cabeça do Gallywix é acompanhada pela incumbência de recuperar um esconderijo roubado da mistura adulterada do Zanzil e abater o pessoal envenenado da torre. Ao assassinar Gallywix no alto de seu posto e levar sua cabeça de volta ao Antro das Sombras, os agentes confirmam que o grande plano da Empreendimentos S.A. nos Sertões foi arruinado."}},faq={{q="De quem é esta cabeça?",a="A cabeça pertence ao Grand Foreman Puzik Gallywix, um supervisor gnomo que comandava as operações da Empreendimentos S.A. no Charco de Lodo, no norte dos Sertões.",al={"quem é gallywix","puzik gallywix","origem da cabeça do gallywix"}},{q="Quem quer a Cabeça do Gallywix?",a="O troféu é entregue a Shenthul, um instrutor de ladinos e agente da The Shattered Hand localizado no Antro das Sombras, em Orgrimmar.",al={"para quem entrego a cabeça","entregar cabeça do gallywix","cabeça shenthul"}},{q="Por que a The Shattered Hand o quer morto?",a="Puzik Gallywix comandava a torre da Empreendimentos S.A. ao norte do Charco de Lodo, onde a Empreendimentos S.A. planejava algo em grande escala, e guardava o último esconderijo da mistura adulterada do Zanzil em seu cofre. A The Shattered Hand decretou sua morte para interromper a operação e confiscar a mistura.",al={"por que matar gallywix","motivo do assassinato de gallywix"}},{q="Onde Puzik Gallywix fica localizado?",a="Ele é encontrado no ponto mais alto da torre da Empreendimentos S.A., localizada logo ao norte do Charco de Lodo, no norte dos Sertões.",al={"onde fica gallywix","localização de gallywix","chefe da torre do charco de lodo"}}},fx={["862bd188"]={q="De onde vem a Cabeça do Gallywix?",a="A cabeça foi decepada do Grande Capataz Puzik Gallywix, um supervisor goblin que supervisiona as operações na torre da Empreendimentos S.A. ao norte do Charco de Lodo nos Sertões. Encarregado pela The Shattered Hand de infiltrar-se na fortaleza e eliminar seus habitantes, um assassino retira a cabeça do capataz diretamente de seu cadáver no topo da torre como prova de que a operação foi decisivamente interrompida.",al={"onde conseguir a cabeça do gallywix","origem da cabeça do gallywix","como conseguir a cabeça do gallywix"}}},fp="15,144,27.371.0,24.322.1,19.152.0,26.119.0,42.285.0,32.117.0"}
P.entries["item:galvanized-horn"] = {n="Chifre Galvanizado",s="Um Chifre Galvanizado é uma protuberância biológica endurecida colhida das formidáveis matriarcas quimeras que assombram os penhascos calcinados de Kalimdor. Altamente cobiçado por mestres armeiros de ambas as facções, este espécime resistente serve como material fundamental para armaduras especializadas de guerreiro.",h="Um Chifre Galvanizado é uma protuberância biológica endurecida colhida das formidáveis matriarcas quimeras...",kw={"vale carbonizado","matriarca quimera","fire hardened mail","furen barbalonga","chifre galvanizado","orm casco de pedra","cordilheira das torres de pedra"},ang={["class:Warrior"]="Matar uma matriarca e obter seu chifre galvanizado é uma prova de resistência e poder, demonstrando a coragem de um guerreiro aos mestres armeiros em Ventobravo ou no Penhasco do Trovão.",["profession:Blacksmithing"]="O chifre demonstra como materiais orgânicos endurecidos em ambientes extremos podem se igualar ou superar metais trabalhados no reforço de armaduras personalizadas."},sec={{t="Troféu do Vale Carbonizado",b="Quimeras são feras selvagens de duas cabeças conhecidas por sua ferocidade, mas as matriarcas anciãs que rondam o Vale Carbonizado na Cordilheira das Torres de Pedra possuem chifres forjados de maneira extraordinariamente rígida por cinzas, chamas e sobrevivência. Enquanto filhotes comuns fornecem chifres frágeis e enegrecidos, o chifre da matriarca possui uma força naturalmente temperada semelhante a metal tratado. Tanto o armeiro anão Furen Barbalonga em Ventobravo quanto Orm Casco de Pedra no Penhasco do Trovão cobiçam o chifre, exigindo-o como um teste de valor marcial e como um ingrediente crucial na confecção de armaduras de malha excepcionais."}},faq={{q="De onde vem um Chifre Galvanizado?",a="Ele é obtido de matriarcas quimeras que habitam o Vale Carbonizado, localizado nos confins ocidentais da Cordilheira das Torres de Pedra.",al={"onde conseguir chifre galvanizado","como conseguir chifre galvanizado","saque de chifre galvanizado"}},{q="Por que os ferreiros querem este chifre específico?",a="Mestres armeiros valorizam o chifre por sua densidade natural e propriedades resistentes ao calor, usando-o para reforçar conjuntos especializados de armaduras de malha e placas.",al={"para que serve o chifre galvanizado","uso do chifre galvanizado"}},{q="Quem aceita o Chifre Galvanizado?",a="Para guerreiros da Aliança, Furen Barbalonga em Ventobravo exige o chifre para forjar armaduras endurecidas pelo fogo. Para guerreiros da Horda, Orm Casco de Pedra no Penhasco do Trovão busca-o como prova de força para confeccionar o elmo de um guerreiro.",al={"quem precisa de chifre galvanizado","onde entregar chifre galvanizado"}},{q="Como ele se diferencia de um Chifre Calcinado comum?",a="Chifres calcinados comuns são facilmente obtidos de quimeras menores e filhotes. O chifre galvanizado vem exclusivamente de uma matriarca madura, possuindo uma estrutura muito mais densa e temperada, adequada para a forja de obras-primas.",al={"chifre calcinado vs chifre galvanizado","é diferente do chifre calcinado"}}},fx={["39b0e048"]={q="O que é um Chifre Galvanizado?",a="Um Chifre Galvanizado é um chifre raro e endurecido retirado de uma Matriarca Quimera que habita na Cordilheira das Torres de Pedra de Kalimdor. Ao contrário dos chifres de quimera comuns, ele foi endurecido pelo ambiente hostil e devastado pelo fogo do Vale Carbonizado, tornando-o excepcionalmente resistente e valorizado por mestres armeiros tanto da Aliança quanto da Horda.",al={"identidade do chifre galvanizado","o que é um chifre galvanizado","lore do chifre galvanizado"}}},fp="15,140,26.367.0,39.107.0,38.131.0,32.205.0,47.173.0"}
P.entries["item:gan-zulah-s-head"] = {n="Gan'zulah's Head",s="A cabeça de Gan'zulah é retirada do chefe Bloodscalp em Zul'Kunda. Em Grom'gol, ela é levada a um caldeirão borbulhante como parte da busca por Yennikan.",h="A cabeça de Gan'zulah é retirada do chefe Bloodscalp em Zul'Kunda.",kw={"bloodscalp","caldeirão","lançanegra","gan'zulah","gan'zulah's head","grom'gol","nimboya","yennikan","zul'kunda"},ang={["faction:Horde"]="Como membro da Horda, você ajuda os Lançanegra em Grom'gol a buscar a verdade sobre Yennikan entre seus inimigos Bloodscalp.",["race:Troll"]="Como troll, você está no meio do conflito entre os Lançanegra e o clã Bloodscalp, cujo chefe Nimboya quer decapitado."},sec={{t="A cabeça de um chefe",b="Em Zul'Kunda, no noroeste da Selva do Espinhaço, buscam a cabeça de Gan'zulah e a de Nezzliok the Dire. Nimboya pede que você leve ambas ao Caldeirão borbulhante no Acampamento Grom'gol. Os Lançanegra esperam que os líderes mortos revelem a verdade sobre Yennikan."}},faq={{q="Quem foi Gan'zulah?",a="Gan'zulah era o chefe dos trolls Bloodscalp em Zul'Kunda, inimigo da tribo Lançanegra.",al={"gan zulah","chefe bloodscalp","história de gan'zulah"}},{q="De onde vem a cabeça de Gan'zulah?",a="A cabeça de Gan'zulah é retirada de Gan'zulah nas ruínas de Zul'Kunda, na Selva do Espinhaço.",al={"de onde vem a cabeça","localização da cabeça de gan zulah","encontrar gan'zulah"}},{q="Por que Nimboya quer a cabeça?",a="Nimboya quer que a cabeça de Gan'zulah e a cabeça de Nezzliok sejam colocadas no Caldeirão borbulhante no Acampamento Grom'gol, na esperança de descobrir a verdade sobre Yennikan.",al={"por que a cabeça","o que nimboya quer","cabeça para nimboya"}},{q="Para que serve o caldeirão?",a="Os Lançanegra colocam as cabeças de Gan'zulah e Nezzliok no caldeirão, na esperança de fazer os líderes mortos falarem sobre Yennikan.",al={"caldeirão borbulhante","caldeirão em grom'gol","para que serve o caldeirão"}},{q="Quem é Yennikan?",a="Yennikan é um troll Lançanegra cujo destino continua desconhecido para Nimboya e seu povo.",al={"yennikan","onde está yennikan","hunt for yenniku"}}},fp="16,150,14.262.0,18.95.0,38.89.0,31.146.0,25.125.1,15.82.0"}
P.entries["item:gargantuan-tumor"] = {n="Tumor Gigantesco",s="O Tumor Gigantesco é uma excrescência enorme e doentia arrancada do lenhatexto corrompido Carrancarvalho em Teldrassil. Ele serve como prova evidente da enfermidade antinatural que se espalha pelas criaturas que habitam o Lago Al'Ameth.",h="O Tumor Gigantesco é uma excrescência enorme e doentia arrancada do lenhatexto corrompido Carrancarvalho em...",kw={"corrupção","tumor gigantesco","lago al'ameth","carrancarvalho","teldrassil","lenhatexto"},ang={["class:Druid"]="Para os druidas que se esforçam para nutrir os galhos recém-formados de Teldrassil, o tumor grotesco é um lembrete alarmante de que a natureza no interior da copa é perigosamente vulnerável à corrupção.",["race:NightElf"]="Ver um respeitado ancião dos lenhatextos reduzido a um monstro enlouquecido e empesteado ressalta os crescentes problemas ambientais que assolam o novo lar dos kaldorei."},sec={{t="Praga Sobre o Lago",b="Perto da margem sul do Lago Al'Ameth, uma caverna abriga Carrancarvalho, outrora um nobre ancião dos lenhatextos que foi vítima de uma aflição vil. A criatura foi visivelmente envenenada por uma excrescência colossal que distorceu seu comportamento e espalhou mácula pela vida selvagem ao redor. Extirpar esse tumor grotesco é crucial não apenas para pôr fim ao massacre atormentado da fera, mas para permitir que pesquisadores locais inspecionem a praga e compreendam como uma enfermidade tão repugnante criou raízes nos galhos da recém-brotada Árvore do Mundo."}},faq={{q="De onde vem o Tumor Gigantesco?",a="O tumor é obtido de Carrancarvalho, um grande lenhatexto corrompido que habita uma caverna na margem sul do Lago Al'Ameth, em Teldrassil.",al={"origem do tumor","como obter tumor gigantesco","saque de carrancarvalho"}},{q="O que está fazendo o tumor crescer em Carrancarvalho?",a="Trata-se de um sintoma visível da estranha corrupção que envenena os lenhatextos e a fauna ao redor do Lago Al'Ameth. Carrancarvalho já foi um líder imponente de sua espécie, mas sucumbiu completamente a esse crescimento virulento.",al={"por que carrancarvalho tem um tumor","doença dos lenhatextos","corrupção do lago al'ameth"}},{q="Quem quer estudar esse tumor?",a="Investigadores da região precisam do tumor para pesquisar a estranha podridão que aflige os lenhatextos locais, na esperança de descobrir como tratar ou deter a praga.",al={"quem fica com o tumor","entregar tumor gigantesco","entregar missão de carrancarvalho"}}},fx={b9b4574c={q="O que é o Tumor Gigantesco?",a="É um crescimento massivo e grotesco cortado de Oakenscowl, um ancião timberling corrompido que espreita em uma caverna ao longo da margem sul do Lago Al'Ameth. O tumor está visivelmente envenenando a criatura e enlouquecendo-a, alimentando a propagação de podridão antinatural e aflições pelas águas locais e pela vida selvagem próxima.",al={"o que é o tumor gigantesco","tumor gigantesco","tumor de oakenscowl"}}},fp="16,140,20.455.0,42.131.0,48.171.0,30.121.0"}
P.entries["item:garrick-s-head"] = {n="Cabeça do Garrick",s="A Cabeça do Garrick é a cabeça decepada de Garrick Padfoot, um assassino infame que atuava perto dos vinhedos do Vale de Vila Norte. Ela serve como uma prova macabra de morte para reivindicar uma recompensa emitida pelas autoridades da Abadia de Vila Norte.",h="A Cabeça do Garrick é a cabeça decepada de Garrick Padfoot, um assassino infame que atuava perto dos vinhedos...",kw={"recompensa","cabo vilém","floresta de elwynn","garrick padfoot","cabeça do garrick","abadia de vila norte","vale de vila norte"},ang={["class:Rogue"]="Eliminar Padfoot demonstra aos baderneiros locais que o banditismo indisciplinado não ficará sem resposta diante de lâminas mais letais e profissionais.",["race:Human"]="Pegar a cabeça de Padfoot marca um dos primeiros golpes decisivos que um jovem recruta de Ventobravo desfere contra a ilegalidade que avança pela Floresta de Elwynn."},sec={{t="O Fim de um Bandido",b="Por semanas, Garrick Padfoot e seu bando de capangas atormentaram fazendeiros e mercadores locais pelo Vale de Vila Norte. Aproveitando-se das defesas sobrecarregadas do Reino de Ventobravo, Garrick se escondeu em um casebre perto dos vinhedos de Vila Norte, saqueando o comércio que passava. Com os guardas locais contidos pelo avanço dos kobolds e dos bandidos Defias, o Cabo Vilém ofereceu uma recompensa pela cabeça de Padfoot, procurando um aventureiro destemido para eliminar o fora da lei e apresentar provas irrefutáveis de sua morte."}},faq={{q="Quem foi Garrick Padfoot?",a="Garrick Padfoot foi um assassino cruel que aterrorizou os fazendeiros, os vinhedos e os mercadores viajantes do Vale de Vila Norte. Ele estabeleceu um pequeno posto avançado com um grupo de capangas a leste da Abadia de Vila Norte, do outro lado do rio.",al={"quem é garrick","história de garrick padfoot","quem foi padfoot"}},{q="Por que uma cabeça decepada é necessária para receber a recompensa?",a="A justiça de fronteira na Floresta de Elwynn exige provas irrefutáveis. O Cabo Vilém e as autoridades de Vila Norte requerem evidências tangíveis da morte de Garrick antes de realizarem o pagamento da recompensa.",al={"por que a cabeça dele","prova de morte","por que pegar a cabeça do garrick"}},{q="Onde Garrick Padfoot estava escondido?",a="Padfoot estabeleceu um acampamento em um pequeno casebre de madeira localizado a leste da Abadia de Vila Norte, atravessando a ponte sobre o rio perto dos vinhedos de Vila Norte.",al={"onde está garrick","localização do casebre de garrick","onde encontrar garrick padfoot"}},{q="Quem paga a recompensa pela cabeça de Garrick?",a="O Cabo Vilém, posicionado logo do lado de fora da entrada da Abadia de Vila Norte, anunciou a recompensa e a paga ao receber a cabeça.",al={"quem quer a cabeça do garrick","entregar a cabeça do garrick","quem entregou a cabeça do garrick"}}},fx={cb1a40d1={q="O que é a Cabeça do Garrick?",a="Esta cabeça decepada é a prova horripilante do fim de Garrick Padfoot, um notório degolador que aterrorizou agricultores e comerciantes locais por todo o Vale de Vila Norte. Trazer este troféu de volta para a Abadia confirma que seu bando de bandidos perdeu seu líder.",al={"o que é a cabeça do garrick","item cabeça do garrick","a quem pertence esta cabeça"}},["79b2de99"]={q="De onde vem a Cabeça do Garrick?",a="Ela é reivindicada diretamente do próprio Garrick Padfoot. O ladino fez seu acampamento em um pequeno barraco aninhado perto dos Vinhedos de Vila Norte, do outro lado do rio a leste, cercado por capangas leais protegendo seus espólios.",al={"onde conseguir a cabeça do garrick","quem deixa cair a cabeça do garrick","fonte da cabeça do garrick"}}},fp="14,162,14.369.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="Livro-caixa do Gasganete",s="O Livro-caixa do Gasganete é um registro detalhado de mercadorias e inventários mantido pelo chefe goblin de Vila Catraca. Ele serve como um livro de contabilidade para verificar os carregamentos de carga que chegam de Angra do Butim em relação ao manifesto do porto.",h="O Livro-caixa do Gasganete é um registro detalhado de mercadorias e inventários mantido pelo chefe goblin de...",kw={"angra do butim","dizzywig","freebooters","gasganete","livro-caixa","vila catraca","carregamento","steamwheedle"},ang={["class:Rogue"]="O livro-caixa comercial privado de um chefe goblin oferece um olhar interessante sobre o fluxo de contrabando, importações valiosas e pirataria ao redor da costa dos Sertões.",["faction:Horde"]="Vila Catraca opera como um porto neutro que recebe o comércio da Horda; ajudar Gasganete a rastrear carregamentos roubados mantém o bom relacionamento com as autoridades locais da Steamwheedle."},sec={{t="Registros Comerciais de Vila Catraca",b="Supervisionar um porto comercial movimentado como Vila Catraca exige uma contabilidade meticulosa. Gasganete mantém este livro-caixa pessoal para rastrear caixotes importados, cargas enviadas e estoques de armazém. Quando um carregamento muito aguardado de Angra do Butim não é contabilizado, Gasganete usa o livro para cruzar seu inventário projetado com os registros marítimos mantidos nas docas pelo Wharfmaster Dizzywig."},{t="Descobrindo o Roubo",b="Ao comparar as entradas do livro-caixa diretamente com os registros do porto de Dizzywig, os goblins confirmam que a carga nunca chegou ao armazém do porto. A discrepância confirma as suspeitas de Gasganete de que os caixotes desaparecidos nunca saíram da água intactos, apontando o dedo diretamente para os Southsea Freebooters que operam ao longo da vizinha Costa dos Mercadores."}},faq={{q="O que é o Livro-caixa do Gasganete?",a="É o livro de inventário pessoal do Gasganete, contendo registros de mercadorias esperadas e armazenadas em Vila Catraca. Gasganete o envia para as docas para conferir com os registros do cais quando carregamentos recebidos estão faltando.",al={"livro-caixa do gasganete","livro-caixa de vila catraca","livro de inventário do gasganete"}},{q="Quem precisa inspecionar o livro-caixa?",a="Wharfmaster Dizzywig, que supervisiona as docas de Vila Catraca, revisa o livro-caixa com seus próprios registros de navegação para determinar se a mercadoria perdida foi extraviada ou nunca descarregada.",al={"para quem devo levar o livro-caixa","destinatário do livro-caixa","livro-caixa de dizzywig"}},{q="Que carga estava faltando no livro-caixa?",a="Gasganete aguardava seu último carregamento de mercadorias de Angra do Butim. Dizzywig não encontra nada de errado em seus próprios registros, embora mencione algumas mercadorias de Undermine esperando para serem buscadas por Gasganete.",al={"o que o gasganete perdeu","carga de carregamento perdida"}},{q="O que acontece depois que o livro-caixa é verificado?",a="Uma vez que Dizzywig verifica que o carregamento nunca passou pelas docas, o livro-caixa é devolvido ao Gasganete, confirmando que piratas Southsea Freebooters provavelmente interceptaram a carga no mar.",al={"o que acontece com o livro-caixa","depois que o dizzywig confere"}}},fx={d44950a4={q="De onde vem o Livro-caixa do Gasganete e quem o guarda?",a="Este livro-caixa pertence a Gasganete, o chefe goblin que supervisiona a cidade portuária de Vila Catraca. Ele serve como seu registro de inventário pessoal, documentando a carga que entra e sai e que é enviada através d'O Grande Oceano entre Vila Catraca e outros centros comerciais goblin, como Angra do Butim.",al={"quem fez o livro-caixa do gasganete","de onde vem o livro-caixa do gasganete","origem do livro-caixa do gasganete"}},c4547cde={q="Por que o Livro-caixa do Gasganete é necessário agora?",a="Gasganete suspeita que uma remessa muito atrasada vinda de Angra do Butim foi roubada pelos Southsea Freebooters. Antes de tirar conclusões precipitadas, ele precisa que você leve seu livro-caixa até o Wharfmaster Dizzywig nas docas para comparar os registros de inventário com os registros do porto e descartar um erro administrativo.",al={"por que querer o livro-caixa do gasganete","por que precisar do livro-caixa do gasganete","para que serve o livro-caixa do gasganete"}}},fp="16,103,28.271.0,20.278.1,25.169.0,32.170.0,37.165.0,41.193.1"}
P.entries["item:gem-of-anacondra"] = {n="Gema de Sucurina",s="A Gema de Sucurina é uma das quatro gemas oníricas em posse dos líderes serpentinos corrompidos na Caverna Ululante. Carregada por Lady Sucurina, ela serve como prova tangível de sua derrota e da contenção da expansão do Pesadelo pelos Sertões.",h="A Gema de Sucurina é uma das quatro gemas oníricas em posse dos líderes serpentinos corrompidos na Caverna...",kw={"gema onirica","druids of the fang","gema de sucurina","lady sucurina","líderes da presa","nara juba agreste","caverna ululante"},ang={["class:Druid"]="Para os druidas cenarianos, recuperar esta gema é um dever solene para abater uma irmã que entregou sua mente e suas formas à corrupção do Pesadelo Esmeralda.",["race:Tauren"]="Recuperar a gema ajuda diretamente Nara Juba Agreste de Penhasco do Trovão, dissipando as visões sombrias que atormentam o sono dos Shu'halo no Platô dos Anciãos."},sec={{t="Um Foco Corrompido",b="Quando Naralex entrou em seu sono profundo para trazer água e vida de volta aos áridos Sertões, o Pesadelo Esmeralda invadiu seus pensamentos e deformou seus discípulos mais próximos. Lady Sucurina e seus companheiros conspiradores abandonaram seus costumes tradicionais para se tornarem os Druids of the Fang, distorcendo seu nobre propósito restaurador em um delírio tóxico. A Gema de Sucurina é uma das quatro gemas oníricas carregadas por esses líderes serpentinos, canalizando seu elo corrompido com o Sonho Esmeralda e ancorando o pesadelo no sistema de cavernas."},{t="Purificando a Visão",b="Nara Juba Agreste e o círculo de druidas cenarianos em Penhasco do Trovão viram seu próprio sono ser atormentado por visões e rostos cruéis da liderança da Presa. Obter a Gema de Sucurina — junto às pedras de Cobrahn, Pythas e Serpentis — é necessário para certificar que Lady Sucurina foi derrotada, dissipando o pesadelo opressor da mente dos guardiões do equilíbrio de Kalimdor."}},faq={{q="O que é a Gema de Sucurina?",a="É uma gema onírica portada por Lady Sucurina, uma das quatro lideranças dos corrompidos Druids of the Fang que habitam a Caverna Ululante.",al={"o que e gema de sucurina","gema de sucurina","o que faz a gema de sucurina"}},{q="Quem deseja esta gema?",a="Nara Juba Agreste, uma druida tauren localizada no Platô dos Anciãos em Penhasco do Trovão, busca a gema junto com as outras três gemas oníricas para livrar sua mente de pesadelos e proteger os Sertões.",al={"quem quer a gema de sucurina","onde entregar gema de sucurina","entrega da gema de sucurina"}},{q="Onde a Gema de Sucurina pode ser encontrada?",a="A gema é portada por Lady Sucurina, que pode ser encontrada à espreita nos túneis subterrâneos e sinuosos da Caverna Ululante, na região central dos Sertões.",al={"onde cai","quem saqueia gema de sucurina","localizacao de lady sucurina"}},{q="Por que as gemas oníricas são importantes?",a="As quatro gemas estão em posse dos líderes corrompidos dos Druids of the Fang. Reuni-las confirma que os líderes foram eliminados, quebrando o domínio deles sobre a corrupção do Sonho Esmeralda na região.",al={"por que quatro gemas","proposito das gemas oniricas","gemas dos lideres da presa"}}},fx={["2e0de493"]={q="De onde vem a Gema de Sucurina e quem a criou?",a="A gema é carregada por Lady Sucurina nas profundezas da Caverna Ululante. Embora o mestre exato que a lapidou ou encantou seja desconhecido, ela serve como uma das gemas dos sonhos mantidas pelos quatro líderes dos Druidas da Presa. Outrora parte de um círculo nobre dedicado a curar os Sertões, esses elfos noturnos corrompidos agora canalizam suas visões distorcidas do Sonho Esmeralda para dentro dessas pedras.",al={"origem da gema de sucurina","quem fez a gema de sucurina","onde sucurina conseguiu sua gema"}}},fp="16,175,17.541.0,20.369.1,29.153.0,19.180.0,40.112.0,33.201.0"}
P.entries["item:gem-of-cobrahn"] = {n="Gema de Cobrahn",s="A Gema de Cobrahn é uma gema dos sonhos carregada pelo Lorde Cobrahn, um dos líderes corruptos dos Druids of the Fang dentro da Caverna Ululante. Ela serve tanto como foco de seu devaneio corrompido quanto como prova física necessária para Nara Wildmane confirmar sua derrota.",h="A Gema de Cobrahn é uma gema dos sonhos carregada pelo Lorde Cobrahn, um dos líderes corruptos dos Druids of...",kw={"gema dos sonhos","druids of the fang","gema de cobrahn","leaders of the fang","lorde cobrahn","nara wildmane","caverna ululante"},ang={["class:Druid"]="Para os druidas Cenarianos, recuperar a Gema de Cobrahn marca o fim trágico, mas necessário, de um irmão caído que abandonou a harmonia da natureza pelo Emerald Nightmare.",["race:Tauren"]="Os druidas do Penhasco do Trovão vigiam os Sertões de perto; pegar a gema de Cobrahn protege diretamente as planícies e as terras de caça contra a corrupção não natural."},sec={{t="Um Foco de Sonhos Corrompidos",b="Quando o druida elfo noturno Naralex entrou no Sonho Esmeralda para restaurar as planícies áridas de Kalimdor, seu pesadelo distorceu tanto a Caverna Ululante quanto seus discípulos. Entre eles estava Cobrahn, que abandonou os caminhos pacíficos do Círculo Cenariano para assumir a forma da serpente. O Lorde Cobrahn carrega uma das quatro gemas dos sonhos que ancoram o domínio dos líderes sobre os cursos d'água subterrâneos, usando-a para canalizar os sonhos distorcidos que ameaçam transformar os Sertões em um pântano venenoso."},{t="Restaurando o Equilíbrio",b="No Penhasco do Trovão, a druida tauren Nara Wildmane é atormentada por pesadelos enviados pelos ladinos Druids of the Fang. Para purificar as fontes subterrâneas e proteger Kalimdor de sua visão, os aventureiros devem entrar nas cavernas, matar o Lorde Cobrahn ao lado de seus três conspiradores e recuperar suas gemas dos sonhos. Devolver a gema de Cobrahn aos druidas Cenarianos põe fim à sua influência corruptora sobre o adormecido Naralex."}},faq={{q="O que é a Gema de Cobrahn?",a="É uma gema dos sonhos guardada pelo Lorde Cobrahn, um druida caído que lidera os Druids of the Fang dentro da Caverna Ululante. Ela atua como um condutor para seus poderes distorcidos por pesadelos.",al={"gema de cobrahn","o que é a gema de cobrahn"}},{q="Quem quer a Gema de Cobrahn?",a="Nara Wildmane, uma druida tauren localizada no Platô dos Anciãos no Penhasco do Trovão, pede a gema junto com outras três para dar um fim aos Druids of the Fang.",al={"quem precisa da gema de cobrahn","entrega da gema de cobrahn","quem recebe a gema de cobrahn"}},{q="Quantas gemas são necessárias para completar a missão?",a="São necessárias quatro gemas: a Gema de Cobrahn, a Gema de Sucurina, a Gema de Pítias e a Gema de Serpentis, cada uma em posse de um dos quatro líderes serpentes nas cavernas.",al={"quantas gemas dos sonhos","gemas de leaders of the fang","todas as gemas fang"}},{q="Quem é o Lorde Cobrahn?",a="O Lorde Cobrahn já foi um discípulo de Naralex. Quando a visão de Naralex se transformou em um pesadelo, Cobrahn e vários outros druidas abraçaram a forma da serpente e formaram os Druids of the Fang.",al={"quem é cobrahn","história do lorde cobrahn","cobrahn"}}},fp="14,123,27.439.0,17.357.1,27.116.0,29.138.0,47.172.0,20.172.0"}
P.entries["item:gem-of-pythas"] = {n="Gema de Pítias",s="A Gema de Pítias é uma das quatro gemas oníricas corrompidas carregadas pelos líderes dos Druids of the Fang dentro da Caverna Ululante. Portada pelo Lorde Pítias, ela alimenta o pesadelo que distorce o oásis subterrâneo e ameaça os Sertões.",h="A Gema de Pítias é uma das quatro gemas oníricas corrompidas carregadas pelos líderes dos Druids of the Fang...",kw={"sertoes","gema onirica","druids of the fang","gema de pítias","lorde pítias","nara juba agreste","caverna ululante"},ang={["class:Druid"]="Para os druidas Cenarianos, recuperar a gema é um dever sombrio, pois ela representa a total degradação do círculo íntimo de Naralex em horrores serpentinos.",["race:Tauren"]="Os rituais distorcidos nas cavernas ameaçam o frágil equilíbrio dos Sertões, tornando a recuperação dessas gemas crucial para proteger o lar dos xamãs e druidas."},sec={{t="Um Receptáculo do Pesadelo",b="Quando Naralex adentrou o Sonho Esmeralda para restaurar os áridos Sertões, sua nobre visão foi distorcida em um pesadelo vivo. Seus principais seguidores sucumbiram com ele, autodenominando-se Druids of the Fang e buscando transformar a superfície em uma selva venenosa. Lorde Pítias carrega esta pedra ressonante, uma das quatro gemas oníricas que ancoram a corrupção dentro das cavernas. A gema serve como canal para seus planos sombrios e como prova aos druidas do Penhasco do Trovão de que o transe distorcido de Pítias foi finalmente quebrado."}},faq={{q="Para que serve a Gema de Pítias?",a="A gema é levada para Nara Juba Agreste no Penhasco do Trovão junto com as gemas de Cobrahn, Sucurina e Serpentis. Juntas, elas concluem a tarefa de dar um fim aos líderes renegados dos Druids of the Fang.",al={"uso da gema de pítias","o que fazer com a gema de pítias","missao gema de pitias"}},{q="Quem carrega esta gema?",a="Ela é portada pelo Lorde Pítias, um druida Elfo Noturno corrompido que habita as profundezas da Caverna Ululante nos Sertões.",al={"quem saqueia gema de pitias","localizacao de pitias","onde conseguir a gema de pitias"}},{q="Por que os druidas do Penhasco do Trovão querem a gema?",a="Nara Juba Agreste e os druidas Cenarianos no Penhasco do Trovão são atormentados pela corrupção que emana da Caverna Ululante. Obter as gemas prova que os quatro líderes aberrantes foram eliminados, impedindo que o pesadelo continue se espalhando pelos Sertões.",al={"por que nara quer gemas","nara juba agreste pitias"}},{q="Existem outras gemas como esta?",a="Sim. Lorde Pítias é um dos quatro líderes. Os outros — Lady Sucurina, Lorde Cobrahn e Lorde Serpentis — carregam, cada um, sua própria gema onírica nas profundezas da caverna.",al={"outras gemas oniricas","gemas presas","gemas da caverna ululante"}}},fx={["3d8d64d3"]={q="O que é a Gema de Pítias?",a="A Gema de Pítias é uma das quatro gemas dos sonhos carregadas pelos líderes dos Druidas da Presa dentro da Caverna Ululante. Mantida por Lorde Pítias, esta relíquia personifica a loucura sombria e serpentina que corrompeu esses elfos noturnos antes nobres, prendendo suas visões distorcidas do Sonho Esmeralda em forma física.",al={"gema de pítias","o que é a gema de pítias","o que é esta gema"}}},fp="13,170,25.468.0,35.195.0,21.114.0,48.234.0,35.134.0"}
P.entries["item:gem-of-serpentis"] = {n="Gema de Serpentis",s="A Gema de Serpentis é uma gema do sonho portada por Lorde Serpentis, um dos quatro líderes dos Druids of the Fang na Caverna Ululante. Ela age como um conduto focal para o pesadelo distorcido que remodela a rede de cavernas e ameaça os Sertões.",h="A Gema de Serpentis é uma gema do sonho portada por Lorde Serpentis, um dos quatro líderes dos Druids of the...",kw={"druids of the fang","gema de serpentis","leaders of the fang","lorde serpentis","nara wildmane","sertões","caverna ululante"},ang={["class:Druid"]="As gemas do sonho carregadas por Serpentis e seu conluio representam o terrível risco de entrar em comunhão de transe profundo com o Sonho sem uma vigilante disciplina espiritual.",["race:Tauren"]="Cortar o domínio de Serpentis sobre esta gema ajuda a libertar os xamãs e druidas do Penhasco do Trovão das visões sombrias que perturbam seu sono por toda Mulgore."},sec={{t="Coração do Sonho Serpentino",b="Quando o sono de Naralex dentro da Caverna Ululante sucumbiu ao Pesadelo Esmeralda, seus seguidores mais devotos foram deformados nos fanáticos Druids of the Fang. Lorde Serpentis é um dos quatro líderes do conluio. Assim como os outros três, Serpentis carrega uma gema do sonho encantada que ancora a vontade coletiva deles à visão corrompida. Recuperar esta gema quebra o controle de Serpentis sobre o ecossistema da caverna, atingindo diretamente a liderança que direciona a corrupção que se espalha pelos Sertões."},{t="Prova para o Penhasco do Trovão",b="Os druidas taurens no topo do Platô dos Anciãos do Penhasco do Trovão, particularmente Nara Wildmane, enfrentam pesadelos vívidos causados pela corrupção à espreita sob a savana. Recuperar a Gema de Serpentis junto com as de Cobrahn, Anacondra e Pythas fornece uma prova tangível de que os líderes da ordem renegada caíram, aliviando o domínio do pesadelo sobre o Círculo Cenariano em Mulgore."}},faq={{q="De onde vem a Gema de Serpentis?",a="A gema é portada por Lorde Serpentis, um dos quatro líderes dos Druids of the Fang, que reside nas profundezas dos canais sinuosos da Caverna Ululante.",al={"quem dropa gema de serpentis","onde conseguir gema de serpentis","localização da gema de serpentis"}},{q="Qual é o propósito da gema?",a="Ela serve como uma das quatro gemas de foco usadas pelos líderes dos Druids of the Fang para canalizar o pesadelo que distorce o oásis subterrâneo. Nara Wildmane, no Penhasco do Trovão, a busca como prova de que Lorde Serpentis foi derrotado.",al={"por que preciso de gema de serpentis","para que serve a gema de serpentis"}},{q="Quem quer todas as quatro gemas do sonho?",a="Nara Wildmane, uma druida posicionada no Platô dos Anciãos no Penhasco do Trovão, pede aos aventureiros que tragam a ela as gemas de Cobrahn, Anacondra, Pythas e Serpentis para cortar o domínio do pesadelo sobre a região.",al={"quem recebe as gemas","entregar gema de serpentis","entregar leaders of the fang"}},{q="Quem era Lorde Serpentis antes de carregar esta gema?",a="Ele era originalmente um discípulo de Naralex que entrou nas cavernas com a intenção de restaurar a vida exuberante nos Sertões, mas o Pesadelo Esmeralda distorceu suas nobres aspirações em um desejo fanático de remodelar o mundo em forma de serpente.",al={"história de lorde serpentis","quem é serpentis"}}},fx={["58ca37b7"]={q="O que é a Gema de Serpentis?",a="A Gema de Serpentis é uma das quatro gemas dos sonhos mantidas pelos líderes dos Druidas da Presa dentro da Caverna Ululante. Carregada pelo próprio Lorde Serpentis, ela serve como um emblema e instrumento dos druidas corrompidos que buscam distorcer os Sertões para corresponder às suas visões sombrias.",al={"lore da gema de serpentis","o que é a gema de serpentis","gema do lorde serpentis"}}},fp="16,191,29.465.0,23.330.1,42.139.0,31.209.0,30.208.0,48.207.0"}
P.entries["item:gem-of-the-serpent"] = {n="Gema da Serpente"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="Braço Mecânico do Hanfritz",s="O Braço Mecânico do Hanfritz é o membro protético enxertado retirado do engenheiro renegado Hanfritz Schaventorck na Cordilheira das Torres de Pedra. Ele serve como prova irrefutável de sua morte para agentes goblins que buscam eliminar a concorrência.",h="O Braço Mecânico do Hanfritz é o membro protético enxertado retirado do engenheiro renegado Hanfritz...",kw={"braco","lago do rochedo","hanfritz","braco mecanico","cobogó","cordilheira das torres de pedra","schaventorck","zé fízzica"},ang={["profession:Engineering"]="O braço ilustra as mentalidades contrastantes das duas tradições de engenharia: gnomos sacrificam de bom grado a própria biologia pela precisão mecânica, enquanto goblins preferem adições externas e poder de fogo bruto.",["race:Gnome"]="Hanfritz representa um extremo sombrio da engenhosidade gnômica, levando a substituição mecânica muito além das próteses médicas convencionais para um aprimoramento próprio mórbido."},sec={{t="Uma Invenção Bizarra",b="Hanfritz Schaventorck levou a automodificação a um extremo grotesco, enxertando engrenagens zumbidoras e metal diretamente em seu corpo debilitado. Empoleirado acima do Lago do Rochedo, o gnomo renegado substituiu membros naturais por maquinário intrincado. Quando o engenhoqueiro goblin Zé Fízzica busca a eliminação de Hanfritz para impressionar seus superiores, este distinto braço mecânico é o único troféu exclusivo o suficiente para servir como evidência incontestável da morte do engenheiro."},{t="Filosofia Gnômica, Crítica Goblin",b="Para a mente goblin, amputar um braço em perfeito funcionamento simplesmente para anexar um substituto mecânico faz pouco sentido. Zé Fízzica comentou de forma famosa que um engenheiro goblin adequado simplesmente manteria ambos os braços biológicos e montaria um terceiro braço mecânico. Apesar da divergência filosófica, entregar o membro decepado satisfaz Cobogó e ajuda Zé a solicitar uma transferência para Geringontzan ou Undermine."}},faq={{q="De onde vem o Braço Mecânico do Hanfritz?",a="Ele é obtido de Hanfritz Schaventorck, que supervisiona operações de extração de madeira e engenharia bem acima do Lago do Rochedo, perto da roda-d'água na Cordilheira das Torres de Pedra.",al={"quem dropa braço do hanfritz","localizacao braco hanfritz","onde conseguir braco mecanico do hanfritz"}},{q="Por que Zé Fízzica quer este braço?",a="Zé precisa de uma prova definitiva para seu superior, Cobogó, de que Hanfritz está morto. Como Hanfritz alterou pesadamente o próprio corpo, seu braço protético exclusivo é impossível de falsificar ou confundir com o de qualquer outra pessoa.",al={"por que ze quer braco","onde entregar missao do braco","prova da morte de hanfritz"}},{q="Por que Hanfritz substituiu o próprio braço?",a="De acordo com Zé Fízzica, a carne de Hanfritz parecia estar apodrecendo. Movido pelo desespero ou por uma experimentação gnômica obsessiva, Hanfritz enxertou maquinários e substituiu seus membros debilitados por equivalentes mecânicos.",al={"por que hanfritz e um ciborgue","carne apodrecida de hanfritz","por que braco mecanico"}}},fx={["379afa91"]={q="O que é o Braço Mecânico do Hanfritz?",a="É a prótese cibernética bruta enxertada diretamente no corpo de Gerenzo Wrenchwhistle, um capataz gnomo doente que espreita perto da roda d'água acima do Lago do Rochedo. Em vez de viver com carne natural, Gerenzo aumentou sua estrutura apodrecida com engrenagens de relojoaria e placas de metal, tornando este membro mecânico intrincado sua característica mais reconhecível.",al={"o que é o braço do gerenzo","item braço do gerenzo","braço mecânico do hanfritz"}}},fp="24,189,19.329.0,35.317.1,46.165.0,35.157.0,36.221.0"}
P.entries["item:ghost-hair-comb"] = {n="Pente de Fantasma",s="O Pente de Fantasma é uma ferramenta de cuidados pessoais sinistra, entrelaçada com os fios espectrais do espírito de Maria Cega. Enviado ao fantasma por Madame Eva, o pente se torna um instrumento de uma trágica constatação antes que os cabelos recolhidos sejam fiados em uma linha misteriosa.",h="O Pente de Fantasma é uma ferramenta de cuidados pessoais sinistra, entrelaçada com os fios espectrais do...",kw={"maria cega","vila sombria","floresta do crepúsculo","pente de fantasma","linha de cabelo de fantasma","madame eva"},ang={["class:Priest"]="A reação angustiada de Maria ao pente reflete a vaidade mortal remanescente e o profundo tormento espiritual comuns entre os mortos inquietos da Floresta do Crepúsculo.",["profession:Tailoring"]="Os fios etéreos retirados do pente representam um tecido sobrenatural, colhido não de ovelhas ou bichos-da-seda, mas fiado diretamente da tristeza espectral."},sec={{t="Uma Vaidade Trágica",b="Madame Eva de Vila Sombria envia o pente ao espírito atormentado de Maria Cega, que reside em uma moradia solitária e decadente nos arredores da Floresta do Crepúsculo. Ao ser apresentada ao pente, o fantasma recua em puro horror, confrontada de repente com a terrível realidade de que não é mais a bela mulher viva de outrora. Em sua dor e aflição, Maria empurra o pente para longe, deixando-o emaranhado com mechas de seu próprio cabelo fantasmagórico."},{t="Fiado da Tristeza",b="Devolvido a Madame Eva em Vila Sombria, o cabelo preso nos dentes do pente serve a um propósito muito mais esotérico. Eva recolhe as delicadas fibras espectrais para fiá-las e transformá-las em Linha de Cabelo de Fantasma, um material de criação místico usado para costurar e atar criações ocultas no reino sombrio da Floresta do Crepúsculo."}},faq={{q="O que é o Pente de Fantasma?",a="É um pente enviado por Madame Eva de Vila Sombria ao espírito de Maria Cega. Depois que Maria o usa ou o descarta, ele retém mechas de seu cabelo espectral, que Eva então transforma em Linha de Cabelo de Fantasma.",al={"pente de fantasma","o que e este pente","pente de eva"}},{q="Por que Maria Cega grita e rejeita o pente?",a="O pente lembra Maria Cega de sua beleza mortal perdida. Recebê-lo a força a encarar sua verdadeira natureza como uma monstruosidade espectral aterrorizante, em vez da mulher bela que lembra ter sido em vida.",al={"por que maria cega grita","reacao de maria cega ao pente","por que maria jogou o pente"}},{q="Quem precisa que o pente seja devolvido?",a="Madame Eva, a adivinha e maga informal residente na cidade de Vila Sombria, pede que o pente seja levado de volta a ela para que possa colher o cabelo de fantasma preso.",al={"quem quer o pente","onde levar o pente","devolver o pente para quem"}},{q="Para que serve o cabelo de fantasma?",a="Madame Eva fia as mechas fantasmagóricas recolhidas do pente para criar a Linha de Cabelo de Fantasma, um reagente incomum necessário para rituais ocultos e criações na Floresta do Crepúsculo.",al={"uso do cabelo de fantasma","o que e linha de cabelo de fantasma","proposito da linha de cabelo de fantasma"}}},fp="15,113,15.349.0,16.279.1,28.162.0,47.204.0,28.134.0,32.135.0"}
P.entries["item:ghost-hair-thread"] = {n="Linha de Cabelo de Fantasma",s="A Linha de Cabelo de Fantasma é um material raro e sobrenatural fiado pela Madame Eva em Vila Sombria. Infundida com propriedades ocultas potentes, diz-se que ela prende energias espirituais e pode até costurar vida em coisas inanimadas. O eremita Abercrombie a solicita para proteger seu barraco em ruínas contra fantasmas inquietos.",h="A Linha de Cabelo de Fantasma é um material raro e sobrenatural fiado pela Madame Eva em Vila Sombria.",kw={"abercrombie","vila sombria","floresta do crepúsculo","linha de cabelo de fantasma","madame eva","monte corvo","espíritos"},ang={["class:Warlock"]="A capacidade da linha de prender entidades espirituais e imbuir matéria inanimada com vida reflete as artes sombrias da manipulação de almas e da ligação de constructos.",["profession:Tailoring"]="Enquanto os alfaiates comuns trabalham com lã, seda e tecido mágico, a linha fantasmagórica de Madame Eva demonstra que o tecido pode ser fiado diretamente de essências sobrenaturais para conter encantamentos."},sec={{t="Fiado do Mundo Espiritual",b="Fiada pela cartomante Madame Eva em Vila Sombria, a Linha de Cabelo de Fantasma é muito mais do que um suprimento comum de alfaiataria. Segundo Eva, a linha espectral possui propriedades ocultas versáteis, que variam desde prender espíritos malévolos até costurar vitalidade em objetos inanimados. Sua natureza etérea a torna um recurso valioso para rituais e proteções no reino amaldiçoado da Floresta do Crepúsculo."},{t="A Proteção de Abercrombie",b="O eremita recluso Abercrombie, que habita um barraco em ruínas logo ao norte do Cemitério de Monte Corvo, pede aos viajantes que busquem a linha em Vila Sombria. Ele alega que precisa desesperadamente passar o fio pelas janelas e pela moldura da porta para impedir que os mortos-vivos errantes do cemitério invadam sua casa. Contudo, dada a estranha habilidade da linha de costurar vida em matéria inanimada, seu verdadeiro propósito permanece um mistério perturbador."}},faq={{q="O que é a Linha de Cabelo de Fantasma?",a="É um material de criação arcano fiado pela Madame Eva em Vila Sombria. Ela possui propriedades ocultas distintas capazes de prender espíritos ou costurar vida em coisas inanimadas.",al={"cabelo de fantasma","o que é linha de cabelo de fantasma","linha fantasma"}},{q="Por que Abercrombie quer a Linha de Cabelo de Fantasma?",a="Abercrombie alega que precisa da linha para forrar suas janelas e porta, criando uma barreira protetora para afastar os espíritos inquietos que vagam do lado de fora perto do Cemitério de Monte Corvo.",al={"linha do abercrombie","por que abercrombie quer a linha","proteção de abercrombie"}},{q="Quem faz a linha?",a="Madame Eva, a adivinha e cartomante residente de Vila Sombria, fabrica e fornece a linha sob encomenda.",al={"quem fia a linha de cabelo de fantasma","linha da madame eva"}},{q="Jogadores podem usar a linha para alfaiataria?",a="Não. Apesar do nome e dos traços mágicos, este é um item de missão especializado destinado estritamente à entrega para Abercrombie e não pode ser usado em receitas de criação padrão.",al={"alfaiataria com linha de cabelo de fantasma","posso criar itens com a linha de cabelo de fantasma"}}},fp="17,214,24.220.0,18.290.1,26.120.0,44.129.0,21.86.0,41.96.0"}
P.entries["item:ghost-o-plasm"] = {n="Ghost-o-Plasm",s="Ghost-o-Plasm é energia fantasmagórica coletada dos Magrami Spectres em Desolação. Guido Guacamole espera vendê-la aos centauros Magram.",h="Ghost-o-Plasm é energia fantasmagórica coletada dos Magrami Spectres em Desolação.",kw={"energia fantasmagórica","ghost-o-plasm","ghostoplasm","guido guacamole","ímã","centauros magram","magrami spectres","vale dos ossos"},ang={["faction:Horde"]="Como integrante da Horda, você está ajudando Guido a negociar com os centauros Magram por meio de uma troca estranha envolvendo energia fantasmagórica.",["race:Gnome"]="Como gnomo, você talvez reconheça os ímãs fantasmagóricos de Guido como dispositivos engenhosos, embora o plano dele dependa do quanto os centauros Magram pagarão."},sec={{t="Coletado no vale",b="Entre os dois grandes esqueletos chamados Dead Goliaths, uma caixa de ímãs fantasmagóricos atrai Magrami Spectres do Vale dos Ossos. O Ghost-o-Plasm deles é o que Guido Guacamole quer. Ele espera que os centauros Magram paguem bem por ele, embora ainda precise convencê-los do que é essa substância estranha."}},faq={{q="O que é Ghost-o-Plasm?",a="Ghost-o-Plasm é energia fantasmagórica extraída de Magrami Spectres em Desolação.",al={"ghost-o-plasm","coisa fantasmagórica","o que é essa gosma"}},{q="Onde encontro Ghost-o-Plasm?",a="Magrami Spectres no Vale dos Ossos fornecem Ghost-o-Plasm quando atraídos por uma caixa de ímãs fantasmagóricos.",al={"onde encontrar ghost-o-plasm","obter ghost-o-plasm","localização da coisa fantasmagórica"}},{q="Quem quer Ghost-o-Plasm?",a="Guido Guacamole quer Ghost-o-Plasm, na esperança de vendê-lo aos centauros Magram.",al={"quem precisa de ghost-o-plasm","coisa do guido","vender energia fantasmagórica"}},{q="Por que Guido quer isso?",a="Guido acredita que os centauros Magram pagarão bem pela energia fantasmagórica capturada.",al={"por que guido quer isso","por que coletar coisa fantasmagórica","energia fantasmagórica dos centauros"}}},fp="13,135,22.304.0,22.72.0,30.99.0,24.81.0,25.77.0"}
P.entries["item:ghoul-fang"] = {n="Presa de Carniçal",s="Presas de Carniçal são troféus grotescos colhidos dos mortos-vivos que rondam os bosques arruinados e cemitérios da Floresta do Crepúsculo. Em Vila Sombria, a vidente Madame Eva os utiliza como componentes essenciais na criação de talismãs defensivos para viajantes que enfrentam a escuridão que avança.",h="Presas de Carniçal são troféus grotescos colhidos dos mortos-vivos que rondam os bosques arruinados e...",kw={"vila sombria","floresta do crepúsculo","presa de carniçal","carniçais","madame eva","totem do castigo","morto-vivo"},ang={["faction:Alliance"]="Para os aventureiros da Aliança que ajudam a cidade sitiada de Vila Sombria, recolher essas presas ajuda a transformar os horrores da Floresta do Crepúsculo em ferramentas de sobrevivência contra a mácula invasora que se assemelha ao Flagelo."},sec={{t="Troféus dos Mortos Inquietos",b="A floresta sombria da Floresta do Crepúsculo rasteja com mortos-vivos vorazes, desde comedores de carne à espreita perto das sepulturas até cadáveres apodrecidos que vagam pelos bosques. Arrancar uma presa dessas criaturas monstruosas é tanto um trabalho sombrio quanto uma prova de sobrevivência contra os mortos esfomeados que ameaçam as fronteiras de Vila Sombria."},{t="Reagentes Ocultistas",b="Madame Eva, a cartomante e mística residente em Vila Sombria, enxerga presságios terríveis pairando sobre os viajantes que ousam atravessar a Floresta do Crepúsculo. Ela vincula a essência necrótica latente das presas de carniçal com dedos esqueléticos e veneno de aracnídeos para encantar o Totem do Castigo, transformando as forças sombrias da floresta em um amuleto protetor contra ataques violentos."}},faq={{q="Onde Presas de Carniçal podem ser encontradas?",a="Elas são obtidas de vários tipos de carniçais por toda a Floresta do Crepúsculo, incluindo Plague Spreaders, Brain Eaters, Bone Chewers, Fetid Corpses, Rotted Ones e Flesh Eaters encontrados assombrando cemitérios e caminhos ermos.",al={"onde caem presas de carniçal","quem derruba presas de carniçal","localização da presa de carniçal"}},{q="Quem quer Presas de Carniçal?",a="Madame Eva, a mística que reside em Vila Sombria, precisa delas como parte de um ritual para criar um amuleto defensivo conhecido como Totem do Castigo.",al={"quem precisa de presas de carniçal","entrega de presas de carniçal","missão de madame eva"}},{q="Por que Madame Eva precisa delas?",a="Eva pressente o perigo iminente para os viajantes e usa as presas junto com dedos de esqueleto e veneno de aranha para encantar um totem protetor que pune aqueles que golpeiam o portador.",al={"por que presas de carniçal","materiais do totem do castigo","o que madame eva faz com as presas"}}},fx={["7c703fef"]={q="O que é uma Presa de Carniçal?",a="Uma Presa de Carniçal é um dente afiado arrancado da bocarra dos carniçais mortos-vivos que assombram a Floresta do Crepúsculo. Manchadas pela praga necromântica e pela fome devoradora de carne, essas presas retêm um vestígio da magia sombria que anima os mortos-vivos, tornando-as reagentes potentes para amuletos de proteção e rituais ocultos.",al={"o que é uma presa de carniçal","lore de presa de carniçal","sobre presa de carniçal"}},["87f3f6fc"]={q="De onde vem uma Presa de Carniçal?",a="Essas presas vêm dos vários carniçais mortos-vivos que vagam pelas sombras da Floresta do Crepúsculo, como Espalhadores de Praga, Devoradores de Cérebro, Roedores de Osso e Devoradores de Carne. Elas não são fabricadas à mão, mas sim retiradas diretamente das mandíbulas dos mortos que vagam.",al={"origem da presa de carniçal","de onde vêm as presas de carniçal","quem deixa cair presas de carniçal"}}},fp="10,182,29.255.0,15.302.0,31.170.0,22.98.0,30.189.0"}
P.entries["item:ghoul-rib"] = {n="Costela de Carniçal",s="Costelas de Carniçal são obtidas dos mortos-vivos que rondam os bosques e cemitérios assombrados da Floresta do Crepúsculo. O eremita Abercrombie afirma precisar delas como materiais para construir uma efígie grotesca a fim de afastar os horrores carnívoros perto de seu casebre.",h="Costelas de Carniçal são obtidas dos mortos-vivos que rondam os bosques e cemitérios assombrados da Floresta...",kw={"abercrombie","refúgio dos mendigos","bone chewer","vila sombria","floresta do crepúsculo","flesh eater","costela de carniçal","boneco de carniçal","morto-vivo"},ang={["class:Paladin"]="Lidar com os ossos profanados dos mortos inquietos é um trabalho desagradável, mas ajudar um eremita isolado contra monstruosidades vorazes condiz com a missão de proteger os vivos contra os horrores da Floresta do Crepúsculo.",["class:Priest"]="A reanimação deturpada que prende esses ossos reflete a profunda sombra que caiu sobre a Floresta do Crepúsculo, transformando aldeões caídos em carniceiros vorazes."},sec={{t="Uma Proteção Macabra",b="A floresta amaldiçoada da Floresta do Crepúsculo rasteja com mortos-vivos violentos, incluindo carniçais vorazes como Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones e Plague Spreaders. Abercrombie, um recluso excêntrico que vive isolado em um casebre ao norte do Cemitério de Monte Corvo, pede esses ossos resistentes e apodrecidos aos viajantes que passam por ali. Ele alega que viver fora da proteção da Vigília Noturna em Vila Sombria o deixa vulnerável, e que montar uma efígie aterrorizante feita de costelas de carniçal servirá como um espantalho para espantar bandos errantes de mortos."},{t="Suspeitas ao Redor do Casebre",b="Embora coletar partes de mortos-vivos abatidos seja comum para a sobrevivência em regiões hostis, o fascínio específico de Abercrombie pela anatomia dos carniçais levanta suspeitas. Em vez de buscar santuário atrás das paliçadas de Vila Sombria ou confiar em proteções consagradas, o eremita insiste em reunir restos necromânticos brutos para fortificar seu lar isolado."}},faq={{q="Quais criaturas carregam Costelas de Carniçal?",a="Elas podem ser obtidas de vários tipos de carniçais por toda a Floresta do Crepúsculo, incluindo Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones e Plague Spreaders. Esses monstros assombram cemitérios antigos, ruínas à beira da estrada e propriedades abandonadas por toda a floresta.",al={"onde cai costela de carniçal","quais carniçais têm costelas","fontes de costela de carniçal"}},{q="Por que Abercrombie quer esses ossos?",a="Abercrombie alega que vive longe demais de Vila Sombria para depender da proteção da Vigília Noturna. Ele pede as costelas para construir um espantalho rústico ou efígie a fim de impedir que mortos-vivos errantes esmurrem suas paredes.",al={"por que abercrombie precisa de costelas","propósito do boneco de carniçal","o que abercrombie faz com costelas"}},{q="Espantalhos realmente mantêm os carniçais afastados?",a="Mortos-vivos geralmente não sentem medo e são movidos inteiramente por uma fome irracional ou compulsão necromântica sombria. A ideia de que carniçais irracionais fugiriam de um espantalho feito de ossos é incomum, mas Abercrombie insiste que isso manterá sua casa segura.",al={"a efígie funciona","efígies assustam mortos-vivos","carniçais temem espantalhos"}},{q="Onde fica o casebre de Abercrombie?",a="Abercrombie vive em um casebre caindo aos pedaços no oeste da Floresta do Crepúsculo, logo ao norte do Cemitério de Monte Corvo.",al={"localização de abercrombie","onde fica o eremita","onde entregar costela de carniçal"}}},fx={["3e8ffb18"]={q="O que é uma Costela de Carniçal?",a="Uma Costela de Carniçal é exatamente o que parece: um osso tirado dos mortos-vivos apodrecidos e reanimados que rondam a Floresta do Crepúsculo. Extraídos de aberrações como Devoradores de Carne, Devoradores de Cérebro e Roedores de Osso, esses remanescentes ainda carregam a leve mancha da magia imunda que anima os mortos vivos nesta floresta assolada.",al={"informações sobre costela de carniçal","o que são costelas de carniçal","item costela de carniçal"}},f2829c95={q="De onde vêm as Costelas de Carniçal?",a="Essas costelas vêm diretamente dos vários carniçais que assombram as estradas sombrias e os túmulos da Floresta do Crepúsculo. São restos esqueléticos naturais, e não relíquias fabricadas, colhidos de monstruosidades mortas-vivas como Espalhadores de Praga e Apodrecidos que vagam muito além da segurança relativa de Vila Sombria.",al={"fonte de costela de carniçal","onde conseguir costelas de carniçal lore","quem fez costelas de carniçal"}}},fp="9,161,15.373.0,27.237.1,32.238.0,38.200.0,40.163.0,37.84.0"}
P.entries["item:giant-crocolisk-skin"] = {n="Pele de Crocolisco Gigante",s="Peles de Crocolisco Gigante são couros grossos retirados dos répteis colossais nativos dos pântanos do Pantanal. Valorizados pelos comerciantes de Porto de Menethil para a couraria, obtê-los é um trabalho perigoso que já mutilou mais de um caçador incauto.",h="Peles de Crocolisco Gigante são couros grossos retirados dos répteis colossais nativos dos pântanos do...",kw={"apprentice's duties","crocolisco","pele de crocolisco gigante","iago halberque","porto de menethil","pantanal"},ang={["class:Hunter"]="Espreitar crocoliscos gigantes ao longo da costa enevoada testa a habilidade do caçador em rastrear feras aquáticas e evitar ser arrastado para as profundezas das águas do pântano."},sec={{t="Um Comércio Perigoso",b="Os podaques e canais fluviais de Pantanal abrigam crocoliscos enormes, cujos couros são densos o suficiente para resistir à podridão úmida dos pântanos. Em Porto de Menethil, artífices como Iago Halberque dependem de remessas constantes de peles para confeccionar artigos de couro resistentes. No entanto, retirar o couro de um crocolisco gigante adulto exige desafiar águas profundas e superar predadores pantanosos ferozes, tornando cada pele obtida uma conquista árdua."},{t="A Tolice do Aprendiz",b="Coletar essas peles grossas era originalmente a tarefa do jovem aprendiz de Halberque. Faltando-lhe habilidade marcial para abater feras adultas do pântano, o garoto foi emboscado ao longo da costa norte. Dilacerado pelos crocoliscos gigantes, ele agora se encontra sob os cuidados de uma parteira local, que afirma que ele talvez sobreviva. O ataque forçou Halberque a contratar aventureiros experientes para caçar os predadores e garantir as peles necessárias."}},faq={{q="Para que são usadas as Peles de Crocolisco Gigante?",a="Elas são obtidas para Iago Halberque, um comerciante de Porto de Menethil, que valoriza esses couros grossos para confeccionar artigos resistentes de couro capazes de suportar o clima úmido d'Os Pântanos.",al={"uso de pele de crocolisco","por que coletar pele de crocolisco gigante","objetivo das peles para halberque"}},{q="Onde são encontrados os crocoliscos que fornecem essas peles?",a="Os Giant Wetlands Crocolisks rondam a costa e as águas pantanosas interiores ao norte de Porto de Menethil, perambulando pelos baixios além dos assentamentos locais de murlocs.",al={"localização de crocolisco gigante","onde encontrar crocoliscos gigantes","costa dos crocoliscos pantanal"}},{q="O que aconteceu com o aprendiz de Halberque?",a="Halberque enviou seu aprendiz ao pântano para coletar peles sozinho. O aprendiz foi atacado por crocoliscos gigantes e ficou tão gravemente ferido que precisou ficar sob os cuidados de uma parteira de Menethil, que afirma que ele talvez sobreviva.",al={"aprendiz ferido","aprendiz de halberque","quem perdeu uma perna"}},{q="Como essas peles se comparam às de crocoliscos jovens?",a="Crocoliscos jovens rendem peles mais finas e maleáveis. Crocoliscos gigantes adultos fornecem couros muito mais resistentes e espessos, mas abater um deles exige habilidades de combate experientes.",al={"pele de crocolisco jovem vs gigante","diferença do couro de crocolisco"}}},fx={["406c8fec"]={q="O que é uma Pele de Crocolisco Gigante?",a="É o couro espesso e durável tirado dos crocoliscos gigantes que vagam pelos pântanos do Pantanal. Valorizada por trabalhadores de couro e artesãos por sua resistência e tamanho, colher tal pele não é uma tarefa fácil, já que esses predadores estão entre as bestas mais cruéis que rondam as vias navegáveis.",al={"o que é a pele de crocolisco gigante","pele de croco gigante","informações sobre pele de crocolisco"}},bd43ba97={q="De onde vem a Pele de Crocolisco Gigante e quem a fez?",a="A pele é colhida naturalmente de crocoliscos gigantes do Pantanal que vivem nos pântanos ao norte, ao longo da costa, além das cabanas dos murlocs. Em vez de ser fabricada por um artesão, ela deve ser esfolada diretamente das carcaças dessas bestas enormes do pântano.",al={"quem fez a pele de crocolisco gigante","de onde vêm as peles de crocolisco gigante","fonte de pele de crocolisco gigante"}},c37602c5={q="Por que Iago Halberque quer Peles de Crocolisco Gigante?",a="Iago Halberque, um artesão no Porto de Menethil, precisa dos couros para seu comércio. Ele originalmente enviou seu jovem aprendiz para reuni-los, mas depois que o menino foi mutilado pelas bestas vorazes e deixado aos cuidados de uma parteira, Halberque recorreu a aventureiros experientes para garantir os materiais e vingar seu protegido.",al={"por que halloran quer as peles","quem quer peles de crocolisco gigante","por que precisar de peles de crocolisco gigante"}}},fp="20,143,17.317.0,22.358.1,40.145.0,56.154.0,39.169.0,52.154.0"}
P.entries["item:gloom-weed"] = {n="Erva-do-emo",s="A Erva-do-emo é uma planta doentia nativa do solo assolado de Clareiras de Tirisfal, crescendo comumente nos campos entre Plangemortis e Montalvo. Ela é mais conhecida por ser a planta errada coletada por Gordo, uma abominação Renegada desajeitada que a confunde com o reagente de alquimia erva-do-demo.",h="A Erva-do-emo é uma planta doentia nativa do solo assolado de Clareiras de Tirisfal, crescendo comumente nos...",kw={"abominação","montalvo","erva-do-demo","erva-do-emo","gordo","mestre holland","clareiras de tirisfal"},ang={["profession:Herbalism"]="Herboristas treinados podem sentir a planta por meio de Descobrir Ervas, tornando-a muito mais fácil de detectar contra a vegetação rasteira e sombria de Tirisfal.",["race:Undead"]="Para os novos Renegados que deixam Plangemortis, buscar Erva-do-emo é uma rápida lição sobre as limitações do trabalho das abominações e o temperamento cáustico dos alquimistas da Cidade Baixa."},sec={{t="Uma Colheita Equivocada",b="Brotando em meio à penumbra e à decadência de Clareiras de Tirisfal, a Erva-do-emo prospera na terra em pousio a oeste de Montalvo e a leste da Fazenda dos Solliden. Apesar de seu nome mórbido, a planta é relativamente inofensiva e carece da potente força alquímica valorizada pela Real Sociedade de Boticários. Sua principal notoriedade decorre da abominação Gordo, que vaga pela estrada tentando arrancar ervas com suas mãos enormes e desajeitadas. Tendo entendido mal as ordens de seu mestre, Gordo colhe Erva-do-emo constantemente e recruta viajantes ingênuos para levar feixes dela de volta ao Mestre Holland no cemitério de Montalvo, para grande irritação do boticário."}},faq={{q="Para que serve a Erva-do-emo?",a="Praticamente nada de valor para os alquimistas Renegados. Ela é colhida unicamente porque a abominação Gordo a confunde com a planta erva-do-demo, que foi o que seu mestre realmente pediu.",al={"uso de erva-do-emo","o que faz erva-do-emo","quem precisa de erva-do-emo"}},{q="Onde a Erva-do-emo cresce?",a="Ela cresce espalhada pelos campos de Clareiras de Tirisfal entre Montalvo e Plangemortis, especialmente ao longo da estrada e nos prados a leste da Fazenda dos Solliden.",al={"onde encontrar erva-do-emo","localização da erva-do-emo","locais de erva-do-emo"}},{q="Quem é Gordo e por que ele a está colhendo?",a="Gordo é uma abominação enviada pelo Mestre Holland para colher reagentes. Como suas mãos costuradas são desajeitadas demais e sua mente é simples, ele vaga pelas estradas arrancando as plantas erradas e implorando para que os transeuntes o ajudem.",al={"quem é gordo","por que gordo está colhendo ervas","gordo abominação"}},{q="O que o Mestre Holland realmente queria?",a="Mestre Holland precisa de erva-do-demo para seus experimentos no cemitério de Montalvo. Ao receber Erva-do-emo, ele zomba do erro e orienta os viajantes a coletarem o que ele verdadeiramente precisava.",al={"erva do mestre holland","do que holland precisa","erva-do-demo vs erva-do-emo"}}},fx={bc1ac336={q="O que é Erva-do-emo?",a="Erva-do-emo é uma planta silvestre comum de aparência doentia que brota no solo amaldiçoado das Clareiras de Tirisfal, encontrada principalmente ao longo das estradas e campos abertos entre Montalvo e Plangemortis. Ela não possui potência mágica ou propriedades alquímicas valiosas. Na verdade, é pouco mais do que uma erva daninha comum à beira da estrada — o equivalente em Tirisfal a uma margarida — que por acaso floresce apesar das condições assoladas do campo.",al={"o que é erva-do-emo","lore de erva-do-emo","planta erva-do-emo"}},defb981c={q="Por que alguém quer Erva-do-emo?",a="Praticamente ninguém quer, de fato, a Erva-do-emo. O único motivo pelo qual alguém a colhe é porque Gordo, uma abominação de mente lenta que vaga pelos campos perto de Montalvo, entendeu completamente mal suas instruções. Seu mestre, o Boticário Júnior Holland, enviou-o para colher a valiosa Doom Weed para experimentos dos Renegados, mas a mente lenta de Gordo confundiu os nomes e enviou viajantes desavisados para colher a inútil Erva-do-emo.",al={"quem quer erva-do-emo","por que coletar erva-do-emo","por que reunir erva-do-emo"}}},fp="10,118,18.441.0,28.137.0,27.131.0,38.172.0,38.180.0"}
P.entries["item:glowing-ember"] = {n="Brasa Faiscante",s="Uma Brasa Faiscante é o núcleo elemental remanescente recuperado de uma Minor Manifestation of Fire derrotada no topo dos penhascos de Durotar. Ela serve como um reagente cerimonial vital nas provações de um xamã, usada para acender o braseiro no Shrine of Eternal Flame.",h="Uma Brasa Faiscante é o núcleo elemental remanescente recuperado de uma Minor Manifestation of Fire derrotada...",kw={"clamor do fogo","sapta do fogo","brasa faiscante","minor manifestation of fire","shrine of eternal flame","telf joolam","tocha da chama latente"},ang={["class:Shaman"]="Obter este núcleo ardente é um rito de passagem marcante, forçando o iniciado a testar sua determinação contra o fogo vivo antes de comandar seu totem."},sec={{t="Núcleo da Chama",b="Quando um xamã em ascensão bebe o Sapta do Fogo e enfrenta os espíritos ígneos no topo da crista perto de Telf Joolam, ele confronta uma Minor Manifestation of Fire. Após a derrota do elemental, este remanescente fumegante é tudo o que resta de sua forma física. Ainda pulsando com calor elemental bruto, a brasa carrega a centelha viva do fogo necessária para despertar o braseiro sagrado no Shrine of Eternal Flame."},{t="Acendendo a Tocha",b="Colocar a Brasa Faiscante na bacia até então fria do braseiro da montanha desencadeia uma ignição repentina e incandescente. Alimentando-se dos resíduos do elemental derrotado, o braseiro permite ao iniciado acender a Tocha da Chama Latente, vinculando a essência rebelde do fogo a um receptáculo que ele pode carregar montanha abaixo para provar seu domínio sobre os elementos."}},faq={{q="De onde vem a Brasa Faiscante?",a="A brasa é recuperada dos restos de uma Minor Manifestation of Fire, um elemental hostil encontrado no cume acima do Shrine of Eternal Flame em Durotar.",al={"como conseguir brasa faiscante","saque de brasa faiscante","onde encontrar brasa faiscante"}},{q="Para que serve a brasa?",a="Os iniciados colocam a brasa no braseiro de metal no Shrine of Eternal Flame. Ela produz uma chama intensa e rítmica usada para acender a cerimonial Tocha da Chama Latente.",al={"o que faz brasa faiscante","uso de brasa faiscante","brasa do braseiro"}},{q="Por que os xamãs precisam do sapta do fogo para adquiri-la?",a="Os espíritos elementais no topo da montanha habitam além da visão mortal comum. Consumir o Sapta do Fogo sintoniza os sentidos do xamã com o plano elemental, revelando a Minor Manifestation of Fire para que possa ser desafiada.",al={"por que precisa de sapta","nao consigo ver elemental do fogo","sapta do fogo brasa"}},{q="Quem instrui os xamãs a procurarem esta brasa?",a="O eremita Telf Joolam, que vive nos penhascos de Durotar, prepara o Sapta do Fogo e guia os iniciados xamãs pela provação de derrotar o espírito das chamas.",al={"quem da a missao","telf joolam brasa","quem entrega clamor do fogo"}}},fx={["8d7073a8"]={q="O que é a Brasa Faiscante?",a="A Brasa Faiscante é o remanescente fumegante colhido de uma Manifestação Menor de Fogo no pico que domina Durotar. É um pedaço concentrado de chama viva deixado para trás assim que o espírito é superado, mantendo calor elemental inato suficiente para acender os fogos dormentes no altar sagrado da montanha.",al={"o que é a brasa faiscante","lore de brasa faiscante","item brasa faiscante"}}},fp="13,157,17.352.0,18.308.1,39.125.0,27.150.0,49.206.0,39.144.0"}
P.entries["item:glowing-fruit"] = {n="Fruta Brilhante",s="A Fruta Brilhante é um espécime exótico e luminescente encontrado crescendo entre folhagens estranhas nos galhos de Teldrassil. Seu brilho não natural e sua interação bizarra com o solo da Árvore do Mundo a tornam objeto de estudo botânico urgente para os naturalistas.",h="A Fruta Brilhante é um espécime exótico e luminescente encontrado crescendo entre folhagens estranhas nos...",kw={"botanica","denalan","fruta brilhante","lago al'ameth","planta","teldrassil","timberlings"},ang={["class:Druid"]="Para os druidas sintonizados com o equilíbrio frágil de Teldrassil, a flora estrangeira que reage erraticamente com o solo representa uma perturbação em potencial para a florescente Árvore do Mundo.",["profession:Herbalism"]="Os herboristas notarão imediatamente que a luminescência estranha da fruta aponta para uma interação potente e exótica entre variedades externas de sementes e o solo encantado."},sec={{t="Um Espécime Curioso",b="Descoberta pendurada sob folhagens incomuns em Teldrassil, esta fruta grande e redonda irradia uma luz inconfundível. O botânico Denalan, no Lago Al'Ameth, reconhece que ela não é nativa da Árvore do Mundo, especulando que suas sementes tenham vindo de terras distantes do outro lado do mar. Qualquer que seja sua origem, a fruta reage de maneira estranha ao solo rico e encantado de Teldrassil, demonstrando como a jovem ramificação do mundo é vulnerável a uma flora estrangeira e imprevisível."}},faq={{q="O que é a Fruta Brilhante?",a="É uma fruta exótica e redonda descoberta crescendo sob folhagens incomuns em Teldrassil. Ela emite um brilho etéreo e parece ter reagido de forma anormal com o solo local.",al={"fruta brilhante teldrassil","o que e esta fruta","missao fruta estranha"}},{q="De onde veio esta fruta?",a="De acordo com o naturalista Denalan, a fruta não é nativa de Teldrassil. Ele suspeita que suas sementes tenham flutuado ou sido transportadas de muito longe através do mar, talvez dos Reinos do Leste de Azeroth, antes de criarem raízes no solo.",al={"origem da fruta","de onde vieram as sementes","e nativa"}},{q="Quem deseja examinar a Fruta Brilhante?",a="Denalan, um pesquisador elfo noturno posicionado no Lago Al'Ameth, estuda os galhos e o ecossistema de Teldrassil. Ele tem grande interesse em plantas estrangeiras que reagiram com a terra da Árvore do Mundo.",al={"quem precisa da fruta","onde levar fruta brilhante","fruta denalan"}}},fp="13,151,18.318.0,26.136.0,31.143.0,39.201.0"}
P.entries["item:glowing-gem"] = {n="Gema Faiscante",s="A Gema Faiscante é uma pedra encantada recuperada dos acampamentos de murlocs ao longo das águas de Vale Gris. Originalmente procurada pelo batedor caído Teronis, a pedra é um componente vital necessário para reconstruir o bastão mágico criado por Dartol.",h="A Gema Faiscante é uma pedra encantada recuperada dos acampamentos de murlocs ao longo das águas de Vale Gris.",kw={"astranaar","bastão de purificação","dartol","gema faiscante","lago íris","murloc","raene correlobos","shael'dryn","teronis"},ang={["class:Druid"]="Os druidas têm interesse na pesquisa de Teronis sobre a corrupção que se espalha e a relíquia que ele esperava restaurar.",["race:NightElf"]="Recuperar a gema e cumprir a missão de Teronis ajuda as Sentinelas a honrar seu batedor caído e proteger Vale Gris da corrupção que se espalha."},sec={{t="Uma Relíquia Perdida de Dartol",b="Descoberta na posse dos agressivos murlocs que habitam perto do Lago Falathim, a Gema Faiscante está imbuída de energia mágica latente. O jovem elfo noturno Teronis aventurou-se para fora de Astranaar para rastreá-la, visando montar uma ferramenta capaz de repelir a corrupção que se infiltra pelas florestas de Vale Gris. Embora Teronis tenha encontrado um fim prematuro no lago, a pedra em si sobreviveu intacta entre os necrófagos da costa."},{t="Restaurando o Bastão",b="Após a recuperação da pedra junto com o diário de Teronis, a líder das Sentinelas Raene Correlobos orienta o portador a levá-la para o nordeste até Shael'dryn, uma dríade que mantém vigília em um poço lunar próximo. A dríade detém o conhecimento antigo necessário para unir a Gema Faiscante com as outras peças perdidas do bastão criado por Dartol, garantindo que o trabalho do batedor caído não tenha sido em vão."}},faq={{q="De onde vem a Gema Faiscante?",a="A gema é carregada pelos murlocs que rondam as costas e águas rasas ao redor do santuário no Lago Falathim, no oeste de Vale Gris, onde Teronis caiu.",al={"localização da gema faiscante","quem derruba gema faiscante","onde conseguir gema faiscante"}},{q="Por que Teronis estava procurando por esta gema?",a="Teronis estava investigando maneiras de purificar a crescente imundície em Vale Gris. De acordo com sua pesquisa, esta gema específica é uma das peças-chave necessárias para reconstruir um bastão mágico outrora concebido por Dartol.",al={"missão de teronis","por que teronis queria a gema","propósito da gema"}},{q="Para quem devo levar a Gema Faiscante?",a="Depois de mostrar a pedra e o diário de Teronis para Raene Correlobos em Astranaar, leve a Gema Faiscante para o nordeste até a dríade Shael'dryn no poço lunar a leste do Lago Íris.",al={"quem precisa da gema faiscante","entregar gema faiscante","o que fazer com a gema"}},{q="O que é o bastão de Dartol?",a="É um instrumento mágico criado por Dartol. Seus componentes foram espalhados pela floresta, sendo a Gema Faiscante necessária para recriá-lo.",al={"bastão de dartol","o que dartol criou"}}},fx={["464fc9d6"]={q="O que é a Gema Faiscante?",a="A Gema Faiscante é uma pedra encantada necessária para recriar o bastão que Dartol fez. Teronis a procurou durante sua pesquisa sobre a corrupção de Vale Gris, e Raene Correlobos direciona a busca pelas peças restantes do bastão.",al={"o que é a gema faiscante","fale-me sobre a gema faiscante","lore de gema faiscante"}}},fp="11,131,22.265.0,17.285.1,37.142.0,37.167.0,37.166.0,26.137.0"}
P.entries["item:glowing-soul-gem"] = {n="Gema Anímica Faiscante",s="Uma Gema Anímica Faiscante é um artefato ritualístico sombrio carregado por operativos do Cult of the Dark Strand no norte de Vale Gris. Imbuída de feitiçaria sombria, a pedra aprisiona o espírito de uma vítima inocente para abastecer as operações sinistras do culto.",h="Uma Gema Anímica Faiscante é um artefato ritualístico sombrio carregado por operativos do Cult of the Dark...",kw={"althalaxx","cult of the dark strand","dark strand","dinis, o purificador","gema anímica faiscante","entreposto de maestra","ordil'aran","gema anímica"},ang={["class:Priest"]="Sacerdotes que observam a gema anímica conseguem sentir a agonia do espírito aprisionado nela, reconhecendo a necessidade urgente de purificar o artefato e conceder paz à alma.",["class:Warlock"]="Bruxos compreendem a arte de aprisionar espíritos em pedras de alma melhor do que ninguém, reconhecendo a gema do Dark Strand como uma derivação necromântica e mais rudimentar da manipulação de almas."},sec={{t="Um Receptáculo de Feitiçaria Sombria",b="A nordeste do Entreposto de Maestra, nas ruínas sombrias de Ordil'Aran, membros do Cult of the Dark Strand empunham feitiçaria sombria sob os olhos vigilantes de seus mestres ocultos. Entre suas fileiras, operativos carregam Gemas Anímicas Faiscantes — receptáculos encantados para aprisionar e atormentar as almas dos mortos. Em vez de meros adornos decorativos, essas pedras atuam como condutores de energia mágica, ancorando espíritos subjugados para servir aos fins sombrios do culto."},{t="Os Segredos de Ordil'Aran",b="Buscando desmantelar a influência do Dark Strand pelo norte de Kalimdor, Dinis, o Purificador, no Entreposto de Maestra, investiga esses artefatos. Decifrar os encantamentos tecidos em uma Gema Anímica Faiscante revela não apenas fórmulas arcanas sombrias, mas uma alma aprisionada clamando de dentro da gema, expondo os experimentos sinistros que ligam os cultistas em Vale Gris aos seus pares na Torre de Althalaxx."}},faq={{q="O que é a Gema Anímica Faiscante?",a="É uma pedra de alma encantada usada pelo Cult of the Dark Strand. Imbuída de Magia Sombria, ela aprisiona espíritos em seu interior para canalizar sua essência e abastecer a feitiçaria vil do culto.",al={"o que é gema anímica","gema anímica costa negra","história gema anímica faiscante"}},{q="De onde vem essa gema anímica?",a="Ela é carregada por membros do Cult of the Dark Strand — incluindo seus cultistas, assassinos, executores e adeptos — que operam a partir das Ruínas de Ordil'Aran, no norte de Vale Gris.",al={"quem dropa gema anímica","localização gema anímica faiscante","gema de ordil'aran"}},{q="Quem quer esta gema anímica e por quê?",a="Dinis, o Purificador, baseado no Entreposto de Maestra, busca a gema. Ele acredita que decifrar seus encantamentos revelará a fonte secreta do poder do culto e exporá o que eles estão tramando.",al={"dinis gema anímica","por que dinis quer a gema anímica","gema anímica entreposto de maestra"}},{q="O que acontece quando a gema anímica é decifrada?",a="Desvendar os encantamentos da gema liberta o fantasma aprisionado em seu interior, libertando a alma atormentada e expondo as profundezas perversas das práticas do Dark Strand.",al={"o que tem dentro da gema anímica","fantasma na gema anímica"}}},fp="16,179,24.294.0,25.318.1,29.167.0,35.167.0,32.161.0,45.143.1"}
P.entries["item:glutton-shackle"] = {n="Grilhão de Glutão",s="Grilhões de Glutão são contenções encantadas usadas por worgens Moonrage Glutton em Floresta de Pinhaprata. Criadas pelo arquimago louco Arugal, essas braçadeiras canalizam magia para reforçar sua feitiçaria, que de outra forma seria falha, e sustentar suas criações lupinas amaldiçoadas.",h="Grilhões de Glutão são contenções encantadas usadas por worgens Moonrage Glutton em Floresta de Pinhaprata.",kw={"arugal","dalar tessalba","grilhão de glutão","moonrage glutton","o sepulcro","floresta de pinhaprata","worgen"},ang={["class:Mage"]="Os magos apreciarão a crítica mordaz de Dalar Tessalba à técnica descuidada de Arugal, já que o uso de muletas físicas encantadas para estabilizar feitiços simples de transmutação e evocação é visto como sinal de magia medíocre.",["race:Undead"]="Os agentes dos Renegados veem a coleta desses grilhões como um passo essencial para neutralizar a ameaça worgen que avança diretamente sobre as fronteiras do Sepulcro."},sec={{t="Uma Muleta para Feitiçaria Fraca",b="Para os magos treinados dos Renegados, os worgens ferozes que infestam Pinhaprata não são meramente monstruosidades selvagens — são evidências de uma crassa ineptidão arcana. Dalar Tessalba, um arcanista talentoso instalado no Sepulcro, não tem nada além de desprezo pelo Arquimago Arugal, considerando-o um incompetente medíocre e indigno do Kirin Tor. Tessalba descobriu que Arugal dependia de relíquias encantadas para compensar seus feitiços frágeis. Os Grilhões de Glutão, usados pelos pesados Moonrage Gluttons que vagam pelo norte de Pinhaprata, agem como âncoras mágicas que reforçam a maldição que aprisiona as feras."},{t="Combustível para Contramedidas dos Renegados",b="Como Arugal vinculou encantamentos brutos diretamente a essas pesadas braçadeiras de ferro, elas retêm energia mágica residual mesmo após seus portadores serem mortos. Tessalba exige esses grilhões dos agentes dos Renegados para estudar sua construção e drenar suas reservas mágicas. Ao analisar os encantamentos rudes incrustados no metal, os Renegados esperam desvendar os mistérios da maldição dos worgens e orquestrar a queda do mestre das feras entrincheirado na Bastilha da Presa Negra."}},faq={{q="O que é um Grilhão de Glutão?",a="Um Grilhão de Glutão é uma contenção de ferro encantada usada por worgens Moonrage Glutton em Floresta de Pinhaprata. Criadas pelo Arquimago Arugal, essas braçadeiras infundem seus portadores com reforço mágico para sustentar seus feitiços falhos.",al={"o que sao grilhoes de glutao","historia do grilhao de glutao","algemas de worgen"}},{q="Por que Dalar Tessalba quer Grilhões de Glutão?",a="Dalar Tessalba precisa dos grilhões para analisar os encantamentos toscos de Arugal e drenar sua energia mágica residual. Ao compreender os itens que Arugal usou para estabilizar suas feras, os Renegados podem combater melhor a magia dele.",al={"por que coletar grilhoes","missao de dalar tessalba","grilhoes para o sepulcro"}},{q="Quem faz esses grilhões?",a="Eles foram encantados pelo Arquimago Arugal, um antigo mago de Dalaran que evocou os worgens para combater o Flagelo e acabou enlouquecendo, prendendo suas criações à sua vontade com bugigangas mágicas.",al={"quem fez os grilhoes","grilhoes de arugal","de onde vieram os grilhoes"}},{q="Onde são encontradas as criaturas que usam esses grilhões?",a="Os Moonrage Gluttons vagam pelas florestas e fazendas abandonadas do centro e do norte de Floresta de Pinhaprata, muitas vezes espreitando em matilhas ao lado de outros worgens Moonrage corrompidos.",al={"onde surgem gluttons","localizacao de moonrage glutton","grilhoes de worgen de pinhaprata"}}},fp="15,143,25.512.0,33.458.1,26.198.0,48.218.0,25.190.0,53.170.0"}
P.entries["item:glyph-of-azora"] = {n="Glifo de Azora",s="Um Glifo de Azora é um dispositivo de rastreamento arcano criado pelo mago Teócrito na Torre de Azora. Vinculadas ao poder de vidência do Olho de Azora, essas pedras inscritas permitem que o mago enxergue através de distâncias e sonde os pensamentos de seus inimigos.",h="Um Glifo de Azora é um dispositivo de rastreamento arcano criado pelo mago Teócrito na Torre de Azora.",kw={"glifo de azora","morganth","montanhas cristarrubra","videncia","bastilha mirante de pedra","teócrito","torre de azora","torre de ilgalar"},ang={["class:Mage"]="O Glifo de Azora demonstra uma aplicação prática da adivinhação arcana, expandindo a vidência de cristal comum para telepatia direcionada e retransmissores sensoriais remotos.",["faction:Alliance"]="Os glifos fornecem informações vitais sobre movimentações hostis em Cristarrubra, rastreando o feiticeiro renegado Morganth e a guarnição de orcs Blackrock em Mirante de Pedra."},sec={{t="Olhos Além da Fronteira",b="De sua torre na Floresta de Elwynn, o mago Teócrito trabalha incansavelmente para monitorar forças hostis que ameaçam o reino. Embora sua relíquia de cristal, o Olho de Azora, possibilite a vidência visual a longa distância, falta-lhe o alcance para penetrar mais fundo nas mentes e nos planos dos adversários. Para contornar essa limitação, Teócrito desenvolve focos em miniatura conhecidos como Glifos de Azora. Uma vez afixado a uma superfície em um local remoto, o glifo atua como uma âncora para sua magia, permitindo-lhe não apenas ler as intenções dos inimigos, mas também projetar sua voz através de milhas para se comunicar diretamente com agentes de campo."},{t="Espionagem em Cristarrubra",b="Teócrito posiciona esses glifos diretamente em território hostil nas Montanhas Cristarrubra. O primeiro é afixado a uma antiga estátua de leão voltada para a Torre de Ilgalar, a fortaleza de seu rival renegado, o mago sombrio Morganth. Após sondar a mente de Morganth, Teócrito descobre uma disputa inesperada entre o mago renegado e os orcs Blackrock que ocupam a vizinha Bastilha Mirante de Pedra. Um segundo glifo é levado até as alturas da torre de vigia intacta da bastilha, escondido em um jarro de bebida descartado, para desvendar por que Morganth e os invasores estão em desacordo."}},faq={{q="Qual é a finalidade do Glifo de Azora?",a="Ele funciona como um repetidor arcano criado por Teócrito. Enquanto seu Olho de Azora permite a vidência visual à distância, posicionar um Glifo de Azora estabelece um ponto de ancoragem que lhe permite ler as mentes e os planos futuros de seus adversários, bem como projetar sua voz para falar com aliados distantes.",al={"o que faz o glifo de azora","para que usar o glifo de azora","proposito do glifo de azora"}},{q="Quem criou o Glifo de Azora?",a="Ele foi criado por Teócrito, um poderoso mago que reside na Torre de Azora, junto à fronteira leste da Floresta de Elwynn.",al={"quem fez o glifo","criador do glifo de azora","glifo de teocrito"}},{q="Onde os Glifos de Azora são colocados?",a="Um glifo é fixado na base de uma estátua de leão desgastada pelo tempo que vigia a Torre de Ilgalar. Um segundo glifo é infiltrado na torre de vigia superior da Bastilha Mirante de Pedra e ocultado dentro de um jarro de bebida vazio para espionar os orcs Blackrock.",al={"onde colocar o glifo","locais de colocacao do glifo","onde vai o glifo"}},{q="Por que Teócrito está espionando a Torre de Ilgalar?",a="A Torre de Ilgalar está ocupada por Morganth, um perigoso mago renegado que é o ferrenho rival de Teócrito. Teócrito usa o glifo para desvendar as maquinações de Morganth antes que ele possa lançar magia sombria sobre a região.",al={"por que espionar morganth","teocrito ilgalar","disputa morganth"}},{q="Como o glifo permite que Teócrito fale com as pessoas?",a="O glifo está ligado diretamente às energias arcanas da Torre de Azora. Uma vez afixado a uma superfície-alvo, ele estabelece um canal bidirecional que permite a Teócrito projetar sua voz desencarnada diretamente pela pedra.",al={"glifo falante","voz de teocrito no glifo","o glifo consegue falar"}}},fx={["16152ed3"]={q="O que é o Glifo de Azora?",a="O Glifo de Azora é um marcador arcano encantado criado pelo mago Teócrito na Torre de Azora. Trabalhando em conjunto com seu foco de escrutínio, o Olho de Azora, essas pedras inscritas servem como postos de escuta remotos. Uma vez afixado a uma superfície perto de uma área de interesse, um glifo permite que Teócrito mergulhe nas mentes e pensamentos de seus alvos a grandes distâncias, bem como projete sua voz para quem estiver ao lado dele.",al={"o que é o glifo de azora","item glifo de azora","fale-me sobre o glifo de azora"}},["7c5a9e02"]={q="Por que Teócrito quer que você plante o Glifo de Azora?",a="Teócrito conta com esses glifos para realizar uma espionagem profunda contra adversários perigosos nas Montanhas Cristarrubra. Embora o Olho de Azora o deixe ver lugares de longe, ele não consegue penetrar mentes sem um condutor por perto. Colocar um glifo perto da Torre de Ilgalar permite que ele sonde os pensamentos e os planos futuros de seu rival, o mago renegado Morganth, enquanto plantar outro perto da Bastilha Mirante de Pedra o ajuda a desvendar a disputa de Morganth com os orcs Rocha Negra.",al={"por que plantar glifo de azora","por que teócrito quer o glifo plantado","objetivo do glifo de azora"}}},fp="14,161,22.362.0,21.468.1,42.206.0,31.107.0,37.168.0,49.150.0,55.136.0"}
P.entries["item:glyphic-letter"] = {n="Carta Glífica",s="A Carta glífica é uma missiva oficial que traz o sigilo arcano de Gaspar Melchior, o instrutor de magos residente na Abadia de Vila Norte. Entregue a novatos promissores após os primeiros serviços prestados à guarnição, ela convoca os aspirantes a mago a se apresentarem no andar de cima e encararem as rigorosas realidades do estudo arcano.",h="A Carta glífica é uma missiva oficial que traz o sigilo arcano de Gaspar Melchior, o instrutor de magos...",kw={"arcano","floresta de elwynn","carta glífica","gaspar melchior","instrutor de magos","major belmonte","abadia de vila norte"},ang={["class:Mage"]="Este despacho marcado assinala a sua iniciação formal nas tradições arcanas da Aliança, chamando você ao andar de cima para estudar com Gaspar Melchior.",["race:Human"]="A Abadia de Vila Norte abrigou muitos estudantes do arcano ao longo da história do reino, e esta convocação inicia o seu serviço às disciplinas mágicas de Ventobravo."},sec={{t="Uma Convocação ao Arcano",b="Selada com a insígnia pessoal do instrutor de magos Gaspar Melchior, a Carta glífica é entregue a aprendizes conjuradores assim que provam sua disciplina no Vale de Vila Norte. A carta atua como um convite formal para se afastar dos deveres básicos de campo e iniciar a instrução mágica dedicada dentro da abadia. Melchior usa a convocação para avaliar a determinação do aluno, garantindo que qualquer um que mexa com o arcano esteja plenamente preparado para enfrentar forças perigosas, escrutínio implacável e os fardos que acompanham o domínio do poder mágico bruto."}},faq={{q="O que é a Carta glífica?",a="É uma convocação instrutiva escrita e selada por Gaspar Melchior, o mentor de magos residente da Abadia de Vila Norte. Ela orienta os aspirantes a mago humanos a procurá-lo nos aposentos superiores da abadia para receberem instrução arcana formal.",al={"o que e esta carta","item carta glifica","carta de gaspar melchior"}},{q="Quem envia a Carta glífica?",a="A carta é selada com a insígnia de Gaspar Melchior, o instrutor de magos local estabelecido na Abadia de Vila Norte. Ela é entregue pelo comando da guarnição depois que um aprendiz prova seu valor contra as pragas locais.",al={"quem escreveu","quem me deu carta glifica","remetente da carta"}},{q="Onde levo a Carta glífica?",a="Você a leva para dentro da Abadia de Vila Norte. Entre pela entrada principal atrás do Major Belmonte, pegue o corredor à esquerda, suba as escadas e procure a sala dos fundos onde Gaspar Melchior ministra sua instrução arcana.",al={"para onde ir","onde fica gaspar melchior","localizacao de gaspar melchior"}},{q="Por que Melchior manda chamar jovens magos?",a="Melchior deseja testar a sua determinação. Como ele adverte em suas lições introdutórias, dedicar-se ao arcano significa atrair tanto o medo quanto o respeito ao mesmo tempo em que se desafiam forças potentes, e ele precisa saber se seus aprendizes possuem a vontade necessária para suportar esse destino.",al={"por que melchior me quer","motivo do instrutor de magos","o que melchior quer"}}},fx={["4321b6bd"]={q="Por que Gaspar Melchior quer que a Carta Glífica seja entregue a você?",a="A carta serve como uma convocação oficial e um teste de determinação para magos iniciantes. Selada com seu brasão pessoal, a nota de Gaspar Melchior expõe o caminho perigoso e assustador do arcano, avisando você sobre o medo e os desafios que acompanham a busca pelo conhecimento proibido. Entregá-la a você garante que você está disposto a enfrentar esse destino antes que ele inicie seu treinamento formal.",al={"por que carta glífica","por que recebi a carta glífica","propósito da carta glífica"}}},fp="14,180,23.390.0,27.190.0,29.183.0,35.185.0,38.193.0"}
P.entries["item:glyphic-memorandum"] = {n="Memorando Glífico",s="O Memorando Glífico é um aviso escrito entregue a magos novatos que chegam ao Vale Cristálgida. Redigido em nome do instrutor de magos Marryk Nurribit, ele direciona os conjuradores novatos para o interior a fim de iniciarem sua instrução arcana formal.",h="O Memorando Glífico é um aviso escrito entregue a magos novatos que chegam ao Vale Cristálgida.",kw={"sidermar","vale cristálgida","dun morogh","memorando glífico","mago","marryk nurribit"},ang={["class:Mage"]="Para magos promissores que se aventuram por Dun Morogh, este bilhete marca o início formal de seu aprendizado arcano sob a tutela de Marryk Nurribit.",["race:Gnome"]="Magos gnomos que iniciam suas jornadas no exílio são lembrados por seu instrutor a se concentrarem em seus estudos e ficarem longe de sua terra natal perdida, Gnomeregan."},sec={{t="Um Chamado para Sidermar",b="Conjuradores novatos que partem para a geada congelante do Vale Cristálgida recebem esta breve missiva após concluírem suas tarefas iniciais. De autoria do instrutor de magos local, Marryk Nurribit, o memorando convoca os jovens praticantes para o calor de Sidermar. Em vez de um dogma acadêmico rígido, a orientação de Marryk é informal e direta: aprenda seus encantamentos, reserve moedas para o treinamento e a cerveja da taverna, e mantenha-se bem longe das ruínas irradiadas de Gnomeregan."}},faq={{q="O que é o Memorando Glífico?",a="É uma breve convocação escrita entregue a magos recém-chegados ao Vale Cristálgida, instruindo-os a procurar o instrutor arcano local dentro de Sidermar.",al={"memorando glífico","bilhete de mago","o que é memorando glífico"}},{q="Quem escreveu este memorando?",a="O bilhete tem origem com Marryk Nurribit, um gnomo instrutor de magos instalado nos salões de Sidermar, em Dun Morogh.",al={"quem escreveu","quem enviou o memorando glífico","autor do bilhete"}},{q="Que conselho o instrutor dá ao responder ao memorando?",a="Ao apresentar o bilhete, Marryk lembra ao novato que pratique contenção, economize dinheiro para feitiços e cerveja da taverna, e evite terminantemente os salões radioativos de Gnomeregan.",al={"conselho de marryk","o que marryk diz"}}},fx={c67a7a55={q="Por que Marryk Nurribit quer que você leve o Memorando Glífico para ele?",a="O memorando serve como um convite e convocação para aspirantes a magos que estão começando no Vale Cristálgida. Ao entregá-lo a Marryk Nurribit em Sidermar, você estabelece contato com seu instrutor de mago local. Ele usa a oportunidade para oferecer conselhos a noviços, lembrar você de ficar longe da caída Gnomeregan e oferecer instrução formal nas artes arcanas sempre que você tiver moedas de sobra.",al={"por que trazer memorando glífico","por que marryk quer o memorando","por que querer memorando glífico"}}},fp="18,158,21.305.0,31.126.0,26.81.0,64.131.0"}
P.entries["item:glyphic-scroll"] = {n="Pergaminho Glífico",s="O Pergaminho glífico é uma convocação entregue aos magos Renegados recém-reanimados em Plangemortis. Com o selo de Isabella, a instrutora local de magia arcana, ele chama os conjuradores novatos à igreja profanada para aprimorarem sua arte na morte-viva.",h="O Pergaminho glífico é uma convocação entregue aos magos Renegados recém-reanimados em Plangemortis.",kw={"arcano","plangemortis","pergaminho glífico","isabella","mago","pergaminho","tirisfal"},ang={["class:Mage"]="O pergaminho é a primeira convocação formal que um mago Renegado recebe, enfatizando que a morte-viva não liberta o conjurador dos vícios corruptores da magia arcana.",["race:Undead"]="Para os Renegados, o conhecimento arcano resgatado não é mero estudo acadêmico — é uma arma essencial para garantir sua soberania contra o Flagelo e contra inimigos vivos."},sec={{t="Uma convocação da igreja",b="Quando um mago Renegado recém-despertado retorna do abate do Flagelo irracional no cemitério de Plangemortis, esta missiva selada o aguarda. Escrito sob a marca de Isabella, a instrutora de magos residente do assentamento, o pergaminho chama o destinatário para as ruínas do santuário paroquial. Para os magos recém-erguidos, ele serve como uma orientação inicial na disciplina do arcano sob o estandarte dos Renegados — lembrando-os de que, embora a morte possa tê-los libertado das fraquezas mortais, as tentações corruptoras do poder mágico permanecem tão persistentes quanto sempre foram."}},faq={{q="O que é o Pergaminho glífico?",a="É um comunicado introdutório entregue a magos Renegados recém-erguidos em Plangemortis. Com o selo pessoal da instrutora arcana Isabella, ele orienta os conjuradores novatos a se apresentarem a ela dentro da igreja da cidade para iniciarem seu treinamento mágico.",al={"o que é este item","uso do pergaminho glífico","o que o pergaminho faz"}},{q="Quem envia o Pergaminho glífico?",a="O pergaminho é entregue em nome de Isabella, a instrutora de magos instalada na igreja em ruínas de Plangemortis. Ela entra em contato com qualquer morto-vivo recém-erguido que possua aptidão para o arcano.",al={"quem escreveu","quem me deu isto","remetente do pergaminho"}},{q="Por que Isabella quer treinar novos magos Renegados?",a="Isabella busca espíritos afins que compartilhem a dor da morte e o desejo de recuperar sua terra natal e seus destinos roubados. Ela os treina para cultivar poder arcano suficiente para destruir qualquer um que se oponha aos Renegados, enquanto os adverte a não sucumbir ao vício e à corrupção mágicos.",al={"motivo de isabella","por que treinar magos"}}},fp="14,167,25.355.0,27.176.0,29.139.0,51.253.0"}
P.entries["item:glyphic-tablet"] = {n="Tabuleta Glífica",s="A Tabuleta Glífica é uma lousa inscrita entregue a magos trolls Lançanegra novatos ao iniciarem suas provações em Durotar. Entregue pelo feitor Gornek, ela orienta os conjuradores novatos a buscarem a tutela da instrutora de magos troll, Mai'ah.",h="A Tabuleta Glífica é uma lousa inscrita entregue a magos trolls Lançanegra novatos ao iniciarem suas...",kw={"arcano","durotar","tabuleta glífica","gornek","mai'ah","mago troll","vale das provações"},ang={["class:Mage"]="A tabuleta marca o início de sua instrução arcana entre os Lançanegra, trazendo um lembrete de Mai'ah de que a atração corruptora da magia é o seu maior perigo.",["race:Troll"]="Magos Lançanegra recebem esta tabuleta para iniciar sua jornada ao lado dos caminhos xamânicos e marciais tradicionais."},sec={{t="A Primeira Convocação de um Mago",b="No Vale das Provações, novos iniciados trolls Lançanegra que exibem afinidade com o poder arcano são apresentados à Tabuleta Glífica. Repassada por Gornek enquanto os jovens recrutas realizam as primeiras tarefas pelos desfiladeiros vermelhos, a tabuleta contém um convite de Mai'ah, uma experiente maga troll posicionada do lado de fora de the Den. Para os Lançanegra, cujas tradições arcanas divergem das academias eruditas dos humanos ou dos altos-elfos, a tabuleta serve como um chamado formal à disciplina. Mai'ah aproveita o encontro para oferecer tanto instrução arcana quanto um solene aviso: a magia pura é corruptora, enganosa e muito mais perigosa para a mente de um praticante do que qualquer soldado inimigo."}},faq={{q="Qual é o propósito da Tabuleta Glífica?",a="Ela serve como uma convocação escrita orientando um mago troll novato a se apresentar a Mai'ah, a instrutora de magos local no Vale das Provações, para dar início ao devido treinamento de conjuração.",al={"o que a tabuleta glífica faz","uso da tabuleta glífica","por que tenho a tabuleta glífica"}},{q="Quem envia a Tabuleta Glífica?",a="A tabuleta é de autoria da instrutora de magos Mai'ah e entregue aos jovens recrutas trolls por Gornek dentro do Vale das Provações.",al={"quem escreveu a tabuleta glífica","quem me deu a tabuleta glífica"}},{q="Por que os magos trolls precisam de um aviso sobre magia?",a="Mai'ah enfatiza que a magia arcana é inerentemente corruptora. Ela adverte que ela alimenta a arrogância e faz com que os conjuradores acreditem ser invencíveis, alertando que os perigos invisíveis do arcano são muito mais mortais do que rivais físicos.",al={"o que mai'ah diz","a magia é perigosa"}},{q="Outras raças da Horda podem receber esta tabuleta?",a="Magos trolls recebem a Tabuleta Glífica no Vale das Provações. Magos orcs são convocados até Mai'ah por um Glyphic Parchment.",al={"orcs podem obter a tabuleta glífica","a tabuleta glífica é apenas para trolls"}}},fx={be25ec39={q="O que é a Tabuleta Glífica?",a="A Tabuleta Glífica é uma mensagem inscrita enviada para magos troll iniciantes que estão começando seus testes no Vale das Provações. Entregue por meio de Gornek, ela convoca você para se encontrar com Mai'ah, a instrutora de mago local, para que você possa começar formalmente sua instrução nas artes arcanas.",al={"o que é tabuleta glífica","item tabuleta glífica","sobre a tabuleta glífica"}},["28b4f0b5"]={q="Por que alguém quer a Tabuleta Glífica?",a="A tabuleta não é procurada por poder ou riqueza, mas serve como uma convocação formal e um símbolo de apresentação. Ela garante que jovens magos troll se apresentem a Mai'ah, que usa o encontro para transmitir avisos cruciais sobre os perigos corruptores inerentes ao uso da magia arcana.",al={"por que querer tabuleta glífica","quem precisa da tabuleta glífica","por que manter a tabuleta glífica"}}},fp="14,152,22.518.0,42.114.0,29.94.0,46.154.0,42.130.0"}
P.entries["item:glyphs-of-summoning"] = {n="Glifos de Evocação",s="Os Glifos de Evocação são inscrições rituais usadas por aprendizes de bruxo em Orgrimmar. Transcritos da antiga Tabuleta de Verga, eles permitem que um praticante retire um emissário do caos do Éter para dentro de um círculo de evocação e o vincule ao seu serviço.",h="Os Glifos de Evocação são inscrições rituais usadas por aprendizes de bruxo em Orgrimmar.",kw={"antro das sombras","gan'rul bloodeye","glifos de evocação","neeru fireblade","orgrimmar","tabuleta de verga","the binding","emissário do caos"},ang={["class:Warlock"]="Os glifos representam um rito de passagem essencial para os bruxos da Horda, servindo como o instrumento pelo qual eles provam seu domínio sobre o Caos e reivindicam seu servo emissário do caos."},sec={{t="Um Pacto Forjado nas Sombras",b="Nas profundezas subterrâneas do Antro das Sombras, as artes sombrias são estudadas longe dos olhos atentos dos guardas do Chefe Guerreiro. Para um aspirante a bruxo sob a tutela de Gan'rul Bloodeye, comandar um emissário do caos marca um passo vital em seu ofício. Os Glifos de Evocação, derivados do conhecimento esotérico inscrito na Tabuleta de Verga, unem a fronteira entre Azeroth e o Éter. Dispostos dentro do círculo de evocação na tenda de Neeru Fireblade, os glifos abrem um limiar, puxando uma Creature of the Void para o reino mortal. O ritual exige que o bruxo vença a entidade evocada em combate antes que Gan'rul ensine os métodos finais de vinculação."}},faq={{q="Para que servem os Glifos de Evocação?",a="Os glifos são escritos rituais usados dentro do círculo de evocação na tenda de Neeru Fireblade em Orgrimmar. Quando ativados, eles conjuram um emissário do caos hostil do Éter, o qual o bruxo deve subjugar para dominar a arte de evocá-lo.",al={"o que os glifos de evocação fazem","propósito dos glifos de evocação","como usar glifos de evocação"}},{q="De onde vêm os Glifos de Evocação?",a="Eles são fornecidos pelo instrutor de bruxos Gan'rul Bloodeye no Antro das Sombras, derivados do conhecimento preservado na Tabuleta de Verga.",al={"onde conseguir glifos de evocação","quem dá glifos de evocação"}},{q="Onde o ritual de evocação é realizado?",a="O ritual ocorre dentro da tenda de Neeru Fireblade, localizada ao longo do piso da caverna no Antro das Sombras de Orgrimmar.",al={"onde evoco o emissário do caos","localização do círculo de evocação em orgrimmar","círculo de neeru fireblade"}},{q="Por que os bruxos precisam derrotar a criatura evocada?",a="Um bruxo não pode controlar com segurança um demônio ou Creature of the Void sem estabelecer domínio sobre ela. Derrotar a entidade evocada prova a determinação do bruxo e permite que Gan'rul Bloodeye ensine os segredos de vincular sua espécie à sua vontade.",al={"por que enfrentar o emissário do caos","subjugar emissário do caos"}}},fx={["094a8ca5"]={q="O que são os Glifos de Evocação?",a="Os Glifos de Evocação são inscrições arcanas e demoníacas transcritas diretamente da Tabuleta de Verga. Confiados a bruxos em desenvolvimento por Gan'rul Bloodeye sob Orgrimmar, eles carregam as invocações precisas necessárias para rasgar o véu e evocar um andalvoide hostil do Nether para ser vinculado.",al={"o que são glifos de evocação","conhecimento sobre glifos de evocação","o que é glifos de evocação"}},fd669514={q="Por que Gan'rul Bloodeye quer os Glifos de Evocação de volta?",a="Gan'rul Bloodeye exige que você traga os glifos de volta junto com a prova de sua vitória para que ele possa completar seu treinamento. Assim que você demonstra que tem força para invocar e subjugar um andalvoide furioso, Gan'rul usa os glifos e sua maestria demonstrada para ensinar você como vincular permanentemente tais entidades ao seu serviço.",al={"por que retornar glifos de evocação","por que gan'rul quer glifos de evocação","por que os glifos de evocação são procurados"}}},fp="19,242,23.539.0,42.207.0,43.139.0,40.109.0,53.218.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="Engrenotreco Gnomo",s="O Engrenotreco Gnomo é uma fonte de energia sofisticada recuperada do Retalhador do Sneed nas profundezas das Minas Mortas. Engenheiros gnomos buscam este componente para sobrecarregar máquinas perfuradoras especializadas em uma tentativa ambiciosa de recuperar seu lar caído de Gnomeregan.",h="O Engrenotreco Gnomo é uma fonte de energia sofisticada recuperada do Retalhador do Sneed nas profundezas das...",kw={"minas mortas","engrenotreco gnomo","gnomeregan","gyrodrillmatic","shoni, a shilenchiosa","sneed","retalhador do sneed","engrenotreco"},ang={["profession:Engineering"]="A engrenagem é uma fonte de energia intacta capaz de abastecer o maquinário necessário para perfurar as fronteiras subterrâneas rochosas de Gnomeregan.",["race:Gnome"]="Cada componente recuperado aproxima os gnomos exilados de perfurar seu lar perdido e expulsar a infestação de troggs."},sec={{t="Uma Fonte de Energia Vital",b="Encontrado em um retalhador goblin operado dentro do reduto dos Defias, o Engrenotreco Gnomo representa um feito excepcional de energia mecânica compacta. Operando nas profundezas da máquina pesada pilotada pelo feitor goblin Sneed, este núcleo especializado fornece energia sustentada suficiente para acionar lâminas industriais pesadas de corte e extração de madeira. Sua estabilidade e potência fazem dele uma peça inestimável de resgate em meio aos túneis subterrâneos de Cerro Oeste."},{t="Invadindo Gnomeregan",b="Em Ventobravo, a inventora gnoma Shoni, a Shilenchiosa destacou o retalhador das Minas Mortas como a chave para uma ofensiva maior. Forças gnomas buscam recuperar Gnomeregan das hordas de troggs que a invadiram, mas os acessos subterrâneos selados representam uma barreira formidável. Ao canalizar o Engrenotreco, Shoni pretende abastecer Gyrodrillmatic Excavationators pesados capazes de perfurar diretamente a rocha sólida que cerca a tecno-cidade perdida, estabelecendo uma rota inesperada de Underground Assault."}},faq={{q="O que é o Engrenotreco Gnomo?",a="É uma fonte de energia mecânica intacta e de alta potência extraída de um retalhador goblin encontrado nas profundezas das Minas Mortas. Possui potência suficiente para operar aparelhos pesados de perfuração subterrânea.",al={"engrenotreco","o que é esta engrenagem","o que é o item"}},{q="De onde vem o Engrenotreco Gnomo?",a="Ele é recuperado do Retalhador do Sneed, uma máquina de madeira industrial operada pelo feitor goblin Sneed dentro das serrarias das Minas Mortas.",al={"quem saqueia","como obter engrenotreco","saque do retalhador"}},{q="Por que Shoni, a Shilenchiosa precisa dele?",a="Shoni precisa de sua produção de energia para abastecer Gyrodrillmatic Excavationators. Essas máquinas são projetadas para perfurar as fronteiras rochosas subterrâneas de Gnomeregan para permitir que gnomos alinhados à Aliança montem um ataque contra os troggs.",al={"por que shoni quer isto","item de missão da shoni"}},{q="A engrenagem é tecnologia goblin ou gnoma?",a="Ela é recuperada de um retalhador goblin funcional nas Minas Mortas, e Shoni planeja usar sua fonte de energia em maquinário de perfuração gnomo. A fonte não identifica quem projetou originalmente o componente.",al={"é tecnologia goblinica","dispositivo gnomo ou goblin"}}},fp="22,198,20.274.0,20.444.0,35.152.0,48.156.0,35.211.0,45.170.0"}
P.entries["item:gnoll-paw"] = {n="Pata de Gnoll",s="Patas de Gnoll são troféus físicos rudimentares obtidos de gnolls Patarrubra que vagam pelas pradarias de Cerro Oeste. Coletadas pela Milícia do Povo, elas servem como prova do sucesso de uma patrulha em reduzir os bandos que ameaçam as fazendas locais.",h="Patas de Gnoll são troféus físicos rudimentares obtidos de gnolls Patarrubra que vagam pelas pradarias de...",kw={"danuvin","pata de gnoll","a patrulha do cerro oeste","a milicia do povo","patarrubra","morro da sentinela","cerro oeste"},ang={["class:Hunter"]="Rastrear bandos agressivos de Patarrubra pelas planícies abertas de Cerro Oeste oferece aos caçadores presas fáceis, ao mesmo tempo em que ajuda a proteger postos avançados rurais.",["faction:Alliance"]="Para os campeões da Aliança, aceitar recompensas para A Milícia do Povo é vital para evitar que o celeiro ocidental de Ventobravo caia inteiramente nas mãos de feras selvagens errantes e bandidos organizados."},sec={{t="Recompensa da Milícia",b="Com a ausência do exército real e a coroa aparentemente cega para a situação dos assentamentos rurais, a defesa de Cerro Oeste recaiu sobre cidadãos comuns e forças voluntárias. A Milícia do Povo, operando a partir do Morro da Sentinela, luta constantemente contra foras da lei, mecanoides renegados e gnolls agressivos com cabeças de hiena. Para conter a ameaça dos gnolls, o Capitão Danuvin instituiu recompensas que exigem provas físicas das feras abatidas. Coletar patas decepadas é uma necessidade sombria, garantindo que os aventureiros contratados realmente vasculhem as terras ermas em vez de vadiar à sombra da torre de vigia."},{t="Uma Ameaça Coordenada",b="Os gnolls Patarrubra em Cerro Oeste são mais do que simples feras selvagens procurando comida pelas planícies. Observadores da milícia notaram sinais preocupantes de que esses gnolls operam em estreita coordenação com os ladrões Defias baseados nos arredores das Minas Mortas. Ao aterrorizar fazendas isoladas e atacar carroças de suprimentos em trânsito, os bandos de gnolls protegem efetivamente os bandidos da resistência local. Suprimi-los entregando suas patas ajuda a manter abertas as precárias rotas terrestres entre o Morro da Sentinela e a Floresta de Elwynn."}},faq={{q="Por que o Capitão Danuvin quer Patas de Gnoll?",a="O Capitão Danuvin usa as patas como prova de uma patrulha bem-sucedida pelas planícies de Cerro Oeste. Como os recursos da milícia são escassos e a coroa não fornece ajuda, as recompensas só são pagas quando os recrutas entregam evidências tangíveis de gnolls mortos.",al={"por que coletar patas","danuvin patas de gnoll","para que servem patas de gnoll"}},{q="Quais gnolls concedem essas patas?",a="Elas são obtidas dos vários gnolls Patarrubra que rondam pelas pradarias, colinas e fazendas abandonadas por todo o Cerro Oeste.",al={"onde conseguir patas de gnoll","quais gnolls tem patas","localizacao pata de gnoll"}},{q="Os gnolls estão agindo sozinhos em Cerro Oeste?",a="Não. O Capitão Danuvin e a milícia suspeitam que os gnolls Patarrubra estejam trabalhando em conjunto com os bandidos e ladrões que operam a partir das Minas Mortas, criando problemas em dobro para as fazendas locais.",al={"gnolls estao com os defias","conexao gnoll minas mortas","quem comanda os gnolls"}},{q="Por que Ventobravo não está lidando com a ameaça dos gnolls?",a="Ventobravo praticamente abandonou Cerro Oeste à própria sorte devido a conflitos internos e paralisia política. A defesa do campo é deixada quase inteiramente para os fazendeiros locais e A Milícia do Povo.",al={"por que nao ha exercito de ventobravo","onde esta o exercito","por que a milicia enfrenta gnolls"}}},fx={aa4b645a={q="O que é uma Pata de Gnoll?",a="Uma Pata de Gnoll é uma mão decepada tirada de um gnoll Pata-do-Rio que ronda as planícies do Cerro Oeste. Para a The People's Militia estacionada no Morro da Sentinela, esses troféus macabros servem como prova física inegável de que um aventureiro patrulhou ativamente o território e abateu as alcateias agressivas de gnolls que ameaçam as propriedades locais.",al={"o que é pata de gnoll","item pata de gnoll","o que são patas de gnoll"}},["96952327"]={q="De onde vêm as Patas de Gnoll?",a="Essas patas vêm diretamente dos gnolls selvagens Pata-do-Rio espalhados pelas pastagens e fazendas abandonadas do Cerro Oeste. Os gnolls ferozes vagam pela região atacando fazendeiros e coordenando-se com bandidos, tornando suas patas decepadas uma recompensa sombria tirada diretamente dos saqueadores caídos em campo.",al={"onde conseguir patas de gnoll","quem deixa cair patas de gnoll","origem da pata de gnoll"}}},fp="9,161,21.403.0,20.379.1,41.199.0,29.98.0,40.159.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="Jujuba de Gnomeregan",s="A Jujuba de Gnomeregan é um doce sazonal especial distribuído durante o Noturnália em nome dos gnomos desalojados. Aventureiros buscam essa guloseima para ajudar a criança doente Jacinto no orfanato de Ventobravo a celebrar o feriado.",h="A Jujuba de Gnomeregan é um doce sazonal especial distribuído durante o Noturnália em nome dos gnomos...",kw={"doce","jujuba de gnomeregan","noturnália","altaforja","jacinto","ventobravo","didiê du mocó"},ang={["faction:Alliance"]="Coletar esse doce exige viajar entre comunidades de humanos, anões e gnomos, destacando os laços estreitos entre as raças da Aliança durante as celebrações sazonais.",["race:Gnome"]="Mesmo sem uma cidade própria recuperada, os gnomos se orgulham de ter sua própria guloseima característica representada entre as grandes capitais da Aliança durante o Noturnália."},sec={{t="Um Gostinho da Engenhosidade Gnômica",b="Enquanto estalajadeiros por toda a Aliança distribuem guloseimas regionais durante o Noturnália, os gnomos exilados de Gnomeregan não têm uma estalagem própria em uma capital completa para administrar. Em vez disso, o engenhoso gnomo Didiê Du Mocó, residente no Ala Mística de Altaforja, distribui Jujubas de Gnomeregan aos viajantes dispostos a entrar na brincadeira com seus truques festivos. Apesar do desastre radioativo que expulsou seu povo de seu reino subterrâneo, os gnomos ainda compartilham com orgulho sua confeitaria singular com o restante da Aliança."},{t="Um Doce para Jacinto",b="Por estar doente e confinado ao orfanato de Ventobravo na Praça da Catedral, Jacinto não pode viajar pelos continentes para pedir doces ele mesmo. A Jujuba de Gnomeregan é uma das quatro guloseimas regionais essenciais — ao lado de quitutes de Ventobravo, Altaforja e Darnassus — que viajantes bondosos recolhem pelas capitais da Aliança para levar as festividades até ele."}},faq={{q="De onde vem a Jujuba de Gnomeregan?",a="Ela é fornecida por Didiê Du Mocó, um gnomo engenhoqueiro localizado no Ala Mística de Altaforja, quando você faz um truque para ele durante o festival de Noturnália.",al={"quem dá jujuba de gnomeregan","como conseguir jujuba","localização da jujuba"}},{q="Por que esse doce não é entregue em Gnomeregan?",a="Gnomeregan foi tomada por troggs e irradiada, forçando os gnomos sobreviventes ao exílio. Muitos, incluindo Didiê Du Mocó, vivem agora ao lado dos anões em Altaforja.",al={"por que altaforja","por que didiê está em altaforja"}},{q="Para que serve esse doce?",a="É um dos quatro doces festivos necessários para concluir a tarefa de Noturnália para Jacinto, um menino órfão doente no orfanato da Praça da Catedral de Ventobravo.",al={"o que a jujuba faz","doce do jacinto"}},{q="Quais outras guloseimas são coletadas junto com ela?",a="Jacinto também pede Nougat de Ventobravo, Balinha de Altaforja e Marzipã de Darnassus, cada um obtido na respectiva capital da Aliança.",al={"outros doces","doces do noturnália"}}},fx={["243db981"]={q="O que é uma Jujuba de Gnomeregan?",a="Uma Jujuba de Gnomeregan é um doce festivo que representa o povo gnomo, distribuído durante o feriado do Horrorífico. Embora nomeado após a maravilha tecnológica perdida de Gnomeregan, o doce é distribuído por gnomos que se refugiam na capital anã de Altaforja, mais notavelmente o mecânico Didiê Du Mocó.",al={"o que é jujuba de gnomeregan","doce jujuba de gnomeregan","conhecimento sobre a jujuba de gnomeregan"}}},fp="18,142,28.371.0,18.281.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="Ferramentas Gnômicas",s="Ferramentas Gnômicas são instrumentos mecânicos complexos recuperados dos navios de guerra naufragados da frota do Grande Almirante Daelin Proudmore na costa de Durotar. A Horda busca esses dispositivos resgatados para estudar a engenharia da Aliança e transformar as vantagens tecnológicas de seus inimigos em benefício próprio.",h="Ferramentas Gnômicas são instrumentos mecânicos complexos recuperados dos navios de guerra naufragados da...",kw={"durotar","engenharia","gar'thok","ferramentas gnômicas","proudmoore","monte navalha","praia do bota-a-pique","bastilha tiragarde"},ang={["faction:Horde"]="Recuperar equipamentos perdidos da Aliança permite à Horda estudar o design inimigo, fazer engenharia reversa de mecanismos estrangeiros e se defender de futuras invasões navais.",["profession:Engineering"]="Esses conjuntos exibem o ofício preciso e intricado dos engenhoqueiros da Aliança, oferecendo percepções valiosas sobre mecanismos de precisão e miniaturização."},sec={{t="Espólios Naufragados",b="Quando o Grande Almirante Daelin Proudmore liderou Kul Tiraz e as forças da Aliança até a costa de Durotar, sua frota transportava vastos suprimentos de equipamentos modernos, incluindo equipamentos sofisticados fabricados por seus aliados gnômicos. Após a destruição da frota de Proudmoore ao longo da Praia do Bota-a-pique, a leste da Bastilha Tiragarde, esses delicados conjuntos mecânicos afundaram sob as ondas. Hoje, caixas de ferramentas à prova d'água permanecem espalhadas entre os mastros apodrecidos e os cascos cobertos de cracas nas águas rasas."},{t="Olhos em Orgrimmar",b="Gar'Thok, feitor do Monte Navalha, encarregou batedores da Horda de resgatar essas ferramentas do túmulo aquático da marinha de Proudmoore. Os orcs reconhecem que humanos e gnomos possuem um artesanato técnico avançado, principalmente em armas de cerco, construção naval e mecânica de precisão. Ao coletar e despachar esses conjuntos em caravanas para os artífices e estudiosos em Orgrimmar, a Horda pretende dissecar as engenhocas da Aliança, aprender a contra-atacar suas máquinas de guerra e adaptar inovações estrangeiras para a sua própria sobrevivência."}},faq={{q="Por que há ferramentas gnômicas na costa de Durotar?",a="Elas eram transportadas a bordo dos navios de guerra da frota do Grande Almirante Daelin Proudmore quando Kul Tiraz atacou Durotar. Quando a armada de Proudmoore foi destruída e afundada ao longo da Praia do Bota-a-pique, a leste da Bastilha Tiragarde, sua carga naval assentou-se no fundo do oceano.",al={"por que ferramentas gnomicas aqui","origem das ferramentas gnomicas","como ferramentas foram parar em durotar"}},{q="Por que a Horda quer essas ferramentas?",a="Gar'Thok, do Monte Navalha, quer que elas sejam resgatadas para que possam ser enviadas a Orgrimmar. A Horda reconhece que os engenheiros da Aliança possuem conhecimentos mecânicos avançados, e estudar suas ferramentas ajuda a Horda a entender como as máquinas inimigas funcionam e a construir equipamentos melhores por conta própria.",al={"por que gar'thok quer ferramentas","uso da horda para ferramentas gnomicas","para que servem as ferramentas"}},{q="Onde as ferramentas são encontradas?",a="Elas ficam guardadas dentro de caixas de ferramentas espalhadas nos destroços submersos e ao redor deles ao longo da Praia do Bota-a-pique, logo a leste da Bastilha Tiragarde, em Durotar. Muitas repousam debaixo d'água ou em cascos despedaçados semissubmersos.",al={"localizacao das ferramentas gnomicas","onde encontrar ferramentas gnomicas","localizacao das caixas de ferramentas gnomicas"}}},fx={bc7dc32b={q="O que são estas Ferramentas Gnômicas?",a="Estes são implementos mecânicos especializados criados pelos gnomos da Aliança. Altamente valorizados por sua precisão e design intrincado, eles representam algumas das engenharias mais sofisticadas de Azeroth. Carregados a bordo dos navios de guerra do Grão-Almirante Proudmoore para manter e reparar o maquinário avançado da Aliança, eles foram espalhados pelo fundo do oceano na costa de Durotar quando sua frota encontrou sua ruína.",al={"o que são ferramentas gnômicas","informações sobre ferramentas gnômicas","o que são as ferramentas gnômicas"}}},fp="13,208,14.447.0,17.457.0,53.225.0,36.204.0,26.188.0"}
P.entries["item:goggles-of-gem-hunting"] = {n="Óculos para Caçar Gemas",s="Os Óculos para Caçar Gemas são um dispositivo gnômico usado para encontrar tesouros sob as águas do Planalto Arathi. Seu encantamento revela gemas enterradas nas rochas do fundo do mar.",h="Os Óculos para Caçar Gemas são um dispositivo gnômico usado para encontrar tesouros sob as águas do Planalto...",kw={"planalto arathi","doutor medeixo","gemas élficas","enseada de faldir","óculos","óculos para caçar gemas","professor bruzundanga","sunken treasure"},ang={["profession:Engineering"]="Como engenheiro, você pode admirar como os óculos do Doutor Medeixo combinam a construção gnômica com o encantamento do Professor Bruzundanga.",["race:Gnome"]="Como gnomo, você pode ver a engenhosidade do Doutor Medeixo em ação num dispositivo feito para encontrar gemas sob o mar."},sec={{t="Sob as ondas",b="Ao largo da Enseada de Faldir, o Doutor Medeixo empresta os Óculos para Caçar Gemas à tripulação do Capitão O'Breen. O Professor Bruzundanga imbui o dispositivo com uma pedra encantada, dando a ele o poder de localizar gemas nas profundezas. O tesouro está submerso há tanto tempo que suas gemas se calcificaram e viraram pedras espessas. Medeixo pede que os óculos sejam devolvidos quando a busca terminar."}},faq={{q="Quem criou os óculos?",a="O Doutor Medeixo construiu os Óculos para Caçar Gemas, e o Professor Bruzundanga os imbuiu com uma pedra encantada.",al={"criador dos óculos","quem os construiu","óculos de medeixo"}},{q="O que os óculos fazem?",a="Os óculos permitem que quem os usa localize gemas sob o mar, mesmo quando elas se calcificaram e viraram pedras espessas.",al={"como os óculos funcionam","encontrar gemas","óculos para caçar gemas"}},{q="Onde os óculos são usados?",a="Os Óculos para Caçar Gemas são usados para vasculhar o fundo do mar ao largo da Enseada de Faldir, no Planalto Arathi.",al={"onde usar os óculos","localização dos óculos","óculos na enseada de faldir"}},{q="Por que o Capitão O'Breen quer as gemas?",a="O Doutor Medeixo pede que você encontre as gemas naufragadas para o Capitão O'Breen. O relato disponível não informa outro motivo para o interesse do Capitão.",al={"capitão quer gemas","por que coletar gemas élficas","tesouro de o'breen"}}},fp="22,175,17.367.0,21.126.0,23.109.0,27.98.0,39.145.0"}
P.entries["item:gold-dust"] = {n="Pó de Ouro",s="Pó de Ouro consiste em pequenos flocos de metal precioso peneirados e acumulados pelos kobolds que infestam as minas da Floresta de Elwynn. Enquanto mineradores comuns procuram veios de minério intactos, oportunistas locais pagam boas moedas a qualquer um disposto a arrancar essas partículas acumuladas das criaturas.",h="Pó de Ouro consiste em pequenos flocos de metal precioso peneirados e acumulados pelos kobolds que infestam...",kw={"elwynn","vailafundo","pó de ouro","vila d'ouro","dentadouro","de jaspe","kobold","remy duas vezes"},ang={["class:Rogue"]="Negociar pó não refinado e não rastreado com figuras suspeitas como Remy \"Duas Vezes\" oferece uma lição prática sobre como o submundo lava riquezas brutas longe dos olhos dos magistrados de Ventobravo.",["profession:Mining"]="Enquanto mineradores buscam veios sólidos de cobre e estanho com picareta e bateia, o pó dos kobolds demonstra que as passagens subterrâneas de Elwynn abrigam jazidas mais ricas do que os levantamentos convencionais sugerem."},sec={{t="Uma Bolsa Cheia de Fragmentos",b="Sob o solo da Floresta de Elwynn, kobolds escavam os túneis subterrâneos das minas Vailafundo e de Jaspe. Em vez de refinar adequadamente o minério que descobrem, essas criaturas semelhantes a ratos costumam acumular pó de ouro bruto diretamente em seus bolsos e bolsas. Essas pequenas lascas reluzentes representam o trabalho exaustivo de coleta subterrânea, facilmente ignorado por sindicatos formais de mineração, mas intensamente cobiçado por mascates locais e receptadores que buscam lucros discretos sem pagar tarifas oficiais de fundição."},{t="O Mercado Negro de Vila d'Ouro",b="No vilarejo de Vila d'Ouro, Remy \"Duas Vezes\" tem o hábito de abordar viajantes em busca de pó de ouro recuperado. Afirmando oferecer o melhor preço da cidade, Remy troca moedas e fichas suspeitas em nome de seus associados anônimos por bolsas de pó bruto. Ao usar mercenários aventureiros para arrancar o ouro diretamente das garras dos kobolds, esses intermediários de beco mantêm as mãos limpas enquanto garantem riquezas irrastreáveis bem debaixo do nariz dos guardas de Ventobravo."}},faq={{q="De onde vem o Pó de Ouro?",a="O Pó de Ouro é carregado por kobolds por toda a Floresta de Elwynn. Mineradores, escavadores, geomantes e seu infame líder Dentadouro recolhem e acumulam as partículas brilhantes enquanto cavam pelas colinas.",al={"como conseguir pó de ouro","saque de pó de ouro","onde encontrar pó de ouro"}},{q="Quais minas têm mais kobolds carregando Pó de Ouro?",a="A Mina Vailafundo, localizada ao sul de Vila d'Ouro, e A Mina de Jaspe, situada a nordeste, estão ambas fortemente infestadas por kobolds que carregam o pó.",al={"onde ficam as minas","melhor mina para pó de ouro","localização das minas"}},{q="Quem compra Pó de Ouro na Floresta de Elwynn?",a="Remy \"Duas Vezes\", um negociante suspeito que opera do lado de fora da Estalagem do Leão Orgulhoso em Vila d'Ouro, compra avidamente bolsas recolhidas de Pó de Ouro em troca de dinheiro e fichas de seus associados.",al={"quem quer pó de ouro","remy duas vezes pó de ouro","entregar pó de ouro"}},{q="Por que os kobolds carregam pó em vez de lingotes?",a="Falta aos kobolds a disciplina e a infraestrutura necessárias para uma fundição adequada. Conforme escavam a rocha com picaretas rústicas, o pó de ouro solto se acumula em seus pertences e nas pequenas bolsas que carregam como bugigangas brilhantes.",al={"por que kobolds têm pó","ouro de kobold"}}},fx={["38570104"]={q="O que é Pó de Ouro?",a="O Pó de Ouro consiste em flocos finos e brutos de ouro precioso minerado pelas infestações de kobolds que espreitam sob a Floresta de Elwynn. Em vez de moeda refinada ou lingotes fundidos, é o resíduo bruto que os kobolds lascam diretamente de veios ricos em lugares como as minas de Fargodeep e Jasperlode.",al={"o que é pó de ouro","item pó de ouro","sobre pó de ouro"}},["4a74ebdb"]={q="Por que Remy \"Duas Vezes\" quer Pó de Ouro?",a="Remy \"Duas Vezes\" em Vila d'Ouro compra pó de ouro bruto para seu próprio comércio e associados sombrios. Kobolds têm pouco senso para fundir lingotes, deixando muita riqueza mineral não rastreada em seus corpos para qualquer um ousado o suficiente para tirar deles e vender.",al={"por que remy quer pó de ouro","por que querer pó de ouro","por que remy duas vezes quer pó de ouro"}}},fp="9,107,22.262.0,24.318.1,31.158.0,53.101.0,36.153.0,44.201.0"}
P.entries["item:golem-oil"] = {n="Golem Oil",s="Golem Oil é coletado dos golens e elementais da Garganta Abrasadora. Velarok Windblade precisa dele para preparar uma tocha para as quatro torres de vigia.",h="Golem Oil é coletado dos golens e elementais da Garganta Abrasadora.",kw={"elementais","flawless flame","golem oil","golens","hearts of flame","garganta abrasadora","torres de vigia","torch of flawless flame","velarok windblade"},sec={{t="Óleo para a Tocha",b="Velarok Windblade pede quatro globos de Golem Oil na Garganta Abrasadora. Ele precisa deles e de quatro Hearts of Flame para criar a Torch of Flawless Flame, destinada a incendiar as quatro torres de vigia. Os golens e elementais destas terras são os primeiros a serem procurados para obter os materiais."}},faq={{q="Para que serve Golem Oil?",a="Velarok Windblade usa quatro globos de Golem Oil e quatro Hearts of Flame para criar a Torch of Flawless Flame.",al={"uso de golem oil","por que coletar golem oil"}},{q="Quem precisa de Golem Oil?",a="Velarok Windblade pede Golem Oil na Garganta Abrasadora para poder criar a Torch of Flawless Flame.",al={"quem quer o óleo","óleo de velarok"}},{q="Onde posso encontrar Golem Oil?",a="Os golens e elementais da Garganta Abrasadora são as primeiras criaturas a serem procuradas por Golem Oil.",al={"onde encontrar golem oil","origem do óleo"}},{q="De quanto Golem Oil Velarok precisa?",a="Velarok Windblade pede quatro globos de Golem Oil.",al={"quantos globos","quantidade de óleo"}},{q="O que a Torch of Flawless Flame deve fazer?",a="A Torch of Flawless Flame deve incendiar as quatro torres de vigia.",al={"torch of flawless flame","propósito da tocha"}}},fp="9,144,17.275.0,22.111.0,20.98.0,27.89.0,37.52.0,48.74.0"}
P.entries["item:golm-fragment"] = {n="Fragmento de Golm",s="O Fragmento de Golm é uma das quatro peças perdidas lascadas da Pedra de Goaz, uma relíquia antiga descoberta no local de escavação dos Pantanal. Recuperado por aventureiros desviando de raptores ferozes, ele ajuda arqueólogos anões a montar inscrições Titânicas misteriosas.",h="O Fragmento de Golm é uma das quatro peças perdidas lascadas da Pedra de Goaz, uma relíquia antiga descoberta...",kw={"local de escavação","pedra de goaz","fragmento de golm","uncovering the past","pantanal","whelgar"},ang={["faction:Alliance"]="Recuperar o fragmento ajuda a Liga dos Exploradores a garantir conhecimento antigo inestimável antes que o local de escavação seja totalmente perdido para os raptores.",["race:Dwarf"]="Para os anões, montar os fragmentos da Pedra de Goaz é vital para descobrir sua ascendência Titânica e a história escondida enterrada em Khaz Modan."},sec={{t="Um pedaço da Pedra de Goaz",b="Descoberto no local de escavação no sul dos Pantanal, o Fragmento de Golm faz parte de uma placa monumental conhecida como Pedra de Goaz. O Prospector Whelgar descobriu a pedra pouco antes de raptores forçarem a Liga dos Exploradores a recuar, mas encontrou sua inscrição cortada em quatro lugares críticos. O Fragmento de Golm foi abandonado em meio à terra e caixotes revirados quando a escavação foi invadida, escondido dentro de uma caixa de relíquia antiga até que exploradores corajosos pudessem recuperá-lo."},{t="Segredos dos Titãs",b="Quando reunido com os fragmentos Ados, Modr e Neru, o Fragmento de Golm completa um texto Titânico enigmático que prenuncia um \"plano divino\" e uma \"profecia condenada\". Remontar a pedra permite que Whelgar decifre linhas que fazem referência a entidades antigas acorrentadas sob a terra, confirmando que o local guarda tradições muito mais antigas e perigosas do que uma simples herança anã."}},faq={{q="Para que serve o Fragmento de Golm?",a="É um dos quatro fragmentos de pedra necessários para o Prospector Whelgar no local de escavação dos Pantanal restaurar a Pedra de Goaz durante a missão Uncovering the Past.",al={"finalidade do fragmento de golm","por que precisar do fragmento de golm","missão do fragmento de golm"}},{q="Onde o Fragmento de Golm pode ser encontrado?",a="Ele é encontrado dentro de relíquias antigas e terra solta espalhadas por todo o local de escavação infestado de raptores nas colinas do sul dos Pantanal.",al={"localização do fragmento de golm","encontrar fragmento de golm","onde está o fragmento de golm"}},{q="O que diz a Pedra de Goaz quando montada?",a="A tradução inicial de Whelgar fala de um plano divino e uma profecia condenada. Ele precisa de todos os quatro fragmentos para continuar a decifrar a escrita Titânica incompleta.",al={"tradução da pedra de goaz","o que diz a placa","tradução de whelgar"}},{q="Quais outros fragmentos são necessários para terminar a pedra?",a="Junto com Golm, você deve recuperar os fragmentos Ados, Modr e Neru para montar completamente a placa.",al={"outros fragmentos da placa","peças da pedra de goaz","quatro fragmentos"}}},fx={["523a83d7"]={q="O que é o Fragmento de Golm?",a="O Fragmento de Golm é uma das quatro peças perdidas quebradas da Pedra de Goaz, uma relíquia antiga descoberta no local de escavação no Pantanal. Ele contém inscrições arcaicas que se encaixam na narrativa enigmática da tabuleta maior.",al={"o que é fragmento de golm","conhecimento sobre fragmento de golm","o que é a peça de golm"}},["890266ad"]={q="De onde vem o Fragmento de Golm e quem o fez?",a="O fragmento originou-se como parte da Pedra de Goaz, esculpida há muito tempo em escrita Titã. Ele foi desenterrado durante a escavação arqueológica anã no local de escavação do Pantanal, antes que raptores hostis invadissem a área e espalhassem suas peças quebradas.",al={"quem fez o fragmento de golm","origem do fragmento de golm","de onde veio o fragmento de golm"}},["6695e471"]={q="Por que o Prospector Whelgar quer o Fragmento de Golm?",a="O Prospector Whelgar precisa do Fragmento de Golm junto com suas peças irmãs para montar a Pedra de Goaz completa. Sem ele, o texto traduzido é cortado abruptamente, deixando detalhes cruciais sobre um plano divino e uma profecia condenada faltando.",al={"por que whelgar precisa do fragmento de golm","quem quer o fragmento de golm","por que procurar pelo fragmento de golm"}}},fp="13,178,25.394.0,21.324.1,35.148.0,37.127.0,44.151.1,52.83.0"}
P.entries["item:goodsteel-ledger"] = {n="Goodsteel Ledger",s="O Goodsteel Ledger é uma cópia de uma lista mantida na Garganta Abrasadora. Ela cita bens que Rugov A. Massoaço quer que levem até ele em Geringontzan.",h="O Goodsteel Ledger é uma cópia de uma lista mantida na Garganta Abrasadora.",kw={"balanced flameberge","geringontzan","goodsteel ledger","rugov a. massoaço","ledger from tanaris","overdue package","garganta abrasadora","solid crystal leg shaft"},sec={{t="O Livro-caixa",b="Perto de uma latrina na Garganta Abrasadora, fica o Goodsteel Ledger, uma cópia destinada a Rugov A. Massoaço, em Geringontzan. Suas páginas listam bens que ele procura em vários lugares. Levar o livro-caixa até ele dá início à busca pelo que está listado."}},faq={{q="O que é o Goodsteel Ledger?",a="O Goodsteel Ledger é uma cópia da lista de bens solicitados por Rugov A. Massoaço, encontrada na Garganta Abrasadora.",al={"goodsteel ledger","lista de goodsteel","ledger from tanaris"}},{q="Onde encontro o livro-caixa?",a="O Goodsteel Ledger fica perto de uma latrina na Garganta Abrasadora.",al={"localização do livro-caixa","onde fica o livro-caixa de goodsteel","livro-caixa garganta abrasadora"}},{q="Quem é Rugov A. Massoaço?",a="Rugov A. Massoaço é um gnomo de Geringontzan que procura bens da Garganta Abrasadora e de outros lugares.",al={"rugov","sujeito goodsteel","quem quer o livro-caixa"}},{q="O que está listado no livro-caixa?",a="O livro-caixa lista Solid Crystal Leg Shafts, um Overdue Package e Goodsteel's Balanced Flameberge.",al={"o que está na lista","itens do livro-caixa","bens que goodsteel quer"}},{q="Para onde devo levá-lo?",a="Leve a cópia do livro-caixa até Rugov A. Massoaço, em Geringontzan, e depois reúna os bens listados nela.",al={"onde levar o livro-caixa","levar livro-caixa para rugov","goodsteel geringontzan"}}},fp="16,131,10.229.0,29.102.0,27.58.0,25.103.0,26.99.0,23.98.0"}
P.entries["item:goodsteel-s-balanced-flameberge"] = {n="Goodsteel's Balanced Flameberge",s="Goodsteel’s Balanced Flameberge é um dos itens que Rugov A. Massoaço procura para seu trabalho em Tanaris. Seu rastro vai da Garganta Abrasadora ao Pântano das Mágoas.",h="Goodsteel’s Balanced Flameberge é um dos itens que Rugov A.",kw={"flameberge","geringontzan","goodsteel’s balanced flameberge","jarquia","rugov a. massoaço","ledger from tanaris","pântano das mágoas"},sec={{t="Um lugar na lista",b="Na Garganta Abrasadora, o livro-caixa de Rugov A. Massoaço lista uma flameberge balanceada entre os bens que ele quer que levem até Geringontzan. Jarquia, um murloc na costa leste do Pântano das Mágoas, carrega a arma. Depois de encontrá-la, você pode levá-la com os outros bens listados até Rugov."}},faq={{q="Quem quer a flameberge?",a="Rugov A. Massoaço, em Geringontzan, quer a flameberge balanceada, que está listada em seu livro-caixa.",al={"quem precisa dela","espada de rugov","quem quer esta arma"}},{q="Onde posso encontrar Goodsteel’s Balanced Flameberge?",a="Jarquia, um murloc na costa leste do Pântano das Mágoas, carrega Goodsteel’s Balanced Flameberge.",al={"onde está a flameberge","encontrar espada de goodsteel","onde fica jarquia"}},{q="Por que querem a flameberge?",a="Rugov A. Massoaço pediu a arma como um dos vários bens listados em seu livro-caixa.",al={"por que rugov precisa dela","para que serve","por que pegar esta espada"}},{q="“Flameberge” está escrito corretamente?",a="O nome usa “flameberge”, embora a palavra geralmente seja escrita “flamberge”.",al={"grafia de flamberge","erro de grafia de flameberge","é uma flamberge"}}},fp="31,162,19.280.0,25.92.0,51.106.0,29.84.0,39.83.0"}
P.entries["item:gordon-s-crate"] = {n="Caixote do Antônio",s="O Caixote do Antônio é uma pesada remessa de armas empacotada na Cidade Baixa para as forças dos Renegados posicionadas na Floresta de Pinhaprata. Ele serve como uma remessa essencial de suprimentos destinada a ser transportada diretamente para a guarnição remota no Sepulcro.",h="O Caixote do Antônio é uma pesada remessa de armas empacotada na Cidade Baixa para as forças dos Renegados...",kw={"tratador de morcegos","necroguarda rodrigo","caixote do antônio","carlos razok","suprimentos de pinhaprata","o sepulcro","cidade baixa"},ang={["faction:Horde"]="A entrega demonstra a crescente integração das rotas de voo dos Renegados, transportando suprimentos e mensageiros rapidamente por Lordaeron disputada.",["race:Undead"]="Cada remessa de lâminas e equipamentos da capital consolida as frágeis fronteiras de Lady Sylvanas na Floresta de Pinhaprata."},sec={{t="Suprimentos para Pinhaprata",b="Manter o domínio dos Renegados sobre a Floresta de Pinhaprata exige um fluxo logístico constante vindo da Cidade Baixa. O Caixote do Antônio contém armamentos destinados a reforçar os defensores do Necroguarda Rodrigo no Sepulcro, garantindo que as sentinelas do entreposto não sejam pegas de surpresa pelos worgens, feras selvagens ou remanescentes humanos à espreita nas matas."},{t="A Rota do Tratador de Morcegos",b="Como as estradas terrestres que saem da capital são perigosas e lentas, remessas valiosas dependem dos tratadores de morcegos da Cidade Baixa. O caixote é entregue a Miguel Garreta, o mestre dos morcegos empoleirado sobre o Distrito Comercial da cidade, que garante a passagem sobre um morcego voador treinado de volta ao poleiro de Carlos Razok no Sepulcro."}},faq={{q="O que há dentro do Caixote do Antônio?",a="O caixote contém armas e suprimentos de combate vitais requisitados da Cidade Baixa para reforçar as sentinelas dos Necroguardas posicionadas na Floresta de Pinhaprata.",al={"conteúdo do caixote do antônio","o que o caixote contém"}},{q="Quem deve receber o Caixote do Antônio?",a="O Necroguarda Rodrigo, no Sepulcro, recebe o caixote. Transportá-lo exige coordenar com o tratador de morcegos da Cidade Baixa, Miguel Garreta, para organizar um voo direto.",al={"quem recebe o caixote do antônio","para onde vai o caixote"}},{q="Por que o caixote é transportado por morcego em vez de um mensageiro a pé?",a="A Floresta de Pinhaprata continua disputada e perigosa. O uso de morcegos treinados sob os cuidados de tratadores como Miguel Garreta e Carlos Razok garante um trânsito aéreo rápido que evita ameaças hostis ao longo das rotas terrestres.",al={"por que enviar o caixote voando","transporte do caixote por morcego"}},{q="Por que Miguel Garreta exige que você visite o Sepulcro primeiro?",a="Os morcegos dos Renegados retornam instintivamente à capital, mas para alcançar bases periféricas como O Sepulcro em segurança, os viajantes precisam estabelecer uma conexão prévia com o tratador local, Carlos Razok, antes que os morcegos possam realizar a viagem.",al={"por que precisa de rota de voo","requisito de voo de morcego"}}},fx={df26763c={q="O que é o Caixote do Antônio?",a="O Caixote do Antônio é um carregamento de armas vitais e suprimentos militares embalado na Cidade Baixa. Ele foi preparado especificamente para ser enviado via tratador de morcegos para o posto avançado remoto dos Renegados no Sepulcro.",al={"caixote do antônio","o que é este caixote"}},e23fc119={q="De onde vem o Caixote do Antônio e quem o fez?",a="O caixote tem origem na Cidade Baixa, onde o Antônio embalou os suprimentos da guarnição antes de providenciar a entrega para os tratadores de morcegos.",al={"de onde veio o caixote do antônio","quem embalou o caixote do antônio","quem fez o caixote do antônio"}},a5301c7a={q="Por que alguém quer o Caixote do Antônio?",a="O Necroguarda Rodrigo e os soldados estacionados no Sepulcro precisam desesperadamente do carregamento. O caixote contém armas necessárias para garantir que os Necroguardas locais que defendem a Floresta de Pinhaprata estejam bem armados e não sejam pegos desprevenidos contra seus inimigos.",al={"por que o caixote do antônio é necessário","por que levar o caixote do antônio para o sepulcro","quem precisa do caixote do antônio"}}},fp="14,148,23.233.0,23.282.0,30.142.0,42.134.0,65.191.0,66.192.0"}
P.entries["item:gordunni-cobalt"] = {n="Gordunni Cobalt",s="No Assentamento Gordunni, brilhos azuis na terra chamam a atenção de Orwin Sheiduztruc. Ele espera que o cobalto enterrado alcance um bom preço.",h="No Assentamento Gordunni, brilhos azuis na terra chamam a atenção de Orwin Sheiduztruc.",kw={"aldeia mojache","cobalto","feralas","gordunni","cobalto gordunni","assentamento gordunni","orwin sheiduztruc","pá de orwin"},sec={{t="Azul na Terra",b="Orwin Sheiduztruc acabou de chegar a Feralas e quer amostras do mineral que os ogros Gordunni enterram no assentamento. Ele lhe empresta sua pá e aponta o caminho ao norte da Aldeia Mojache. Procure o brilho azul entre os montes de terra; Orwin quer o cobalto pelo valor que tem para um comprador."}},faq={{q="Quem quer o Cobalto Gordunni?",a="Orwin Sheiduztruc, na Aldeia Mojache, quer doze amostras de Cobalto Gordunni.",al={"quem quer cobalto","orwin sheiduztruc cobalto","mineral de sheiduztruc"}},{q="Onde posso encontrar Cobalto Gordunni?",a="O cobalto fica em montes de terra no Assentamento Gordunni, ao norte da Aldeia Mojache, em Feralas.",al={"local do cobalto","onde fica o cobalto","terra azul"}},{q="Por que o cobalto está enterrado?",a="Os ogros Gordunni enterram o mineral para impedir que outros ponham as mãos nele.",al={"por que está enterrado","ogros enterram cobalto","terra gordunni"}},{q="Para que Orwin quer o cobalto?",a="Orwin espera encontrar alguém que pague um bom preço pelo cobalto.",al={"por que orwin quer o cobalto","preço do cobalto","vender cobalto"}}},fp="15,127,16.277.0,30.71.0,33.85.0,25.82.0,36.69.0"}
P.entries["item:gordunni-orb"] = {n="Orbe Gordunni",s="O Orbe Gordunni é um poderoso objeto mágico tomado dos Gordunni em Feralas. Sua magia pode ajudar a revelar o propósito da Dark Ceremony.",h="O Orbe Gordunni é um poderoso objeto mágico tomado dos Gordunni em Feralas.",kw={"aldeia mojache","dark ceremony","darkbriar lodge","feralas","gordunni","orbe gordunni","senhor mago","rok orhan","uthel'nay"},ang={["class:Mage"]="Como Mago, você pode entender por que Rok Orhan busca o orbe: sua magia pode ajudar a revelar mais sobre a cerimônia dos Gordunni.",["faction:Horde"]="Como integrante da Horda, você pode ajudar Rok Orhan, da Aldeia Mojache, a saber mais sobre os Gordunni e planejar sua queda."},sec={{t="Orbe de um Mago",b="Rok Orhan, na Aldeia Mojache, busca um Orbe Gordunni para saber mais sobre os Gordunni e sua magia. O orbe é obtido de um dos senhores magos Gordunni. Seu poder pode ajudar a descobrir o propósito da Dark Ceremony."},{t="Em Orgrimmar",b="Rok Orhan envia o Orbe Gordunni para Uthel'nay, na Darkbriar Lodge, em Orgrimmar. Uthel'nay reconhece seu grande poder e avisa que ele é perigoso."}},faq={{q="O que é o Orbe Gordunni?",a="O Orbe Gordunni é um poderoso objeto mágico mantido pelos senhores magos Gordunni em Feralas.",al={"orbe gordunni","que orbe","orbe de mago"}},{q="Quem quer o orbe?",a="Rok Orhan, na Aldeia Mojache, busca o orbe para saber mais sobre os Gordunni e sua magia.",al={"quem quer o orbe","orbe de rok orhan","orbe da aldeia mojache"}},{q="Para que serve o orbe?",a="Rok Orhan espera que o poder do orbe ajude a revelar mais sobre a Dark Ceremony dos Gordunni.",al={"propósito do orbe","por que precisa do orbe","o que ele faz"}},{q="Quem pode examinar o orbe?",a="Uthel'nay, na Darkbriar Lodge, em Orgrimmar, pode contar mais sobre o orbe.",al={"quem examina o orbe","uthel'nay","mago e orbe"}},{q="Por que o orbe é perigoso?",a="Uthel'nay diz que o Orbe Gordunni é muito poderoso e perigoso.",al={"perigo do orbe","orbe perigoso","ele é poderoso"}}},fp="12,141,12.213.0,12.147.0,25.85.0,18.89.0,25.89.0,24.70.0,25.63.0"}
P.entries["item:gorishi-queen-brain"] = {n="Gorishi Queen Brain",s="O Gorishi Queen Brain é um espécime retirado da rainha na Fenda Coleante. Pesquisadores de Geringontzan querem estudá-lo para entender os silitídeos e a força que talvez os controle.",h="O Gorishi Queen Brain é um espécime retirado da rainha na Fenda Coleante.",kw={"geringontzan","gorishi","gorishi hive queen","gorishi queen brain","cristal da colmeia","inteligência maligna","silitídeos","fenda coleante","cratera un’goro"},sec={{t="Uma mente para estudar",b="Pesquisadores de Geringontzan procuram o Gorishi Queen Brain depois que a Gorishi Hive Queen é convocada de sua câmara no sul da Cratera Un’Goro. Eles suspeitam que os silitídeos possam obedecer a uma inteligência maligna e esperam que o cérebro da rainha os ajude a entendê-la. As descobertas podem revelar mais sobre a colmeia do que apenas sobre sua rainha."}},faq={{q="O que é o Gorishi Queen Brain?",a="O Gorishi Queen Brain é um espécime retirado da Gorishi Hive Queen para ser estudado por pesquisadores de Geringontzan.",al={"cérebro da rainha","cérebro gorishi","o que é este cérebro"}},{q="De onde vem o Gorishi Queen Brain?",a="Ele vem da Gorishi Hive Queen, na Fenda Coleante, no sul da Cratera Un’Goro.",al={"de onde vem o cérebro","local do cérebro da rainha","rainha gorishi"}},{q="Por que os pesquisadores querem o cérebro da rainha?",a="Pesquisadores de Geringontzan esperam que o cérebro os ajude a entender os silitídeos e a inteligência maligna que, segundo suspeitam, talvez os controle.",al={"por que precisam do cérebro","para que serve o cérebro","estudar a rainha"}},{q="Como a Gorishi Hive Queen é convocada?",a="A Gorishi Queen Lure, usada em um cristal nos criadouros da colmeia, deve atrair a rainha para fora.",al={"convocar a rainha","isca gorishi","como tirar a rainha de lá"}},{q="A rainha é a única presença silitídea?",a="Os pesquisadores duvidam que a Gorishi Hive Queen represente toda a presença dos silitídeos.",al={"mais silitídeos","silitídeos ainda estão aqui","isso é tudo"}}},fp="19,174,15.327.0,32.110.0,45.88.0,42.137.0,39.95.0,40.97.0"}
P.entries["item:gorishi-queen-lure"] = {n="Gorishi Queen Lure",s="A Gorishi Queen Lure é uma ferramenta usada para atrair a Gorishi Hive Queen para fora de sua câmara na Cratera Un’Goro. Pesquisadores de Geringontzan precisam do cérebro da rainha para estudar os silithid.",h="A Gorishi Queen Lure é uma ferramenta usada para atrair a Gorishi Hive Queen para fora de sua câmara na...",kw={"geringontzan","gorishi","gorishi hive","gorishi queen lure","cristal da colmeia","rainha","cérebro da rainha","silithid","cratera un’goro"},sec={{t="Uma colmeia agitada",b="Na Gorishi Hive da Cratera Un’Goro, acredita-se que um cristal sintonize os silithid em toda a rede da colmeia. A isca é usada nesse cristal para atrair a rainha. Pesquisadores de Geringontzan querem estudar o cérebro dela, pois temem que uma inteligência maligna possa controlar os silithid."}},faq={{q="O que a Gorishi Queen Lure faz?",a="A Gorishi Queen Lure é usada em um cristal na Gorishi Hive para atrair a Gorishi Hive Queen para fora.",al={"uso da gorishi queen lure","finalidade da gorishi queen lure","como a isca funciona"}},{q="Onde a isca é usada?",a="A isca é usada em um cristal nos viveiros da Gorishi Hive, na Cratera Un’Goro.",al={"onde usar a isca da rainha","local da isca","onde fica a gorishi hive"}},{q="Quem forneceu a isca?",a="Pesquisadores de Geringontzan fornecem a Gorishi Queen Lure para que a rainha possa ser atraída para estudo.",al={"quem forneceu a isca","origem da isca","isca de geringontzan"}},{q="Por que os pesquisadores querem o cérebro da rainha?",a="Os pesquisadores precisam do cérebro da Gorishi Hive Queen para estudar os silithid e investigar se uma inteligência maligna os controla.",al={"por que querem o cérebro da rainha","motivo para obter o cérebro gorishi","para que serve o cérebro"}},{q="O que é o cristal na colmeia?",a="Acredita-se que o cristal sintonize os silithid em toda a rede da colmeia.",al={"cristal da colmeia","cristal dos silithid","função do cristal"}}},fp="18,175,14.272.0,36.99.0,23.86.0,22.96.0,42.134.0,32.73.0"}
P.entries["item:grape-manifest"] = {n="Manifesto da Uva",s="O Manifesto da Uva é um livro-razão manuscrito que acompanha a colheita do vinhedo de Madel Quintana no Vale de Vila Norte. Ele documenta a recuperação de frutas frescas após bandidos locais invadirem os campos, destinadas às adegas da Abadia de Vila Norte.",h="O Manifesto da Uva é um livro-razão manuscrito que acompanha a colheita do vinhedo de Madel Quintana no Vale...",kw={"irmão neals","elwynn","manifesto da uva","madel quintana","abadia de vila norte","vinhedo","vinho"},ang={["profession:Cooking"]="Para os cozinheiros, o manifesto representa o equilíbrio delicado entre a produção do campo e as despensas da abadia, mostrando como os ingredientes locais sustentam toda uma comunidade monástica.",["race:Human"]="O documento destaca os primeiros conflitos no coração de Ventobravo, onde até mesmo a vida monástica e as colheitas simples exigem defesa armada contra foras da lei errantes."},sec={{t="Um Registro da Colheita",b="A Abadia de Vila Norte há muito se sustenta com a agricultura regional, incluindo os vinhedos verdejantes cultivados por agricultores locais como Madel Quintana. Quando os bandidos Defias invadiram o vale e tomaram a colheita, o estoque de frutas frescas e ingredientes fermentáveis da abadia foi colocado em risco. O Manifesto da Uva serve como confirmação oficial de que os caixotes foram recuperados dos campos. Ele detalha a quantidade de uvas salvas para que os intendentes da abadia possam equilibrar seus mantimentos e preparar os barris para a fermentação."},{t="O Adegueiro da Abadia",b="O Irmão Neals supervisiona a comida e a bebida de Vila Norte, mantendo um apreço especial por provar as safras da abadia na tranquilidade elevada da torre do sino. Para ele, receber o manifesto não é apenas burocracia administrativa; garante que os monges e os recrutas visitantes não passem sede. Para os irmãos devotos da abadia, cada alqueire salvo é celebrado tanto como uma vitória logística quanto como uma bênção serena da Luz Sagrada."}},faq={{q="O que é o Manifesto da Uva?",a="É um documento de inventário escrito por Madel Quintana que registra a colheita recuperada de seu vinhedo invadido. Ele acompanha o volume de uvas frescas entregues à Abadia de Vila Norte.",al={"o que é o manifesto da uva","item manifesto da uva"}},{q="Quem recebe o manifesto?",a="O Irmão Neals o recebe. Ele supervisiona os estoques de comida e vinho da abadia e geralmente pode ser encontrado degustando safras no alto da torre do sino da Abadia de Vila Norte.",al={"quem recebe o manifesto da uva","para quem entrego o manifesto da uva","onde vai o manifesto da uva"}},{q="Por que as uvas estavam em perigo?",a="Bandidos Defias atacaram o Vale de Vila Norte e expulsaram Madel Quintana de seu vinhedo, ameaçando a colheita e cortando o suprimento de frutas frescas da abadia até a intervenção dos recrutas.",al={"por que as uvas precisavam ser salvas","bandidos do vinhedo","o que aconteceu com a colheita de madel"}},{q="O que o Irmão Neals faz com as uvas?",a="O Irmão Neals as utiliza para reabastecer as reservas de alimentos da abadia e fermentar o vinho fresco de Vila Norte, que abastece tanto a irmandade residente quanto os defensores visitantes.",al={"para que a uva é usada","vinho da abadia"}}},fx={a2f30a46={q="De onde vem o Manifesto da Uva e quem o fez?",a="O manifesto é elaborado por Milly Osworth, uma fazendeira que trabalha nos vinhedos do Vale de Vila Norte. Depois que você a ajuda a expulsar os bandidos Defias que invadiram seus campos e recuperar sua colheita, ela prepara este registro para documentar o rendimento salvo.",al={"quem escreveu manifesto da uva","de onde veio o manifesto da uva","origem do manifesto da uva"}},cbb35726={q="Por que o Manifesto da Uva é necessário?",a="Irmão Neals gerencia os estoques de comida e bebida para a Abadia de Vila Norte. Milly envia o manifesto para notificá-lo de que sua colheita foi resgatada dos bandidos, permitindo que os vinicultores da abadia contem com frutas frescas para prensar seu vinho.",al={"por que irmão neals quer o manifesto da uva","propósito do manifesto da uva","por que precisar do manifesto da uva"}}},fp="14,104,23.282.0,20.303.0,27.142.0,26.154.0,30.162.0,43.168.0"}
P.entries["item:gray-bear-tongue"] = {n="Língua de Urso Cinzento",s="A Língua de Urso Cinzento é um reagente bruto colhido dos ursos selvagens que vagam por Contraforte de Eira dos Montes. Ela é procurada pela Real Sociedade de Boticários na Serraria Tarren para servir como componente biológico em suas toxinas experimentais.",h="A Língua de Urso Cinzento é um reagente bruto colhido dos ursos selvagens que vagam por Contraforte de Eira...",kw={"boticário lindolfo","big samras","elixir do sofrimento","língua de urso cinzento","contraforte de eira dos montes","real sociedade de boticários","serraria tarren"},ang={["race:Undead"]="Obter componentes orgânicos da fauna local auxilia diretamente a missão da Real Sociedade de Boticários de criar novas pragas contra os vivos."},sec={{t="Pesquisas Boticárias em Eira dos Montes",b="A natureza selvagem e indomada ao redor da Serraria Tarren é rica em fauna nativa, incluindo diversas variedades de robustos ursos cinzentos. Embora esses predadores naturais representem uma ameaça constante aos viajantes, os Renegados os veem como uma fonte colhível de componentes alquímicos brutos. O Boticário Lindolfo estuda a vida selvagem local para isolar agentes orgânicos potentes, utilizando o espesso tecido muscular e os fluidos das línguas de urso cinzento como ingrediente-base para preparar soluções letais, como o Elixir do Sofrimento."}},faq={{q="Quem quer línguas de urso cinzento?",a="O Boticário Lindolfo, estabelecido no entreposto dos Renegados na Serraria Tarren, em Contraforte de Eira dos Montes, procura essas línguas para produzir agentes letais experimentais.",al={"quem precisa de línguas de urso","boticário lindolfo línguas","onde entregar língua de urso"}},{q="Para que o boticário está usando essas línguas?",a="Lindolfo está desenvolvendo uma mistura letal conhecida como Elixir do Sofrimento, criada para ajudar a assolar as populações humanas vivas de Eira dos Montes. As línguas servem como um dos principais agentes orgânicos, ao lado do Pus de Rastejante.",al={"por que lindolfo quer línguas","utilidade da língua de urso","ingredientes do elixir do sofrimento"}},{q="Quais criaturas concedem essas línguas?",a="Elas podem ser obtidas de qualquer um dos ursos cinzentos locais que vagam por Contraforte de Eira dos Montes, incluindo ursos cinzentos comuns, ursos cinzentos anciãos, ursos cinzentos cruéis e a fera notória Big Samras.",al={"onde caem línguas de urso","quais ursos têm línguas","ursos de eira dos montes"}}},fx={["57051fe5"]={q="O que é Língua de Urso Cinzento?",a="É exatamente o que parece: uma língua recém-cortada tirada de um dos ursos cinzentos selvagens que rondam o Contraforte de Eira dos Montes. Embora pouco atraente para a maioria dos viajantes, alquimistas e pesquisadores entre os Renegados valorizam tecidos animais por suas propriedades químicas específicas ao formular novas poções.",al={"o que é língua de urso cinzento","item língua de urso cinzento","o que são línguas de urso cinzento"}},["4de594f1"]={q="De onde vem uma Língua de Urso Cinzento?",a="Essas línguas são colhidas diretamente dos ursos cinzentos que rondam as florestas e colinas ao redor da Serraria Tarren no Contraforte de Eira dos Montes. Caçadores podem obtê-las de ursos cinzentos comuns, espécimes anciãos, variantes cruéis ou feras notáveis como Big Samras.",al={"origem da língua de urso cinzento","de onde vêm as línguas de urso cinzento","quem deixa cair línguas de urso cinzento"}}},fp="16,112,32.187.0,28.112.0,47.207.0,35.162.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-i"] = {n="Grande Espinhaço: Veredas - Chapter I",s="Páginas dispersas de Grande Espinhaço: Veredas foram reunidas no Capítulo I. Barnil está juntando os capítulos do manuscrito de Master Nesingwary.",h="Páginas dispersas de Grande Espinhaço: Veredas foram reunidas no Capítulo I.",kw={"barnil","capítulo i","capítulo um","grande espinhaço: veredas","manuscrito","master nesingwary","páginas dispersas","selva do espinhaço"},sec={{t="Páginas dispersas",b="Uma rajada de vento atravessou o acampamento de Master Nesingwary e espalhou as páginas do manuscrito pela Selva do Espinhaço. Barnil reuniu muitas, mas ainda faltavam páginas dos quatro capítulos. Este capítulo faz parte do livro que Barnil está montando, e ele está pronto para organizar as páginas quando forem encontradas."}},faq={{q="O que é o Capítulo I?",a="O Capítulo I é uma das quatro partes do manuscrito disperso de Master Nesingwary, Grande Espinhaço: Veredas.",al={"grande espinhaço veredas capítulo um","livro capítulo i","o que é este capítulo"}},{q="Quem é Barnil?",a="Barnil está ajudando a montar o manuscrito de Master Nesingwary e pede os capítulos quando estiverem completos.",al={"quem é barnil","quem quer as páginas","manuscrito de barnil"}},{q="Por que as páginas estão espalhadas?",a="Uma forte rajada de vento passou pelo acampamento de Master Nesingwary e espalhou páginas do manuscrito pela selva.",al={"páginas levadas pelo vento","por que faltam páginas","páginas do manuscrito"}},{q="Quem escreveu Grande Espinhaço: Veredas?",a="Master Nesingwary é o autor de Grande Espinhaço: Veredas, um romance que Barnil está ajudando a montar.",al={"livro de nesingwary","quem escreveu grande espinhaço veredas","manuscrito de master nesingwary"}}},fp="40,160,15.305.0,18.115.0,14.109.0,28.117.0,43.104.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-ii"] = {n="Grande Espinhaço: Veredas - Chapter II",s="O Capítulo II é uma das quatro partes do manuscrito perdido do Mestre Nesingwary, Grande Espinhaço: Veredas. Suas páginas precisam ser reunidas para que Barnil organize os capítulos e devolva o livro a Nesingwary.",h="O Capítulo II é uma das quatro partes do manuscrito perdido do Mestre Nesingwary, Grande Espinhaço: Veredas.",kw={"barnil","capítulo 2","capítulo ii","grande espinhaço: veredas","manuscrito","nesingwary","páginas espalhadas","selva do espinhaço"},sec={{t="Páginas espalhadas",b="Barnil havia reunido a maior parte do manuscrito quando uma rajada de vento passou pelo acampamento do Mestre Nesingwary. As páginas do Capítulo II se espalharam pela Selva do Espinhaço junto com as demais. Você pode ajudar Barnil a pôr os quatro capítulos em ordem e depois levá-los de volta para ele."}},faq={{q="O que é o Capítulo II?",a="O Capítulo II é uma parte do manuscrito do Mestre Nesingwary, Grande Espinhaço: Veredas.",al={"capítulo 2","grande espinhaço veredas capítulo ii"}},{q="Quem está reunindo os capítulos?",a="Barnil está recolhendo e organizando os capítulos espalhados para o Mestre Nesingwary.",al={"quem quer as páginas","páginas de barnil"}},{q="Por que as páginas estão espalhadas?",a="Uma forte rajada de vento passou pelo acampamento do Mestre Nesingwary e espalhou as páginas do manuscrito pela selva.",al={"o que aconteceu com as páginas","vento espalhou as páginas"}},{q="O que devo fazer com os capítulos?",a="Reúna os quatro capítulos e leve-os de volta para Barnil, para que ele possa organizá-los para o Mestre Nesingwary.",al={"onde devolver os capítulos","do que barnil precisa"}},{q="Quem escreveu Grande Espinhaço: Veredas?",a="O Mestre Nesingwary é o autor de Grande Espinhaço: Veredas.",al={"livro de nesingwary","romance do mestre nesingwary"}}},fp="41,210,15.253.0,19.93.0,30.81.0,28.116.0,35.97.0,43.68.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iii"] = {n="Grande Espinhaço: Veredas - Chapter III",s="O Capítulo III é uma das quatro partes espalhadas do manuscrito do Mestre Nesingwary, Grande Espinhaço: Veredas. Barnil está reunindo as páginas no acampamento na Selva do Espinhaço.",h="O Capítulo III é uma das quatro partes espalhadas do manuscrito do Mestre Nesingwary, Grande Espinhaço...",kw={"barnil","capítulo iii","capítulo três","grande espinhaço: veredas","manuscrito","nesingwary","páginas espalhadas","selva do espinhaço"},sec={{t="Páginas espalhadas",b="Uma rajada passou pelo acampamento do Mestre Nesingwary na Selva do Espinhaço e espalhou as páginas do manuscrito pela selva. Barnil reuniu a maioria delas, mas os quatro capítulos continuam incompletos. Ele está recolhendo as páginas para que o manuscrito possa ser reorganizado."}},faq={{q="O que é o Capítulo III?",a="O Capítulo III é uma das quatro partes do manuscrito espalhado do Mestre Nesingwary, Grande Espinhaço: Veredas.",al={"capítulo três","grande espinhaço veredas capítulo 3"}},{q="Quem está recolhendo as páginas?",a="Barnil está reunindo as páginas espalhadas e organizando os capítulos para o Mestre Nesingwary.",al={"quem quer as páginas","páginas de barnil"}},{q="Por que as páginas estão espalhadas?",a="Uma forte rajada de vento passou pelo acampamento do Mestre Nesingwary e espalhou as páginas do manuscrito pela selva.",al={"o que aconteceu com as páginas","vento espalhou páginas"}},{q="Como se chama o manuscrito?",a="O manuscrito se chama Grande Espinhaço: Veredas.",al={"livro de nesingwary","livro grande espinhaço veredas"}}},fp="42,178,15.266.0,20.117.0,28.90.0,28.114.0,30.58.0"}
P.entries["item:green-hills-of-stranglethorn-chapter-iv"] = {n="Grande Espinhaço: Veredas - Chapter IV",s="Na Selva do Espinhaço, Barnil precisa reunir os capítulos espalhados do manuscrito de Master Nesingwary e colocá-los em ordem. O Capítulo IV é uma das quatro partes necessárias para completar o livro.",h="Na Selva do Espinhaço, Barnil precisa reunir os capítulos espalhados do manuscrito de Master Nesingwary e...",kw={"barnil","capítulo quatro","capítulo iv","grande espinhaço: veredas","manuscrito","master nesingwary","páginas espalhadas","selva do espinhaço"},sec={{t="Páginas espalhadas",b="Uma rajada atravessou o acampamento de Master Nesingwary e espalhou páginas do romance dele pela selva. Barnil reuniu a maioria, mas ainda é preciso encontrar as páginas que faltam e organizá-las em quatro capítulos. O Capítulo IV deve ser reunido aos outros três antes que o manuscrito possa ser devolvido a Barnil."}},faq={{q="O que é o Capítulo IV?",a="O Capítulo IV é um dos quatro capítulos do romance de Master Nesingwary, Grande Espinhaço: Veredas.",al={"capítulo quatro","grande espinhaço veredas capítulo iv","livro capítulo quatro"}},{q="Quem precisa deste capítulo?",a="Barnil está reunindo os capítulos do manuscrito de Master Nesingwary e pede que o entreguem quando os quatro estiverem completos.",al={"quem quer o capítulo iv","para quem entregar o capítulo quatro","páginas de barnil"}},{q="Por que as páginas estão espalhadas?",a="Uma forte rajada de vento atravessou o acampamento de Master Nesingwary e espalhou páginas do manuscrito dele pela selva.",al={"por que há páginas por toda parte","o que aconteceu com o livro","o vento espalhou as páginas"}},{q="Sobre o que é Grande Espinhaço: Veredas?",a="É um romance de Master Nesingwary. Os capítulos reunidos devem completar o manuscrito.",al={"romance de nesingwary","livro grande espinhaço veredas","o que é o manuscrito"}}},fp="41,192,15.301.0,19.104.0,23.114.0,28.119.0,47.95.0"}
P.entries["item:gregor-s-remains"] = {n="Restos Mortais de Gregor",s="Os Restos Mortais de Gregor são os ossos físicos recuperados de Gregor Agamand, escravizado pelo Flagelo. Antigo membro da dinastia mais rica das Clareiras de Tirisfal, seus restos mortais são procurados por um antigo trabalhador do moinho, ansioso para acertar contas antigas vindas de além-túmulo.",h="Os Restos Mortais de Gregor são os ossos físicos recuperados de Gregor Agamand, escravizado pelo Flagelo.",kw={"agamand","montalvo","eurico","mortes na família","farthing","gregor","moinhos","restos mortais","flagelo"},ang={["faction:Horde"]="Expurgar os Moinhos dos Agamand desfere um golpe direto contra bolsões remanescentes do Flagelo que ameaçam a segurança das Clareiras de Tirisfal.",["race:Undead"]="A tragédia dos Agamand reflete o destino de muitos Renegados: pessoas comuns traídas pelo orgulho da nobreza e abandonadas aos horrores da Praga."},sec={{t="Um Legado de Ruína",b="Antes da Terceira Guerra, a família Agamand possuía imensa riqueza e vastas extensões de terra pelo norte das Clareiras de Tirisfal. Quando o Flagelo invadiu Lordaeron, os patriarcas escolheram o orgulho em vez da fuga, fortificando os moinhos da família e convencendo seus leais trabalhadores a montar uma resistência desesperada contra os mortos-vivos. A defesa fracassou completamente. A propriedade foi tomada, e aqueles que resistiram foram trucidados e erguidos na morte-vinda. Gregor Agamand tornou-se mais um lacaio descerebrado a serviço do Lich Rei, assombrando os mesmos moinhos que sua família outrora governou."},{t="O Preço da Vingança",b="Para os sobreviventes que se libertaram do domínio do Lich Rei para se juntar aos Renegados, a lembrança daquela defesa fatídica permanece como uma ferida amarga. Eurico Palhares, um antigo trabalhador do moinho estabelecido em Montalvo, culpa a arrogância dos Agamand por prender sua alma em eterna podridão. Coletar os restos mortais de Gregor oferece a Farthing uma medida de retribuição pessoal, encerrando o capítulo sobre um mestre que conduziu seus servos direto para a danação."}},faq={{q="Quem foi Gregor Agamand?",a="Gregor Agamand foi um membro proeminente da dinastia Agamand, a família de proprietários de terras mais rica das Clareiras de Tirisfal antes da Terceira Guerra. Quando a Praga da Morte-vida chegou, ele e sua família escolheram fortificar sua propriedade em vez de fugir, o que levou ao massacre e à reanimação de todos ali dentro.",al={"história de gregor","quem é gregor","gregor agamand"}},{q="Por que Eurico Palhares quer os Restos Mortais de Gregor?",a="Eurico Palhares era um trabalhador do moinho empregado pelos Agamand em vida. Ele guarda profundo rancor da família por ter convencido os trabalhadores a ficar e lutar contra o Flagelo, um erro que condenou a todos à morte-vida. Ter os restos mortais de Gregor entregues a ele serve como uma vingança há muito esperada.",al={"por que eurico quer restos mortais","rancor de eurico palhares","por que coletar ossos de gregor"}},{q="Onde são encontrados os Restos Mortais de Gregor?",a="Os restos mortais são recuperados da forma reanimada de Gregor Agamand nos Moinhos dos Agamand, situados nas colinas ao norte das Clareiras de Tirisfal.",al={"onde encontrar gregor","localização de gregor","moinhos dos agamand gregor"}},{q="Os Agamand fazem parte dos Renegados?",a="Não. Ao contrário dos Renegados que se libertaram sob o comando da Rainha Sylvana, Gregor Agamand e seus parentes continuam sendo servos descerebrados acorrentados à vontade do Flagelo.",al={"gregor é renegado","os agamand são do flagelo","quem controla gregor"}}},fx={["6dd1de2a"]={q="O que são Restos Mortais de Gregor?",a="São os restos físicos de Gregor Agamand, um dos herdeiros da proeminente dinastia Agamand. Após sucumbir à Praga da Não-Morte, Gregor se ergueu como um lacaio sem mente do Flagelo, assombrando as ruínas dos moinhos outrora prósperos de sua família até ser derrotado permanentemente.",al={"o que são restos mortais de gregor","item restos mortais de gregor","o que é restos mortais de gregor"}},["45ae8d93"]={q="De onde vêm os Restos Mortais de Gregor?",a="Estes restos são o que sobrou de Gregor Agamand depois que ele foi derrotado nos Moinhos dos Agamand, na parte oeste das Clareiras de Tirisfal. Quando o Flagelo varreu Lordaeron, sua família fortificou sua propriedade e exortou seus trabalhadores a resistir e lutar, apenas para que todos fossem massacrados e erguidos na não-morte.",al={"origem restos mortais de gregor","quem fez restos mortais de gregor","de onde vieram os restos mortais de gregor"}}},fp="16,123,16.482.0,22.346.0,23.279.0,48.232.0,33.109.0,38.134.0"}
P.entries["item:grelin-s-report"] = {n="Relatório de Grolin",s="O Relatório de Grolin é um despacho escrito por Grolin Barbabranca detalhando a situação dos trolls Jubafria no Vale Cristálgida. Confiado a um aventureiro em vez de a um aprendiz novato, ele serve como o elo oficial entre os batedores que guardam Sidermar e Senir Barbabranca estacionado em Kharanos.",h="O Relatório de Grolin é um despacho escrito por Grolin Barbabranca detalhando a situação dos trolls Jubafria...",kw={"vale cristálgida","grolin barbabranca","relatório de grolin","senado de altaforja","kharanos","montanhista thalos","senir barbabranca"},ang={["race:Dwarf"]="Carregar este relatório é a passagem de um anão dos campos de treinamento seguros de Cristálgida para a defesa mais ampla do coração de Dun Morogh e o serviço a Altaforja.",["race:Gnome"]="Entregar a mensagem de Grolin permite que os refugiados gnomos provem seu valor aos montanhistas anões enquanto atravessam as passagens montanhosas compartilhadas de Dun Morogh."},sec={{t="Um despacho além dos troggs",b="Escrito após observar os trolls Jubafria no Vale Cristálgida, o Relatório de Grolin conclui que eles não representam uma grande ameaça e podem ser lidados pelos Montanhistas já posicionados lá e por mercenários pagos com fundos do Senado. Em vez de confiar informações cruciais a seu aprendiz desajeitado, Grolin recruta um viajante capaz para levar o documento através do Caminho de Cristálgida infestado de troggs. O papel funciona como um salvo-conduto oficial pelo bloqueio do Montanhista Thalos, provando que o portador viaja em missão urgente para a vasta extensão nevada de Dun Morogh."},{t="Provocando desconforto em Kharanos",b="Quando entregue a Senir Barbabranca na Destilaria Cervaforte em Kharanos, o relatório fornece atualizações de campo cruciais destinadas a Altaforja. Senir observa com resignação divertida que seu irmão invocou o nome do Rei Magni Barbabronze liberalmente por todo o texto. Grolin afirma ter a aprovação do Rei para a ação, e Senir espera que esse apelo à autoridade real provoque certo desconforto no Senado de Altaforja."}},faq={{q="Qual é o propósito do Relatório de Grolin?",a="O relatório leva a avaliação de Grolin Barbabranca sobre os trolls Jubafria do Vale Cristálgida para seu irmão Senir em Kharanos. Ele assegura à liderança fora do vale que os trolls não representam uma grande ameaça e podem ser contidos pelos Montanhistas locais e por mercenários financiados pelo Senado.",al={"o que é o relatório de grolin","por que enviar o relatório","objetivo do relatório de grolin"}},{q="Por que Grolin não pode entregá-lo pessoalmente?",a="Grolin permanece posicionado no Vale Cristálgida monitorando os trolls. Embora tenha considerado inicialmente enviar seu aprendiz, a perigosa jornada através do túnel infestado de troggs o levou a entregar os papéis vitais a um aventureiro testado em batalha.",al={"por que não entregar pessoalmente","por que confiar a um aventureiro"}},{q="Por que o Montanhista Thalos deixa você passar com o relatório?",a="O Montanhista Thalos guarda o túnel que sai do Vale Cristálgida para manter os civis a salvo dos troggs ferozes. Possuir o Relatório de Grolin prova que você está viajando em assuntos urgentes de defesa dos anões, convencendo Thalos a conceder passagem.",al={"por que thalos me deixa passar","bloqueio do túnel","troggs do caminho de cristálgida"}},{q="Por que o Senado de Altaforja fica incomodado com o relatório?",a="Senir Barbabranca nota que Grolin invocou o nome do Rei Magni liberalmente por todo o documento. Ignorar as sutilezas diplomáticas habituais para exigir a atenção real frequentemente irrita os burocratas do Senado de Altaforja, mesmo que os irmãos concordem que os políticos precisam de um choque de realidade.",al={"por que o senado está bravo","provocar desconforto","reação de senir"}}},fx={cdcce173={q="O que é o Relatório de Grolin?",a="É um despacho escrito por Grolin Barbabranca no Vale Cristálgida, endereçado ao seu irmão, Senir Barbabranca, em Kharanos. Ele detalha observações locais e assuntos urgentes no vale, embora Grolin tenha invocado o nome do Rei Magni Barbabronze liberalmente o suficiente em suas páginas para causar controvérsia entre os senadores lá em Altaforja.",al={"o que é o relatório de grolin","relatório de grolin"}},["9a092709"]={q="De onde vem o Relatório de Grolin e quem o fez?",a="O documento foi redigido por Grolin Barbabranca enquanto estava estacionado no Vale Cristálgida. Em vez de confiá-lo ao seu aprendiz, Grolin decidiu colocá-lo nas mãos de um viajante capaz para garantir sua jornada segura para o leste, através do túnel infestado de troggs que leva à maior parte de Dun Morogh.",al={"quem escreveu o relatório de grolin","de onde veio o relatório de grolin","quem fez o relatório de grolin"}},["6be6ebf1"]={q="Por que alguém quer o Relatório de Grolin?",a="Seu irmão, Senir Barbabranca, está esperando pelo despacho em Kharanos para coordenar suas descobertas antes de encaminhar seus relatórios combinados para Altaforja. O documento também é vital para você pessoalmente: apresentar prova dos negócios oficiais de Barbabranca é o único motivo pelo qual o Montanhista Thalos permite que você passe pelo perigoso túnel infestado de troggs saindo do Vale Cristálgida.",al={"por que o relatório de grolin é necessário","por que senir quer o relatório de grolin"}}},fp="15,155,26.493.0,29.370.0,39.233.0,36.218.0,57.195.0,50.236.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="Diário de Grolin Barbabranca",s="O Diário de Grolin Barbabranca é um caderno de campo pessoal mantido pelo batedor anão Grolin Barbabranca no Vale Cristálgida. Contendo anotações cruciais sobre a atividade dos trolls Jubafria locais, o diário foi roubado pelo brutamontes Jubafria Grik'nir the Cold e arrastado para The Troll Cave no Vale Cristálgida.",h="O Diário de Grolin Barbabranca é um caderno de campo pessoal mantido pelo batedor anão Grolin Barbabranca no...",kw={"vale cristálgida","dun morogh","fortaleza jubafria","grolin barbabranca","grik'nir the cold","senir barbabranca","diário roubado"},ang={["race:Dwarf"]="Recuperar este diário resguarda informações cruciais da inteligência dos anões sobre a ameaça dos Jubafria, que avançam contra os próprios Portões de Altaforja em suas áreas de treinamento."},sec={{t="O Livro-razão de um Batedor",b="Enquanto observava os movimentos agressivos dos trolls Jubafria perto do Vale Cristálgida, Grolin Barbabranca registrou diligentemente suas descobertas neste caderno encadernado em couro. O documento contém suas observações de campo brutas a respeito da força, organização e nível de ameaça representados pelos trolls do inverno nativos. No entanto, durante um confronto ou emboscada, o diário foi arrebatado por Grik'nir the Cold — um brutamontes troll com muitas marcas —, forçando Grolin a recrutar aventureiros que passavam por ali para entrar em The Troll Cave e recuperá-lo antes que seu relatório pudesse ser finalizado."},{t="Despacho para Senir",b="Uma vez recuperadas das garras de Grik'nir, as anotações dentro deste diário desgastado oferecem a Grolin tranquilidade suficiente para avaliar a ameaça dos trolls do Vale Cristálgida como temporariamente contida. Usando os apontamentos recuperados, Grolin finaliza seu despacho por escrito sobre a revolta dos Jubafria, que é posteriormente lacrado e confiado a mensageiros com destino ao seu irmão Senir Barbabranca, estacionado mais além, em Dun Morogh."}},faq={{q="Quem roubou o diário de Grolin Barbabranca?",a="O diário foi levado por Grik'nir the Cold, um proeminente brutamontes troll Jubafria com muitas marcas que reside nas profundezas de The Troll Cave no Vale Cristálgida.",al={"quem pegou o diário","quem está com o diário de grolin","ladrão do diário de grolin"}},{q="O que está escrito no diário?",a="O diário contém as anotações diretas de reconhecimento de Grolin Barbabranca sobre os trolls Jubafria locais, o nível de ameaça deles e a situação de segurança no Vale Cristálgida.",al={"conteúdo do diário","o que há dentro do diário","anotações de grolin barbabranca"}},{q="O que acontece depois que o diário é recuperado?",a="Após recuperar seu caderno, Grolin usa suas anotações para escrever um relatório de inteligência finalizado sobre a situação dos trolls, o qual ele pede a um aventureiro para entregar ao seu irmão, Senir Barbabranca.",al={"o que grolin faz com o diário","depois de the stolen journal"}},{q="Por que este diário é tão importante para Grolin?",a="Sem o seu caderno, Grolin não consegue compilar um relatório de reconhecimento preciso sobre a revolta dos Jubafria para as autoridades anãs e para seu irmão Senir, deixando incertas as defesas do Vale Cristálgida.",al={"por que grolin quer recuperá-lo","importância do diário"}}},fx={["15978139"]={q="O que é o Diário de Grolin Barbabranca?",a="É um caderno pessoal mantido por Grolin Barbabranca, um observador estacionado no Vale Cristálgida. Nele, Grolin registra suas descobertas sobre a atividade local dos trolls Pelo-gélido e prepara relatórios de campo detalhando a situação defensiva do vale.",al={"o que é diário de grolin barbabranca","diário de grolin","caderno de grolin"}},["9ed18e74"]={q="De onde vem o Diário de Grolin Barbabranca e quem o fez?",a="O diário foi compilado diretamente pelo anão Grolin Barbabranca durante sua vigília sobre o Vale Cristálgida. No entanto, foi arrebatado dele e levado para o fundo da caverna de trolls próxima pelo bruto Pelo-gélido, Grik'nir, o Frio.",al={"quem fez o diário de grolin","de onde veio o diário de grolin","origem do diário de grolin"}}},fp="27,163,16.436.0,17.302.1,38.142.0,31.134.0,44.133.1,43.198.0"}
P.entries["item:grell-earring"] = {n="Brinco de Capeta",s="Em Bashal'Aran, o Brinco de Capeta guarda vestígios do selo que prende Astérion.",h="Em Bashal'Aran, o Brinco de Capeta guarda vestígios do selo que prende Astérion.",kw={"astérion","bashal'aran","costa negra","brinco de capeta","selo","vile sprite","grell selvagem"},ang={["class:Mage"]="Como Mago, você pode perceber como o metal retém, com o tempo, a magia ambiente dos antigos selos de proteção.",["race:NightElf"]="Como Elfo Noturno, você vê ruínas sagradas tomadas por sprites usando latão recolhido, um lembrete de quanto decaíram as outrora grandiosas propriedades da antiga Kalimdor."},sec={{t="Vestígios no latão",b="Grells selvagens e Vile Sprites em Bashal'Aran recolhem restos entre as ruínas e fazem brincos com eles. A maioria dos mortais vê apenas bugigangas sem valor. Astérion, um antigo Elfo Noturno preso ali como um fantasma atormentado, estuda a magia que permanece nos brincos. Ele espera que esses vestígios o levem ao antigo selo que o aprisiona."}},faq={{q="De onde vêm os Brincos de Capeta?",a="Grells selvagens e Vile Sprites carregam os brincos no assentamento élfico noturno em ruínas de Bashal'Aran, na Costa Negra.",al={"saque do brinco de capeta","onde conseguir brincos de capeta","quem deixa cair brincos de capeta"}},{q="Por que Astérion quer esses brincos?",a="Astérion é um espírito antigo mantido cativo em Bashal'Aran por uma magia poderosa. Ele usa os brincos para buscar vestígios do selo que prende sua alma há séculos.",al={"brincos de astérion","por que coletar brincos de capeta","uso do brinco de capeta"}},{q="Como os brincos ajudam Astérion a procurar o selo?",a="Astérion espera lançar um feitiço sobre os brincos e rastrear o selo que aprisiona sua forma espectral em Bashal'Aran.",al={"os brincos são mágicos","os grells sabem usar magia"}},{q="Astérion encontra nos brincos o que precisa?",a="Os brincos não contêm o selo. Seus vestígios mostram que as criaturas estiveram recentemente perto dele, guiando a busca de Astérion para o interior das ruínas.",al={"os brincos funcionaram","localização do selo de astérion"}}},fx={f6dd1a4f={q="O que é um Brinco de Capeta?",a="Um Brinco de Capeta é um simples adorno usado pelos capetas selvagens e espíritos vis que infestam as ruínas de Bashal'Aran na Costa Negra. Embora sejam bugigangas mundanas por si só, estes brincos saqueados absorveram emanações mágicas sutis das ruínas e de quaisquer relíquias que as criaturas tenham manuseado.",al={"o que são brincos de capeta","história do brinco de capeta","o que é brinco de capeta"}}},fp="13,75,19.322.0,34.120.0,38.141.0,54.116.0,51.146.0"}
P.entries["item:grenka-s-claw"] = {n="Garra da Grenka",s="A Garra da Grenka é um troféu físico obtido da formidável harpia Grenka Bloodscreech nas profundezas do Covil Plumerrante. Apresentada a Dorn Espreitaprados na Gruta Velha, ela serve como prova irrefutável de que um aspirante a aventureiro resistiu a uma provação física extenuante nas alturas do cânion.",h="A Garra da Grenka é um troféu físico obtido da formidável harpia Grenka Bloodscreech nas profundezas do Covil...",kw={"dorn espreitaprados","grenka bloodscreech","garra da grenka","harpia","covil plumerrante","screeching canyon","teste de resistência","mil agulhas","gruta velha"},ang={["faction:Horde"]="Eliminar os recessos profundos do Covil Plumerrante e derrotar Grenka Bloodscreech enfraquece a ameaça das harpias que assediam constantemente os viajantes ao redor da Aldeia Vento Livre.",["race:Tauren"]="O Ancião Dorn Espreitaprados considera seu dever sagrado fortalecer jovens campeões da Horda por meio da sabedoria e da determinação dos ritos taurens antes que enfrentem o mundo mais vasto e implacável."},sec={{t="Um Troféu de Resistência",b="Nas cavernas sinuosas do Covil Plumerrante, a oeste da Aldeia Vento Livre, as harpias estocam comida e defendem seu território violentamente contra forasteiros. Para testar a resiliência física de jovens campeões, Dorn Espreitaprados os incumbe de invadir os poleiros profundos e destruir as reservas de mantimentos do bando. Tamanha provocação descarada inevitavelmente atrai a fúria de Grenka Bloodscreech. Arrancar e entregar sua garra perversa prova que um guerreiro consegue suportar onda após onda de harpias enfurecidas e sobreviver ao ataque violento de sua matriarca."}},faq={{q="Para que serve a Garra da Grenka?",a="A garra serve como prova de vitória para Dorn Espreitaprados, um ancião tauren que reside na Gruta Velha, em Mil Agulhas. Entregá-la a ele conclui o Teste de resistência, demonstrando que você possui a garra física necessária para sobreviver a combates prolongados.",al={"uso da garra da grenka","por que preciso da garra da grenka","missao garra da grenka"}},{q="Quem é Grenka Bloodscreech?",a="Grenka Bloodscreech é uma poderosa harpia que empoleira dentro do Covil Plumerrante, localizado no Screeching Canyon ao longo dos penhascos ao sul de Mil Agulhas. Ela só emerge quando invasores ameaçam o bando ao destruir os suprimentos armazenados.",al={"quem e grenka","historia de grenka bloodscreech","o que e grenka"}},{q="Para onde levo a garra depois de obtê-la?",a="Leve a garra de volta a Dorn Espreitaprados na Gruta Velha, aninhada nas falésias de Mil Agulhas. Ele aceita o troféu para verificar que seu teste de resistência física foi bem-sucedido.",al={"onde entregar a garra da grenka","quem quer a garra da grenka"}},{q="Por que Dorn Espreitaprados exige este troféu específico?",a="Dorn Espreitaprados orienta jovens viajantes por meio de testes rigorosos para garantir que estejam mental, espiritual e fisicamente equipados para perigos maiores. Abater Grenka e reivindicar sua garra prova que um guerreiro consegue suportar tanto a emboscada de um enxame quanto o ataque direto de uma líder mortal.",al={"por que dorn quer a garra","proposito da garra"}}},fx={cd538a11={q="O que é a Garra da Grenka?",a="A Garra da Grenka é um troféu físico tirado de Grenka Grito-de-Sangue, uma harpia formidável que habita as profundezas do Covil Plumerrante no Desfiladeiro Estridente. Arrancada da criatura cruel após provocar e sobreviver à ira de seu bando, a garra serve como prova inegável de que um aspirante a aventureiro possui a resistência e a proeza marcial para suportar um teste brutal de combate.",al={"garra da grenka","o que é garra da grenka","sobre a garra da grenka"}}},fp="13,207,21.408.0,31.187.0,27.199.0,42.163.0,55.244.0"}
P.entries["item:grimtotem-horn"] = {n="Grimtotem Horn",s="Os Grimtotem Horns são retirados de taurens Grimtotem a oeste da Aldeia Mojache, em Feralas. Krueg Rachacrânio pede esses chifres ao descobrir que a tribo está por perto.",h="Os Grimtotem Horns são retirados de taurens Grimtotem a oeste da Aldeia Mojache, em Feralas.",kw={"belgrom","aldeia mojache","feralas","grimtotem","grimtotem horn","grimtotem horns","krueg rachacrânio","tauren"},ang={["faction:Horde"]="Como viajante da Horda, você ouve o alerta de Krueg, que apresenta os Grimtotem como uma ameaça às terras e aldeias da Horda."},sec={{t="Obtidos em Feralas",b="A oeste da Aldeia Mojache, taurens Grimtotem carregam esses chifres. Krueg Rachacrânio pede que você leve uma coleção até ele ao descobrir que o clã está em Feralas. Ele diz que Belgrom colocou uma recompensa pelos Grimtotem e alerta que eles são perigosos."}},faq={{q="De onde vêm os Grimtotem Horns?",a="Taurens Grimtotem a oeste da Aldeia Mojache, em Feralas, carregam os chifres.",al={"de onde vêm os chifres","origem dos grimtotem horns"}},{q="Quem quer os chifres?",a="Krueg Rachacrânio, na Aldeia Mojache, pede que você leve Grimtotem Horns até ele.",al={"quem precisa dos chifres","chifres de krueg"}},{q="Por que Krueg os quer?",a="Krueg pede os chifres ao descobrir que há taurens Grimtotem por perto. Ele diz que Belgrom tem interesse na tribo e colocou uma recompensa por eles.",al={"por que coletar chifres","para que servem os chifres"}},{q="Quem são os Grimtotem?",a="Os Grimtotem são um clã de taurens encontrado a oeste da Aldeia Mojache, em Feralas.",al={"quem são os grimtotem","taurens grimtotem"}}},fp="14,150,16.239.0,35.65.0,20.74.0,25.151.0,22.70.0"}
P.entries["item:grimtotem-satchel"] = {n="Algibeira do Temível Totem",s="A Algibeira do Temível Totem é uma bolsa de couro segurada pelo tauren caído Mauren Temível Totem nas profundezas das Cavernas Ígneas. Mesmo quando os troggs o subjugaram na caverna subterrânea sob Orgrimmar, Mauren protegeu esta bolsa com seu último suspiro. Recuperá-la e devolvê-la ao Penhasco do Trovão revela que The Elder Crone Magatha Temível Totem tinha um interesse ativo em qualquer coisa que seu membro de clã carregava.",h="A Algibeira do Temível Totem é uma bolsa de couro segurada pelo tauren caído Mauren Temível Totem nas...",kw={"platô dos anciãos","temível totem","magatha temível totem","mauren temível totem","cavernas ígneas","rahauro","algibeira","penhasco do trovão","trogg"},ang={["faction:Horde"]="A descoberta de um mensageiro do Temível Totem morto nas profundezas dos túneis sob a capital de Thrall mostra que os perigos das Cavernas Ígneas vão muito além de simples infestações de feras.",["race:Tauren"]="Encontrar um Temível Totem operando nas profundezas sob Orgrimmar e prestando contas a Magatha no Platô dos Anciãos destaca as manobras políticas sutis e tensas do clã Temível Totem dentro das tribos unidas dos taurens."},sec={{t="Um Aperto Agonizante",b="Descoberta sob o corpo abatido de Mauren Temível Totem nas profundezas das Cavernas Ígneas, esta bolsa simples estava presa em um abraço firme e desesperado. Mauren lutou bravamente para proteger o que quer que ela contenha enquanto era cercado e morto por troggs selvagens. A pura determinação necessária para proteger uma algibeira acima da própria vida sugere que seu conteúdo é muito mais significativo do que simples rações de viagem ou suprimentos comuns."},{t="O Interesse de The Elder Crone",b="Ao levar a algibeira até Rahauro no Platô dos Anciãos, no Penhasco do Trovão, o mistério maior se desenrola. Rahauro aceita a bolsa em nome de Magatha Temível Totem, a matriarca do clã Temível Totem. Mauren era servo de Magatha, e chegou a ela a notícia de que ele havia encontrado algo peculiar nas cavernas sob Orgrimmar antes de morrer; Magatha organizou recompensas especificamente para o retorno seguro do item, demonstrando que a liderança do Temível Totem tinha interesses deliberados e secretos no abismo infestado de troggs."}},faq={{q="Onde a Algibeira do Temível Totem é encontrada?",a="A algibeira é descoberta nas profundezas das Cavernas Ígneas, a caverna vulcânica sob Orgrimmar. Ela repousa sob o cadáver de Mauren Temível Totem, presa em seus braços onde ele caiu diante dos troggs da caverna.",al={"localização da algibeira","onde fica a algibeira","como encontrar a algibeira"}},{q="A quem pertence a algibeira?",a="Ela pertencia a Mauren Temível Totem, um membro do clã Temível Totem que se aventurou nas Cavernas Ígneas. Mesmo na morte, seus braços permaneceram firmemente enrolados na bolsa para proteger seu conteúdo do ataque dos troggs.",al={"de quem é a algibeira","dono da algibeira de mauren"}},{q="Quem deseja o retorno da algibeira?",a="A algibeira é entregue a Rahauro no Platô dos Anciãos, no Penhasco do Trovão. Rahauro a aceita sob ordens diretas de Magatha Temível Totem, que providenciou uma recompensa para qualquer um que recuperasse os pertences de seu membro de clã caído.",al={"quem recebe a algibeira","onde entregar a algibeira","quem quer a algibeira do temível totem"}},{q="Por que um Temível Totem estava carregando isso sob Orgrimmar?",a="Mauren Temível Totem era um servo de Magatha Temível Totem, que havia demonstrado interesse pelas Cavernas Ígneas. Ele entrou no abismo para falar com os troggs e encontrou algo peculiar por lá, mas nunca conseguiu sair para mostrar a ela o que era.",al={"por que mauren estava nas cavernas ígneas","o que o temível totem fazia em orgrimmar"}},{q="O que há dentro da algibeira?",a="O conteúdo exato dentro da bolsa é mantido selado e entregue diretamente a Rahauro no Penhasco do Trovão. Magatha espera que ele contenha indícios da coisa peculiar que Mauren encontrou no abismo.",al={"conteúdo da algibeira","o que tem na bolsa"}}},fp="17,225,12.266.0,26.343.1,37.178.0,31.135.0,31.165.0,50.190.0,27.153.0"}
P.entries["item:grizzled-bear-heart"] = {n="Coração de Urso Cinzento",s="Um Coração de Urso Cinzento é um reagente biológico extraído dos robustos ursos que vagam pela Floresta de Pinhaprata. Ele serve como um componente vital na sombria pesquisa da Real Sociedade de Boticários sobre a Nova Praga.",h="Um Coração de Urso Cinzento é um reagente biológico extraído dos robustos ursos que vagam pela Floresta de...",kw={"receita mortal","boticário renferrel","coração de urso cinzento","mestre-boticário faranello","nova praga","velho tenaz","real sociedade de boticários","floresta de pinhaprata","sangue de pateante"},ang={["class:Hunter"]="Os ursos imensos de Pinhaprata são presas perigosas, e rastrear feras como o Velho Tenaz em busca de amostras biológicas testa a paciência de um caçador e sua habilidade de evisceração em campo.",["race:Undead"]="Para os Renegados, coletar esses órgãos ajuda diretamente o Mestre-boticário Faranello na criação da arma definitiva contra o Flagelo de Arthas e contra os mortais vivos que ameaçam Lordaeron."},sec={{t="Um Reagente para a Nova Praga",b="A Real Sociedade de Boticários trabalha incessantemente para desenvolver uma praga artificial capaz de exterminar tanto o Flagelo quanto a humanidade viva. Nos bosques da Floresta de Pinhaprata, o Boticário Renferrel descobriu que uma toxina única derivada do coração de um urso cinzento, quando combinada com o icor aracnídeo, resulta em uma mistura incrivelmente letal. Mensageiros e lealistas Renegados caçam ursos cinzentos ferozes, ursos cinzentos gigantes e a infame fera Velho Tenaz para extrair esses órgãos e entregá-los diretamente ao Mestre-boticário Faranello nas profundezas do Boticarium de Cidade Baixa."}},faq={{q="Para que serve o Coração de Urso Cinzento?",a="Os Corações de Urso Cinzento são coletados como reagentes experimentais para a Real Sociedade de Boticários. O Boticário Renferrel descobriu que as toxinas derivadas desses corações podem ser destiladas em um elixir letal como parte do esforço dos Renegados para criar a Nova Praga.",al={"o que faz o coração de urso","missão coração de urso","reagentes de receita para a morte"}},{q="Quem quer esses corações de urso?",a="O Boticário Renferrel na Floresta de Pinhaprata instrui viajantes a coletar os corações junto com Sangue de Pateante e entregá-los diretamente ao Mestre-boticário Faranello no Boticarium de Cidade Baixa.",al={"quem precisa de coração de urso","faranello coração de urso","para quem entregar coração de urso"}},{q="De onde vêm os Corações de Urso Cinzento?",a="Eles são extraídos dos vários ursos cinzentos que vagam pela Floresta de Pinhaprata, incluindo ursos cinzentos ferozes, ursos cinzentos gigantes e a formidável fera errante Velho Tenaz.",al={"onde encontrar corações de urso","quais ursos dropam coração","localização coração de urso"}},{q="Por que a Real Sociedade de Boticários precisa de toxinas de animais naturais?",a="A sociedade busca agentes biológicos potentes capazes de contaminar e destruir tanto a carne viva quanto a fisiologia dos mortos-vivos. As propriedades químicas únicas encontradas nos tecidos cardíacos dos robustos ursos de Pinhaprata fornecem uma base reativa ideal quando combinadas com sangue de aranha virulento.",al={"por que boticários usam veneno de urso","por que corações de animais para a praga"}}},fx={["9ca08a87"]={q="O que é um Coração de Urso Cinzento?",a="É o órgão fresco colhido dos ferozes ursos cinzentos que rondam a Floresta de Pinhaprata. Embora seja um órgão mundano à primeira vista, o coração contém uma toxina biológica natural e resiliente que o torna um reagente atraente para experimentos alquímicos.",al={"o que é coração de urso cinzento","informações sobre coração de urso","história do coração de urso cinzento"}}},fp="19,114,28.520.0,39.234.0,28.188.0,40.156.0,65.274.0"}
P.entries["item:grizzled-scalp"] = {n="Escalpo Grisalho",s="Um Escalpo Grisalho é o couro espesso e peludo retirado de ursos-do-cardo grisalhos que vagam pelas florestas ao sul de Costa Negra. Embora pareça um troféu peculiar, essas peles são procuradas pelo excêntrico engenhoqueiro gnomo Xafetim Manigiro para abastecer seu maquinário escondido na natureza selvagem.",h="Um Escalpo Grisalho é o couro espesso e peludo retirado de ursos-do-cardo grisalhos que vagam pelas florestas...",kw={"auberdine","caixazorra 525","costa negra","escalpo grisalho","urso-do-cardo grisalho","cerveja de urso-do-cardo","xafetim manigiro"},ang={["profession:Engineering"]="A rede de caixazorras demonstra o talento gnômico para disfarçar alambiques de fermentação automatizados como dispositivos de comunicação de reparo de campo.",["race:NightElf"]="Os elfos noturnos protegem a vida selvagem de Costa Negra e veem com maus olhos tanto a caça predatória quanto os alambiques gnômicos clandestinos entulhando suas terras selvagens."},sec={{t="Uma Fermentação Peculiar",b="Viajantes que caçam ao longo da estrada ao sul de Auberdine encontram os calejados ursos-do-cardo grisalhos, conhecidos por suas peles ásperas e espessas. Embora esfolar predadores perigosos seja natural para caçadores da floresta, levar quatro de seus escalpos para a Caixazorra 525 revela um propósito bem menos nobre. O aparelho não precisa de pele de urso para reparos de engenharia ou análises científicas. Em vez disso, o gnomo Xafetim Manigiro utiliza as caixazorras ocultas espalhadas por Costa Negra como destilarias clandestinas. Como os elfos noturnos locais reprovam operações ilícitas de fermentação dentro de seus assentamentos, Xafetim conta com aventureiros ingênuos para coletar escalpos de urso e outros ingredientes bizarros para produzir sua adorada 'cerveja de urso-do-cardo'."}},faq={{q="Onde posso encontrar Escalpos Grisalhos?",a="Os Escalpos Grisalhos são obtidos de ursos-do-cardo grisalhos e de sua matriarca, a Den Mother, nas florestas ao sul de Auberdine, ao longo da trilha principal em Costa Negra.",al={"localização de escalpo grisalho","quem dropa escalpo grisalho","escalpo de urso-do-cardo"}},{q="Para que servem os Escalpos Grisalhos?",a="Eles são depositados na Caixazorra 525, um terminal mecânico automatizado escondido nos arbustos ao lado da estrada, bem ao sul de Auberdine.",al={"uso do escalpo grisalho","o que fazer com escalpos grisalhos"}},{q="Por que a Caixazorra 525 precisa de escalpos de urso?",a="Xafetim Manigiro usa secretamente sua rede de caixazorras para destilar bebida clandestina longe dos olhares vigilantes dos elfos noturnos. Os escalpos grisalhos servem como ingrediente em sua cerveja de urso-do-cardo caseira.",al={"por que xafetim quer escalpos","propósito da caixazorra 525"}},{q="Por que Xafetim está escondendo sua produção de bebidas na selva de Costa Negra?",a="Os elfos noturnos que residem em Auberdine não toleram um comércio de bebidas barulhento e não autorizado em seus bosques sagrados. Xafetim escondeu suas engenhocas no matagal ao longo das estradas selvagens para manter sua operação de bebida clandestina funcionando sem ser detectada.",al={"por que esconder caixazorra","bebida de xafetim em costa negra"}}},fx={["903811df"]={q="O que é um Escalpo Grisalho?",a="Um Escalpo Grisalho é a coroa espessa e peluda colhida dos ursos robustos que vagam pelas terras selvagens da Costa Negra. Essas feras experientes suportam o clima rigoroso do norte, desenvolvendo couros resilientes e cerdosos que caçadores e inventores curiosos valorizam por sua densidade única.",al={"o que é escalpo grisalho","informações sobre escalpo grisalho","me fale sobre escalpos grisalhos"}},e940f924={q="De onde vem um Escalpo Grisalho?",a="Esses escalpos vêm dos ursos-cardos maduros nativos da Costa Negra, principalmente os Ursos-cardos Grisalhos e a feroz Mãe da Alcateia. Em vez de bens manufaturados, são troféus brutos tirados diretamente das feras selvagens que vagam ao sul de Auberdine.",al={"de onde vêm os escalpos grisalhos","fonte do escalpo grisalho","quem deixa cair escalpos grisalhos"}}},fp="14,129,23.410.1,33.127.0,34.117.0,38.137.1,60.214.1"}
P.entries["item:groddoc-liver"] = {n="Groddoc Liver",s="O fígado de Groddoc vem dos símios de Feralas. Rhapsody Shindigger precisa dele para uma bebida que, espera, o ajudará a falar sobre um voo assustador sobre um pântano.",h="O fígado de Groddoc vem dos símios de Feralas.",kw={"feralas","groddoc ape","groddoc liver","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="Um ingrediente amargo",b="Rhapsody Shindigger pede Groddoc Liver nas Terras Agrestes, junto com Roc Gizzards e Ironfur Livers. Ele planeja destilar os três ingredientes para preparar um Kalimdor Kocktail. Segundo ele, a bebida pode ajudá-lo a falar dos horrores de um voo sobre um pântano."}},faq={{q="De onde vêm os fígados de Groddoc?",a="Os fígados de Groddoc vêm de Groddoc Apes em Feralas.",al={"onde encontrar groddoc liver","origem de groddoc liver"}},{q="Quem quer Groddoc Liver?",a="Rhapsody Shindigger, nas Terras Agrestes, pede três Groddoc Liver para preparar seu Kalimdor Kocktail.",al={"quem precisa deste fígado","fígado de rhapsody"}},{q="Para que serve Groddoc Liver?",a="Rhapsody Shindigger usa Groddoc Liver com Roc Gizzards e Ironfur Livers para preparar um Kalimdor Kocktail.",al={"uso de groddoc liver","por que precisa do fígado"}},{q="Por que Rhapsody está preparando a bebida?",a="Rhapsody diz que precisa de uma bebida mais forte antes de poder contar a você sobre um voo assustador sobre um pântano.",al={"por que o coquetel","rhapsody quer bebida"}}},fp="13,159,19.254.0,34.49.0,24.99.0,31.100.0,33.103.0"}
P.entries["item:gryshka-s-letter"] = {n="Carta de Gryshka",s="Carta de Gryshka é uma nota pessoal de agradecimento escrita pela Estalajadeira Gryshka de Orgrimmar e endereçada ao açougueiro Zargh n'A Encruzilhada. Enviada após o recebimento de uma remessa de carne fresca, a carta serve tanto como sinal de gratidão quanto como pretexto para ensinar jovens mensageiros da Horda a utilizar a rede de voo de mantícoras.",h="Carta de Gryshka é uma nota pessoal de agradecimento escrita pela Estalajadeira Gryshka de Orgrimmar e...",kw={"sertões","encruzilhada","doraso","gryshka","carta de gryshka","carne","orgrimmar","mantícora","zargh"},ang={["faction:Horde"]="A entrega da Carta de Gryshka marca um rito de passagem para jovens aventureiros da Horda, servindo como sua introdução inicial à rede de mestres de voo de serpes que conecta Durotar e os Sertões."},sec={{t="Uma Estalajadeira Agradecida",b="Quando Zargh envia um pacote de bifes preparados das extensões áridas dos Sertões para a taverna central de Orgrimmar, a Estalajadeira Gryshka escreve esta nota em resposta. Além de expressar sua satisfação com os cortes do açougueiro, a carta revela um apreço afetuoso — ainda que rústico — por Zargh, relembrando desventuras cômicas como a vez em que ele perdeu um dedo ao preparar carne. Gryshka conclui com diversão afetuosa, comentando que ele fica bonito mesmo ensanguentado pelo seu trabalho."},{t="Mensageiro Pelas Rotas de Voo",b="Carregar a Carta de Gryshka proporciona aos viajantes uma lição prática na logística da Horda. Para retornar com o pergaminho à Encruzilhada, os aventureiros são instruídos a se apresentar a Doraso, o mestre de mantícoras empoleirado no platô de Orgrimmar. Ao demonstrar que o viajante já se apresentou a Devrak n'A Encruzilhada, Doraso apresenta os mensageiros novatos às rotas de voo de serpes que interligam os assentamentos de Durotar e dos Sertões."}},faq={{q="Quem escreveu a Carta de Gryshka?",a="A Estalajadeira Gryshka, que administra a movimentada taverna no Vale da Força em Orgrimmar, escreveu a carta após receber uma remessa de carne fresca.",al={"quem escreveu isto","autor da carta de gryshka","remetente"}},{q="A quem a carta se destina?",a="A carta é endereçada a Zargh, um açougueiro estabelecido na Encruzilhada, nos Sertões, que forneceu carne a Gryshka.",al={"destinatário","quem recebe a carta de gryshka","para onde vai a carta"}},{q="O que está escrito dentro da carta?",a="Gryshka agradece ao açougueiro pelos cortes de qualidade, relembra em tom de brincadeira um acidente no qual ele perdeu um dedo durante o trabalho e provoca dizendo que ele fica charmoso mesmo sangrando.",al={"texto da carta","o que gryshka diz","conteúdo da carta"}},{q="Por que Doraso precisa ver a carta?",a="Doraso é o mestre de mantícoras de Orgrimmar. Gryshka envia você até ele para que possa providenciar uma viagem em uma serpe de volta à Encruzilhada, ilustrando como funcionam as rotas aéreas da Horda.",al={"por que mostrar a doraso","doraso, o mestre de mantícoras","mestre de voo de orgrimmar"}}},fx={["950e527c"]={q="O que é a Carta de Gryshka?",a="É uma mensagem de gratidão escrita à mão pela Estalajadeira Gryshka de Orgrimmar. Ela a redigiu em resposta a uma remessa especial de carne enviada para sua estalagem, pretendendo que fosse tanto uma nota de agradecimento quanto um gesto paquerador de afeição para ser levado de volta aos Sertões.",al={"o que é a carta de gryshka","item carta de gryshka","sobre a carta de gryshka"}},["0c09fbc7"]={q="Por que alguém quer a Carta de Gryshka?",a="O açougueiro Zargh na Encruzilhada aguarda ansiosamente notícias sobre como sua carne de primeira foi recebida. Gryshka deseja que ela seja entregue para mostrar seu agradecimento sincero e retribuir seu afeto, enquanto Doras, o mestre dos cavaleiros de vento, simplesmente precisa confirmar seu destino para organizar o voo de volta através dos Sertões.",al={"por que entregar a carta de gryshka","quem quer a carta de gryshka","por que zargh quer a carta de gryshka"}}},fp="16,165,20.205.0,30.294.0,27.119.0,31.108.0,34.137.0,38.176.0"}
P.entries["item:gunther-s-spellbook"] = {n="Grimório de Tertuliano",s="O Grimório de Tertuliano é um tomo arcano pessoal vinculado a um misterioso mago que habita as Clareiras de Tirisfal. Imbuído com um encantamento de Boanerges Stalactus, o livro serve como prova de que outros praticantes de magia conseguiram se libertar do controle do Lich Rei, embora a verdadeira história entre seu proprietário e os Renegados ainda precise ser desvendada.",h="O Grimório de Tertuliano é um tomo arcano pessoal vinculado a um misterioso mago que habita as Clareiras de...",kw={"arcanus","boanerges","dalaran","tertuliano","stalactus","kirin tor","grimório","tirisfal"},ang={["class:Mage"]="Para os praticantes do arcano, o tomo representa as raízes compartilhadas de Dalaran conectando a atual liderança mágica dos Renegados a praticantes renegados nas terras ermas.",["race:Undead"]="O livro encantado destaca o esforço contínuo dos Renegados para recrutar mortos-vivos independentes e poderosos que se libertaram do Lich Rei por conta própria."},sec={{t="Um Símbolo de Antigo Parentesco",b="Antes da Terceira Guerra, Tertuliano Arcanus estudou as artes arcanas em Dalaran ao lado de Boanerges Stalactus e Thule Ravenclaw como membros do Kirin Tor. Quando o Flagelo dos Mortos-vivos varreu Lordaeron, Tertuliano caiu e foi erguido como morto-vivo, mas acabou conseguindo libertar sua própria mente do Flagelo. Acreditando estar isolado e perpetuamente perseguido pelos agentes do Lich Rei, ele permaneceu profundamente hostil a estranhos. Após o tomo ser recuperado, Boanerges Stalactus aplicou um encantamento arcano sobre suas páginas — uma assinatura mágica deliberada que permite a Tertuliano reconhecer a presença de Boanerges e perceber que não é o único mago a possuir livre-arbítrio."}},faq={{q="De quem é este grimório?",a="Pertence a Tertuliano Arcanus, um poderoso mago morto-vivo que reside em uma ilha isolada no Lago Águas Claras, nas Clareiras de Tirisfal.",al={"quem é o dono do livro","tertuliano dono do livro","dono do grimório"}},{q="Por que Boanerges encantou o grimório?",a="Boanerges colocou um feitiço pessoal no tomo para servir como prova inequívoca de que sobrevive em Lordaeron e está livre do controle do Lich Rei, esperando convencer Tertuliano a se aliar aos Renegados.",al={"por que encantar o livro","feitiço de boanerges no livro","magia do livro"}},{q="Por que Tertuliano desconfia quando o livro é devolvido?",a="Tertuliano presume que qualquer pessoa que se aproxime de seu refúgio seja um agente do Flagelo enviado para escravizá-lo novamente e, a princípio, acredita que o aventureiro era apenas o ladrão que pegou seu tomo.",al={"por que tertuliano está bravo","tertuliano irritado","tertuliano hostil"}},{q="Como Tertuliano e Boanerges se conheciam?",a="Há muito tempo, Tertuliano, Boanerges Stalactus e Thule Ravenclaw estudaram magia juntos como amigos e aprendizes do Kirin Tor em Dalaran antes que a Praga os levasse.",al={"passado de boanerges e tertuliano","conexão com o kirin tor","amigos de dalaran"}}},fp="19,150,22.608.1,24.107.1,37.179.0,52.162.0,43.144.1"}
P.entries["item:gyromechanic-gear"] = {n="Equipamento Giromecânico",s="Um Equipamento Giromecânico é uma peça de engenharia de precisão recuperada dos escombros fora de Gnomeregan. Inventores gnômicos em Kharanos buscam essas engrenagens específicas para construir um dispositivo experimental capaz de reverter as mutações dos gnomos contaminados.",h="Um Equipamento Giromecânico é uma peça de engenharia de precisão recuperada dos escombros fora de Gnomeregan.",kw={"gnomeregan","equipamento giromecânico","kharanos","gnomo contaminado","operação remendão","razzle molavivaz","recombobulador","roda de reestabilização"},ang={["profession:Engineering"]="A engenharia de precisão gnomica é renomada por sua extrema complexidade, baseando-se em componentes giromecânicos de tolerância rigorosa para regular maquinário protótipo instável.",["race:Gnome"]="Cada engrenagem recuperada deixa os inventores gnômicos um passo mais perto de potencialmente resgatar seus irmãos radioativos que vagam pelas neves fora de Gnomeregan."},sec={{t="Componentes para Recombobulação",b="Quando a radiação inundou Gnomeregan para purgar a invasão dos troggs, ela corrompeu uma vasta parte da população gnomica sobrevivente, transformando-a em gnomos contaminados irradiados e insanos. Recusando-se a abandonar seus parentes transformados, os inventores Ozzie Mudavolt e Razzle Molavivaz começaram a trabalhar em esquemas para o Recombobulador — uma engenhoca ambiciosa projetada para desfazer os efeitos horríveis da radiação. Construir o protótipo requer mecanismos de precisão capazes de suportar pressões internas voláteis, particularmente Equipamentos Giromecânicos e Engrenagens de Reestabilização complementares. Como a manufatura local entrou em colapso com a queda de sua capital, os pesquisadores são forçados a coletar essas peças delicadas diretamente dos gnomos contaminados hostis que vagam por Dun Morogh."}},faq={{q="Para que serve um Equipamento Giromecânico?",a="Ele serve como um componente mecânico central necessário para Razzle Molavivaz em Kharanos. Junto com Engrenagens de Reestabilização, ele é incorporado ao Recombobulador, uma máquina protótipo projetada para curar gnomos contaminados irradiados.",al={"objetivo do equipamento giromecânico","o que faz o equipamento giromecânico","missão do equipamento giromecânico"}},{q="De onde vêm essas engrenagens?",a="Elas são recuperadas de Gnomos Contaminados fora de Gnomeregan e de Gibblewilt em Dun Morogh.",al={"onde encontrar equipamento giromecânico","saque do equipamento giromecânico","quem deixa cair equipamento giromecânico"}},{q="O Recombobulador consegue realmente curar os gnomos contaminados?",a="Razzle Molavivaz permanece infinitamente otimista com os esquemas de Ozzie, acreditando que ajustes nos pistões de combustão e no gel eletrogoma restaurarão seus parentes. Se a máquina pode verdadeiramente reverter o envenenamento radioativo catastrófico em grande escala permanece uma teoria gnomica não testada.",al={"o recombobulador funciona","gnomos contaminados podem ser curados","sucesso da recombobulação"}},{q="Por que os gnomos simplesmente não podem forjar novas engrenagens?",a="A perda de Gnomeregan destruiu a capacidade industrial gnomica, isolando suas ferramentas, oficinas e fundições automatizadas mais sofisticadas. Recuperar hardware de precisão intacto de antes da queda no perímetro da cidade é muitas vezes muito mais rápido do que usinar peças manualmente.",al={"por que recuperar engrenagens","por que não fabricar equipamentos giromecânicos"}}},fx={["93a017f3"]={q="O que é um Equipamento Giromecânico?",a="Um Equipamento Giromecânico é um componente intrinsecamente projetado para maquinários gnômicos complexos. Originalmente utilizado nas vastas obras mecânicas de Gnomeregan, essas peças de precisão estão agora espalhadas pelas ruínas e saqueadas pelas criaturas miseráveis que espreitam fora da cidade tecnológica caída.",al={"o que é equipamento giromecânico","informações sobre equipamento giromecânico","sobre equipamentos giromecânicos"}}},fp="17,121,30.581.0,37.195.0,31.94.0,50.211.0,40.221.0"}
P.entries["item:hallowed-letter"] = {n="Carta Santificada",s="A Hallowed Letter é uma convocação formal com a insígnia da Sacerdotisa Anita, entregue a jovens sacerdotes promissores no Vale de Vila Norte. Ela chama o portador à Abadia de Vila Norte para iniciar o estudo e treinamento formal na Luz Sagrada.",h="A Hallowed Letter é uma convocação formal com a insígnia da Sacerdotisa Anita, entregue a jovens sacerdotes...",kw={"anita","floresta de elwynn","hallowed letter","luz sagrada","abadia de vila norte","sacerdote","sacerdotisa anita"},ang={["class:Priest"]="Esta missiva marca seu reconhecimento formal como um instrumento da Luz Sagrada, estabelecendo seu vínculo com os instrutores da Abadia de Vila Norte.",["race:Human"]="Sacerdotes humanos têm praticado no Vale de Vila Norte desde antes da Primeira Guerra; receber esta carta dá continuidade a essa tradição ancestral de dever sagrado."},sec={{t="Um Chamado à Fé",b="Selada com a marca pessoal da Sacerdotisa Anita, a Hallowed Letter é entregue a sacerdotes novatos após suas primeiras provações contra os acampamentos de kobolds do Vale de Vila Norte. Anita reconhece a centelha interior da Luz Sagrada dentro do novato e insta-o a não hesitar, mas a entrar nos muros da abadia para se dedicar formalmente. Com forças sombrias ainda presentes por toda Azeroth no rescaldo da Terceira Guerra, o sacerdócio reúne ativamente aqueles capazes de curar, proteger e oferecer orientação espiritual a um império que luta para manter a ordem."}},faq={{q="O que é a Hallowed Letter?",a="É uma missiva introdutória selada pela Sacerdotisa Anita, entregue a sacerdotes recém-chegados na Abadia de Vila Norte para convocá-los para sua instrução inicial de classe.",al={"o que é hallowed letter","item hallowed letter","carta de sacerdote vila norte"}},{q="Quem escreveu a carta?",a="A carta traz a insígnia da Sacerdotisa Anita, a instrutora residente e guia espiritual que orienta jovens sacerdotes humanos que chegam a Vila Norte.",al={"quem enviou a carta","quem é o autor","remetente da carta"}},{q="Por que o sacerdócio está convocando novos iniciados agora?",a="O mundo permanece em turbulência. Resquícios da Legião Ardente ainda assombram Azeroth, Kalimdor enfrenta novas provações, e o reino de Ventobravo necessita de líderes e curadores compassivos para reconstruir e proteger seu povo.",al={"por que os sacerdotes precisam de ajuda","estado do mundo","história de sacerdote 25 adp"}},{q="O que devo fazer após ler a carta?",a="Leve a carta para dentro da Abadia de Vila Norte e fale com a Sacerdotisa Anita. Ela aceitará seu juramento à Luz e oferecerá treinamento em novas disciplinas sacerdotais à medida que sua jornada se desenrola.",al={"onde levo a carta","entrega da missão hallowed letter","com quem falar"}}},fx={["0a342f04"]={q="Por que a Sacerdotisa Anita quer que você tenha a Hallowed Letter?",a="A Sacerdotisa Anita envia a carta para convocar iniciantes promissores da Luz Sagrada dentro da Abadia de Vila Norte. Reconhecendo que você mostrou promessa na defesa do vale, ela deseja se apresentar, guiar sua devoção espiritual e oferecer instrução mais profunda nas artes sagradas do sacerdócio.",al={"por que hallowed letter","por que anita enviou a carta","propósito da hallowed letter"}}},fp="15,128,15.424.0,28.147.0,21.113.0,58.196.0,42.179.0"}
P.entries["item:hallowed-rune"] = {n="Runa Santificada",s="A Runa santificada é uma pedra inscrita entregue a sacerdotes novatos que iniciam seu treinamento no Vale Cristálgida. Enviada pelo instrutor de sacerdotes anão Branstock Khalder, ela convoca os aspirantes a praticantes da Luz Sagrada para Sidermar a fim de iniciarem sua instrução formal.",h="A Runa santificada é uma pedra inscrita entregue a sacerdotes novatos que iniciam seu treinamento no Vale...",kw={"sidermar","branstock khalder","vale cristálgida","dun morogh","runa santificada","sacerdote","troggs"},ang={["class:Priest"]="A Runa santificada marca o início oficial da mentoria formal de um sacerdote sob a Luz Sagrada no Vale Cristálgida.",["race:Dwarf"]="Os sacerdotes anões combinam uma reverência devota pela Luz com um dever inabalável para com Altaforja, apresentando-se para defender sua terra natal montanhosa dos troggs."},sec={{t="Um chamado para a Luz",b="Quando um sacerdote iniciante demonstra sua determinação ajudando os montanhistas e defensores do Vale Cristálgida, Branstock Khalder envia a Runa santificada. Inscrita com ensinamentos da Luz Sagrada, a pedra serve tanto como introdução quanto como convite. Os novatos anões são orientados a se afastar das escaramuças menores na neve e a se apresentar em Sidermar, onde Branstock os prepara para curar ferimentos e canalizar o poder sagrado contra a infestação de troggs que ameaça Dun Morogh."}},faq={{q="O que é a Runa santificada?",a="A Runa santificada é uma pequena pedra sagrada contendo palavras de orientação para sacerdotes novatos. Ela serve como uma convocação oficial de Branstock Khalder para iniciar a instrução mágica e espiritual formal dentro de Sidermar.",al={"o que e este item","item runa santificada","proposito da runa"}},{q="Quem envia a Runa santificada para você?",a="Ela é enviada por Branstock Khalder, o instrutor de sacerdotes anão baseado em Sidermar. Ele a entrega por meio de aliados no Vale Cristálgida para alcançar jovens sacerdotes que começaram a provar seu valor em campo.",al={"quem enviou a runa","quem me deu esta runa","runa de branstock"}},{q="O que devo fazer após receber a Runa santificada?",a="Você deve reservar um momento para ler a runa e, em seguida, dirigir-se ao salão principal de Sidermar para se apresentar a Branstock Khalder, onde ele se oferecerá para lhe ensinar novas preces e feitiços.",al={"onde levo a runa","o que fazer com a runa santificada"}},{q="Por que Branstock quer sacerdotes novatos treinados tão rapidamente?",a="O Vale Cristálgida sofre com o assédio constante das incursões de troggs, e os montanhistas precisam de toda a cura divina e poder ofensivo que puderem reunir para defender Dun Morogh.",al={"por que precisam de sacerdotes","problema dos troggs sacerdotes"}}},fx={fac25589={q="Por que a Hallowed Rune me foi dada?",a="A runa atua como uma convocação formal e mensagem dirigida aos sacerdotes novatos que trabalham no Vale Cristálgida. Branstock Khalder a envia para chamar aspirantes a acólitos da Luz Sagrada para Sidermar, para que ele possa instruí-los em sua fé e ensinar-lhes feitiços sagrados vitais para a defesa do vale.",al={"por que tenho a hallowed rune","propósito da hallowed rune","por que hallowed rune"}}},fp="13,114,22.281.0,26.185.0,35.121.0,51.138.0,58.152.0"}
P.entries["item:hallowed-scroll"] = {n="Pergaminho Consagrado",s="O Pergaminho consagrado é uma convocação formal entregue a sacerdotes Renegados recém-despertados em Plangemortis. Com o selo pessoal do Clérigo das Trevas Duesten, ele orienta os novatos a irem até a capela em ruínas para iniciar sua reeducação em fé, força de vontade e sombras.",h="O Pergaminho consagrado é uma convocação formal entregue a sacerdotes Renegados recém-despertados em...",kw={"plangemortis","duesten","renegados","pergaminho consagrado","luz","sacerdote","tirisfal"},ang={["class:Priest"]="Este pergaminho marca a ruptura definitiva com a fé humana tradicional, orientando os sacerdotes Renegados rumo à convicção própria e às artes sombrias praticadas pelo Culto da Sombra Esquecida.",["race:Undead"]="Receber esta convocação reflete a mobilização urgente e pragmática de Plangemortis, garantindo que os mortos-vivos recém-despertados sejam rapidamente treinados e integrados às forças de Sylvana."},sec={{t="Uma Convocação aos Incrédulos",b="Sacerdotes Renegados recém-erguidos descobrem que sua conexão com o mundo mudou de forma violenta. Entregue em meio ao caos contínuo da recuperação de Plangemortis, o Pergaminho consagrado orienta os conjuradores novatos a buscarem orientação na capela em ruínas do povoado. Marcado com o selo do Clérigo das Trevas Duesten, o pergaminho serve tanto como introdução quanto como ordem de apresentação para instrução formal, iniciando o sacerdote na filosofia pragmática que define o sacerdócio dos Renegados."},{t="O Caminho da Autossuficiência",b="Ao atenderem à convocação do pergaminho, os sacerdotes são imediatamente desenganados dos antigos dogmas. Duesten deixa claro que os apoios tradicionais — a veneração da Luz Sagrada, espíritos ancestrais ou pactos demoníacos — não servem mais aos mortos-vivos. Em vez disso, o pergaminho marca o início de uma disciplina interior enraizada estritamente na força de vontade individual. Os ensinamentos iniciados por este pergaminho enfatizam sobreviver e governar por pura convicção, transformando a devoção religiosa em um instrumento de autodeterminação e domínio."}},faq={{q="O que é o Pergaminho consagrado?",a="O Pergaminho consagrado é uma mensagem escrita entregue a sacerdotes Renegados recém-erguidos em Plangemortis. Ele instrui o leitor a se apresentar ao Clérigo das Trevas Duesten dentro da capela local para iniciar seu treinamento formal de sacerdócio.",al={"o que é este pergaminho","objetivo do pergaminho consagrado","item pergaminho consagrado"}},{q="Quem enviou o Pergaminho consagrado?",a="O pergaminho traz o selo pessoal do Clérigo das Trevas Duesten, o instrutor de sacerdotes estabelecido na igreja abandonada de Plangemortis.",al={"quem escreveu o pergaminho consagrado","quem enviou o pergaminho","pergaminho de duesten"}},{q="O que o Clérigo das Trevas Duesten ensina quando você lhe leva o pergaminho?",a="Duesten ensina que os sacerdotes mortos-vivos devem descartar a dependência tradicional da Luz Sagrada, de espíritos ancestrais ou de poderes de outros mundos. Ele prega que os Renegados sobreviveram apenas pela pura força de vontade individual e instrui os jovens sacerdotes a cultivarem a fé em si mesmos para guiar e dominar os outros.",al={"o que duesten diz","crenças dos sacerdotes renegados","história dos sacerdotes de plangemortis"}}},fx={["758c1904"]={q="Por que o Clérigo das Trevas Duesten quer que você tenha o Hallowed Scroll?",a="O Clérigo das Trevas Duesten usa o pergaminho selado para convocar sacerdotes Renegados recém-erguidos para a igreja de Plangemortis. Em vez de deixar você se apegar à Luz esquecida ou aos espíritos ancestrais, ele pretende instruí-lo na filosofia sombria do sacerdócio Renegado — contando estritamente com sua própria força de vontade inabalável para exercer poder e sobreviver em um mundo hostil.",al={"por que hallowed scroll","por que duesten hallowed scroll","propósito do hallowed scroll"}}},fp="15,183,26.374.0,25.351.0,28.161.0,29.118.0,66.279.0"}
P.entries["item:hallowed-sigil"] = {n="Selo Sagrado",s="O selo sagrado é um emblema gravado de Elfo Noturno carregado por jovens iniciados em Umbravale. Enviado pela instrutora de sacerdotes Shanda, ele serve como uma convocação formal que direciona os futuros servos de Elune aos antigos galhos de Aldrassil.",h="O selo sagrado é um emblema gravado de Elfo Noturno carregado por jovens iniciados em Umbravale.",kw={"aldrassil","o selo sagrado","iniciado","kaldorei","sacerdote","umbravale","shanda","teldrassil"},ang={["class:Priest"]="Para os sacerdotes Elfos Noturnos, O selo sagrado representa sua primeiríssima convocação para o treinamento formal sob a Irmandade de Elune.",["race:NightElf"]="O sinete marca o início do serviço de um devoto Kaldorei em uma época na qual os viajantes da Aliança recém começaram a chegar aos galhos de Teldrassil."},sec={{t="Uma Convocação ao Sacerdócio",b="Sacerdotes Elfos Noturnos novatos que entram na copa sagrada de Umbravale costumam receber O selo sagrado de um mensageiro da floresta. Gravado com marcas sagradas, o emblema funciona como uma ordem pessoal de Shanda, a instrutora de sacerdotes residente em Aldrassil. Carregar e ler o sinete direciona o acólito para o alto, até o imponente tronco oco de Aldrassil, apresentando-o formalmente à Irmandade de Elune e iniciando seu serviço espiritual aos Kaldorei enquanto novos viajantes chegam por Teldrassil."}},faq={{q="O que é O selo sagrado?",a="O selo sagrado é um emblema sagrado gravado entregue a jovens sacerdotes Elfos Noturnos em Umbravale. Ele traz uma convocação instruindo o iniciado a procurar sua mentora, Shanda.",al={"o que e o selo sagrado","sinete de sacerdote umbravale"}},{q="Quem envia O selo sagrado?",a="Ele é enviado por meio de um mensageiro local em nome de Shanda, a instrutora de sacerdotes situada dentro da grande árvore oca de Aldrassil.",al={"quem enviou este sinete","emblema de sacerdote shanda"}},{q="Onde devo levar o sinete?",a="Leve o sinete até Shanda dentro de Aldrassil, localizada no coração de Umbravale, em Teldrassil. Após lê-lo, apresentar o emblema a ela conclui sua apresentação inicial aos seus mentores do sacerdócio.",al={"onde levar o selo sagrado","entregar o selo sagrado"}}},fx={["71c8963a"]={q="Por que Shanda quer que o Hallowed Sigil seja devolvido a ela?",a="O sigilo serve como uma convocação formal e um símbolo introdutório para sacerdotes novatos elfos noturnos. A Sacerdotisa Shanda o enviou através de um mensageiro para chamá-lo para Aldrassil, garantindo que você busque sua orientação enquanto o mundo em geral se agita e viajantes chegam aos galhos de Teldrassil. Retornar com ele confirma que você recebeu sua mensagem e está pronto para começar seu treinamento sagrado.",al={"por que levar hallowed sigil para shanda","por que shanda quer o sigilo","propósito do hallowed sigil"}}},fp="14,133,27.408.0,27.149.0,29.96.0,30.188.0"}
P.entries["item:hallowed-tablet"] = {n="Tabuleta Consagrada",s="A Tabuleta consagrada é uma mensagem inscrita entregue a jovens sacerdotes trolls Lançanegra em treinamento no Vale das Provações. Enviada pelo ancião espiritual Ken'jai, ela convoca os novatos a procurá-lo e começar a aprender como comungar com os espíritos.",h="A Tabuleta consagrada é uma mensagem inscrita entregue a jovens sacerdotes trolls Lançanegra em treinamento...",kw={"lançanegra","durotar","gornek","tabuleta consagrada","ken'jai","sacerdote troll","vale das provações"},ang={["class:Priest"]="A tabuleta marca o início do treinamento formal de um sacerdote em Durotar, estabelecendo seu vínculo com o mentor de classe Ken'jai.",["race:Troll"]="Para os Lançanegra, o sacerdócio é uma comunhão íntima com os espíritos e os loa, tornando o chamado inscrito na tabuleta um convite para as tradições espirituais ancestrais."},sec={{t="Uma Convocação dos Espíritos",b="Quando um promissor sacerdote troll dá seus primeiros passos nos desfiladeiros carmesins e implacáveis do Vale das Provações, Gornek lhe entrega a Tabuleta consagrada. Em vez de uma ordem burocrática formal, ela serve como um convite pessoal de Ken'jai, o instrutor de sacerdotes residente do lado de fora d'O Covil. Ken'jai interpreta os sinais e sussurros dos espíritos, pressentindo quando jovens Lançanegra com potencial espiritual chegam a Durotar. A tabuleta instrui o iniciado a ler suas palavras e se apresentar para receber orientação sobre como canalizar adequadamente a autoridade espiritual."}},faq={{q="O que é a Tabuleta consagrada?",a="É uma tabuleta de pedra inscrita entregue a sacerdotes trolls novatos por Gornek no Vale das Provações. Ela contém uma mensagem direcionando o iniciado a Ken'jai, seu instrutor de classe.",al={"o que é este item","história da tabuleta consagrada","o que a tabuleta faz"}},{q="Quem enviou a tabuleta?",a="A tabuleta foi enviada por Ken'jai, o instrutor de sacerdotes localizado do lado de fora d'O Covil. Os espíritos previram a chegada de um novo acólito, fazendo com que ele enviasse um recado por meio de Gornek.",al={"quem a escreveu","quem me deu isso","autor da tabuleta"}},{q="Por que os sacerdotes trolls precisam ver Ken'jai?",a="Os sacerdotes Lançanegra dependem da comunhão e do comando sobre os espíritos. Ken'jai guia os iniciados à medida que sua conexão espiritual se aprofunda, garantindo que os espíritos estejam dispostos a lhes ensinar habilidades mais potentes.",al={"o que ken'jai faz","por que ver ken'jai"}}},fp="15,147,26.486.0,28.144.0,20.144.0,41.186.0"}
P.entries["item:hammertoe-s-amulet"] = {n="Amuleto do Pé-de-malho",s="O Amuleto do Pé-de-malho é uma lembrança de um anão que investigava o passado de Uldaman. Nos Ermos, ele leva seu trabalho adiante, até quem o conhecia.",h="O Amuleto do Pé-de-malho é uma lembrança de um anão que investigava o passado de Uldaman.",kw={"amuleto","ermos","anões","hammertoe","historiador karnik","prospector ryedol","pergaminhos","clã shadowforge","uldaman"},ang={["race:Dwarf"]="Como anão, a busca de Hammertoe pelas origens de seu povo toca a sua própria herança. Seu amuleto leva esse trabalho aos estudiosos que o conheciam."},sec={{t="A missão de um anão",b="Ferido nos Ermos, Hammertoe pede que você leve seu amuleto ao Prospector Ryedol. Hammertoe buscava as origens de seu povo e tentava impedir que o clã Shadowforge encontrasse os pergaminhos. Ryedol conhece esse trabalho, e Hammertoe confia nele para decidir o que deve ser feito."},{t="Em Altaforja",b="Depois de ouvir o que aconteceu com Hammertoe, Ryedol envia você ao Historiador Karnik, em Altaforja. Karnik e Hammertoe trabalharam juntos para encontrar artefatos perdidos em Uldaman. O amuleto leva o trabalho dos dois às mãos de Karnik, que percebe que ele representa mais do que a dor pela perda do companheiro."}},faq={{q="Quem era Hammertoe?",a="Hammertoe era um anão que buscava as origens de seu povo em Uldaman. Ele também tentava impedir que o clã Shadowforge encontrasse os pergaminhos.",al={"anão hammertoe","quem é hammertoe","história de hammertoe"}},{q="Por que Hammertoe me entrega o amuleto?",a="Hammertoe pede que você leve o amuleto ao Prospector Ryedol, nos Ermos. Ryedol conhece a busca de Hammertoe e pode decidir o que fazer em seguida.",al={"por que o amuleto","por que o amuleto do pé-de-malho","o que fazer com o amuleto"}},{q="Quem é Prospector Ryedol?",a="Prospector Ryedol é o anão a quem Hammertoe confia seu amuleto e seu trabalho em Uldaman.",al={"quem é ryedol","o prospector"}},{q="Por que o amuleto é importante?",a="O amuleto pertencia a Hammertoe e representa seu trabalho de busca pelas origens de seu povo em Uldaman. Ryedol e o Historiador Karnik conhecem esse trabalho.",al={"importância do amuleto","o que ele tem de especial","por que o amuleto importa"}},{q="Quem é Historiador Karnik?",a="O Historiador Karnik está em Altaforja e trabalhou com Hammertoe para encontrar artefatos perdidos em Uldaman. Ryedol direciona você até ele com o amuleto.",al={"quem é karnik","o historiador"}},{q="O que Hammertoe tentava impedir?",a="Hammertoe tentava impedir que o clã Shadowforge encontrasse os pergaminhos em Uldaman.",al={"objetivo de shadowforge","por que impedir shadowforge","pergaminhos em uldaman"}}},fp="18,150,18.291.0,12.285.0,18.143.0,38.147.0,25.88.0,28.149.0,24.136.0,34.82.0"}
P.entries["item:hand-of-dagun"] = {n="Mão de Dagun",s="A Mão de Dagun é uma relíquia procurada por Gerrig Agarrosso em Altaforja. Ela é um dos três itens que ele pede em troca do Compêndio de Yagyin.",h="A Mão de Dagun é uma relíquia procurada por Gerrig Agarrosso em Altaforja.",kw={"dagun","gerrig agarrosso","mão de dagun","legacy heart","veneno","relíquia","estrela de xil'yeh","compêndio de yagyin"},ang={["faction:Alliance"]="Para a Aliança, o pedido de Gerrig Agarrosso é uma oportunidade de ajudar a iniciar um novo capítulo de sua ordem."},sec={{t="Uma Relíquia para Agarrosso",b="Gerrig Agarrosso pede a Mão de Dagun junto com outras duas relíquias. Ele precisa das três antes de entregar a você uma cópia do Compêndio de Yagyin, um texto ligado ao início de um novo capítulo de sua ordem."}},faq={{q="O que é a Mão de Dagun?",a="A Mão de Dagun é uma relíquia que Gerrig Agarrosso pede junto com a Estrela de Xil'yeh e Legacy Heart.",al={"mão de dagun","o que é a mão"}},{q="Quem quer a Mão de Dagun?",a="Gerrig Agarrosso, em Altaforja, pede que você leve a ele a Mão de Dagun e outras duas relíquias.",al={"quem quer a mão de dagun","mão de agarrosso","quem precisa dela"}},{q="Por que Gerrig Agarrosso precisa dela?",a="Gerrig precisa da Mão de Dagun como uma das três relíquias que pede antes de entregar a você uma cópia do Compêndio de Yagyin.",al={"por que agarrosso a quer","por que precisa da mão","para que serve"}},{q="O que a Mão de Dagun faz?",a="Dizem que a Mão de Dagun carrega um veneno que transforma sua vítima em integrante de uma raça antiga.",al={"poderes da mão de dagun","o que ela faz","mão envenenada"}}},fp="13,138,20.193.0,26.100.0,28.90.0,33.110.0,31.97.1"}
P.entries["item:hand-of-dextren-ward"] = {n="Mão de Flávio Lúcio",s="A Mão de Flávio Lúcio é um troféu decepado tirado de um violador de túmulos condenado e aprisionado em Stormwind Stockade. Entregue em Vila Sombria, serve como prova de que a justiça da fronteira foi finalmente feita contra um homem que profanou os mortos da cidade.",h="A Mão de Flávio Lúcio é um troféu decepado tirado de um violador de túmulos condenado e aprisionado em...",kw={"vila sombria","flávio lúcio","floresta do crepúsculo","ebonlocke","mão de flávio lúcio","house of nobles","millstipe","morbent fel","o cárcere"},ang={["class:Mage"]="Lúcio não era um conjurador, mas os corpos que ele desenterrava alimentavam as artes sombrias do necromante Morbent Fel, tornando sua morte um golpe contra aqueles que traficam com os mortos.",["faction:Alliance"]="O atrito em torno da prisão de Lúcio expõe a profunda divisão entre a distante House of Nobles de Ventobravo e os colonos abandonados da fronteira da Floresta do Crepúsculo."},sec={{t="O Preço de um Profanador",b="Flávio Lúcio recebeu uma sentença de morte de Lord Ebonlocke após ser flagrado desenterrando corpos nos cemitérios da Floresta do Crepúsculo e vendendo-os ao necromante Morbent Fel. Antes que a cidade pudesse executá-lo, Ventobravo interveio, levando o criminoso para O Cárcere. Para as famílias enlutadas de Vila Sombria, a Mão de Flávio Lúcio é a prova física de que o profanador teve a execução que merecia, contornando a leniência indesejada da House of Nobles."},{t="Uma Mensagem aos Nobres",b="Além de satisfazer a vingança local, exigir a mão decepada de Lúcio é um ato de desafio do Conselheiro Bonfá-lobos contra a coroa. A Floresta do Crepúsculo se sente abandonada pela elite de Ventobravo, que nega ajuda militar mas impõe sua própria autoridade quando lhe convém. Executar um prisioneiro nas masmorras mais profundas da capital e reivindicar sua mão é um lembrete contundente de que o Conselho de Vila Sombria aplicará suas próprias leis quando a House of Nobles falhar com eles."}},faq={{q="Quem foi Flávio Lúcio?",a="Flávio Lúcio foi um criminoso pego desenterrando cadáveres dos cemitérios de Vila Sombria e vendendo-os ao vil necromante Morbent Fel. Embora sentenciado à decapitação na Floresta do Crepúsculo, as autoridades de Ventobravo o transferiram para O Cárcere em vez de cumprir a execução.",al={"história de flávio lúcio","quem é flávio lúcio","crime de lúcio"}},{q="Por que Vila Sombria quer a mão dele?",a="O Conselheiro Bonfá-lobos exige a mão decepada de Lúcio como prova incontestável de seu assassinato. Ela traz alívio às famílias cujos túmulos dos ancestrais foram saqueados e serve como uma mensagem desafiadora à corrupta House of Nobles de que a justiça de Vila Sombria não pode ser anulada.",al={"por que mão decepada","por que cortar a mão de lúcio","prova de bonfá-lobos"}},{q="Onde a Mão de Flávio Lúcio é encontrada?",a="A mão é obtida diretamente do próprio Flávio Lúcio. Ele está trancado nas câmaras mais profundas do lado esquerdo de Stormwind Stockade, onde luta como um guerreiro, com um brado aterrorizante que faz os inimigos fugirem.",al={"onde encontrar lúcio","localização de lúcio no cárcere","localização de flávio lúcio"}},{q="Por que Ventobravo aprisionou Lúcio em vez de executá-lo?",a="A House of Nobles reivindicou jurisdição sobre Lúcio e preferiu aprisioná-lo em O Cárcere em vez de permitir que Vila Sombria executasse sua sentença de morte. A liderança de Vila Sombria vê essa medida como uma interferência burocrática corrupta que desrespeita a difícil situação da cidade fronteiriça.",al={"por que lúcio foi poupado","câmara dos nobres de ventobravo lúcio","lúcio aprisionado"}}},fx={["48b9455f"]={q="O que é a Mão de Flávio Lúcio?",a="É a mão decepada de Flávio Lúcio, um notório ladrão de túmulos e profanador dos mortos que foi pego vendendo cadáveres do cemitério de Vila Sombria para o necromante Morbent Fel. Tomada como prova física de seu assassinato dentro da Stormwind Stockade, ela serve como uma confirmação sombria de que a sentença de morte do Lorde Ebonlocke foi finalmente executada.",al={"o que é mão de flávio lúcio","item mão de flávio lúcio","mão de flávio lúcio"}},b59a9a35={q="De onde vem a Mão de Flávio Lúcio?",a="Ela vem diretamente do corpo de Flávio Lúcio, decepada pela sua própria lâmina dentro de sua cela no Cárcere de Ventobravo. Em vez de ser forjada ou criada, ela é tomada como um troféu irrefutável de justiça para ser entregue ao Conselheiro Bonfá-lobos na Floresta do Crepúsculo.",al={"onde surgiu a mão de flávio lúcio","quem fez a mão de flávio lúcio","origem da mão de flávio lúcio"}}},fp="20,181,16.374.0,23.378.1,21.246.0,33.225.0,40.189.0,57.245.0"}
P.entries["item:hand-of-iruxos"] = {n="Hand of Iruxos",s="A Hand of Iruxos é um artefato medonho que pode abrir portais demoníacos e fechar os que abriu. Taiga Crina Sábia precisa dele para ajudar a banir os portais nas Ruínas de Mannoroc.",h="A Hand of Iruxos é um artefato medonho que pode abrir portais demoníacos e fechar os que abriu.",kw={"lâmina ardente","portais demoníacos","hand of iruxos","iruxos","ruínas de mannoroc","aldeia pescassombra","taiga crina sábia"},sec={{t="Uma visão grotesca",b="Na Aldeia Pescassombra, Taiga Crina Sábia entrega a Hand of Iruxos a você e pede que a leve às Ruínas de Mannoroc. Os cultistas da Lâmina Ardente abriram portais que trazem demônios ao mundo. A mão pode fechar os portais que abriu, e Taiga precisa do poder dela para conter a crescente ameaça demoníaca."}},faq={{q="O que é a Hand of Iruxos?",a="É uma relíquia macabra que abre portais demoníacos e pode fechar os que abriu.",al={"hand of iruxos","mão de iruxos"}},{q="Quem me dá a Hand of Iruxos?",a="Taiga Crina Sábia, na Aldeia Pescassombra, entrega a Hand of Iruxos a você e pede que a use contra os portais nas Ruínas de Mannoroc.",al={"quem tem a mão","mão de taiga"}},{q="Onde uso a Hand of Iruxos?",a="Taiga Crina Sábia pede que você use a Hand of Iruxos para banir portais demoníacos nas Ruínas de Mannoroc.",al={"localização da mão","onde usar a mão"}},{q="Por que há demônios nas Ruínas de Mannoroc?",a="Os cultistas da Lâmina Ardente abriram portais nas Ruínas de Mannoroc que trazem demônios ao mundo.",al={"demônios de mannoroc","por que há demônios"}},{q="A Hand of Iruxos pode fechar portais?",a="A Hand of Iruxos pode fechar os portais demoníacos que abriu.",al={"fechar portais","mão do portal"}}},fp="14,172,16.299.0,27.82.0,32.127.0,34.94.0,39.94.0,37.59.0"}
P.entries["item:handful-of-oats-classic"] = {n="Punhado de Aveia",s="Punhados de Aveia são grãos simples recuperados das fazendas abandonadas de Cerro Oeste. Eles servem como alimento essencial para animais de tração em trabalho, como a Velha Blanchy, que sofrem sob o peso das viagens de refugiados.",h="Punhados de Aveia são grãos simples recuperados das fazendas abandonadas de Cerro Oeste.",kw={"blanchy","furlbrow","grão","punhado de aveia","aveia","sacos de aveia","cerro oeste"},ang={["faction:Alliance"]="Para viajantes da Aliança passando por Cerro Oeste, catar aveia para ajudar refugiados retidos como os Furlbrows é um pequeno ato de misericórdia em meio à fronteira negligenciada de Ventobravo."},sec={{t="Forragem Entre as Ruínas",b="Outrora o celeiro do Reino de Ventobravo, as vastas terras agrícolas de Cerro Oeste agora jazem abandonadas ou tomadas por bandidos Défias e golens de colheita rebeldes. Apesar do colapso da ordem, sacos de grãos cultivados e aveia continuam abandonados perto de dependências, celeiros e terrenos tomados pelo mato. Para viajantes e refugiados retidos por carroças quebradas ao longo das estradas empoeiradas, recuperar punhados dessas sobras de aveia é uma das poucas maneiras de nutrir cavalos de tração exaustos."}},faq={{q="Para que servem os Punhados de Aveia?",a="Eles são coletados para alimentar a Velha Blanchy, uma égua cansada pertencente à família Furlbrow. Depois que a carroça deles quebrou na estrada em Cerro Oeste, ela ficou exausta e necessitando desesperadamente de nutrição.",al={"para que serve a aveia","por que coletar aveia","uso do punhado de aveia"}},{q="Onde esta aveia pode ser encontrada?",a="Punhados de Aveia são recolhidos de sacos espalhados pelas fazendas abandonadas em Cerro Oeste, particularmente ao sudoeste.",al={"onde encontrar aveia","localização do saco de aveia","como obter aveia"}},{q="Por que os sacos de aveia foram deixados desprotegidos?",a="A ascensão repentina da Irmandade Défias e o descontrole das máquinas de colheita rebeldes forçaram os fazendeiros locais a fugir às pressas de suas terras, deixando para trás grãos colhidos e suprimentos em seus campos e celeiros.",al={"por que sacos abandonados","quem deixou a aveia"}}},fx={["67495104"]={q="O que é um Punhado de Aveia?",a="Um Punhado de Aveia é uma ração simples para gado colhida dos sacos de aniagem deixados espalhados pelas fazendas de Cerro Oeste. Em dias férteis, estes grãos sustentavam os cavalos de carga e animais de arado do reino. Hoje, com os campos abandonados aos golens de colheita ladinos e bandidos, aveia solta está entre as poucas sobras de ração limpa que restam para uma besta de carga faminta.",al={"o que são punhados de aveia","item punhado de aveia","o que é um punhado de aveia"}},a4d08151={q="Por que alguém quer um Punhado de Aveia?",a="Vera Taturana precisa desesperadamente deles para nutrir Blanchy, a dedicada égua de carga de sua família. Depois que os Taturana fugiram de sua casa, a carroça deles quebrou na estrada, deixando Blanchy exausta, faminta e em seus últimos momentos. Alguns punhados nutritivos de grãos são tudo o que mantém a égua fiel viva enquanto a família permanece presa.",al={"quem quer o punhado de aveia","por que colher aveia","por que precisa de um punhado de aveia"}}},fp="15,75,22.347.0,35.137.0,30.94.0,37.187.0"}
P.entries["item:handful-of-stardust"] = {n="Punhado de Poeira Estelar",s="Punhados de Poeira Estelar são camadas cintilantes e congeladas colhidas de arbustos brilhantes na vastidão sul de Vale Gris. Obtido nas antigas Ruínas de Poeira Estelar, este pó possui propriedades naturais refrescantes estimadas pelos curandeiros elfos noturnos no tratamento de febres intensas.",h="Punhados de Poeira Estelar são camadas cintilantes e congeladas colhidas de arbustos brilhantes na vastidão...",kw={"vale gris","astranaar","orendil","pelturas","cataplasma","relara","ruínas de poeira estelar","poeira estelar"},ang={["profession:Herbalism"]="Embora seja colhida diretamente à mão de arbustos cintilantes em vez de ser coletada como um reagente botânico formal, a poeira estelar exemplifica a dependência dos elfos noturnos da flora regional rara para a medicina restauradora.",["race:NightElf"]="Para os Kaldorei que defendem Vale Gris, obter remédios locais como a poeira estelar reflete a harmonia duradoura entre suas ruínas antigas e as tradições de herborismo."},sec={{t="Um Remédio Herbáceo Refrescante",b="Encontrada aderida aos arbustos folhosos dentro das antigas Ruínas de Poeira Estelar, ao sul de Astranaar, a poeira estelar surge como uma geada fina e luminosa. Embora as próprias ruínas sejam assombradas por espíritos elementais remanescentes, a vegetação que viceja entre as pedras partidas absorve uma rara luminescência ambiente. A medicina tradicional dos elfos noturnos utiliza esse resíduo congelado, processando-o em cataplasmas para extrair febres persistentes e perigosas quando os unguentos comuns e as águas do Poço Lunar não conseguem trazer alívio completo."},{t="A Esperança de um Pai",b="Pelturas Lunalva, um pai angustiado em Astranaar, buscou esse pó a conselho do herborista Orendil Folharga. A jovem filha de Pelturas, Relara, fora afligida por uma enfermidade mágica teimosa e pesadelos. Embora uma bênção inicial de uma pedra tocada por Elune tenha acalmado sua mente, uma febre corporal intensa persistia, motivando a busca por poeira estelar para preparar uma pasta refrescante que salvasse a vida da criança."}},faq={{q="Onde é encontrado o Punhado de Poeira Estelar?",a="Ele é colhido de arbustos cintilantes cobertos de poeira estelar que crescem por todas as Ruínas de Poeira Estelar, localizadas ao sul do assentamento de elfos noturnos de Astranaar, no centro de Vale Gris.",al={"localização da poeira estelar","onde encontrar poeira estelar","arbustos cobertos de poeira estelar"}},{q="Para que serve esta poeira estelar?",a="Pelturas Lunalva, em Astranaar, usa o pó para preparar um cataplasma calmante destinado a quebrar a febre implacável que aflige sua filha doente, Relara.",al={"uso da poeira estelar","cura de pelturas","propósito da poeira estelar"}},{q="Quais perigos cercam os arbustos de poeira estelar?",a="As Ruínas de Poeira Estelar são habitadas por elementais da água hostis que espreitam perto da margem e entre os antigos pilares caídos onde crescem os arbustos.",al={"inimigos de ruínas de poeira estelar","mobs de ruínas de poeira estelar"}},{q="A poeira estelar está relacionada à deusa Elune?",a="Embora os elfos noturnos reverenciem poderes celestes e as ruínas tragam um nome estrelado, a poeira estelar funciona primariamente como um ingrediente medicinal físico recomendado por herboristas por sua natureza gélida e refrescante.",al={"poeira estelar é mágica","conexão de elune com poeira estelar"}}},fx={["8cce1335"]={q="O que é um Punhado de Poeira Estelar?",a="Um Punhado de Poeira Estelar é um pó cintilante e congelado coletado da folhagem brilhante dentro das antigas Ruínas de Poeira Estelar de Vale Gris. Este raro resíduo botânico possui propriedades calmantes e de resfriamento mágico, tornando-o inestimável para preparar cataplasmas de ervas potentes para tratar febres persistentes e ameaçadoras.",al={"o que é um punhado de poeira estelar","o que é poeira estelar","história do item poeira estelar"}}},fp="19,128,23.366.0,15.368.1,39.106.0,31.160.0,42.126.0,41.119.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Casco Endurecido de Tartaruga",s="Hardened Tortoise Shells são carapaças incrivelmente duráveis obtidas de tartarugas casco de faísca que vagueiam pela Chapada Cintilante. Cobiçadas por corredores gnomos no Circuito da Ilusão, essas placas orgânicas e resistentes oferecem uma proteção inigualável contra combustíveis experimentais voláteis e corrosivos.",h="Hardened Tortoise Shells são carapaças incrivelmente duráveis obtidas de tartarugas casco de faísca que...",kw={"casco endurecido de tartaruga","circuito da ilusão","carro-foguete","chapada cintilante","casco de faísca","capu latafuso"},ang={["profession:Engineering"]="Usar carapaças orgânicas como tanques de combustível de alta pressão foge do comum, mas quando o combustível desenvolvido por gnomos derrete tubulações de ligas padrão, materiais naturais de alta durabilidade costumam salvar o dia.",["race:Gnome"]="Apenas a engenhosidade gnômica olharia para uma tartaruga do deserto e pensaria imediatamente em um recipiente leve e altamente resistente para combustível de foguete perigoso."},sec={{t="Armadura Natural para Perigos em Alta Velocidade",b="A extensão crestada pelo sol da Chapada Cintilante abriga várias espécies de tartarugas casco de faísca, incluindo mordedoras e perfuradoras, cujas carapaças evoluíram para se tornarem defesas excepcionalmente resistentes contra o sal impiedoso do deserto e predadores errantes. Na planície salgada, tanques de combustível comuns feitos de ligas metálicas costumam se corroer ou romper sob a pressão da química experimental gnômica. Mecânicos como Capu Latafuso valorizam essas carapaças não como armaduras ou escudos, mas como matéria-prima orgânica resistente o suficiente para ser adaptada em tanques de combustível improvisados e resistentes a ácidos, capazes de conter propelentes de foguete voláteis."}},faq={{q="Onde você encontra Hardened Tortoise Shells?",a="Elas são obtidas de tartarugas casco de faísca — especificamente Sparkleshell Snappers, Borers e Sparkleshell Tortoises comuns — que vagam pelas extensões abertas de sal da Chapada Cintilante, em Mil Agulhas.",al={"onde conseguir carapaças de tartaruga","localização de carapaça endurecida","localização de casco de faísca"}},{q="Por que Capu Latafuso quer essas carapaças?",a="O irmão de Capu está criando um combustível de foguete extremamente potente e corrosivo, que ameaça derreter o chassi do carro de corrida deles. Capu pretende esvaziar e reforçar as carapaças excepcionalmente duráveis das tartarugas para utilizá-las como tanques de combustível quimicamente resistentes.",al={"para que servem as carapaças","uso das carapaças de capu","qual a utilidade das carapaças"}},{q="Ferramentas de oficina padrão conseguem moldá-las facilmente?",a="Não. As carapaças são tão descomunalmente rígidas que os mecânicos gnomos preveem entortar e estragar uma caixa de ferramentas inteira de utensílios metálicos apenas na tentativa de entalhar, perfurar e moldá-las em formato de tanques.",al={"carapaças são difíceis de trabalhar","entortar ferramentas carapaça"}}},fx={cc86b908={q="O que é um Casco Endurecido de Tartaruga?",a="É a carapaça externa natural, excepcionalmente durável, colhida das grandes tartarugas de casco brilhante que vagam pelas salinas. Esses cascos são conhecidos por serem muito mais resistentes do que peles comuns de bestas ou placas padrão, resistindo ao atrito, sal e erosão química intensa.",al={"o que é um casco endurecido de tartaruga","item casco endurecido de tartaruga","casco endurecido"}},["4ed6fee7"]={q="De onde vem um Casco Endurecido de Tartaruga?",a="Esses cascos são completamente naturais, em vez de fabricados. Eles são colhidos diretamente das tartarugas de casco brilhante, cágados e perfuradores que prosperam no agreste deserto de sal sob o sol escaldante da Chapada Cintilante em Mil Agulhas.",al={"origem do casco endurecido de tartaruga","quem fez o casco endurecido de tartaruga","de onde vêm os cascos endurecidos"}}},fp="23,236,36.355.0,43.181.0,45.238.0,46.156.0"}
P.entries["item:hardened-tumor"] = {n="Tumor Endurecido",s="Um Tumor Endurecido é uma anomalia biológica rara coletada dos murlocs da tribo Barbatanavil que habitam ao redor do Espelho de Lordaeron. Observado originalmente nas pesquisas do Boticário Berardo, agora um servo sem mente de Arugal, este crescimento calcificado serve como um reagente incomum nos esforços da Real Sociedade de Boticários para preparar a Nova Praga.",h="Um Tumor Endurecido é uma anomalia biológica rara coletada dos murlocs da tribo Barbatanavil que habitam ao...",kw={"boticário faranello","boticário renferrel","berardo","ilhas da aurora","tumor endurecido","espelho de lordaeron","murloc","nova praga","barbatanavil"},ang={["race:Undead"]="Obter o tumor impulsiona a pesquisa vital do Mestre-boticário Faranello sobre a Nova Praga, servindo a Lady Sylvanas e à luta dos Renegados contra seus adversários vivos e mortos-vivos."},sec={{t="Uma Anomalia Biológica Rara",b="Ao estudar a vida selvagem nativa ao longo das fronteiras orientais da Floresta de Pinhaprata, o Boticário Berardo catalogou um crescimento calcificado anormal que se desenvolvia dentro dos murlocs Barbatanavil do Espelho de Lordaeron. Tais crescimentos são extremamente raros, aparecendo apenas em espécimes maduros ao longo da costa e nas Ilhas da Aurora. O que causa nos murlocs Barbatanavil a produção dessas massas endurecidas permanece incerto, mas seu tecido denso e mórbido chamou a atenção imediata da Real Sociedade de Boticários."},{t="Combustível para a Nova Praga",b="Depois que a maldição de Arugal deixou Berardo como um servo sem mente, seu diário foi recuperado do Vilarejo Lenhardente e levado ao Boticário Renferrel no Sepulcro. Reconhecendo o potencial no trabalho de Berardo, Renferrel encarregou agentes dos Renegados de recuperar um Tumor Endurecido juntamente com musgos aquáticos nativos. O Mestre-boticário Faranello supervisiona o Boticarium na Cidade Baixa, buscando reagentes que possam resistir à decomposição ou alterar matéria biológica. Ele incorporou este crescimento peculiar diretamente na preparação contínua da Nova Praga pela Sociedade."}},faq={{q="O que é um Tumor Endurecido?",a="É uma massa calcificada anormal que raramente se forma dentro dos murlocs Barbatanavil que vivem ao redor do Espelho de Lordaeron. Descoberto pelo pesquisador dos Renegados, o Boticário Berardo, ele resiste à degradação física normal e possui propriedades biológicas únicas.",al={"o que é este tumor","história do tumor","obtenção de tumor endurecido"}},{q="Por que a Real Sociedade de Boticários o quer?",a="O Mestre-boticário Faranello e a Real Sociedade de Boticários estão reunindo espécimes tóxicos e biológicos incomuns para sintetizar a Nova Praga. A resiliência anormal e a composição celular do tumor o tornam um excelente candidato para seus experimentos com a praga.",al={"por que o boticário quer o tumor","uso do tumor na receita da morte","tumor de faranello"}},{q="Onde esses tumores são encontrados?",a="Eles são obtidos dos murlocs Barbatanavil na Floresta de Pinhaprata, especificamente aqueles que habitam as Ilhas da Aurora no leste do Espelho de Lordaeron e as margens do vilarejo a nordeste de Lenhâmbar.",al={"onde encontrar tumor endurecido","quais murlocs deixam cair o tumor","localização do tumor"}},{q="Quem era o Boticário Berardo?",a="Berardo era um boticário da Real Sociedade de Boticários estacionado na Floresta de Pinhaprata. Antes que a maldição de Arugal o deixasse como um servo sem mente no Vilarejo Lenhardente, ele compilou pesquisas detalhadas sobre a flora, fauna e mutações de murlocs locais, descobrindo a utilidade dos musgos e dos tumores endurecidos das Ilhas da Aurora.",al={"quem é berardo","história de berardo","diário de berardo"}}},fx={["9aa7efc6"]={q="De onde vem um Tumor Endurecido?",a="Tumores endurecidos são crescimentos biológicos anormais encontrados nos murlocs Barbafenosa que habitam ao redor do Espelho de Lordaeron na Floresta de Pinhaprata. Eles não são criados por mãos mortais, mas sim colhidos da carne dessas criaturas anfíbias contaminadas. O Boticário Berardo documentou pela primeira vez sua existência em sua pesquisa de campo, observando que encontrar um murloc portando tal crescimento calcificado e incomumente denso é notavelmente raro.",al={"origem do tumor endurecido","de onde vêm os tumores endurecidos","quem fez o tumor endurecido"}}},fp="14,179,25.353.0,23.477.1,25.212.0,46.223.0,29.175.0,26.287.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Anel de Tenente Harpia",s="Os Anéis de Tenente Harpia são adornos rústicos usados pelas Witchwing Slayers nos Montes Áridos, no norte dos Sertões. Carregados como emblemas de comando no bando, eles servem como prova de morte para Darsok Punhálacre na Encruzilhada.",h="Os Anéis de Tenente Harpia são adornos rústicos usados pelas Witchwing Slayers nos Montes Áridos, no norte...",kw={"encruzilhada","darsok punhálacre","montes áridos","anel de tenente harpia","sertões","witchwing","witchwing slayer"},ang={["class:Rogue"]="Darsok Punhálacre prefere ataques cirúrgicos contra alvos de alto valor, dando prioridade a assassinos capazes de se infiltrar nos ninhos das harpias para eliminar os comandantes diretamente.",["faction:Horde"]="As harpias Witchwing fustigam constantemente as linhas de suprimento entre Durotar, Mulgore e os postos avançados do norte; quebrar sua liderança garante passagem segura para as caravanas da Horda pelos Sertões."},sec={{t="Símbolos de Posto",b="Dentro da hierarquia matriarcal das harpias Witchwing, a posição social é mantida impiedosamente. Enquanto os saqueadores comuns que assolam os Sertões lutam com pouca coordenação, as Witchwing Slayers atuam como tenentes de campo comandando ataques contra viajantes da Horda. Para se destacar e impor autoridade sobre suas subordinadas, essas matadoras veteranas carregam anéis característicos. Para Darsok Punhálacre e os defensores posicionados na Encruzilhada, cortar esses anéis das harpias derrotadas é a única forma garantida de confirmar que a liderança intermediária do bando foi desmantelada."}},faq={{q="Quem carrega esses anéis?",a="Os anéis são carregados especificamente pelas Witchwing Slayers, as harpias veteranas que atuam como tenentes no bando Witchwing nos Montes Áridos.",al={"quem concede anel de tenente harpia","anéis de witchwing slayer","quais harpias têm anéis"}},{q="Onde as Witchwing Slayers podem ser encontradas?",a="As Witchwing Slayers fazem seus ninhos nos Montes Áridos, uma região escarpada e elevada situada no extremo norte dos Sertões, logo a noroeste da Encruzilhada.",al={"localização de witchwing slayer","onde encontrar tenentes harpias","harpias dos montes áridos"}},{q="Por que Darsok Punhálacre quer esses anéis?",a="Darsok deseja despedaçar a estrutura de comando das harpias. Eliminar os tenentes lança seus grupos de saque no caos, punindo o bando por atacar caravanas e viajantes da Horda por todos os Sertões.",al={"por que coletar anéis de harpia","anéis de darsok punhálacre"}},{q="As harpias saqueadoras comuns carregam esses anéis?",a="Não. As invasoras comuns são subordinadas de baixo escalão. Os anéis representam comando e são usados apenas pelas Witchwing Slayers.",al={"invasores podem conceder anéis","witchwing raiders têm anéis"}}},fx={["105f77c8"]={q="O que é um Anel de Tenente Harpia?",a="Esses anéis são adornos distintos carregados pelas matadoras Asa-bruxa dos Montes Áridos. Dentro de seus ninhos, as matadoras agem como tenentes, comandando as subordinadas harpias menores em nome de suas matriarcas. Para os batedores da Horda que observam os Sertões, essas bugigangas servem como prova identificável de patente entre o bando vicioso.",al={"o que é um anel de tenente harpia","identidade do anel harpia","história do anel de tenente harpia"}}},fp="21,180,14.331.0,24.88.0,37.94.0,38.129.0,43.96.0"}
P.entries["item:hatecrest-naga-scale"] = {n="Hatecrest Naga Scale",s="As Hatecrest Naga Scales são retiradas dos naga que ameaçam a Ilha de Sardor, em Feralas. Latrônicus Lunalança, no Domínio de Plumaluna, quer enfraquecer a presença dos naga e estudar o que pode ser feito com elas.",h="As Hatecrest Naga Scales são retiradas dos naga que ameaçam a Ilha de Sardor, em Feralas.",kw={"domínio de plumaluna","hatecrest naga scale","hatecrest scales","latrônicus lunalança","naga","pratt","ilha de sardor"},ang={["race:NightElf"]="Como elfo noturno, você ajuda Latrônicus a proteger os interesses do Domínio de Plumaluna na Ilha de Sardor. Ele diz que seu povo busca a paz, mas agirá para defender o que lhe pertence."},sec={{t="Escamas para Plumaluna",b="Latrônicus Lunalança pede que você leve dez Hatecrest Naga Scales ao Domínio de Plumaluna. Ele teme que os naga tentem tomar a Ilha de Sardor, por isso pretende enfraquecer a presença deles antes que essa ameaça cresça. As escamas precisam estar em boas condições. Quando as receber, ele planeja enviá-las a Pratt para estudo e possível uso em artesanato."}},faq={{q="Para que servem as Hatecrest Naga Scales?",a="Latrônicus Lunalança quer dez Hatecrest Naga Scales em boas condições para enfraquecer a presença dos naga na Ilha de Sardor. Ele também planeja enviá-las a Pratt para descobrir se podem ser usadas em artesanato.",al={"por que escamas","uso das hatecrest scales","finalidade das escamas"}},{q="Quem quer as escamas?",a="Latrônicus Lunalança, do Domínio de Plumaluna, pede dez Hatecrest Naga Scales.",al={"quem precisa de escamas","escamas de latrônicus","escamas para quem"}},{q="Por que Plumaluna quer enfraquecer os naga?",a="Latrônicus teme que os naga Hatecrest tentem tomar a Ilha de Sardor, então quer enfraquecer a presença deles antes que consigam.",al={"por que lutar contra os hatecrest","ameaça dos naga","por que ilha de sardor"}},{q="O que Pratt pode fazer com as escamas?",a="Latrônicus planeja enviar as escamas a Pratt, que talvez consiga fabricar algo útil com elas.",al={"escamas para pratt","fabricar com escamas","artesanato com escamas"}}},fp="20,205,22.331.0,35.182.0,21.82.0,45.127.0,36.98.0"}
P.entries["item:hatefury-claw"] = {n="Hatefury Claw"}
P.entries["item:hatefury-horn"] = {n="Hatefury Horn",s="Um Hatefury Horn é retirado de um dos sátiros nas ruínas de Sargeron, a leste de Nijel’s Point. Kreldig Ungor reúne chifres e garras para uma lista de reagentes de Kharanos.",h="Um Hatefury Horn é retirado de um dos sátiros nas ruínas de Sargeron, a leste de Nijel’s Point.",kw={"hatefury claw","hatefury horn","sátiro hatefury","kreldig ungor","leftwitch","posto do nijel","reagentes","sargeron"},ang={["race:Gnome"]="Como gnomo, você talvez conheça Leftwitch de nome: a maga em Kharanos enviou uma lista de reagentes aos Reclaimers."},sec={{t="Um reagente de Sargeron",b="A leste de Nijel’s Point, os sátiros Hatefury assombram as ruínas de Sargeron. Seus chifres estão entre os reagentes de que Kreldig Ungor precisa para Leftwitch, uma maga gnoma em Kharanos. Kreldig pede dez chifres e dez Hatefury Claws, mas não pode garantir a qualidade deles."}},faq={{q="De onde vêm os Hatefury Horns?",a="Os sátiros Hatefury nas ruínas de Sargeron, a leste de Nijel’s Point, carregam os chifres.",al={"origem de hatefury horn","onde conseguir chifres","chifres de sátiro"}},{q="Quem quer Hatefury Horns?",a="Kreldig Ungor reúne dez Hatefury Horns para uma lista de reagentes enviada por Leftwitch, uma maga gnoma em Kharanos.",al={"quem precisa de hatefury horns","chifres para kreldig","reagentes para reclaimers"}},{q="Por que Kreldig está reunindo os chifres?",a="Kreldig reúne os chifres como reagentes para Leftwitch, em Kharanos.",al={"por que os chifres","reagentes de leftwitch","para que servem os chifres"}},{q="De que mais Kreldig precisa?",a="Kreldig também pede dez Hatefury Claws.",al={"outros reagentes","hatefury claws","o que fazer com os chifres"}}},fp="13,166,23.263.0,34.78.0,25.105.0,31.64.0,28.41.0"}
P.entries["item:head-of-arugal"] = {n="Cabeça de Arugal",s="A Cabeça de Arugal é o troféu macabro tirado do arquimago louco no topo da Bastilha da Presa Negra. Levada aos Renegados no Sepulcro, ela serve como prova irrefutável de que o mestre dos worgens locais caiu.",h="A Cabeça de Arugal é o troféu macabro tirado do arquimago louco no topo da Bastilha da Presa Negra.",kw={"arugal","arugal tem que morrer","dalar tessalba","cabeça de arugal","o sepulcro","bastilha da presa negra","floresta de pinhaprata"},ang={["class:Mage"]="A cabeça decepada de um ex-arquimago do Kirin Tor serve como um aviso severo da loucura e ruína que invocações desesperadas e desmedidas podem trazer até mesmo aos praticantes mais talentosos.",["race:Undead"]="Para os Renegados, entregar a cabeça de Arugal elimina um feiticeiro instável às suas portas ao sul, assegurando a Floresta de Pinhaprata para a Dama Sombria."},sec={{t="Troféu do Arquimago Louco",b="O Arquimago Arugal há muito lança uma sombra sombria sobre a Floresta de Pinhaprata, comandando os horrores lupinos das muralhas da Bastilha da Presa Negra. Reivindicar sua cabeça decepada é o mandato supremo dado por Dalar Tessalba no Sepulcro. Para os Renegados, a cabeça é muito mais do que uma lembrança grotesca; ela simboliza a eliminação de um conjurador poderoso cujas feras ferozes impediam o domínio total de Lady Sylvana sobre Pinhaprata. Apresentá-la a Tessalba confirma que a feitiçaria nefasta do arquimago renegado foi finalmente extirpada da região."}},faq={{q="Quem quer a Cabeça de Arugal?",a="Dalar Tessalba, um emissário situado no Sepulcro, na Floresta de Pinhaprata, exige a cabeça como parte da missão 'Arugal tem que morrer'.",al={"quem precisa da cabeça de arugal","onde entregar a cabeça de arugal","quem recebe a cabeça de arugal"}},{q="Onde você obtém a Cabeça de Arugal?",a="Ela é decepada do próprio Arquimago Arugal, que reside no pináculo mais alto da Bastilha da Presa Negra, com vista para o Vilarejo Lenhardente e os bosques de Pinhaprata.",al={"como conseguir a cabeça de arugal","saque da cabeça de arugal","onde fica a cabeça de arugal"}},{q="Por que os Renegados querem Arugal morto?",a="A presença de Arugal e sua matilha de worgens ferozes impedem que os Renegados protejam a Floresta de Pinhaprata como um reduto estratégico seguro para Lady Sylvana e a Cidade Baixa.",al={"por que matar arugal","motivo renegados arugal","por que dalar quer arugal morto"}},{q="O que acontece depois que a cabeça é entregue?",a="Dalar Tessalba jura erradicar os resquícios dos feitiços vis de Arugal, declarando que Pinhaprata está finalmente livre das garras do mago louco.",al={"apos arugal morrer","resultado de arugal tem que morrer"}}},fx={c9f64370={q="O que é a Cabeça de Arugal?",a="A Cabeça de Arugal é a cabeça decepada do Arquimago Arugal, o louco ex-mago de Dalaran que libertou os worgens na Floresta de Pinhaprata. Tomada de sua fortaleza na Bastilha da Presa Negra, ela serve como prova física inegável de que o feiticeiro enlouquecido foi finalmente morto e suas magias sombrias quebradas.",al={"o que é a cabeça de arugal","item cabeça de arugal","cabeça de arugal"}},["10305f38"]={q="De onde vem a Cabeça de Arugal?",a="A cabeça é reivindicada diretamente do Arquimago Arugal dentro das alturas da Bastilha da Presa Negra. Após invadir a fortaleza amaldiçoada e superar o louco arquimago em batalha, você o derrota e reivindica sua cabeça para confirmar sua morte.",al={"onde você pega a cabeça de arugal","quem deixa cair a cabeça de arugal","origem da cabeça de arugal"}}},fp="14,152,26.345.0,29.128.0,39.144.0,37.160.0,41.147.1"}
P.entries["item:head-of-bangalash"] = {n="Head of Bangalash",s="Rosarães Guima busca a Cabeça de Bangalash na Selva do Espinhaço. O grande tigre branco é a presa mais recente de sua caçada.",h="Rosarães Guima busca a Cabeça de Bangalash na Selva do Espinhaço.",kw={"caçador de caça grossa","cabeça de bangalash","rosarães guima","troféu de caça","rei bangalash","selva do espinhaço","tigre branco"},ang={["class:Hunter"]="Como caçador, a perseguição de Rosarães ao Rei Bangalash é uma prova de sua habilidade em caçar e rastrear."},sec={{t="O Grande Tigre Branco",b="Rosarães Guima caça o Rei Bangalash há muito tempo. Depois das caçadas a Sin'Dall, Bhag'thera e Tethis, o grande tigre branco é o prêmio que ele ainda busca. A cabeça do tigre prova que a caçada terminou."}},faq={{q="Quem quer a Cabeça de Bangalash?",a="Rosarães Guima quer a Cabeça de Bangalash como prêmio por sua caçada ao Rei Bangalash.",al={"quem quer a cabeça do tigre","troféu de rosarães","para quem é"}},{q="O que é Bangalash?",a="O Rei Bangalash é um grande tigre branco na Selva do Espinhaço.",al={"quem é bangalash","tigre branco","tigre rei"}},{q="Por que Rosarães quer a cabeça?",a="Rosarães persegue o Rei Bangalash há muito tempo e chama o tigre de verdadeiro prêmio da caçada.",al={"por que rosarães o quer","caçada a bangalash","por que matar bangalash"}},{q="Quais caçadas vieram antes de Bangalash?",a="Rosarães cita Sin'Dall, Bhag'thera e Tethis entre as caçadas anteriores à do Rei Bangalash.",al={"caça grossa anterior","sin'dall bhag'thera tethis","o que rosarães caçou"}}},fp="17,123,21.207.0,32.89.0,18.60.0,29.97.0,33.91.0"}
P.entries["item:head-of-baron-vardus"] = {n="Head of Baron Vardus",s="A cabeça decepada do Barão Vardus prova que Costa Sul caçava o antigo nobre de Alterac. O Magistrado Maleb busca justiça pela brutalidade imposta à cidade.",h="A cabeça decepada do Barão Vardus prova que Costa Sul caçava o antigo nobre de Alterac.",kw={"alterac","barão vardus","cabeça do barão vardus","magistrado maleb","costa sul","strahnbrad","camarilha"},ang={["faction:Alliance"]="Como viajante da Aliança, você pode ver Costa Sul buscando justiça contra um nobre da Camarilha que enviou capangas contra a cidade."},sec={{t="Um Barão Derrubado",b="O contrato com o nome do Barão Vardus leva de Costa Sul aos esconderijos da Camarilha em Alterac. Vardus é um nobre do antigo reino, conhecido pelo coração frio e por suas práticas brutais. O Magistrado Maleb quer que ele seja levado à justiça depois que seus capangas foram enviados contra Costa Sul. A cabeça do Barão é a prova que Maleb exige."}},faq={{q="Quem foi o Barão Vardus?",a="O Barão Vardus era um nobre do antigo reino de Alterac, conhecido pelo coração frio e por suas práticas brutais.",al={"quem é vardus","barão vardus","história de vardus"}},{q="Por que Costa Sul quer a cabeça dele?",a="O Magistrado Maleb diz que Vardus enviou seus capangas contra Costa Sul e quer que ele seja levado à justiça.",al={"por que matar vardus","costa sul quer vardus","vardus procurado"}},{q="Onde o Barão Vardus pode ser encontrado?",a="Vardus está entre os esconderijos da Camarilha em Alterac, talvez nas ruínas de Strahnbrad ou no vale ao norte delas.",al={"onde está vardus","localização de vardus","encontrar o barão"}},{q="Quem recebe a cabeça?",a="O Magistrado Maleb, em Costa Sul, recebe a cabeça do Barão Vardus como prova de que a caçada terminou.",al={"quem quer a cabeça","cabeça para maleb","cabeça de vardus"}}},fp="20,163,19.327.0,21.105.0,34.96.0,32.115.0,22.93.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Cabeça de Basílio Taborda",s="A cabeça decepada de Basílio Taborda serve como prova definitiva de que o líder por trás da rebelião no Cárcere foi eliminado. Exigida pelo Carcereiro-chefe Thelágua, essa sombria recompensa marca o fim do controle organizado da Irmandade Défias sobre a prisão subterrânea de Ventobravo.",h="A cabeça decepada de Basílio Taborda serve como prova definitiva de que o líder por trás da rebelião no...",kw={"basílio taborda","défias","cabeça de basílio taborda","o cárcere","the stockade riots","carcereiro-chefe thelágua"},ang={["faction:Alliance"]="Apresentar a cabeça decepada de Taborda aplaca o pânico imediato na capital, provando que a justiça da coroa ainda pode alcançar as profundezas do rebelde Cárcere."},sec={{t="Prova do Fim da Traição",b="Quando as rebeliões eclodiram por todo O Cárcere, sob Ventobravo, Basílio Taborda rapidamente se estabeleceu como o mentor intelectual da insurreição. Entrincheirado em seu bloco de celas entre detentos leais da Irmandade Défias, Taborda comandou o caos das profundezas das muralhas da masmorra. Desconfiado de forasteiros e lutando para manter a ordem, o Carcereiro-chefe Thelágua exigiu a cabeça de Taborda como evidência inequívoca de sua morte e como um teste da verdadeira lealdade de The Adventurer a Ventobravo."}},faq={{q="Quem quer a Cabeça de Basílio Taborda?",a="O Carcereiro-chefe Thelágua, posicionado na entrada do Cárcere, exige a cabeça. Ele a requer como prova absoluta de que o líder foi morto antes de estar disposto a compartilhar qualquer informação sobre os conspiradores de Taborda.",al={"quem precisa da cabeça de taborda","onde entregar a cabeça de taborda","iniciador da missão da cabeça de taborda"}},{q="Quem foi Basílio Taborda?",a="Basílio Taborda era um membro de alto escalão da Irmandade Défias aprisionado sob Ventobravo. Assim que os prisioneiros se rebelaram, ele assumiu o comando do motim, coordenando a insurreição do fundo do bloco de celas oriental.",al={"quem é basílio taborda","história de taborda","o que basílio fez"}},{q="Onde Basílio Taborda é encontrado?",a="Basílio Taborda está localizado na ala leste da masmorra O Cárcere. Ele está trancado no extremo oposto do bloco em uma cela central, protegido por detentos da Irmandade Défias leais a ele.",al={"onde fica taborda","localização de taborda","como encontrar basílio taborda"}}},fx={["4fd859a6"]={q="O que é a Cabeça de Basílio Taborda?",a="É a cabeça decepada de Basílio Taborda, o prisioneiro que orquestra a rebelião nas profundezas do Cárcere. Para o Carcereiro-chefe Thelágua, apresentar este troféu sombrio serve como prova física inegável de que o líder do motim na prisão foi eliminado permanentemente.",al={"o que é a cabeça de basílio taborda","item cabeça de basílio taborda","cabeça de basílio taborda"}},fe91a8a0={q="De onde vem a Cabeça de Basílio Taborda?",a="Ela é tomada diretamente de Basílio Taborda depois que você o confronta e o mata em sua cela dentro do Cárcere de Ventobravo, onde ele dirige a revolta sob a proteção de seus guardas brutos.",al={"onde conseguir a cabeça de basílio taborda","como você consegue a cabeça de basílio taborda","origem da cabeça de basílio taborda"}}},fp="20,202,22.327.0,35.171.0,21.197.0,28.143.0"}
P.entries["item:head-of-deepfury"] = {n="Cabeça de Fundafúria",s="A cabeça decepada de Kam Fundafúria serve como prova sombria de que o conspirador Ferro Negro por trás da sabotagem da Ponte Thandol encontrou seu fim. Morto durante as rebeliões no Cárcere de Ventobravo, sua morte cumpre uma vingança pessoal para os defensores anões de Dun Modr.",h="A cabeça decepada de Kam Fundafúria serve como prova sombria de que o conspirador Ferro Negro por trás da...",kw={"fundafúria","dun modr","cabeça de fundafúria","kam fundafúria","trançalonga","rocio garmason","o cárcere","ponte thandol"},ang={["faction:Alliance"]="A recompensa ilustra o atrito crescente dentro da Aliança, contrastando a cautela jurídica humana em Ventobravo com a dura justiça da fronteira exigida pelos montanhistas de Altaforja.",["race:Dwarf"]="Para os anões de Altaforja, tomar a cabeça de Fundafúria é uma questão de pura justiça de clã, quitando uma dívida de sangue contraída pela traição dos Ferro Negro na Ponte Thandol."},sec={{t="A Justiça de um Conspirador",b="Kam Fundafúria foi preso e trancafiado no Cárcere de Ventobravo por razões políticas, poupado da execução imediata pela burocracia diplomática humana. Para os montanhistas de Altaforja destacados em Dun Modr, essa contenção era inaceitável. Informações descobertas por Roggo revelaram que Fundafúria orquestrou o ataque devastador à Ponte Thandol — uma investida que custou a vida de soldados do Rei Magni e de parentes de Trançalonga, o Austero. Preso ao dever de permanecer em seu posto, Rocio Garmason encarregou campeões da Aliança de se infiltrarem na prisão rebelada e reivindicarem a cabeça de Fundafúria, garantindo que a verdadeira vingança dos anões fosse cumprida onde a diplomacia humana falhou."}},faq={{q="Quem foi Kam Fundafúria?",a="Kam Fundafúria foi um anão Ferro Negro traiçoeiro que ajudou a planejar a sabotagem da Ponte Thandol, a ponte terrestre crucial que conecta os Pantanais ao Planalto Arathi. Sua conspiração resultou na morte de defensores anões, incluindo o irmão de Trançalonga, o Austero.",al={"história de kam fundafúria","quem é fundafúria","passado de kam fundafúria"}},{q="Por que Kam Fundafúria estava no Cárcere em vez de executado?",a="Fundafúria estava sendo mantido vivo pelas autoridades em Ventobravo por motivos políticos. Enquanto a burocracia humana se contentava em deixá-lo apodrecer em uma cela de prisão, os montanhistas de Altaforja viam essa clemência como um ultraje e exigiam sangue.",al={"por que fundafúria foi preso","por que o cárcere"}},{q="Quem quer a Cabeça de Fundafúria?",a="Rocio Garmason, um anão destacado em Dun Modr, no norte dos Pantanais, pede a cabeça. Preso pela honra de permanecer em seu posto ao lado de Trançalonga, o Austero, Rocio envia um aventureiro para concluir o que ele próprio não pode fazer.",al={"quem recebe a cabeça de fundafúria","entrega da fúria profunda"}},{q="O que a entrega da cabeça realiza?",a="Apresentar a cabeça decepada de Fundafúria traz encerramento e justiça para as famílias anãs em luto em Dun Modr. Vinga o irmão assassinado de Trançalonga, o Austero, e demonstra que os crimes contra Altaforja não serão soterrados pelas manobras políticas humanas.",al={"por que trazer a cabeça de fundafúria","resultado da fúria profunda"}}},fx={["42407f6f"]={q="O que é a Cabeça de Fundafúria?",a="É a cabeça decepada de Kam Fundafúria, um anão Ferro Negro encarcerado nas profundezas do Cárcere de Ventobravo. Você a reivindica como prova física irrefutável de que o conspirador por trás do ataque desastroso na The Thandol Span finalmente enfrentou a justiça.",al={"cabeça de fundafúria","o que é a cabeça de fundafúria","cabeça de kam fundafúria"}},ff6e9a29={q="De onde vem a Cabeça de Fundafúria?",a="A cabeça é tirada diretamente do próprio Kam Fundafúria dentro das celas do Cárcere sob a cidade de Ventobravo. Embora ele tenha sido trancado pelas autoridades humanas em vez de executado, você deve derrubá-lo em sua cela para recuperá-la.",al={"onde conseguir a cabeça de fundafúria","quem deixa cair a cabeça de fundafúria","origem da cabeça de fundafúria"}}},fp="16,185,23.478.0,21.230.0,57.148.0,31.183.0,44.228.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Cabeça de Gath'Ilzogg",s="A cabeça decepada de Gath'Ilzogg serve como prova incontestável de que o senhor da guerra Rocha Negra foi morto. Reivindicá-la destrói a liderança por trás do cerco à Bastilha Mirante de Pedra e traz um alívio desesperador à cidade de Vila Plácida.",h="A cabeça decepada de Gath'Ilzogg serve como prova incontestável de que o senhor da guerra Rocha Negra foi...",kw={"rocha negra","gath'ilzogg","vila plácida","magistrado salomão","montanhas cristarrubra","mirante de pedra","bastilha mirante de pedra"},ang={["faction:Alliance"]="Com a capital distraída por disputas internas, os voluntários da Aliança precisam assumir o fardo de defender Cristarrubra e abater os líderes Rocha Negra por conta própria.",["race:Human"]="Para o povo de Ventobravo, derrubar Gath'Ilzogg vinga o massacre de colonos inocentes e a humilhante queda da Bastilha Mirante de Pedra."},sec={{t="Um Senhor da Guerra a Prêmio",b="Gath'Ilzogg orquestrou o ataque brutal dos Rocha Negra que subjugou a Bastilha Mirante de Pedra, expulsando seus defensores e submetendo o vale ao redor a incursões implacáveis. Com Vila Plácida à beira da ruína e Ventobravo não oferecendo praticamente nenhum reforço militar, o Magistrado Salomão colocou uma recompensa pela cabeça do senhor da guerra. Abater Gath'Ilzogg nos níveis superiores fortificados de Mirante de Pedra e reivindicar sua cabeça despedaça a liderança local dos Rocha Negra, marcando o primeiro passo real para retomar a bastilha para o reino."}},faq={{q="Quem foi Gath'Ilzogg?",a="Gath'Ilzogg foi um poderoso senhor da guerra orc Rocha Negra que liderou a conquista da Bastilha Mirante de Pedra e comandou incursões contra os assentamentos das Montanhas Cristarrubra, levando Vila Plácida à beira do colapso.",al={"quem e gath'ilzogg","historia de gathilzogg","chefe de mirante de pedra"}},{q="Para onde a cabeça é levada depois de coletada?",a="A cabeça é levada diretamente ao Magistrado Salomão na prefeitura de Vila Plácida como prova de que a recompensa afixada no quadro de procurados da cidade foi cumprida.",al={"quem quer a cabeca","entregar cabeca de gath'ilzogg","recompensa magistrado salomao"}},{q="O que a morte de Gath'Ilzogg significa para Vila Plácida?",a="Sua morte priva os invasores Rocha Negra de seu principal estrategista em Cristarrubra. Embora muitos orcs Rocha Negra continuem entrincheirados por Mirante de Pedra, romper sua cadeia de comando dá à defesa local uma chance real de manter a região.",al={"vila placida e salva","importancia de matar gath'ilzogg"}},{q="Onde Gath'Ilzogg foi encontrado?",a="Ele ocupava os pontos mais altos da Bastilha Mirante de Pedra, entrincheirado nas profundezas da fortificação capturada ao lado de seus guarda-costas pessoais e tenentes.",al={"onde fica gathilzogg","localizacao da bastilha mirante de pedra"}}},fx={a1bebb0c={q="Por que o Magistrado Salomão quer a Cabeça de Gath'Ilzogg?",a="O Magistrado Salomão ofereceu uma recompensa severa exigindo prova física da morte do senhor da guerra. Gath'Ilzogg foi responsável por massacrar humanos inocentes e invadir a Bastilha Mirante de Pedra. Ver sua cabeça entregue garante à liderança de Vila Plácida que a ameaça imediata foi quebrada, oferecendo vindicação e a esperança de retomar a fortaleza.",al={"por que o salomão quer a cabeça de gath'ilzogg","por que trazer a cabeça de gath ilzogg","recompensa pela cabeça de gath'ilzogg"}},["0b5a65b1"]={q="O que é a Cabeça de Gath'Ilzogg?",a="É a cabeça decepada de Gath'Ilzogg, o senhor da guerra orc Rocha Negra que comandou o ataque à Bastilha Mirante de Pedra e organizou ataques que ameaçavam Vila Plácida. Decepá-la fornece uma prova física incontestável de que o líder brutal que orquestrava a campanha Rocha Negra nas Montanhas Cristarrubra finalmente foi eliminado.",al={"o que é a cabeça de gath'ilzogg","cabeça de gath'ilzogg","cabeça de gath ilzogg"}},ca6d6fe9={q="De onde vem a Cabeça de Gath'Ilzogg?",a="A cabeça é retirada diretamente de Gath'Ilzogg depois que ele é morto nas alturas da Bastilha Mirante de Pedra. Enfurnado na fortaleza que conquistou, o senhor da guerra planejava novas agressões contra o povo das Montanhas Cristarrubra, até que um aventureiro enfrentou seu reduto e tomou a cabeça como troféu.",al={"de onde veio a cabeça de gath'ilzogg","quem pegou a cabeça de gath'ilzogg","origem da cabeça de gath ilzogg"}}},fp="19,133,18.453.0,20.185.0,39.133.0,49.230.0,28.152.0"}
P.entries["item:head-of-grimson"] = {n="Cabeça de Severo",s="A Cabeça de Severo é o troféu decepado tirado de Grimson the Pale, o feitor corrompido da Mina Elenfunda na Floresta de Pinhaprata. Levada a Dalar Tessalba no Sepulcro, ela serve como prova física de que a liderança da mina foi eliminada. Proteger a mina permite que os Renegados tomem posse de valiosas riquezas minerais para abastecer as campanhas militares de Varimatras.",h="A Cabeça de Severo é o troféu decepado tirado de Grimson the Pale, o feitor corrompido da Mina Elenfunda na...",kw={"arugal","dalar tessalba","mina elenfunda","grimson the pale","cabeça de severo","o sepulcro","floresta de pinhaprata","varimatras"},ang={["profession:Mining"]="A Mina Elenfunda representa uma das principais reservas minerais de Pinhaprata, agora limpa de seu feitor enlouquecido para que o minério bruto possa abastecer as linhas de suprimento da Horda.",["race:Undead"]="Reivindicar a mina atende às determinações estratégicas do alto comando da Cidade Baixa, provando a determinação dos Renegados em retomar a infraestrutura vital de Lordaeron dos remanescentes enlouquecidos."},sec={{t="Protegendo a Mina Elenfunda",b="Enquanto Dalar Tessalba estuda os encantamentos sombrios do Arquimago Arugal a partir da segurança do Sepulcro, batedores Renegados conhecidos como Darkstalkers identificaram uma ameaça estratégica crescendo nas colinas a sudeste. A magia sombria de Arugal infiltrou-se na Mina Elenfunda, corrompendo seus trabalhadores e levando seu feitor, Grimson the Pale, à loucura. Para proteger as riquezas subterrâneas para as forças de Varimatras, Tessalba despachou campeões para abater Grimson e retornar com sua cabeça decepada como confirmação inegável da libertação da mina de magias rebeldes."},{t="Um troféu para o Senhor do Terror",b="Para os Renegados, troféus macabros de guerra carregam um peso pragmático. Reivindicar a cabeça de Severo garante que a força de trabalho subterrânea na Mina Elenfunda seja inteiramente subjugada, encerrando qualquer lealdade remanescente ao reinado distorcido de Arugal. Com Grimson eliminado, os ricos veios minerais no interior da mina podem ser extraídos e reforjados em armas e armaduras, sustentando o avanço contínuo dos Renegados pela Floresta de Pinhaprata e pelos territórios vizinhos de Lordaeron."}},faq={{q="Quem foi Grimson the Pale?",a="Grimson the Pale era o feitor da Mina Elenfunda, localizada nas colinas a sudeste da Floresta de Pinhaprata. Exposto à Magia Sombria que se espalhava do Arquimago Arugal, Grimson e seus companheiros mineradores caíram sob sua influência nefasta, transformando a mina em uma fortaleza corrompida até que os Renegados intervieram.",al={"quem e grimson","historia de grimson the pale","origem de grimson"}},{q="Por que Dalar Tessalba quer a cabeça de Grimson?",a="Dalar Tessalba precisa de uma prova concreta de que o capataz corrompido foi permanentemente eliminado. Varimatras deseja a riqueza mineral da Mina Elenfunda para o esforço de guerra dos Renegados, e matar Grimson quebra a resistência dos mineradores corrompidos que dominam os túneis.",al={"por que dalar quer a cabeca","utilidade da cabeca de severo","por que pegar a cabeca"}},{q="Onde fica localizada a Mina Elenfunda?",a="A Mina Elenfunda está situada nas colinas a sudeste do Sepulcro, na Floresta de Pinhaprata. Ela serve como um depósito mineral vital disputado pelos Renegados e pelos remanescentes corrompidos subjugados pela magia de Arugal.",al={"onde fica a mina elenfunda","localizacao de grimson","localizacao da mina em pinhaprata"}},{q="Qual é o papel de Varimatras nesta tarefa?",a="Varimatras atua como o supervisor militar que comanda a expansão dos Renegados por Lordaeron a partir da Cidade Baixa. Proteger os recursos da Mina Elenfunda atende diretamente aos seus objetivos estratégicos, fornecendo matérias-primas para abastecer sua crescente máquina de guerra em Pinhaprata.",al={"papel de varimatras","por que varimatras quer a mina","varimatras floresta de pinhaprata"}}},fx={f0354d96={q="O que é a Cabeça de Severo?",a="A Cabeça de Severo é a cabeça decepada de Severo, o Pálido, tomada como prova de sua morte. Outrora um supervisor comum, Severo foi distorcido pela mancha mágica sombria liberada por toda Pinhaprata pelo Arquimago Arugal. Reivindicar sua cabeça marca o fim de seu comando sobre a Mina Elenfunda, garantindo evidências inegáveis de que a liderança corrompida da mina caiu.",al={"cabeça de severo","o que é a cabeça de severo"}},["923cacb6"]={q="De onde vem a Cabeça de Severo?",a="Este troféu sombrio vem diretamente da Mina Elenfunda, localizada nas colinas a sudeste do Sepulcro. Ela é decepada dos ombros de Severo, o Pálido, o capataz contaminado da mina. Severo sucumbiu às magias selvagens que vazavam de Pinhaprata e da Bastilha da Presa Negra, mantendo a mina até ser derrubado por ordens de Dalar Tessalba.",al={"onde conseguir a cabeça de severo","quem deixa cair a cabeça de severo","origem da cabeça de severo"}}},fp="15,198,27.409.0,26.275.1,25.184.0,46.226.0,36.158.0,45.173.0"}
P.entries["item:head-of-kelris"] = {n="Cabeça de Kelris",s="A cabeça decepada do Senhor do Crepúsculo Kelris serve como prova inegável de que o líder do Martelo do Crepúsculo nas Profundezas Negras caiu. Trazida para fora das ruínas do templo corrompido, ela é procurada por representantes da Aurora Argêntea para confirmar o fim de seus sacrifícios rituais profanos.",h="A cabeça decepada do Senhor do Crepúsculo Kelris serve como prova inegável de que o líder do Martelo do...",kw={"aku'mai","aurora argêntea","bashana runa totem","profundezas negras","blackfathom villainy","cabeça de kelris","selgorm","senhor do crepúsculo kelris"},ang={["faction:Alliance"]="Entregar a cabeça de Kelris ao Vigilalva Selgorm em Darnassus vinga a profanação de um antigo templo de elfo noturno dedicado a Elune.",["faction:Horde"]="Apresentar a cabeça a Bashana Runa Totem no Penhasco do Trovão conquista a confiança do Círculo Cenariano, provando sua dedicação em purificar a corrupção de Kalimdor."},sec={{t="Um Troféu de Ruína",b="Nas profundezas submersas do Templo de Elune submerso, o Senhor do Crepúsculo Kelris orquestrou sacrifícios sombrios para Aku'mai, um monstruoso servo de um Deus Antigo. Reivindicar sua cabeça marca o fim de sua liderança tirânica sobre os cultistas do Martelo do Crepúsculo e seus aliados naga na caverna. O troféu macabro deve ser levado de volta às civilizações da superfície para garantir aos líderes que as cerimônias sangrentas de Kelris finalmente cessaram."},{t="Prova para a Aurora",b="Por meses, Kelris foi presumido morto ou perdido pela Aurora Argêntea, apenas para sua influência sinistra ressurgir junto com as sombras invasoras de Kalimdor. Quando apresentada aos agentes em Darnassus ou no Penhasco do Trovão, a cabeça encerra recompensas pendentes e confirma que suas tentativas de mergulhar o mundo de volta no caos primordial foram frustradas."}},faq={{q="Quem foi o Senhor do Crepúsculo Kelris?",a="Kelris era o líder da seita do Martelo do Crepúsculo entrincheirada nas Profundezas Negras. Aliado aos naga, ele orquestrou sacrifícios rituais de inocentes para alimentar Aku'mai, uma hidra serva de um Deus Antigo, em busca de poder sombrio e caos ancestral.",al={"quem é kelris","história de kelris","senhor do crepúsculo kelris"}},{q="Quem quer a Cabeça de Kelris?",a="Campeões da Aliança entregam a cabeça ao Vigilalva Selgorm em Darnassus, enquanto aventureiros da Horda a trazem para Bashana Runa Totem no Platô dos Anciãos no Penhasco do Trovão. O Vigilalva Selgorm serve à Aurora Argêntea, enquanto Bashana Runa Totem pertence ao Círculo Cenariano.",al={"quem recebe a cabeça de kelris","entregar cabeça de kelris","para quem entrego a cabeça de kelris"}},{q="Por que a Aurora Argêntea se importa com Kelris?",a="A Aurora Argêntea rastreia ameaças malévolas que põem Azeroth em perigo. Kelris era um vilão conhecido que havia muito tempo os eludia, e sua adoração aos Deuses Antigos e o sacrifício de inocentes representavam uma terrível ameaça ao equilíbrio de Kalimdor.",al={"por que a aurora argêntea quer kelris","aurora argêntea profundezas negras"}},{q="Onde a cabeça é obtida?",a="Ela é decepada do cadáver do Senhor do Crepúsculo Kelris dentro de seu santuário na masmorra das Profundezas Negras, localizada sob a Praia de Zoram, ao longo da costa de Vale Gris.",al={"onde conseguir a cabeça de kelris","localização da cabeça de kelris"}}},fx={["0e645b89"]={q="De onde vem a Cabeça de Kelris?",a="A cabeça é tirada diretamente do Senhor do Crepúsculo Kelris nas profundezas de Profundezas Negras, ao longo de The Zoram Strand. Você deve lutar contra os cultistas fanáticos e os servos aberrantes dele para matar o senhor do crepúsculo em seu santuário interno antes de reivindicá-la.",al={"onde conseguir cabeça de kelris","origem da cabeça de kelris","como obter cabeça de kelris"}},c257c517={q="O que é a Cabeça de Kelris?",a="É a cabeça decepada do Senhor do Crepúsculo Kelris, o líder dos cultistas do Martelo do Crepúsculo que se enraizaram profundamente nas ruínas das Profundezas Negras. Ela serve como prova macabra e inegável de que o mestre sinistro do culto no templo submerso foi morto e seus rituais levados ao fim.",al={"cabeça de kelris","o que é a cabeça de kelris","item cabeça de kelris"}}},fp="14,116,16.305.0,18.291.0,29.202.0,29.236.0,43.156.0,27.139.0"}
P.entries["item:head-of-lathoric-the-black"] = {n="Head of Lathoric the Black",s="Head of Lathoric the Black é uma prova levada da Garganta Abrasadora a Thorius, em Altaforja. Está ligado ao perigo em torno de Obsidion.",h="Head of Lathoric the Black é uma prova levada da Garganta Abrasadora a Thorius, em Altaforja.",kw={"head of lathoric the black","heart of obsidion","altaforja","lathoric","obsidion","garganta abrasadora","thorius"},ang={["race:Dwarf"]="Como anão, você leva a Thorius, em Altaforja, uma prova do perigo na Garganta Abrasadora."},sec={{t="A Grim Token",b="Thorius, em Altaforja, pede que você leve até ele o Head of Lathoric the Black da Garganta Abrasadora. A cabeça prova a morte de Lathoric e é levada junto com o Heart of Obsidion."}},faq={{q="De quem é a cabeça?",a="A cabeça é de Lathoric the Black, encontrado na Garganta Abrasadora.",al={"cabeça de lathoric"}},{q="Por que Thorius quer a cabeça?",a="Thorius pede que você leve a cabeça a Altaforja como prova ligada ao perigo em torno de Obsidion.",al={"por que levar a cabeça a thorius","prova para thorius"}},{q="Onde devo levar a cabeça?",a="Leve o Head of Lathoric the Black a Thorius, em Altaforja.",al={"entregar a cabeça","onde levar a cabeça de lathoric"}},{q="O que acompanha a cabeça?",a="O Heart of Obsidion é levado com a cabeça até Thorius.",al={"coração junto com a cabeça","itens de obsidion"}}},fp="26,138,12.183.0,21.67.0,25.97.0,25.61.0,24.58.0"}
P.entries["item:head-of-nagaz"] = {n="Head of Nagaz",s="A cabeça de Nagaz prova que a busca do Magistrate Maleb nas Montanhas de Alterac chegou ao Argus Wake. Maleb teme que o grupo ameace a Camarilha.",h="A cabeça de Nagaz prova que a busca do Magistrate Maleb nas Montanhas de Alterac chegou ao Argus Wake.",kw={"montanhas de alterac","argus shadow mages","argus wake","dark council","cabeça de nagaz","nagaz","costa sul","strahnbrad","camarilha","as terras altas"},ang={["faction:Alliance"]="Como viajante da Aliança, você leva a preocupação do Magistrate Maleb da Costa Sul às Terras Altas, onde a Camarilha é mais forte."},sec={{t="Prova para Maleb",b="Nas Terras Altas, ao norte de Strahnbrad, Nagaz lidera os Argus Shadow Mages citados em uma carta entregue ao Magistrate Maleb. Maleb suspeita que o Argus Wake tenha se aliado à Camarilha. A cabeça de Nagaz prova para a Costa Sul que os emissários foram encontrados."}},faq={{q="Quem era Nagaz?",a="Nagaz era membro do Argus Wake e liderava Argus Shadow Mages nas Terras Altas.",al={"quem é nagaz","nagaz sujeito"}},{q="Onde posso encontrar Nagaz?",a="Nagaz fica nas Terras Altas das Montanhas de Alterac, ao norte de Strahnbrad.",al={"localização de nagaz","onde fica nagaz"}},{q="Por que o Magistrate Maleb quer a cabeça de Nagaz?",a="O Magistrate Maleb quer provas de que Nagaz e os Argus Shadow Mages estão nas Terras Altas, onde teme que o Argus Wake ameace a Camarilha.",al={"por que a cabeça de nagaz","maleb quer a cabeça"}},{q="O que é o Argus Wake?",a="O Argus Wake é um grupo cujo membro Nagaz escreveu à Camarilha. Maleb teme que sua aliança com a Camarilha represente uma ameaça.",al={"significado de argus wake","quem são argus wake"}},{q="O que os Argus Shadow Mages estão fazendo?",a="Os Argus Shadow Mages são emissários do Argus Wake, encontrados ao lado de Nagaz nas Terras Altas.",al={"magos de argus","magos das sombras"}}},fp="13,155,15.256.0,14.79.0,23.70.0,46.144.0,23.131.0,38.89.0"}
P.entries["item:head-of-overseer-maltorius"] = {n="Head of Overseer Maltorius",s="A cabeça de Head of Overseer Maltorius comprova uma recompensa na Garganta Abrasadora. Capitão-vigia Lolo Longalcance pede que você a traga de volta de O Caldeirão.",h="A cabeça de Head of Overseer Maltorius comprova uma recompensa na Garganta Abrasadora.",kw={"caldeirão","head of overseer maltorius","lolo longalcance","maltorius","overseer maltorius","garganta abrasadora","fosso de lava","irmandade do tório"},ang={["race:Dwarf"]="Como anão, você enfrenta um comandante Ferro Negro no Fosso de Lava, onde sua equipe trabalha em O Caldeirão."},sec={{t="Uma recompensa na Garganta Abrasadora",b="Capitão-vigia Lolo Longalcance oferece uma recompensa por Maltorius, um anão Ferro Negro que comanda a equipe do Fosso de Lava em O Caldeirão. O anúncio o identifica como agente renegado da Irmandade do Tório. A cabeça decepada dele é a prova que Longalcance pede que você traga das profundezas do Fosso de Lava."}},faq={{q="Quem foi Overseer Maltorius?",a="Overseer Maltorius era um anão Ferro Negro e comandante da equipe do Fosso de Lava em O Caldeirão. A recompensa o identifica como agente renegado da Irmandade do Tório.",al={"quem é maltorius"}},{q="Onde posso encontrar Maltorius?",a="Maltorius está nas profundezas do Fosso de Lava, em O Caldeirão, na Garganta Abrasadora.",al={"localização de maltorius","onde fica maltorius"}},{q="Por que Maltorius é procurado?",a="O anúncio da recompensa identifica Maltorius como agente renegado da Irmandade do Tório e ordena sua morte.",al={"por que maltorius é procurado","recompensa por maltorius"}},{q="Quem quer a cabeça de Maltorius?",a="Capitão-vigia Lolo Longalcance oferece a recompensa e pede que você traga a cabeça de Maltorius como prova.",al={"quem ofereceu a recompensa","lolo maltorius"}},{q="O que é Head of Overseer Maltorius?",a="É a cabeça decepada de Maltorius, tomada como prova da recompensa na Garganta Abrasadora.",al={"cabeça de maltorius","item de cabeça"}}},fp="26,151,21.281.0,27.148.0,27.76.0,24.88.0,27.104.0,39.82.0"}
P.entries["item:head-of-targorr"] = {n="Cabeça de Targorr",s="A Cabeça de Targorr é a prova sombria exigida pelo Guarda Berto na Vila Plácida para confirmar a morte de Targorr, o Horror. Outrora o carrasco supremo do senhor da guerra Blackrock Gath'Ilzogg nas Montanhas Cristarrubra, o orc capturado foi sentenciado à morte no Stormwind Stockade antes que uma suspeita interferência política suspendesse sua execução.",h="A Cabeça de Targorr é a prova sombria exigida pelo Guarda Berto na Vila Plácida para confirmar a morte de...",kw={"blackrock","gath'ilzogg","guarda berto","cabeça de targorr","vila plácida","montanhas cristarrubra","o cárcere","targorr","targorr, o horror"},ang={["faction:Alliance"]="Para os campeões da Aliança que defendem as Montanhas Cristarrubra, derrotar Targorr vinga os defensores massacrados da Vila Plácida e contorna a burocracia nobre corrupta de Ventobravo.",["race:Human"]="Soldados humanos e guardas da cidade guardam rancor pessoal contra Targorr pela tortura sádica de tropas capturadas do Reino durante a ofensiva de Blackrock."},sec={{t="Uma Execução Adiada",b="Targorr, o Horror ganhou infâmia por toda Cristarrubra como o carrasco brutal a serviço do senhor da guerra do clã Blackrock, Gath'Ilzogg. Responsável por torturar e massacrar defensores do Reino de Ventobravo, Targorr acabou sendo capturado e condenado à morte dentro do Stormwind Stockade. No entanto, a intervenção burocrática de nobres de Ventobravo suspendeu misteriosamente a sentença, levando guardas locais como Berto a suspeitarem de armação e corrupção na capital."},{t="Justiça de Fronteira",b="Temendo que Targorr pudesse ser usado como peão político ou de alguma forma orquestrar uma fuga, o Guarda Berto encarregou um campeão externo de invadir a prisão volátil e concluir o que os tribunais adiaram. Decepar a cabeça de Targorr ignorou totalmente o sistema judiciário paralisado, trazendo encerramento às famílias enlutadas e aos defensores sitiados da Vila Plácida que sofreram sob as lâminas do carrasco."}},faq={{q="Quem foi Targorr, o Horror?",a="Targorr era um infame carrasco orc pertencente ao clã Blackrock nas Montanhas Cristarrubra. Servindo sob o senhor da guerra Gath'Ilzogg, ele se tornou notório por torturar e executar soldados e defensores capturados de Ventobravo.",al={"targorr","história de targorr","quem é targorr"}},{q="Por que Targorr foi mantido vivo no Cárcere?",a="Embora formalmente sentenciado à morte, a execução de Targorr foi misteriosamente interrompida por nobres burocratas de Ventobravo. Os guardas na Vila Plácida suspeitam de trapaça política e corrupção, temendo que o orc estivesse sendo mantido como moeda de troca.",al={"por que não executar targorr","suspensão da execução de targorr","julgamento do cárcere"}},{q="Quem quer a cabeça de Targorr?",a="O Guarda Berto, posicionado do lado de fora da Estalagem da Vila Plácida, solicita a cabeça decepada. Tendo visto a carnificina que Targorr causou nas Montanhas Cristarrubra, Berto busca uma prova definitiva de que o carrasco jamais poderá ser libertado.",al={"quem fica com a cabeça de targorr","guarda berto","entregar cabeça de targorr"}},{q="Onde Targorr é encontrado?",a="Targorr, o Horror está aprisionado dentro do Stormwind Stockade, mantido atrás de grades de ferro nos blocos centrais de celas ao lado de detentos amotinados.",al={"localização de targorr","encontrar targorr","onde no cárcere"}}},fx={["1b8c229f"]={q="O que é a Cabeça de Targorr?",a="É a cabeça decepada de Targorr, o Horror, o notório Carrasco supremo que servia sob as ordens do senhor da guerra Rocha Negra, Gath'Ilzogg. Targorr foi capturado e mantido em Stormwind Stockade sob sentença de morte por torturar e executar bravos defensores do reino.",al={"o que é cabeça de targorr","informações sobre cabeça de targorr","descrição da cabeça de targorr"}},["29061798"]={q="De onde vem a Cabeça de Targorr?",a="A cabeça vem do próprio Targorr, o Horror, trancado profundamente dentro de Stormwind Stockade. Depois que um nobre de Ventobravo interrompeu sua execução programada, o Guarda Berto encarrega um aventureiro de resolver o assunto, entrando nas celas da prisão para decepar a cabeça do orc impiedoso.",al={"de onde vem a cabeça de targorr","quem deixa cair a cabeça de targorr","origem da cabeça de targorr"}}},fp="15,187,19.344.0,16.356.0,26.183.0,43.205.0,25.202.0,23.118.0"}
P.entries["item:head-of-vancleef"] = {n="Cabeça do VanCleef",s="A cabeça decepada de Edwin VanCleef serve como uma prova sombria e irrefutável de que o líder da Irmandade Défias caiu. Trazida das profundezas das Minas Mortas de volta ao Morro da Sentinela, ela representa a vingança duramente conquistada pela Milícia do Povo.",h="A cabeça decepada de Edwin VanCleef serve como uma prova sombria e irrefutável de que o líder da Irmandade...",kw={"minas mortas","edwin vancleef","miguel mantoforte","cabeça do vancleef","milicia do povo","morro da sentinela","cerro oeste"},ang={["class:Rogue"]="Edwin VanCleef foi um dos mestres ladinos mais letais da história humana; tomar sua cabeça sela o término definitivo de uma carreira incomparável nas sombras e na sabotagem.",["faction:Alliance"]="Apresentar a cabeça de VanCleef proporciona uma vitória catártica para a Milícia do Povo, embora ressalte a ausência perturbadora da Casa dos Nobres de Ventobravo durante o momento mais sombrio de Cerro Oeste."},sec={{t="Prova da Queda do Mestre",b="Por meses, Edwin VanCleef orquestrou o terror da Irmandade Défias a partir do santuário mais profundo das Minas Mortas, protegido por bandidos fortemente armados, engenheiros goblins e um enorme encouraçado de guerra. Meras palavras jamais convenceriam os castigados colonos de Cerro Oeste de que o pesadelo havia chegado ao fim. Miguel Mantoforte, líder da Milícia do Povo, exigiu uma prova física inegável antes de declarar a região em segurança. Decepar a cabeça do líder e trazê-la à luz do dia oferece aos exaustos defensores a garantia tangível de que o grande arquiteto de sua ruína nunca mais ameaçará Cerro Oeste."},{t="Uma Vitória Sombria",b="Embora Mantoforte tenha buscado a morte de VanCleef pelo bem maior de Cerro Oeste, a apresentação do troféu carrega uma solene gravidade. VanCleef outrora fora o reverenciado mestre artífice que reconstruiu Ventobravo após a Primeira Guerra, antes que a traição e as dívidas não pagas o levassem, juntamente com a Stonemasons Guild, a uma rebelião foras da lei. Sua cabeça decepada marca o ápice da campanha da milícia local de Cerro Oeste, mas também expõe o fracasso do reino em lidar com suas próprias turbulências internas, deixando a fazendeiros voluntários e aventureiros forasteiros a execução da alta justiça."}},faq={{q="Quem quer a Cabeça do VanCleef?",a="Miguel Mantoforte, capitão da Milícia do Povo no Morro da Sentinela em Cerro Oeste, exige a cabeça para concluir a longa campanha contra a Irmandade Défias.",al={"para quem entrego isso","quem fica com a cabeca de vancleef","onde levar a cabeca de vancleef"}},{q="Por que Miguel Mantoforte exige especificamente a cabeça dele?",a="A Irmandade Défias manteve Cerro Oeste sob seu jugo por tanto tempo que rumores sobre a morte de VanCleef jamais seriam aceitos sem uma prova física absoluta. Mantoforte precisa de evidências incontestáveis para tranquilizar os fazendeiros acossados e demonstrar que a luta da milícia não foi em vão.",al={"por que pegar a cabeca dele","por que a cabeca de vancleef"}},{q="Onde a cabeça é obtida?",a="Ela é tirada de Edwin VanCleef a bordo de seu navio de guerra encouraçado secreto, localizado bem ao final das Minas Mortas, sob Arroio da Lua, no sudoeste de Cerro Oeste.",al={"onde conseguir a cabeca de vancleef","como pegar a cabeca do vancleef"}},{q="Pegar a cabeça de VanCleef põe fim à Irmandade Défias?",a="Mantoforte enxerga a morte dele como o princípio do fim da irmandade, mas facções dissidentes, bandidos desgarrados e simpatizantes ainda persistem por Cerro Oeste, Floresta de Elwynn e além.",al={"os defias foram destruidos","o que acontece com os defias"}}},fx={["4a1d52aa"]={q="O que é a Cabeça do VanCleef?",a="A Cabeça do VanCleef é a cabeça decepada de Edwin VanCleef, a mente por trás de The Defias Brotherhood escondida profundamente dentro de Minas Mortas. Ela serve como prova macabra e indiscutível de que o líder da revolta fora da lei finalmente foi derrotado.",al={"o que é cabeça do vancleef","item cabeça do vancleef","cabeça de edwin vancleef"}}},fp="16,176,26.514.0,14.475.1,31.167.0,56.249.0,27.149.0,55.192.0"}
P.entries["item:heart-of-flame-quest-item"] = {n="Heart of Flame",s="Um Heart of Flame é um dos materiais de que Velarok Windblade precisa na Garganta Abrasadora. Ele o ajudará a preparar uma tocha para atacar as quatro torres de sentinela.",h="Um Heart of Flame é um dos materiais de que Velarok Windblade precisa na Garganta Abrasadora.",kw={"golem oil","heart of flame","hearts of flame","garganta abrasadora","torres de sentinela","the flawless flame","tocha de chama impecável","velarok windblade"},sec={{t="Para a tocha",b="Velarok Windblade precisa de quatro Hearts of Flame e quatro globes of Golem Oil na Garganta Abrasadora. Com esses materiais, ele pode criar uma tocha de chama impecável. Ele pretende incendiar as quatro torres de sentinela e atacar antes que seus defensores reajam."}},faq={{q="Para que serve um Heart of Flame?",a="Velarok Windblade precisa de quatro Hearts of Flame para criar uma tocha de chama impecável. Ele planeja usá-la para incendiar as quatro torres de sentinela.",al={"uso de heart of flame","por que heart of flame","coração de chama"}},{q="Quem quer o Heart of Flame?",a="Velarok Windblade quer quatro Hearts of Flame e quatro globes of Golem Oil para a tocha que planeja criar.",al={"quem precisa dele","heart of flame de velarok","quem quer heart of flame"}},{q="Onde encontro Hearts of Flame?",a="Velarok indica golems e elementais da Garganta Abrasadora como criaturas que podem fornecer Hearts of Flame.",al={"localização de heart of flame","onde conseguir heart of flame","hearts of flame na garganta abrasadora"}},{q="De quantos Hearts of Flame Velarok precisa?",a="Velarok precisa de quatro Hearts of Flame para fazer a tocha de chama impecável.",al={"quantidade de hearts of flame","quantos hearts of flame","precisa de quatro hearts"}},{q="Para que serve a tocha de chama impecável?",a="Velarok planeja usar a tocha para incendiar quatro torres de sentinela e abrir caminho para uma ofensiva.",al={"tocha de chama impecável","finalidade da tocha","por que quatro torres"}}},fp="14,156,13.244.0,29.137.0,29.115.0,32.103.0,43.71.0,40.102.0"}
P.entries["item:heart-of-isha-awak"] = {n="Coração de Isha Awak",s="O Coração de Isha Awak é retirado do poderoso debulhador conhecido como Isha Awak, o Deep Doom da Costa dos Mercadores. Procurado pela vidente tauren Mahren Skyseer, ele serve como prova de superação de um dos predadores mais formidáveis do oceano.",h="O Coração de Isha Awak é retirado do poderoso debulhador conhecido como Isha Awak, o Deep Doom da Costa dos...",kw={"deep doom","coração de isha awak","isha awak","mahren skyseer","costa dos mercadores","vila catraca","sertões"},ang={["class:Hunter"]="Rastrear e subjugar o Deep Doom sob as ondas da Costa dos Mercadores é o teste definitivo da coragem de um caçador contra presas aquáticas.",["race:Tauren"]="Para os caçadores taurens, perseguir Isha Awak é um ato de comunhão espiritual com os predadores mais ferozes da natureza, seguindo as orientações da anciã Mahren Skyseer."},sec={{t="Troféu do Deep Doom",b="Ao largo das margens ensolaradas da Costa dos Mercadores, ao sul de Vila Catraca, habita Isha Awak, uma enorme fera marinha reverenciada e temida tanto por marinheiros quanto por habitantes da costa. Conhecida como o Deep Doom, a criatura tirou a vida de inúmeros invasores humanos ao longo da costa. Para a mística Mahren Skyseer, no entanto, a fera representa um predador honrado, e não uma ameaça insensata. Ela acredita que o espírito feroz de Isha Awak reside diretamente dentro de seu coração, incumbindo bravos caçadores de mergulhar nas ondas, vencer a fera em seu domínio e reivindicar o órgão pulsante tanto como troféu quanto como oferenda espiritual."}},faq={{q="O que é o Coração de Isha Awak?",a="É o coração de Isha Awak, um debulhador aquático gigante que ronda as águas costeiras ao sul de Vila Catraca. Ele é reivindicado como prova da matança da fera para a mística tauren Mahren Skyseer.",al={"coração de isha awak","o que é este coração"}},{q="Quem quer o Coração de Isha Awak?",a="Mahren Skyseer, uma vidente tauren acampada ao longo da Costa dos Mercadores ao sul de Vila Catraca, pede aos caçadores que recuperem o coração para honrar o poder da fera e absorver seu espírito.",al={"quem aceita o coração","para quem entrego o coração","mahren skyseer"}},{q="Onde Isha Awak é encontrado?",a="Isha Awak habita as águas oceânicas ao largo da Costa dos Mercadores no leste de Barrens, nadando ao sul do porto goblin de Vila Catraca.",al={"localização de isha awak","onde fica isha awak","onde encontrar isha awak"}},{q="Por que Mahren Skyseer quer o coração?",a="Mahren considera Isha Awak um caçador honrado e um adversário valoroso. Ao matar a fera e segurar seu coração, o caçador acolhe o espírito da criatura marinha para si.",al={"por que matar isha awak","por que mahren quer o coração"}}},fx={["1c3e01c4"]={q="De onde vem o Coração de Isha Awak?",a="O coração não é um artefato criado, mas um órgão obtido diretamente de Isha Awak, a poderosa fera marinha conhecida como a Perdição Profunda. A criatura assombra as águas da costa dos Sertões, ao sul de Vila Catraca, temida pelos humanos locais cujos parentes ela consumiu. Matar este predador primitivo do mar e arrancar seu coração é a única maneira de obtê-lo.",al={"origem do coração de isha awak","de onde veio o coração de isha awak","quem fez o coração de isha awak"}}},fp="18,147,23.489.0,31.174.0,33.189.0,25.94.0,39.171.0"}
P.entries["item:heart-of-obsidion"] = {n="Heart of Obsidion",s="Heart of Obsidion é a prova que Thorius precisa da Garganta Abrasadora. Ele confirma o perigo que ainda ameaça estas terras.",h="Heart of Obsidion é a prova que Thorius precisa da Garganta Abrasadora.",kw={"heart of obsidion","altaforja","lathoric the black","obsidion","old gods","ragnaros","garganta abrasadora","thorius"},ang={["race:Dwarf"]="Como anão, Thorius sente de perto a traição contra Altaforja: ele teme que a influência dos Old Gods ameace seu povo."},sec={{t="O coração devolvido",b="Thorius, em Altaforja, pede Heart of Obsidion após um aviso de Dorius. O coração, tomado de Obsidion na Garganta Abrasadora, é trazido de volta junto com Head of Lathoric the Black. Thorius precisa ver os dois antes de acreditar no que aconteceu."},{t="A dor de Thorius",b="Quando Thorius vê Heart of Obsidion e a cabeça de Lathoric, seu rosto fica pálido. Ele descobre que o próprio irmão armou a cilada e traiu Altaforja. Thorius teme que a influência dos Old Gods continue forte nestas terras e que Ragnaros possa corromper até os nobres e honrados."}},faq={{q="O que é Heart of Obsidion?",a="Heart of Obsidion é um troféu tomado de Obsidion na Garganta Abrasadora.",al={"heart of obsidion","coração de obsidion"}},{q="Quem precisa de Heart of Obsidion?",a="Thorius, em Altaforja, pede Heart of Obsidion junto com Head of Lathoric the Black.",al={"quem quer o coração de obsidion","coração de thorius"}},{q="Por que Thorius quer o coração?",a="Thorius precisa de Heart of Obsidion e de Head of Lathoric the Black como prova da traição.",al={"por que o coração","de que prova thorius precisa"}},{q="O que o coração prova?",a="Junto com a cabeça de Lathoric, o coração mostra a Thorius que o aviso sobre uma cilada era verdadeiro.",al={"prova do coração","o que aconteceu com thorius"}}},fp="17,117,16.245.0,15.273.1,30.71.0,32.93.0,32.96.1,26.94.1"}
P.entries["item:heartswood"] = {n="Palocórdio",s="Heartswood é a madeira extraída de uma árvore sagrada enraizada nas Ruínas de Ordil'Aran, no noroeste de Vale Gris. Nascida no local de descanso final de dois amantes ancestrais, sua ressonância com uma devoção imortal a torna uma isca essencial para evocar uma súcubo.",h="Heartswood é a madeira extraída de uma árvore sagrada enraizada nas Ruínas de Ordil'Aran, no noroeste de Vale...",kw={"anathera","vale gris","gakin, o neromante","heartswood","latherion","ordil'aran","súcubo"},ang={["class:Warlock"]="Para os bruxos da Aliança, conseguir Heartswood é um rito de passagem crucial orientado por Gakin, o Neromante, fornecendo a isca emocional necessária para compelir e vincular um lacaio súcubo.",["race:NightElf"]="A árvore representa um memorial trágico e sagrado da Guerra dos Antigos, tornando sua profanação por bruxos e cultistas uma ofensa amarga contra a memória dos ancestrais caídos."},sec={{t="Um Monumento à Devoção",b="A Heartswood cresce entre as pedras élficas das Ruínas de Ordil'Aran, no noroeste de Vale Gris. De acordo com a lenda, dois amantes chamados Anathera e Latherion tombaram lado a lado durante a catastrófica Guerra dos Antigos, milhares de anos atrás. Na mesma terra onde deram seu último suspiro, uma árvore peculiar criou raízes, florescendo como um testemunho eterno de sua devoção. Mesmo milênios depois, a madeira cortada dessa árvore vibra com a lembrança de uma paixão imortal, tornando-se um objeto de grande curiosidade para aqueles que estudam laços emocionais e espirituais."},{t="Uma Ferramenta de Subjugação",b="Embora nascida de um sentimento puro, a Heartswood atrai atenções mais sombrias. Súcubos — demônios que prosperam na paixão, no anseio e na exploração emocional — são intensamente atraídas por artefatos imbuídos de amor genuíno e imortal. Bruxos humanos e gnomos sob a instrução de Gakin, o Neromante em Ventobravo buscam essa madeira rara especificamente para construir uma isca ritual. Ao usar a ressonância inata do sacrifício dos amantes, um praticante pode atrair uma súcubo através do Espaço Caótico, arrastá-la para um círculo de evocação e prendê-la à sua vontade."}},faq={{q="O que é Heartswood?",a="Heartswood é a madeira retirada de uma árvore que brotou nas Ruínas de Ordil'Aran, em Vale Gris, marcando o local onde dois antigos amantes elfos noturnos pereceram juntos durante a Guerra dos Antigos.",al={"árvore heartswood","o que é heartswood","história de heartswood"}},{q="Quem foram Anathera e Latherion?",a="Anathera e Latherion foram amantes que lutaram lado a lado durante a Guerra dos Antigos. Quando ambos caíram em batalha, seu abraço final nutriu a terra, dando origem à árvore Heartswood como um símbolo duradouro de sua devoção.",al={"anathera e latherion","amantes de heartswood","quem morreu em heartswood"}},{q="Por que os bruxos precisam de Heartswood?",a="Súcubos são criaturas demoníacas de desejo e manipulação emocional. Como a Heartswood ressoa poderosamente com a essência do amor inabalável e eterno, os bruxos a usam como uma potente isca psíquica para tentar e evocar uma súcubo para o mundo físico.",al={"por que bruxos querem heartswood","súcubo heartswood","propósito de heartswood"}},{q="Onde Heartswood pode ser encontrada?",a="Heartswood é encontrada nas Ruínas de Ordil'Aran, localizadas nos confins do noroeste da floresta de Vale Gris, perto da fronteira com Costa Negra.",al={"localização de heartswood","onde fica heartswood","ruínas de ordil'aran heartswood"}}},fx={["61f35e8f"]={q="De onde vem Heartswood e quem o fez?",a="Heartswood não é criado por mãos mortais, mas colhido de uma árvore solitária que brotou nas Ruínas de Ordil'Aran, no noroeste de Vale Gris. Durante a catastrófica Guerra dos Antigos, milênios atrás, dois amantes chamados Anathera e Latherion tombaram juntos em batalha. Onde eles deram seus últimos suspiros, a árvore criou raízes e cresceu, permanecendo como um monumento vivo à sua devoção eterna.",al={"origem de heartswood","de onde vem heartswood","como heartswood foi criado"}}},fp="10,201,22.420.0,21.390.1,19.157.0,32.223.0,32.184.0,30.113.0"}
P.entries["item:heartswood-core"] = {n="Cerne de Palocórdio",s="O Cerne de Palocórdio é um foco ritualístico encantado criado a partir da madeira de uma árvore ancestral. Fornecido por Gakin, o Neromante em Ventobravo, ele canaliza a magia necessária para perfurar a Espiral Etérea e evocar uma súcubo em um círculo de evocação arcano.",h="O Cerne de Palocórdio é um foco ritualístico encantado criado a partir da madeira de uma árvore ancestral.",kw={"gakin, o neromante","cerne de palocórdio","slaughtered lamb","ventobravo","sucubo","circulo de evocacao","a vinculação","bruxo"},ang={["class:Warlock"]="O Cerne de Palocórdio é uma relíquia de treinamento essencial para os bruxos da Aliança, servindo como o instrumento pelo qual eles evocam e dominam sua primeira súcubo."},sec={{t="Um Foco para o Éter",b="Nas criptas escuras sob a taverna O Cordeiro Imolado no Distrito dos Magos de Ventobravo, os bruxos realizam ritos longe dos olhos curiosos da guarda da cidade. O Cerne de Palocórdio serve como um canal arcano essencial para iniciar o ritual de aprisionamento. Feito a partir de palocórdio colhido, o cerne contém ressonância mágica residual suficiente para perfurar o véu entre os mundos. Ao focar suas artes sombrias através da madeira em um círculo de evocação consagrado, um iniciado pode abrir uma passagem para a Espiral Etérea, forçando uma súcubo a atravessar a barreira planar."},{t="O Teste de Aprisionamento",b="Evocar um demônio é apenas metade da luta; controlá-lo exige provar domínio absoluto sobre sua natureza astuta e sedutora. Gakin confia o Cerne de Palocórdio a praticantes promissores especificamente para que possam confrontar o demônio evocado em combate. Súcubos se aproveitam da fraqueza e facilmente subjugam mentes frágeis, tornando o encontro um rito de passagem mortal. Somente ao subjugar a criatura e devolver o cerne esgotado a Gakin é que um aspirante a bruxo prova que sua vontade é forte o suficiente para aprisionar o servo permanentemente."}},faq={{q="Para que serve o Cerne de Palocórdio?",a="O Cerne de Palocórdio é usado por bruxos como um reagente ritualístico para abrir um portal no círculo de evocação sob O Cordeiro Imolado. Este portal atrai uma súcubo da Espiral Etérea para o nosso reino para que ela possa ser combatida e aprisionada.",al={"o que faz o cerne de palocordio","uso do cerne de palocordio","proposito do cerne de palocordio"}},{q="Quem fornece o Cerne de Palocórdio?",a="Ele é fornecido por Gakin, o Neromante, um mestre bruxo que treina noviços nas catacumbas ocultas sob a taverna O Cordeiro Imolado no Distrito dos Magos de Ventobravo.",al={"onde consigo o cerne de palocordio","quem entrega o cerne de palocordio"}},{q="Onde o cerne deve ser usado?",a="O cerne deve ser canalizado no círculo de evocação rúnico localizado nas profundezas das criptas sob O Cordeiro Imolado, bem abaixo das ruas de Ventobravo.",al={"localizacao do cerne de palocordio","onde evocar sucubo"}},{q="O que acontece depois que o ritual termina?",a="Depois de usar o cerne para evocar a súcubo, você deve derrotar o demônio em combate para quebrar sua resistência. Uma vez que ele for banido de volta ao caos, devolva o Cerne de Palocórdio a Gakin, o Neromante para aprender o segredo de comandar o demônio à vontade.",al={"o que fazer apos evocar","entregar cerne de palocordio"}}},fx={["34d5c17e"]={q="O que é o Cerne de Palocórdio?",a="O Cerne de Palocórdio é uma relíquia oculta encantada, criada especificamente para rituais de invocação. Preparado por praticantes de magia sombria, ele atua como um catalisador mágico poderoso o suficiente para romper o véu entre os mundos e trazer uma súcubo da Espiral Etérea para um círculo de invocação.",al={"história do cerne de palocórdio","o que é cerne de palocórdio","item palocórdio"}},a2df89b9={q="De onde vem o Cerne de Palocórdio e quem o fez?",a="O cerne é preparado usando Palocórdio bruto recuperado das Ruínas de Ordil'Aran no Vale Gris, moldado e fortalecido sob a direção de Gakin, o Neromante. Gakin confia a relíquia completa a bruxos promissores que estudam abaixo do The Slaughtered Lamb em Ventobravo.",al={"quem fez o cerne de palocórdio","origem do cerne de palocórdio","como o cerne de palocórdio foi feito"}},cef9a99d={q="Por que Gakin quer que o Cerne de Palocórdio seja usado?",a="Um bruxo que busca subjugar uma súcubo precisa de uma âncora de imenso poder para abrir um portal para o vazio. Sem o Cerne de Palocórdio, você não consegue completar o feitiço ritual necessário para manifestar o demônio e subjugar sua mente traiçoeira.",al={"por que usar cerne de palocórdio","propósito do cerne de palocórdio","por que querer o cerne de palocórdio"}}},fp="15,202,22.443.0,20.458.1,37.194.0,33.176.0,28.125.0,42.179.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Coletor de Chumbo Pesado",s="O Coletor de Chumbo Pesado é um recipiente de amostragem blindado fornecido por Ozzie Mudavolt em Kharanos. Ele é projetado para extrair e conter com segurança a descarga irradiada altamente instável dos mutantes nas profundezas de Gnomeregan para pesquisas contínuas de descontaminação.",h="O Coletor de Chumbo Pesado é um recipiente de amostragem blindado fornecido por Ozzie Mudavolt em Kharanos.",kw={"gnomeregan","hall of gears","coletor de chumbo pesado","ozzie mudavolt","frasco","precipitação radioativa","the only cure is more green glow"},ang={["profession:Engineering"]="O frasco é um equipamento especializado para coletar precipitação volátil, um processo que pode exigir várias tentativas mesmo com um recipiente adequado.",["race:Gnome"]="Cada gota de precipitação volátil guardada no frasco representa um passo desesperado para reconquistar Gnomeregan e compreender a loucura química que roubou seu lar."},sec={{t="Um Recipiente Blindado",b="O Coletor de Chumbo Pesado é um recipiente de amostragem usado para extrair resíduos voláteis de criaturas vivas e irradiadas em Gnomeregan. Conter essa precipitação radioativa é difícil, e coletar uma amostra adequada pode exigir várias tentativas."},{t="Em Busca de uma Cura",b="Ozzie Mudavolt fornece o frasco como parte de sua pesquisa para reverter as horríveis mutações que afligem os gnomos leprosos. Amostras anteriores coletadas de troggs da superfície não tinham a potência necessária para uma análise química eficaz. Ao usar o frasco de chumbo em feras virulentas, como gosmas irradiadas e espreitadores no Hall of Gears, os pesquisadores esperam isolar os elementos ativos da precipitação tóxica da cidade e formular um antídoto eficaz."}},faq={{q="Para que serve o Coletor de Chumbo Pesado?",a="Ele é usado para extrair descargas radioativas concentradas diretamente de criaturas vivas e irradiadas dentro de Gnomeregan, fornecendo aos pesquisadores em Kharanos amostras puras para testes de descontaminação.",al={"o que este frasco faz","finalidade do frasco","o que é o frasco de chumbo"}},{q="Quem fornece o Coletor de Chumbo Pesado?",a="O pesquisador gnomo Ozzie Mudavolt o fornece em Kharanos, em Dun Morogh, como parte de sua pesquisa para curar gnomos leprosos irradiados e afligidos.",al={"quem fornece o frasco","onde obter o frasco","doador da missão do frasco"}},{q="Por que o frasco é feito de chumbo pesado?",a="Ele é descrito como um frasco de chumbo pesado, mas sua construção precisa não é explicada. Ozzie alerta que conter a precipitação radioativa é difícil e que a amostra se degradará rapidamente.",al={"por que frasco de chumbo","por que chumbo pesado"}},{q="Quais criaturas devem ser amostradas com o frasco?",a="Ele deve ser canalizado em horrores vivos e brilhantes encontrados nas profundezas de Gnomeregan, como gosmas irradiadas, espreitadores e horrores que rondam os níveis inferiores do Hall of Gears.",al={"em que usar","criaturas-alvo","quais monstros brilham"}}},fx={ca9f55e0={q="Por que Ozzie Mudavolt quer que o Coletor de Chumbo Pesado seja devolvido?",a="Ozzie Mudavolt precisa que tanto o frasco quanto uma amostra de Resíduo Radioativo de Alta Potência sejam devolvidos à sua oficina em Kharanos. Tendo testado anteriormente espécimes de trogg mais fracos e considerado-os insuficientes, ele precisa de radiação pura e não corrompida diretamente das criaturas dentro de Gnomeregan para avançar seus experimentos na cura dos gnomos leprosos aflitos.",al={"por que devolver o frasco de chumbo pesado","por que ozzie quer o frasco","por que o frasco coletor é necessário"}}},fp="29,212,17.202.0,17.442.0,51.172.0,47.150.0,36.193.0,47.175.0"}
P.entries["item:hezrul-s-head"] = {n="Cabeça do Hezrul",s="A Cabeça do Hezrul é o troféu macabro arrancado de Hezrul Marca de Sangue, chefe dos centauros Kolkar que habitam os Sertões. Entregue a Regthar Portões-da-morte a oeste da Encruzilhada, ela serve como prova inegável de que a liderança central dos saqueadores locais caiu.",h="A Cabeça do Hezrul é o troféu macabro arrancado de Hezrul Marca de Sangue, chefe dos centauros Kolkar que...",kw={"marca de sangue","centauro","encruzilhada","portões-da-morte","hezrul","kolkar","águas claras","regthar"},ang={["faction:Horde"]="Reivindicar a cabeça do chefe dos Kolkar garante o controle vital sobre as águas do Oásis das Águas Claras e protege os viajantes da Horda que cruzam os áridos Sertões.",["race:Orc"]="Regthar Portões-da-morte vê os Kolkar como arruaceiros indisciplinados cuja fúria desmedida é facilmente superada pela disciplina militar dos orcs, tornando este troféu um testemunho da verdadeira honra marcial."},sec={{t="Decapitando os Kolkar",b="Os centauros Kolkar mantêm um domínio agressivo sobre os oásis cruciais pelos áridos Sertões, ameaçando constantemente as rotas de suprimentos e os povoados emergentes da Horda. Hezrul Marca de Sangue comanda seu clã a partir do Oásis das Águas Claras, ao sul. Regthar Portões-da-morte, um veterano orc encarregado de proteger o território a oeste da Encruzilhada, reconhece que, embora os Kolkar possuam uma fúria feroz, eles carecem de disciplina formal. Ao exigir a cabeça decepada de Hezrul, Regthar busca fragmentar a estrutura de comando do clã, mergulhando os combatentes sobreviventes no caos e enfraquecendo seus ataques coordenados contra a Horda."}},faq={{q="A quem pertence esta cabeça?",a="A cabeça pertence a Hezrul Marca de Sangue, o líder brutal e astuto do clã de centauros Kolkar que infesta o centro dos Sertões.",al={"quem é hezrul","identidade de hezrul","de quem é esta cabeça"}},{q="Onde Hezrul Marca de Sangue é encontrado?",a="Hezrul comanda seu bando ao redor do Oásis das Águas Claras, situado ao sul da Encruzilhada, nos Sertões.",al={"localização de hezrul","onde fica hezrul","encontrar hezrul"}},{q="Quem quer a Cabeça do Hezrul?",a="Regthar Portões-da-morte, um orc estacionado em um posto avançado militar ao longo da estrada a oeste da Encruzilhada, pede a cabeça como prova da derrota do chefe.",al={"entregar cabeça do hezrul","quem recebe a cabeça do hezrul","regthar portões-da-morte"}},{q="Por que a Horda exige a cabeça dele em vez de apenas afugentá-lo?",a="A Horda precisa de certeza absoluta de que Hezrul está morto. Os centauros são naturalmente voláteis e propensos a conflitos internos; eliminar seu chefe supremo despedaça a estrutura de comando deles e diminui a ameaça que representam para a Encruzilhada.",al={"por que matar hezrul","por que pegar a cabeça dele","ameaça dos centauros"}}},fx={["67b3da29"]={q="De onde vem a Cabeça do Hezrul?",a="Esta cabeça decepada é retirada de Hezrul Bloodmark, um chefe centauro astuto e brutal encontrado no Oásis das Águas Claras, ao sul da Encruzilhada. Hezrul lidera a tribo Kolkar na região, coordenando seus ataques contra postos avançados da Horda e povoados vizinhos até ser derrotado.",al={"origem da cabeça do hezrul","de onde veio a cabeça do hezrul","de quem veio a cabeça do hezrul"}}},fp="13,177,23.465.0,29.70.0,32.85.0,24.143.0,69.186.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="Resíduo Radioativo de Alta Potência",s="O Resíduo Radioativo de Alta Potência é uma amostra concentrada e volátil do lodo irradiado que envenena as profundezas inferiores de Gnomeregan. Coletado em pesados recipientes de chumbo a pedido de pesquisadores gnomos, ele é buscado na esperança de fazer engenharia reversa para criar uma cura para os gnomos leprosos afetados.",h="O Resíduo Radioativo de Alta Potência é uma amostra concentrada e volátil do lodo irradiado que envenena as...",kw={"gnomeregan","brilho verde","hall of gears","resíduo radioativo de alta potência","lodo irradiado","gnomo leproso","ozzie mudavolt"},ang={["profession:Engineering"]="Conter e transportar isótopos radioativos voláteis e em decomposição exige frascos de chumbo feitos sob medida para proteger o portador contra uma exposição catastrófica.",["race:Gnome"]="Cada gota de resíduo tóxico coletada das profundezas da cidade representa uma tênue esperança de reverter a terrível mutação que despedaçou seu povo durante a queda de Gnomeregan."},sec={{t="Direto da Fonte",b="Embora pequenas amostras de radiação possam ser raspadas de carniceiros contaminados na superfície externa, o verdadeiro coração da catástrofe de Gnomeregan exige algo muito mais concentrado. Os pesquisadores posicionados do lado de fora da capital caída precisam de resíduos radioativos puros e não adulterados, extraídos diretamente de horrores, espreitadores e lodos irradiados vivos que rastejam pelos níveis mais baixos do Hall of Gears. Como esse lodo viscoso se decompõe constantemente, ele deve ser armazenado em um frasco de chumbo especializado e entregue rapidamente antes que a amostra se desestabilize por completo."},{t="Em Busca da Restauração",b="A busca desesperada por materiais tão letais tem um propósito urgente. Ozzie Mudavolt e seus colegas acreditam que desvendar os segredos do lodo irradiado é o único caminho viável para desenvolver uma cura para os gnomos leprosos. Enlouquecidos e deformados pela liberação de gases tóxicos ordenada durante a invasão dos troggs, esses sobreviventes trágicos permanecem presos em um pesadelo vivo, fazendo com que até mesmo as expedições de coleta mais perigosas dentro das ruínas valham o risco."}},faq={{q="De onde vem este resíduo radioativo?",a="Ele é extraído diretamente de criaturas irradiadas vivas — como lodos, horrores e espreitadores irradiados — que habitam as profundezas dos níveis inferiores do Hall of Gears, em Gnomeregan.",al={"onde conseguir resíduo radioativo","localização do resíduo radioativo","fonte do resíduo radioativo"}},{q="Por que esta amostra é necessária?",a="Pesquisadores gnômicos, incluindo Ozzie Mudavolt, precisam de uma amostra pura e altamente concentrada da radiação de Gnomeregan para estudar a aflição e tentar criar uma cura para seus irmãos corrompidos, os gnomos leprosos.",al={"quem quer o resíduo","propósito do resíduo radioativo","por que coletar resíduo radioativo"}},{q="Por que ele deve ser manuseado com tanto cuidado?",a="O resíduo é extremamente volátil e entra em colapso rapidamente à medida que se decompõe. Ele requer contenção pesada de chumbo para ser transportado com segurança e deve ser entregue aos pesquisadores antes que sua potência se degrade em resíduo inútil.",al={"decomposição do resíduo","por que frasco de chumbo","resíduo instável"}},{q="Por que o resíduo anterior dos troggs não foi suficiente?",a="O resíduo coletado de troggs da superfície fora da cidade provou ser fraco e impuro demais para testes científicos. Os pesquisadores precisam especificamente do brilho puro e concentrado encontrado apenas em criaturas que habitam as profundezas irradiadas da cidade.",al={"por que não o brilho dos troggs","radiação de trogg vs resíduo","falha da amostra anterior"}}},fx={["30a827ed"]={q="O que é o Resíduo Radioativo de Alta Potência?",a="Este resíduo é um composto concentrado e volátil colhido diretamente dos limos, horrores e espreitadores profundamente irradiados que se agitam dentro dos corredores arruinados de Gnomeregan. Altamente instável e brilhando com energia tóxica virulenta, ele representa o contaminante bruto que permanece no próprio coração do desastre.",al={"o que é resíduo radioativo de alta potência","lore sobre resíduo radioativo","o que é o resíduo"}}},fp="32,146,21.383.0,24.362.0,46.145.0,26.163.0,36.138.0,45.166.0"}
P.entries["item:highborne-relic-classic"] = {n="Relíquia dos Altaneiros",s="As Highborne Relics são antigos implementos mágicos recuperados dos espíritos inquietos que assombram as ruínas de Ameth'Aran na Costa Negra. Imbuídas com os experimentos arcanos que despedaçaram a antiga Kalimdor, elas são procuradas por estudiosos elfos noturnos que desejam vê-las destruídas antes que seus poderes adormecidos possam causar mais danos.",h="As Highborne Relics são antigos implementos mágicos recuperados dos espíritos inquietos que assombram as...",kw={"ameth'aran","arcano","costa negra","altaneiros","relíquia dos altaneiros","sentinelas","trovejius tecevento"},ang={["class:Mage"]="Os magos podem achar fascinante o trabalho artesanal arcano das relíquias, mas as autoridades locais dos elfos noturnos não toleram hesitação em destruí-las.",["race:NightElf"]="Para os elfos noturnos, essas relíquias servem como uma lembrança sombria da desastrosa arrogância arcana que despedaçou sua antiga civilização."},sec={{t="Vestígios da Cisão",b="Dez mil anos atrás, a casta dos Altaneiros praticava uma magia arcana imprudente, acabando por trazer a ruína sobre a antiga Kalimdor. Hoje, suas antigas propriedades jazem em ruínas despedaçadas pela Costa Negra. Entre as colunas decadentes de Ameth'Aran, aparições que choram e se contorcem vagam pelo chão da floresta, apegando-se indefinidamente aos implementos físicos de sua feitiçaria do passado. Essas relíquias permanecem como pontos de ancoragem persistentes de mácula arcana, agarradas por fantasmas que se recusam a soltar os instrumentos de sua própria ruína."},{t="Expurgando a Mácula Arcana",b="Para a sociedade moderna dos elfos noturnos, que em grande parte renunciou à magia arcana após a Grande Cisão, tais artefatos representam um grave perigo. Estudiosos como Trovejius Tecevento em Auberdine, agindo com base em relatórios de patrulha das Sentinelas, comissionam ativamente viajantes para arrancar essas relíquias das mãos espectrais dos espíritos amaldiçoados. Uma vez reunidas, as relíquias são sistematicamente destruídas para garantir que os males antigos e os erros catastróficos dos Altaneiros não se repitam."}},faq={{q="De onde vêm as Highborne Relics?",a="Elas são recuperadas dos espectros fantasmagóricos que assombram as ruínas de Ameth'Aran, localizadas a leste da estrada principal no sul da Costa Negra. Espíritos amaldiçoados, contorcidos e lamentantes de Altaneiros as carregam em meio às pedras antigas.",al={"onde encontrar highborne relics","quem dropa highborne relics","localização das relíquias"}},{q="Por que Trovejius Tecevento quer essas relíquias?",a="Trovejius Tecevento teme a corrupção arcana residual que ainda se apega a esses itens antigos. Ele as coleta para que possam ser completamente desmanteladas e destruídas, impedindo que qualquer pessoa reviva a perigosa feitiçaria dos Altaneiros.",al={"por que coletar relíquias","o que acontece com as relíquias","objetivo de tecevento"}},{q="Por que os espíritos dos Altaneiros ainda estão em Ameth'Aran?",a="Os espíritos são nobres antigos Altaneiros que pereceram quando o mundo se despedaçou há dez mil anos. Amaldiçoados por sua soberba e apego persistente à magia arcana, suas almas inquietas permanecem presas às ruínas de sua antiga cidade.",al={"por que fantasmas de ametharan estao la","quem sao os altaneiros amaldiçoados","por que ha fantasmas na costa negra"}},{q="As Highborne Relics são seguras para uso?",a="Não. Os elfos noturnos as consideram maculadas pelas práticas arcanas vis e descontroladas que desencadearam a Grande Cisão. Sua magia adormecida é considerada perigosa, razão pela qual os estudiosos exigem sua destruição em vez de seu estudo.",al={"posso usar highborne relics","as reliquias sao perigosas"}}},fx={["9b193d00"]={q="O que é uma Relíquia dos Altaneiros?",a="Uma Relíquia dos Altaneiros é um antigo instrumento mágico criado pelos feiticeiros Altaneiros da antiga Kalimdor. Essas ferramentas encantadas sobrevivem nas mãos dos espíritos inquietos que assombram as ruínas destruídas de Ameth'Aran, carregando a mancha persistente da feitiçaria arcana que precipitou a Grande Cisão.",al={"o que é relíquia dos altaneiros","lore sobre relíquias dos altaneiros","o que são essas relíquias"}}},fp="15,141,25.381.0,24.381.0,36.173.0,47.157.0,50.228.0,33.202.0"}
P.entries["item:highperch-venom-sac"] = {n="Vesícula de Peçonha de Alcândora",s="As Bolsas de Veneno de Alcândora são coletadas das serpes aladas selvagens que nidificam sobre as torres imponentes de Alcândora, em Mil Agulhas. Embora os orcs valorizem as serpes aladas como montarias aéreas, boticários e comerciantes seletos prezam seus potentes ferrões ainda mais do que as feras vivas.",h="As Bolsas de Veneno de Alcândora são coletadas das serpes aladas selvagens que nidificam sobre as torres...",kw={"fiora longears","heartrazor","alcândora","veneno","theramore","mil agulhas","bolsa de veneno","serpe alada"},ang={["class:Rogue"]="O veneno paralisante altamente concentrado, extraído das serpes aladas indomadas de Mil Agulhas, representa uma das toxinas naturais mais potentes encontradas em Kalimdor.",["faction:Alliance"]="Atacar os ninhos de Alcândora serve a um duplo propósito para a Aliança: coletar reagentes biológicos valiosos para o comércio enquanto abate espécimes selvagens que, de outro modo, poderiam ser capturados e domados como montarias da Horda."},sec={{t="Uma Colheita Potente",b="Os altos pináculos de Mil Agulhas abrigam prósperos bandos de serpes aladas selvagens, particularmente ao redor dos penhascos elevados de Alcândora. Esses predadores alados dependem de um veneno poderoso, injetado por suas caudas farpadas, para paralisar e matar presas. Embora a Horda frequentemente domestique essas criaturas como leais mantícoras, suas bolsas de veneno alcançam um preço notavelmente alto entre alquimistas, caçadores e mercadores oportunistas por toda Kalimdor."},{t="Uma Compradora Distante",b="Embora seja nativo dos cânions profundos da região central de Kalimdor, este veneno atrai interesse muito além deles. Na cidade portuária de Theramore, a elfa altiva Fiora Longears paga generosamente por bolsas frescas coletadas das ninhadas de Alcândora. Ela busca amostras estufadas de veneno — normalmente encontradas apenas em serpes aladas jovens ou fêmeas férteis —, alimentando o comércio de reagentes perigosos longe do habitat natural desértico dessas feras."}},faq={{q="Quais criaturas carregam essas bolsas de veneno?",a="Elas são coletadas diretamente das serpes aladas selvagens que habitam Alcândora, em Mil Agulhas, incluindo as Serpes Aladas de Alcândora, Patriarcas, Consortes e a matriarca Heartrazor.",al={"onde caem bolsas de veneno","quem dropa highperch venom","drop de veneno de serpe alada"}},{q="Por que Fiora Longears quer esse veneno em Theramore?",a="Fiora Longears reconhece que o veneno de serpe alada é extremamente valioso em círculos comerciais específicos — às vezes até mais lucrativo do que as próprias montarias. Ela contrata viajantes que se aventuram até Alcândora, em Mil Agulhas, para recuperar bolsas intactas para o comércio.",al={"por que fiora quer veneno","comprador de veneno de theramore","quem compra veneno de serpe alada"}},{q="Todas as bolsas de veneno de serpe alada são idênticas?",a="A potência e o volume variam. As bolsas mais valiosas estão estufadas e transbordando de veneno, o que é encontrado tipicamente entre serpes aladas jovens ou fêmeas férteis em idade reprodutiva.",al={"qualidade do veneno de serpe alada","bolsas de veneno estufadas"}},{q="Como a Horda utiliza essas serpes aladas em comparação com a Aliança?",a="A Horda primariamente captura e cria serpes aladas como montarias aéreas e batedores conhecidos como mantícoras. Comerciantes independentes e contatos da Aliança, sem redes de domesticação, preferem abater as feras diretamente para extrair seus reagentes químicos letais.",al={"uso de serpes aladas pela horda","orcs usam o veneno"}}},fx={["98761a97"]={q="O que é uma Vesícula de Peçonha de Alcândora?",a="Uma Vesícula de Peçonha de Alcândora é um órgão colhido das mantícoras selvagens que fazem ninho no imponente planalto de Alcândora em Mil Agulhas. Embora as mantícoras sejam mais conhecidas em toda Kalimdor como montarias aladas utilizadas pela Horda, seu veneno é valorizado por sua pura potência. As vesículas retiradas das bestas no topo de Alcândora são particularmente ricas e inchadas com essa toxina mortal, tornando-as um prêmio lucrativo para alquimistas e comerciantes que lidam com reagentes animais exóticos.",al={"o que é vesícula de peçonha de alcândora","vesícula de peçonha de alcândora","vesícula de veneno de mantícora"}}},fp="19,123,16.261.0,15.310.0,38.125.0,53.203.0,36.137.0,66.206.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Ovo de Mantícora de Alcândora",s="Ovos de Mantícora de Alcândora são ovos de ninhada coletados nos locais de nidificação no topo dos altos platôs de Mil Agulhas. Eles são cobiçados por aspirantes a Wind Riders da Horda para criar e treinar novas montarias aéreas.",h="Ovos de Mantícora de Alcândora são ovos de ninhada coletados nos locais de nidificação no topo dos altos...",kw={"elu","aldeia vento livre","alcândora","ovo de mantícora de alcândora","mil agulhas","wind rider","mantícora"},ang={["class:Hunter"]="Navegar pelas alturas perigosas de Alcândora exige compreender o comportamento de predadores ferozes, já que as mantícoras adultas defendem seus locais de nidificação com garras afiadas e ferrões venenosos.",["faction:Horde"]="O transporte aéreo confiável é vital para manter a comunicação e a prontidão militar pelos vastos territórios de Kalimdor, tornando a obtenção de novos espécimes de mantícora uma questão de importância estratégica."},sec={{t="Ninhos no Platô",b="O alto platô de Alcândora em Mil Agulhas oferece um santuário natural para mantícoras nativas empoleirarem e criarem seus filhotes. Acessíveis apenas por caminhos íngremes e sinuosos pelas paredes do desfiladeiro, esses locais de nidificação são ferozmente protegidos por feras adultas. Os ovos postos nesses poleiros são resistentes e aquecidos, abrigando filhotes em desenvolvimento capazes de se adaptar aos céus severos de Kalimdor."},{t="Criando Novos Wind Riders",b="Por toda Kalimdor, a demanda por mantícoras treinadas supera continuamente a oferta à medida que a Horda expande suas redes de mensageiros e patrulha. Na Aldeia Vento Livre, aprendizes como o tauren Elu buscam ovos intactos diretamente de ninhos selvagens. Ao criar os filhotes desde a casca, os treinadores esperam forjar os laços profundos necessários para treinar montarias aladas confiáveis para os Wind Riders da Horda."}},faq={{q="Onde esses ovos são encontrados?",a="Eles ficam espalhados em ninhos por toda Alcândora, um platô elevado situado ao longo dos paredões rochosos ocidentais de Mil Agulhas, acessível por um caminho que sobe a partir do fundo do desfiladeiro.",al={"localizações dos ovos","onde encontrar ovos de mantícora","localização dos ovos de alcândora"}},{q="Por que a Horda coleta ovos de mantícora selvagens?",a="As fileiras de Wind Riders da Horda estão crescendo, e os adestradores lutam para treinar mantícoras adultas suficientes para atender à demanda. Aprendizes como Elu coletam ovos para poder criar os filhotes desde o nascimento, preparando tanto a fera quanto o cavaleiro para o serviço aéreo.",al={"por que roubar ovos de mantícora","para que servem os ovos","objetivo da missão de ovos de elu"}},{q="Os pais mantícoras são hostis com quem coleta os ovos?",a="Sim. Mantícoras selvagens protegem ferozmente seus ninhos e atacam com violência quaisquer invasores que entrarem em Alcândora para mexer em suas ninhadas.",al={"mantícoras atacam","mantícoras são protetoras"}},{q="Quem aceita esses ovos na Aldeia Vento Livre?",a="Elu, um aspirante a Wind Rider posicionado no topo da Aldeia Vento Livre, coleta os ovos na esperança de iniciar seu próprio treinamento formal de montaria.",al={"quem aceita ovos de mantícora","elu aldeia vento livre"}}},fx={efbaa71b={q="O que é um Ovo de Mantícora de Alcândora?",a="Estes são os ovos viáveis de mantícoras selvagens que fazem ninhos no alto dos planaltos do cânion de Mil Agulhas. Dentro de suas cascas resistentes descansam os filhotes não nascidos dos predadores alados de Kalimdor, altamente procurados por aqueles que desejam criar montarias aéreas leais desde a infância.",al={"o que é ovo de mantícora de alcândora","informações sobre ovo de mantícora","o que são esses ovos"}},bbfa5024={q="De onde vêm os Ovos de Mantícora de Alcândora?",a="Eles são postos por mantícoras selvagens em seus ninhos no topo das falésias em Alcândora, um planalto elevado que se ergue acima dos cânions de Mil Agulhas. As mantícoras adultas protegem ferozmente seus ninhos contra predadores e saqueadores audazes.",al={"de onde vêm os ovos de mantícora de alcândora","quem pôs os ovos","origem do ovo de mantícora"}}},fp="20,116,17.269.0,23.290.0,27.139.0,44.168.0,48.118.0,40.107.0"}
P.entries["item:hildelve-s-journal"] = {n="Diário de Hildelve",s="O Diário de Hildelve é o último registro do piloto anão Hildelve, resgatado de seus restos mortais na gélida vastidão de Dun Morogh. Suas páginas manchadas de sangue relatam seu encontro fatal com um urso feroz e transmitem seu último desejo de vingança.",h="O Diário de Hildelve é o último registro do piloto anão Hildelve, resgatado de seus restos mortais na gélida...",kw={"dun morogh","hildelve","urso garra-de-gelo","diário","mangeclaw","piloto pisafundo","brigada de cerco"},ang={["faction:Alliance"]="Recuperar os pertences pessoais de membros das forças militares caídos, como Hildelve, fortalece o vínculo entre a Aliança e a Brigada de Cerco de Altaforja.",["race:Dwarf"]="O diário honra o espírito inabalável dos pilotos anões, que desafiam o clima congelante e feras selvagens para proteger as alturas de Khaz Modan."},sec={{t="As Últimas Palavras de um Piloto",b="Quando seu tanque a vapor quebrou, o piloto anão Hildelve deixou seu parceiro Pisafundo com os tanques e partiu sozinho pelos penhascos açoitados pela neve de Dun Morogh em busca de rumores sobre o minério de chiron. De acordo com as anotações rabiscadas em seu diário, ele foi perseguido por dias e depois emboscado por um monstruoso urso garra-de-gelo conhecido como Mangeclaw. Embora Hildelve tenha lutado com bravura e conseguido espantar a fera, ele ficou gravemente ferido e encalhado no frio congelante. O diário detalha suas angustiantes horas finais, concluindo com um apelo único e claro antes que o predador retornasse para matá-lo: que quem quer que descobrisse seu corpo vingasse sua morte caçando Mangeclaw."},{t="Retorno à Brigada de Cerco",b="O diário resgatado serve como um desfecho sombrio para o camarada de Hildelve, o Piloto Pisafundo, estacionado perto do Posto de Guarda do Portão Norte, na parte leste de Dun Morogh. Como membro da Brigada de Cerco de Altaforja, Pisafundo temia o pior quando Hildelve nunca retornou de sua busca por minério. Entregar o diário junto com a garra decepada da fera serve como prova de que o espírito de Hildelve agora descansa em paz e seu último desejo foi honrado."}},faq={{q="Quem foi Hildelve?",a="Hildelve era um piloto de tanque a vapor anão que pertencia à Brigada de Cerco de Altaforja. Após o colapso de seu tanque, ele partiu sozinho pelas terras ermas de Dun Morogh em busca de minério de chiron e foi morto pelo urso Mangeclaw antes que pudesse retornar.",al={"história de hildelve","quem é hildelve","piloto anão hildelve"}},{q="O que é Mangeclaw?",a="Mangeclaw é um urso garra-de-gelo extraordinariamente grande e feroz que vaga pelas cristas nevadas de Dun Morogh. Ele emboscou Hildelve enquanto este estava desamparado, feriu-o gravemente e, mais tarde, retornou para tirar sua vida.",al={"quem é mangeclaw","o que matou hildelve","urso que matou hildelve"}},{q="Quem recebe o diário depois que ele é encontrado?",a="O diário é entregue ao Piloto Pisafundo, um piloto de engenho de cerco estacionado perto do Posto de Guarda do Portão Norte, na parte leste de Dun Morogh. Pisafundo era um grande amigo de Hildelve e buscava notícias sobre o paradeiro do piloto desaparecido.",al={"onde levar o diário","quem recebe o diário de hildelve","entregar o diário de hildelve"}},{q="O que Hildelve pede no diário?",a="Sabendo que seus ferimentos eram fatais, Hildelve usou suas últimas páginas para documentar a fera que o atacou e pediu a qualquer viajante que encontrasse seus restos mortais que caçasse Mangeclaw para vingar sua morte.",al={"último desejo de hildelve","o que tem no diário","último desejo do piloto"}}},fx={b58cc0e1={q="O que é o Diário de Hildelve?",a="Este diário surrado pertenceu a Hildelve, um piloto anão abatido da Brigada de Cerco de Altaforja. Encontrado ao lado de seus restos mortais nas extensões congeladas de Dun Morogh, ele registra seus angustiantes momentos finais — documentando sua sobrevivência a um ataque brutal inicial do grande urso Mangeclaw, e escrevendo seu desejo final de vingança antes que a besta voltasse para acabar com ele.",al={"o que é este diário","lore do diário de hildelve","sobre o diário de hildelve"}},["308c8265"]={q="De onde vem o Diário de Hildelve e quem o fez?",a="O diário foi escrito pelo próprio Piloto Hildelve durante seu calvário em Dun Morogh. Depois que seu tanque a vapor quebrou, ele saiu à procura de minério de círon a pé e foi atacado pelo urso Mangeclaw; ele manteve este registro pessoal até sua morte, deixando um testamento escrito de sua luta e seu pedido final.",al={"quem escreveu o diário","de onde veio o diário de hildelve","origem do diário de hildelve"}},["856dae3f"]={q="Por que alguém quer o Diário de Hildelve?",a="Seu colega piloto de tanque a vapor, Piloto Pisafundo, estava desesperadamente procurando notícias de seu camarada perdido. O diário oferece uma prova definitiva do destino de Hildelve e honra seu pedido final de retribuição contra o monstro que tirou sua vida, trazendo um encerramento para seus amigos na Brigada de Cerco de Altaforja.",al={"por que guardar o diário de hildelve","quem quer o diário","por que trazer o diário de hildelve de volta"}}},fp="18,145,21.567.0,27.344.1,17.205.0,18.207.0,42.179.0,42.197.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Crânio Humano de Eira dos Montes",s="Um macabro troféu de guerra colhido de defensores e habitantes humanos mortos por todo o Contraforte de Eira dos Montes. Esses crânios são coletados por Renegados estacionados na Serraria Tarren como lembranças sombrias do ataque implacável contra os povoados humanos locais.",h="Um macabro troféu de guerra colhido de defensores e habitantes humanos mortos por todo o Contraforte de Eira...",kw={"darthalia","eira dos montes","samsa","crânio","costa sul","serraria tarren","troféu"},ang={["faction:Alliance"]="A visão dos fazendeiros e soldados de Eira dos Montes reduzidos a bugigangas colecionadas representa a crueldade sombria da campanha dos Renegados em Lordaeron.",["race:Undead"]="Para os Renegados, reivindicar crânios humanos de Eira dos Montes é tanto uma doce vingança quanto um lembrete macabro dos irmãos vivos que os rejeitam."},sec={{t="Troféus de uma Guerra Amarga",b="Enquanto o conflito se intensifica entre os Renegados da Serraria Tarren e os habitantes humanos da Costa Sul e dos assentamentos ao redor, crânios decepados servem como prova física do massacre. Enquanto os Espreitadores da Morte e os soldados executam a purga sistemática ordenada por Darthalia durante a Battle of Hillsbrad, outros guardas presos ao serviço de vigia anseiam por uma parte da carnificina. A Necroguarda Sandoval solicita avidamente esses troféus aos combatentes da linha de frente, sentindo um prazer perverso ao acumular os restos das mesmas pessoas entre as quais os Renegados viveram quando eram vivos."}},faq={{q="Quem quer estes crânios humanos?",a="O Necroguarda Sandoval, um sentinela Renegado estacionado na Serraria Tarren, os coleta. Com inveja dos soldados enviados para lutar e saquear Eira dos Montes enquanto permanece confinado ao serviço de guarda, ele pede aos aventureiros que passam que lhe tragam trinta crânios para adicionar à sua coleção particular.",al={"quem quer crânios","quem aceita crânios humanos","crânios do necroguarda sandoval"}},{q="Onde são coletados os Crânios Humanos de Eira dos Montes?",a="Eles são obtidos de combatentes e trabalhadores humanos por todo o Contraforte de Eira dos Montes, principalmente ao redor das fazendas, minas e fortificações da cidade controladas por humanos que foram atacadas durante a campanha da Battle of Hillsbrad.",al={"onde caem crânios","farmar crânios humanos","quem dropa crânios humanos"}},{q="Por que os Renegados coletam restos humanos?",a="Além do ódio puro e do humor sombrio, colecionar troféus de humanos mortos é um esporte macabro para alguns Renegados. Soldados como Sandoval veem os crânios como curiosidades valiosas e provas satisfatórias da queda iminente de Eira dos Montes.",al={"por que os renegados querem crânios","coleção de crânios dos renegados"}}},fx={["0091f8c0"]={q="O que é um Crânio Humano de Eira dos Montes?",a="Estes são os troféus macabros decepados dos defensores humanos caídos e habitantes da cidade espalhados pelo Contraforte de Eira dos Montes. À medida que o conflito ocorre entre os Renegados da Serraria Tarren e os humanos vivos de Eira dos Montes, tais símbolos macabros servem como prova tangível de baixas da Aliança no território disputado.",al={"o que são crânios humanos de eira dos montes","item crânio de eira dos montes","informações sobre crânio humano de eira dos montes"}},["9eb161fa"]={q="De onde vem um Crânio Humano de Eira dos Montes e quem o fez?",a="Esses crânios são tirados diretamente dos humanos mortais que habitam o Contraforte de Eira dos Montes, colhidos por combatentes da Horda engajados na guerra de fronteira em curso. Em vez de serem fabricados, eles são remanescentes mórbidos de campos de batalha retirados dos soldados, fazendeiros e cidadãos mortos que defendiam os assentamentos humanos locais contra os Renegados.",al={"origem do crânio humano de eira dos montes","de onde vêm os crânios de eira dos montes","quem faz os crânios de eira dos montes"}},a9ea879b={q="Por que o Necroguarda Sandoval quer Crânios Humanos de Eira dos Montes?",a="O Necroguarda Sandoval, estacionado em serviço de guarda na Serraria Tarren, morre de inveja dos guerreiros enviados para saquear e lutar contra os vivos. Preso atrás das linhas de frente, ele coleciona os crânios como preciosas lembranças pessoais de morte para compartilhar, de forma vicária, o massacre dos defensores humanos de Eira dos Montes.",al={"por que samsa quer crânios","quem quer crânios humanos de eira dos montes e por que","por que coletar crânios humanos de eira dos montes"}}},fp="21,143,24.447.0,29.227.0,42.203.0,42.160.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Cartório de Eira dos Montes",s="O Cartório de Eira dos Montes é um livro de registro municipal oficial mantido dentro da prefeitura dos Campos de Eira dos Montes. Ele serve como uma contabilidade dos cidadãos sobreviventes, proprietários de terras e registros cívicos do assentamento, tornando-o um alvo estratégico essencial durante a ofensiva dos Renegados contra o reduto humano.",h="O Cartório de Eira dos Montes é um livro de registro municipal oficial mantido dentro da prefeitura dos...",kw={"a batalha de eira dos montes","darthalia","campos de eira dos montes","prefeitura de eira dos montes","cartório de eira dos montes","magistrado burnside"},ang={["faction:Horde"]="Capturar o cartório da cidade é um passo decisivo para quebrar a autoridade humana nos contrafortes e consolidar a fortaleza dos Renegados na Serraria Tarren.",["race:Human"]="O livro de registro representa a existência formal e os direitos dos cidadãos restantes de Eira dos Montes, tornando sua perda um golpe devastador para a comunidade regional."},sec={{t="Um Registro de Desafio",b="Repousando na prefeitura perto do pódio do Magistrado Burnside, o Cartório de Eira dos Montes documenta a população, as propriedades e os direitos administrativos de Eira dos Montes. Conforme os Renegados da Serraria Tarren avançam para quebrar a resistência humana nos contrafortes, Darthalia ordena que os campeões da Horda infiltrem-se na prefeitura, eliminem o conselho e confisquem este livro de registro. Confiscar o cartório despoja Eira dos Montes de sua ordem cívica e fornece à Cidade Baixa informações valiosas sobre a população sobrevivente e seus bens."}},faq={{q="Onde o Cartório de Eira dos Montes é guardado?",a="O registro está abrigado dentro da prefeitura nos Campos de Eira dos Montes, localizado em um canto perto das escadas que levam à plataforma do Magistrado Burnside.",al={"localização do cartório","onde fica o cartório da cidade","encontrar cartório de eira dos montes"}},{q="Por que os Renegados querem roubá-lo?",a="A Alta-executora Darthalia busca desmantelar completamente o governo humano nos contrafortes. Tomar o cartório priva a cidade de registros vitais sobre seus cidadãos e propriedades, ao mesmo tempo em que fornece aos Renegados informações detalhadas sobre a comunidade sobrevivente.",al={"por que roubar o cartório","missão do cartório de darthalia","objetivo do cartório"}},{q="Quem guarda o cartório?",a="Ele é guardado pelo Magistrado Burnside e pelos Conselheiros de Eira dos Montes, que utilizam magia defensiva e se reúnem dentro e ao redor da prefeitura.",al={"quem protege o cartório","defensores da prefeitura"}}},fx={["188a667c"]={q="O que é o Cartório de Eira dos Montes?",a="O Cartório de Eira dos Montes é um livro de registros oficial mantido dentro da prefeitura do assentamento de Campos de Eira dos Montes. Mantido pela administração humana local sob o Magistrado Burnside, ele documenta os assuntos cívicos, a população e a governança de uma das propriedades sobreviventes da Aliança no contraforte.",al={"o que é o cartório de eira dos montes","cartório de eira dos montes","o que é o livro de registros"}}},fp="23,209,20.486.0,42.136.0,37.220.0,24.138.0"}
P.entries["item:hinterlands-honey-ripple"] = {n="Suco Gami das Terras Agrestes",s="Caixas de Suco Gami das Terras Agrestes estão numa base abandonada da Horda perto da Rocha Oculta. Dran Droffers quer as garrafas para um esquema de embalagem.",h="Caixas de Suco Gami das Terras Agrestes estão numa base abandonada da Horda perto da Rocha Oculta.",kw={"dran droffers","suco gami das terras agrestes","honey ripple","caixas da horda","malton","ripple","rocha oculta"},ang={["faction:Horde"]="As garrafas estão em caixas numa base abandonada da Horda perto da Rocha Oculta."},sec={{t="Caixas na Rocha Oculta",b="As caixas na Rocha Oculta contêm Suco Gami das Terras Agrestes, uma bebida incomum que Dran Droffers procura. A base abandonada da Horda fica entre ruínas cobertas de limo, onde as garrafas devem ser recolhidas com cuidado. As embalagens intactas são importantes para o esquema que Dran planeja."}},faq={{q="Onde posso encontrar Suco Gami das Terras Agrestes?",a="O Suco Gami das Terras Agrestes está em caixas espalhadas pela base abandonada da Horda perto da Rocha Oculta.",al={"localização do honey ripple","onde fica o ripple","garrafas das terras agrestes"}},{q="Quem quer o Honey Ripple?",a="Dran Droffers procura Suco Gami das Terras Agrestes para um esquema de embalagem envolvendo o pai de Malton.",al={"quem quer o ripple","dran droffers e o ripple","ripple para quem"}},{q="Por que Dran precisa das garrafas intactas?",a="Dran diz que as garrafas não podem sofrer pancadas, pois o sacolejo estraga o buquê da bebida. Ele tem embalagens vazias para o ripple.",al={"por que não amassar as garrafas","não amassar o ripple","embalagem do ripple"}},{q="O que é Suco Gami das Terras Agrestes?",a="É uma bebida engarrafada guardada em caixas na base abandonada da Horda perto da Rocha Oculta.",al={"honey ripple","o que é ripple","bebida das terras agrestes"}}},fp="24,138,20.263.0,42.86.0,27.96.1,38.127.0,33.81.0"}
P.entries["item:hippogryph-muisek"] = {n="Hippogryph Muisek",s="Hippogryph Muisek preserva os espíritos dos hipogrifos Frayfeather em Feralas. Um druida da Selva Alta pede que você os capture com um Muisek Vessel.",h="Hippogryph Muisek preserva os espíritos dos hipogrifos Frayfeather em Feralas.",kw={"feralas","frayfeather","selva alta","hipogrifo","hippogryph muisek","muisek vessel","espírito"},ang={["race:NightElf"]="Como elfo noturno, você conhece os hipogrifos como companheiros leais cujos espíritos são firmes. A preocupação do druida é preservar esses espíritos com segurança."},sec={{t="Espíritos preservados",b="Entre os hipogrifos Frayfeather da Selva Alta, você deve capturar dez com o Muisek Vessel. Os elfos noturnos há muito mantêm hipogrifos como companheiros leais, e seus espíritos são firmes. O recipiente preserva cada espírito depois que sua criatura é morta."}},faq={{q="O que é Hippogryph Muisek?",a="Hippogryph Muisek é o espírito preservado de um hipogrifo Frayfeather, capturado em um Muisek Vessel.",al={"hippogryph muisek","item muisek"}},{q="Onde encontro hipogrifos Frayfeather?",a="Os hipogrifos Frayfeather vivem na Selva Alta, ao sul do druida que pede que você os capture.",al={"local dos hipogrifos","onde encontrar frayfeather"}},{q="Por que capturar os hipogrifos?",a="O druida quer que o muisek deles seja preservado, pois um espírito que fica livre depois que sua criatura morre pode assumir a forma de uma criatura maior e ameaçar quem estiver por perto.",al={"por que muisek","capturar hipogrifos"}},{q="Quantos hipogrifos são necessários?",a="O druida pede que você capture dez hipogrifos Frayfeather.",al={"quantos hipogrifos","quantidade de muisek"}}},fp="17,160,17.263.0,26.99.0,40.101.0,28.155.1,32.58.0"}
P.entries["item:hippogryph-muisek-vessel"] = {n="Hippogryph Muisek Vessel",s="O Hippogryph Muisek Vessel preserva os espíritos dos hipogrifos em Feralas. Ele é usado para capturar o muisek deles na Selva Alta.",h="O Hippogryph Muisek Vessel preserva os espíritos dos hipogrifos em Feralas.",kw={"frayfeather","selva alta","hipogrifo","muisek de hipogrifo","hippogryph muisek vessel","muisek","zor solárbol"},ang={["race:NightElf"]="Há muito tempo, os hipogrifos são companheiros leais dos elfos noturnos, e preservar seus espíritos é importante para Zor Solárbol."},sec={{t="Um espírito preservado",b="Depois que você provar que sabe usar o recipiente, Zor Solárbol pedirá que capture o muisek dos hipogrifos. Os hipogrifos Frayfeather vivem na Selva Alta, ao sul dele. Há muito tempo, seus espíritos são companheiros leais dos elfos noturnos. Zor teme que um espírito solto após a morte do animal possa se tornar uma criatura maior e buscar vingança."}},faq={{q="Para que serve o Hippogryph Muisek Vessel?",a="O recipiente captura o muisek dos hipogrifos para que seus espíritos possam ser preservados.",al={"para que serve o recipiente","uso do recipiente de hipogrifo"}},{q="Onde devo usar o recipiente?",a="Os hipogrifos Frayfeather ficam na Selva Alta, ao sul de Zor Solárbol.",al={"onde usar o recipiente de muisek","recipiente na selva alta"}},{q="Por que capturar o muisek dos hipogrifos?",a="O recipiente preserva o muisek dos hipogrifos. Zor Solárbol teme que um espírito solto após a morte possa se tornar uma criatura maior e buscar vingança.",al={"por que capturá-los","espíritos de hipogrifo"}},{q="Os hipogrifos são importantes para os elfos noturnos?",a="Há muitos anos, os hipogrifos são companheiros leais dos elfos noturnos.",al={"hipogrifos dos elfos noturnos","companheiros hipogrifos"}}},fp="24,137,18.341.0,42.72.0,26.78.0,30.145.0,41.73.0"}
P.entries["item:hollow-vulture-bone"] = {n="Osso Oco de Abutre",s="Ossos Ocos de Abutre são restos esqueléticos leves e duráveis, obtidos dos carniceiros da Chapada Cintilante. No Circuito da Ilusão, mecânicos goblins os valorizam como materiais de construção especializados para aliviar seus carros-foguete sem sacrificar a integridade estrutural.",h="Ossos Ocos de Abutre são restos esqueléticos leves e duráveis, obtidos dos carniceiros da Chapada Cintilante.",kw={"osso oco de abutre","peso pena","circuito da ilusão","relé","carniceiro","chapada cintilante","mil agulhas"},ang={["class:Hunter"]="Os abutres da Chapada Cintilante são carniceiros resistentes, tornando-se alvos naturais para rastreamento pelo leito de sal ofuscante.",["profession:Engineering"]="Enquanto os diagramas típicos dependem de ferro e bronze pesados, o uso de osso oco de ave demonstra o pragmatismo engenhoso de redução de peso fundamental para a inovação automobilística goblin."},sec={{t="Materiais de Corrida na Chapada",b="A velocidade é tudo nas salinas, e o peso é o inimigo da velocidade. Enquanto a engenharia padrão depende muito de ferro e cobre, as equipes de apoio goblins no Circuito da Ilusão recorrem a tudo o que o deserto oferece para obter uma vantagem. Os ossos de abutre são naturalmente ocos, mas incrivelmente resistentes, proporcionando a relação resistência-peso perfeita para suportes internos, mecanismos de direção e pequenas estruturas de apoio. Para chefes de engenharia como Relé, coletar ossos de carniceiros locais é um atalho prático e barato para reduzir preciosos segundos na pista."}},faq={{q="Por que os goblins querem ossos de abutre?",a="Engenheiros goblins como Relé usam ossos ocos de abutre para reduzir o excesso de peso de seus carros-foguete. Como os ossos de aves são naturalmente leves e surpreendentemente fortes, eles se tornam o material ideal para mecanismos de direção e pequenas estruturas de sustentação.",al={"por que ossos","uso de ossos goblins","uso de ossos relé"}},{q="De onde vêm esses ossos?",a="Eles são obtidos de Salt Flats Scavengers e Salt Flats Vultures que sobrevoam a Chapada Cintilante em Mil Agulhas, principalmente ao redor dos restos esqueléticos gigantes espalhados pelo deserto de sal.",al={"onde encontrar osso oco de abutre","localização osso de abutre","como conseguir ossos de abutre"}},{q="Quem é Relé?",a="Relé é um engenheiro goblin e mecânico-chefe alocado no Circuito da Ilusão. Ele continuamente aprimora e modifica carros-foguete para competir contra a equipe gnômica liderada por Xabu Latafuso.",al={"quem e rele","rele circuito da ilusao","quem pega os ossos"}}},fx={["2d4c7633"]={q="O que é um Osso Oco de Abutre?",a="São ossos leves e resistentes, coletados de aves carniceiras que voam sobre a Chapada Cintilante. Esqueletos de aves são naturalmente ocos para auxiliar no voo, o que os torna ideais para a engenharia mecânica, onde eliminar cada grama extra faz diferença. No Circuito da Ilusão, os mecânicos goblins os usam para criar peças estruturais resistentes e componentes de direção para seus carros-foguete.",al={"o que é um osso oco de abutre","ossos ocos de abutre"}}},fp="19,195,29.384.0,38.158.0,31.189.0,14.164.0"}
P.entries["item:honorary-picks"] = {n="Picaretas Honorárias",s="As Picaretas Honorárias são um conjunto de ferramentas cerimoniais criadas em Altaforja para jovens aprendizes de mineração anões. Confiadas a viajantes por meio da rede de grifos, elas são entregues a Brock Buscapedra em Thelsamar para marcar que seus alunos estão prontos para trabalhar nos ricos veios de minério de Loch Modan.",h="As Picaretas Honorárias são um conjunto de ferramentas cerimoniais criadas em Altaforja para jovens...",kw={"brock buscapedra","grif trovino","picaretas honorárias","altaforja","loch modan","picaretas de mineração","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Todo mineiro em Khaz Modan entende o valor de uma picareta sólida, e receber uma ferramenta honorária marca a verdadeira passagem de um novato para a profissão.",["race:Dwarf"]="Para um anão, presentear aprendizes que trabalham nas províncias com ferramentas forjadas em Altaforja é uma tradição celebrada de parentesco e ofício."},sec={{t="Ferramentas para a Próxima Geração",b="Na sociedade anã, a mineração é muito mais do que um ofício; é um pilar cultural que mantém as grandes forjas ardendo e o reino abastecido com ferro e pedra. As Picaretas Honorárias representam o reconhecimento formal aos prospectores novatos que aprendem com Brock Buscapedra em Thelsamar. Obtidas diretamente de Altaforja, estas picaretas são presenteadas aos alunos que provaram sua dedicação e estão prontos para enfrentar os depósitos de minério a céu aberto por todo Loch Modan."},{t="Testando as Linhas de Grifos",b="Transportar as picaretas serve a um propósito secundário para os montanheses e mercadores da Aliança: apresentar aos mensageiros a rede de grifos do reino. Transportada da Grande Forja de Altaforja diretamente para Grif Trovino e levada de voo através das montanhas até Thorgrum Borrelson em Thelsamar, a remessa ilustra o quão estreitamente a capital permanece ligada aos seus postos avançados remotos por meio de rápida passagem aérea."}},faq={{q="Para que servem as Picaretas Honorárias?",a="As Picaretas Honorárias são criadas para os alunos de mineração de Brock Buscapedra em Loch Modan. Elas servem como ferramentas cerimoniais, porém funcionais, dadas a aprendizes prontos para minerar veios de minério por toda a região.",al={"o que são picaretas honorárias","uso das picaretas honorárias","propósito das picaretas honorárias"}},{q="Quem envia as picaretas e quem as recebe?",a="As picaretas são preparadas em Altaforja e levadas até Grif Trovino no Gryphon Roost da cidade. De lá, são levadas de voo para o leste até Thelsamar e entregues em mãos ao instrutor de mineração Brock Buscapedra.",al={"quem recebe picaretas honorárias","entrega das picaretas honorárias","destinatário das picaretas honorárias"}},{q="Por que as picaretas precisam ser entregues por grifo?",a="Embora pudessem ser carregadas a pé pelo Desfiladeiro do Portão Norte, enviá-las através do mestre de grifos Grif Trovino garante transporte rápido e ensina aos viajantes como utilizar as rotas de voo estabelecidas da Aliança entre Altaforja e Loch Modan.",al={"por que enviar picaretas de voo","por que usar grifo","voo das picaretas honorárias"}},{q="As Picaretas Honorárias são armas reais ou ferramentas que você pode equipar?",a="Não. O mensageiro as carrega apenas como carga; elas são destinadas aos alunos de mineração de Brock Buscapedra, que estão ansiosos para colocá-las em uso nos depósitos de minério de Loch Modan.",al={"posso equipar picaretas honorárias","picaretas honorárias são um item","picaretas honorárias utilizáveis"}}},fx={a7b14bb4={q="O que são as Picaretas Honorárias?",a="As Picaretas Honorárias são um conjunto de ferramentas de mineração cerimoniais ou comemorativas criadas em Altaforja. Elas são designadas como um presente especial para mineiros noviços que aprendem o ofício sob a orientação de garimpeiros experientes nas colinas de Loch Modan.",al={"o que são as picaretas honorárias","item picaretas honorárias","história das picaretas honorárias"}},["0ecadd79"]={q="De onde vêm as Picaretas Honorárias e quem as fez?",a="As picaretas são adquiridas na capital anã de Altaforja. Criadas por ferreiros montanheses habilidosos na Grande Forja da cidade, elas são embaladas especificamente para serem transportadas até instrutores que treinam aprendizes fora das fronteiras de Dun Morogh.",al={"quem fez as picaretas honorárias","origem das picaretas honorárias","de onde vieram as picaretas"}},["1a632b74"]={q="Por que alguém quer as Picaretas Honorárias?",a="O instrutor de mineração Brock Buscapedra, em Thelsamar, solicitou as picaretas para presentear seus alunos novatos. Como garimpeiros aspirantes que trabalham em Loch Modan, os alunos aguardam ansiosamente por essas honrarias e ferramentas para começar a explorar os ricos veios minerais da região.",al={"por que entregar as picaretas honorárias","quem quer as picaretas honorárias","por que brock quer as picaretas"}}},fp="14,202,29.256.0,25.237.0,37.165.0,43.192.0,49.237.0,61.144.0"}
P.entries["item:horn-of-arra-chea"] = {n="Chifre de Arra'chea",s="O Chifre de Arra'chea é um troféu de caça retirado do lendário kodo Arra'chea, que vagueia pelas planícies de Mulgore. Reivindicado a pedido do Grande Chefe Caerne Casco Sangrento, o chifre serve como prova definitiva de que um aspirante a caçador possui a disciplina e a habilidade de rastreamento necessárias para prover aos Shu'halo.",h="O Chifre de Arra'chea é um troféu de caça retirado do lendário kodo Arra'chea, que vagueia pelas planícies de...",kw={"arra'chea","caerne casco sangrento","chifre de arra'chea","kodo","mulgore","ritos da mãe terra","penhasco do trovão"},ang={["class:Hunter"]="Rastrear o caminho circular de Arra'chea pela ampla extensão de Mulgore testa habilidades fundamentais de perseguição e sobrevivência na selva, valorizadas por qualquer verdadeiro caçador.",["race:Tauren"]="Apresentar este chifre ao Grande Chefe Caerne marca um rito de passagem crucial, confirmando sua prontidão para sustentar e defender seu povo no topo do Penhasco do Trovão."},sec={{t="O Teste de um Chefe",b="Embora passar pelos Ritos da Mãe Terra iniciais conceda a um jovem o seu devido lugar no topo do Penhasco do Trovão, o Grande Chefe Caerne Casco Sangrento espera que seu povo continue a provar seu valor. Para os taurens, a identidade está diretamente ligada à caça e à sua duradoura harmonia com a terra. Caerne testa jovens caçadores incumbindo-os de rastrear Arra'chea, um touro kodo enorme e solitário que vagueia pelas pradarias abaixo. Obter o chifre de Arra'chea comprova o domínio sobre a arte fundamental de rastrear presas através de vastas distâncias."},{t="Provendo para a Tribo",b="Levar o chifre ao High Rise do Penhasco do Trovão é mais do que uma demonstração de força marcial; serve à sobrevivência de toda a comunidade. Na cultura tauren, nada de uma fera abatida é desperdiçado. Apresentar o troféu alerta o Grande Chefe sobre a localização da fera caída, permitindo que grupos de coleta desçam rapidamente às planícies para recolher o couro espesso e a carne farta de Arra'chea para a jovem capital."}},faq={{q="O que é o Chifre de Arra'chea?",a="É um chifre retirado de Arra'chea, um kodo poderoso e esquivo que percorre as planícies de Mulgore. Caçadores o levam a Caerne Casco Sangrento como um rito de passagem para demonstrar suas habilidades de rastreamento.",al={"chifre de arrachea","chifre arrachea","o que e este chifre"}},{q="Quem é Arra'chea?",a="Arra'chea é um renomado touro kodo que circula pelas pradarias a nordeste do Penhasco do Trovão. Conhecido por sua força e sua ampla rota migratória, ele serve como uma presa formidável para caçadores que buscam provar seu valor para a tribo.",al={"arrachea","quem e arrachea","historia de arrachea"}},{q="Por que Caerne Casco Sangrento pede esse troféu?",a="Caerne acredita que manter a própria posição no Penhasco do Trovão exige provas contínuas de serviço e capacidade. Ao rastrear e abater Arra'chea, o caçador comprova sua dedicação às tradições da Mãe Terra e fornece recursos valiosos para a comunidade.",al={"por que caerne quer o chifre","caerne arrachea","chifre dos ritos da mae terra"}},{q="O que acontece com o resto da fera após ser morta?",a="De acordo com o costume tauren, nenhuma parte do animal caçado é desperdiçada. Assim que o chifre é entregue para confirmar o abate, Caerne envia um grupo de coleta a Mulgore para recolher o couro e a carne para o Penhasco do Trovão.",al={"carne de arrachea","tradicao de caca tauren","carcaca de arrachea"}}},fx={["0ff92160"]={q="De onde vem o Chifre de Arra'chea e quem o fez?",a="O chifre não é um artefato criado, mas um troféu natural retirado de Arra'chea, um poderoso kodo que vaga pelas planícies de Mulgore, abaixo do Penhasco do Trovão. Para reivindicá-lo, um caçador deve rastrear a grande fera nas pastagens abertas e abatê-la em combate honroso.",al={"origem chifre de arra'chea","de onde veio o chifre de arra'chea","quem fez o chifre de arra'chea"}}},fp="17,138,18.421.0,23.316.0,30.173.0,17.199.0,46.233.0,57.169.0"}
P.entries["item:horn-of-awakening"] = {n="Corneta do Despertar",s="A Corneta do Despertar é um instrumento sonoro guardado em um baú por Kerlonian Perenumbra no sul de Costa Negra. Ela é usada para despertar o druida sonolento sempre que ele cai no sono na estrada para Vale Gris.",h="A Corneta do Despertar é um instrumento sonoro guardado em um baú por Kerlonian Perenumbra no sul de Costa...",kw={"vale gris","costa negra","druid of the claw","sonho esmeralda","corneta do despertar","kerlonian perenumbra","entreposto de maestra"},ang={["class:Druid"]="Druids of the Claw passaram gerações dormindo nos Barrow Dens em comunhão com o Sonho Esmeralda, e retornar à realidade desperta frequentemente os deixa atordoados e desorientados.",["race:NightElf"]="A jornada sonolenta de Kerlonian mostra como o retorno ao mundo desperto pode ser difícil para os druidas dos elfos noturnos após seu longo sono no Sonho Esmeralda."},sec={{t="Um Remédio para Druidas Sonolentos",b="Kerlonian Perenumbra, um Druid of the Claw recém-desperto de séculos dentro do Sonho Esmeralda, encontra-se constantemente letárgico no reino desperto. Viajando para o sul em direção ao Entreposto de Maestra, ele confia esta corneta a viajantes dispostos a escoltá-lo. Sempre que a exaustão o domina ao longo da perigosa trilha selvagem, um toque claro do instrumento sobressalta seus sentidos, incentivando-o a se levantar antes que feras selvagens ou cultistas possam tirar proveito de seu sono."}},faq={{q="Onde a Corneta do Despertar é encontrada?",a="A corneta repousa dentro do Kerlonian's Chest, ao lado do acampamento de Kerlonian Perenumbra no sul de Costa Negra, perto da fronteira de Vale Gris.",al={"localização da corneta","onde fica a corneta do despertar","kerlonians chest"}},{q="Por que Kerlonian precisa da corneta para ficar acordado?",a="Tendo passado longas eras dormindo dentro do Sonho Esmeralda, Kerlonian luta para se ajustar à vigília mortal e cai constantemente em cochilos repentinos e profundos enquanto viaja.",al={"por que kerlonian está dormindo","por que ele adormece","sono do sonho esmeralda"}},{q="Para onde Kerlonian está tentando ir?",a="Ele está tentando chegar ao Entreposto de Maestra, no norte de Vale Gris, para se encontrar com Liladris Luneflúvia.",al={"destino de kerlonian","para onde ele está caminhando","escolta até o entreposto de maestra"}}},fx={["061d2ee3"]={q="O que é a Corneta do Despertar?",a="A Corneta do Despertar é um instrumento pessoal que pertence ao druida elfo noturno Kerlonian Perenumbra. Tendo emergido recentemente do Sonho Esmeralda, Kerlonian sofre de ataques de sono profundo e inoportuno durante suas viagens. Ele mantém esta corneta guardada em seu baú especificamente para que um escolta possa tocá-la para acordá-lo sempre que ele desmaiar ao longo da estrada.",al={"corneta do despertar","o que é este chifre","chifre de kerlonian"}}},fp="17,119,26.391.0,37.127.0,47.148.0,32.93.0"}
P.entries["item:horn-of-echeyakee"] = {n="Berrante de Echeyaki",s="O Berrante de Echeyaki é um instrumento de caça fornecido por Sergra Espinhonegro na Encruzilhada. Tocá-lo em meio aos antigos restos de kodo a nordeste do assentamento evoca Névoa Branca, o lendário predador branco dos Sertões.",h="O Berrante de Echeyaki é um instrumento de caça fornecido por Sergra Espinhonegro na Encruzilhada.",kw={"sertões","encruzilhada","echeyaki","berrante","ossos de kodo","sergra espinhonegro","névoa branca"},ang={["class:Hunter"]="Para os caçadores, invocar Echeyaki representa um rito de passagem lendário, confrontando seus sentidos contra um predador famoso por todos os Sertões por sua furtividade quase impecável.",["race:Tauren"]="A caçada de Echeyaki tem peso espiritual entre os taurens, que veem o abate rápido e indolor da fera como uma personificação tanto da misericórdia quanto da dura necessidade da morte."},sec={{t="Chamando o Névoa Branca",b="Entregue a iniciados que testam suas proezas na caçada, o chamado do berrante ecoa pela savana para invocar Echeyaki, cujo nome se traduz do Taur-ahe como \"Névoa Branca\". Conhecido como o rei dos felinos da savana, Echeyaki é reverenciado pelos caçadores taurens tanto como misericórdia quanto como morte, atacando tão depressa que sua presa não sente pavor nem sofrimento. O berrante deve ser tocado apenas no covil do grande predador, um ninho branqueado pelo sol de ossos de kodo gigantes escondido atrás das colinas a nordeste da Encruzilhada."}},faq={{q="O que o Berrante de Echeyaki faz?",a="O berrante é usado para atrair Echeyaki, o esquivo felino branco da savana. Tocar o berrante perto dos ossos de kodo gigantes a nordeste da Encruzilhada provoca a fera a aparecer para que um caçador possa enfrentá-lo.",al={"usar berrante de echeyaki","para que serve o berrante de echeyaki"}},{q="De onde vem o berrante?",a="Sergra Espinhonegro, uma caçadora orc que reside na Encruzilhada nos Sertões, confia o berrante aos aventureiros que buscam provar sua sutileza e habilidade de rastreamento.",al={"quem entrega o berrante","origem do berrante de echeyaki"}},{q="O que significa o nome Echeyaki?",a="Na língua tauren, o Taur-ahe, Echeyaki significa \"Névoa Branca\". O nome homenageia a pelagem pálida da fera e sua habilidade silenciosa, semelhante a uma névoa, de espreitar pela relva seca sem ser detectado.",al={"significado de echeyaki","significado de névoa branca"}},{q="Onde se toca o berrante?",a="O berrante deve ser tocado entre as costelas de kodo gigantes e os restos esqueléticos encontrados atrás das colinas a nordeste da Encruzilhada, onde o leão branco estabeleceu seu território de caça.",al={"onde usar o berrante","localização de echeyaki"}}},fx={eb6b337d={q="O que é o Berrante de Echeyaki?",a="O Berrante de Echeyaki é um instrumento ritual de caça dado a caçadores promissores na Encruzilhada por Sergra Darkthorn. Soprado entre os ossos gigantes de kodo a nordeste do assentamento, seu chamado atrai o próprio Echeyakee — o leão branco reverenciado pelos taurens como o rei dos felinos da savana.",al={"berrante de echeyaki","o que é este chifre","o que é o berrante de echeyaki"}},["5884ea69"]={q="Por que Sergra Darkthorn lhe dá o Berrante de Echeyaki?",a="Sergra Darkthorn fornece o berrante como uma ferramenta vital para testar sua proeza. Echeyakee espreita as planícies sem ser visto, como um nevoeiro branco, tornando-o quase impossível de rastrear apenas pela visão. O sopro do berrante desafia o grande predador, atraindo-o para lutar, para que você possa reivindicar sua pele e provar sua habilidade de caça.",al={"por que preciso do berrante de echeyaki","por que berrante de echeyaki","propósito do berrante de echeyaki"}}},fp="17,207,21.375.0,35.165.0,30.144.0,34.134.0,27.135.0"}
P.entries["item:huge-gnoll-claw"] = {n="Enorme Garra de Gnoll",s="A Enorme Garra de Gnoll é um troféu inconfundível obtido de Hogger, o imenso gnoll que espreita o sudoeste da Floresta de Elwynn. Com dimensões muito superiores a qualquer garra normal de gnoll, ela serve como a Proof of Demise oficial exigida pelas autoridades de Ventobravo em Vila d'Ouro.",h="A Enorme Garra de Gnoll é um troféu inconfundível obtido de Hogger, o imenso gnoll que espreita o sudoeste da...",kw={"recompensa","floresta de elwynn","vila d'ouro","hogger","enorme garra de gnoll","delegado durão","riverpaw"},ang={["class:Hunter"]="Garantir a garra de um predador tão descomunal demonstra suprema capacidade de rastreamento e caça a feras contra um brutamontes que rotineiramente subjugava patrulhas armadas.",["faction:Alliance"]="Reivindicar a garra livra o coração do reino de seu terror mais infame dos bosques, provando o seu valor ao Delegado Durão e à guarnição sobrecarregada em Vila d'Ouro."},sec={{t="Prova do Caçador de Recompensas",b="Durante meses, o brutamontes Hogger aterrorizou os bosques ao sul de Boca da Mata, ignorando patrulhas e frustrando qualquer esforço da guarnição local para cercá-lo ou subjugá-lo. Superado e disperso por Elwynn, o Exército de Ventobravo colocou uma recompensa aberta pela cabeça da fera. O Delegado Durão em Vila d'Ouro exige provas inegáveis antes de liberar os fundos da recompensa, e a garra descomunal do bruto oferece uma confirmação indiscutível de que o terror dos bosques finalmente caiu."}},faq={{q="Para que serve a Enorme Garra de Gnoll?",a="A garra serve como prova oficial da morte de Hogger. Ela é levada diretamente ao Delegado Durão em Vila d'Ouro para concluir a recompensa anunciada e recolher a sua recompensa.",al={"o que fazer com a garra de hogger","uso da enorme garra de gnoll","quem quer a garra"}},{q="De onde vem esta garra?",a="Ela é obtida diretamente de Hogger, um gnoll elite que vaga perto dos acampamentos Riverpaw ao longo das fronteiras do sudoeste de Boca da Mata na Floresta de Elwynn.",al={"quem saqueia a garra","como conseguir enorme garra de gnoll","onde encontrar enorme garra de gnoll"}},{q="Por que o Delegado Durão quer uma garra em vez da cabeça?",a="Hogger é anormalmente grande até mesmo para um gnoll, e suas garras imensas são distintas e instantaneamente reconhecíveis. Apresentar uma delas não deixa dúvidas para o Exército de Ventobravo de que o notório saqueador foi verdadeiramente abatido.",al={"por que proof of demise garra","por que não a cabeça de hogger","prova de recompensa do durão"}},{q="Posso conseguir outra garra se eu perdê-la?",a="Sim. Se a garra for perdida antes de você entregá-la ao Delegado Durão, você poderá caçar Hogger novamente no sudoeste da Floresta de Elwynn para reivindicar uma substituta.",al={"enorme garra de gnoll perdida","posso pegar a garra novamente","renascimento da garra de hogger"}}},fx={d9093290={q="O que é a Enorme Garra de Gnoll?",a="A Enorme Garra de Gnoll é a prova física cortada do fim de Hogger, um gnoll notório e enorme que aterroriza o sudoeste da Floresta de Elwynn. Como Hogger superou todas as tentativas de captura pelas autoridades locais, essa garra distinta serve como evidência inegável para o Delegado Durão de que o bruto finalmente foi morto.",al={"o que é a enorme garra de gnoll","informações da enorme garra de gnoll","garra de hogger"}},["7983cdb8"]={q="Por que o Delegado Durão quer a Enorme Garra de Gnoll?",a="O Delegado Durão e o Exército de Ventobravo colocaram uma recompensa por Hogger depois que a fera gigante evadiu e dominou suas patrulhas. Durão exige a garra enorme do gnoll como prova de sua morte antes de pagar a recompensa em Vila d'Ouro, acabando finalmente com a dor de cabeça que Hogger causou a seus homens.",al={"por que dughan quer a garra","quem quer a enorme garra de gnoll","por que querer a enorme garra de gnoll"}}},fp="15,140,21.406.0,37.104.0,31.138.0,56.179.0,36.142.0"}
P.entries["item:humbert-s-sword"] = {n="Espada do Humberto",s="A Espada do Humberto é a arma secundária pessoal pertencente ao Necroguarda Humberto de Serraria Tarren. A arma foi saqueada de seu acampamento por soldados anões enquanto ele espionava a fortaleza deles em Dun Garok.",h="A Espada do Humberto é a arma secundária pessoal pertencente ao Necroguarda Humberto de Serraria Tarren.",kw={"darthalia","necroguarda humberto","dun garok","eira dos montes","espada do humberto","serraria tarren"},ang={["faction:Horde"]="Recuperar a espada coincide com operações mais amplas da Horda voltadas contra o enclave anão de Dun Garok, incluindo a coleta de sangue de anão e insígnias militares.",["race:Undead"]="A Alta-executora Darthalia mantém uma disciplina implacável sobre as forças dos Renegados em Eira dos Montes, deixando sentinelas negligentes como Humberto desesperados para esconder seus erros."},sec={{t="O descuido de um batedor",b="O Necroguarda Humberto foi enviado pela Alta-executora Darthalia para vigiar a presença dos anões em Dun Garok a partir de uma posição escondida. Quando ele deixou seu posto desacompanhado certa manhã para buscar lenha para ferver água, patrulhas de anões se depararam com seu acampamento e pilharam todos os seus pertences, incluindo sua lâmina pessoal. Com tantos anões para vasculhar, Humberto depende de agentes da Horda para se infiltrarem na fortaleza e recuperarem sua arma perdida."},{t="O tesouro dos anões",b="Após o roubo, os pertences de Humberto foram levados para trás das barricadas fortificadas de Dun Garok. Como fuzileiros, montanhistas e sacerdotes anões circulam suprimentos por toda a guarnição, localizar o ladrão específico exige fazer buscas entre os defensores posicionados nas trincheiras e redutos da fortaleza."}},faq={{q="Quem é o dono desta espada?",a="A lâmina pertence ao Necroguarda Humberto, uma sentinela Renegada posicionada em Serraria Tarren destacada para espionar Dun Garok.",al={"de quem é esta espada","dono humberto","quem é humberto"}},{q="Como os anões conseguiram a espada de Humberto?",a="O Necroguarda Humberto deixou seu acampamento de espionagem do lado de fora de Dun Garok para buscar lenha pela manhã. Enquanto estava longe, uma patrulha de anões saqueou o acampamento e levou seus equipamentos.",al={"como os anões conseguiram","por que os anões têm a espada","como a espada foi roubada"}},{q="Por que Humberto está tão desesperado para recuperar sua espada?",a="Humberto precisa de sua arma para manter a vigia sobre Dun Garok ordenada pela Alta-executora Darthalia e, com tantos anões na guarnição, ele não tem como encontrar o ladrão sozinho.",al={"por que humberto quer a espada","o que acontece se humberto perder a espada","por que humberto se importa"}},{q="Onde a espada pode ser encontrada?",a="A espada está em posse das forças anãs aquarteladas em Dun Garok, situada no sudeste de Contraforte de Eira dos Montes. Ela pode ser recuperada de montanhistas, fuzileiros ou sacerdotes posicionados por todo o posto avançado.",al={"onde a espada cai","localização da espada","como encontrar a espada do humberto"}}},fp="15,163,25.357.0,17.242.0,20.116.0,40.156.0,50.171.0,29.181.0"}
P.entries["item:huntsman-malkhor-s-bones"] = {n="Huntsman Malkhor's Bones",s="Huntsman Malkhor's Bones são restos encontrados em um poço de lama em Jintha'alor. Guarda-caça Markhor procura por eles para que seu irmão gêmeo receba um enterro digno.",h="Huntsman Malkhor's Bones são restos encontrados em um poço de lama em Jintha'alor.",kw={"terras agrestes","huntsman malkhor's bones","guarda-caça markhor","jintha'alor","malkhor","separation anxiety","poço de lama","irmão gêmeo","vilebranch"},sec={{t="Restos de um irmão",b="Em Jintha'alor, nas Terras Agrestes, Huntsman Malkhor's Bones jazem em uma fossa de lixo entre os limos dos Vilebranch. Guarda-caça Markhor pede que você recupere os restos junto com o crânio do irmão. Ele espera levar os restos até Yayo'jin para um enterro digno."}},faq={{q="Onde estão os ossos de Malkhor?",a="Huntsman Malkhor's Bones estão em um poço de lama em Jintha'alor, perto do topo do templo.",al={"localização dos ossos de malkhor","onde encontrar os ossos"}},{q="Quem quer os ossos de Malkhor?",a="Guarda-caça Markhor, na Aldeia Revatusco, quer os restos do irmão gêmeo para providenciar um enterro digno.",al={"quem precisa dos ossos","ossos do irmão de markhor"}},{q="Quem foi Malkhor?",a="Huntsman Malkhor era irmão gêmeo de Guarda-caça Markhor. Os Vilebranch o capturaram e mataram durante uma incursão.",al={"história de malkhor","gêmeo de markhor"}},{q="Por que recuperar os ossos?",a="Markhor espera levar os restos de Malkhor até Yayo'jin para um enterro digno.",al={"por que os ossos importam","enterro de malkhor"}},{q="O que aconteceu com os restos de Malkhor?",a="Os Vilebranch deram os restos de Malkhor como alimento aos limos e lobos de Jintha'alor.",al={"restos de malkhor","o que aconteceu com os ossos dele"}}},fp="24,151,19.239.0,26.88.0,26.105.0,16.103.1,22.72.0,35.76.1"}
P.entries["item:huntsman-malkhor-s-skull"] = {n="Huntsman Malkhor's Skull",s="Huntsman Malkhor's Skull faz parte dos restos mortais que o Guarda-caça Markhor procura em Jintha'alor. Ele espera dar ao irmão gêmeo um enterro digno.",h="Huntsman Malkhor's Skull faz parte dos restos mortais que o Guarda-caça Markhor procura em Jintha'alor.",kw={"huntsman malkhor","guarda-caça markhor","jintha'alor","caveira de malkhor","aldeia revatusco","separation anxiety","vilebranch"},sec={{t="Os restos de um irmão",b="Entre as caveiras de Jintha'alor está a de Huntsman Malkhor, irmão gêmeo do Guarda-caça Markhor, da Aldeia Revatusco. Os Vilebranch mataram Malkhor e deixaram seus restos para os limos e lobos perto dos andares superiores do templo. Markhor pede que você recupere a caveira e os ossos para que a alma do irmão possa descansar em paz."}},faq={{q="A quem pertence a caveira?",a="A caveira pertence a Huntsman Malkhor, irmão gêmeo do Guarda-caça Markhor, da Aldeia Revatusco.",al={"caveira de malkhor","de quem é a caveira","huntsman malkhor"}},{q="Onde está a caveira de Malkhor?",a="A caveira de Malkhor está numa pilha de caveiras no andar superior de Jintha'alor.",al={"localização da caveira","onde fica a caveira","caveira de jintha'alor"}},{q="Quem quer os restos mortais de Malkhor?",a="O Guarda-caça Markhor quer que você recupere a caveira e os ossos do irmão gêmeo para dar a ele um enterro digno.",al={"quem quer os restos mortais","irmão de markhor","separation anxiety"}},{q="Como Malkhor morreu?",a="Os Vilebranch mataram Malkhor durante uma incursão e deram seus restos mortais aos limos e lobos.",al={"o que aconteceu com malkhor","morte de malkhor","vilebranch matou"}},{q="Por que Markhor está procurando os restos mortais?",a="Markhor espera preparar os restos mortais de Malkhor para um enterro digno e dar paz à sua alma.",al={"por que recuperar a caveira","enterro de malkhor","restos do irmão"}}},fp="24,137,19.321.0,29.97.0,25.75.0,28.93.0,20.80.1,41.95.0"}
P.entries["item:hyacinth-mushroom"] = {n="Cogumelo Jacinto",s="Os Cogumelos Jacinto são fungos distintos encontrados brotando nas raízes das árvores por todo o Umbravale em Teldrassil. Apreciados pelos herboristas elfos noturnos locais por suas propriedades medicinais, eles também são alimentos e forragem favoritos dos travessos grell e grellkin.",h="Os Cogumelos Jacinto são fungos distintos encontrados brotando nas raízes das árvores por todo o Umbravale em...",kw={"antídoto","dirânia pratafulge","grell","grellkin","cogumelo jacinto","iverron","umbravale","teldrassil"},ang={["profession:Herbalism"]="Embora colher esses fungos em Umbravale não exija treinamento formal, qualquer herborista iniciante apreciará seu papel na neutralização de toxinas virulentas da floresta.",["race:NightElf"]="Para jovens elfos noturnos em treinamento em Umbravale, colher a flora selvagem como os Cogumelos Jacinto é uma lição inicial sobre como utilizar as dádivas da natureza para sustentar seu povo."},sec={{t="Flora de Umbravale",b="Os Cogumelos Jacinto crescem abundantemente por todo o Umbravale, florescendo nas sombras úmidas nas bases das árvores, em pedras musgosas e nas raízes extensas de Aldrassil. Embora úteis em remédios da floresta, eles também chamaram a atenção dos grell corrompidos, que frequentemente os acumulam. Quando jovens sentinelas ou aprendizes elfos noturnos são afligidos pela fauna venenosa local — como as aranhas da Caverna Fionumbra —, esses cogumelos servem como um componente essencial em poções calmantes e antídotos preparados por curandeiros da floresta."}},faq={{q="Para que servem os Cogumelos Jacinto?",a="Dirânia Pratafulge os utiliza como um ingrediente vital para preparar um antídoto para Iverron, um jovem elfo noturno que foi picado e envenenado por aranhas venenosas enquanto explorava a Caverna Fionumbra.",al={"uso do cogumelo jacinto","o que ele faz","cura de iverron"}},{q="Onde crescem os Cogumelos Jacinto?",a="Eles brotam diretamente no chão, perto dos troncos e raízes de grandes árvores, bem como ao lado de pedregulhos por todo o vale isolado de Umbravale em Teldrassil.",al={"localização do cogumelo","onde encontrar cogumelo jacinto","cogumelos de umbravale"}},{q="Por que os grell carregam Cogumelos Jacinto?",a="Os travessos grell e grellkin que infestam o sul de Umbravale desenvolveram um apreço peculiar pelos cogumelos, colhendo-os e acumulando-os em seus acampamentos.",al={"cogumelos saqueados de grell","por que os grells têm eles","cogumelos de grellkin"}},{q="Os Cogumelos Jacinto são venenosos?",a="Não. Apesar de sua aparência brilhante e do ambiente sombrio no qual florescem, os curandeiros locais os empregam com segurança como ingrediente em emplastros cicatrizantes e antídotos restauradores.",al={"o cogumelo jacinto é tóxico","cogumelo venenoso"}}},fx={["77b7a797"]={q="O que é um Cogumelo Jacinto?",a="Um Cogumelo Jacinto é um fungo nativo encontrado por todos os galhos sombrios de Teldrassil, particularmente ao redor das bases das árvores e pedras musgosas em Umbravale. Notáveis pelo seu valor medicinal, estes cogumelos da floresta possuem propriedades naturais capazes de neutralizar venenos quando preparados adequadamente junto com outras floras locais.",al={"o que é o cogumelo jacinto","informações do cogumelo jacinto","sobre cogumelos jacinto"}}},fp="17,161,19.329.0,37.158.0,33.121.0,42.102.0,44.84.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Dispositivo Hipercapacitador",s="O Dispositivo Hipercapacitador é uma peça excêntrica de engenharia recuperada do leito do cânion de Mil Agulhas. Outrora pendurado no pescoço de uma fera enjaulada em uma caravana em ruínas, seu verdadeiro propósito permanece um mistério até mesmo para o engenhoqueiro que afirma ser seu dono.",h="O Dispositivo Hipercapacitador é uma peça excêntrica de engenharia recuperada do leito do cânion de Mil...",kw={"centauro","pantera enfurecida","dispositivo","hipercapacitador","mil agulhas","posto confinalvo","wizlo bearingshiner"},ang={["faction:Horde"]="Viajantes que ajudam o Posto Confinalvo auxiliam a eliminar os centauros agressivos e a recuperar esquisitices perdidas de caravanas em ruínas por todo o leito do cânion.",["profession:Engineering"]="O dispositivo representa a clássica engenharia gnômica e goblínica: um dispositivo intrincado, de nome perigoso, construído com grande entusiasmo antes que alguém se preocupasse em decidir o que ele deveria fazer."},sec={{t="A Estranha Relíquia de uma Caravana",b="Quando saqueadores centauros emboscaram uma caravana de goblins que viajava por Mil Agulhas, eles pilharam quase tudo à vista. O único sobrevivente, Wizlo Bearingshiner, conseguiu rastejar em segurança até o Posto Confinalvo, deixando para trás seu melhor dispositivo: o Dispositivo Hipercapacitador. Estranhamente, a engenhoca acabou presa ao pescoço de uma pantera feroz e enfurecida, trancada dentro de uma gaiola de transporte. Os centauros invasores temiam a fera o suficiente para deixar a gaiola totalmente intocada em meio aos destroços em chamas, preservando sem querer a estranha máquina de Wizlo."},{t="Engenhocando no Escuro",b="Embora Wizlo orgulhosamente chame o dispositivo de sua melhor criação, ele admite, após sua recuperação, que não faz a menor ideia do que ele realmente faz. Como muitas engenhocas de goblins, o Dispositivo Hipercapacitador é um emaranhado de ambição e peças voláteis, destinado a manter seu dono ocupado com ajustes sem fim, em vez de servir a qualquer função prática e compreensível."}},faq={{q="O que é o Dispositivo Hipercapacitador?",a="É um dispositivo de engenharia pertencente ao goblin Wizlo Bearingshiner. Apesar de seu nome pomposo, nem mesmo Wizlo sabe realmente que função ele desempenha, pretendendo dedicar seu tempo a estudá-lo para descobrir seu propósito.",al={"o que é o dispositivo","hipercapacitador","o que o dispositivo faz"}},{q="Como o dispositivo foi parar no pescoço de uma pantera?",a="A caravana de Wizlo foi atacada e saqueada por centauros no norte de Mil Agulhas. Durante o caos, o dispositivo acabou preso ao pescoço de uma pantera enfurecida trancada em uma gaiola de viagem, o que impediu os centauros supersticiosos de saqueá-lo.",al={"por que a pantera tem o dispositivo","como a pantera conseguiu"}},{q="Quem quer o Dispositivo Hipercapacitador de volta?",a="Wizlo Bearingshiner, o único sobrevivente da caravana saqueada, busca seu retorno. Ele se refugiou no Posto Confinalvo, um acampamento Tauren no noroeste de Mil Agulhas.",al={"quem precisa do dispositivo","dispositivo do wizlo"}},{q="Por que os centauros não o roubaram?",a="Os centauros saquearam toda a caravana, mas estavam apavorados com a pantera feroz dentro da gaiola. Eles deixaram a fera e sua coleira de metal completamente intocadas em meio às ruínas.",al={"por que os centauros não pegaram","centauros e pantera"}}},fx={["240fe489"]={q="De onde vem o Dispositivo Hipercapacitador e quem o fez?",a="O dispositivo estava em posse do engenheiro goblin Wizlo Bearingshiner, que viajava com uma caravana por Mil Agulhas antes que centauros os emboscassem. Embora Wizlo o chame de sua engenhoca valiosa, seu inventor preciso permanece um mistério — até Wizlo admite que não entende completamente o que a curiosa máquina realmente faz.",al={"quem fez o dispositivo hipercapacitador","origem dispositivo hipercapacitador","onde wizlo conseguiu o hipercapacitador"}}},fp="20,178,25.378.0,21.227.0,33.172.0,50.235.0,40.175.0,32.147.0"}
P.entries["item:ignition-key"] = {n="Chave de Ignição",s="A Chave de Ignição é uma chave de controle essencial portada pelo Supervisor Lugwizzle na operação de perfuração da Empreendimentos S.A. no Charco de Lodo. Ela é necessária para destravar a coluna de direção e ativar os controles de um triturador avançado da Empreendimentos S.A.",h="A Chave de Ignição é uma chave de controle essencial portada pelo Supervisor Lugwizzle na operação de...",kw={"chave de ignição","triturador","charco de lodo","cobogó","supervisor lugwizzle","empreendimentos s.a.","wizzlecrank"},ang={["profession:Engineering"]="A chave destrava um triturador que conta com mecanismos de controle incrivelmente avançados, superando os projetos típicos de goblins tanto na regulação de velocidade quanto na articulação precisa dos braços."},sec={{t="Uma Peça Que Falta na Espionagem",b="Quando Cobogó de Vila Catraca enviou um agente para roubar um triturador patenteado da Empreendimentos S.A. no Charco de Lodo, as coisas não saíram como o planejado. O piloto infiltrado, Wizzlecrank, conseguiu entrar na cabine da máquina apenas para descobrir que sua coluna de movimento estava totalmente travada. Para evitar que os capatazes desconfiassem, ele fingiu problemas mecânicos enquanto aguardava um aventureiro para recuperar a necessária Chave de Ignição. A chave permanece guardada a sete chaves pelo Supervisor Lugwizzle no topo da torre de perfuração central, controlando o acesso aos mecanismos modernos de braço, velocidade e rotação da máquina."}},faq={{q="Onde a Chave de Ignição pode ser encontrada?",a="A chave fica em posse do Supervisor Lugwizzle, que supervisiona os trabalhos de perfuração a partir da sala de controle no topo da torre de perfuração no Charco de Lodo.",al={"localização da chave de ignição","quem concede a chave de ignição","como obter a chave de ignição"}},{q="Por que Wizzlecrank precisa desta chave específica?",a="Ao contrário de maquinários de engenharia mais simples, este triturador avançado da Empreendimentos S.A. possui uma coluna de movimento travada. Sem a devida chave de ignição, o piloto não consegue regular a rotação, velocidade, estabilidade ou os controles dos braços para manobrá-lo e fugir.",al={"por que precisa da chave","o que a chave faz","propósito da chave do triturador"}},{q="Quem quer roubar o triturador?",a="Cobogó, um engenheiro gnomo situado em Vila Catraca, organizou a operação para pôr as mãos nos projetos superiores de engenharia da Empreendimentos S.A.",al={"quem enviou wizzlecrank","por que roubar o triturador","triturador de vila catraca"}},{q="O que acontece assim que a chave é entregue?",a="Assim que a chave destrava a coluna de movimento, Wizzlecrank liga o motor do triturador e precisa fazer uma fuga desesperada por entre os trabalhadores hostis do Charco de Lodo para escapar em direção a Vila Catraca.",al={"após entregar a chave","a fuga","o que vem depois"}}},fx={["762c90b7"]={q="O que é a Chave de Ignição?",a="A Chave de Ignição é uma chave operacional usada para destravar a coluna de movimento de um triturador da Empreendimentos S.A. no Charco de Lodo. Sem ela, os controles da pesada máquina de extração de madeira permanecem bloqueados, deixando o piloto incapaz de manobrar ou dirigir.",al={"o que é a chave de ignição","uso da chave de ignição","chave de triturador"}},["8801ec8f"]={q="De onde vem a Chave de Ignição?",a="A chave pertence às operações de perfuração e extração de madeira da Empreendimentos S.A. no Charco de Lodo. Ela está sob a posse do Supervisor Lugwizzle, que supervisiona o local da sala de controle no topo da torre de petróleo central.",al={"quem fez a chave de ignição","origem da chave de ignição","de onde veio a chave"}}},fp="12,203,28.502.0,36.136.0,44.189.0,30.124.0,39.169.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Tomo de Ilkrud Magthrull",s="O Tomo de Ilkrud Magthrull é um grimório recuperado de um perigoso bruxo orc que reside nas profundezas corrompidas de Vale Gris. Levado a Dinis, o Purificador, seu conteúdo repugnante revela as amplas maquinações sombrias em torno dos cultistas que operam a partir de A Torre de Althalaxx.",h="O Tomo de Ilkrud Magthrull é um grimório recuperado de um perigoso bruxo orc que reside nas profundezas...",kw={"vale gris","dinis, o purificador","santuário cicatriz de fogo","ilkrud magthrull","entreposto de maestra","tomo","torre de althalaxx","bruxo"},ang={["class:Paladin"]="Recuperar o tomo ajuda o Irmão Dinis, um companheiro guerreiro da Luz Sagrada que se mantém vigilante contra a sombra e a corrupção na vastidão indômita de Vale Gris.",["class:Warlock"]="O grimório de Magthrull é um valioso registro de pactos sombrios, detalhando a subjugação de emissários do caos e súcubos no corrompido Santuário Cicatriz de Fogo."},sec={{t="Um Grimório de Corrupção",b="Ilkrud Magthrull é um formidável bruxo orc entrincheirado no Santuário Cicatriz de Fogo, no sudoeste de Vale Gris, um local envenenado pela persistente influência demoníaca. Cercado por lacaios evocados, Magthrull registrou seus rituais vis e comunicações sombrias dentro deste tomo pessoal. Embora o paladino da Aurora Argêntea, Dinis, o Purificador, soubesse há muito tempo da presença do bruxo, as conexões descobertas entre Magthrull e os cultistas sombrios reunidos em A Torre de Althalaxx tornaram a recuperação do livro uma prioridade urgente."},{t="Desvendando o culto",b="Ao reivindicar o tomo das mãos do falecido Magthrull, ele é entregue a Dinis no Entreposto de Maestra. Dinis procura decifrar os escritos do bruxo para compreender a rede que coordena as atividades demoníacas além das fronteiras de Costa Negra e Vale Gris. O texto fornece informações cruciais sobre os conspiradores sombrios que manipulam os cordéis por trás da corrupção que se enraíza no norte de Kalimdor."}},faq={{q="Quem é o dono deste tomo?",a="O livro pertence a Ilkrud Magthrull, um poderoso bruxo orc que se estabeleceu entre as ruínas demoníacas do Santuário Cicatriz de Fogo, no sudoeste de Vale Gris.",al={"quem é ilkrud magthrull","quem escreveu o tomo","ilkrud magthrull"}},{q="Onde o tomo é encontrado?",a="Ele é recuperado diretamente do próprio Ilkrud Magthrull no Santuário Cicatriz de Fogo, localizado ao sul do Altar de Aessina, em Vale Gris.",al={"localização do tomo","como obter o tomo","onde encontrar ilkrud"}},{q="Por que Dinis, o Purificador quer o livro?",a="Dinis busca estudar os escritos de Magthrull para desvendar os laços sombrios que conectam adoradores de demônios locais aos cultistas que habitam A Torre de Althalaxx.",al={"por que dinis quer o tomo","o que está no tomo","propósito do livro de dinis"}},{q="O que acontece depois que o tomo é recuperado?",a="Dinis examina o texto no Entreposto de Maestra para decifrar as comunicações demoníacas de Magthrull e determinar o próximo passo para desmantelar a rede do culto.",al={"entregar tomo","o que dinis faz com o livro"}}},fx={["5352c240"]={q="De onde vem o Tomo de Ilkrud Magthrull e quem o fez?",a="O livro contém os escritos pessoais e as pesquisas sombrias de Ilkrud Magthrull, um poderoso bruxo orc que vivia em meio à corrupção demoníaca do Santuário Cicatriz de Fogo, no sudoeste de Vale Gris. Escrito pelo próprio bruxo, o volume compila seus feitiços sombrios e anotações, mantidos à mão até sua queda.",al={"quem escreveu o tomo de ilkrud magthrull","origem do tomo de ilkrud","de onde veio o tomo"}}},fp="23,159,24.434.0,19.342.1,19.142.0,24.109.0,44.139.0,41.138.0"}
P.entries["item:incantations-from-the-nether"] = {n="Encantamentos do Éter",s="Encantamentos do Éter é um grimório de magia demoníaca mantido pelos cultistas da Searing Blade que espreitam sob Orgrimmar. Sylvana Correventos e seu tenente lorde do medo, Varimatras, buscam reivindicar o tomo para utilizar seu conhecimento vil a favor dos Renegados.",h="Encantamentos do Éter é um grimório de magia demoníaca mantido pelos cultistas da Searing Blade que espreitam...",kw={"encantamentos do éter","cavernas ígneas","searing blade","shadow council","feitiços da sombra","sylvanas","o poder para destruir","varimatras"},ang={["class:Warlock"]="Tomos extraídos diretamente do Éter contêm potente magia vil que qualquer praticante ambicioso das artes sombrias cobiçaria.",["race:Undead"]="Recuperar este livro ajuda diretamente o círculo íntimo da Dama Sombria em Cidade Baixa, reunindo o conhecimento sombrio necessário para travar guerra contra o Flagelo."},sec={{t="Dons da Legião",b="Sob as ruas de pedra vermelha de Orgrimmar, a Searing Blade — uma seita subterrânea ligada ao Shadow Council — opera nos túneis ardentes das Cavernas Ígneas. Entre seus tesouros mais sombrios está Encantamentos do Éter, um livro de feitiços repleto de ritos demoníacos concedidos por agentes da Legião Ardente. Enquanto os cultistas usam seus vis segredos para tramar traição na capital órquica, a notícia do texto viajou para muito além do mar até os aposentos reais de Cidade Baixa."},{t="Ambição dos Renegados",b="Para a Senhora Sylvana Correventos e o lorde do medo Varimatras, relíquias vis tão poderosas são desperdiçadas em cultistas com o que consideram uma visão inferior. Varimatras envia aventureiros leais da Horda às profundezas das Cavernas Ígneas para recuperar Encantamentos do Éter junto com seu volume irmão, Feitiços da Sombra. A Dama Sombria pretende dobrar os poderes forjados no éter do livro em direção à sua cruzada derradeira: destruir o Lich King e levar retribuição ao Flagelo."}},faq={{q="Onde o livro Encantamentos do Éter é encontrado?",a="O livro é carregado pelos cultistas e bruxos da Searing Blade que espreitam nas Cavernas Ígneas, a rede de cavernas vulcânicas diretamente abaixo da cidade de Orgrimmar.",al={"onde conseguir encantamentos do éter","quem saqueia encantamentos do éter","localização de encantamentos do éter"}},{q="Quem quer este livro e por quê?",a="O lorde do medo Varimatras e a Grande Dama Sylvana Correventos buscam o livro. Eles acreditam que dons demoníacos como esses são desperdiçados nos cultistas insignificantes da Searing Blade e desejam usar sua magia sombria contra seu inimigo declarado, o Lich King.",al={"quem precisa de encantamentos do éter","por que sylvanas quer este livro","missão de livro de varimatras"}},{q="O que é a Searing Blade?",a="A Searing Blade é um conciliábulo secreto de bruxos e cultistas que opera sob Orgrimmar, aliado ao Shadow Council. Eles servem à Legião Ardente e trabalham nas sombras para minar a nova Horda de Thrall.",al={"história da searing blade","quem são a searing blade"}},{q="Qual outro livro faz par com este?",a="Varimatras exige dois volumes: Encantamentos do Éter e um segundo grimório chamado Feitiços da Sombra. Ambos devem ser arrancados dos cultistas nas Cavernas Ígneas para completar sua missão.",al={"outro livro para varimatras","poder para destruir livros"}}},fx={e0d58fa2={q="O que são Encantamentos do Éter?",a="Encantamentos do Éter é um grimório sombrio contendo feitiçaria vil presenteada pela Legião Ardente. Ele caiu na posse da Lâmina Ardente, um culto oculto do Conselho das Sombras que opera nas profundezas dos abismos ígneos abaixo de Orgrimmar. Ao lado de seu tomo irmão, Feitiços da Sombra, o livro contém rituais demoníacos potentes que bruxos cultistas estudam para controlar os poderes do Éter.",al={"o que são os encantamentos do éter","livro encantamentos do éter","que tipo de livro é encantamentos do éter"}}},fp="28,178,19.393.0,17.383.1,53.136.0,28.188.0,26.215.0,40.164.0"}
P.entries["item:incendia-agave"] = {n="Agave Incendia",s="A Agave Incendia é uma planta aquática rara e pontiaguda, nativa da Boiling Pool sob o Pináculo da Nuvem Negra, em Mil Agulhas. Quando encantada por um xamã habilidoso, suas propriedades únicas permitem que ela acenda o fogo sagrado da vida.",h="A Agave Incendia é uma planta aquática rara e pontiaguda, nativa da Boiling Pool sob o Pináculo da Nuvem...",kw={"arikara","boiling pool","pináculo da nuvem negra","agave incendia","magatha temível totem","fogo sagrado","mil agulhas"},ang={["class:Shaman"]="A agave exige a manipulação elemental xamânica em seu estado bruto para se transformar de uma suculenta aquática em um pó potente o bastante para acender chamas rituais sagradas.",["profession:Herbalism"]="Os herboristas acharão seu sentido de rastreamento indispensável para localizar os aglomerados pontiagudos de Agave Incendia escondidos ao longo do fundo turvo da Boiling Pool."},sec={{t="Uma Erva Rara do Deserto",b="Crescendo sob e ao redor das águas da Boiling Pool em Mil Agulhas, a Agave Incendia viceja diretamente à sombra do Pináculo da Nuvem Negra. Protegida naturalmente por elementais do vapor errantes, a planta é difícil de colher e escassa por toda Kalimdor. Apesar de crescer submersa na água, ela contém elementos naturais potentes que se prestam diretamente a rituais de chamas."},{t="O Fogo Sagrado",b="Os ritualistas taurens sabem que o dormente fogo sagrado da vida não pode ser aceso apenas por faíscas mundanas. A Anciã Magatha Temível Totem, no Platô dos Anciãos em Penhasco do Trovão, possui o conhecimento xamânico necessário para encantar feixes colhidos de Agave Incendia e transformá-los em um pó místico. Uma vez preparado, este pó acende o braseiro cerimonial necessário para invocar a vingativa serpente alada Arikara."}},faq={{q="Onde a Agave Incendia cresce?",a="A Agave Incendia cresce dentro e ao redor do lago na Boiling Pool, situada sob o Pináculo da Nuvem Negra, no norte de Mil Agulhas. Grande parte dela pode ser encontrada submersa na água ao longo do leito do lago.",al={"onde encontrar agave","localização agave incendia","onde fica a agave"}},{q="Para que serve a Agave Incendia?",a="Dez feixes da agave são colhidos para produzir um pó ritualístico. Uma vez encantado por Magatha Temível Totem em Penhasco do Trovão, o pó é usado para acender o fogo sagrado da vida e invocar a serpente Arikara.",al={"para que serve agave incendia","por que coletar agave","o que a agave faz"}},{q="Quem pode encantar a Agave Incendia?",a="Magatha Temível Totem, uma influente xamã situada no Platô dos Anciãos em Penhasco do Trovão, detém o conhecimento ritualístico para infundir magia xamânica no material vegetal bruto.",al={"quem encanta agave","magatha agave","quem transforma agave em po"}},{q="Quais ameaças cercam a Agave Incendia?",a="As águas e margens da Boiling Pool são percorridas por elementais do vapor hostis, que são excepcionalmente resistentes a feitiços de fogo e gelo.",al={"perigos da agave","o que protege a agave","perigos de boiling pool"}}},fx={d4005c78={q="O que é Agave Incendia?",a="Agave Incendia é uma erva excepcionalmente rara e espinhosa encontrada prosperando apenas ao redor e dentro das águas fumegantes da Piscina Fervente em Mil Agulhas. Apesar de crescer nas profundezas do lago, ela abriga propriedades latentes ígneas potentes, tornando-a um componente essencial para rituais que exigem poder elemental, uma vez refinada corretamente por um xamã habilidoso.",al={"o que é a agave incendia","planta agave incendia","que tipo de planta é a agave incendia"}}},fp="14,136,18.272.0,15.238.1,31.165.0,32.172.0,35.131.0,41.131.0"}
P.entries["item:incendia-powder"] = {n="Pó de Incendia",s="O Pó de Incendia é um catalisador ritualístico encantado refinado para acender chamas sagradas. Transportado por emissários da Horda até Mil Agulhas, o pó é especificamente tratado com encantamentos xamânicos para invocar a fera espiritual adormecida Arikara no topo do Pináculo da Nuvem Negra.",h="O Pó de Incendia é um catalisador ritualístico encantado refinado para acender chamas sagradas.",kw={"arikara","pináculo da nuvem negra","pó de incendia","motega firemane","sacred fire da vida","mil agulhas","posto confinalvo"},ang={["class:Shaman"]="O pó demonstra como a chama elemental e a proteção espiritual podem ser combinadas para despertar entidades ancestrais adormecidas.",["race:Tauren"]="Usar pós ritualísticos para acender fogueiras fúnebres reflete o equilíbrio delicado entre reverenciar tradições sagradas e defender a liderança das tribos."},sec={{t="Uma Faísca de Invocação",b="O Pó de Incendia não é um explosivo mundano nem um pó de clarão mundano; é uma substância purificada e ritualística cuidadosamente imbuída de magia xamânica. Encantada e confiada a viajantes por Magatha Temível Totem no Platô dos Anciãos do Penhasco do Trovão, a mistura foi criada para reagir exclusivamente com o dormente Sacred Fire da vida no topo dos pináculos isolados do Pináculo da Nuvem Negra. Uma vez espalhada sobre o braseiro consagrado onde os mortos descansam, sua proteção alquímica e espiritual invoca a vingativa serpente alada Arikara."},{t="Mau Agouro",b="Os ritos que determinam a criação e o uso do Pó de Incendia originam-se de interpretações compartilhadas pela anciã xamã Magatha Temível Totem. Acreditando que tradições inconstantes e mudanças nos costumes dos taurens haviam provocado espíritos ancestrais a caçar o Grande Chefe Caerne Casco Sangrento, o pó foi encantado para forçar a aparição a se revelar para que pudesse ser destruída. Embora tenha êxito em invocar a feroz serpente, o confronto violento deixa perguntas inquietantes sobre por que tal fera foi verdadeiramente incitada."}},faq={{q="Para que serve o Pó de Incendia?",a="O Pó de Incendia é um pó encantado lançado no Sacred Fire da vida no topo do Pináculo da Nuvem Negra, em Mil Agulhas. Acender a chama com esta mistura invoca o vingativo espírito serpente Arikara.",al={"propósito do pó de incendia","por que preciso de pó de incendia","o que o pó de incendia faz"}},{q="Quem preparou o encantamento no pó?",a="Magatha Temível Totem encantou a Agave Incendia colhida para transformá-la no pó refinado no Platô dos Anciãos, no Penhasco do Trovão, após Motega Firemane do Posto Confinalvo enviar notícias de Arikara.",al={"quem fez o pó de incendia","quem encantou o pó de incendia"}},{q="Onde o pó precisa ser usado?",a="Ele deve ser espalhado na pira do Sacred Fire em um pináculo solitário de sepultamento no Pináculo da Nuvem Negra, bem acima dos cânions de sal de Mil Agulhas.",al={"localização do pó de incendia","onde jogar o pó de incendia","onde usar o pó de incendia"}},{q="Por que era necessário invocar Arikara?",a="Magatha Temível Totem teme que mudanças nas tradições taurens tenham enfurecido Arikara e que a serpente possa estar perseguindo Caerne Casco Sangrento. Ela pede que Arikara seja invocada e abatida antes que qualquer mal aconteça a Caerne.",al={"por que invocar arikara","por que lutar contra arikara"}}},fx={["53c7ed7b"]={q="O que é o Pó de Incendia?",a="O Pó de Incendia é um reagente refinado e purificado, imerso em magia ritual. Quando espalhado sobre o fogo sagrado da vida no topo do Pináculo da Nuvem Negra em Mil Agulhas, seu encantamento entrelaçado atua como um farol que atrai Arikara, o espírito vingativo da serpente do vento.",al={"o que é o pó de incendia","história do pó de incendia","o que é o pó"}}},fp="15,164,20.287.0,15.324.1,33.156.0,43.164.0,38.153.0,36.192.0"}
P.entries["item:insane-scribbles"] = {n="Rabiscos Malucos",s="Arrancados do desconcertante Twilight Tome, estes Rabiscos Malucos são um fragmento de literatura sombria carregado por cultistas em Costa Negra. Apenas olhar para o texto que dança e para os arabescos distorcidos já induz tontura severa e desgaste mental. Os antigos protetores da floresta estudam tais fragmentos para decifrar os motivos sinistros do Twilight's Hammer.",h="Arrancados do desconcertante Twilight Tome, estes Rabiscos Malucos são um fragmento de literatura sombria...",kw={"costa negra","rabiscos malucos","loucura","old gods","onu","twilight tome","twilight's hammer"},ang={["class:Priest"]="Sacerdotes sensíveis a ataques mentais e energias tocadas pelo Caos reconhecerão a escrita retorcida como uma manifestação perigosa de loucura, em oposição direta à clareza da Luz.",["race:NightElf"]="Para os elfos noturnos, relíquias do Twilight's Hammer representam uma ameaça corruptora à paz ancestral e às terras sagradas de Costa Negra."},sec={{t="Um Manuscrito Enlouquecedor",b="Fixar o olhar sobre as páginas do Twilight Tome se mostra profundamente perigoso para a sanidade mortal. A escrita se contorce pelo pergaminho, enquanto arabescos graciosos se transformam diante dos olhos do leitor em imagens grotescas e perturbadoras. Arrancar mesmo que uma única folha — estes Rabiscos Malucos — é uma provação que deixa quem a carrega zonzo e desorientado. Apesar da incoerência caótica da escrita, o pergaminho vibra com uma magia primordial e profundamente ancestral, ligada diretamente a poderes sombrios há muito sepultados sob Azeroth."},{t="Pistas para os Ancientes",b="Levados a Onu, o venerável anciente que vela pelo Bosque dos Ancientes, os rabiscos oferecem um vislumbre das invasões que assolam Costa Negra. Onu reconhece a energia caótica impregnada no pergaminho como a obra inconfundível dos Old Gods. Para os defensores de Kalimdor, juntar as partes desses rabiscos é um passo crucial para descobrir com exatidão por que o Twilight's Hammer se reuniu ao longo das praias encobertas de névoa."}},faq={{q="O que acontece se você tentar ler estes rabiscos?",a="O texto desafia qualquer tradução simples. Apenas olhar para o pergaminho faz as letras oscilarem e os desenhos ao redor se transformarem em formas aterrorizantes, induzindo tontura repentina e exaustão mental em qualquer um que tente decifrá-los.",al={"ler rabiscos malucos","o que diz o texto","é possível ler os rabiscos"}},{q="De onde estes rabiscos foram arrancados?",a="Eles foram arrancados do Twilight Tome, um grimório vil guardado pelos cultistas do Twilight's Hammer que agem em Costa Negra.",al={"de onde vêm os rabiscos","origem do twilight tome"}},{q="Quem consegue entender ou estudar os rabiscos?",a="O Anciente da Tradição, Onu, examina o pergaminho recuperado. Recorrendo a séculos de conhecimento, Onu pressente a magia ancestral e primordial que prende a tinta e tenta determinar o propósito do culto na região.",al={"quem quer os rabiscos","rabiscos para onu"}},{q="Que tipo de poder irradia do pergaminho?",a="O pergaminho pulsa com uma magia caótica e primordial ligada aos Old Gods, refletindo as divindades sombrias adoradas pelo Twilight's Hammer.",al={"que magia há nos rabiscos","tipo de magia"}}},fx={["12486380"]={q="O que são os Rabiscos Malucos?",a="Eles são uma única página enlouquecedora arrancada do texto sombrio conhecido como o Tomo do Crepúsculo. A escrita nela nada, dança e se retorce em formas grotescas diante dos seus olhos, irradiando uma aura mágica caótica e primal que ameaça sobrecarregar seus sentidos se você olhar por muito tempo.",al={"o que são os rabiscos malucos","história dos rabiscos malucos","o que é este pergaminho"}},b40c7e7e={q="Por que Onu quer os Rabiscos Malucos?",a="O antigo Onu sente o toque caótico dos Deuses Antigos entrelaçado no pergaminho. Ele busca estudar esses escritos recuperados na esperança de decifrar o que o culto secreto do Martelo do Crepúsculo está tramando dentro das florestas e costas de Costa Negra.",al={"por que onu quer os rabiscos malucos","quem quer os rabiscos","por que levar rabiscos para onu"}}},fp="16,246,22.397.0,22.356.1,48.213.0,37.122.0,42.200.0,47.123.0"}
P.entries["item:inscribed-bark"] = {n="Casca de Árvore Inscrita",s="A Casca de Árvore Inscrita é um pergaminho vivo confiado pela antiga Árvore Oráculo para levar notícias sobre o estado de Teldrassil ao Arquidruida Fandral Guenelmo. Ela serve como um relatório oficial sobre os galhos da Árvore do Mundo e as ameaças persistentes que assolam seus bosques.",h="A Casca de Árvore Inscrita é um pergaminho vivo confiado pela antiga Árvore Oráculo para levar notícias sobre...",kw={"círculo cenariano","darnassus","fandral guenelmo","casca de árvore inscrita","árvore oráculo","teldrassil"},ang={["class:Druid"]="Os druidas reconhecem esta madeira inscrita como um despacho urgente de um aliado ancestral, destacando o equilíbrio delicado e as aflições contínuas que assolam a jovem Árvore do Mundo.",["race:NightElf"]="Para os Kaldorei, mensagens transportadas na casca de árvores antigas representam o elo sagrado entre a natureza e seus guardiões, unindo os bosques selvagens e os terraços de mármore de Darnassus."},sec={{t="Uma Mensagem do Oráculo",b="Talhada da madeira sagrada da Árvore Oráculo, esta casca de árvore inscrita atua como um comunicado direto entre o antigo guardião e a liderança do Círculo Cenariano em Darnassus. Depois que aventureiros contêm o avanço das harpias nas clareiras, a Árvore Oráculo lhes confia este emblema, relutante em arriscar mensageiros comuns pelos caminhos corrompidos dos galhos. A mensagem inscrita informa o Arquidruida Fandral Guenelmo tanto sobre as vitórias recentes quanto sobre a praga mais profunda e inquietante que continua a assolar Teldrassil."}},faq={{q="O que é a Casca de Árvore Inscrita?",a="É um pedaço de casca inscrito pela Árvore Oráculo contendo um relatório de situação sobre a saúde e os perigos dos galhos, destinado ao Arquidruida Fandral Guenelmo em Darnassus.",al={"o que é casca de árvore inscrita","casca de árvore oráculo","objetivo casca de árvore inscrita"}},{q="Quem envia esta mensagem e por quê?",a="A Árvore Oráculo a concede aos aventureiros após eles expulsarem as harpias de seus ninhos. Tendo se tornado cauteloso em relação a enviar mensageiros comuns pelas trilhas ameaçadas da floresta, o ancião confia em um viajante comprovado para entregar seu relatório.",al={"quem escreveu casca de árvore inscrita","quem dá casca de árvore inscrita","mensageiro árvore oráculo"}},{q="Como o Arquidruida Fandral Guenelmo reage à mensagem?",a="Fandral reconhece o alívio obtido com a eliminação das harpias, mas observa com frustração que problemas mais profundos persistem. O relatório reforça suas ansiedades latentes sobre se seu trabalho em Teldrassil algum dia realmente restaurará a imortalidade perdida dos elfos noturnos.",al={"reação fandral casca","o que fandral diz sobre casca"}}},fp="14,166,25.352.0,23.152.0,31.202.0,58.213.1"}
P.entries["item:insect-analysis-report"] = {n="Relatório de Análise de Insetos",s="O Relatório de Análise de Insetos traz descobertas urgentes sobre uma ameaça que se espalha por Tanaris. O Topógrafo Sênior Secamolha faz uma cópia para que o alerta chegue a outras pessoas.",h="O Relatório de Análise de Insetos traz descobertas urgentes sobre uma ameaça que se espalha por Tanaris.",kw={"secamolha","geringontzan","relatório de análise de insetos","insect part analysis","almofarrista","silithid","tanaris","zilzibin tamborleiro"},ang={["faction:Alliance"]="O alerta do relatório diz respeito aos silithid, que Zilzibin Tamborleiro identifica como uma ameaça tanto à Aliança quanto à Horda.",["faction:Horde"]="O relatório pretende alertar sua facção sobre os silithid, uma ameaça que, segundo Zilzibin Tamborleiro, aflige tanto a Horda quanto a Aliança."},sec={{t="Um alerta de Tanaris",b="Em Geringontzan, o Topógrafo Sênior Secamolha pede que o relatório seja amplamente compartilhado. O Alquimista Almofarrista acredita que todos que sabem ler devem conhecer o perigo. Secamolha concorda em fazer uma cópia para você levar à sua facção."},{t="O estudioso no Drag",b="Em Orgrimmar, Zilzibin Tamborleiro estuda as formas de vida e a história de Azeroth. Ele reconhece as criaturas descritas no relatório como silithid e alerta que elas podem consumir rapidamente o deserto de Tanaris. Ele as chama de instrumentos de uma ameaça que aflige tanto a Horda quanto a Aliança."}},faq={{q="O que é o Relatório de Análise de Insetos?",a="O Relatório de Análise de Insetos descreve os silithid, uma grave ameaça que se espalha a partir de Tanaris.",al={"relatório de insetos","relatório de análise","o que há no relatório"}},{q="Quem escreveu o relatório?",a="O Topógrafo Sênior Secamolha envia o relatório para estudos adicionais e ampla distribuição.",al={"quem fez o relatório","relatório de secamolha","de onde veio o relatório"}},{q="Por que Secamolha faz uma cópia?",a="O Alquimista Almofarrista pede uma cópia para que o alerta seja divulgado entre os membros da sua facção.",al={"por que copiar o relatório","conseguir uma cópia","compartilhar o relatório"}},{q="Quem é Zilzibin Tamborleiro?",a="Zilzibin Tamborleiro é um estudioso troll em Orgrimmar que pesquisa as formas de vida e a história de Azeroth.",al={"quem é zil","história de zilzibin","estudioso troll"}},{q="Que criaturas o relatório descreve?",a="Zilzibin identifica as criaturas do relatório como silithid, que ameaçam Tanaris e tanto a Horda quanto a Aliança.",al={"quais insetos","relatório dos silithid","o que são os insetos"}}},fp="22,163,22.232.0,23.264.1,35.89.0,21.87.0,34.93.0,25.95.0,40.116.0"}
P.entries["item:intact-raptor-horn"] = {n="Chifre Intacto de Raptor",s="Um chifre intacto colhido dos raptores predadores que espreitam as savanas dos Sertões. Mantido em perfeitas condições, ele é cobiçado por um goblin empreendedor que busca lucrar com os rumores sobre a inteligência dos raptores.",h="Um chifre intacto colhido dos raptores predadores que espreitam as savanas dos Sertões.",kw={"chifre intacto","ishamuhale","cáliper porcatraca","chifres de raptor","vila catraca","bebidas inteligentes","sunscale scytheclaw","takk the leaper"},ang={["class:Hunter"]="Obter um chifre de troféu inteiro requer uma morte limpa, provando sua precisão contra alguns dos predadores mais ferozes que as savanas têm a oferecer.",["profession:Cooking"]="Enquanto Cáliper planeja pulverizar os chifres para infusões de vinho, os sobreviventes práticos sabem que as partes de raptores costumam ser mais adequadas para a fabricação de ferramentas do que para a culinária saborosa."},sec={{t="Um Ingrediente Questionável",b="Enquanto os caçadores comuns valorizam partes de raptores por couros, garras e troféus, chifres intactos são mais difíceis de encontrar em campo. Na cidade portuária de Vila Catraca, um excêntrico alquimista goblin chamado Cáliper Porcatraca formulou uma teoria mirabolante sobre a fauna local: como os raptores dos Sertões exibem uma astúcia superior à de seus semelhantes de outros lugares, ele suspeita que seu intelecto resida diretamente em seus chifres. Ao moer chifres inteiros e misturá-los em tônicos, Cáliper almeja engarrafar essa suposta genialidade em 'bebidas inteligentes' comerciais."},{t="Espreitando os Bandos",b="Chifres intactos não podem ser simplesmente arrancados de qualquer fera jovem. Para fornecer material viável para a infusão, os caçadores precisam extraí-los de predadores particularmente cruéis, como os Sunscale Scytheclaws que rondam as planícies do sul e as fronteiras ao norte perto de Vale Gris. Terrores lendários notáveis da savana, como Takk the Leaper e a esquiva Ishamuhale, também ostentam chifres resistentes o suficiente para resistir intactos ao combate da caçada."}},faq={{q="Quem quer esses chifres de raptor intactos?",a="Cáliper Porcatraca, um comerciante goblin e aspirante a cervejeiro estabelecido em Vila Catraca, está à procura deles. Ele acredita que chifres inteiros guardam o segredo para o seu próximo produto de enriquecimento rápido.",al={"quem precisa de chifres de raptor","comprador de chifres","quem compra chifre de raptor"}},{q="Por que os chifres precisam estar intactos?",a="Cáliper pretende moê-los até virarem um pó fino para ingestão. Chifres lascados ou quebrados são descartados durante a caçada ou considerados inúteis, sem a potência total que o goblin espera aproveitar em suas receitas.",al={"por que intacto","chifres despedaçados"}},{q="Quais raptores os possuem?",a="Eles são encontrados predominantemente em Sunscale Scytheclaws adultos que rondam os extremos norte e sul dos Sertões, bem como em raptores raros notórios como Ishamuhale e Takk the Leaper.",al={"onde caem chifres","quais raptores","quem saqueia chifre intacto"}},{q="Os chifres de raptor realmente deixam você mais inteligente?",a="Embora os raptores dos Sertões sejam conhecidos por uma astúcia e coordenação de bando incomuns, a ideia de que sua inteligência é armazenada em seus chifres — ou transferível por meio de uma bebida — é um plano goblin sem comprovação.",al={"bebidas inteligentes funcionam","raptores são inteligentes","inteligência de raptor"}}},fx={["41f89fc5"]={q="O que é um Chifre Intacto de Raptor?",a="Um Chifre Intacto de Raptor é um chifre craniano não danificado colhido dos raptores predadores que espreitam os Sertões. Esses chifres são valorizados por habitantes locais empreendedores que acreditam que sua condição impecável preserva a essência natural e a astúcia das feras.",al={"o que é chifre intacto de raptor","o que é chifre de raptor"}},b3ef4089={q="De onde vêm os chifres intactos de raptor?",a="Esses chifres crescem naturalmente nas cabeças dos raptores dos Sertões, notavelmente os garras-de-foice escama-do-sol, bem como feras notórias como Ishamuhale e Takk, o Saltador. Eles são troféus biológicos tirados diretamente de raptores abatidos por todas as savanas.",al={"de onde vêm os chifres de raptor","quem derruba chifre intacto de raptor"}}},fp="18,157,25.376.0,19.322.0,36.152.0,35.210.0,25.168.0,42.162.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Chave do Cofre do Intrépido",s="A Chave do Cofre do Intrépido é uma chave de ferro enferrujada, outrora guardada com zelo pelo Capitão Halyndor, comandante da condenada embarcação da Aliança, o Intrépido. Mesmo na morte-vida, o capitão a segura com firmeza, mantendo trancado o artefato amaldiçoado que levou sua tripulação à ruína na costa do Pantanal.",h="A Chave do Cofre do Intrépido é uma chave de ferro enferrujada, outrora guardada com zelo pelo Capitão...",kw={"capitão halyndor","tripulação amaldiçoada","glorin testaço","intrépido","naufrágio","cofre","the third fleet","pantanal"},ang={["class:Priest"]="A chave abre um artefato de energia necrótica vil, exigindo os ritos sagrados do sacerdote de Menethil, Glorin Testaço, para purificar e conceder descanso às almas da tripulação.",["faction:Alliance"]="A chave pertencia a um comandante da The Third Fleet da Aliança, cuja perda trágica na costa do Porto de Menethil continua sendo uma ferida aberta para os sobreviventes do porto."},sec={{t="O Segredo de um Capitão",b="Durante o naufrágio da The Third Fleet na costa tempestuosa do Pantanal, o navio de guerra Intrépido foi reduzido a ruínas, e sua tripulação transformada em espíritos amaldiçoados e inquietos. O Capitão Halyndor vigiava obsessivamente um item misterioso guardado dentro do pesado cofre da embarcação. Na morte, sua figura espectral continua a rondar o convés encharcado, recusando-se a abrir mão da chave enferrujada que destranca a carga mais profunda e sombria do porão."},{t="Quebrando o Elo",b="Arrancar a chave do Capitão Halyndor é a única maneira de abrir o cofre trancado do Intrépido e recuperar a relíquia amaldiçoada responsável por prender a tripulação ao seu tormento. Somente usando esta chave para recuperar o objeto é que ele poderá ser entregue ao sacerdote anão Glorin Testaço no Porto de Menethil para passar por purificação."}},faq={{q="Quem carrega a Chave do Cofre do Intrépido?",a="A chave está em posse do Capitão Halyndor, o comandante fantasmagórico que percorre o convés superior do naufrágio ao norte, na costa noroeste do Pantanal.",al={"quem tem a chave","saque da chave do intrépido","chave de halyndor"}},{q="O que a Chave do Cofre do Intrépido abre?",a="Ela destranca o Cofre Trancado do Intrépido, que repousa submerso no casco fraturado do navio naufragado abaixo do convés do capitão.",al={"o que ela abre","localização do cofre do intrépido","onde fica o baú"}},{q="Por que o cofre foi mantido trancado?",a="O Capitão Halyndor trancou um objeto sombrio e amaldiçoado dentro do baú para mantê-lo oculto e seguro e, depois que a frota afundou, seu mal persistente prendeu a tripulação à morte-vida.",al={"o que estava no baú","por que estava trancado"}},{q="Quem pode purificar o item amaldiçoado dentro do baú?",a="Glorin Testaço, um sacerdote anão residente no Porto de Menethil, possui o conhecimento sagrado necessário para purificar o artefato amaldiçoado assim que o baú for destrancado.",al={"quem purifica","baú de glorin testaço"}}},fx={b4277111={q="O que é a Chave do Cofre do Intrépido?",a="É uma chave de navio enferrujada mantida pelo Capitão Halyndor a bordo do navio naufragado Intrépido. Mesmo após a morte, o capitão amaldiçoado guarda a chave zelosamente, pois é o único meio de abrir o cofre reforçado do navio escondido dentro do casco estilhaçado.",al={"chave do cofre do intrépido","o que é a chave","chave do intrépido"}},["90ec2e74"]={q="Por que a Chave do Cofre do Intrépido é necessária?",a="A chave é necessária para abrir o cofre do Intrépido e recuperar a relíquia sombria trancada lá dentro. O Primeiro Oficial Simonez acredita que este artefato guardado causou a maldição horrível que prende Halyndor e sua tripulação aos destroços, e abrir o baú é o primeiro passo para quebrá-la.",al={"por que preciso da chave","por que pegar a chave","propósito da chave do intrépido"}}},fp="22,188,18.260.0,17.194.1,39.122.0,42.110.0,34.154.0,49.114.0"}
P.entries["item:invisibility-liquor"] = {n="Elixir de Invisibilidade",s="O Elixir de Invisibilidade é uma bebida potente, infundida alquimicamente e preparada com raras Crystal Kelp Fronds encontradas na Floresta de Elwynn. Projetado para tornar quem o bebe invisível por um breve período, ele serve como ponto central em um plano clandestino que permite a dois jovens amantes desafortunados contornarem a rivalidade de suas famílias.",h="O Elixir de Invisibilidade é uma bebida potente, infundida alquimicamente e preparada com raras Crystal Kelp...",kw={"crystal kelp","floresta de elwynn","elixir de invisibilidade","mabel madruga","rivalidade dos stonefield","a fuga","tomasino campedra"},ang={["class:Mage"]="Enquanto os arcanistas do Kirin Tor passam anos aperfeiçoando ilusões e feitiços de invisibilidade, os habitantes de Elwynn conseguem uma imitação rústica usando destilados fermentados e algas encharcadas.",["race:Human"]="A bebida evidencia os extremos absurdos da amarga rivalidade rural na Floresta de Elwynn entre os clãs Stonefield e Maclure."},sec={{t="Uma Poção para Amantes Desafortunados",b="A rivalidade contínua entre os Stonefield e os Maclure torna o contato pacífico entre suas famílias quase impossível. Quando o jovem Tomasino Campedra busca se encontrar com Mabel Madruga longe dos olhos vigilantes de seus parentes, o sigilo convencional não é suficiente. O Elixir de Invisibilidade oferece uma solução insólita: uma bebida alcoólica que distorce a visão ao redor de quem a ingere, concedendo furtividade suficiente para cruzar terras agrícolas disputadas sem ser detectado."},{t="Alquimia Pouco Ortodoxa de Elwynn",b="Preparada com Crystal Kelp Fronds colhidas em águas locais infestadas de murlocs, a mistura combina o preparo simples de aguardente clandestina com reagentes mágicos brutos. Embora ilícita e talvez perigosa de ingerir, a poção se mostra potente o bastante para fazer Mabel sumir da vista de todos no instante em que toca seus lábios, permitindo que ela fuja para a floresta para um encontro secreto."}},faq={{q="O que o Elixir de Invisibilidade faz?",a="É uma bebida alcoólica potente com propriedades mágicas que torna temporariamente quem a bebe completamente invisível.",al={"efeitos do elixir","bebida de invisibilidade","o que faz"}},{q="Quem usa o Elixir de Invisibilidade?",a="A bebida é levada a Mabel Madruga para que ela possa desaparecer da vista de sua família e fugir para encontrar seu amante, Tomasino Campedra, apesar da rivalidade entre suas famílias.",al={"quem bebe","elixir de mabel madruga"}},{q="Como a bebida é feita?",a="Ela é preparada usando Crystal Kelp Fronds colhidas nos leitos de rios e margens de lagos da Floresta de Elwynn, onde murlocs frequentemente acumulam as plantas mágicas.",al={"ingredientes do elixir","elixir de crystal kelp"}},{q="Os jogadores podem beber o Elixir de Invisibilidade?",a="Não. A poção é um item de missão especializado destinado estritamente para ser entregue a Mabel Madruga como parte de seu plano para fugir de sua família.",al={"posso beber","beber elixir de invisibilidade"}}},fx={["19edabb3"]={q="O que é o Elixir de Invisibilidade?",a="O Elixir de Invisibilidade é uma poção alquímica potente preparada na Floresta de Elwynn. Embora seja ostensivamente uma bebida alcoólica, ela carrega propriedades mágicas derivadas de frondes de alga-cristal, concedendo temporariamente a quem a bebe invisibilidade completa aos olhos mortais.",al={"o que é o elixir de invisibilidade","conhecimento sobre o elixir de invisibilidade","que tipo de bebida é o elixir de invisibilidade"}},f0e7bc08={q="Por que alguém quer o Elixir de Invisibilidade?",a="O elixir é procurado para resolver um romance proibido. Mabel Madruga e Tomasino Campedra estão presos em lados opostos da amarga disputa das famílias em Elwynn, e a poção permite que Mabel escape sem ser vista por seus parentes vigilantes para visitar seu amado.",al={"por que precisar do elixir de invisibilidade","quem quer o elixir de invisibilidade","por que querem o elixir"}}},fp="19,148,32.249.0,25.180.1,33.110.0,33.143.0,23.120.0,53.91.0"}
P.entries["item:iron-pike"] = {n="Pique Férreo",s="Piques Férreos são materiais de construção resistentes, enviados originalmente de Ventobravo para ajudar no conserto da ponte do Lago Plácido em Vila Plácida. O carregamento foi emboscado e saqueado por gnolls de Cristarrubra, deixando a vila sem suprimentos essenciais de reconstrução.",h="Piques Férreos são materiais de construção resistentes, enviados originalmente de Ventobravo para ajudar no...",kw={"a ponte do lago placido","encarregado oslow","pique férreo","rebite de ferro","vila plácida","gnolls de cristarrubra","montanhas cristarrubra"},ang={["faction:Alliance"]="Recuperar suprimentos de construção roubados de gnolls selvagens ajuda a proteger as travessias vitais de Vila Plácida, mantendo a fronteira leste de Ventobravo fortificada contra a agressão dos Rocha Negra.",["profession:Blacksmithing"]="Esses pesados piques estruturais demonstram a pressão exercida sobre os ferreiros locais, cujo suprimento inteiro de ferro bruto teve de ser desviado para armas de guerra."},sec={{t="Carga de Caravana Roubada",b="Quando Vila Plácida enfrentou ataques recentes dos orcs Rocha Negra, as reservas de metal da vila foram derretidas para forjar armaduras, lâminas e munições para defesa. Em resposta à escassez, os construtores locais solicitaram um carregamento de ferro para reabastecimento vindo de Ventobravo. Antes que os materiais pudessem chegar à vila, um bando de gnolls de Cristarrubra interceptou a caravana de transporte ao longo da estrada. Os gnolls arrastaram caixotes de piques férreos e rebites para o norte, em direção às colinas, paralisando reparos críticos na ponte do Lago Plácido."},{t="Reconstruindo a Estrutura",b="O Encarregado Oslow, responsável por supervisionar a reconstrução da ponte do Lago Plácido, conta com aventureiros para entrar em território gnoll e recuperar o material surrupiado. Sem esses pesados piques férreos para reforçar a estrutura de pedra e madeira, Vila Plácida permanece parcialmente isolada da estrada do norte e vulnerável a novas incursões."}},faq={{q="Por que os gnolls estão carregando piques de construção?",a="Os gnolls emboscaram uma caravana de suprimentos que viajava de Ventobravo para Vila Plácida. Eles se dispersaram pelas colinas de Cristarrubra com caixotes de ferragens de construção roubadas, incluindo piques férreos e rebites.",al={"por que gnolls tem piques ferreos","onde os gnolls conseguiram piques ferreos"}},{q="Quem precisa desses piques férreos em Vila Plácida?",a="O Encarregado Oslow precisa deles para reconstruir a ponte do Lago Plácido, que conecta Vila Plácida através do Lago Plácido. A vila não tem ferro sobressalente depois de derreter suas reservas locais para forjar armas e armaduras durante recentes ataques de orcs.",al={"quem quer pique ferreo","encarregado oslow pique ferreo"}},{q="Onde esses piques férreos podem ser recuperados?",a="Eles estão em posse dos gnolls de Cristarrubra acampados nas colinas e cumes ao norte de Vila Plácida.",al={"onde encontrar pique ferreo","localizacao de pique ferreo"}},{q="Por que Vila Plácida simplesmente não forjou seus próprios piques férreos?",a="Vila Plácida esgotou seu suprimento local de ferro lutando contra os orcs Rocha Negra, derretendo cada pedaço de metal para espadas, balas e equipamentos de proteção. Eles foram forçados a solicitar novo ferro estrutural a Ventobravo.",al={"por que vila placida pediu ferro","escassez de ferro em vila placida"}}},fx={c6b2b586={q="O que é um Pique Férreo?",a="Um Pique Férreo é uma estaca de construção de ferro pesado destinada a reforçar alvenaria e trabalhos em pedra. O Encarregado Oslow e sua equipe precisam desses espigões estruturais robustos para reparar e estabilizar a arruinada Ponte da Eterna Calma de Vila Plácida.",al={"o que é o pique férreo","o que são piques férreos","pique férreo montanhas cristarrubra"}}},fp="9,162,20.307.0,19.266.0,47.197.0,40.193.0,40.89.0,55.180.0"}
P.entries["item:iron-pommel"] = {n="Castão de Ferro",s="O Castão de Ferro é o fragmento final que faltava da Varinha de Dartol, uma varinha criada pelo mago Dartol, há muito falecido, e buscada pelos elfos noturnos de Astranaar para retardar os ataques dos furbolgs ao seu povo. Confiada aos druidas do Retiro de Dor'Danil para ser guardada, ela foi perdida quando seu santuário foi massacrado e invadido por limos.",h="O Castão de Ferro é o fragmento final que faltava da Varinha de Dartol, uma varinha criada pelo mago Dartol...",kw={"vale gris","varinha de dartol","dor'danil","castão de ferro","baú de oso","raene's cleansing","shael'dryn"},ang={["class:Druid"]="O castão serve como um memorial sombrio aos druidas caídos de Dor'Danil, cujo encargo sagrado terminou em massacre na borda da floresta.",["faction:Alliance"]="Recuperar o castão completa um estágio crítico para garantir a Varinha de Dartol, uma ferramenta essencial para defender Vale Gris contra a corrupção crescente."},sec={{t="O Fardo de um Círculo Destruído",b="A Varinha de Dartol foi dividida e espalhada por Vale Gris para proteger seu poder místico. O Castão de Ferro foi colocado sob os cuidados dos druidas elfos noturnos que viviam perto da estrada que serpenteia para o sul em direção aos Sertões. A tragédia atingiu o enclave isolado no Retiro de Dor'Danil quando o círculo foi massacrado, seu abrigo tranquilo caindo em silêncio arruinado. O castão desapareceu nas consequências, engolido pelos limos grotescos e borbulhantes que agora cambaleiam pela clareira profanada."},{t="Recuperado do Pântano",b="Com os druidas mortos, encontrar o castão exige vasculhar a cavidade contaminada ao sul do Posto Machadada. A relíquia permaneceu trancada dentro de um baú resistente. Aventureiros que cortam os limos corrompidos descobrem o baú engolido intacto dentro da massa ácida de um limo, garantindo finalmente a última peça necessária para a reconstrução da varinha."}},faq={{q="Para que serve o Castão de Ferro?",a="O Castão de Ferro serve como o componente final necessário para remontar a Varinha de Dartol. Levá-lo a Shael'dryn no poço lunar permite que ela conserte o artefato antigo para que possa ser usado para retardar os ataques dos furbolgs aos elfos noturnos de Vale Gris.",al={"objetivo do castão de ferro","por que preciso do castão de ferro","o que o castão de ferro faz"}},{q="Quem detinha originalmente o castão?",a="Ele foi confiado aos druidas elfos noturnos que viviam perto da estrada que segue em direção aos Sertões. Infelizmente, o círculo foi massacrado antes que a varinha pudesse ser reunida, deixando seu refúgio em ruínas.",al={"quem guardava o castão","quem tinha o castão de ferro","druidas de dor'danil"}},{q="Onde o castão é encontrado?",a="O castão está trancado dentro de um baú carregado dentro de um dos limos corrompidos que vagam pela cavidade contaminada a leste da estrada principal, ao sul do Posto Machadada e ao norte da fronteira dos Sertões.",al={"localização do castão de ferro","onde fica o castão de ferro","onde consigo o castão de ferro"}},{q="A quem devo entregar o castão?",a="O castão deve ser entregue a Shael'dryn, uma dríade que cuida do poço lunar a leste do Lago Íris, que possui o conhecimento ritual para reconstruir a Varinha de Dartol.",al={"entregar o castão de ferro","onde levar o castão de ferro","quem quer o castão"}}},fx={["9716c2ef"]={q="O que é o Castão de Ferro?",a="O Castão de Ferro é o componente final que falta para reconstruir o Bastão de Dartol, um bastão criado pelo mago há muito falecido Dartol. Antes de sua trágica queda, os druidas que residiam no Retiro de Dor'Danil foram encarregados de proteger esta peça de metal pesada. Perdido em meio à corrupção e violência que varreram seu santuário, o castão acabou trancado dentro de um baú antigo na natureza, esperando alguém capaz de recuperá-lo.",al={"o que é o castão de ferro","conhecimento sobre o castão de ferro","para que serve o castão para o bastão de dartol"}}},fp="11,302,23.366.0,23.246.1,33.213.0,30.169.0,26.199.0,29.136.0"}
P.entries["item:iron-rivet"] = {n="Rebite de Ferro",s="Rebites de Ferro são fixadores de construção resistentes fabricados em Ventobravo para ajudar a reconstruir as ruínas da Ponte do Lago Plácido em Vila Plácida. Após uma caravana de suprimentos ser emboscada e saqueada por gnolls das Montanhas Cristarrubra, esses pesados componentes de metal acabaram espalhados pelos acampamentos gnolls nas colinas do norte.",h="Rebites de Ferro são fixadores de construção resistentes fabricados em Ventobravo para ajudar a reconstruir...",kw={"ponte do lago plácido","encarregado oslow","pique férreo","rebite de ferro","vila plácida","gnolls das montanhas cristarrubra","montanhas cristarrubra"},ang={["faction:Alliance"]="Recuperar esses suprimentos roubados ajuda diretamente a infraestrutura local de Vila Plácida, ao mesmo tempo em que contêm a ousada ameaça gnoll que assola a cidade.",["profession:Blacksmithing"]="Esses fixadores de alta resistência exibem a forja padrão de Ventobravo, criados especificamente para ancorar grandes obras civis, como pontes de pedra e madeira."},sec={{t="Carga Roubada da Caravana",b="Quando Vila Plácida enfrentou repetidos ataques dos orcs Blackrock, o conselho da cidade foi forçado a derreter suas reservas de ferro estrutural para forjar com urgência armas, armaduras e munições. Assim que a crise imediata diminuiu, o Encarregado Oslow solicitou novos suprimentos de construção de Ventobravo para consertar a fraturada Ponte do Lago Plácido. No entanto, a caravana de suprimentos que transportava a remessa foi emboscada por gnolls locais das Montanhas Cristarrubra antes de chegar à cidade. As bestas de carga e as carroças foram arrastadas para as colinas ao norte do Lago Plácido, espalhando materiais de construção essenciais, como rebites de ferro e lanças, entre os bandos de gnolls."},{t="Consertando a Ponte",b="Sem esses pesados rebites de ferro, os reparos estruturais na Ponte do Lago Plácido não podem prosseguir com segurança. A estrutura de pedra e madeira sobre o lago requer fixadores de metal reforçados para suportar o peso de carroças e viajantes. Recuperar os rebites diretamente dos acampamentos gnolls é essencial para restaurar a ligação vital de Vila Plácida com os vales ocidentais e proteger o perímetro da cidade contra novas incursões."}},faq={{q="Para que servem os Rebites de Ferro?",a="Eles são fixadores estruturais pesados necessários para o Encarregado Oslow reparar a danificada Ponte do Lago Plácido em Vila Plácida, que perdeu seu ferro original durante os combates contra os orcs Blackrock.",al={"propósito do rebite de ferro","por que precisa de rebites de ferro","para que servem rebites de ferro"}},{q="Por que os gnolls têm esses rebites?",a="Uma caravana de suprimentos enviada de Ventobravo foi interceptada pelos gnolls das Montanhas Cristarrubra ao longo da estrada. Os saqueadores fugiram com a carga de construção, levando os rebites e lanças de ferro para seus acampamentos ao norte de Vila Plácida.",al={"por que gnolls têm rebites","como gnolls conseguiram rebites de ferro","quem roubou os rebites"}},{q="Por que Vila Plácida estava sem ferro para começo de conversa?",a="Durante uma invasão orc recente, os defensores de Vila Plácida tiveram que derreter todos os seus suprimentos estocados de ferro para fazer espadas, balas e armaduras a fim de sobreviver ao cerco.",al={"escassez de ferro em vila plácida","por que sem ferro em vila plácida"}},{q="Quem está procurando por esses rebites?",a="O Encarregado Oslow, o mestre de obras que supervisiona a restauração da Ponte do Lago Plácido nas margens de Vila Plácida.",al={"quem quer rebites de ferro","quem aceita rebites de ferro"}}},fx={["0d91405a"]={q="O que é um Rebite de Ferro?",a="Um Rebite de Ferro é um prendedor de metal resistente forjado para trabalhos de construção pesada no reino. Ventobravo enviou um carregamento desses rebites para Vila Plácida para ajudar na reconstrução da infraestrutura arruinada da cidade, particularmente a vital Ponte da Eterna Calma.",al={"o que é o rebite de ferro","o que são rebites de ferro","descrição do rebite de ferro"}},a8a8e120={q="De onde vêm esses Rebites de Ferro e quem os fez?",a="Esses rebites foram enviados de Ventobravo como parte de uma caravana de socorro carregando matérias-primas e bens de construção para as Montanhas Cristarrubra. Antes de chegar a Vila Plácida, a caravana foi emboscada e saqueada por gnolls das Montanhas Cristarrubra, espalhando os suprimentos de ferro por seus acampamentos nas encostas.",al={"de onde vêm os rebites de ferro","quem fez os rebites de ferro","origem do rebite de ferro"}}},fp="10,141,20.378.0,18.284.0,30.169.0,36.153.0,46.111.0,32.90.0"}
P.entries["item:iron-shaft"] = {n="Haste de Ferro",s="A Haste de Ferro é um segmento metálico de Dartol's Rod, uma relíquia que Teronis, amigo de Raene Correlobos, procurou na esperança de conter os ataques dos fúrbolgs a Vale Gris. Recuperada de um baú trancado perto da fronteira de Selva Maleva, ela serve como um componente crucial para restaurar a relíquia para os defensores de Vale Gris.",h="A Haste de Ferro é um segmento metálico de Dartol's Rod, uma relíquia que Teronis, amigo de Raene Correlobos...",kw={"vale gris","crazed ancient","dartol's rod","selva maleva","haste de ferro","raene's cleansing","shael'dryn","withered ancient","chave de madeira"},ang={["class:Druid"]="Remontar Dartol's Rod se relaciona intimamente com a tutela druídica, utilizando ferramentas esquecidas para curar terras feridas.",["race:NightElf"]="Recuperar a Haste de Ferro é um dever sombrio, pois exige abater amados arvorescentes da floresta que foram vítimas da praga demoníaca que emana de Selva Maleva."},sec={{t="Um pedaço de Dartol's Rod",b="Dartol's Rod foi uma criação de Dartol, e seus pedaços foram espalhados por Vale Gris; um deles foi até entregue aos druidas de Dor'Danil para custódia. A Haste de Ferro representa o núcleo metálico resistente do instrumento, guardado dentro de um baú trancado em uma clareira isolada perto da fronteira norte de Vale Gris, não muito longe do reino corrompido de Selva Maleva."},{t="A praga da floresta",b="Para obter a Haste de Ferro, é necessário recuperar sua chave dos arvorescentes locais que outrora cuidavam destas matas. Com a corrupção demoníaca avançando para o sul a partir de Selva Maleva, antigos guardiões como os Crazed Ancients e os Withered Ancients sucumbiram à loucura. A dríade Shael'dryn encarrega os viajantes de obter a haste para que a vara possa ser forjada novamente e a missão do falecido Teronis seja concluída."}},faq={{q="Para que serve a Haste de Ferro?",a="A Haste de Ferro é uma parte de Dartol's Rod, uma relíquia quebrada. Ela é coletada para que a dríade Shael'dryn possa ajudar a remontar a vara e concluir a tarefa de Teronis, que a procurava para conter os ataques dos fúrbolgs a Vale Gris.",al={"objetivo da haste de ferro","o que é esta haste","por que preciso da haste de ferro"}},{q="Onde a Haste de Ferro é encontrada?",a="Ela está trancada dentro de um baú localizado em uma clareira tranquila a oeste da estrada que leva a Selva Maleva, na parte norte de Vale Gris.",al={"localização da haste de ferro","encontrar haste de ferro","onde fica o baú"}},{q="Como você abre o baú que contém a haste?",a="O baú requer uma Chave de Madeira. Essa chave é carregada pelos arvorescentes corrompidos — os Crazed Ancients e os Withered Ancients — que vagam pelos bosques a nordeste do Refúgio Bosque Real.",al={"como abrir o baú","chave do baú","chave da haste de ferro"}},{q="Quem está procurando a Haste de Ferro?",a="Shael'dryn, uma dríade localizada em um poço lunar no centro de Vale Gris, orienta os aventureiros a reunir os pedaços de Dartol's Rod como parte do esforço para purificar a floresta.",al={"quem quer a haste de ferro","quem dá a missão da haste de ferro"}}},fx={ad78a81b={q="O que é a Haste de Ferro?",a="A Haste de Ferro é um segmento chave do Bastão de Dartol, uma relíquia criada por Dartol. As peças do bastão foram espalhadas por Vale Gris, e esta acabou trancada dentro de um baú escondido perto das fronteiras da Selva Maleva, com sua chave carregada pelos gigantes corrompidos das proximidades.",al={"o que é a haste de ferro","item haste de ferro","haste de ferro bastão de dartol"}},["45340e91"]={q="De onde vem a Haste de Ferro e quem a fez?",a="Ela foi forjada como parte de um bastão mágico criado por Dartol. As peças do bastão foram posteriormente espalhadas, e esta haste específica foi fixada em um baú gasto escondido em uma clareira perto da Selva Maleva, guardada indiretamente pelos gigantes corrompidos que possuem sua chave.",al={"quem fez a haste de ferro","origem da haste de ferro","haste de ferro de dartol"}},["3705c59d"]={q="Por que a Haste de Ferro é desejada?",a="Raene Correlobos e Shael'dryn buscam remontar o Bastão de Dartol, que Teronis acreditava que poderia retardar os ataques dos furbolgs aos elfos noturnos de Vale Gris. Reconstruir a relíquia exige reunir seus componentes perdidos, e esta haste de ferro resistente forma o cabo central e o núcleo necessário para manter a gema mágica e o castão do bastão unidos.",al={"por que querem a haste de ferro","por que coletar a haste de ferro","motivo da missão da haste de ferro"}}},fp="10,146,23.242.0,19.262.1,32.190.0,30.104.0,47.138.0,34.139.0"}
P.entries["item:ironband-s-progress-report"] = {n="Relatório de Progresso de Bandaferro",s="O Relatório de Progresso de Bandaferro é um despacho por escrito que detalha os problemas enfrentados no sítio de escavação do Prospector Bandaferro, no leste de Loch Modan. Ele traz tanto um relato da lentidão nas escavações devido a troggs agressivos quanto um apelo urgente por mais pólvora de detonação.",h="O Relatório de Progresso de Bandaferro é um despacho por escrito que detalha os problemas enfrentados no...",kw={"pólvora de detonação","liga dos exploradores","bandaferro","jern elmocorno","loch modan","prospector lançatroz","thelsamar","troggs"},ang={["profession:Mining"]="Mineradores entendem muito bem a necessidade de pólvora de detonação ao remover formações rochosas teimosas — e o perigo que surge quando suprimentos desaparecem em território trogg.",["race:Dwarf"]="Para mineradores e exploradores anões, este despacho representa a perigosa realidade de escavar sítios titânicos ancestrais no coração de Khaz Modan."},sec={{t="Um Apelo por Pólvora",b="A escavação do Prospector Bandaferro em Loch Modan sofre interrupções contínuas causadas por troggs locais. Para manter o projeto em andamento, Bandaferro compilou este relatório de progresso a fim de reiterar sua necessidade desesperada por pólvora de detonação. Levado primeiro a Jern Elmocorno em Thelsamar e depois encaminhado à Assembleia dos Exploradores em Altaforja, o relatório documenta as paralisações do local enquanto solicita munições pesadas. O despacho rapidamente levanta suspeitas entre a liderança da liga, já que uma quantidade farta de pólvora de detonação havia sido enviada a Bandaferro semanas antes, deixando os superiores intrigados sobre o paradeiro dos carregamentos anteriores."}},faq={{q="O que é o Relatório de Progresso de Bandaferro?",a="É uma atualização oficial de campo redigida pelo Prospector Bandaferro sobre a situação de seu sítio de escavação em Loch Modan, destacando especificamente a interferência causada por troggs e exigindo mais pólvora de detonação.",al={"relatório de progresso","relatório de bandaferro","o que é este relatório"}},{q="Quem recebe este relatório?",a="O relatório é entregue primeiro a Jern Elmocorno, o contato local da escavação em Thelsamar. Elmocorno então instrui o portador a levá-lo diretamente ao Prospector Lançatroz, no quartel-general da Liga dos Exploradores em Altaforja.",al={"quem recebe o relatório","para quem entrego o relatório","entregar relatório de progresso"}},{q="Por que Bandaferro precisa de mais pólvora de detonação?",a="Bandaferro afirma precisar da pólvora para ajudar em suas escavações arqueológicas, embora os constantes ataques de troggs nos arredores sugiram que ele também precise de explosivos para defesa. Curiosamente, tanto Elmocorno quanto Lançatroz acreditam ter enviado bastante pólvora de detonação para ele semanas atrás.",al={"por que pólvora de detonação","o que aconteceu com a pólvora","falta de pólvora"}},{q="Como o Prospector Lançatroz reage ao relatório?",a="Lançatroz fica furioso com o progresso lento e perplexo com o fato de Bandaferro não fazer menção alguma ao enorme carregamento de pólvora de detonação enviado anteriormente, questionando para onde essas munições desaparecidas podem ter ido.",al={"reação de lançatroz","lançatroz está bravo"}}},fx={["9e6c80e6"]={q="De onde vem o Relatório de Progresso de Bandaferro e quem o fez?",a="O documento é redigido pelo próprio Prospector Bandaferro em seu local de escavação no leste de Loch Modan. Supervisionando os árduos esforços de escavação em meio ao persistente assédio dos trogs, Bandaferro escreveu o relatório para fornecer atualizações formais sobre o ímpeto lento de sua operação e registrar oficialmente suas requisições de materiais em andamento.",al={"quem escreveu o relatório de progresso de bandaferro","quem fez o relatório de bandaferro","de onde vem o relatório de bandaferro"}},["2cf6b481"]={q="Por que alguém quer o Relatório de Progresso de Bandaferro?",a="O relatório é uma documentação vital exigida pelos contatos administrativos em Thelsamar e na sede da Liga dos Exploradores em Altaforja. Sem esse relato oficial detalhando as dificuldades do local e a interferência dos trogs, superiores como o Prospector Lançatroz não darão aprovação burocrática para liberar e despachar novas remessas de pó de explosão.",al={"por que o relatório de progresso de bandaferro é necessário","por que pegar o relatório de bandaferro","propósito do relatório de progresso de bandaferro"}}},fp="26,178,20.281.0,35.116.0,25.137.0,40.185.0,50.191.0"}
P.entries["item:ironfur-liver"] = {n="Ironfur Liver",s="Ironfur Liver vem dos ursos Ironfur de Feralas. Rhapsody Shindigger precisa dele para preparar uma bebida que, espera, o ajude a falar sobre uma aventura no pântano.",h="Ironfur Liver vem dos ursos Ironfur de Feralas.",kw={"feralas","groddoc liver","urso ironfur","ironfur liver","kalimdor kocktail","rhapsody shindigger","roc gizzard"},sec={{t="Uma bebida mais forte",b="Rhapsody Shindigger, nas Terras Agrestes, pede que você traga três Ironfur Livers para seu Kalimdor Kocktail. Ele os combina com Groddoc Livers de Feralas e Roc Gizzards de Tanaris. Segundo ele, a bebida vai ajudá-lo a falar sobre seu voo pelo pântano."}},faq={{q="De onde vêm os Ironfur Livers?",a="Os Ironfur Livers vêm dos ursos Ironfur de Feralas.",al={"origem de ironfur liver","onde conseguir liver"}},{q="Quem quer Ironfur Liver?",a="Rhapsody Shindigger, nas Terras Agrestes, quer três Ironfur Livers para seu Kalimdor Kocktail.",al={"quem precisa disso","rhapsody liver"}},{q="Por que Rhapsody precisa desses fígados?",a="Rhapsody precisa de Ironfur Livers, Groddoc Livers e Roc Gizzards para preparar um Kalimdor Kocktail forte. Ele espera que a bebida o ajude a falar sobre sua aventura no pântano.",al={"por que liver","para que serve o coquetel"}},{q="O que mais vai no Kalimdor Kocktail?",a="O Kalimdor Kocktail também leva Groddoc Livers de Feralas e Roc Gizzards de Tanaris.",al={"ingredientes do coquetel","outros órgãos"}}},fp="13,148,16.252.0,34.50.0,24.92.0,36.164.0,42.95.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Presa de Ishamuhale",s="A Presa de Ishamuhale é um troféu de caça obtido de Ishamuhale, o notório raptor escama-do-sol conhecido como Dente-de-lança nos Sertões. Levado a Jorn Vidente do Céu no Acampamento Taurajo, o dente serve como prova de ter superado um dos predadores naturais mais letais de Kalimdor.",h="A Presa de Ishamuhale é um troféu de caça obtido de Ishamuhale, o notório raptor escama-do-sol conhecido como...",kw={"sertões","presa","ishamuhale","jorn","raptor","sergra","dente-de-lança","escama-do-sol","taurajo"},ang={["class:Hunter"]="Tomar a presa de Dente-de-lança é um rito de passagem essencial pelos Sertões, testando a habilidade de um rastreador em atrair, confrontar e superar uma fera alfa astuta.",["race:Tauren"]="Para os caçadores de Taurajo, reivindicar o dente não se trata de matança desnecessária, mas de absorver o poder bruto de um predador mantendo a disciplina e o equilíbrio."},sec={{t="Troféu de Dente-de-lança",b="Ishamuhale é temido em toda a savana central como o mais feroz raptor escama-do-sol vivo, um predador alfa de quem se diz matar puramente por paixão predatória, e não por mera fome. Atraída para campo aberto com carne fresca de zhevra ao lado de uma árvore ressequida a noroeste de Vila Catraca, a fera não demonstra piedade. Arrancar sua presa maciça prova aos instrutores de caça da Horda que um viajante conquistou não apenas uma besta, mas a própria selvageria das planícies."},{t="Uma Lição de Moderação",b="Quando apresentada a Jorn Vidente do Céu no Acampamento Taurajo, a presa é reconhecida como muito mais do que marfim e sangue. Para os taurens do acampamento, tomar a presa de Ishamuhale transfere a força feroz do predador para o caçador que o derrotou. O verdadeiro teste que se segue é a moderação: dominar essa fúria selvagem em vez de permitir que ela controle a alma do caçador."}},faq={{q="O que é a Presa de Ishamuhale?",a="É um troféu resgatado do cadáver de Ishamuhale, o infame raptor escama-do-sol 'Dente-de-lança' que espreita nos Sertões.",al={"dente de ishamuhale","presa de dente-de-lança","presa de raptor sertões"}},{q="Quem deseja a Presa de Ishamuhale?",a="A presa é levada a Jorn Vidente do Céu no Acampamento Taurajo como parte das provações de caça que começam com Sergra Espinhonegro na Encruzilhada.",al={"a quem entregar a presa de ishamuhale","entregar presa de ishamuhale","onde entregar presa de ishamuhale"}},{q="Como a fera Ishamuhale é encontrada?",a="Ishamuhale não vagueia abertamente. Os caçadores precisam abater uma zhevra fresca e colocar sua carcaça perto de uma árvore morta a noroeste de Vila Catraca para atrair o raptor para fora de seu esconderijo.",al={"como fazer ishamuhale aparecer","invocar ishamuhale","onde fica ishamuhale"}},{q="O que a conquista da presa representa para os taurens?",a="De acordo com Jorn Vidente do Céu, reivindicar o troféu simboliza que a força lendária de Ishamuhale agora reside no caçador, que deve carregar o fardo de usar esse poder com moderação e honra.",al={"significado da presa","ritual de caçador tauren ishamuhale"}}},fx={aa73e2a3={q="De onde vem a Presa de Ishamuhale?",a="A presa é tirada diretamente das mandíbulas de Ishamuhale, também conhecido como Dente de Lança. Ele é o mais feroz raptor escama-do-sol vagando pelos Sertões, um predador natural que mata puramente por instinto selvagem. Ela não foi trabalhada por mãos mortais, mas cresceu naturalmente como uma arma mortal da fera.",al={"origem da presa de ishamuhale","de onde veio a presa de ishamuhale","quem fez a presa de ishamuhale"}}},fp="17,199,20.409.0,22.293.1,26.117.0,28.129.0,34.105.0,52.166.0"}
P.entries["item:ivar-s-head"] = {n="Cabeça de Ivar",s="A Cabeça de Ivar é a prova macabra da destruição do carniçal voraz Ivar the Foul na Floresta de Pinhaprata. Ela é procurada pela Deathstalker Rane Yorick para garantir uma recuperação segura para seu irmão ferido, Quintino.",h="A Cabeça de Ivar é a prova macabra da destruição do carniçal voraz Ivar the Foul na Floresta de Pinhaprata.",kw={"deathstalkers","plantação do ivar","ivar the foul","cabeça de ivar","quintino yorick","rane yorick","floresta de pinhaprata"},ang={["faction:Horde"]="Eliminar remanescentes desgarrados do Flagelo como Ivar protege mensageiros da Horda que viajam pelo norte de Pinhaprata em direção ao Sepulcro.",["race:Undead"]="Para batedores Renegados, carniçais selvagens são estorvos irracionais que atrapalham o reconhecimento militar e ameaçam a segurança nascente de Lordaeron."},sec={{t="Uma Ameaça Decepada",b="Enquanto faziam o reconhecimento do norte da Floresta de Pinhaprata sob as ordens do Alto-executor Hadrec, os Deathstalkers Renegados Rane e Quintino Yorick foram emboscados em uma propriedade rural abandonada por um carniçal feral conhecido como Ivar the Foul. Embora os irmãos tenham conseguido repelir a criatura, Quintino foi gravemente ferido no confronto. Presa na fazenda em ruínas enquanto seu irmão se recuperava, Rane não podia deixar Quintino desacompanhado com segurança para completar a missão. Decepar a cabeça de Ivar fornece uma prova definitiva de que a fera nunca mais aterrorizará a propriedade, concedendo a Quintino o tempo necessário para se restabelecer sob o olhar atento de Rane."}},faq={{q="De quem é esta cabeça?",a="A cabeça pertencia a Ivar the Foul, um carniçal selvagem que assombra a propriedade rural abandonada conhecida como Plantação do Ivar, no norte da Floresta de Pinhaprata.",al={"quem é ivar","identidade da cabeça de ivar","o que é ivar"}},{q="Por que Rane Yorick quer a cabeça de Ivar?",a="Rane exige uma prova física de que Ivar foi destruído. Seu irmão Quintino foi gravemente dilacerado pela criatura e precisa de tempo para se curar sem o temor de outra emboscada antes de se apresentarem de volta ao Alto-executor Hadrec.",al={"por que rane quer a cabeça","entrega da cabeça de ivar","por que matar ivar"}},{q="Onde Ivar the Foul foi encontrado?",a="Ivar the Foul espreita dentro do celeiro dilapidado na Plantação do Ivar, vigiando e esperando que os Deathstalkers feridos baixem a guarda.",al={"localização de ivar","onde fica ivar"}}},fx={fce823f2={q="De onde vem a Cabeça de Ivar?",a="Esta cabeça decepada é tirada diretamente do cadáver de Ivar the Foul, um carniçal cruel à espreita dentro do celeiro arruinado na Plantação do Ivar na Floresta de Pinhaprata. Não é um artefato ou item criado, mas o troféu físico decepado de um monstro morto-vivo para garantir que ele tenha sido verdadeiramente destruído.",al={"origem da cabeça de ivar","de onde veio a cabeça de ivar","quem fez a cabeça de ivar"}}},fp="11,174,16.448.0,19.136.0,38.183.0,30.129.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Antídoto de Iverron",s="Iverron's Antidote é uma poção medicinal delicada preparada por Dirânia Pratafulge em Umbravale. Especialmente feita para neutralizar o veneno letal das aranhas Webwood locais, a mistura é altamente instável e se estraga rapidamente após o preparo.",h="Iverron's Antidote é uma poção medicinal delicada preparada por Dirânia Pratafulge em Umbravale.",kw={"aldrassil","dirânia pratafulge","iverron","iverron's antidote","umbravale","veneno de aranha","teldrassil","webwood venom"},ang={["profession:Herbalism"]="A mistura demonstra a extrema volatilidade dos reagentes nativos de Teldrassil, destacando como certos remédios de ervas devem ser consumidos imediatamente após o preparo.",["race:NightElf"]="Para jovens aventureiros elfos noturnos que começam em Umbravale, levar esta cura às pressas para Iverron demonstra a dependência da comunidade em ações rápidas e no conhecimento de ervas contra a corrupção rastejante nos galhos de Teldrassil."},sec={{t="Um Remédio Frágil",b="Criado por Dirânia Pratafulge em Aldrassil, este antídoto é formulado para combater o potente veneno que aflige o jovem elfo noturno Iverron. Devido à natureza volátil de seus ingredientes e catalisadores de ervas, a poção possui uma vida útil excepcionalmente curta, permanecendo viável por apenas cinco minutos após o preparo. Mensageiros devem correr para o norte em direção à caverna Webwood sem demora para entregar a mistura antes que ela se degrade em uma pasta inútil."}},faq={{q="Para que serve o Iverron's Antidote?",a="Ele cura Iverron da picada tóxica que sofreu das aranhas Webwood nas proximidades de sua caverna, no norte de Umbravale.",al={"uso do antídoto","o que faz o iverron's antidote"}},{q="Por que o antídoto tem um limite de tempo?",a="Dirânia Pratafulge observa que a mistura é frágil e só permanece potente por cinco minutos após o preparo. Se não for administrada rapidamente, suas propriedades medicinais se degradam por completo.",al={"por que 5 minutos","temporizador do antídoto","por que expira"}},{q="Quem prepara o antídoto?",a="Dirânia Pratafulge, uma curadora elfa noturna estabelecida em Aldrassil, dentro de Umbravale, prepara a poção usando ingredientes colhidos para salvar Iverron.",al={"quem fez o antídoto","criador do antídoto"}},{q="O que acontece se o antídoto expirar?",a="Se o tempo acabar, a poção se estraga e não funcionará mais. O mensageiro deve retornar até Dirânia Pratafulge em Aldrassil para obter uma nova dose.",al={"antídoto expirado","tempo acabou"}}},fx={["59c1ca07"]={q="O que é o Iverron's Antidote?",a="É uma poção medicinal recém-preparada criada especificamente para neutralizar o veneno mortal das aranhas de Teia-de-madeira que espreitam nos galhos de Teldrassil. Devido à sua mistura natural delicada, o curativo é altamente volátil e estragará rapidamente se não for consumido minutos após sua preparação.",al={"o que é o iverron's antidote","antídoto de iverron","cura de iverron"}}},fp="18,204,16.292.0,36.115.0,40.143.0,23.127.0,37.142.0"}
P.entries["item:jade-phial"] = {n="Frasco de Jade",s="O Frasco de Jade é um recipiente especialmente criado fornecido pelo druida Elfo Noturno Corithras Lunafúria em Dolanaar. Ele foi projetado para coletar e transportar com segurança a água sagrada dos poços lunares de Teldrassil, a fim de reabastecer o poço central dos druidas em Darnassus.",h="O Frasco de Jade é um recipiente especialmente criado fornecido pelo druida Elfo Noturno Corithras Lunafúria...",kw={"corithras lunafúria","coroa da terra","dolanaar","frasco de jade","poço lunar","vilarejo brisastral","teldrassil"},ang={["class:Druid"]="Para os jovens druidas, carregar o Frasco de Jade é uma lição primordial de zelo, enfatizando que a vitalidade dos poços lunares de Teldrassil exige reverência e cuidado constantes.",["race:NightElf"]="Os poços lunares representam o vínculo duradouro entre os kaldorei e Elune; cuidar deles com recipientes como o Frasco de Jade é um dever sagrado para todo Elfo Noturno."},sec={{t="Um Recipiente para Águas Sagradas",b="Teldrassil é repleta de poços lunares que canalizam energias lunares e naturais vitais para a sociedade dos Elfos Noturnos e para o culto druídico. Como parte da manutenção dessa harmonia, o poço lunar central usado pelos druidas em Darnassus deve ser reabastecido periodicamente a partir dos poços periféricos espalhados pela grande ramagem. Corithras Lunafúria confia aos jovens iniciados o Frasco de Jade, um receptáculo cuidadosamente preparado para coletar águas puras do poço lunar próximo ao Vilarejo Brisastral sem perturbar sua delicada potência espiritual."}},faq={{q="Para que serve o Frasco de Jade?",a="O Frasco de Jade é usado para coletar água sagrada do poço lunar situado logo nos arredores do Vilarejo Brisastral. Depois de cheio, ele deve ser levado de volta a Corithras Lunafúria em Dolanaar para ajudar a reabastecer o poço lunar dos druidas em Darnassus.",al={"propósito do frasco de jade","por que preciso do frasco de jade","o que o frasco de jade faz"}},{q="Quem fornece o Frasco de Jade?",a="Corithras Lunafúria, um druida Elfo Noturno localizado em Dolanaar, fornece o frasco aos aventureiros que realizam o rito conhecido como a Coroa da Terra.",al={"quem dá o frasco de jade","onde conseguir o frasco de jade","corithras frasco de jade"}},{q="Para onde vai a água deste frasco?",a="As águas coletadas no frasco são transportadas para sustentar e reabastecer o poço lunar central mantido pelos druidas Cenarianos dentro da capital de Darnassus.",al={"para onde vai a água do poço lunar","destino do frasco de jade","quem usa a água"}}},fx={["8250d8c3"]={q="O que é o Frasco de Jade?",a="O Frasco de Jade é um recipiente ritual especialmente criado, fornecido por Corithras Lunafúria em Dolanaar. Ele é projetado para conter e transportar com segurança as águas sagradas e abençoadas retiradas dos poços da lua de Teldrassil sem perturbar ou degradar suas propriedades mágicas inerentes.",al={"frasco de jade","o que é o frasco de jade","o que é frasco de jade"}}},fp="10,185,26.442.0,32.207.0,28.143.0,44.125.0"}
P.entries["item:jennea-s-flask"] = {n="Frasco de Jennea",s="O Frasco de Jennea é um recipiente vazio entregue a aspirantes a magos pela maga Jana Catão no Distrito dos Magos de Ventobravo. Ele é usado para coletar uma amostra de água do Lago Espelhado a fim de estudar perturbações nas linhas de meridiano locais.",h="O Frasco de Jennea é um recipiente vazio entregue a aspirantes a magos pela maga Jana Catão no Distrito dos...",kw={"floresta de elwynn","jana catão","frasco de jennea","lago espelhado","ventobravo","amostra de água","sacrário dos teurgos"},ang={["class:Mage"]="Para magos noviços, carregar este frasco representa uma de suas primeiras tarefas de campo para o Sacrário dos Teurgos, provando que você é capaz de lidar com pesquisas arcanas delicadas e monitorar a estabilidade das linhas de meridiano."},sec={{t="Um Recipiente para Pesquisa Arcana",b="Após os conflitos mágicos cataclísmicos por toda Azeroth, o fluxo natural das correntes arcanas se desgarrou de seus canais ancestrais. Em Ventobravo, Jana Catão procura entender a profundidade com que essas mudanças místicas afetaram a Floresta de Elwynn. Ela fornece este frasco de vidro simples a aprendizes promissores, enviando-os ao sudoeste dos portões da capital para coletar água fresca na base da cachoeira no Lago Espelhado. Depois de cheio, o recipiente protege a amostra delicada para que ela possa ser levada intacta de volta ao Sacrário dos Teurgos para análise arcana."},{t="Protegendo as Águas",b="A principal preocupação por trás do uso do frasco é a segurança pública. Se linhas de meridiano flutuantes começarem a infiltrar corrupção mágica no Lago Espelhado, o ecossistema ao redor e qualquer um que beba de suas águas podem sofrer aflições estranhas ou prejudiciais. Coletar uma amostra pura no frasco de Jana permite que os magos de Ventobravo detectem resíduos mágicos invisíveis antes que correntes corrompidas se espalhem sem serem notadas pelos campos."}},faq={{q="Para que serve o Frasco de Jennea?",a="É um recipiente vazio entregue a você para coletar uma amostra de água da cachoeira no Lago Espelhado, na Floresta de Elwynn.",al={"propósito do frasco","o que o frasco faz","uso do frasco"}},{q="Quem entrega este frasco a você?",a="Ele é fornecido por Jana Catão, uma instrutora de magos instalada dentro do Sacrário dos Teurgos em Ventobravo.",al={"quem entrega o frasco","origem do frasco de jennea"}},{q="Por que Jana quer água do Lago Espelhado?",a="Conflitos místicos recentes perturbaram o fluxo de magia pelo mundo. Jana teme que essas correntes desgarradas estejam se infiltrando nas águas naturais de Elwynn, o que pode colocar em risco qualquer pessoa que beba do lago.",al={"por que água do lago espelhado","por que amostra de água"}},{q="Onde o frasco é cheio?",a="Você deve levar o frasco até a base da cachoeira que deságua no Lago Espelhado, localizado a sudoeste dos portões principais de Ventobravo, na Floresta de Elwynn.",al={"onde encher o frasco","localização do frasco","localização do lago"}}},fx={b836f408={q="O que é o Frasco de Jennea?",a="É um recipiente de amostra especializado fornecido por Jana Catão, uma instrutora no Distrito dos Magos de Ventobravo. Ela o confia a aprendizes promissores para coletar água diretamente da cachoeira do Lago Espelhado, para que ela possa inspecioná-la em busca de contaminação mágica.",al={"o que é o frasco de jennea","frasco de jennea"}}},fp="14,138,28.439.0,19.309.0,32.86.0,25.88.0,44.184.0,28.126.0"}
P.entries["item:jer-kai-s-signet-ring"] = {n="Jer'kai's Signet Ring",s="Jer'kai's Signet Ring leva a mensagem dela dos ermos de Feralas até Tyrande Murmuréolo, em Darnassus. Ela conta à Alta Sacerdotisa que Jer'kai e Kindal estão bem e reconhece sua ajuda.",h="Jer'kai's Signet Ring leva a mensagem dela dos ermos de Feralas até Tyrande Murmuréolo, em Darnassus.",kw={"darnassus","feralas","jer'kai teceluna","anel-sinete de jer'kai","kindal","mensagem","anel-sinete","templo da lua","tyrande murmuréolo"},ang={["race:NightElf"]="Como Elfo Noturno, você leva a mensagem de Jer'kai a Tyrande Murmuréolo, Alta Sacerdotisa de Eluna, no Templo da Lua."},sec={{t="Uma mensagem para Darnassus",b="Em Feralas, Jer'kai Teceluna confia a você seu anel-sinete depois que você ajuda a ela e Kindal. Ela pede que você o leve a Tyrande Murmuréolo, no Templo da Lua, em Darnassus. O anel informa que as duas estão bem e conta a Tyrande a verdade sobre sua ajuda."},{t="No templo",b="Tyrande ouve seu relato sobre como você ajudou os dragonídeos e uma de suas sacerdotisas. Ela promete devolver o anel de Jer'kai, enviando batedores em direção a Feralas com ele. Por ora, o anel já levou sua mensagem à Alta Sacerdotisa."}},faq={{q="Para que serve o anel-sinete de Jer'kai?",a="Jer'kai pede que você leve o anel a Tyrande Murmuréolo, no Templo da Lua, em Darnassus. Ele conta a Tyrande que Jer'kai e Kindal estão bem e reconhece sua ajuda.",al={"anel de jerkai","para que serve o anel-sinete","anel para tyrande"}},{q="Quem me deu o anel?",a="Jer'kai Teceluna lhe dá seu anel-sinete em Feralas, depois que você ajuda a ela e Kindal.",al={"quem deu o anel","quem deu o anel de jerkai","de onde veio o anel"}},{q="Quem deve receber o anel?",a="Tyrande Murmuréolo, a Alta Sacerdotisa no Templo da Lua de Darnassus, deve receber o anel.",al={"destinatário do anel","quem recebe o anel de jerkai","anel de tyrande"}},{q="O que Tyrande faz com o anel?",a="Tyrande promete devolver o anel a Jer'kai e envia batedores em direção a Feralas com ele.",al={"resposta de tyrande","anel devolvido","o que acontece com o anel"}}},fp="21,197,22.267.0,13.219.0,34.178.0,21.86.0,36.98.0,35.86.1"}
P.entries["item:jeweled-pendant"] = {n="Jeweled Pendant",s="O Jeweled Pendant é um adorno nobre finamente trabalhado, encontrado entre soldados da Aliança perto de Theramore. Sua presença entre tropas comuns chamou a atenção da Horda.",h="O Jeweled Pendant é um adorno nobre finamente trabalhado, encontrado entre soldados da Aliança perto de...",kw={"aliança","horda","jeweled pendant","marg","muckshell","nazeer","pingente","ventobravo","theramore","zor solárbol"},ang={["faction:Alliance"]="Viram um soldado de Ventobravo usando este pingente finamente trabalhado perto de Theramore, e seu dono desconhecido pode ser um nobre.",["faction:Horde"]="O pingente pode oferecer à Horda uma pista sobre os assuntos dos nobres da Aliança. Zor Solárbol estuda seu artesanato e sua história."},sec={{t="O prêmio de um soldado",b="Perto de Theramore, Marg viu um soldado da Aliança usando um pingente com mais gemas do que um soldado comum poderia pagar. Marg o roubou do acampamento, mas um muckshell o matou no caminho de volta. O pingente foi recuperado e levado a Nazeer, na Aldeia Muralha Verde, onde seu fino acabamento levantou dúvidas sobre quem seria o verdadeiro dono."},{t="Trabalho de um nobre",b="Zor Solárbol, que conhece bem a política da Aliança, agora estuda o pingente em Orgrimmar. Ele percebe a habilidade do artesão e acredita que muitos humanos cobiçariam uma joia dessas. Seu dono continua desconhecido, enquanto a Horda aguarda para descobrir o que o adorno pode revelar."}},faq={{q="Quem era o dono do Jeweled Pendant?",a="O dono do pingente é desconhecido. Marg o viu com um soldado da Aliança perto de Theramore, mas o fino acabamento sugere que pertencia a um nobre.",al={"dono do pingente","quem usava","de quem é a joia"}},{q="Por que Marg roubou o pingente?",a="Marg viu um soldado da Aliança usando um pingente coberto de gemas e o roubou do acampamento perto de Theramore.",al={"por que roubar","pingente de marg","o que marg pegou"}},{q="O que aconteceu com Marg?",a="Um muckshell matou Marg quando ele voltava à base com o pingente que havia roubado do acampamento da Aliança.",al={"destino de marg","como marg morreu","história de marg"}},{q="Por que a Horda se importa com o pingente?",a="O pingente parece ter sido feito para um nobre, mas um soldado da Aliança o usava perto de Theramore. Zor Solárbol o estuda em busca de pistas sobre seu dono.",al={"pingente da horda","por que reportar a zor","mistério do pingente"}},{q="Onde está o pingente agora?",a="Zor Solárbol está estudando o Jeweled Pendant em Orgrimmar.",al={"localização do pingente","onde levar a joia","pingente de zor"}}},fp="15,179,19.329.0,16.264.0,30.145.0,31.105.0,22.101.1,42.143.0,25.58.0"}
P.entries["item:jitters-completed-journal"] = {n="Diário Completo de Medrisco",s="O Diário Completo de Medrisco é um relato manuscrito detalhando as trágicas atrocidades da Floresta do Crepúsculo, especificamente o massacre na fazenda de Noel Figueira. Temendo vingança, o recluso Medrisco entrega o texto finalizado para limpar seu nome e lançar luz sobre as forças sinistras que assombram a região.",h="O Diário Completo de Medrisco é um relato manuscrito detalhando as trágicas atrocidades da Floresta do...",kw={"bispo palhares","catedral da luz","cavaleiros sombrios","floresta do crepúsculo","morro dos esquecidos","medrisco","diário","morbent fel","noel figueira"},ang={["class:Priest"]="Entregar o diário ao Bispo Palhares na Catedral da Luz coloca os sacerdotes diretamente a serviço da purificação de profanações vis através de relíquias sagradas.",["faction:Alliance"]="O diário serve como um lembrete vívido de quão profundamente a Floresta do Crepúsculo caiu em perigo enquanto a liderança de Ventobravo permanece preocupada com outras questões."},sec={{t="Uma Confissão Covarde",b="Quando a fazenda de Noel foi atacada, Medrisco fugiu em pavor, abandonando seu diário incompleto entre as ruínas. O diário completo preenche as partes que faltavam daquele dia terrível, narrando como misteriosos cavaleiros sombrios massacraram a família de Noel. Por semanas, manter o diário foi o único consolo de Medrisco enquanto se escondia na Floresta do Crepúsculo. Ele entrega o volume finalizado de bom grado, desesperado para explicar o que realmente aconteceu e esperando que a verdade escrita o poupe da fúria vingativa de Noel."},{t="Desvendando a Escuridão",b="O diário faz mais do que acalmar velhas mágoas: ele leva Noel a revelar que viu os cavaleiros de mantos negros falando com o mago Morbent Fel no Morro dos Esquecidos. Noel envia o manuscrito completo com viajantes para o norte, até a Catedral da Luz em Ventobravo. Lá, o Bispo Palhares lê as palavras de Medrisco para entender a corrupção vil que apodrece na Floresta do Crepúsculo, usando suas revelações para ajudar a forjar uma arma sagrada capaz de perfurar as proteções sombrias de Fel."}},faq={{q="Por que Medrisco entregou seu diário?",a="Medrisco fugiu da fazenda de Noel durante o ataque e deixou um diário incompleto para trás. Ele deu a versão completa aos aventureiros para que pudessem levá-la a Noel, esperando que a verdade completa o inocentasse e o mantivesse a salvo do temperamento explosivo de Noel.",al={"por que medrisco entrega o diário","diário de medrisco","por que medrisco escreveu isto"}},{q="O que o diário revela sobre a fazenda de Noel?",a="Ele fornece o relato completo como testemunha ocular de Medrisco sobre a tragédia na fazenda de Noel Figueira, preenchendo as lacunas deixadas pelo seu diário inacabado.",al={"o que aconteceu na fazenda de noel","ataque à família de noel","cavaleiros sombrios na fazenda de noel"}},{q="Quem é Morbent Fel e como ele está conectado ao diário?",a="Morbent Fel é um necromante que reside no Morro dos Esquecidos. O diário leva Noel a compartilhar informações que direcionam a investigação para ele.",al={"conexão de morbent fel","quem é morbent fel","mago do morro dos esquecidos"}},{q="Por que o diário é levado para Ventobravo?",a="Noel instrui os aventureiros a levar o diário ao Bispo Palhares na Catedral da Luz. Como Ventobravo tem negligenciado amplamente a defesa de Vila Sombria, a sabedoria e a perícia sagrada de Palhares são necessárias para preparar uma arma que possa perfurar as proteções mágicas de Morbent Fel.",al={"por que o bispo palhares","levar diário para a catedral","diário de seeking wisdom"}}},fx={["3f8dfebe"]={q="O que é o Diário Completo de Medrisco?",a="É a crônica pessoal completa mantida por Medrisco, um vagabundo aterrorizado escondido na Floresta do Crepúsculo. Ao contrário das notas fragmentárias deixadas para trás quando ele fugiu da fazenda de Noel Figueira, este manuscrito completo apresenta toda a sequência de tragédias que atingiram a propriedade, os horrores invasores da floresta e as figuras sinistras movendo-se através das sombras.",al={"diário completo de medrisco","o que é este diário","diário de medrisco"}},e7121643={q="De onde vem o Diário Completo de Medrisco e quem o escreveu?",a="O diário foi escrito pelo próprio Medrisco. Depois de fugir do massacre na fazenda de Noel Figueira e abandonar um diário anterior, ele passou semanas escondido, escrevendo freneticamente seus pensamentos e relatando as forças sinistras que espreitavam a Floresta do Crepúsculo. Ele guardou o volume terminado como sua única companhia até entregá-lo para evitar enfrentar a ira de Noel Figueira.",al={"quem escreveu o diário de medrisco","origem do diário de medrisco","de onde veio o diário"}},["5c3c5710"]={q="Por que o Diário Completo de Medrisco é procurado?",a="Noel Figueira procura o diário pelo relato em primeira mão de Medrisco sobre a tragédia em sua fazenda. Mais tarde, o Bispo Palhares na Catedral da Luz estuda-o para ajudar a preparar um aventureiro para enfrentar o mal que aflige a Floresta do Crepúsculo.",al={"por que querem o diário","por que o diário de medrisco é importante","quem quer o diário"}}},fp="26,161,21.343.1,23.373.1,36.219.0,47.140.1,58.142.1,38.206.1"}
P.entries["item:johaan-s-findings"] = {n="Achados de Joaquino",s="Os Achados de Joaquino são um maço de documentos de pesquisa escritos pelo Boticário Joaquino em Montalvo. Confiadas a um mensageiro que ruma para o sul, essas anotações transmitem os desenvolvimentos alquímicos recentes nas Clareiras de Tirisfal ao Boticário Renferrel no Sepulcro.",h="Os Achados de Joaquino são um maço de documentos de pesquisa escritos pelo Boticário Joaquino em Montalvo.",kw={"boticário joaquino","boticário renferrel","montalvo","joaquino","achados de joaquino","uma nova peste","real sociedade de boticários","o sepulcro"},ang={["faction:Horde"]="Levar as pesquisas para o sul marca a transição do viajante das terras familiares das Clareiras de Tirisfal para os conflitos mais sombrios da Floresta de Pinhaprata.",["race:Undead"]="Estes achados refletem a ambição primordial e implacável da Sociedade Real dos Boticários: entregar a Nova Peste prometida à Dama Sombria."},sec={{t="Correspondência dos Boticários",b="A Sociedade Real dos Boticários opera sob a pressão incessante de Grande Dama Sylvana Correventos para desenvolver Uma nova peste capaz de destruir tanto os vivos quanto o Flagelo. Como os pesquisadores estão espalhados pelas ruínas disputadas de Lordaeron, manter um fluxo de dados entre os postos avançados é vital. O Boticário Joaquino reúne suas anotações de testes locais em Montalvo e as envia para o sul, para o Boticário Renferrel, que coordena os esforços da sociedade a partir d'O Sepulcro, na Floresta de Pinhaprata. Esses registros representam uma pequena parte do esforço coletivo da Sociedade para aprimorar suas misturas letais."}},faq={{q="O que são os Achados de Joaquino?",a="Trata-se de um pacote de anotações e pesquisas alquímicas compiladas pelo Boticário Joaquino em Montalvo. Os papéis detalham seus testes e experimentos recentes nas Clareiras de Tirisfal.",al={"achados de joaquino","o que sao os achados de joaquino","papeis de pesquisa de joaquino"}},{q="Quem deve receber este item?",a="Os achados são endereçados ao Boticário Renferrel, um membro veterano da Sociedade Real dos Boticários alocado n'O Sepulcro, no norte da Floresta de Pinhaprata.",al={"quem recebe os achados de joaquino","onde levar os achados de joaquino","entrega para renferrel"}},{q="Por que esta pesquisa está sendo compartilhada entre boticários?",a="A Sociedade Real dos Boticários depende do conhecimento compartilhado entre seus pesquisadores dispersos para acelerar seus trabalhos. Sylvana Correventos exige o desenvolvimento rápido de Uma nova peste, tornando essencial que os pesquisadores em Pinhaprata permaneçam atualizados sobre os avanços alcançados em Tirisfal.",al={"por que compartilhar achados","proposito dos achados de joaquino","pesquisa da sociedade real dos boticarios"}},{q="Quem escreveu estes documentos?",a="O Boticário Joaquino, um alquimista da Sociedade Real dos Boticários que fica perto da forca em Montalvo. Ele realiza testes experimentais em espécimes locais para promover os objetivos alquímicos dos Renegados.",al={"quem e o boticario joaquino","quem escreveu isto","boticário joaquino"}}},fp="17,181,25.524.0,26.156.0,37.156.0,55.236.0,26.169.0"}
P.entries["item:johaan-s-special-drink"] = {n="Bebida Especial do Joaquino",s="A Bebida Especial do Joaquino é uma mistura letal preparada pelo Boticário Joaquino no vilarejo de Montalvo. Disfarçada como um refresco comum, a mistura serve como um teste de campo para a peste que a Sociedade Real dos Boticários está desenvolvendo.",h="A Bebida Especial do Joaquino é uma mistura letal preparada pelo Boticário Joaquino no vilarejo de Montalvo.",kw={"boticário joaquino","montalvo","montanhista capturado","taberna finda forca","joaquino","bebida especial do joaquino","nova peste"},ang={["race:Dwarf"]="A mistura revela o destino sombrio que aguarda os batedores anões que se aproximam demais das Clareiras de Tirisfal, onde os cativos são usados como cobaias de laboratório.",["race:Undead"]="Para os Renegados, entregar a poção de Joaquino representa um serviço prático prestado à Sociedade Real dos Boticários e aos grandes planos da Dama Sylvanas contra os vivos."},sec={{t="Uma Mistura Tóxica",b="Preparada nos caldeirões de Montalvo, a Bebida Especial do Joaquino está longe de ser uma bebida de taberna. O Boticário Joaquino elabora a poção refinando vários componentes venenosos e reagentes locais em uma única dose, criada sob medida para testar a virulência contra a fisiologia dos vivos. Entregue sob o pretexto de saciar a sede de um prisioneiro, ela representa a ambição contínua dos boticários Renegados de criar uma arma potente o suficiente para cumprir os planos de Sylvana Correventos para Azeroth."},{t="O Teste no Porão",b="A bebida encontra seu destinatário planejado no porão sombrio sob a Taberna Finda Forca, que a Guarda Mortal usa como cela temporária para intrusos desgarrados. Ao ser oferecida a um montanhista anão capturado que definha acorrentado, o prisioneiro sedento bebe-a avidamente, confundindo-a com cerveja ruim. A beberagem age instantaneamente, matando o anão no local e provando à Sociedade Real dos Boticários que sua cepa mais recente consegue extinguir rapidamente vítimas vivas."}},faq={{q="O que é a Bebida Especial do Joaquino?",a="É uma poção mortal criada pelo Boticário Joaquino em Montalvo. Embora apresentada como uma bebida, ela é infundida com uma cepa da peste que os Renegados estão desenvolvendo, feita para testar sua eficácia letal contra seres vivos.",al={"o que e a bebida do joaquino","bebida do joaquino","o que e este item"}},{q="A quem a bebida é dada?",a="A bebida é levada ao porão da Taberna Finda Forca em Montalvo e entregue a um Montanhista Capturado que foi feito prisioneiro pela Guarda Mortal local.",al={"quem bebe ela","para quem entrego a bebida","alvo da bebida"}},{q="O que acontece quando alguém a bebe?",a="O prisioneiro engole o líquido esperando uma zurrapa de taberna forte para saciar a sede, apenas para cair morto imediatamente devido às toxinas virulentas da poção.",al={"o anao morre","efeito da bebida","o que ela faz"}},{q="Por que o Boticário Joaquino faz essa bebida?",a="O Boticário Joaquino está conduzindo testes para a nova peste da Sociedade Real dos Boticários. Ele usa o anão capturado como cobaia viva involuntária para ver a eficácia da mistura em ceifar a vida mortal.",al={"por que joaquino fez isso","motivo do boticario joaquino","por que testar a peste"}}},fx={["7bd04f9d"]={q="De onde vem a Bebida Especial do Joaquino e quem a fez?",a="A mistura é produzida diretamente pelo Boticário Joaquino em Montalvo, nas Clareiras de Tirisfal. Trabalhando em nome da Real Sociedade de Boticários e da Grande Dama Sylvana Correventos, Joaquino refina toxinas experimentais coletadas de criaturas locais para criar esta mistura potente e letal.",al={"quem fez a bebida especial do joaquino","de onde veio a bebida especial do joaquino","quem fabricou a bebida"}}},fp="22,174,12.359.0,16.323.1,31.117.0,26.139.0,36.68.1,43.163.0"}
P.entries["item:jon-jon-s-golden-spyglass"] = {n="Luneta Dourada de Janjão",s="A Luneta Dourada de Janjão está entre os objetos de valor que Sea Wolf MacKinley procura em Angra do Butim. Ele quer recebê-la de volta junto com outras duas dívidas das ruínas da selva.",h="A Luneta Dourada de Janjão está entre os objetos de valor que Sea Wolf MacKinley procura em Angra do Butim.",kw={"angra do butim","luneta dourada","jon-jon","jon-jon the crow","ruínas de aboraz","ruínas de jubuwal","sea wolf mackinley","luneta","voodoo dues"},sec={{t="Uma dívida em ouro",b="Sea Wolf MacKinley, em Angra do Butim, quer a Luneta Dourada de Janjão de volta junto com outros dois objetos de valor. Jon-Jon the Crow é um dos três devedores que, segundo MacKinley, desapareceram nas ruínas da selva. Eles estão devendo há meses, e MacKinley quer receber o que lhe devem."}},faq={{q="Quem quer a luneta de Jon-Jon?",a="Sea Wolf MacKinley, de Angra do Butim, quer recebê-la de volta junto com outros dois objetos de valor que lhe devem.",al={"quem quer a luneta","luneta de mackinley","dívida da luneta"}},{q="Quem é Jon-Jon the Crow?",a="Jon-Jon the Crow é um dos três devedores que, segundo MacKinley, foram para as ruínas da selva depois que suas dívidas venceram.",al={"jon-jon","história de jon-jon","the crow"}},{q="Por que MacKinley quer a luneta?",a="MacKinley diz que Jon-Jon lhe deve e quer receber de volta os objetos de valor que lhe são devidos.",al={"por que a luneta","dívida com mackinley","por que cobrar"}},{q="Onde fica a luneta de Jon-Jon?",a="MacKinley indica as Ruínas de Aboraz e as Ruínas de Jubuwal, a nordeste de Angra do Butim, onde os devedores vagam.",al={"localização da luneta","onde está jon-jon","encontrar a luneta dourada"}},{q="Que outros objetos de valor MacKinley quer?",a="MacKinley também procura o Pé-de-clava do Maury e o Anel Enorme do Chucky.",al={"outras dívidas","maury e chucky","três objetos de valor"}},{q="O que MacKinley diz sobre os devedores?",a="MacKinley diz que ouviu que os devedores foram amaldiçoados e enfeitiçados e agora vagam pelas ruínas da selva.",al={"por que estão nas ruínas","devedores amaldiçoados","o que aconteceu com eles"}}},fp="25,152,14.264.0,29.90.0,24.117.0,37.80.0,38.123.0,41.65.0,42.94.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Carregamento de Minério do Jardel",s="O Carregamento de Minério do Jardel é um caixote de minério que Bailor Manopedra transformaria em sua liga para o ferreiro Jardel Calmafonte. Transportada por caravana a partir do Pantanal, a entrega foi interceptada e saqueada por ogros Mo'grosh nas colinas a nordeste de Loch Modan.",h="O Carregamento de Minério do Jardel é um caixote de minério que Bailor Manopedra transformaria em sua liga...",kw={"liga","bailor manopedra","jardel calmafonte","carregamento de minério do jardel","loch modan","mo'grosh","the test of righteousness"},ang={["class:Paladin"]="Recuperar esta liga roubada dos ogros Mo'grosh é uma etapa vital na encomenda de Jardel Calmafonte, provando sua dedicação durante The Test of Righteousness.",["profession:Blacksmithing"]="A liga especializada de Bailor Manopedra representa uma metalurgia anã refinada, valorizada a ponto de Jardel Calmafonte recusar substitutos comuns para seu ofício."},sec={{t="Uma Entrega Emboscada",b="Destinado a ser refinado pelo anão Bailor Manopedra em sua liga especial, este minério foi originalmente prometido a Jardel Calmafonte para sua ferraria. Ao cruzar as montanhas rumo ao sul, do Pantanal para Loch Modan, a caravana de suprimentos foi violentamente emboscada pelos ogros Mo'grosh. O carregamento foi arrastado para a fortaleza selvagem dos ogros, deixando os guardas sobreviventes perecerem em decorrência de seus ferimentos e paralisando o projeto de ferraria de Jardel até que um aventureiro possa arrancá-lo de volta das mãos dos brutos."}},faq={{q="O que há dentro do carregamento?",a="O carregamento contém minério que o anão Bailor Manopedra refina em sua liga especial, prometida ao ferreiro Jardel Calmafonte para sua ferraria em Altaforja.",al={"o que há no carregamento de minério do jardel","que minério é este","conteúdo do minério de jardel"}},{q="Quem roubou o Carregamento de Minério do Jardel?",a="Os ogros Mo'grosh emboscaram a caravana de suprimentos enquanto ela viajava para o sul a partir do Pantanal, massacrando as escoltas e levando os caixotes de volta ao seu território a nordeste do Loch.",al={"quem pegou o carregamento de minério","quem o roubou","ogros carregamento de minério"}},{q="Quem é Bailor Manopedra?",a="Bailor Manopedra é um artesão anão estabelecido em Loch Modan e um velho amigo de Jardel Calmafonte. Ele providenciou o carregamento da liga antes que fosse tomado pelos ogros.",al={"bailor manopedra","quem é bailor"}},{q="Por que esse carregamento é importante para os paladinos?",a="Paladinos que realizam The Test of Righteousness buscam essa liga para ajudar Jardel Calmafonte a forjar uma arma consagrada da Luz.",al={"carregamento de minério do paladino","minério de the test of righteousness","por que os paladinos precisam disso"}}},fx={bb183b6f={q="O que é o Carregamento de Minério do Jardel?",a="O Carregamento de Minério do Jardel é um caixote de minério que o anão Bailor Manopedra iria refinar em sua liga especial para o ferreiro Jardel Calmafonte em Altaforja. A carga era transportada por uma caravana vinda do Pantanal antes de ser emboscada e tomada por ogros Mo'grosh no norte de Loch Modan.",al={"o que e o carregamento de minerio do jardel","informacoes sobre o carregamento de minerio do jardel","o que e o minerio de bailor"}},["84b5d642"]={q="De onde vem o Carregamento de Minério do Jardel e quem o fez?",a="O carregamento consiste em minério que estava a caminho por meio de uma caravana do Pantanal para Loch Modan, onde Bailor Manopedra iria refiná-lo em sua liga para seu velho amigo, Jardel Calmafonte. Ogros interceptaram o transporte e mataram seus guardas antes que ele chegasse.",al={"quem fez o carregamento de minerio do jardel","de onde veio o carregamento de minerio do jardel","origem do carregamento de minerio do jardel"}}},fp="21,201,20.399.0,28.134.0,32.168.0,24.157.0,43.126.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Carregamento de Minério Refinado do Jardel",s="O Carregamento de Minério Refinado do Jardel é um caixote de metal de alta qualidade preparado especificamente para o ferreiro Jardel Calmafonte. Adquirido como parte das provações sagradas de um paladino, ele fornece o material essencial necessário para forjar uma arma sagrada de virtude.",h="O Carregamento de Minério Refinado do Jardel é um caixote de metal de alta qualidade preparado...",kw={"bailor","altaforja","jardel calmafonte","arma de paladino","minério refinado","a prova da retidão"},ang={["class:Paladin"]="Obter este carregamento refinado testa a paciência e a dedicação de um paladino, servindo como uma das provações físicas necessárias para criar sua arma simbólica da Luz.",["profession:Blacksmithing"]="Todo artesão compreende que a forja de uma obra-prima exige lingotes impecáveis e cuidadosamente preparados, em vez de minério bruto do campo."},sec={{t="Os Materiais de um Ferreiro",b="Quando Jardel Calmafonte decidiu forjar uma arma digna de um paladino dedicado, materiais comuns não bastavam. O ferreiro precisava de uma variedade de componentes raros e específicos: uma Gema de Kor Purificada, Madeira de Carvalho de Pedralva resistente, seu próprio martelo de ferreiro perdido e um carregamento especializado de minério refinado. Esta remessa representa a base de metal para esse trabalho sagrado, levada a Altaforja para concluir A prova da retidão."}},faq={{q="Para que serve o Carregamento de Minério Refinado do Jardel?",a="O minério refinado é entregue a Jardel Calmafonte nos arredores de Altaforja como um dos quatro componentes essenciais necessários para forjar uma arma de obra-prima para paladinos que realizam A prova da retidão.",al={"propósito do minério refinado","o que jardel faz com o minério","uso do carregamento de minério"}},{q="Quem prepara o minério refinado?",a="O envio é organizado por meio de Bailor, que supervisiona o refino e o despacho do metal especializado de que Jardel Calmafonte precisa.",al={"quem fez o minério","minério de bailor","quem refina o minério de jardel"}},{q="Por que Jardel precisa deste carregamento específico?",a="Jardel Calmafonte pretende criar um símbolo do sacerdócio dos paladinos e da Luz, exigindo materiais superiores em vez de sobras comuns de forja. Este metal especialmente processado garante que a lâmina ou a cabeça do martelo possua o equilíbrio e a pureza dignos de um cavaleiro sagrado.",al={"por que minério especial","por que jardel não pode usar ferro comum","razão do minério refinado"}}},fx={ec64bb0f={q="O que é o Carregamento de Minério Refinado do Jardel?",a="O Carregamento de Minério Refinado do Jardel é um engradado de metal de alta qualidade e processado especialmente, preparado para o ferreiro Jardel Calmafonte. Destinado a uma forja fina, em vez de trabalho de forja comum, este minério refinado fornece a base metálica pura que Jardel requer para criar uma arma excepcional digna de um paladino dedicado da Luz.",al={"o que é o carregamento de minério refinado do jardel","lore do carregamento de minério refinado do jardel","o que é o minério refinado do jardel"}}},fp="29,158,19.241.0,47.167.0,29.114.0,44.240.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Martelo de Ferreiro de Jardel",s="O Martelo de Ferreiro de Jardel é uma preciosa relíquia de família passada ao ferreiro humano Jardel Calmafonte por seu pai. Sua recuperação dos salões assombrados da Bastilha da Presa Negra é essencial para forjar uma arma sagrada consagrada à Luz.",h="O Martelo de Ferreiro de Jardel é uma preciosa relíquia de família passada ao ferreiro humano Jardel...",kw={"dun morogh","altaforja","jardel calmafonte","arma de paladino","bastilha da presa negra","martelo de ferreiro","a prova da retidão"},ang={["class:Paladin"]="Recuperar a relíquia de família faz parte dos árduos testes de retidão, provando a determinação de um paladino em se aventurar em terras perigosas pelas ferramentas do artesanato sagrado.",["profession:Blacksmithing"]="Todo ferreiro compreende o vínculo sentimental e prático entre um mestre de forja e o martelo passado a ele por seus antepassados."},sec={{t="O Legado de um Artesão",b="Para um observador comum, o Martelo de Ferreiro de Jardel pode parecer mero ferro de ferreiro, mas para Jardel Calmafonte, ele representa tanto herança quanto destino. Herdada de seu pai, esta ferramenta é fundamental para a identidade de Jardel como mestre de forja nos arredores de Altaforja. Tendo ido parar de alguma forma dentro das muralhas de pedra abandonadas da Bastilha da Presa Negra, na Floresta de Pinhaprata, ela precisa ser recuperada antes que Jardel possa tentar sua obra-prima: uma arma sagrada digna de um campeão sagrado."}},faq={{q="Onde fica o Martelo de Ferreiro de Jardel?",a="O martelo repousa dentro das muralhas amaldiçoadas da Bastilha da Presa Negra, localizada nas florestas sombrias de Pinhaprata. Paladinos que realizam A prova da retidão devem se aventurar na fortaleza ocupada para recuperá-lo.",al={"localização do martelo","onde fica o martelo de jardel","onde encontrar o martelo de ferreiro de jardel"}},{q="Por que este martelo é tão importante para Jardel Calmafonte?",a="O martelo foi passado a Jardel por seu pai. Ele carrega um profundo valor sentimental e é o instrumento de que ele precisa para forjar sua melhor criação, uma arma sagrada da Luz.",al={"por que jardel quer o martelo","história do martelo de jardel calmafonte"}},{q="Para que o martelo é usado depois de recuperado?",a="Uma vez levado de volta a Jardel do lado de fora dos Portões de Altaforja, junto com madeira, minério e uma gema, ele o utiliza para forjar um armamento grandioso e sagrado para recompensar o paladino que o ajudou.",al={"o que o martelo cria","uso do martelo da prova da retidão"}}},fx={["126e648c"]={q="O que é o Martelo de Ferreiro de Jardel?",a="O Martelo de Ferreiro de Jardel é uma ferramenta de forja estimada que pertence ao mestre ferreiro Jardel Calmafonte. Além de seu uso prático na bigorna, carrega um profundo valor sentimental como uma herança passada diretamente para Jardel por seu pai.",al={"o que é o martelo de ferreiro de jardel","item martelo de jardel","sobre o martelo de ferreiro de jardel"}},["1df19239"]={q="De onde vem o Martelo de Ferreiro de Jardel e quem o fez?",a="O martelo foi passado para Jardel Calmafonte por seu pai. Seu criador exato não foi registrado, mas antes de você recuperá-lo, a herança tinha de alguma forma acabado longe de Altaforja, escondida dentro das muralhas sombrias da Bastilha da Presa Negra.",al={"de onde veio o martelo de jardel","quem fez o martelo de ferreiro de jardel","origem do martelo de ferreiro de jardel"}}},fp="24,93,20.244.0,42.172.0,51.148.0,43.150.0"}
P.entries["item:jungle-remedy"] = {n="Jungle Remedy",s="No Acampamento dos Rebeldes, Jungle Remedy pode ajudar a manter os feridos prontos para lutar contra as forças de Kurzen. O Sargento Yohwa precisa de remédios do Kurzen Compound para tratar os combatentes do acampamento.",h="No Acampamento dos Rebeldes, Jungle Remedy pode ajudar a manter os feridos prontos para lutar contra as...",kw={"headshrinkers","jungle remedy","kurzen","medicine men","acampamento dos rebeldes","sargento yohwa","selva do espinhaço","witch doctors"},sec={{t="Uma necessidade do acampamento",b="Os Kurzen Medicine Men usam Jungle Remedies para curar seus combatentes no Kurzen Compound. O Sargento Yohwa precisa deles no Acampamento dos Rebeldes, onde podem ajudar a manter seu próprio povo vivo e pronto para lutar."}},faq={{q="Para que serve Jungle Remedy?",a="O Sargento Yohwa precisa de Jungle Remedies para tratar os combatentes do Acampamento dos Rebeldes e mantê-los em condições de lutar contra Kurzen.",al={"uso de jungle remedy","para que serve o remédio"}},{q="Quem carrega Jungle Remedies?",a="Kurzen Medicine Men, Witch Doctors e Headshrinkers carregam Jungle Remedies. Jungle Fighters às vezes também os carregam.",al={"onde conseguir remédios","remédios de kurzen"}},{q="Por que o Sargento Yohwa precisa deles?",a="As forças de Kurzen usam os remédios para curar seus próprios combatentes, e o Sargento Yohwa precisa deles para cuidar dos feridos no Acampamento dos Rebeldes.",al={"por que yohwa os quer","remédios no acampamento dos rebeldes"}},{q="Onde posso encontrar Jungle Remedies?",a="Procure no Kurzen Compound, na Selva do Espinhaço; os curandeiros de Kurzen e outros combatentes carregam os remédios.",al={"localização dos remédios","onde ficam os remédios"}}},fp="13,185,15.194.0,26.121.0,28.116.0,34.135.0,33.107.0"}
P.entries["item:jungle-stalker-feather"] = {n="Jungle Stalker Feather"}
P.entries["item:kadrak-s-flag"] = {n="Bandeira de Kadrak",s="A Bandeira de Kadrak é um emblema da Horda entregue pelo batedor Kadrak na fronteira entre os Sertões e o Vale Gris. Ela serve como um aviso inequívoco aos elfos noturnos e às dríades do Morro das Torres de Pedra, fincada diretamente no Retiro do Gadanho após a eliminação da Chaveira Rynthariel.",h="A Bandeira de Kadrak é um emblema da Horda entregue pelo batedor Kadrak na fronteira entre os Sertões e o...",kw={"sertões","presença da horda","kadrak","bandeira de kadrak","rynthariel","cordilheira das torres de pedra","morro das torres de pedra","retiro do gadanho"},ang={["faction:Horde"]="Fincar este estandarte no fundo do Retiro do Gadanho é uma afirmação agressiva de força territorial, provando que a Horda contra-atacará diretamente santuários dos elfos noturnos quando provocada.",["race:NightElf"]="A profanação do Retiro do Gadanho com um estandarte rubro da Horda representa um insulto direto e uma provocação contra os protetores do Morro das Torres de Pedra."},sec={{t="Um Sinal de Desafio",b="As tensões estão altas ao longo das fronteiras de Kalimdor, onde mensageiros e sentinelas da Aliança rotineiramente testam os limites dos territórios sob o controle da Horda. Quando um pergaminho decodificado revela comunicações da dríade Rynthariel, a Chaveira do Retiro do Gadanho, Kadrak conclui que matá-la não é o bastante. Ele fornece este estandarte carmesim para ser fincado nas profundezas d'O Covil, no cume das Torres de Pedra. Ao fincar as cores da Horda dentro de um dos redutos montanhosos sagrados dos elfos noturnos, Kadrak pretende enviar uma mensagem clara: incursões pelos Sertões serão respondidas com represálias audaciosas em solo da Aliança."}},faq={{q="Para que serve a Bandeira de Kadrak?",a="A bandeira é fincada dentro do Retiro do Gadanho, no topo do Morro das Torres de Pedra, após abater Rynthariel, a Chaveira. Fincar o estandarte da Horda no reduto deles adverte os elfos noturnos contra o envio de mais batedores e mensageiros aos Sertões.",al={"objetivo da bandeira","por que fincar a bandeira","o que a bandeira faz"}},{q="Quem dá a bandeira a você?",a="Kadrak, um batedor orc posicionado no posto de vigia da fronteira entre o norte dos Sertões e o Vale Gris, dá o estandarte aos aventureiros da Horda como parte de sua campanha para proteger a região.",al={"quem dá a bandeira","onde pegar a bandeira","localização de kadrak"}},{q="Onde a bandeira é fincada?",a="O estandarte é fincado dentro do Retiro do Gadanho, um santuário cavernoso localizado nas encostas ocidentais do Morro das Torres de Pedra, na Cordilheira das Torres de Pedra.",al={"onde fincar a bandeira","local da bandeira","local da bandeira no retiro do gadanho"}},{q="Quem é Rynthariel?",a="Rynthariel é uma dríade que atua como Chaveira do Retiro do Gadanho. Ela coordena os mensageiros que cruzam o território da Horda até que Kadrak intercepta suas comunicações e ordena a sua morte.",al={"dríade rynthariel","quem é rynthariel","chaveira"}}},fx={["555b344d"]={q="O que é a Bandeira de Kadrak?",a="A Bandeira de Kadrak é um emblema da Horda, confiado a você pelo comandante do posto avançado orc Kadrak, na fronteira entre os Sertões e o Vale Gris. Ostentando as cores e o sigilo da Horda, serve como um marcador territorial inconfundível destinado a reivindicar terreno e transmitir uma mensagem intransigente de desafio às forças da Aliança que se aventuram pelo sul.",al={"o que é a bandeira de kadrak","bandeira de kadrak","sobre a bandeira de kadrak"}},["52bd9818"]={q="Por que Kadrak quer sua bandeira plantada no Retiro do Gadanho?",a="Kadrak quer que o estandarte seja cravado diretamente no coração do Retiro do Gadanho, no Morro das Torres de Pedra, após a morte da líder dríade Rynthariel. Plantar o estandarte da Horda dentro do santuário garante que quaisquer batedores sobreviventes ou simpatizantes da Aliança entendam que a invasão do território da Horda será respondida com retaliação decisiva e letal.",al={"por que plantar a bandeira de kadrak","por que kadrak quer que a bandeira seja colocada","propósito de plantar a bandeira"}}},fp="13,140,18.386.0,31.202.0,23.145.0,26.127.0,18.161.0"}
P.entries["item:karnitol-s-satchel"] = {n="Karnitol's Satchel",s="A bolsa de Karnitol guarda pertences procurados após o naufrágio do Karnitol em Desolação. Kreldig Ungor direciona a busca para os nagas Slitherblade ao longo da costa.",h="A bolsa de Karnitol guarda pertences procurados após o naufrágio do Karnitol em Desolação.",kw={"desolação","karnitol","bolsa de karnitol","kreldig ungor","nagas","ilha ranazjar","reclaimers","putren rochamalho","bolsa","slitherblade"},ang={["faction:Alliance"]="Os Reclaimers procuram os pertences de Karnitol, e Kreldig Ungor chama a recuperação deles de um grande serviço aos Reclaimers."},sec={{t="Entre os Slitherblade",b="Kreldig Ungor aponta o caminho até a Ilha Ranazjar, onde os nagas Slitherblade vivem entre ruínas de elfos noturnos sob o mar. Ele suspeita que os poderosos caçadores das marés e bruxas do mar possam ter reunido os pertences de Karnitol. A bolsa é recuperada com eles ao longo da costa de Desolação."},{t="De volta aos Reclaimers",b="Em Desolação, você devolve a bolsa recuperada a Kreldig Ungor, que chama isso de um grande serviço aos Reclaimers. Ele a envia a Putren Rochamalho em Altaforja. Putren diz que o baú foi destruído, mas os pertences estão presentes, e deixa que Karnitol avalie o estado deles."}},faq={{q="Quem está procurando a bolsa de Karnitol?",a="Kreldig Ungor direciona a busca pelos pertences de Karnitol em nome dos Reclaimers. Depois, a bolsa é levada a Putren Rochamalho em Altaforja.",al={"quem quer a bolsa","pertences de karnitol","bolsa para quem"}},{q="Onde posso encontrar a bolsa?",a="Os nagas Slitherblade ao longo da costa de Desolação podem estar com os pertences de Karnitol. Kreldig Ungor aponta o caminho até os caçadores das marés e as bruxas do mar perto da Ilha Ranazjar.",al={"onde está a bolsa","localização da bolsa","encontrar a bolsa de karnitol"}},{q="Quem são os Slitherblade?",a="Os Slitherblade são uma tribo de nagas que vive entre ruínas de elfos noturnos sob o mar, perto da Ilha Ranazjar, em Desolação.",al={"nagas slitherblade","nagas em desolação","quem vive na ilha ranazjar"}},{q="Quem recebe a bolsa em Altaforja?",a="Putren Rochamalho recebe a bolsa em Altaforja e diz que Karnitol pode avaliar se os pertences recuperados estão em boas condições.",al={"bolsa em altaforja","quem recebe a bolsa","bolsa de putren rochamalho"}},{q="O baú de Karnitol foi recuperado intacto?",a="Não. Putren Rochamalho diz que o baú foi destruído, embora os pertences estejam lá para Karnitol inspecionar.",al={"o que aconteceu com o baú","baú destruído","pertences de karnitol danificados"}}},fp="18,163,22.274.0,22.283.0,38.150.0,29.164.0,26.115.0,38.132.1,38.110.1"}
P.entries["item:keg-of-shindigger-stout"] = {n="Barril de Stout do Festeiro",s="Um Barril de Stout do Festeiro é um barril de potente cerveja anã fabricada e guardada pelos fuzileiros e soldados aquartelados dentro de Dun Garok. Desejado pela Real Sociedade de Boticários na Serraria Tarren, ele serve não como uma bebida noturna, mas como um veículo de entrega dissimulado para pragas recém-sintetizadas.",h="Um Barril de Stout do Festeiro é um barril de potente cerveja anã fabricada e guardada pelos fuzileiros e...",kw={"boticário lindolfo","dun garok","cerveja dos anões","elixir of agony","barril de stout do festeiro","stout do festeiro","serraria tarren"},ang={["faction:Horde"]="Atacar Dun Garok desestabiliza um perigoso ponto de apoio militar da Aliança situado nas colinas do sudeste de Contraforte de Eira dos Montes.",["race:Undead"]="Para os Renegados, roubar um barril da estimada cerveja anã é pura alquimia prática: o álcool mascara o odor e o sabor das misturas mortais desenvolvidas para Lady Sylvanas."},sec={{t="Um Favorito dos Anões",b="Dun Garok ergue-se como um formidável bastião anão no sudeste de Contraforte de Eira dos Montes, ferozmente mantido pelos anões de Altaforja. Dentro de seus quartéis e refeitórios entrincheirados, os defensores de coração forte compartilham barris de Stout do Festeiro para suportar o frio e o cerco desgastante contra os inimigos regionais. A bebida é encorpada e abundante, tornando-se essencial para a sobrevivência diária da guarnição."},{t="O Recipiente de Veneno do Boticário Lindolfo",b="Enquanto os anões consideram o Stout do Festeiro uma recompensa honesta após a batalha, o Boticário Lindolfo na Serraria Tarren o vê como um vetor ideal para o terror. Incumbido de desenvolver o sinistro Elixir of Agony dos Renegados, Lindolfo se recusa a testar sua fórmula letal em feras. Em vez disso, ele busca um barril intacto da cerveja para adulterá-lo com a beberagem, criando uma oferenda contaminada destinada aos fazendeiros humanos capturados mantidos na Serraria Tarren."}},faq={{q="Para que é usado o Stout do Festeiro?",a="O Boticário Lindolfo na Serraria Tarren quer o barril de stout para testar seu Elixir of Agony recém-refinado. Em vez de desperdiçar o veneno virulento em animais de laboratório, ele pretende adulterar a cerveja anã para realizar um teste de campo letal contra cobaias humanoides.",al={"por que obter stout do festeiro","objetivo do stout do festeiro","o que lindolfo faz com o barril"}},{q="Onde um Barril de Stout do Festeiro pode ser encontrado?",a="Barris do stout são armazenados nas profundezas da fortaleza anã de Dun Garok, situada no sudeste de Contraforte de Eira dos Montes. Eles normalmente podem ser encontrados nos refeitórios e nos aposentos inferiores dos quartéis ocupados pela infantaria anã.",al={"localização do barril","onde fica o stout do festeiro","encontrar o stout"}},{q="Quem fabrica o Stout do Festeiro?",a="Ele é fabricado e mantido pelos anões de Dun Garok, que mantêm uma guarnição fortemente fortificada em Contraforte de Eira dos Montes em nome de Altaforja.",al={"quem faz o stout do festeiro","é cerveja dos anões"}},{q="Por que o Boticário Lindolfo não fabrica seu próprio álcool para o teste?",a="Lindolfo pede um barril já mantido em Dun Garok para poder usar a cerveja em seu experimento; a missão não o descreve fabricando álcool ele mesmo.",al={"por que roubar cerveja dos anões","por que cerveja de dun garok"}}},fx={b55cb0ca={q="O que é um Barril de Stout do Festeiro?",a="Um Barril de Stout do Festeiro é um barril de potente cerveja anã mantido pelos anões de Altaforja estacionados na fortaleza de Dun Garok. Embora destinado a suprir os soldados anões durante sua mobilização no Contraforte de Eira dos Montes, sua bebida forte a torna um veículo ideal para os experimentos do Boticário Lindolfo em nome da Real Sociedade de Boticários.",al={"o que é o barril de stout do festeiro","informações sobre o barril de stout do festeiro","o que é a stout do festeiro"}}},fp="23,169,18.253.0,32.234.1,34.150.0,45.163.0,27.125.0,63.144.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Trago do Ken'zigla",s="O Trago do Ken'zigla é um tônico medicinal potente e de gosto ruim preparado por Ken'zigla na Cordilheira das Torres de Pedra. Ele é formulado para restaurar força suficiente a indivíduos gravemente feridos para que possam se mover sem sangrar até a morte.",h="O Trago do Ken'zigla é um tônico medicinal potente e de gosto ruim preparado por Ken'zigla na Cordilheira das...",kw={"acampamento taurajo","dogran","bruto logmar","trago do ken'zigla","ken'zigla","cordilheira das torres de pedra","missao da sucubo","sertões"},ang={["class:Warlock"]="Obter e entregar este trago é uma etapa essencial durante as provações para evocar e subjugar uma súcubo, provando a desenvoltura e as habilidades de rastreamento de um bruxo pelos Sertões.",["faction:Horde"]="Com o Acampamento Taurajo com falta de pessoal devido a patrulhas de coleta, o trago representa a única salvação para um agente capturado atrás das linhas inimigas dos javatuscos."},sec={{t="Um Remédio Amargo",b="Preparado por Ken'zigla na Cordilheira das Torres de Pedra, este potente preparado serve como um restaurador de emergência para aqueles à beira da morte. O tônico é extremamente forte e deve ser dosado com cuidado; beber mais de meia dose de uma vez traz o risco de fazer o paciente sangrar até a morte com o aumento súbito da circulação. Administrar metade fornece vigor bruto suficiente para se mover e fugir do perigo iminente, enquanto o restante deve aguardar até que o corpo se estabilize após uma noite inteira de descanso."},{t="Misericórdia nos Sertões",b="O trago desempenha um papel vital na busca por Dogran, um agente capturado e torturado por javatuscos ao norte do Acampamento Taurajo. Carregada por bruxos da Horda em busca da insígnia de um devorador de almas, a mistura amarga é entregue diretamente no acampamento hostil dos Crinamaris. Bebê-la dá a Dogran vitalidade suficiente para mancando escapar de seus captores, ainda que ferimentos graves tenham lhe custado permanentemente o uso de seus membros."}},faq={{q="Para que serve o Trago do Ken'zigla?",a="É um preparado medicinal potente criado para restaurar a força de indivíduos agonizantes ou gravemente feridos. Administrado corretamente, ele dá a uma pessoa ferida vigor suficiente para ficar de pé e escapar do cativeiro sem causar hemorragias fatais.",al={"o que faz o trago do ken'zigla","objetivo do trago","por que preciso do trago do ken'zigla"}},{q="Quem faz o trago?",a="Ele é preparado por Ken'zigla, um boticário ou herborista que reside na Cordilheira das Torres de Pedra e o preparou antecipando que alguém chegaria em busca de ajuda para Dogran.",al={"quem prepara o trago","quem e ken'zigla","localizacao de ken'zigla"}},{q="Por que o trago só deve ser tomado metade por vez?",a="A poção é excepcionalmente agressiva para o corpo. Meia dose confere vigor suficiente para se mover sem causar sangramento grave, enquanto a segunda metade deve aguardar até que o paciente descanse por uma noite para evitar um esforço fatal.",al={"como tomar o trago do ken'zigla","meia dose do trago","instrucoes do trago"}},{q="Quem recebe o trago?",a="Ele é levado no final das contas a Dogran, um agente mantido prisioneiro e gravemente ferido em um acampamento de javatuscos ao norte do Acampamento Taurajo nos Sertões.",al={"quem bebe o trago","quem e dogran","onde entregar o trago"}},{q="Por que bruxos são enviados para obter este remédio?",a="Bruxos da Horda que buscam subjugar uma súcubo são guiados até Dogran, que possui um item de profunda ressonância emocional. Ajudar a entregar o trago é necessário para alcançá-lo e garantir o que é necessário para o ritual de evocação.",al={"por que bruxos precisam disso","missao da sucubo trago","missao de bruxo ken'zigla"}}},fx={["6eadaa9a"]={q="O que é o Trago do Ken'zigla?",a="É uma bebida medicinal potente e de sabor horrível, preparada pelo boticário troll Ken'zigla na Cordilheira das Torres de Pedra. Criada para sustentar traumas graves, a mistura é poderosa o suficiente para restaurar a vitalidade de um soldado mortalmente ferido e permitir que ele se mova, embora deva ser administrada com grande cautela.",al={"o que é o trago","trago do ken'zigla","poção de ken'zigla"}},["42d17912"]={q="Por que o Trago do Ken'zigla é necessário?",a="Um orc chamado Dogran foi capturado e brutalmente torturado por homens-javalis nos Sertões. Sangrando e quase morto no cativeiro, ele não consegue sobreviver ou escapar sem a magia restauradora do trago. O Bruto Logmar no Acampamento Taurajo precisa desesperadamente do remédio para que Dogran possa suportar seus ferimentos tempo suficiente para fugir de seus captores.",al={"por que precisam do trago","quem precisa do trago do ken'zigla","por que fazer o trago"}}},fp="19,177,15.340.0,20.294.1,37.180.0,22.59.0,50.208.0,25.136.0,48.207.0"}
P.entries["item:khan-dez-hepah-s-head"] = {n="Khan Dez'hepah's Head",s="Khan Dez'hepah's Head prova que o líder Kolkar foi derrotado. Felgur Doiscortes quer usá-la para demonstrar força diante dos clãs de centauros.",h="Khan Dez'hepah's Head prova que o líder Kolkar foi derrotado.",kw={"centauro","desolação","cabeça de dez'hepah","felgur doiscortes","khan dez'hepah","kolkar","aldeia kolkar"},sec={{t="Prova de força",b="Por toda a Desolação, os clãs de centauros lutam entre si. Felgur Doiscortes teme que eles se tornem inimigos ferozes caso se unam, então envia você para enfraquecer os Kolkar derrotando seu líder, Khan Dez'hepah. A cabeça dele é a prova que Felgur pede que você traga de volta."}},faq={{q="Quem quer Khan Dez'hepah's Head?",a="Felgur Doiscortes pede que você leve Khan Dez'hepah's Head até ele na Desolação.",al={"quem quer isso","pedido de cabeça de felgur"}},{q="Por que Felgur quer a cabeça?",a="Felgur quer enfraquecer o clã Kolkar e demonstrar força aos clãs de centauros da Desolação.",al={"por que pegar a cabeça","para que serve"}},{q="Quem era Khan Dez'hepah?",a="Khan Dez'hepah era o líder do clã Kolkar na Desolação.",al={"quem é dez'hepah","líder kolkar"}},{q="Onde posso encontrar Khan Dez'hepah?",a="Khan Dez'hepah fica na Aldeia Kolkar, a nordeste de Felgur Doiscortes.",al={"onde fica dez'hepah","localização da aldeia kolkar"}}},fp="21,145,17.256.0,32.74.0,30.91.0,23.61.0,32.65.0"}
P.entries["item:khan-jehn-s-head"] = {n="Khan Jehn's Head",s="Khan Jehn's Head prova que o Khan Magram foi derrotado. Uthek, a Sábia, da Aldeia Gelkis, exige isso como sinal de amizade com o clã Gelkis.",h="Khan Jehn's Head prova que o Khan Magram foi derrotado.",kw={"centauro","desolação","magia da terra","gelkis","jehn","khan jehn","khan jehn's head","magram","uthek, a sábia"},sec={{t="Um Sinal de Amizade",b="Na Desolação, Uthek, a Sábia, pede que você leve Khan Jehn's Head à Aldeia Gelkis. Jehn lidera os centauros Magram rivais, e Uthek diz que a terra lhe conta que o clã está enfraquecendo. Os Gelkis querem a morte do Khan inimigo e esperam que você prove estar ao lado deles."},{t="A Queda do Khan",b="Quando você retorna com Khan Jehn's Head, Uthek chama Jehn de forte, mas tolo. Ele acredita que a magia da terra é mais poderosa que a força de Jehn. Com o líder Magram morto, Uthek espera que o clã caia e diz que os Gelkis governarão a Desolação."}},faq={{q="Quem quer Khan Jehn's Head?",a="Uthek, a Sábia, da Aldeia Gelkis, pede que você leve Khan Jehn's Head como prova de amizade com os Gelkis.",al={"quem quer a cabeça","cabeça de uthek","pedido dos gelkis"}},{q="Quem foi Khan Jehn?",a="Khan Jehn era o líder dos centauros Magram, rivais do clã Gelkis.",al={"quem é jehn","khan magram","khan jehn"}},{q="Por que os Gelkis querem Jehn morto?",a="Uthek diz que os Magram estão enfraquecendo e pede que você mate o Khan deles. Ele acredita que os Gelkis poderão governar quando Jehn se for.",al={"por que matar jehn","gelkis contra magram","por que jehn"}},{q="Onde levo Khan Jehn's Head?",a="Leve Khan Jehn's Head até Uthek, a Sábia, na Aldeia Gelkis, na Desolação.",al={"para onde levar a cabeça","levar a cabeça de jehn","localização de uthek"}},{q="O que Uthek diz depois da queda de Jehn?",a="Uthek chama Jehn de forte, mas tolo, e diz que os Magram cairão sem seu líder. Ele espera que os Gelkis governem.",al={"conclusão de uthek","o que acontece depois de jehn","governo dos gelkis"}}},fp="16,152,20.273.0,15.231.1,27.107.0,18.78.0,33.122.0,34.72.0,37.118.1"}
P.entries["item:khan-shaka-s-head"] = {n="Khan Shaka's Head",s="Khan Shaka's Head é a cabeça do khan Gelkis, procurada por Warug, dos Magram, na Desolação. Ela representa a força dos Magram contra o clã rival.",h="Khan Shaka's Head é a cabeça do khan Gelkis, procurada por Warug, dos Magram, na Desolação.",kw={"centauro","desolação","gelkis","khan shaka","magram","aldeia magram","cabeça de shaka","warug"},sec={{t="A cabeça de um khan",b="Warug, da Aldeia Magram, quer a cabeça de Khan Shaka depois que você ajudou os Magram. Shaka lidera os Gelkis, e Warug pretende manter a cabeça em uma estaca. Ele quer que Shaka veja a força dos Magram."}},faq={{q="Quem é Khan Shaka?",a="Khan Shaka é o khan dos centauros Gelkis na Desolação.",al={"shaka","identidade de khan shaka","khan dos gelkis"}},{q="Quem quer a cabeça de Khan Shaka?",a="Warug a quer na Aldeia Magram, depois que você provar seu valor aos Magram.",al={"quem quer a cabeça de shaka","warug quer a cabeça","pedido dos magram"}},{q="Por que Warug quer a cabeça?",a="Warug quer manter a cabeça de Khan Shaka em uma estaca para que Shaka veja a força dos Magram.",al={"por que querem a cabeça de shaka","motivo de warug","força dos magram"}},{q="Para onde a cabeça de Khan Shaka será levada?",a="Você deve levar a cabeça de Khan Shaka para Warug, na Aldeia Magram, na Desolação.",al={"onde levar a cabeça","cabeça para warug","cabeça na aldeia magram"}}},fp="17,153,13.201.0,18.57.0,30.79.0,29.94.1,35.74.0"}
P.entries["item:khazgorm-s-journal"] = {n="Diário de Khazgorm",s="O Diário de Khazgorm é um livro de registros de campo pessoal mantido pelo Prospector Khazgorm, o líder da escavação dos anões de Altaforja em Bael Modan, nos Sertões Meridionais. Ele detalha as atividades invasivas da Liga dos Exploradores em terras reivindicadas pela tribo tauren Agulha de Pedra.",h="O Diário de Khazgorm é um livro de registros de campo pessoal mantido pelo Prospector Khazgorm, o líder da...",kw={"bael modan","sertões","anão","liga dos exploradores","gann agulha de pedra","diário","khazgorm","prospector"},ang={["faction:Horde"]="Recuperar este livro ajuda Gann Agulha de Pedra a defender Kalimdor de expedições invasivas da Aliança adentrando o território soberano da Horda.",["race:Tauren"]="O diário serve como evidência tangível da insensibilidade dos invasores de Altaforja, que explodiram terras ancestrais sagradas sem consideração pela tribo Agulha de Pedra."},sec={{t="Um Registro de Destruição",b="O diário pertence ao Prospector Khazgorm, que comanda o maquinário pesado e as operações de detonação que escavam as encostas dos Sertões Meridionais. Longe da busca idílica por conhecimento professada pela Liga dos Exploradores, as anotações refletem uma campanha implacável de escavação que desalojou a tribo Agulha de Pedra. As tentativas dos taurens de alcançar uma resolução pacífica foram rejeitadas, tornando o diário um valioso troféu de guerra para Gann Agulha de Pedra em sua busca para entender e desmantelar a presença dos anões em sua terra natal."},{t="Uma Mudança de Tática",b="Recuperado dos restos mortais de Khazgorm entre as tendas e pilares do sítio de escavação, o livro oferece a Gann informações cruciais sobre a estrutura, o equipamento e as vulnerabilidades da expedição dos anões. A análise dos escritos pessoais do prospector permite que Gann passe de simplesmente repelir os trabalhadores para executar sabotagens direcionadas contra o maquinário da escavação, consolidando o diário como um ponto de virada na luta por Bael Modan."}},faq={{q="A quem pertence o diário?",a="O diário pertence ao Prospector Khazgorm, um líder da escavação dos anões de Altaforja estabelecida no sítio de escavação de Bael Modan, nos Sertões Meridionais.",al={"quem é o dono do diário","khazgorm","prospector khazgorm"}},{q="Por que Gann Agulha de Pedra quer este livro?",a="Gann Agulha de Pedra busca o diário para inspecionar os planos e segredos dos invasores anões que desalojaram sua tribo, usando as próprias anotações de Khazgorm para coordenar novos ataques contra o acampamento de Bael Modan.",al={"por que gann quer o diário","diário da missão de gann","livro da reivindicação de gann"}},{q="Onde o diário pode ser encontrado?",a="O diário é carregado pelo próprio Prospector Khazgorm, que pode ser encontrado entre as tendas e pilares de pedra do sítio de escavação ativo logo ao sul de Bael Modan.",al={"onde fica o diário de khazgorm","encontrar o diário de khazgorm","localização de khazgorm"}},{q="O que o diário revela sobre os anões?",a="Ele expõe o lado menos erudito da Liga dos Exploradores, mostrando como a busca por relíquias enterradas e herança dos Titãs frequentemente ocorre às custas diretas e violentas de tribos indígenas, como os taurens Agulha de Pedra.",al={"liga dos exploradores sertões","segredos da escavação dos anões","propósito de bael modan"}}},fx={["6ed76dba"]={q="De onde vem o Diário de Khazgorm e quem o escreveu?",a="O diário foi escrito pelo Prospector Khazgorm, um líder entre os escavadores anões da Liga dos Exploradores estacionados em Bael Modan, nos Sertões Meridionais. Khazgorm manteve o livro para registrar as descobertas e os assuntos diários de sua expedição enquanto percorria as terras ancestrais dos tauren da Espiral de Pedra.",al={"origem do diário de khazgorm","quem escreveu o diário de khazgorm","de onde veio o diário de khazgorm"}}},fp="18,180,23.415.0,18.357.1,31.122.0,40.187.0,31.123.0,47.163.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Diário de Filipe Pinel",s="O Diário de Filipe Pinel é um relatório de inteligência recuperado por agentes da AVIN da torre dos Défias no nordeste de Cerro Oeste. Mantido seguro dentro de um baú enviado da Floresta do Crepúsculo, ele detalha as tentativas secretas da Irmandade de preparar misturas alquímicas capazes de reanimar os mortos.",h="O Diário de Filipe Pinel é um relatório de inteligência recuperado por agentes da AVIN da torre dos Défias no...",kw={"torre dos defias","bau da floresta do crepusculo","diario","klaven mortwake","mathias shaw","venenos","avin","zanzil"},ang={["class:Rogue"]="Infiltrar-se na torre para capturar o diário de Mortwake serve como um teste decisivo para ladinos da AVIN, demonstrando proficiência em arrombamento, furtividade e introduzindo a arte de preparar venenos letais.",["faction:Alliance"]="O diário fornece aos mestres espiões de Ventobravo uma prova definitiva de que a revolta dos Défias se estende além de trabalhadores descontentes, revelando laços com médicos-bruxos trolls e necromancia alquímica."},sec={{t="Uma Fórmula Macabra",b="A AVIN há muito vigiava a torre dos Défias que se ergue ao longo dos cumes do norte de Cerro Oeste, notando remessas estranhas chegando das fronteiras sombrias da Floresta do Crepúsculo ao lado de sentinelas deformadas e não humanas. O diário encontrado dentro do baú mais alto pertencia a Klaven Mortwake e desvenda o propósito por trás dessas entregas. Mortwake registrou pesquisas alquímicas detalhando como alquimistas associados aos trolls Zanzil em Selva do Espinhaço descobriram um método para erguer zangões mortos-vivos irracionais usando venenos e misturas especializadas, uma prática que A Irmandade Défias procurava duplicar para suas próprias fileiras."},{t="Informações para a AVIN",b="O Mestre Mathias Shaw, líder do serviço de inteligência de Ventobravo, priorizou a recuperação do diário de Mortwake para desvendar a rede mais ampla de alianças da Irmandade. As anotações confirmam não apenas experimentos sombrios de reanimação, mas também o apoio logístico ilícito conectando a Floresta do Crepúsculo, a Empreendimentos S.A. e os Défias. Para agentes ladinos a serviço da coroa, a recuperação dessa pesquisa sombria marca a transição crucial para o domínio da arte dos venenos."}},faq={{q="O que é o Diário de Filipe Pinel?",a="É um caderno de pesquisas compilado por Klaven Mortwake, um agente que opera dentro da torre dos Défias no nordeste de Cerro Oeste. Ele contém anotações sobre necromancia alquímica e rotas de suprimentos ilícitas.",al={"o que e o diario de klaven","diario de mortwake","o que e este item"}},{q="Onde o diário é encontrado?",a="Ele está trancado dentro de um Baú da Floresta do Crepúsculo no último andar da torre dos Défias no norte de Cerro Oeste, guardado por sentinelas mortas-vivas e acessível apenas com uma chave obtida de um dos guardas monstruosos de Klaven.",al={"onde encontrar o diario de klaven","localizacao do diario de klaven","localizacao do bau da floresta do crepusculo"}},{q="Quais segredos estão escritos dentro do diário?",a="O texto revela que os trolls Zanzil da Selva do Espinhaço desenvolveram poções tóxicas capazes de erguer e controlar os mortos, uma receita letal que A Irmandade Défias tentava ativamente adquirir e utilizar.",al={"o que diz o diario","segredos do diario","veneno de zanzil"}},{q="Quem quer este diário?",a="O Mestre Mathias Shaw, líder da agência de inteligência AVIN de Ventobravo, solicita o documento para monitorar a logística dos Défias e instruir os agentes da coroa sobre os perigos e usos de venenos táticos.",al={"quem entrega o diario de klaven","para quem entrego o diario","diario de mathias shaw"}}},fx={["887d3337"]={q="De onde vem o Diário de Filipe Pinel e quem o escreveu?",a="O diário pertence a Filipe Pinel, que supervisionava a fortaleza da The Defias Brotherhood na torre de Cerro Oeste. Ele foi enviado junto com guardas mortos-vivos sinistros e um baú vindo da Floresta do Crepúsculo, detalhando segredos alquímicos sombrios originários dos trolls de Zanzil, o Exilado, na Selva do Espinhaço.",al={"quem escreveu o diário de filipe pinel","origem do diário de filipe pinel","de onde o filipe pinel conseguiu o diário"}}},fp="25,137,18.586.1,21.348.0,34.203.0,27.201.0,44.188.0,23.183.0"}
P.entries["item:kodo-bone"] = {n="Kodo Bone",s="Ossos de kodo do Cemitério dos Kodos da Desolação são valiosos para Bibbly Ferrafivela. Ele vê muitos usos para eles, de móveis e instrumentos a pólvora explosiva.",h="Ossos de kodo do Cemitério dos Kodos da Desolação são valiosos para Bibbly Ferrafivela.",kw={"bibbly ferrafivela","coletor de ossos","desolação","osso de kodo","ossos de kodo","cemitério dos kodos","barraco do kormek","aldeia pescassombra"},sec={{t="Um negócio de goblin",b="Bibbly Ferrafivela, no Barraco do Kormek, procura ossos de kodo do Cemitério dos Kodos, ao sul de sua casa. Ele diz que os clientes fazem móveis, instrumentos musicais e pólvora explosiva com eles. Uma caravana leva seus ossos até a Aldeia Pescassombra, e Bibbly espera que o negócio o deixe rico."}},faq={{q="Quem quer ossos de kodo?",a="Bibbly Ferrafivela, no Barraco do Kormek, quer ossos de kodo do Cemitério dos Kodos.",al={"comprador de ossos de kodo","quem quer os ossos"}},{q="Para que servem os ossos de kodo?",a="Bibbly diz que seus clientes fazem móveis, instrumentos musicais e pólvora explosiva com ossos de kodo.",al={"usos dos ossos de kodo","o que fazem com os ossos"}},{q="Para onde a caravana leva os ossos?",a="Bibbly diz que uma caravana vende seus ossos de kodo na Aldeia Pescassombra.",al={"caravana de ossos","para onde vão os ossos"}}},fp="9,158,18.273.0,21.76.0,29.99.0,38.65.0"}
P.entries["item:kodo-horn"] = {n="Chifre de Kodo",s="Chifres de Kodo são reagentes naturais resistentes obtidos das feras que vagueiam pelas extensões setentrionais dos Sertões. Para os druidas Cenarianos, sua composição densa fornece a força e a potência necessárias para misturas herbais experimentais, especialmente na confecção de unguentos curativos para tratar a vida selvagem envenenada.",h="Chifres de Kodo são reagentes naturais resistentes obtidos das feras que vagueiam pelas extensões...",kw={"sertões","cenariano","earthroot","gazela","chifre de kodo","veneno","tonga runa totem"},ang={["class:Druid"]="Para os jovens druidas da Horda, reunir esses chifres é um rito de passagem crucial sob a tutela de Tonga Runa Totem, conduzindo ao domínio inato sobre os venenos da natureza.",["race:Tauren"]="Os taurens têm grande reverência pelos kodos, retirando deles apenas com reverência e propósito — neste caso, para proteger o delicado ecossistema dos Sertões."},sec={{t="Um Reagente das Planícies",b="Embora os kodos sejam reverenciados em todos os Sertões pelos taurens por sua resistência e força, seus chifres têm valor medicinal prático. Tonga Runa Totem, trabalhando a partir da Encruzilhada, utiliza chifres inteiros para reforçar a potência de seus remédios herbais. Lascas e fragmentos não bastam para refinar esses unguentos; apenas chifres intactos colhidos de kodos adultos que vagam pelas planícies áridas possuem força suficiente para sustentar a cura."}},faq={{q="Para que servem os Chifres de Kodo?",a="Tonga Runa Totem os usa junto com Earthroot e água pura para preparar um unguento curativo. Essa mistura é formulada para tratar gazelas envenenadas pelos Sertões, servindo como uma etapa crítica no treinamento de um druida para dominar remédios naturais contra venenos.",al={"propósito do chifre de kodo","por que coletar chifres de kodo","uso do chifre de kodo"}},{q="Onde esses chifres são coletados?",a="Eles são obtidos de Barrens Kodos e Lost Barrens Kodos que vagam pelas extensões ao norte dos Sertões, geralmente encontrados pastando entre a Encruzilhada e a vegetação rasteira ao redor.",al={"onde encontrar chifres de kodo","localização do chifre de kodo","quais kodos concedem chifres"}},{q="Por que os druidas não podem usar fragmentos de chifre?",a="Tonga Runa Totem ressalta que meras lascas e fragmentos carecem da potência necessária para equilibrar adequadamente o unguento. O remédio exige chifres inteiros e intactos para criar doses fortes o suficiente para combater toxinas virulentas.",al={"por que não chifres quebrados","lascas de chifre"}},{q="Caçar kodos é considerado respeitoso para um druida?",a="Sim, desde que sirva ao equilíbrio maior da natureza. Druidas tiram da terra e de suas criaturas apenas o necessário para curar males maiores, como o envenenamento misterioso que aflige os rebanhos nativos de gazelas.",al={"druida caçando kodos","equilíbrio e kodos"}}},fx={f5876d60={q="O que é um Chifre de Kodo?",a="É um chifre intacto colhido dos enormes kodos que vagam pelas savanas do norte dos Sertões. Embora frequentemente utilizado em artesanato ou ferramentas tribais, chifres inteiros e resistentes são valorizados por xamãs e druidas como potentes reagentes alquímicos, capazes de infundir misturas medicinais com forte força natural.",al={"o que é um chifre de kodo","chifre de kodo","sobre o chifre de kodo"}},["062d3e91"]={q="De onde vêm os Chifres de Kodo?",a="Esses chifres vêm diretamente dos kodos dos Sertões que pastam nas planícies áridas. Derrubar uma dessas feras formidáveis permite que caçadores e druidas reivindiquem um chifre intacto, desde que não tenha sido despedaçado ou gasto em meras lascas e fragmentos.",al={"de onde vem o chifre de kodo","origem do chifre de kodo","como obter o chifre de kodo"}}},fp="9,116,23.263.0,29.184.0,32.146.0,44.156.0,51.166.0"}
P.entries["item:kodo-kombobulator"] = {n="Kodoagrupandador",s="O Kodoagrupandador permite que Smid Rabiscafuso dome kodos envelhecidos em Desolação. Ele o usa para fornecer animais para a estrada a uma parceria de caravanas.",h="O Kodoagrupandador permite que Smid Rabiscafuso dome kodos envelhecidos em Desolação.",kw={"kodo envelhecido","caravana","desolação","kodo","kodoagrupandador","smid rabiscafuso","domar"},ang={["profession:Engineering"]="Como engenheiro, você pode reconhecer a engenhoca goblin por trás do dispositivo de Smid Rabiscafuso para controlar kodos envelhecidos."},sec={{t="Um Dispositivo Goblin",b="No Acampamento do Rabiscafuso, em Desolação, Smid Rabiscafuso empresta o Kodoagrupandador para domar kodos antigos ou envelhecidos. O dispositivo dá um choque em cada animal e o faz segui-lo, fornecendo montarias novas para a caravana local. Smid espera que a parceria lhe traga um bom lucro."}},faq={{q="O que o Kodoagrupandador faz?",a="O Kodoagrupandador doma kodos antigos ou envelhecidos e faz com que sigam Smid Rabiscafuso.",al={"dispositivo para kodos","para que serve o agrupandador"}},{q="Quem criou o Kodoagrupandador?",a="Smid Rabiscafuso diz que aprendeu a rejuvenescer e controlar kodos envelhecidos e moribundos com seu Kodoagrupandador.",al={"quem é dono da coisa de kodo","dispositivo do smid"}},{q="Por que Smid quer kodos domados?",a="Smid, o dono da caravana Cork, e Rigger formaram uma parceria em torno da habilidade dele de domar kodos. A caravana depende do fornecimento de Smid.",al={"por que domar kodos","kodos para a caravana"}},{q="Onde posso encontrar o Kodoagrupandador?",a="Smid Rabiscafuso, no Acampamento do Rabiscafuso em Desolação, fornece o Kodoagrupandador para seu trabalho com kodos envelhecidos.",al={"localização do agrupandador","onde fica smid"}}},fp="17,144,17.268.0,35.92.0,31.110.0,32.130.0,39.116.0"}
P.entries["item:kodo-liver"] = {n="Fígado de Kodo",s="Um Fígado de Kodo é um órgão pesado extraído dos kodos gigantescos que vagam pelas planícies dos Sertões. Embora esteja longe de ser um prato comum da culinária tradicional, o Cervejeiro Drohn em Vila Catraca precisa dele como um ingrediente vital para fermentar uma exótica cerveja trogg aprendida com o cervejeiro errante Chen Malte do Trovão.",h="Um Fígado de Kodo é um órgão pesado extraído dos kodos gigantescos que vagam pelas planícies dos Sertões.",kw={"sertões","fermentação","chen malte do trovão","drohn","kodo","fígado de kodo","vila catraca","cerveja trogg"},ang={["profession:Cooking"]="Embora a carne de kodo comum forneça rações básicas em toda a região central de Kalimdor, o fígado de kodo é considerado fétido e pungente demais para o preparo doméstico padrão — tornando sua inclusão na cerveja trogg de Vila Catraca ainda mais notória.",["race:Tauren"]="Os taurens honram cada parte dos kodos que caçam, mas até mesmo os seus corredores da estepe mais experientes olham com desdém para os goblins e forasteiros que transformam as vísceras sagradas dos kodos em uma cerveja exótica em Vila Catraca."},sec={{t="Um Reagente de Fermentação Bizarro",b="Os grandes kodos dos Sertões são caçados principalmente por taurens e predadores errantes devido aos seus couros resistentes e carne nutritiva. Contudo, um fígado de kodo fresco serve a um propósito muito mais excêntrico na cidade portuária de Vila Catraca. O Cervejeiro Drohn utiliza o órgão juntamente com glândulas salivares de falcão-do-trovão e glândulas de relâmpago para recriar uma bebida potente que Chen Malte do Trovão lhe ensinou: a cerveja trogg. Drohn afirma que essa mistura incomum tem um efeito formidável, oferecendo aos viajantes aventureiros uma beberagem encorpada saída diretamente das terras selvagens do centro de Kalimdor."}},faq={{q="Para que serve um Fígado de Kodo?",a="Um Fígado de Kodo é entregue ao Cervejeiro Drohn em Vila Catraca. Ele o incorpora a uma potente receita de cerveja trogg ensinada originalmente pelo famoso cervejeiro pandaren Chen Malte do Trovão.",al={"propósito do fígado de kodo","por que precisa de fígado de kodo","para que serve o fígado de kodo"}},{q="Quais criaturas concedem um Fígado de Kodo?",a="Ele pode ser extraído de vários kodos que vagam pela savana aberta dos Sertões, incluindo kodos dos Sertões comuns, kodos lanosos, kodos perdidos, kodos maiores e feras raras como Lakota'mani e Brontus.",al={"onde conseguir fígado de kodo","quem dropa fígado de kodo","fonte de fígado de kodo"}},{q="Por que alguém colocaria órgãos de animais na cerveja?",a="O Cervejeiro Drohn produz suas bebidas de acordo com receitas exóticas e excêntricas transmitidas por Chen Malte do Trovão. No caso da cerveja trogg, órgãos crus como fígados de kodo e glândulas elementais conferem à bebida seu famoso impacto e sabor marcante e agressivo.",al={"por que fígado na cerveja","fígado de kodo no álcool"}}},fx={a4c717e9={q="O que é um Fígado de Kodo?",a="É um órgão interno colhido dos enormes kodos de pele grossa que vagam pelas planícies dos Sertões. Embora não seja um prato típico de taverna, sua natureza potente o torna um componente valioso para cervejeiros excêntricos que criam misturas com um sabor verdadeiramente lendário.",al={"o que é um fígado de kodo","lore do fígado de kodo","fígado de kodo"}},c325e464={q="De onde vem um Fígado de Kodo?",a="É colhido diretamente dos kodos selvagens que vagam pela savana dos Sertões, desde feras errantes comuns até gigantes antigos como Lakota'mani e Brontus. Caçadores e aventureiros o retiram após derrubarem as enormes criaturas.",al={"onde obter fígado de kodo","quem derruba fígado de kodo","fonte do fígado de kodo"}},["328036a8"]={q="Por que o Cervejeiro Drohn quer um Fígado de Kodo?",a="O Cervejeiro Drohn em Vila Catraca procura um fígado fresco para preparar uma receita não convencional de cerveja de trogg ensinada a ele pelo mestre cervejeiro pandaren errante, Chen Malte do Trovão. Combinado com glândulas de relâmpago e saliva de falcão-trovão, o fígado dá à potente bebida seu toque característico.",al={"por que o drohn precisa de fígado de kodo","quem quer fígado de kodo","uso do fígado de kodo na missão"}}},fp="10,128,25.371.0,30.101.0,35.127.0,42.165.0"}
P.entries["item:kodobane-s-head"] = {n="Cabeça do Findekodo",s="A Cabeça do Findekodo é a cabeça decepada de Barak Kodobane, um astuto chefe centauro Kolkar. Tomada como prova de sua morte, ela é levada ao senhor da guerra orc Regthar Portões-da-morte para mostrar que a ameaça dos centauros perto d'Os Charcos Esquecidos foi aniquilada.",h="A Cabeça do Findekodo é a cabeça decepada de Barak Kodobane, um astuto chefe centauro Kolkar.",kw={"barak","sertões","centauro","encruzilhada","portões-da-morte","os charcos esquecidos","kodobane","kolkar","regthar"},ang={["faction:Horde"]="As encruzilhadas dos Sertões servem como a ligação terrestre vital entre Orgrimmar e Penhasco do Trovão; suprimir líderes centauros como Kodobane é essencial para manter as rotas de caravanas seguras.",["race:Tauren"]="Por gerações, os centauros levaram os taurens nômades por Kalimdor à beira da extinção. Abater Barak Kodobane vinga séculos de derramamento de sangue e protege os pastos de Mulgore e dos Sertões."},sec={{t="Um Troféu de Guerra",b="Os centauros Kolkar dos Sertões historicamente foram um estorvo fragmentado e desorganizado, mas a ascensão de senhores da guerra ambiciosos ameaça unir seus bandos saqueadores em um exército. Barak Kodobane estabeleceu seu acampamento nas águas verdejantes d'Os Charcos Esquecidos, cortando recursos vitais do oásis e saqueando caminhos próximos. Regthar Portões-da-morte, instalado em um abrigo a oeste da Encruzilhada, exige sua cabeça decepada como prova inegável de que este comandante não pode mais reunir seus parentes brutais contra a Horda."}},faq={{q="Quem foi Barak Kodobane?",a="Barak Kodobane era um chefe proeminente entre os centauros Kolkar. Diferente de muitos dos seus parentes indisciplinados, Barak possuía a astúcia e a presença necessárias para organizar bandos de guerra, montando acampamento ao redor d'Os Charcos Esquecidos para impor o domínio Kolkar sobre o norte dos Sertões.",al={"barak kodobane","quem é kodobane","história de barak"}},{q="Por que Regthar Portões-da-morte quer a cabeça dele?",a="Regthar Portões-da-morte tem a missão de proteger o território da Horda nos Sertões. Como os centauros costumam ser desunidos, líderes com visão tática genuína são marcados para eliminação. Exigir a cabeça de Kodobane garante que o chefe está morto, e não simplesmente dispersado.",al={"por que pegar a cabeça","cabeça regthar portões-da-morte","recompensa de kodobane"}},{q="Onde Barak Kodobane é encontrado?",a="Barak Kodobane monta seu acampamento perto do oásis ao norte conhecido como Os Charcos Esquecidos, a noroeste da Encruzilhada nos Sertões.",al={"localização de barak","onde fica kodobane","surgimento de barak"}},{q="Matar Barak põe fim à ameaça Kolkar?",a="Não. Barak Kodobane é apenas o primeiro de vários senhores da guerra a arregimentar os Kolkar. Sua morte desestabiliza a presença deles n'Os Charcos Esquecidos, mas outros líderes como Verog, o Dervixe e Hezrul Marca de Sangue continuam a comandar a agressão dos centauros por todos os Sertões.",al={"centauros foram derrotados","o que acontece após a morte de barak"}}},fx={["891c4b09"]={q="O que é a Cabeça do Findekodo?",a="É a cabeça decepada de Barak Findekodo, um dos chefes proeminentes entre os centauros Kolkar nos Sertões. Mantida como prova física da morte do chefe, ela significa um golpe decisivo contra a ameaça coordenada dos centauros que aterrorizavam os assentamentos da Horda perto de The Forgotten Pools.",al={"o que é a cabeça do findekodo","item cabeça de barak findekodo","história da cabeça de barak"}}},fp="15,171,15.418.0,23.242.0,41.246.0,30.114.0,42.231.0"}
P.entries["item:kravel-s-crate"] = {n="Caixote de Kravel",s="O Caixote de Kravel é um pacote pesado enviado por Kravel Barbakarvão a partir do Circuito da Ilusão, na Chapada Cintilante. Destinado à expedição de Nesingwary na Selva do Espinhaço, ele contém munição de caça especializada projetada para abater as presas mais mortais da selva.",h="O Caixote de Kravel é um pacote pesado enviado por Kravel Barbakarvão a partir do Circuito da Ilusão, na...",kw={"munição","rosarães guima","kravel barbakarvão","caixote de kravel","circuito da ilusão","chapada cintilante","selva do espinhaço"},ang={["class:Hunter"]="O caixote contém munição pesada especializada, projetada especificamente para rifles de caça anões de alta qualidade, feita sob medida para expedições de caça grossa.",["race:Dwarf"]="A entrega é um assunto inteiramente entre anões, conectando os negócios de Kravel Barbakarvão nas salinas com o renomado grupo de caça de Nesingwary nos Reinos do Leste."},sec={{t="Uma Entrega para a Selva",b="Entregue pelo astuto empreendedor Kravel Barbakarvão no Circuito da Ilusão, o Caixote de Kravel representa uma transação comercial inacabada entre continentes. Encomendada semanas antes por um cliente anão abastado, a remessa atrasou o bastante para que seu comprador partisse de Kalimdor por completo. Em vez de perder o prestígio com um cliente rico que já havia pago pelo reenvio, Kravel confia a aventureiros que passam por ali o transporte do caixote até o norte da Selva do Espinhaço."},{t="Munição de Calibre Especial",b="Apesar de sua aparência comum e da crosta de poeira de sal acumulada na Chapada Cintilante, o caixote transporta uma carga letal: munição pesada de calibre especial, feita sob medida para rifles de caça. Ao ser recebida no acampamento da expedição ao norte de Grom'gol, o destinatário observa que esses projéteis potentes são muito valorizados por caçadores de animais de grande porte e vitais para a sobrevivência contra os predadores que rondam sob a copa da selva."}},faq={{q="O que há dentro do Caixote de Kravel?",a="O caixote está cheio de munição de caça de calibre especial. Os projéteis de grosso calibre destinam-se especificamente a rifles para caça grossa usados para abater feras perigosas na natureza selvagem.",al={"o que tem no caixote","conteúdo do caixote","o que há no caixote de kravel"}},{q="Quem enviou o Caixote de Kravel?",a="Ele é enviado por Kravel Barbakarvão, um comerciante anão que opera em meio às corridas e apostas no Circuito da Ilusão, na Chapada Cintilante de Mil Agulhas.",al={"quem entrega o caixote","de quem é o caixote de kravel"}},{q="Para onde este caixote precisa ir?",a="O caixote deve ser transportado até o acampamento da expedição de caça de Nesingwary, no norte da Selva do Espinhaço, situado ao longo do rio ao norte do Acampamento Grom'gol.",al={"onde entregar o caixote","destino do caixote","quem recebe o caixote de kravel"}},{q="Por que a entrega atrasou?",a="A encomenda levou semanas para chegar até as salinas de Mil Agulhas, período no qual o cliente já havia feito as malas e partido para as selvas da Selva do Espinhaço.",al={"por que kravel demorou tanto","por que atrasou"}}},fx={["3beca7b7"]={q="O que é o Caixote de Kravel?",a="É um pacote de entrega pesado mantido por Kravel Koalbeard no Circuito da Ilusão, na Chapada Cintilante. Embalado de forma segura para transporte de longa distância através de Kalimdor e do Grande Oceano, o caixote contém suprimentos de caça especializados destinados a uma expedição nas terras selvagens da Selva do Espinhaço.",al={"o que é o caixote de kravel","informações sobre o caixote de kravel","item caixote de kravel"}},["6061fde3"]={q="Por que o Caixote de Kravel é procurado?",a="O caixote contém munição de calibre especial encomendada especificamente para a caça de animais de grande porte. A expedição de caça Nesingwary na Selva do Espinhaço depende de munições pesadas e confiáveis para abater as feras mais ferozes da selva, tornando este envio atrasado um reabastecimento essencial para o acampamento deles.",al={"por que nesingwary quer o caixote","por que o caixote de kravel é importante","propósito do caixote de kravel"}}},fp="14,186,24.367.0,24.340.0,30.134.0,24.154.0,33.152.0,29.147.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Presa de Kreenig Rosnento",s="A Presa de Kreenig Rosnento é um troféu de caça grotesco tirado do líder dos invasores javatuscos Razormane no norte dos Sertões. Arrancar a presa serve como prova indiscutível para Thork, na Encruzilhada, de que a ameaça contra as linhas de suprimento da Horda foi eliminada.",h="A Presa de Kreenig Rosnento é um troféu de caça grotesco tirado do líder dos invasores javatuscos Razormane...",kw={"sertões","encruzilhada","kreenig","javatusco","razormane","snarlsnout","thork","presa"},ang={["faction:Horde"]="As caravanas transportando armas, provisões e colonos de Durotar são vitais para a expansão da Horda nos Sertões. Entregar esta presa protege essas linhas vitais.",["race:Orc"]="Pegar um troféu de um comandante derrotado reflete a guerra brutal e pragmática adotada pelos orcs da Encruzilhada, demonstrando força e ao mesmo tempo semeando o pânico entre os inimigos."},sec={{t="Um Troféu de Ambição Ceifada",b="As caravanas de suprimentos que viajam a oeste de Durotar em direção aos Sertões enfrentam assédio constante, mas os ataques recentes tornaram-se cada vez mais ousados sob a liderança de um feroz líder Razormane chamado Kreenig Snarlsnout. Para enfraquecer a coordenação dos javatuscos, Thork — comandante da guarda da Encruzilhada — ordenou a eliminação de Snarlsnout. Obter a presa do chefe não só oferece uma prova concreta de que o invasor caiu, mas também serve como um insulto deliberado à tribo Razormane, quebrando a determinação deles e deixando seus guerreiros sem comando central."}},faq={{q="Quem foi Kreenig Snarlsnout?",a="Kreenig Snarlsnout foi um líder proeminente entre os javatuscos Razormane acampados a nordeste da Encruzilhada. Ele organizava ataques agressivos contra as caravanas de suprimentos da Horda que viajavam pela estrada principal a partir de Durotar, transformando a rota de suprimentos em um perigo até a sua morte.",al={"kreenig snarlsnout","quem é kreenig","história de snarlsnout"}},{q="Por que Thork quer a presa especificamente?",a="Thork exige a presa tanto como evidência incontestável de que Kreenig está morto quanto como um insulto direto à tribo Razormane. Remover a presa de um chefe javatusco caído fere o orgulho deles e desmoraliza os invasores sobreviventes.",al={"por que a presa","por que levar a presa para thork","presa de thork"}},{q="De onde esta presa foi tirada?",a="A presa é obtida no acampamento de Kreenig Snarlsnout situado a nordeste da Encruzilhada, aninhado junto às colinas ao sul da estrada principal que vai de Durotar para os Sertões.",al={"onde está kreenig","onde conseguir a presa","localização de snarlsnout"}},{q="Que efeito a eliminação de Kreenig tem sobre os Sertões?",a="Ao eliminar Kreenig, Thork acredita que os invasores Razormane ficarão desorientados sem liderança. Remover o comandante deles cria o caos em suas fileiras e reduz drasticamente novos ataques a remessas vitais de suprimentos.",al={"os ataques pararam","consequências da morte de kreenig"}}},fx={["4371b9f1"]={q="O que é a Presa de Kreenig Rosnento?",a="É uma presa de quiljavali decepada, reivindicada como um troféu sombrio de Kreenig Rosnento, o líder dos saqueadores Presa-de-navalha a nordeste da Encruzilhada. Thork exigiu-a como prova inegável da morte do chefe e para insultar amargamente os quiljavalis, demonstrando à tribo restante que seu líder de ataque caiu.",al={"o que é a presa de kreenig","item presa de kreenig rosnento"}}},fp="25,173,28.413.0,27.207.0,42.176.0,26.185.0,57.174.0"}
P.entries["item:kron-s-amulet"] = {n="Amuleto de Kron",s="O Amuleto de Kron é uma lembrança pessoal pertencente a Kron, um jovem caçador orc de Durotar que desapareceu ao longo do Rio Furiaustral.",h="O Amuleto de Kron é uma lembrança pessoal pertencente a Kron, um jovem caçador orc de Durotar que desapareceu...",kw={"amuleto","crocolisco bocamedo","kron","misha tor'kren","monte navalha","rio furiaustral"},ang={["class:Hunter"]="Uma dura lição para qualquer aspirante a rastreador sobre os perigos de subestimar feras ferozes em território fluvial desconhecido.",["race:Orc"]="O destino de Kron é um lembrete trágico de que, embora o orgulho e a glória marcial movam a tradição orca, a imprudência e a ignorância à sabedoria dos mais velhos podem trazer uma morte rápida e desnecessária."},sec={{t="Tragédia no Furiaustral",b="Kron era um jovem orc teimoso de uma fazenda a noroeste de Monte Navalha. Ansioso para provar sua perícia e desdenhando o perigo, ele partiu furioso para caçar os ferozes crocoliscos Bocamedo que rondavam o Rio Furiaustral ao longo da fronteira com os Sertões. Ignorando os avisos de sua mãe, Misha Tor'kren, seu orgulho obstinado o levou diretamente às mandíbulas dos predadores do rio. Ele nunca mais voltou, deixando para trás apenas esta bugiganga engolida como confirmação silenciosa de que havia sido morto e devorado."}},faq={{q="Quem foi Kron?",a="Kron era um jovem caçador orc impulsivo que vivia com sua mãe, Misha Tor'kren, em uma fazenda a noroeste de Monte Navalha. Determinado a testar sua força, ele saiu sozinho para caçar feras fluviais, apesar dos avisos sobre a ferocidade delas.",al={"quem é kron","história de kron","lore de kron"}},{q="Onde o Amuleto de Kron é encontrado?",a="O amuleto é recuperado da barriga de Crocoliscos Bocamedo e Crocoliscos Bocamedo Corrompidos à espreita pelas margens do Rio Furiaustral em Durotar.",al={"onde encontro o amuleto","localização do amuleto de kron","quem saqueia o amuleto de kron"}},{q="Quem deseja o retorno do Amuleto de Kron?",a="Sua mãe enlutada, Misha Tor'kren, aguarda notícias de seu filho em sua fazenda a noroeste de Monte Navalha. O amuleto dá a ela o desfecho doloroso e definitivo de que precisava para começar o luto.",al={"quem precisa do amuleto","onde entregar o amuleto de kron","misha tor'kren"}}},fx={["5d838632"]={q="O que é o Amuleto de Kron?",a="Este item pessoal pertencia a Kron, um jovem orc de uma fazenda a noroeste de Monte Navalha. Movido pelo orgulho e ansioso para provar sua força, ele partiu sozinho em direção ao Rio Furiaustral para caçar os ferozes crocodilianos Boca-terrível ao longo da fronteira dos Sertões. Em vez de retornar em triunfo, ele tornou-se presa das feras que tentava matar. Engolido junto com seus restos mortais, este talismã é a única peça sobrevivente do jovem caçador que pode provar sua morte sombria.",al={"o que é o amuleto","história do amuleto de kron","quem é o dono do amuleto"}}},fp="13,87,24.445.1,13.218.0,29.141.1,33.172.1"}
P.entries["item:kurzen-s-head"] = {n="Kurzen's Head",s="Kurzen’s Head é a prova que os rebeldes do Acampamento dos Rebeldes, na Selva do Espinhaço, procuram. Tenente Doren precisa dela para saber se o comando do Coronel Kurzen foi desfeito.",h="Kurzen’s Head é a prova que os rebeldes do Acampamento dos Rebeldes, na Selva do Espinhaço, procuram.",kw={"coronel kurzen","kurzen","elite de kurzen","subchefe de kurzen","kurzen’s head","tenente doren","acampamento dos rebeldes","stockpile","selva do espinhaço"},sec={{t="Prova para Doren",b="Tenente Doren aguarda no Acampamento dos Rebeldes notícias do Stockpile, onde o Coronel Kurzen comanda seus homens. Os rebeldes enfrentam os elites e subchefes de Kurzen, além do próprio Coronel. Doren pede Kurzen’s Head como prova de que os líderes inimigos foram derrotados. A segurança de seu grupo depende da resposta."}},faq={{q="Quem quer Kurzen’s Head?",a="Tenente Doren, no Acampamento dos Rebeldes, pede Kurzen’s Head como prova de que o Coronel Kurzen e seus líderes foram derrotados.",al={"quem quer a cabeça","cabeça de doren","onde levar kurzen’s head"}},{q="Onde está o Coronel Kurzen?",a="O Coronel Kurzen comanda seus homens nas profundezas do Stockpile, na Selva do Espinhaço.",al={"localização de kurzen","onde está kurzen","homem do stockpile"}},{q="Por que os rebeldes precisam de Kurzen’s Head?",a="Os rebeldes precisam de Kurzen’s Head como prova de que o Coronel Kurzen e seus líderes foram derrotados.",al={"por que a cabeça","finalidade de kurzen’s head","prova para doren"}},{q="Que ameaça Kurzen representa?",a="Tenente Doren chama Kurzen de comandante cruel e formidável, cujos homens ameaçam o grupo rebelde.",al={"ameaça de kurzen","por que lutar contra kurzen","história de kurzen"}},{q="O que acontece quando Kurzen é derrotado?",a="Tenente Doren diz que a derrota de Kurzen salva o grupo rebelde e permite que todos respirem mais aliviados.",al={"kurzen derrotado","o que acontece com os rebeldes","desfecho de kurzen"}}},fp="13,169,15.307.0,26.114.0,24.85.0,39.96.0,29.97.0,37.90.1"}
P.entries["item:kuz-s-skull"] = {n="Crânio de Kaz",s="O Crânio de Kaz é a cabeça decepada de Kuz, um proeminente invasor javatusco Razormane nos Sertões Meridionais. Vindo de Urzal dos Tuscos, Kuz ajudou a orquestrar ataques violentos contra postos avançados da Horda antes de se tornar alvo de morte por parte de um antigo parente mantido em cativeiro.",h="O Crânio de Kaz é a cabeça decepada de Kuz, um proeminente invasor javatusco Razormane nos Sertões...",kw={"sertões","acampamento taurajo","kuz","crânio de kaz","lok orcbane","denterroto","nak","razormane"},ang={["faction:Horde"]="Pegar a cabeça de Kuz protege diretamente assentamentos da Horda como a Encruzilhada e o Acampamento Taurajo de ataques organizados de javatuscos."},sec={{t="Uma disputa amarga",b="As planícies dos Sertões Meridionais estão infestadas pela tribo Razormane, mas sua agressão organizada provém de líderes específicos enviados diretamente de Urzal dos Tuscos. Kuz, ao lado de Nak e de seu implacável chefe Lok Orcbane, coordenou incursões brutais contra viajantes e assentamentos como a Encruzilhada. No entanto, sua traição interna causou sua ruína. Tendo traído seu companheiro javatusco Denterroto e o deixado para apodrecer em uma jaula no Acampamento Taurajo, criaram um inimigo vingativo. Denterroto negociou a localização de Kuz com campeões da Horda dispostos a decepar a cabeça do invasor e pôr fim aos seus ataques de vez."},{t="Prova de retribuição",b="Levar o Crânio de Kaz de volta ao Acampamento Taurajo serve como uma confirmação sombria de que um terço do comando do bando de guerra do sul foi destruído. Para Denterroto, a cabeça é uma doce satisfação contra a tribo que o abandonou. Para a Horda aquartelada por todos os Sertões, a morte de Kuz quebra a espinha dorsal das ofensivas coordenadas dos Razormane, despedaçando sua liderança e concedendo um alívio temporário às rotas de suprimentos que conectam as planícies."}},faq={{q="Quem foi Kuz?",a="Kuz foi um dos três ardilosos javatuscos Razormane enviados de Urzal dos Tuscos para os Sertões Meridionais. Ao lado de Nak e Lok Orcbane, ela ajudou a comandar emboscadas letais e ataques contra acampamentos e linhas de suprimento da Horda.",al={"quem é kuz","kuz história","kuz razormane"}},{q="Por que Denterroto quer o crânio de Kuz?",a="Denterroto foi traído e deixado para morrer em uma jaula no Acampamento Taurajo por sua própria espécie. Ansioso por vingança antes de encarar o próprio fim, ele orienta aventureiros da Horda a abater seus rivais traiçoeiros e trazer seus crânios como prova.",al={"por que denterroto quer kuz morto","denterroto vingança"}},{q="Onde Kuz é encontrada nos Sertões?",a="Kuz vaga pelas profundezas das regiões austrais dos Sertões, acampada com os javatuscos Razormane ao sul do Acampamento Taurajo, perto das regiões fronteiriças espinhosas.",al={"kuz localização","onde encontrar kuz"}},{q="O que acontece após Kuz ser morta?",a="Levar o Crânio de Kaz junto com as cabeças de Nak e Lok Orcbane para Denterroto desmantela a liderança que comanda as incursões dos Razormane, abrindo caminho para proteger as rotas comerciais do sul.",al={"recompensa da missão de kuz","desfecho de traição intestina"}}},fx={["9baef7d0"]={q="De onde vem o Crânio de Kaz?",a="O crânio é tirado diretamente dos restos mortais de Kaz, uma proeminente quiljavali Presa-de-navalha operando nos Sertões Meridionais. Emergindo de Urzal dos Tuscos junto com seus companheiros saqueadores, Kaz ajudou a orquestrar ataques violentos contra a Horda antes de ser caçada.",al={"de onde veio o crânio de kaz","quem fez o crânio de kaz","origem do crânio de kaz"}}},fp="11,189,13.399.0,20.287.1,12.193.0,38.228.0,34.120.0,32.167.0"}
P.entries["item:laced-pumpkin"] = {n="Abóbora Inoculada",s="Uma Abóbora Inoculada é uma abóbora comum tratada com uma mistura letal desenvolvida pelo Boticário Joaquino em Montalvo. Entregue a um Scarlet Crusader aprisionado e faminto sob o pretexto de sustento, ela serve como um teste de campo real para o crescente arsenal de armas alquímicas dos Renegados.",h="Uma Abóbora Inoculada é uma abóbora comum tratada com uma mistura letal desenvolvida pelo Boticário Joaquino...",kw={"boticário joaquino","montalvo","zelote escarlate capturado","finda forca","abóbora inoculada","real sociedade de boticários","clareiras de tirisfal"},ang={["faction:Alliance"]="O destino do zelote cativo serve como um lembrete contundente e aterrorizante dos destinos grotescos que aguardam qualquer humano vivo capturado vivo em território dos Renegados.",["race:Undead"]="Para os Renegados, transformar comida comum em arma demonstra o pragmatismo da Real Sociedade de Boticários em usar qualquer meio necessário para proteger Tirisfal contra os fanáticos cruzados vivos."},sec={{t="Uma Colheita Amarga",b="Aos olhos destreinados, a abóbora inoculada parece ser um produto agrícola comum resgatado do solo empestado das Clareiras de Tirisfal. Sob a supervisão do Boticário Joaquino em Montalvo, contudo, o vegetal é tratado com toxinas experimentais projetadas para alcançar o potencial máximo do morticínio. A Real Sociedade de Boticários busca constantemente novas armas para repelir tanto o Flagelo no norte quanto as forças de humanos vivos que avançam do sul, transformando até mesmo simples produtos da colheita em vetores de infecção e morte química."},{t="O Experimento no Porão",b="O propósito principal da abóbora inoculada é o teste prático em cobaias vivas. No porão úmido da Taberna Finda Forca, captores Renegados mantêm um faminto Zelote Escarlate Capturado. Desesperado por nutrição, o prisioneiro aceita a oferenda contaminada com alívio imediato. Ao consumir a abóbora, a mistura do boticário desencadeia uma transformação violenta, transformando o zelote humano em um carniçal irracional que cambaleia brevemente em agonia antes de desabar morto no chão de pedra frio."}},faq={{q="O que é a Abóbora Inoculada?",a="É uma abóbora do campo injetada com uma fórmula experimental desenvolvida pelo Boticário Joaquino em Montalvo, destinada a testar os efeitos da alquimia dos Renegados em cobaias vivas.",al={"abóbora inoculada","abóbora envenenada","abóbora de joaquino"}},{q="Quem come a Abóbora Inoculada?",a="Um Zelote Escarlate Capturado, aprisionado no porão sob a Taberna Finda Forca em Montalvo, consome-a após ter sido privado de comida por seus captores.",al={"quem a come","alvo da abóbora","alimentar com a abóbora"}},{q="O que acontece quando alguém come a abóbora?",a="A abóbora é entregue ao zelote cativo como um teste da mais nova fórmula de Joaquino. Seus efeitos precisos são revelados quando o prisioneiro a consome.",al={"efeito da abóbora","o que acontece com o zelote","zelote carniçal"}},{q="Por que os Renegados fizeram isso?",a="O Boticário Joaquino e a Real Sociedade de Boticários estão testando novas misturas biológicas para combater tanto o Flagelo no norte quanto os humanos vivos que avançam, usando inimigos capturados como cobaias de teste.",al={"por que criar a abóbora envenenada","testes de praga dos renegados"}}},fx={["242570cd"]={q="De onde vem a Abóbora Inoculada e quem a fez?",a="O Boticário Joaquino preparou esta abóbora em Montalvo. Buscando armas para defender os Renegados contra o Flagelo ao norte e os humanos vivos ao sul, ele colheu produtos comuns da Fazenda dos Solliden e os tratou com sua mistura experimental de praga.",al={"quem fez a abóbora inoculada","de onde veio a abóbora inoculada","criador da abóbora inoculada"}},["071bacef"]={q="Por que alguém quer a Abóbora Inoculada?",a="O Boticário Joaquino precisa que a abóbora seja dada a um sujeito vivo para avaliar sua mais recente fórmula química. Ela é oferecida a um prisioneiro faminto da Cruzada Escarlate trancado no porão sob a Taberna Finda Forca em Montalvo, servindo como um teste letal para a pesquisa da Real Sociedade de Boticários.",al={"por que querer a abóbora inoculada","por que usar a abóbora inoculada","para que a abóbora inoculada é necessária"}}},fp="13,177,16.375.0,21.383.1,26.160.0,27.168.0,43.170.1,31.201.0"}
P.entries["item:laden-dew-gland"] = {n="Laden Dew Gland",s="Uma Laden Dew Gland contém água recolhida por um coletor de orvalho em Tanaris. Marin Nublacuca, em Geringontzan, quer uma para aliviar a sede.",h="Uma Laden Dew Gland contém água recolhida por um coletor de orvalho em Tanaris.",kw={"coletor de orvalho","glândula de orvalho","laden dew gland","marin nublacuca","tanaris","vale moitagulhas"},sec={{t="Água para Marin",b="A sudoeste de Geringontzan, o Vale Moitagulhas abriga coletores de orvalho que armazenam água em glândulas especiais. Marin Nublacuca pede que você leve a ele uma Laden Dew Gland, na esperança de que ela sacie sua sede terrível."}},faq={{q="O que é uma Laden Dew Gland?",a="Uma Laden Dew Gland é um órgão cheio de água carregado pelos coletores de orvalho no Vale Moitagulhas.",al={"glândula de orvalho","glândula cheia"}},{q="Quem quer a glândula?",a="Marin Nublacuca, em Geringontzan, quer uma Laden Dew Gland para tentar saciar a sede.",al={"quem precisa de glândula de orvalho","glândula de marin"}},{q="Onde encontro uma Laden Dew Gland?",a="Os Orvalho Moitagulhas Collectors do Vale Moitagulhas, a sudoeste de Geringontzan, carregam Laden Dew Glands.",al={"local da glândula de orvalho","onde encontrar glândula em tanaris"}},{q="Por que Marin a quer?",a="Marin espera que a água armazenada na glândula renda uma bebida que sacie sua sede terrível.",al={"marin com sede","por que glândula de orvalho"}}},fp="15,131,15.208.0,26.91.0,20.84.0,34.99.0,23.94.0"}
P.entries["item:laird-s-response"] = {n="Resposta de Laird",s="Resposta de Laird é um despacho lacrado escrito pelo defumador de peixes Laird no porto costeiro de Auberdine. Escrita para Nessa Cantonegro na Vila de Rut'theran, a carta detalha curiosas diferenças ecológicas entre a vida marinha continental e os peixes invulgarmente grandes que prosperam ao longo da costa de Teldrassil.",h="Resposta de Laird é um despacho lacrado escrito pelo defumador de peixes Laird no porto costeiro de Auberdine.",kw={"auberdine","costa negra","pesca","laird","resposta de laird","nessa cantonegro","vila de rut'theran","teldrassil"},ang={["race:NightElf"]="Para os elfos noturnos que cuidam da costa de Teldrassil, as notas de Laird oferecem uma pista intrigante, embora ligeiramente desconcertante, sobre como a jovem Árvore do Mundo já exerce uma influência não natural sobre a natureza circundante."},sec={{t="Uma Questão de Escamas e Raízes",b="Após analisar relatórios de pesca de todo o Veiled Sea, Laird de Auberdine notou uma discrepância impressionante: os peixes puxados da costa de Teldrassil são notavelmente maiores e mais abundantes do que os capturados ao longo das praias continentais de Costa Negra. Nesta resposta escrita endereçada a Nessa Cantonegro, Laird compartilha sua teoria de trabalho: a de que a presença não natural e a vitalidade bruta da recém-plantada Árvore do Mundo podem estar deformando e estimulando a vida marinha circundante. Entregue por viajantes que retornavam através das águas, a carta desperta fascínio e silenciosa curiosidade entre os pescadores da Vila de Rut'theran."}},faq={{q="O que é Resposta de Laird?",a="É um despacho por escrito redigido por Laird, um comerciante e defumador de peixes estabelecido em Auberdine, destinado a responder a uma consulta de Nessa Cantonegro em Teldrassil.",al={"o que é este item","carta resposta de laird","o que é resposta de laird"}},{q="Para quem Laird está escrevendo?",a="A resposta é enviada para Nessa Cantonegro, uma elfa noturna que reside na Vila de Rut'theran, na base sul de Teldrassil.",al={"quem recebe a resposta de laird","quem recebe esta carta","carta nessa laird"}},{q="O que a carta diz sobre os peixes?",a="Laird observa que os peixes capturados ao longo da costa de Teldrassil são visivelmente maiores e mais abundantes do que aqueles encontrados na costa continental de Costa Negra, sugerindo que a própria Árvore do Mundo pode estar influenciando a vida marinha local.",al={"por que os peixes são grandes","diferença peixes costa negra teldrassil","o que laird descobriu"}},{q="Como a mensagem viaja de volta para a Vila de Rut'theran?",a="Os portadores podem embarcar na balsa regular que parte das docas de Auberdine ou providenciar um voo de hipogrifo com o mestre de voo Caylais Moonfeather.",al={"como voltar para nessa","barco rut'theran costa negra","balsa auberdine para nessa"}}},fx={aee914ad={q="De onde vem a Resposta de Laird e quem a escreveu?",a="Esta resposta escrita foi redigida por Laird, um habitante de Auberdine nas costas da Costa Negra. Ele a escreve para responder a perguntas enviadas através do mar da Vila de Rut'theran sobre a vida marinha local.",al={"quem escreveu a resposta de laird","de onde vem a resposta de laird","origem da resposta de laird"}},fb1c817f={q="Por que Nessa quer a Resposta de Laird?",a="Nessa Shadowsong na Vila de Rut'theran aguarda ansiosamente pelas observações de Laird sobre como as capturas do continente se comparam às águas de Teldrassil. Os peixes estranhos e grandes ao redor dos grandes ramos da Árvore do Mundo intrigaram os pescadores, e as notas de Laird confirmam que a Costa Negra continental não vê nada parecido com eles, sugerindo que a própria Teldrassil está transformando a vida selvagem local.",al={"por que nessa quer a resposta de laird","por que a resposta de laird é procurada","quem quer a resposta de laird"}}},fp="16,154,28.461.0,25.127.0,24.108.0,40.176.0,55.135.0"}
P.entries["item:lake-creeper-moss"] = {n="Musgo de Rastejante do Lago",s="O Musgo de Rastejante do Lago é um composto orgânico extraído dos rastejantes aquáticos que habitam as Ilhas da Aurora no Espelho de Lordaeron. Ele serve como um reagente vital procurado pela Real Sociedade de Boticários para seus esforços de criar uma nova praga letal.",h="O Musgo de Rastejante do Lago é um composto orgânico extraído dos rastejantes aquáticos que habitam as Ilhas...",kw={"berard","ilhas da aurora","rastejante do lago ancião","faranello","rastejante do lago","musgo de rastejante do lago","espelho de lordaeron","nova praga","real sociedade de boticários"},ang={["profession:Herbalism"]="Embora nativo de feras aquáticas em vez de solo comum, o musgo representa a parte mais sombria e experimental da flora de Lordaeron colhida para pesquisa de boticário.",["race:Undead"]="Cada amostra de musgo de lago levada ao Boticarium deixa os Renegados mais perto de aperfeiçoar a Nova Praga, garantindo vingança contra o Flagelo e os vivos."},sec={{t="Colheita Alquímica",b="Cultivado ao longo das peles das cruéis feras de água doce que rondam as Ilhas da Aurora ao sul do Espelho de Lordaeron, o Musgo de Rastejante do Lago possui propriedades únicas moldadas pelas águas assoladas de Lordaeron. O Boticário Berard, antes que a maldição de Arugal tomasse sua mente, documentou-o em seu diário, observando que o musgo se assemelhava a traços de materiais em fósseis de criaturas mortas por uma praga antiga no lago. Quando recuperadas por agentes Renegados, as amostras são enviadas diretamente para o Boticarium na Cidade Baixa para abastecer a pesquisa sombria do Mestre-boticário Faranello."},{t="Abastecendo a Nova Praga",b="O musgo não é apenas um crescimento aquático curioso; ele forma um estágio crítico no desenvolvimento da arma característica dos Renegados. Juntamente com o musgo relacionado coletado de Lake Skulkers e tumores doentes retirados de murlocs Vile Fin locais, o musgo de rastejante fornece a base orgânica necessária para refinar uma cepa capaz de exterminar tecidos vivos e o Flagelo da mesma forma. Apesar da perda do boticário que descobriu sua utilidade, a Real Sociedade de Boticários continua a preparar sua receita a serviço da Dama Sombria."}},faq={{q="Para que serve o Musgo de Rastejante do Lago?",a="É um reagente alquímico usado pelo Mestre-boticário Faranello e pela Real Sociedade de Boticários para preparar e refinar sua Nova Praga na Cidade Baixa.",al={"propósito do musgo de rastejante","por que coletar musgo de rastejante do lago","uso do musgo de rastejante do lago"}},{q="De onde vem este musgo?",a="Ele é coletado de Lake Creepers e Elder Lake Creepers que habitam as águas ao redor das Ilhas da Aurora ao sul, no leste do Espelho de Lordaeron.",al={"onde conseguir musgo de rastejante","localização do musgo de rastejante","localização do rastejante do lago"}},{q="Quem descobriu o valor alquímico do musgo?",a="O Boticário Berard documentou as propriedades únicas do musgo em seu diário de campo antes que a maldição de Arugal o deixasse um servo sem mente no Vilarejo Lenhardente. Suas anotações foram recuperadas mais tarde pelo Boticário Renferrel.",al={"quem encontrou o musgo","musgo de berard","quem escreveu sobre o musgo de rastejante"}},{q="Quem recebe o musgo colhido?",a="O Mestre-boticário Faranello aceita o musgo no Boticarium da Cidade Baixa, combinando-o com o Musgo de Sorrateiro do Lago e um Tumor Endurecido para avançar sua pesquisa.",al={"quem quer o musgo de rastejante","entrega de musgo de rastejante","musgo de faranello"}}},fx={["70aadfdf"]={q="O que é o Musgo de Rastejante do Lago?",a="O Musgo de Rastejante do Lago é um crescimento orgânico colhido diretamente dos corpos dos rastejantes aquáticos que habitam o Espelho de Lordaeron. Embora seja externamente uma flora de pântano comum, a Real Sociedade de Boticários valoriza-o como um reagente vital em seus experimentos sombrios.",al={"o que é musgo de rastejante","história do musgo de rastejante do lago","explicação do musgo de rastejante"}}},fp="17,190,18.486.0,22.414.1,35.160.0,31.139.0,43.207.0,32.158.0"}
P.entries["item:lake-skulker-moss"] = {n="Musgo de Sorrateiro do Lago",s="O Musgo de Sorrateiro do Lago é um reagente biológico coletado das feras do pântano que habitam o norte do Espelho de Lordaeron. Ele foi identificado pelo Boticário Berardo, antes que a maldição de Arugal reivindicasse sua mente, como um componente orgânico essencial para a pesquisa da Real Sociedade de Boticários na criação de uma New Plague.",h="O Musgo de Sorrateiro do Lago é um reagente biológico coletado das feras do pântano que habitam o norte do...",kw={"berardo","ilhas da aurora","faranello","espelho de lordaeron","lake skulker","musgo de sorrateiro do lago","new plague","renferrel"},ang={["race:Undead"]="Cada lote de musgo colhido deixa a Real Sociedade de Boticários um passo mais perto de aperfeiçoar a New Plague, a maior arma dos Renegados contra o Flagelo e os vivos."},sec={{t="Um reagente de praga",b="Colhido dos corpos musgosos de Lake Skulkers e Elder Lake Skulkers nas Ilhas da Aurora, este musgo aquático úmido possui propriedades muito valorizadas pelos alquimistas Renegados. Antes que a maldição de Arugal reivindicasse sua mente, o Boticário Berardo catalogou meticulosamente a flora e a fauna do leste da Floresta de Pinhaprata, concluindo em seu diário que tanto o musgo de Lake Skulker quanto o de Lake Creeper poderiam servir como agentes estabilizadores ou reativos. Depois que Berardo se tornou um servo sem mente de Arugal, seu diário foi recuperado do Vilarejo Lenhardente para o Boticário Renferrel, que instruiu campeões dos Renegados a coletar amostras de musgo junto com um tumor raro de murlocs Vile Fin locais, entregando-os diretamente ao Mestre-boticário Faranello na Cidade Baixa."}},faq={{q="Para que serve o Musgo de Sorrateiro do Lago?",a="Ele é utilizado pela Real Sociedade de Boticários na Cidade Baixa como um ingrediente-base orgânico para produzir a New Plague, servindo aos objetivos da Grande Dama Sylvana Correventos e dos Renegados.",al={"uso do musgo","por que coletar musgo de skulker","o que faz o musgo de skulker"}},{q="De onde vem este musgo?",a="O musgo é raspado dos corpos de Lake Skulkers e Elder Lake Skulkers, bestas aquáticas que habitam as águas ao redor das Ilhas da Aurora no nordeste do Espelho de Lordaeron, na costa da Floresta de Pinhaprata.",al={"onde conseguir musgo de skulker","localização do musgo de skulker","quem derruba musgo de sorrateiro do lago"}},{q="Quem descobriu a utilidade do musgo?",a="O Boticário Berardo identificou primeiro seu potencial durante sua pesquisa de campo na Floresta de Pinhaprata. Embora a maldição de Arugal tenha deixado Berardo como um servo sem mente, seu diário sobrevivente guiou o Boticário Renferrel e o Mestre-boticário Faranello a continuar seus experimentos.",al={"quem encontrou o musgo","musgo de berardo","pesquisa do boticário berardo"}},{q="Quem precisa deste reagente?",a="O Mestre-boticário Faranello, líder da Real Sociedade de Boticários que reside no Boticarium da Cidade Baixa, precisa do musgo para avançar seus projetos de guerra biológica.",al={"quem quer musgo de skulker","musgo de skulker de faranello"}}},fx={["18c0a856"]={q="O que é o Musgo de Sorrateiro do Lago?",a="O Musgo de Sorrateiro do Lago é um crescimento natural colhido das costas dos sorrateiros do lago, feras anfíbias que espreitam ao redor das Ilhas da Aurora do Espelho de Lordaeron. Embora insignificante para pescadores e viajantes, esta matéria orgânica possui propriedades específicas que atraíram a atenção dos alquimistas Renegados que estudam a flora e a fauna locais.",al={"o que é o musgo de sorrateiro do lago","informações sobre o musgo de sorrateiro do lago","explicação do musgo de sorrateiro"}}},fp="17,194,16.613.0,35.178.0,31.179.0,37.225.0,26.149.0"}
P.entries["item:large-candle"] = {n="Vela Grande",s="Velas Grandes são círios de cera valorizados e carregados por kobolds que escavam as minas da Floresta de Elwynn. Fixadas no topo de suas cabeças, essas luzes rudimentares fornecem visibilidade em túneis subterrâneos e servem como uma fonte confiável de cera bruta para boticários humanos.",h="Velas Grandes são círios de cera valorizados e carregados por kobolds que escavam as minas da Floresta de...",kw={"mina vailafundo","vila d'ouro","goldtooth","mina de jaspe","kobold candles","vela grande","cera","durval pilão"},ang={["faction:Alliance"]="Ao retirar velas dos kobolds em Elwynn, os aventureiros da Aliança enfraquecem simultaneamente as pragas que infestam as minas e fornecem materiais essenciais para o comércio de botica de Ventobravo.",["profession:Mining"]="Mineiros que trabalham nos veios de Vailafundo e Jaspe frequentemente entram em conflito com as infestações de kobolds, que cobiçam tanto o ouro quanto a luz bruxuleante dessas velas grandes."},sec={{t="Luz Subterrânea e Cera",b="Kobolds que cavam túneis sob a Floresta de Elwynn dependem da chama das velas para navegar por poços subterrâneos completamente escuros, fixando círios de cera diretamente em suas cabeças. Kobold Miners, Tunnelers e Geomancers defendem ferozmente suas velas contra invasores. Apesar de sua fabricação rudimentar, as velas grandes carregadas nas profundezas da Mina Vailafundo e da Mina de Jaspe contêm cera valiosa que os comerciantes da superfície não conseguem produzir facilmente em grande escala, transformando uma ferramenta comum de monstros em uma mercadoria alquímica."},{t="Comércio e o Boticário",b="Durval Pilão, um agente boticário vindo de Ventobravo, recolhe essas velas avantajadas na Estalagem do Leão Orgulhoso, em Vila d'Ouro. Em busca de cera derretida para as poções, bálsamos e unguentos preparados pela botica de sua família, Pilão contrata aventureiros que passam pelo local para limpar as minas infestadas e tirar as velas dos invasores subterrâneos."}},faq={{q="Para que servem as Velas Grandes?",a="Durval Pilão recolhe Velas Grandes em Vila d'Ouro para a botica que administra com seu irmão em Ventobravo. O negócio derrete as velas coletadas para usar a cera como ingrediente em vários unguentos, bálsamos e receitas alquímicas.",al={"uso da vela grande","por que obter velas grandes","quem quer velas grandes"}},{q="Onde as Velas Grandes podem ser encontradas?",a="Elas são carregadas por kobolds que habitam as minas da Floresta de Elwynn, predominantemente dentro da Mina Vailafundo, ao sul de Vila d'Ouro, e da Mina de Jaspe, ao leste. Tunnelers, Miners e Geomancers as carregam.",al={"localização da vela grande","onde conseguir velas grandes","saques de vela de kobold"}},{q="Por que os kobolds carregam velas na cabeça?",a="Os kobolds habitam túneis subterrâneos completamente escuros e precisam de luz para cavar e se orientar. Eles usam velas fixadas na cabeça para manter as mãos livres para picaretas, lançamentos de feitiços geomânticos e armas.",al={"por que os kobolds têm velas","história da vela na cabeça dos kobolds"}},{q="Quem é Durval Pilão?",a="Durval Pilão é um boticário de Ventobravo que conduz seus negócios na Estalagem do Leão Orgulhoso, em Vila d'Ouro. Ele reúne ingredientes brutos da natureza e das minas locais para abastecer a botica que administra com seu irmão.",al={"história de durval pilão","quem é o boticário de vila d'ouro"}}},fx={["05873d56"]={q="O que é uma Vela Grande?",a="Uma Vela Grande é um cone de cera bruto e substancial carregado pelos kobolds que habitam as minas da Floresta de Elwynn. Os kobolds são notoriamente protetores de suas fontes de luz, usando essas velas pesadas para perfurar a escuridão de túneis subterrâneos como as minas Fargodeep e Jasperlode enquanto cavam em busca de ouro e minerais.",al={"o que é uma vela grande","vela grande em elwynn","história da vela grande"}}},fp="12,108,26.430.0,24.316.0,32.199.0,33.177.0,44.194.0,22.229.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Fragmento Grande de Soran'ruk",s="O Fragmento Grande de Soran'ruk é um remanescente considerável de um antigo artefato imbuído de energia demoníaca. Abrigando originalmente o espírito de um demônio desgraçado da Legião Ardente, este estilhaço foi parar nas mãos de conjuradores sinistros dentro das muralhas assombradas da Bastilha da Presa Negra.",h="O Fragmento Grande de Soran'ruk é um remanescente considerável de um antigo artefato imbuído de energia...",kw={"legião ardente","doan karhan","fragmento grande de soran'ruk","orbe de soran'ruk","bastilha da presa negra","soran'ruk"},ang={["class:Warlock"]="Recuperar o Fragmento Grande de Soran'ruk permite que você domine o espírito demoníaco aprisionado em seu interior, ajudando Doan Karhan a reconstruir uma arma potente criada sob medida para artes demoníacas."},sec={{t="O Legado de Soran'ruk",b="Quando demônios da Legião Ardente perdem o favor de seus mestres sombrios, seus espíritos às vezes são condenados ao aprisionamento dentro de orbes encantados. Esses receptáculos são subsequentemente distribuídos entre magos e bruxos aliados à Legião, que recorrem às potentes forças vis aprisionadas em seu interior. Mesmo quando estilhaçado em fragmentos, a essência remanescente do demônio aprisionado ainda irradia poder, tornando cada pedaço uma dádiva valiosa para praticantes ambiciosos de Magia Sombria."},{t="O Estilhaço em Presa Negra",b="O orbe de Soran'ruk foi partido em duas metades há muito tempo. Enquanto uma parte foi ainda mais fraturada e dispersa entre cultistas em outro lugar, a metade maior foi reivindicada por um feiticeiro que habitava a fortaleza amaldiçoada da Bastilha da Presa Negra. Lá, carregado entre os sinistros Shadowfang Darksouls, o Fragmento Grande de Soran'ruk canaliza poder demoníaco até ser procurado por aqueles que esperam reforjar o antigo receptáculo."}},faq={{q="O que é o Fragmento Grande de Soran'ruk?",a="É a metade principal de O orbe de Soran'ruk, um antigo receptáculo mágico que contém o espírito aprisionado de um demônio desgraçado da Legião Ardente.",al={"fragmento grande de soran'ruk","grande fragmento de soran'ruk","o que e este fragmento"}},{q="Onde o fragmento é encontrado?",a="O fragmento está em posse dos Shadowfang Darksouls, conjuradores malévolos que residem na fortaleza assombrada da Bastilha da Presa Negra, na Floresta de Pinhaprata.",al={"onde encontrar o fragmento grande","localizacao do fragmento grande","quem saqueia fragmento grande de soran'ruk"}},{q="Por que o orbe foi quebrado?",a="O orbe original foi dividido em duas partes primárias. A metade menor foi quebrada em estilhaços menores e levada para as cavernas costeiras de Profundezas Negras, enquanto esta porção maior foi mantida por magos sombrios na Bastilha da Presa Negra.",al={"como o orbe quebrou","por que o orbe esta fragmentado","historia do orbe de soran'ruk"}},{q="Quem deseja reagrupá-lo?",a="Doan Karhan, um eremita recluso que vive nos confins ao sul dos Sertões, dedicou sua vida a estudar e reconstruir os orbes perdidos da Legião Ardente.",al={"quem precisa do fragmento grande","quem reconstroi o orbe"}}},fx={["0cdd1dfd"]={q="De onde vem o Fragmento Grande de Soran'ruk e quem o criou?",a="O fragmento já foi parte de The Orb of Soran'ruk, um artefato criado pela Legião Ardente. Quando demônios da Legião caem em desgraça, seus espíritos são presos dentro de orbes e entregues a magos e bruxos mortais. Soran'ruk era um desses demônios, e sua essência foi aprisionada para alimentar magia demoníaca. O orbe foi posteriormente dividido em duas partes, com este fragmento maior caindo nas mãos de um conjurador das trevas dentro da Bastilha da Presa Negra.",al={"origem do fragmento de soranruk","quem criou the orb of soranruk","de onde veio soranruk"}}},fp="24,146,23.317.0,23.330.0,37.138.0,28.99.0,23.199.0,27.145.0"}
P.entries["item:large-stone-slab"] = {n="Large Stone Slab",s="Large Stone Slabs são pedaços de rocha encontrados nos elementais de rocha dos Ermos. Lotwil Viriato precisa deles para testar seus feitiços.",h="Large Stone Slabs são pedaços de rocha encontrados nos elementais de rocha dos Ermos.",kw={"ermos","elemental","large stone slab","lotwil viriato","elemental de rocha","pedra","pedra de rocha"},ang={["race:Tauren"]="Lotwil se admira que um único tauren tenha trazido as pedras, dizendo que esperava que fossem necessárias meia dúzia de pessoas."},sec={{t="Pedra para Estudo",b="A oeste de Lotwil Viriato, nos Ermos, elementais de rocha carregam as pedras que ele procura. Seus corpos maiores e mais fortes fornecem pedaços adequados aos testes. Lotwil acredita que seus feitiços podem ajudá-lo a controlar elementais, e essas pedras fazem parte desse trabalho."}},faq={{q="De onde vêm as Large Stone Slabs?",a="Elementais de rocha nos Ermos carregam Large Stone Slabs. Lotwil Viriato aponta para as colinas a oeste e as encostas das montanhas próximas.",al={"de onde vêm as pedras","origem das pedras de rocha"}},{q="Quem quer as pedras?",a="Lotwil Viriato precisa de Large Stone Slabs para testar feitiços que pretendem controlar elementais.",al={"quem precisa das pedras","pedras de lotwil"}},{q="Por que Lotwil quer essas pedras?",a="Lotwil testa seus feitiços nas pedras, na esperança de usá-las em experimentos para controlar elementais.",al={"por que as pedras","para que servem as pedras"}},{q="Quais elementais carregam as pedras?",a="Elementais de rocha carregam as pedras que Lotwil procura. As instruções dele indicam que ficam a oeste e nas encostas das montanhas.",al={"o que é elemental de rocha","quais pedras"}}},fp="16,122,15.246.0,37.141.0,20.92.0,26.94.0,28.113.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Cabelo da Irmã Risonha",s="O Cabelo da Irmã Risonha consiste em mechas macias e mágicas colhidas de dríades que habitam as florestas encantadas do Vale Gris. Muito cobiçados por tecelões habilidosos, esses fios possuem propriedades místicas inatas ideais para a confecção de vestes refinadas.",h="O Cabelo da Irmã Risonha consiste em mechas macias e mágicas colhidas de dríades que habitam as florestas...",kw={"vale gris","tecido","encruzilhada","denya","driade","cabelo","kil'hala","irma risonha","refúgio bosque real"},ang={["faction:Horde"]="Adquirir essas mechas requer avançar pelo território dos elfos noturnos no Vale Gris para abater espíritos do bosque, demonstrando a disposição da Horda em colher magia local à força.",["profession:Tailoring"]="As mechas etéreas das dríades representam uma das fontes de fio mais exóticas de Kalimdor, valorizadas por vincular a magia natural inata ao tecido."},sec={{t="Um Componente Raro de Tecelagem",b="Colhido das dríades conhecidas como irmãs risonhas perto do Refúgio Bosque Real no Vale Gris, este cabelo possui uma magia natural notável. Embora as dríades sejam protetoras sagradas dos bosques ligadas a Cenarius e aos elfos noturnos, os artesãos da Horda valorizam o cabelo delas puramente como um potente reagente de criação. O alfaiate troll Kil'hala na Encruzilhada fia essas mechas coletadas em vestes encantadas para praticantes iniciantes do arcano."}},faq={{q="De onde vem o Cabelo da Irmã Risonha?",a="O cabelo é obtido das irmãs risonhas, dríades que vagam pelos bosques encantados perto do Refúgio Bosque Real, no centro do Vale Gris.",al={"onde conseguir cabelo de irma risonha","localizacao cabelo de irma risonha","fonte de cabelo de driade"}},{q="Por que Kil'hala está procurando cabelo de dríade?",a="Kil'hala é um alfaiate artesão situado na Encruzilhada nos Sertões. Ele utiliza os fios mágicos para tecer vestes de tecido encantadas para os alunos promissores de Denya.",al={"por que kilhala quer cabelo","uso para cabelo de irma risonha","alfaiate troll cabelo de driade"}},{q="As irmãs risonhas abrirão mão do seu cabelo por vontade própria?",a="Não. As irmãs risonhas são guardiãs ferozes da natureza e protetoras juradas do Vale Gris. Como Kil'hala observa com frieza, as dríades jamais entregariam seu cabelo voluntariamente a agentes da Horda.",al={"e possivel pedir cabelo para driades","driades doam cabelo"}}},fx={["3a458879"]={q="O que é o Cabelo da Irmã Risonha?",a="O Cabelo da Irmã Risonha consiste em mechas cortadas coletadas de irmãs risonhas, as dríades da floresta que habitam perto do Refúgio Bosque Real em Vale Gris. Impregnadas com a graça natural e a magia das filhas de Cenarius, essas mechas são valorizadas por tecelões habilidosos como material de tecelagem raro para vestimentas de conjuração poderosas.",al={"o que é o cabelo da irmã risonha","informações sobre o cabelo da irmã risonha","material de cabelo de dríade"}}},fp="22,138,24.333.0,44.136.0,39.136.0,55.149.0"}
P.entries["item:leftwitch-s-package"] = {n="Leftwitch's Package",s="Leftwitch’s Package leva de volta a Altaforja a última parte dos negócios da Reagents for Reclaimers Inc. na Desolação. Putren Rochamalho recebe o pacote e paga pelo serviço.",h="Leftwitch’s Package leva de volta a Altaforja a última parte dos negócios da Reagents for Reclaimers Inc.",kw={"desolação","altaforja","leftwitch","leftwitch's package","reagents for reclaimers inc","putren rochamalho"},sec={{t="De volta a Altaforja",b="Putren Rochamalho aguarda em Altaforja por Leftwitch’s Package, vindo da Desolação. Leve o pacote de volta para ele, e a Reagents for Reclaimers Inc. pagará por esse último serviço. Putren fica feliz em contar com você, mesmo para um trabalho pequeno."}},faq={{q="Para quem é Leftwitch’s Package?",a="Putren Rochamalho, em Altaforja, recebe Leftwitch’s Package em nome de Leftwitch.",al={"quem quer o pacote","leftwitch package para quem"}},{q="Para onde vai o pacote?",a="Leve Leftwitch’s Package da Desolação até Putren Rochamalho, em Altaforja.",al={"onde levar","destino do pacote"}},{q="A que o pacote está ligado?",a="Leftwitch’s Package é a entrega final dos negócios da Reagents for Reclaimers Inc. na Desolação.",al={"por que o pacote","pacote da reclaimers"}},{q="O que Putren faz quando recebe o pacote?",a="Putren agradece pelo serviço pontual e paga você em nome da Reagents for Reclaimers Inc.",al={"o que acontece após a entrega","putren paga"}}},fp="19,162,17.218.0,33.88.0,26.77.0,33.101.0,37.80.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Legado dos Aspectos",s="Legado dos Aspectos é um tomo antigo escondido nas profundezas do Retiro de Dor'Danil, no sul de Vale Gris. Recuperado durante uma provação de intelecto da Horda, o volume contém conhecimentos essenciais sobre os Grandes Aspectos que moldaram a antiga Azeroth.",h="Legado dos Aspectos é um tomo antigo escondido nas profundezas do Retiro de Dor'Danil, no sul de Vale Gris.",kw={"vale gris","retiro","braug espírito turvo","dor'danil","legado dos aspectos","túnel garracava","teste de saber"},ang={["class:Druid"]="O texto repousa nas profundezas do Retiro de Dor'Danil, cercado pelos espíritos trágicos e atormentados de druidas Elfos Noturnos caídos.",["faction:Horde"]="O tomo é fundamental para um rito de passagem tradicional que testa se os aventureiros da Horda possuem sabedoria e conhecimento à altura de sua força física."},sec={{t="Um Teste da Mente",b="Enquanto provações anteriores propostas por anciãos taurens testam a resistência física e a determinação, a busca por Legado dos Aspectos foi criada para desafiar a mente. Incumbido por Braug Espírito Turvo na entrada do Túnel Garracava, na Cordilheira das Torres de Pedra, o aspirante deve adentrar os túmulos assombrados de Dor'Danil. Protegido pelos espíritos inquietos de druidas caídos e pelas criaturas cruéis que os mataram, o texto antigo repousa sobre um pedestal de pedra. Reivindicar o volume é apenas o primeiro passo; o buscador deve memorizar seu conteúdo antes de entregar o livro, pois será testado a respeito de suas lições históricas."}},faq={{q="Onde o livro está localizado?",a="O livro repousa sobre um pedestal de pedra nas câmaras inferiores do Retiro de Dor'Danil, localizado no sul de Vale Gris, ao sul do Posto Machadada.",al={"encontrar legado dos aspectos","localização do livro","onde fica o livro"}},{q="Por que Braug Espírito Turvo quer este livro?",a="Braug Espírito Turvo usa o tomo para conduzir o Teste de saber. Diferente dos desafios físicos, esta provação serve para determinar se um aventureiro possui a inteligência e a atenção necessárias para estudar e recordar conhecimentos históricos vitais.",al={"por que braug quer o livro","objetivo do teste de saber"}},{q="O que acontece se você não estudar o texto antes de falar com Braug?",a="Braug faz perguntas aos buscadores sobre a história contida nas páginas logo após recolher o volume. Responder incorretamente resulta em um rápido banimento mágico, teletransportando o requerente despreparado para longe, no Acampamento Taurajo, nos Sertões.",al={"consequência de resposta errada","falhar no teste"}}},fx={["32a02485"]={q="O que é o Legado dos Aspectos?",a="O Legado dos Aspectos é um tomo antigo e valioso que repousa nas profundezas do Retiro de Dor'Danil, no sul de Vale Gris. Guardado pelos espíritos inquietos de druidas caídos e pelas criaturas vis que os mataram, o livro contém conhecimento histórico sobre os Aspectos Dragônicos, servindo como um teste rigoroso de sabedoria e memória para aqueles que ousam recuperá-lo.",al={"o que é o legado dos aspectos","livro legado dos aspectos","o que é este livro"}}},fp="21,226,18.582.0,26.144.0,40.174.0,68.193.0"}
P.entries["item:letter-of-commendation"] = {n="Letter of Commendation",s="A Letter of Commendation de Brother Anton traz seu selo e os cumprimentos da Cruzada Escarlate. Ela orienta seu portador a ir de Desolação até Raul, o Devotado, na Costa Sul.",h="A Letter of Commendation de Brother Anton traz seu selo e os cumprimentos da Cruzada Escarlate.",kw={"brother anton","desolação","letter of commendation","lordaeron","raul, o devotado","cruzada escarlate","monastério escarlate","costa sul"},ang={["faction:Alliance"]="Para um viajante da Aliança, Costa Sul é uma cidade conhecida, onde Raul, o Devotado, recebe a recomendação selada de Brother Anton."},sec={{t="Uma carta selada",b="Raul, o Devotado, aguarda na Costa Sul o portador da carta de Brother Anton. A mensagem selada elogia as fortalezas da Cruzada Escarlate, de Amparo às Clareiras de Tirisfal. Ela declara que a verdadeira ameaça da praga está em Lordaeron e pede que Raul receba o portador."}},faq={{q="Quem me deu a carta?",a="Brother Anton entregou a Letter of Commendation e a selou com sua marca.",al={"carta de anton","carta anton","quem selou"}},{q="Quem deve recebê-la?",a="Raul, o Devotado, na Costa Sul, é indicado como destinatário.",al={"onde levar a carta","carta para raul","quem recebe isto"}},{q="Para que serve a carta?",a="A carta recomenda seu portador a Raul e pede que ele o escolte até um lugar de honra no Monastério Escarlate.",al={"para que serve esta carta","o que ela faz","objetivo da carta"}},{q="O que Brother Anton diz sobre a praga?",a="Brother Anton diz que a verdadeira ameaça da praga está em Lordaeron.",al={"ameaça da praga","anton sobre lordaeron","onde a praga é pior"}},{q="O que a carta diz sobre a Cruzada Escarlate?",a="A Cruzada Escarlate reivindica fortalezas de Amparo às Clareiras de Tirisfal e as chama de bastiões de purificação.",al={"fortalezas da cruzada","bastiões escarlates","onde a cruzada reivindica terras"}}},fp="22,168,15.278.0,23.74.0,22.59.0,23.115.1,45.62.0,51.111.0"}
P.entries["item:letter-to-delgren"] = {n="Carta para Dinis",s="A Carta para Dinis é uma missiva urgente escrita por Balthule Umbrataque perto d'A Torre de Althalaxx, no norte de Costa Negra. Endereçada ao seu mentor, o paladino Dinis, o Purificador, ela detalha as operações sinistras do culto demoníaco Dark Strand. Entregá-la leva informações cruciais para o sul, até o Entreposto de Maestra, em Vale Gris.",h="A Carta para Dinis é uma missiva urgente escrita por Balthule Umbrataque perto d'A Torre de Althalaxx, no...",kw={"vale gris","balthule umbrataque","dark strand","costa negra","dinis, o purificador","carta para dinis","entreposto de maestra","torre de althalaxx"},ang={["class:Paladin"]="Esta missiva destaca uma aliança incomum: um paladino humano treinando um estudante elfo noturno na Luz Sagrada, unindo as antigas terras Kaldorei à fé marcial dos Reinos do Leste.",["faction:Alliance"]="A mensagem reflete a crescente cooperação dentro da Aliança, à medida que campeões humanos e Sentinelas noctiélficas unem forças para combater cultos demoníacos que se infiltram no norte de Kalimdor."},sec={{t="Um aviso enviado ao sul",b="Enquanto cultistas do Dark Strand se reúnem ao redor das ruínas d'A Torre de Althalaxx, o elfo noturno Balthule Umbrataque vigia a crescente maldade deles. Sem o poder marcial necessário para erradicar o culto sozinho, Balthule redige este despacho para pedir ajuda ao seu tutor na Luz Sagrada, Dinis, o Purificador. Como os ritos vis do culto ameaçam mais do que apenas a costa de Costa Negra, a mensagem precisa ser levada por toda a extensão da região até o oeste de Vale Gris, onde Dinis trabalha em conjunto com as Sentinelas noctiélficas para caçar ameaças demoníacas e de mortos-vivos."}},faq={{q="O que é a Carta para Dinis?",a="É uma mensagem selada escrita por Balthule Umbrataque, relatando o aumento das atividades do culto demoníaco Dark Strand n'A Torre de Althalaxx. Ela é endereçada ao paladino Dinis, o Purificador.",al={"o que é esta carta","carta para dinis","carta de balthule"}},{q="Quem é Dinis, o Purificador?",a="Dinis é um paladino humano instalado no Entreposto de Maestra, no oeste de Vale Gris. Dedicado à Luz Sagrada, ele ofereceu suas habilidades marciais para ajudar as Sentinelas noctiélficas a expurgar demônios e mortos-vivos das florestas antigas, enquanto instrui Balthule na guerra sagrada.",al={"quem é dinis","história de dinis","onde fica dinis"}},{q="Por que Balthule está enviando a carta para tão longe?",a="Balthule é aluno de Dinis e busca especificamente a perícia de seu mentor contra a corrupção demoníaca. Dinis possui tanto a destreza em combate quanto o apoio das forças locais das Sentinelas no Entreposto de Maestra para organizar uma resposta contra os rituais sombrios do Dark Strand.",al={"por que enviar para vale gris","por que não avisar auberdine"}},{q="Onde esta carta precisa ser entregue?",a="A carta deve ser levada para o sul através de toda a Costa Negra e além da fronteira com Vale Gris, alcançando o Entreposto de Maestra ao longo da estrada oeste.",al={"onde entrego a carta","local de entrega da carta"}}},fx={["8fccd45f"]={q="De onde vem a Carta para Dinis e quem a escreveu?",a="A carta foi redigida por Balthule Umbrataque, um elfo noturno estacionado no norte da Costa Negra perto de The Tower of Althalaxx. Buscando purgar a corrupção demoníaca que criava raízes nas ruínas antigas, Balthule escreveu esta missiva urgente para convocar a ajuda e o conselho de seu mentor, o paladino Delgren the Purifier.",al={"quem escreveu a carta para dinis","de onde veio a carta para dinis","quem enviou a carta para dinis"}},["99aa1720"]={q="Por que a Carta para Dinis é tão importante?",a="A missiva contém inteligência crítica que expõe as operações sinistras do culto do Círculo Sombrio em The Tower of Althalaxx. Delgren the Purifier dedicou-se a ajudar os elfos noturnos a limpar demônios e mortos-vivos das florestas, e Balthule precisa que seu mentor seja alertado imediatamente para que possam confrontar a ameaça crescente.",al={"por que delgren precisa da carta","por que querer a carta para dinis","importância da carta para dinis"}}},fp="17,204,20.414.0,30.134.0,28.229.0,47.214.0,44.122.0"}
P.entries["item:letter-to-ello"] = {n="Carta para Malaquias",s="A Carta para Malaquias é uma missiva selada escrita por Abercrombie, um eremita excêntrico que vive em um casebre ao norte do Cemitério de Monte Corvo, na Floresta do Crepúsculo. Endereçada ao Prefeito Ello Ebonlocke de Vila Sombria, a carta é entregue sob a alegação do eremita de uma velha amizade, embora seu conteúdo esteja escrito em uma caligrafia arcaica.",h="A Carta para Malaquias é uma missiva selada escrita por Abercrombie, um eremita excêntrico que vive em um...",kw={"abercrombie","vila sombria","floresta do crepúsculo","ello ebonlocke","carta para malaquias","note to the mayor","sirra von'indi"},ang={["faction:Alliance"]="Levar despachos entre reclusos excêntricos e prefeitos de cidades locais é um dever padrão para viajantes na Floresta do Crepúsculo, embora os funcionários municipais de Vila Sombria permaneçam constantemente apreensivos quanto a missivas estranhas."},sec={{t="Uma Saudação Bizarra",b="Depois que aventureiros ajudam o eremita Abercrombie em tarefas pela Floresta do Crepúsculo, o velho recluso lhes confia este bilhete, afirmando que o Prefeito Ello Ebonlocke é um velho amigo que vai comemorar o que foi realizado. Na realidade, o prefeito de Vila Sombria não tem lembrança de ninguém chamado Abercrombie. Ao romper o selo, o Prefeito Ebonlocke descobre que não consegue decifrar uma única frase da caligrafia arcaica, o que o leva a enviar o bilhete à erudita de Vila Sombria, Sirra Von'Indi, para tradução."},{t="Mau Presságio",b="A tarefa aparentemente inocente oculta as verdadeiras e macabras intenções do eremita. Longe de ser uma troca amigável entre velhos conhecidos da cidade, as runas antigas escritas por Abercrombie anunciam a desgraça de toda a cidade de Vila Sombria."}},faq={{q="Quem escreveu a Carta para Malaquias?",a="A carta foi escrita por Abercrombie, um eremita que vive em uma cabana aos pedaços perto do Cemitério de Monte Corvo, no oeste da Floresta do Crepúsculo.",al={"quem escreveu a carta","autor de carta para malaquias","quem enviou a carta"}},{q="O Prefeito Ello Ebonlocke consegue ler a carta?",a="Não. Quando entregue ao Prefeito Ebonlocke em Vila Sombria, ele acha a escrita completamente incompreensível e observa que ela parece estar escrita em uma língua antiga e irreconhecível.",al={"o malaquias consegue ler","por que malaquias não consegue ler o bilhete","idioma da carta para malaquias"}},{q="Quem pode traduzir o bilhete?",a="O Prefeito Ebonlocke orienta os mensageiros a levarem a missiva a Sirra Von'Indi, uma erudita residente em Vila Sombria e versada em escritas antigas e línguas esotéricas.",al={"quem traduz o bilhete","traduzir bilhete de abercrombie","quem pode ler a carta"}},{q="O Prefeito Ebonlocke realmente conhece Abercrombie?",a="Apesar da alegação de Abercrombie de que ele e o prefeito são velhos amigos, Ello Ebonlocke insiste que nunca ouviu falar de ninguém chamado Abercrombie.",al={"o malaquias conhece o abercrombie","malaquias e abercrombie são amigos","abercrombie velhos amigos malaquias"}}},fx={["74d18927"]={q="O que é a Carta para Malaquias?",a="A Carta para Malaquias é uma missiva misteriosa escrita em uma língua antiga e ilegível, redigida por Abercrombie, o eremita. Endereçada diretamente ao Prefeito Malaquias Ebonlocke de Vila Sombria, o eremita afirma que o bilhete informará seu \"velho amigo\" sobre os feitos que você realizou no cemitério.",al={"carta para malaquias","o que é a carta para malaquias","bilhete de abercrombie"}},ee8215fa={q="Por que o Prefeito Ebonlocke quer a Carta para Malaquias?",a="O Prefeito Ebonlocke quer a carta apenas porque você chega trazendo a notícia de que um velho amigo chamado Abercrombie a enviou para ele. Ao recebê-la, no entanto, o prefeito descobre que não consegue ler sua escrita arcaica e busca urgentemente que ela seja traduzida para descobrir o que o eremita realmente pretendia.",al={"por que malaquias quer a carta","por que querer a carta para malaquias","por que entregar a carta para malaquias"}}},fp="14,205,18.399.0,10.165.1,29.117.0,41.155.0,27.151.0,47.119.1"}
P.entries["item:letter-to-jin-zil"] = {n="Carta para Jin'Zil",s="A Carta para Jin'Zil é uma correspondência escrita pelo orc Darsok Punhálacre na Encruzilhada. Confiada a um aventureiro após a derrota de Serena Bloodfeather, ela leva a notícia ao mandingueiro Lançanegra Jin'Zil, na Cordilheira das Torres de Pedra, de que o norte dos Sertões foi purgado da ameaça de Bloodfeather.",h="A Carta para Jin'Zil é uma correspondência escrita pelo orc Darsok Punhálacre na Encruzilhada.",kw={"darsok punhálacre","harpias","jin'zil","carta para jin'zil","malaka'jin","rokhan","serena bloodfeather","cordilheira das torres de pedra"},ang={["faction:Horde"]="A carta serve como uma ponte para aventureiros da Horda em transição do policiamento dos Sertões para o enfrentamento de conflitos mais profundos que se formam na Cordilheira das Torres de Pedra.",["race:Troll"]="Entregar a carta conduz os viajantes Lançanegra diretamente ao Mandingueiro Jin'Zil, um praticante veterano que mantém o vodu tradicional fora das Ilhas do Eco."},sec={{t="Um Mensageiro para a Cordilheira das Torres de Pedra",b="Após a erradicação da infestação de harpias nos Montes Áridos e a matança de Serena Bloodfeather, Darsok Punhálacre redige esta missiva para um velho camarada. Reconhecendo que as harpias dos Sertões originalmente nidificavam nos picos da Cordilheira das Torres de Pedra, Darsok usa o despacho para apresentar um guerreiro promissor à fronteira mais ampla, enquanto notifica o mandingueiro Jin'Zil de que a matriarca das harpias caiu."},{t="Velhas Memórias em Malaka'jin",b="Após a entrega na caverna em Malaka'jin, Jin'Zil recebe a notícia com satisfação nostálgica. A morte de Serena lembra o velho mandingueiro da fundação de Durotar após a Terceira Guerra, quando seu amigo Rokhan se uniu ao mestre das feras meio-ogro Rexxar para abater a irmã mais velha de Serena, Bloodfeather. Com Serena agora também morta, Jin'Zil considera a vingança da linhagem Bloodfeather completamente extinta."}},faq={{q="Quem escreveu a Carta para Jin'Zil?",a="A carta foi escrita por Darsok Punhálacre, um orc estacionado na Encruzilhada, nos Sertões, que coordena a defesa contra os bandos de harpias saqueadoras.",al={"quem escreveu isso","remetente da carta","carta de darsok"}},{q="Onde Jin'Zil está localizado?",a="O Mandingueiro Jin'Zil reside dentro de uma caverna em Malaka'jin, um posto avançado de trolls Lançanegra situado nos penhascos a sudeste da Cordilheira das Torres de Pedra.",al={"onde fica jinzil","localização de jin'zil","encontrar jinzil"}},{q="Quais são as notícias contidas na carta?",a="A mensagem informa a Jin'Zil que Serena Bloodfeather, a líder das harpias que desciam em direção ao norte dos Sertões, foi morta, protegendo o perímetro ao norte da Encruzilhada.",al={"o que diz a carta","mensagem da carta"}},{q="Por que Jin'Zil se importa com as Bloodfeathers?",a="Jin'Zil se lembra da fundação de Durotar após a Terceira Guerra, quando seu companheiro Rokhan e o guerreiro meio-ogro Rexxar mataram a irmã mais velha de Serena. Desde então, Serena buscou vingança contra a Horda, tornando sua queda um desfecho bem-vindo.",al={"por que jinzil harpias","história de bloodfeather","rokhan e bloodfeather"}}},fx={f9426e82={q="Por que Jin'Zil quer que a Carta para Jin'Zil seja entregue a ele?",a="A carta traz notícias muito esperadas de seu velho amigo Darsok Punhálacre nos Sertões. Jin'Zil não ouve falar de Darsok há muitos anos, e a missiva confirma a morte de Serena Bloodfeather, pondo fim às matriarcas harpias que perturbavam tanto os Sertões quanto a Cordilheira das Torres de Pedra.",al={"por que entregar a carta para jin'zil","quem quer a carta para jin'zil","por que jin'zil se importa com a carta"}}},fp="17,157,25.330.0,26.369.1,32.137.0,25.116.0,41.183.0,46.243.1"}
P.entries["item:letter-to-jorgen"] = {n="Carta a Jorge",s="A Carta a Jorge é uma missiva confidencial redigida para recrutar um velho contato em Ventobravo. Ela serve como apresentação de um agente durante os estágios iniciais de uma investigação sobre um desaparecimento diplomático de alto nível.",h="A Carta a Jorge é uma missiva confidencial redigida para recrutar um velho contato em Ventobravo.",kw={"jaina proudmore","jorge","carta a jorge","diplomata desaparecido","ventobravo","theramore","vale dos heróis"},ang={["class:Rogue"]="Operar por meio de despachos discretos e informantes relutantes nas ruas, em vez da guarda da cidade, é um método familiar e necessário para descobrir crimes na capital.",["faction:Alliance"]="A missiva aborda a frágil estabilidade da Aliança, buscando lidar silenciosamente com um incidente que ameaça os laços diplomáticos entre Ventobravo e Theramore."},sec={{t="Uma Convocação Desapaixonada",b="Quando um diplomata de alto escalão a caminho de Theramore não compareceu às negociações agendadas com Grã-senhora Jaina Proudmore, os investigadores reais se apressaram para manter o incidente em sigilo. Enquanto agentes oficiais começavam a vasculhar a capital, canais alternativos foram silenciosamente mobilizados. Esta carta selada foi redigida para contornar a burocracia militar padrão, direcionada especificamente a Jorge — um veterano rabugento que passa seus dias pescando sob as estátuas colossais no Vale dos Heróis. O bilhete apela para velhas obrigações, puxando um contato relutante para uma investigação secreta cercada por rumores de conspiração Défias."}},faq={{q="Qual é o propósito desta carta?",a="A carta atua como uma apresentação e um apelo para honrar uma velha obrigação. Ela direciona o portador até Jorge, um agente no Vale dos Heróis, para trazer um olhar independente ao caso de um diplomata desaparecido sem alertar o público geral.",al={"o que faz carta a jorge","por que carta a jorge","objetivo da carta"}},{q="Quem é Jorge?",a="Jorge é um contato recluso que reside logo na entrada dos portões de Ventobravo, passando seu tempo pescando nas águas do Vale dos Heróis. Embora se irrite com interrupções, ele está obrigado por uma dívida passada a ajudar quando esta missiva lhe for apresentada.",al={"quem e jorge","pnj jorge","jorge ventobravo"}},{q="A qual desaparecimento a carta se refere?",a="Um diplomata proeminente partiu de Ventobravo em uma viagem para Theramore a fim de ter uma audiência com Grã-senhora Jaina Proudmore, mas desapareceu no caminho. As suspeitas apontam para A Irmandade Défias, embora a extensão total da trama continue sendo mantida sob estrito sigilo.",al={"qual diplomata esta desaparecido","quem desapareceu","diplomata desaparecido"}},{q="Onde a carta é entregue?",a="A carta é levada ao Vale dos Heróis, a grandiosa entrada de Ventobravo ladeada por monumentos aos heróis da Segunda Guerra. Jorge pode ser encontrado à beira d'água, perto dos portões da frente.",al={"onde levar a carta","localizacao de jorge","onde esta jorge"}}},fx={["0eeb183b"]={q="O que é a Carta a Jorge?",a="Esta carta é uma mensagem confidencial enviada a respeito do desaparecimento silencioso de um diplomata de Ventobravo a caminho de Theramore. Como agentes reais oficiais já estão vasculhando a cidade abertamente, este bilhete selado recruta contatos particulares e discretos fora dos canais comuns da coroa para investigar o suposto envolvimento da The Defias Brotherhood.",al={"o que é a carta a jorge","item carta a jorge","sobre a carta a jorge"}},["5d64bfbf"]={q="De onde vem a Carta a Jorge e quem a escreveu?",a="A carta foi redigida pelo Bispo DeLavey em Ventobravo, que buscava uma investigação independente sobre o diplomata desaparecido. Confiando em aliados pessoais em vez de investigadores conspícuos da coroa, ele redigiu a mensagem especificamente para pedir ajuda a um velho amigo chamado Jorge, que atualmente mantém um perfil discreto perto das águas do Vale dos Heróis.",al={"quem escreveu a carta a jorge","quem enviou a carta a jorge","origem da carta a jorge"}},["9fd54092"]={q="Por que a Carta a Jorge é procurada?",a="Jorge precisa da carta porque ela descreve uma obrigação secreta que ele não pode ignorar. Embora relutante em ser afastado de sua pescaria tranquila, o conteúdo da missiva o convence a ajudar a desvendar o complô da Defias antes que o pânico se espalhe pela capital.",al={"por que entregar a carta a jorge","por que jorge precisa da carta","objetivo de entregar a carta a jorge"}}},fp="16,80,23.440.0,35.174.0,14.196.0,45.206.0,30.181.0"}
P.entries["item:lewis-note"] = {n="Bilhete do Ludovico",s="O Bilhete do Ludovico é uma requisição urgente de suprimentos escrita pelo Intendente Ludovico no Morro da Sentinela. Levado por um mensageiro em voo de grifo, ele solicita remessas vitais de equipamentos de proteção a um armeiro particular em Cidade Velha, Ventobravo.",h="O Bilhete do Ludovico é uma requisição urgente de suprimentos escrita pelo Intendente Ludovico no Morro da...",kw={"grifo","bilhete do ludovico","limited immunity","cidade velha","larso norde","intendente ludovico","morro da sentinela","thor"},ang={["race:Human"]="Entregar esta requisição ensina jovens aventureiros humanos a utilizar a rede de grifos do reino, ao mesmo tempo em que expõe a dura realidade de quão pouco os governantes de Ventobravo estão fazendo para equipar os defensores de Cerro Oeste."},sec={{t="Um Apelo por Aço",b="A Milícia do Povo no Morro da Sentinela opera com um orçamento apertadíssimo, recebendo pouco apoio oficial da Casa dos Nobres em Ventobravo. Enfrentando escaramuças constantes contra a Irmandade Défias, a guarnição esgota regularmente seus parcos estoques de equipamento. Para manter os defensores equipados, o Intendente Ludovico depende de acordos comerciais privados em vez da logística da coroa. Esta nota de requisição contorna totalmente os canais militares oficiais, incumbindo um mensageiro da Aliança de voar de grifo até Cidade Velha e apresentar o pedido diretamente a Larso Norde, proprietário da loja Limited Immunity."}},faq={{q="O que é o Bilhete do Ludovico?",a="É um pedido por escrito do Intendente Ludovico no Morro da Sentinela solicitando a Larso Norde, um armeiro em Ventobravo, o envio de mais equipamentos de proteção para a combalida guarnição de Cerro Oeste.",al={"o que é este item","objetivo do bilhete do ludovico","o que o bilhete faz"}},{q="Quem escreveu este bilhete?",a="Foi escrito pelo Intendente Ludovico, o oficial encarregado de gerenciar suprimentos, provisões e armamentos para a Milícia do Povo estacionada no Morro da Sentinela.",al={"quem é ludovico","intendente ludovico"}},{q="Quem recebe o bilhete?",a="O bilhete é levado primeiro ao mestre de grifos Thor no Morro da Sentinela e, em seguida, entregue diretamente a Larso Norde dentro de sua loja de armaduras, a Limited Immunity, localizada no distrito de Cidade Velha, em Ventobravo.",al={"para onde vai o bilhete","quem recebe o bilhete do ludovico","bilhete para larso norde"}},{q="Por que a guarnição não recebe armaduras diretamente do reino?",a="O governo do reino praticamente negligenciou Cerro Oeste, deixando os defensores locais por conta própria, sem financiamento militar direto ou armaduras fornecidas pela coroa. Ludovico precisa recorrer a contatos comerciais pessoais, como Larso Norde, para manter a milícia equipada.",al={"por que comprar de larso","por que ventobravo não ajuda","ajuda de ventobravo a cerro oeste"}}},fp="11,153,16.423.0,20.153.0,20.125.0,22.166.0,57.204.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Insígnia do Tenente",s="A Insígnia do Tenente é um emblema usado por membros graduados do culto da Lâmina Ardente escondidos em Durotar. Recuperada por aventureiros da Horda, ela serve como prova crucial da atividade do culto operando perigosamente perto de Orgrimmar.",h="A Insígnia do Tenente é um emblema usado por membros graduados do culto da Lâmina Ardente escondidos em...",kw={"lâmina ardente","antro das sombras","durotar","hidden enemies","insígnia do tenente","neeru fireblade","shadow council","rocha da caveira","thrall"},ang={["class:Warlock"]="O distintivo mostra como a Lâmina Ardente faz mau uso da magia caótica para servir à Legião Ardente, complicando diretamente a tênue tolerância de Thrall com os bruxos leais da Horda.",["faction:Horde"]="Para a jovem Horda, a insígnia representa a ameaça insidiosa da corrupção demoníaca tentando subverter a nova nação de Thrall por dentro."},sec={{t="Uma Marca do Culto",b="Recuperada de cultistas entrincheirados dentro da Rocha da Caveira ao longo da costa leste de Durotar, a Insígnia do Tenente identifica seu portador como um oficial da Lâmina Ardente. Embora o Chefe de Guerra Thrall se recuse a tolerar traidores em sua nova nação, um expurgo imediato apenas dispersaria o culto antes que seus mestres pudessem ser expostos. Em vez disso, Thrall transforma o distintivo em uma credencial falsa, entregando-o de volta a um campeão de confiança para testar a lealdade de infiltrados suspeitos à espreita logo abaixo de Orgrimmar."},{t="Antro das Sombras",b="Thrall orienta seu agente a levar o símbolo até Antro das Sombras e apresentá-lo ao bruxo Neeru Fireblade. Acreditando estar recebendo um subordinado recém-promovido, Neeru morde a isca por completo. Cego pela arrogância, o bruxo vangloria-se abertamente de que a Lâmina Ardente atua como um instrumento direto do Shadow Council e da Legião Ardente, dando a Thrall, sem saber, a brecha necessária para expor a corrupção enraizada sob a cidade."}},faq={{q="De onde vem a Insígnia do Tenente?",a="Ela é recuperada de fanáticos e aprendizes da Lâmina Ardente que operam dentro da Rocha da Caveira, uma caverna ao longo da costa a leste de Orgrimmar, em Durotar.",al={"como conseguir insignia do tenente","quem dropa insignia do tenente","origem da insignia do tenente"}},{q="Para que a insígnia é usada?",a="O Chefe de Guerra Thrall usa a insígnia para criar um disfarce para seu agente. Portando-a, um jovem aventureiro pode se passar por um oficial da Lâmina Ardente e ir a lugares onde os próprios agentes de Thrall não podem ir, descobrindo quem realmente lidera o culto.",al={"para que serve a insignia do tenente","missao com a insignia do tenente","o que fazer com a insignia"}},{q="Quem é Neeru Fireblade?",a="Neeru Fireblade é um bruxo orc que reside em Antro das Sombras, em Orgrimmar. Embora afirme servir a Thrall demonstrando que os bruxos podem ajudar a Horda, ele é secretamente o líder local do culto da Lâmina Ardente.",al={"quem e neeru","historia neeru fireblade"}},{q="Por que Thrall não mata Neeru Fireblade imediatamente?",a="Thrall sabe que Neeru é um traidor, mas atacar prematuramente apenas alertaria os verdadeiros mestres do culto e dispersaria sua rede. Thrall prefere manipular Neeru como um informante involuntário para desvendar a presença mais ampla do Shadow Council em Durotar.",al={"por que thrall nao mata neeru","por que manter neeru vivo","por que infiltrar neeru"}}},fx={["2e1cfb76"]={q="O que é a Insígnia do Tenente?",a="É um emblema carregado por oficiais dentro do culto da Lâmina Ardente, marcando o portador como um tenente graduado reconhecido entre suas fileiras. Para cultistas demoníacos que operam em segredo por Durotar, apresentar este distintivo significa lealdade, posição e autoridade dentro da rede do Conselho das Sombras.",al={"o que é a insígnia do tenente","insígnia da lâmina ardente"}}},fp="21,121,18.363.0,19.359.1,47.135.0,30.207.1,23.183.2,57.211.1"}
P.entries["item:lightning-gland"] = {n="Glândula Relampejante",s="Glândulas Relampejantes são obtidas de feras stormhide que vagam pelas planícies dos Sertões. Imbuídas de uma carga elemental natural, elas são procuradas pelo Cervejeiro Drohn em Vila Catraca para preparar uma cerveja trogg potente e ardente, aprendida com o pandaren errante Chen Malte do Trovão.",h="Glândulas Relampejantes são obtidas de feras stormhide que vagam pelas planícies dos Sertões.",kw={"sertões","cervejeiro drohn","chen malte do trovão","glândula relampejante","vila catraca","stormhide","cerveja trogg"},ang={["profession:Cooking"]="Embora não sejam um ingrediente culinário comum, as glândulas relampejantes demonstram a filosofia cervejeira de fronteira de Chen Malte do Trovão e do Cervejeiro Drohn, infundindo órgãos brutos de feras diretamente em uma bebida espirituosa."},sec={{t="Um Ingrediente Chocante",b="As savanas dos Sertões abrigam uma variedade de predadores tocados pelos elementos, incluindo os stormhides. Dentro de sua carne encontra-se a glândula relampejante, um órgão que pulsa com energia elétrica latente. Embora dificilmente adequadas para a culinária comum, essas glândulas voláteis são muito valorizadas por cervejeiros excêntricos que apreciam uma bebida com uma verdadeira picada."},{t="A Cerveja Trogg de Drohn",b="Na cidade portuária de Vila Catraca, o Cervejeiro Drohn dá continuidade às tradições cervejeiras ensinadas a ele por Chen Malte do Trovão. Para preparar uma bebida potente conhecida como cerveja trogg, Drohn precisa de cinco glândulas relampejantes, além de uma glândula salivar de falcotrom e um fígado de kodo fresco. O trago resultante tem um impacto inconfundível que os aventureiros acham revigorante e potente."}},faq={{q="Quais criaturas possuem glândulas relampejantes?",a="Glândulas relampejantes são obtidas de stormhides que vagam pelas vastas savanas dos Sertões.",al={"onde conseguir glândula relampejante","quem dropa glândula relampejante","stormhide glândula relampejante"}},{q="Quem quer glândulas relampejantes e por quê?",a="O Cervejeiro Drohn em Vila Catraca as coleta para preparar uma leva de cerveja trogg, uma receita ensinada a ele pelo mestre cervejeiro errante Chen Malte do Trovão.",al={"quem precisa de glândula relampejante","entregar glândula relampejante","utilidade da glândula relampejante"}},{q="O que mais é necessário além da glândula relampejante?",a="A receita de Drohn pede cinco glândulas relampejantes, uma glândula salivar de falcotrom de falcotrons maiores e um fígado de kodo fresco retirado das feras dos Sertões.",al={"ingredientes da cerveja trogg de drohn","barril de chen 3 itens"}}},fx={f0cc18d7={q="O que é uma glândula relampejante?",a="Uma glândula relampejante é um órgão colhido de bestas de couro-tempestade que vagam pelos Sertões. Imbuída das energias elétricas naturais que percorrem essas criaturas, a glândula contém uma potente carga elemental que a torna valiosa como um ingrediente exótico de alquimia.",al={"o que é a glândula relampejante","lore da glândula relampejante","o que é uma glândula relampejante"}},ba679c5d={q="De onde vem uma glândula relampejante?",a="Glândulas relampejantes não são feitas por mãos mortais; são órgãos biológicos retirados diretamente dos couro-tempestade que perseguem as savanas dos Sertões. Essas bestas selvagens desenvolvem naturalmente as glândulas para canalizar energia elétrica estalante.",al={"de onde vêm as glândulas relampejantes","origem da glândula relampejante","como as glândulas relampejantes são feitas"}}},fp="15,155,21.241.0,17.277.0,38.63.0,35.131.0,50.143.0"}
P.entries["item:logging-rope"] = {n="Corda para Transportar Toras",s="A Corda para Transportar Toras é um cordame pesado vital para as operações madeireiras contínuas do clã Brado Guerreiro em Vale Gris. Remessas desta linha resistente foram emboscadas e roubadas por tribos locais de furborgs que resistem violentamente à expansão da Horda pela floresta ancestral.",h="A Corda para Transportar Toras é um cordame pesado vital para as operações madeireiras contínuas do clã Brado...",kw={"vale gris","foulweald","locke okarr","corda para transportar toras","posto machadada","thistlefur","acampamento de lenhadores brado guerreiro","suprimentos do brado guerreiro"},ang={["faction:Horde"]="Recuperar as cordas de extração é vital para manter a máquina de guerra do clã Brado Guerreiro abastecida com madeira, apesar das constantes emboscadas.",["race:Orc"]="O assentamento órquico em Kalimdor depende inteiramente da madeira de Vale Gris, tornando cada caixote roubado de ferramentas de corte um ultraje que exige retaliação."},sec={{t="Cordas Roubadas",b="A manutenção do maquinário de fabricação gnômica e das serrarias do Acampamento de Lenhadores Brado Guerreiro exige grandes quantidades de cabos de extração duráveis. Em vez de chegarem aos lenhadores em seu acampamento, remessas essenciais foram interceptadas pelas tribos de furborgs Foulweald e Thistlefur. Enlouquecidos pela corrupção e ferozmente defensores de suas florestas ancestrais, esses furborgs acumulam as cordas roubadas em seus acampamentos pelo norte e centro de Vale Gris."},{t="Abastecendo o Esforço de Guerra",b="Locke Okarr, no Posto Machadada, tem a tarefa de recuperar a cadeia logística perdida antes que o acampamento de lenhadores Brado Guerreiro seja paralisado. Recuperar a corda pesada diretamente das mães-de-toca e dos guerreiros furborgs permite à Horda fixar a madeira cortada, amarrar toras e montar o maquinário das serras em meio à constante resistência de guerrilha dos habitantes nativos da floresta."}},faq={{q="Para que serve a Corda para Transportar Toras?",a="É uma corda grossa de padrão industrial, necessária ao Acampamento de Lenhadores Brado Guerreiro para amarrar a madeira colhida, puxar toras por terrenos acidentados e fixar maquinário pesado em Vale Gris.",al={"uso da corda para transportar toras","por que brado guerreiro precisa de corda","corda para transportar toras brado guerreiro"}},{q="Quem roubou a corda para transportar toras?",a="As remessas foram atacadas pelos furborgs nativos Foulweald e Thistlefur, que levaram as cordas roubadas para suas tocas nas aldeias e acampamentos por todo o Vale Gris.",al={"quem pegou a corda","ladrão de corda","quais furborgs têm a corda"}},{q="Quem quer essa corda de volta?",a="Locke Okarr, instalado no Posto Machadada, solicita a corda juntamente com outros suprimentos extraviados para garantir que as operações no Acampamento de Lenhadores Brado Guerreiro não sejam paralisadas.",al={"quem precisa da corda para transportar toras","iniciador da missão da corda para transportar toras"}},{q="Por que os furborgs roubam suprimentos de extração de madeira?",a="Os furborgs se opõem violentamente ao desmatamento de Vale Gris pela Horda. Interceptar caravanas de suprimentos desestabiliza as serrarias e vinga a invasão de seus territórios.",al={"motivo dos furborgs","por que furborgs atacam remessas"}}},fx={["26f07746"]={q="O que é a Corda para Transportar Toras?",a="A Corda para Transportar Toras é uma corda resistente vital para as extensas operações de madeira do clã Brado Guerreiro por todo o Vale Gris. Usada para prender, puxar e amarrar enormes árvores derrubadas, é um item indispensável da colheita diária do acampamento madeireiro.",al={"o que é a corda para transportar toras","informações sobre a corda para transportar toras","corda para transportar toras do brado guerreiro"}}},fp="12,184,12.342.0,24.231.0,30.118.0,27.130.0,25.136.0,43.120.0"}
P.entries["item:lok-s-skull"] = {n="Crânio de Lok",s="O Crânio de Lok é a cabeça decepada de Lok Orcbane, um feroz guerreiro dos Presanúbia que liderou ataques brutais de quilboars contra as rotas de suprimentos da Horda nos Sertões Meridionais. Procurado pelo quilboar aprisionado Denterroto como um ato de vingança, o crânio serve como prova inegável de que o chefe dos invasores caiu.",h="O Crânio de Lok é a cabeça decepada de Lok Orcbane, um feroz guerreiro dos Presanúbia que liderou ataques...",kw={"betrayal from within","acampamento taurajo","encruzilhada","lok orcbane","crânio de lok","denterroto","presanúbia","thork"},ang={["faction:Horde"]="Tomar o crânio de Lok Orcbane desmonta a liderança quilboar do sul que assedia constantemente as caravanas de suprimentos entre o Acampamento Taurajo e A Encruzilhada.",["race:Orc"]="Exibir a cabeça decepada de um chefe quilboar audaciosamente chamado 'Orcbane' proporciona profunda satisfação pessoal e segurança aos orcs que defendem os Sertões."},sec={{t="A Queda de um Chefe",b="Saindo do Urzal dos Tuscos para os Sertões Meridionais, Lok Orcbane liderou assaltos agressivos de quilboars Presanúbia contra as linhas de suprimentos da Horda ao lado de seus tenentes Nak e Kuz. Após trair e abandonar Denterroto ao cativeiro no Acampamento Taurajo, Lok ganhou uma reputação sombria entre os defensores orcs que lutavam para conter seus ataques impiedosos. Reivindicar o Crânio de Lok não apenas vinga o cativo injustiçado que direciona os campeões da Horda ao acampamento de Lok, mas também despedaça a liderança central que impulsiona a ofensiva Presanúbia."},{t="Prova para a Encruzilhada",b="Enquanto Denterroto exige os crânios de todos os três conspiradores para satisfazer sua própria vingança, ele devolve o Crânio de Lok para que possa ser levado ao norte, para Thork em A Encruzilhada. Thork e o comando da Horda suspeitavam que outro quilboar estivesse orquestrando os ataques, tornando o troféu macabro uma surpresa profunda e a prova conclusiva de que a ameaça às rotas comerciais centrais dos Sertões foi decisivamente eliminada."}},faq={{q="Quem era Lok Orcbane?",a="Lok Orcbane foi um formidável guerreiro Presanúbia que surgiu do Urzal dos Tuscos para comandar grupos de ataque de quilboars pelos Sertões Meridionais. Conhecido por seu ódio pelos orcs e táticas astutas, ele organizou assaltos agressivos a caravanas e postos avançados da Horda ao lado de seus aliados de confiança, Nak e Kuz.",al={"quem é lok","lore de lok orcbane","quem era lok orcbane"}},{q="Por que Denterroto quer o Crânio de Lok?",a="Lok Orcbane e seus companheiros traíram Denterroto, abandonando-o para ser capturado e enjaulado pelos taurens no Acampamento Taurajo. Sabendo que seu próprio fim é inevitável, Denterroto busca vingança contra os parentes que lhe viraram as costas, direcionando aventureiros da Horda para executar seus antigos camaradas.",al={"por que denterroto quer o crânio","vingança de denterroto","por que matar lok"}},{q="Por que o crânio é levado a Thork em A Encruzilhada?",a="Thork supervisiona a defesa de A Encruzilhada e trabalha para proteger rotas vitais de suprimentos da Horda contra incursões de quilboars. Entregar o Crânio de Lok prova ao comandante orc que o verdadeiro mentor por trás dos ataques do sul foi morto, garantindo paz aos viajantes da região.",al={"por que levar o crânio para thork","thork crânio de lok","quem recebe o crânio de lok"}},{q="Quem eram Nak e Kuz?",a="Nak e Kuz eram colegas líderes de ataque de Lok Orcbane nos Sertões Meridionais. Denterroto descreve um como um conjurador e o outro como um rastreador, apoiando a força guerreira de Lok na organização de ataques contra a Horda.",al={"nak e kuz","tenentes de lok orcbane","kuz e nak"}}},fx={a8e2f7c2={q="O que é o Crânio de Lok?",a="O Crânio de Lok é a cabeça decepada de Lok Ruinorc, um guerreiro feroz que liderava ataques impiedosos dos javatus ferroníver contra as rotas de suprimentos da Horda nos Sertões Meridionais. Tomado como prova sombria de sua morte, serve tanto como um instrumento de vingança para um membro da tribo traído quanto como evidência inegável para os defensores da Encruzilhada de que a ameaça foi eliminada.",al={"o que é o crânio de lok","item crânio de lok","o que é este crânio"}},["4d726f58"]={q="De onde vem o Crânio de Lok?",a="Ele é retirado diretamente do corpo morto de Lok Ruinorc nos Sertões Meridionais. Lok e seus tenentes surgiram do Urzal dos Tuscos para organizar grupos de ataque contra a Horda, até que Denterroto, um javatus banido mantido no Acampamento Taurajo, revelou a fortaleza deles para que Lok pudesse ser derrotado.",al={"de onde veio o crânio de lok","quem fez o crânio de lok","fonte do crânio de lok"}}},fp="11,183,18.461.0,24.319.1,20.250.0,38.265.0,52.240.0,21.196.0"}
P.entries["item:lonebrow-s-journal"] = {n="Diário do Monocelha",s="O Diário do Monocelha é um diário desgastado encontrado preso nos restos esqueléticos do explorador anão Henrig Lonebrow na base d'O Grande Elevador. Suas páginas detalham a última e sombria jornada de Monocelha pelos Sertões e apontam para perigos à espreita no Urzal dos Tuscos.",h="O Diário do Monocelha é um diário desgastado encontrado preso nos restos esqueléticos do explorador anão...",kw={"the crone of the kraul","falfindel waywarder","o grande elevador","henrig lonebrow","urzal dos tuscos","thalanaar","mil agulhas"},ang={["faction:Alliance"]="Os últimos escritos de Henrig Lonebrow forjam uma ligação crucial entre batedores da Aliança e os druidas que guardam a fronteira com Feralas, reunindo ajuda contra a ameaça dos javatuscos.",["race:Dwarf"]="Descobrir um semelhante caído em terras tão remotas e hostis é um lembrete sombrio dos perigos que os exploradores anões enfrentam enquanto realizam reconhecimento muito além de Khaz Modan."},sec={{t="Um Último Desejo n'O Grande Elevador",b="Henrig Lonebrow teve um fim trágico perto da base d'O Grande Elevador, que liga os Sertões a Mil Agulhas. Abandonados em uma saliência rochosa, seus restos esqueléticos ainda seguram este diário desgastado. O diário serve como um testamento de suas últimas viagens e orienta quem o descobrir a levar notícias ao druida elfo noturno Falfindel Waywarder em Thalanaar, o posto fronteiriço que conduz a Feralas. As anotações de Monocelha lançam luz crítica sobre a ameaça dos javatuscos que cresce nos Sertões Meridionais."},{t="Laços com o Urzal",b="Quando entregues a Falfindel Waywarder, os registros de Monocelha confirmam as crescentes preocupações da Aliança em relação aos javatuscos do Urzal dos Tuscos. O conteúdo do diário conduz diretamente a um chamado para que heróis ataquem o coração do labirinto espinhoso e derrotem Charlga Talhaflanco, The Crone of the Kraul, que orquestra a ameaça dos javatuscos."}},faq={{q="Quem foi Henrig Lonebrow?",a="Henrig Lonebrow foi um viajante anão que pereceu aos pés d'O Grande Elevador em Mil Agulhas. Ele morreu com seu diário preso na mão, com a intenção de que seu conteúdo chegasse aos elfos noturnos posicionados em Thalanaar.",al={"henrig lonebrow","quem é monocelha","anão morto elevador"}},{q="Onde o diário é encontrado?",a="O diário repousa ao lado do esqueleto de Henrig Lonebrow, logo na saída da rampa na base d'O Grande Elevador, em uma saliência rochosa baixa no norte de Mil Agulhas.",al={"onde fica diário do monocelha","encontrar diário do monocelha","esqueleto no grande elevador"}},{q="Quem deve receber o Diário do Monocelha?",a="O diário deve ser levado a oeste através de Mil Agulhas para Falfindel Waywarder, um druida elfo noturno estacionado em Thalanaar ao longo da fronteira de Feralas.",al={"para quem levar o diário","falfindel waywarder","onde entregar o diário"}},{q="A que o diário leva?",a="Ler o diário e relatar a Falfindel Waywarder revela informações sobre os javatuscos, levando a uma missão no Urzal dos Tuscos para derrotar a velha Charlga Talhaflanco.",al={"missão the crone of the kraul","continuação do diário do monocelha"}}},fx={a9190e03={q="O que é o Diário do Monocelha?",a="O Diário do Monocelha é um registro pessoal desgastado encontrado apertado nas mãos esqueléticas do anão Henrig Monocelha. Descoberto ao pé do Grande Elevador em Mil Agulhas, ele documenta suas viagens e desejos finais antes de encontrar seu fim no cânion.",al={"o que é o diário do monocelha","o que é este livro","diário do monocelha de henrig"}},["090ee1d4"]={q="De onde vem o Diário do Monocelha e quem o fez?",a="O diário foi redigido por Henrig Monocelha, um viajante anão que viajou pelos cânions traiçoeiros de Mil Agulhas. Ele o carregou consigo até sua morte perto da base do Grande Elevador, onde seus restos mortais e o volume foram finalmente descobertos.",al={"quem escreveu o diário do monocelha","autor do diário do monocelha","de onde veio o diário"}},ea8f453f={q="Por que alguém quer o Diário do Monocelha?",a="Entregar o diário cumpre os desejos finais do anão caído. Falfindel Waywarder, um druida elfo noturno estacionado em Thalanaar na fronteira de Feralas, busca ler seu conteúdo para entender o destino de Henrig e descobrir os perigos que se agitam no Urzal dos Tuscos.",al={"por que entregar o diário do monocelha","quem precisa do diário do monocelha","por que querer o diário do monocelha"}}},fp="18,144,30.432.0,20.245.1,24.192.0,27.150.0,38.134.0,30.133.1"}
P.entries["item:lookout-s-spyglass"] = {n="Luneta do Espia",s="A Luneta do Espia é um instrumento roubado, muito valorizado pela Irmandade do Tório. Sua perda deixa os vigias da Garganta Abrasadora sem uma excelente ferramenta para observar a região.",h="A Luneta do Espia é um instrumento roubado, muito valorizado pela Irmandade do Tório.",kw={"dark iron lookouts","luneta do espia","garganta abrasadora","fosso de lava","luneta","instrumento roubado","capataz scrange","irmandade do tório"},sec={{t="Um instrumento roubado",b="Dark Iron dwarves roubaram a Luneta do Espia da Irmandade do Tório na Garganta Abrasadora. A Irmandade quer que ela seja devolvida ao Capataz Scrange, que aguarda os bens roubados."}},faq={{q="O que é a Luneta do Espia?",a="A Luneta do Espia é uma excelente ferramenta de vigilância usada pelos vigias.",al={"luneta","luneta do espia","o que é a luneta"}},{q="Quem roubou a luneta?",a="A Irmandade do Tório afirma que Dark Iron dwarves na Garganta Abrasadora roubaram a Luneta do Espia.",al={"quem a roubou","dark iron stole spyglass","ladrões da luneta"}},{q="Quem quer a luneta de volta?",a="O Capataz Scrange, da Irmandade do Tório, quer que a Luneta do Espia roubada seja devolvida.",al={"quem a quer","devolver a luneta","luneta scrange"}},{q="Onde ficam os Dark Iron Lookouts?",a="Dark Iron Lookouts vigiam de torres ao redor do Fosso de Lava, na Garganta Abrasadora.",al={"localização dos vigias","onde ficam os vigias","torres dos dark iron lookouts"}},{q="Por que a Irmandade a quer?",a="A Luneta do Espia é uma ferramenta de vigilância inestimável para os vigias.",al={"por que a luneta é importante","uso da luneta","para que serve"}}},fp="18,170,19.180.0,31.72.0,23.93.0,28.96.0,33.74.0,33.73.0"}
P.entries["item:lorgalis-manuscript"] = {n="Manuscrito de Lorgalis",s="O Manuscrito de Lorgalis é um texto antigo ligado à adoração e à história dos Deuses Antigos, preservado das ruínas élficas caídas sob Vale Gris. Oculto dentro do complexo do templo submerso de Profundezas Negras, ele guarda segredos cobiçados por estudiosos sombrios que buscam despertar poderes antigos e adormecidos.",h="O Manuscrito de Lorgalis é um texto antigo ligado à adoração e à história dos Deuses Antigos, preservado das...",kw={"profundezas negras","forlorn cavern","gerrig agarrosso","altaforja","lorgalis","manuscrito","deus antigo","aqueles que dormem"},ang={["class:Warlock"]="O manuscrito representa uma rara janela para a história proibida dos Deuses Antigos e das entidades das profundezas, oferecendo percepções cobiçadas por aqueles que lidam com artes sombrias.",["race:NightElf"]="O texto jaz nas ruínas afogadas onde elfos noturnos outrora viveram, e sua reverência por Aku'mai e pelos Deuses Antigos demonstra a adoração sombria que criou raízes entre aqueles salões arruinados."},sec={{t="Um Tomo Daqueles Que Dormem",b="O Manuscrito de Lorgalis repousa no fundo de Profundezas Negras, as ruínas submersas onde elfos há muito mortos habitaram antes da queda de sua cidade. Escrito por um tal de Lorgalis, ele fala sobre os Deuses Antigos que se enfureceram por Azeroth quando o mundo era novo e agora jazem acorrentados e adormecidos, e louva Aku'mai, um servo dos Deuses Antigos que habita nas Profundezas. Diz-se que seu conhecimento abre portais místicos e desperta entidades antigas que dormem nas profundezas sob o mundo. Guardado em um baú de ferro carcomido em meio aos corredores inundados, ele atraiu a atenção de cultistas e estudiosos das sombras."},{t="Olhos nas Sombras",b="Na Forlorn Cavern de Altaforja, um excêntrico colecionador chamado Gerrig Agarrosso contrata ativamente aventureiros intrépidos para se aventurarem pelo mar a fim de recuperar o texto. Agarrosso fala com reverência sobre os \"dias finais\" e o despertar de divindades adormecidas. Uma vez recuperado, pretende-se que o texto seja transcrito e compartilhado entre seu círculo sombrio de irmãos e irmãs, espalhando percepções proibidas que o povo da superfície jamais deveria compreender."}},faq={{q="O que é o Manuscrito de Lorgalis?",a="É um texto antigo escrito por um tal de Lorgalis, contendo conhecimento sombrio e esotérico sobre os Deuses Antigos. Diz-se que seu conteúdo guarda os segredos necessários para abrir portais e despertar entidades primordiais adormecidas.",al={"o que é o manuscrito de lorgalis","história do livro de lorgalis","o que o manuscrito faz"}},{q="Onde o manuscrito está localizado?",a="O manuscrito repousa dentro de um baú de ferro carcomido submerso nas profundezas de Profundezas Negras, um templo élfico noturno em ruínas localizado ao longo da Praia de Zoram, em Vale Gris.",al={"onde encontrar o manuscrito de lorgalis","localização do manuscrito","baú de profundezas negras"}},{q="Quem quer o manuscrito?",a="Gerrig Agarrosso, um enigmático guardião do conhecimento que opera na Forlorn Cavern em Altaforja, encomenda aventureiros para recuperá-lo. Ele planeja copiar e distribuir seus ensinamentos antigos entre seus pares misteriosos.",al={"quem quer o manuscrito de lorgalis","missão de gerrig agarrosso","quem é agarrosso"}},{q="Por que Gerrig Agarrosso fala sobre os dias finais?",a="Agarrosso se alinha com aqueles que estudam e reverenciam os Deuses Antigos. Seu interesse pelos antigos escritos élficos concentra-se no conhecimento capaz de despertar \"Aqueles Que Dormem\", anunciando o que ele considera a chegada do fim dos tempos.",al={"gerrig dias finais","agarrosso cultista","agarrosso deuses antigos"}}},fx={["61ae2bf7"]={q="De onde vem o Manuscrito de Lorgalis e quem o fez?",a="O manuscrito foi escrito por um certo Lorgalis e jaz no fundo das Profundezas Negras, as ruínas submersas onde elfos há muito mortos outrora habitaram antes da queda de sua cidade. Quem foi Lorgalis não está registrado. O texto relata o conhecimento proibido sobre os Deuses Antigos e Aqueles que Dormem e louva Aku'mai, um servo dos Deuses Antigos que habita as Profundezas. Ele repousa trancado em um baú de ferro corroído nos salões inundados.",al={"origem do manuscrito de lorgalis","quem escreveu o manuscrito de lorgalis","onde foi feito o manuscrito de lorgalis"}}},fp="19,187,25.525.0,19.394.1,32.172.0,32.139.0,25.164.0,49.155.0"}
P.entries["item:lotwil-s-shackles-of-elemental-binding"] = {n="Lotwil's Shackles of Elemental Binding",s="Lotwil Viriato fez estas algemas para uma tentativa ousada de invocar um elemental nos Ermos. Recuperá-las é importante para seu trabalho.",h="Lotwil Viriato fez estas algemas para uma tentativa ousada de invocar um elemental nos Ermos.",kw={"alquimia","ermos","elemental","engenharia","fam'retor guardian","lotwil viriato","algemas de lotwil","algemas de vínculo elemental"},sec={{t="Uma invocação preparada",b="Nos Ermos, Lotwil Viriato terminou as algemas para um experimento notável. Ele chama Lucien e Servo para testemunharem sua mistura de alquimia, engenharia e magia arcana. Com o vínculo pronto, Lotwil pretende invocar um elemental poderoso."},{t="O resultado",b="O Fam'retor Guardian deixa para trás as algemas de Lotwil. Quando você as devolve, ele agradece pelo esforço e diz que sua magia mandou a criatura de volta para casa. Seja lá o que tenha dado errado, as algemas voltam para seu criador."}},faq={{q="O que são as Lotwil's Shackles of Elemental Binding?",a="São algemas que Lotwil Viriato fez para tentar prender um elemental poderoso.",al={"algemas de lotwil","algemas de vínculo elemental","o que são as algemas"}},{q="Quem fez as algemas?",a="Lotwil Viriato as fez como parte de um experimento que combina alquimia, engenharia e magia arcana.",al={"quem fez estas","criador das algemas de lotwil","quem é lotwil"}},{q="Onde posso encontrar as algemas?",a="O Fam'retor Guardian nos Ermos deixa para trás as algemas de Lotwil.",al={"onde ficam as algemas","localização das algemas","fam'retor guardian"}},{q="Por que Lotwil quer as algemas de volta?",a="Lotwil precisa que elas sejam devolvidas depois que sua tentativa de invocar um elemental poderoso dá errado.",al={"por que devolver as algemas","do que lotwil precisa","algemas para lotwil"}}},fp="38,130,20.249.0,11.217.1,48.83.0,22.99.0,30.71.1,39.86.1"}
P.entries["item:lunar-fungus"] = {n="Fungo Lunar",s="O Fungo Lunar é um potente vegetal medicinal colhido de eflorescências fúngicas nas profundezas dos sistemas de cavernas de Costa Negra. Iniciados druidas coletam esses cogumelos juntamente com ervas comuns para preparar um unguento restaurador capaz de tratar a vida selvagem doente.",h="O Fungo Lunar é um potente vegetal medicinal colhido de eflorescências fúngicas nas profundezas dos sistemas...",kw={"alanndária noturcanto","auberdine","curar veneno","costa negra","earthroot","lunar fungal bloom","fungo lunar"},ang={["class:Druid"]="Jovens druidas procuram o Fungo Lunar nas cavernas de Costa Negra como parte de seus ritos fundamentais para dominar a magia curativa e curar a vida selvagem envenenada.",["race:NightElf"]="Cuidar das criaturas corrompidas do bosque ao redor de Auberdine com remédios nativos como o Fungo Lunar é um dever contínuo para os guardiões de Costa Negra."},sec={{t="Propriedades e Ecologia",b="Colhido de Lunar Fungal Blooms, este fungo característico prospera em cavernas subterrâneas e escuras por toda Costa Negra. O Círculo Cenariano o valoriza por seus efeitos amplificadores; quando misturado a uma base de água calmante e Earthroot comum, o fungo fornece a potência necessária para criar um contraveneno eficaz contra aflições debilitantes. Por crescer principalmente em espaços subterrâneos úmidos frequentados por moonkin territoriais, obtê-lo exige navegar com cautela pelas terras ermas e selvagens."},{t="Uma Lição de Cura",b="Em Auberdine, Alanndária Noturcanto orienta jovens druidas a colherem o Fungo Lunar como parte de seus estudos nas artes restauradoras da natureza. Ao testemunharem como reagentes físicos como este fungo neutralizam venenos virulentos nos cervos locais, os iniciados aprendem os princípios fundamentais dos remédios herbais antes de avançarem para canalizar antídotos naturais diretamente por meio da metamorfose e do poder espiritual puro."}},faq={{q="Para que serve o Fungo Lunar?",a="O Fungo Lunar fornece potência curativa no preparo de um unguento restaurador. Alanndária Noturcanto o combina com Earthroot e água limpa para tratar cervos enfermos por toda a natureza selvagem de Costa Negra.",al={"para que serve fungo lunar","o que faz o fungo lunar","por que coletar fungo lunar"}},{q="Onde o Fungo Lunar cresce?",a="Ele brota de Lunar Fungal Blooms abrigadas nas cavernas a leste de Auberdine, em Costa Negra. Essas cavernas escuras são compartilhadas com moonkin irritadiços que defendem seu território contra invasores.",al={"localização do fungo lunar","onde encontrar fungo lunar","eflorescências de fungo lunar"}},{q="Quem precisa deste fungo em Auberdine?",a="A druida Alanndária Noturcanto pede o Fungo Lunar a estudantes da natureza como parte de seu treinamento, utilizando suas propriedades medicinais naturais para formular remédios para os animais enfermos da floresta.",al={"quem precisa de fungo lunar","missão de ervas de auberdine"}},{q="Por que os iniciados druidas precisam colher ervas físicas para curar veneno?",a="Compreender os antídotos físicos é um passo fundamental na educação druídica. Ao colher reagentes selvagens como o Fungo Lunar e observar como ingredientes específicos neutralizam toxinas específicas, os alunos assimilam os princípios da cura antes de aprenderem a expurgar venenos diretamente por meio de magia espiritual.",al={"por que druidas colhem ervas","treinamento de cura de veneno druida"}}},fx={["2a41e7eb"]={q="O que é o Fungo Lunar?",a="O Fungo Lunar é um cogumelo medicinal potente nativo da Costa Negra. Ele floresce dentro de cavernas escuras a leste de Auberdine, colhido de grupos maiores conhecidos como florescências fúngicas lunares. Druidas valorizam o fungo por sua potência natural, utilizando suas propriedades como um ingrediente essencial ao preparar pomadas alquímicas para tratar a vida selvagem envenenada.",al={"o que é o fungo lunar","informações sobre o fungo lunar","sobre o fungo lunar"}}},fp="12,136,22.338.0,19.318.0,30.136.0,29.166.0,38.154.0,68.254.0"}
P.entries["item:lurker-venom"] = {n="Peçonha de Tocaieiro",s="Peçonha de Tocaieiro é uma potente toxina natural extraída das aranhas predadoras que rondam as colinas rochosas e os bosques de Loch Modan. Os defensores anões precisam desse veneno cáustico como ingrediente fundamental para preparar um composto alquímico neutralizador contra a sabotagem dos Ferro Negro.",h="Peçonha de Tocaieiro é uma potente toxina natural extraída das aranhas predadoras que rondam as colinas...",kw={"engenheiro-chefe hinderweir","cliff lurker","loch modan","peçonha de tocaieiro","shanda a fiandeira","veneno de aranha","dique lapidado","wood lurker"},ang={["profession:Engineering"]="O uso de toxinas orgânicas para desativar munições hostis demonstra uma vertente reativa e improvisada da engenharia anã em condições de campo de batalha.",["race:Dwarf"]="Montanhistas e defensores de Loch Modan rotineiramente utilizam perigos da vida selvagem local para proteger a infraestrutura crucial de Khaz Modan contra o clã Ferro Negro."},sec={{t="Um Reagente Volátil",b="As colinas e penhascos ao redor de Loch Modan estão repletos de aracnídeos predadores — desde os comuns tocaieiros-da-floresta até a infame matriarca Shanda, a Fiandeira. Embora suas picadas representem um perigo constante para montanhistas e viajantes, o especialista em explosivos Ashlan Risadura indicou seu veneno virulento como um dos ingredientes de uma Mistura de Desarme preparada pelo Engenheiro-chefe Hinderweir. Combinada com minerais raros e lágrimas colhidas dos crocoliscos do Loch, a Peçonha de Tocaieiro forma um solvente reativo capaz de desarmar explosivos complexos dos Ferro Negro."}},faq={{q="De onde vem a Peçonha de Tocaieiro?",a="Ela é extraída de várias aranhas tocaieiras nativas de Loch Modan, incluindo Cliff Lurkers, Forest Lurkers, Wood Lurkers e sua matriarca da ninhada, Shanda, a Fiandeira.",al={"como conseguir peçonha de tocaieiro","quem dropa peçonha de tocaieiro","onde achar peçonha de tocaieiro"}},{q="Para que serve a Peçonha de Tocaieiro?",a="O Engenheiro-chefe Hinderweir usa a peçonha como parte de uma mistura química especializada para neutralizar e desarmar artefatos explosivos instalados por infiltrados Ferro Negro ao redor do Dique Lapidado.",al={"por que preciso de peçonha de tocaieiro","para que serve peçonha de tocaieiro","o que hinderweir faz com o veneno"}},{q="Por que usar veneno para desarmar um explosivo?",a="Engenheiros anões frequentemente recorrem a misturas reativas, ácidas ou cáusticas para dissolver componentes mecânicos delicados ou neutralizar pólvoras instáveis sem detoná-las.",al={"por que veneno de aranha para bombas","como o veneno para bombas ferro negro"}},{q="Shanda, a Fiandeira, é a única fonte?",a="Não. Embora Shanda carregue o veneno, qualquer uma das aranhas tocaieiras selvagens comuns que habitam os bosques e penhascos rochosos de Loch Modan pode fornecê-lo.",al={"preciso matar shanda","peçonha de tocaieiro shanda"}}},fx={["0e11e6d3"]={q="O que é a Peçonha de Tocaieiro?",a="A Peçonha de Tocaieiro é uma toxina natural potente colhida das aranhas tocaieiras predatórias nativas da natureza selvagem acidentada de Loch Modan. Embora mortal para a presa, suas propriedades químicas distintas a tornam valiosa para artesãos e engenheiros especializados. O Engenheiro-chefe Hinderweir utiliza especificamente o fluido volátil como um reagente crucial em um solvente neutralizante alquímico projetado para desarmar com segurança os explosivos dos anões Ferro Negro.",al={"o que é a peçonha de tocaieiro","lore da peçonha de tocaieiro","que tipo de item é a peçonha de tocaieiro"}}},fp="12,147,18.533.0,34.147.0,30.160.0,37.163.0,38.133.0"}
P.entries["item:lydon-s-toxin"] = {n="Toxina do Lindolfo",s="A Toxina do Lindolfo é uma poção alquímica sintetizada pelo Boticário Lindolfo na Serraria Tarren para interromper o desmatamento promovido pelos Empreendimentos S.A. na Cordilheira das Torres de Pedra. Confiada a aventureiros da Horda, ela é entregue à Boticária Zaqueia no Penhasco do Trovão para que ela possa conceber um mecanismo de dispersão eficaz.",h="A Toxina do Lindolfo é uma poção alquímica sintetizada pelo Boticário Lindolfo na Serraria Tarren para...",kw={"boticário lindolfo","boticária zaqueia","toxina do lindolfo","real sociedade de boticários","penhasco do trovão","vaporizador tóxico","empreendimentos s.a."},ang={["race:Tauren"]="Embora os taurens aceitem de bom grado ajuda contra a destruição da natureza causada pelos Empreendimentos S.A., os métodos químicos da Real Sociedade de Boticários testam os limites de suas sensibilidades xamânicas.",["race:Undead"]="O transporte da Toxina do Lindolfo exemplifica a rede de longo alcance da Real Sociedade de Boticários, que coordena pesquisas de campo entre Lordaeron e Kalimdor para demonstrar a utilidade dos Renegados aos seus aliados."},sec={{t="Uma Solução do Boticário Real",b="Desenvolvido pelo Boticário Lindolfo no Contraforte de Eira dos Montes, este composto virulento foi criado para combater os madeireiros invasores dos Empreendimentos S.A. que assolam a Cordilheira das Torres de Pedra. De acordo com Lindolfo, a mistura produz resultados letais e potencialmente contagiosos ao contato. No entanto, antes que a substância possa ser usada contra as operações dos goblins ao redor do Rochedo Cortavento, ela precisa ser transportada entre continentes até a Boticária Zaqueia, a representante da Real Sociedade de Boticários no Penhasco do Trovão. Zaqueia precisa da mistura bruta para projetar um aparato de ampla dispersão — o Vaporizador Tóxico —, garantindo que o preparado aniquile os desmatadores exploradores sem colocar desnecessariamente em risco os recursos da Horda."}},faq={{q="Para que serve a Toxina do Lindolfo?",a="A toxina foi preparada pelo Boticário Lindolfo para quebrar o domínio dos Empreendimentos S.A. na região do Rochedo Cortavento. Ela foi desenvolvida para ser devastadora e potencialmente contagiosa contra os destrutivos trabalhadores goblins.",al={"objetivo da toxina do lindolfo","o que a toxina faz","por que criar a toxina do lindolfo"}},{q="Quem é o Boticário Lindolfo?",a="O Boticário Lindolfo é um membro da Real Sociedade de Boticários baseado na Serraria Tarren, no Contraforte de Eira dos Montes. Ele se especializou na criação de venenos virulentos e compostos experimentais para avançar os objetivos dos Renegados.",al={"quem é lindolfo","boticário lindolfo","criador lindolfo"}},{q="Por que a toxina precisa ir para o Penhasco do Trovão?",a="Embora Lindolfo tenha aperfeiçoado a mistura química, falta um método prático de aplicação em massa. A Boticária Zaqueia reside no Platô dos Espíritos, no Penhasco do Trovão, para estudar a flora regional e coordenar as ações da Sociedade em Kalimdor; ela recebe a toxina para adaptá-la a um sistema portátil de dispersão por nebulização.",al={"por que penhasco do trovão","por que levar a toxina para zaqueia","papel da boticaria zaqueia"}},{q="O que acontece depois que Zaqueia recebe a toxina?",a="Ao receber o frasco, a Boticária Zaqueia processa o agente em um dispositivo pressurizado de aerossol chamado Vaporizador Tóxico, permitindo que um operador o disperse no coração do acampamento dos Empreendimentos S.A.",al={"criacao do vaporizador toxico","o que zaqueia faz com a toxina"}}},fx={["73882111"]={q="O que é a Toxina do Lindolfo?",a="A Toxina do Lindolfo é uma mistura alquímica virulenta formulada pelo Boticário Lindolfo da Real Sociedade de Boticários. Projetada especificamente para uso contra a Empreendimentos S.A., controlada por goblins, a substância foi criada para produzir resultados devastadores e potencialmente contagiosos quando implantada contra as fileiras inimigas.",al={"o que é a toxina do lindolfo","toxina do lindolfo","sobre a toxina do lindolfo"}},["105322cc"]={q="Por que alguém quer a Toxina do Lindolfo?",a="Os boticários Renegados e seus aliados da Horda querem a toxina para erradicar os operativos invasores da Empreendimentos S.A. A Apothecary Zamah precisa da mistura de Lindolfo para que possa construir um mecanismo de entrega eficaz, permitindo que a Horda disperse seus efeitos letais e contagiosos por todo o canteiro de obras inimigo.",al={"por que querer a toxina do lindolfo","por que a toxina é necessária","objetivo da toxina do lindolfo"}}},fp="13,212,27.420.0,31.148.0,24.179.0,47.216.0,44.177.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="Carne-seca do MacGrann",s="A Carne-seca do MacGrann é o suprimento de um mês de provisões salgadas preparadas pelo caçador Tundra MacGrann para sobreviver ao rigoroso inverno de Dun Morogh. Guardada em um armário de carnes reforçado com tório, toda a reserva foi levada pelo feroz yeti conhecido como Old Icebeard.",h="A Carne-seca do MacGrann é o suprimento de um mês de provisões salgadas preparadas pelo caçador Tundra...",kw={"vale brisa álgida","dun morogh","carne-seca do macgrann","armário de carnes","old icebeard","tundra macgrann"},ang={["profession:Cooking"]="Salgar e curar a caça é uma técnica culinária de sobrevivência essencial em Dun Morogh, permitindo que caçadores como MacGrann conservem carnes por meses sem estragar no frio congelante.",["race:Dwarf"]="Os montanhistas anões sabem muito bem que a preparação significa sobrevivência nos picos elevados, e uma reserva de inverno perdida pode significar a diferença entre a vida e a morte."},sec={{t="Uma Reserva de Inverno",b="A vida nos penhascos congelantes de Dun Morogh exige um planejamento cuidadoso. Para se preparar para as nevascas da estação fria, o caçador anão Tundra MacGrann passou semanas caçando animais, salgando a carne e guardando tudo dentro de um baú resistente. Ciente de que ursos carniceiros e predadores à espreita atormentam rotineiramente sua propriedade, MacGrann não quis arriscar e trancou seu suprimento de comida dentro de um armário de carnes de tório. Mesmo com essas precauções, ele não previu um invasor forte o suficiente para carregar o baú inteiro em vez de tentar arrombá-lo no local."},{t="Dentro do Covil do Yeti",b="Enquanto MacGrann estava fora rastreando cervos, o notório yeti Old Icebeard invadiu o acampamento do caçador e arrastou o pesado baú de volta ao seu covil em Vale Brisa Álgida. Embora a fera não tivesse como romper a blindagem de tório maciço, a perna machucada de MacGrann o impedia de realizar um resgate rápido na caverna. Sem ajuda externa para recuperar a reserva antes da chegada do inverno, o caçador isolado enfrentava a fome em meio às neves da montanha."}},faq={{q="O que é a Carne-seca do MacGrann?",a="É o suprimento de um mês de provisões salgadas preservadas por Tundra MacGrann para sustentá-lo durante o inverno rigoroso de Dun Morogh.",al={"o que é carne-seca do macgrann","carne de tundra","reserva de carne de macgrann"}},{q="Por que as carnes estavam trancadas em um baú?",a="Dun Morogh está repleta de predadores famintos, como ursos-da-montanha. MacGrann manteve sua carne-seca protegida dentro de um armário de carnes reforçado com tório para que animais carniceiros não conseguissem violar seu suprimento de comida para o inverno.",al={"por que trancar a carne","por que armário de tório","baú de macgrann"}},{q="Quem roubou o armário de carnes?",a="Um yeti ameaçador chamado Old Icebeard roubou todo o armário enquanto MacGrann estava caçando cervos, arrastando o pesado recipiente de volta para seu covil em uma caverna em Vale Brisa Álgida.",al={"quem pegou a carne","quem roubou","ladrão do armário de carnes"}},{q="Por que Tundra MacGrann não pode recuperar suas carnes sozinho?",a="MacGrann sofre de uma lesão na perna que lhe tira a velocidade e a furtividade necessárias para entrar no covil de Old Icebeard e escapar antes que o feroz yeti o encurrale.",al={"por que macgrann não busca","por que tundra precisa de ajuda","tundra ferido"}}},fx={["1f8f3b04"]={q="De onde veio a Carne-seca do MacGrann e quem a preparou?",a="Estas carnes secas foram preparadas e salgadas por Tundra MacGrann, um montanhês que vive nas gélidas terras selvagens de Dun Morogh. Ele curou um mês inteiro de rações para sobreviver à rigorosa estação de congelamento que se aproximava, armazenando-as cuidadosamente em um pesado armário de tório antes que a besta local, Barba de Gelo, interviesse.",al={"quem fez a carne-seca do macgrann","de onde veio a carne-seca","origem da carne do macgrann"}},["6a0307bf"]={q="Por que Tundra MacGrann quer sua carne-seca de volta?",a="Sem este estoque preservado, Tundra MacGrann enfrenta a inanição quando as severas rajadas de neve varrem Dun Morogh. Representa um mês inteiro de provisões salgadas. Como uma perna machucada o impede de enfrentar a toca de Barba de Gelo para buscá-la, recuperar a carne é vital para sua sobrevivência durante o inverno que se aproxima.",al={"por que tundra quer a carne","por que pegar as carnes secas","por que as carnes do macgrann são necessárias"}}},fp="22,188,14.351.0,20.394.0,32.110.0,37.176.0,26.124.0,53.88.0"}
P.entries["item:mackreel-s-moonshine"] = {n="Pinga de Mackreel",s="A Pinga de Mackreel é uma bebida anã potente fabricada por Ruço MacKreel, posicionado na rompida Ponte Thandol, ao norte dos Pantanais. Forte o suficiente para nocautear uma sentinela de serviço, ela é apreciada até o extremo norte, em Costa Sul, onde o Mestre-cervejeiro Podrágua a aceita como pagamento de dívidas.",h="A Pinga de Mackreel é uma bebida anã potente fabricada por Ruço MacKreel, posicionado na rompida Ponte...",kw={"mestre-cervejeiro podrágua","bebida anã","ruço mackreel","pinga de mackreel","pinga","costa sul","pantanal"},ang={["profession:Cooking"]="Embora destilada como uma pinga rústica em vez de um vinho refinado, bebidas regionais potentes como a de Ruço são mercadorias essenciais em tavernas de fronteira.",["race:Dwarf"]="Os anões reconhecem uma bebida forte de verdade só pelo cheiro, e a pinga de Ruço com certeza tem força suficiente para nocautear um montanhês."},sec={{t="Uma Bebida Potente",b="Fabricada pelo guarda Ruço MacKreel na Ponte Thandol, esta bebida tem uma fama notória por sua potência. Até mesmo sentinelas anões experientes acabam derrubados após uma noite com a bebida, acordando com dores de cabeça semelhantes a uma brigada de máquinas de cerco passando por cima deles. Apesar do seu efeito punitivo, ela é muito valorizada por aquecer os viajantes contra os calafrios úmidos de Lordaeron e Khaz Modan."},{t="Pagamento para Costa Sul",b="Ruço MacKreel acumulou uma dívida pendente com o Mestre-cervejeiro Podrágua, o taverneiro e mestre-cervejeiro de Costa Sul. Para quitar sua conta, Ruço ofereceu um lote de sua pinga em vez de moedas. Podrágua aceita a bebida com prazer no lugar de ouro, ansioso para adicionar a bebida potente de MacKreel ao seu estoque para os dias costeiros gelados do Contraforte de Eira dos Montes."}},faq={{q="Quem faz a Pinga de Mackreel?",a="Ela é destilada por Ruço MacKreel, uma sentinela anã posicionada no trecho quebrado da Ponte Thandol, entre os Pantanais e o Planalto Arathi.",al={"criador da pinga de mackreel","quem fabricou","bebida de ruço mackreel"}},{q="Por que esta pinga está sendo enviada para Costa Sul?",a="Ruço MacKreel tinha uma dívida com o Mestre-cervejeiro Podrágua em Costa Sul. Em vez de moedas, ele combinou de acertar seu saldo devedor enviando a Podrágua um lote fresco de sua pinga.",al={"por que costa sul","entrega de pinga","dívida com mestre-cervejeiro podrágua"}},{q="Quão forte é a Pinga de Mackreel?",a="Ela é excepcionalmente forte. Ruço admitiu ter desmaiado completamente durante o serviço após bebê-la, queixando-se depois de uma dor de cabeça que parecia uma brigada inteira de máquinas de cerco estrondando sobre seu crânio.",al={"quão potente é","força da pinga","efeitos da pinga de mackreel"}},{q="Por que a entrega precisa ser feita às pressas?",a="Ruço bebeu demais e dormiu durante o turno de guarda, percebendo apenas ao acordar que restavam meros minutos antes que o prazo de sua dívida com o Mestre-cervejeiro Podrágua expirasse.",al={"por que cronometrada","a missão é cronometrada","por que a pressa"}}},fx={abca7076={q="O que é o MacKreel's Moonshine?",a="O MacKreel's Moonshine é um licor potente e feito à mão, fabricado por Ruço MacKreel no Pantanal. Notório por causar um impacto tremendo, é forte o suficiente para deixar até um anão robusto com uma ressaca que parece uma brigada de máquinas de cerco passando por cima de sua cabeça. Além de seu chute formidável, serve como escambo valioso, procurado até no norte, no Contraforte de Eira dos Montes, para aquecer o povo em dias frios.",al={"o que é o mackreel's moonshine","mackreel's moonshine","bebida do ruço mackreel"}}},fp="20,161,13.281.0,21.302.0,31.138.0,47.148.0,35.182.0,40.134.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Pata do Olho de Verme",s="A Pata do Olho de Verme é o troféu macabro tirado do líder gnoll Olho de Verme no Sítio dos Garren. Levada de volta a Montalvo, ela serve como prova física da execução da fera por saquear túmulos a serviço do Flagelo.",h="A Pata do Olho de Verme é o troféu macabro tirado do líder gnoll Olho de Verme no Sítio dos Garren.",kw={"recompensa","montalvo","executor zigano","sítio dos garren","gnoll","olho de verme","pata do olho de verme","clareiras de tirisfal"},ang={["race:Undead"]="Para os Renegados de Montalvo, trazer a pata do Olho de Verme é um golpe direto contra os ladrões de corpos que fornecem matéria-prima para o odiado Lich Rei."},sec={{t="Prova de Execução",b="Olho de Verme atraiu a severa ira dos Renegados ao saquear túmulos e pilhar os campos perto do Sítio dos Garren, fornecendo cadáveres para reforçar as fileiras dos exércitos do Lich Rei. Em resposta, uma sentença formal de morte e uma recompensa foram anunciadas na cidade de Montalvo. Como meros boatos de uma morte nunca são suficientes para administradores militares como o Executor Zigano, os caçadores de recompensa devem cortar a pata do vilão e levá-la de volta à cidade para receber a recompensa e encerrar o contrato."}},faq={{q="Por que o Executor Zigano quer a pata do Olho de Verme?",a="O Executor Zigano exige provas irrefutáveis de que o gnoll condenado foi realmente eliminado. Uma pata decepada serve como confirmação física da execução antes que Montalvo pague a recompensa.",al={"por que a pata","prova da recompensa de olho de verme","pata zigano"}},{q="Quais crimes o Olho de Verme cometeu contra os Renegados?",a="Olho de Verme liderou saques e pilhagens pelos confins do norte das Clareiras de Tirisfal, roubando especificamente cadáveres enterrados em propriedades rurais como o Sítio dos Garren para abastecer os exércitos do Lich Rei.",al={"crimes de olho de verme","por que olho de verme é procurado","o que olho de verme fez"}},{q="Onde o Olho de Verme é encontrado?",a="Olho de Verme reside no Sítio dos Garren, uma propriedade rural em ruínas localizada ao norte de Montalvo, nas Clareiras de Tirisfal, geralmente à espreita dentro da casa de fazenda em ruínas.",al={"localização de olho de verme","onde encontrar olho de verme","gnoll sítio dos garren"}},{q="Por que os gnolls estão trabalhando com as forças do Lich Rei?",a="Embora os gnolls sejam carniceiros oportunistas por natureza, bandos renegados nas Clareiras de Tirisfal se aliaram ou caíram sob o domínio do Flagelo, saqueando túmulos de humanos e Renegados para entregar corpos a necromantes.",al={"gnolls e flagelo","por que os gnolls roubam corpos","gnolls do flagelo"}}},fx={["9017e45e"]={q="O que é a Pata do Olho de Verme?",a="É a pata decepada do notório gnoll Olho de Verme. Pegá-la serve como prova física inegável da execução da besta para as autoridades em Montalvo.",al={"o que é a pata do olho de verme","pata do olho de verme","o que é esta pata"}},e496e47e={q="De onde vem a Pata do Olho de Verme e quem a fez?",a="Não é um artefato fabricado, mas um troféu esculpido diretamente do cadáver do próprio Olho de Verme, um gnoll traiçoeiro que opera perto do Sítio dos Garren nas Clareiras de Tirisfal.",al={"de onde veio a pata do olho de verme","origem da pata do olho de verme","quem fez a pata do olho de verme"}}},fp="16,148,18.356.0,47.139.0,55.167.0,26.138.0,51.166.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Carta de Dispensa de Maggran",s="A Carta de Dispensa de Maggran é uma mensagem oficial escrita por Maggran Ata Terra no Retiro Rocha do Sol. Transportada através de Kalimdor até O Grande Elevador, ela concede a um sentinela posicionado um alívio há muito esperado para que possa voltar para casa e visitar sua família.",h="A Carta de Dispensa de Maggran é uma mensagem oficial escrita por Maggran Ata Terra no Retiro Rocha do Sol.",kw={"sertões","ata terra","grish","carta","elevador","pisa léguas","maggran","dispensa","cordilheira das torres de pedra"},ang={["faction:Horde"]="A missiva destaca os esforços pós-guerra da Horda para cuidar de suas forças dispersas, enviando reservas descansadas para postos remotos por toda Kalimdor."},sec={{t="Um Sentinela Dispensado",b="Manter postos avançados pela vasta extensão acidentada de Kalimdor exige vigilância, mas os líderes da Horda reconhecem que o serviço de vigia prolongado cobra um preço alto da moral. Escrita por Maggran Ata Terra nos altos penhascos do Retiro Rocha do Sol, esta simples missiva serve como ordens oficiais notificando Grish Pisa Léguas de que um guerreiro substituto foi enviado para assumir seu posto no Grande Elevador. Para um guarda solitário vigiando os imponentes guinchos de madeira muito ao sul, a carta promete algo raro em tempos conturbados: uma dispensa honrosa para se reunir com a família."}},faq={{q="Qual é o propósito da Carta de Dispensa de Maggran?",a="A carta contém ordens oficiais de Maggran Ata Terra dispensando o sentinela Grish Pisa Léguas de seu posto no Grande Elevador, nos Sertões Meridionais, permitindo que ele retorne para casa e visite sua família.",al={"o que esta carta faz","propósito da carta de maggran","por que entregar a carta"}},{q="Quem escreveu a carta?",a="A carta foi escrita por Maggran Ata Terra, um ancião residente no Retiro Rocha do Sol, na Cordilheira das Torres de Pedra.",al={"quem escreveu","autor da carta de dispensa","maggran ata terra"}},{q="Quem deve recebê-la?",a="Ela é endereçada a Grish Pisa Léguas, um guarda da Horda posicionado no topo do Grande Elevador que liga os Sertões Meridionais a Mil Agulhas.",al={"quem recebe a carta","destinatário da carta","para onde vai"}},{q="Onde a carta é entregue?",a="Ela deve ser levada ao sul, através dos Sertões, até a borda do desfiladeiro de Mil Agulhas, onde fica O Grande Elevador.",al={"local de entrega","onde está grish","localização do grande elevador"}}},fx={["419ae143"]={q="O que é a Carta de Dispensa de Maggran?",a="É um despacho oficial escrito por Maggran Ata Terra no Retiro Rocha do Sol, na Cordilheira das Torres de Pedra. A mensagem informa a um guarda da Horda estacionado, Grish Pisa Léguas, que um guerreiro reserva está sendo enviado para assumir seu posto, concedendo-lhe licença para visitar sua família.",al={"o que é a carta de dispensa de maggran","carta de maggran","carta de dispensa"}},eb8a36e5={q="Por que Grish Pisa Léguas quer a Carta de Dispensa de Maggran?",a="Grish pediu dispensa de seu posto há muito tempo e está ansioso por notícias. Guardar O Grande Elevador nos Sertões Meridionais é um dever monótono, e esta carta autoriza formalmente sua substituição por um guerreiro da reserva, finalmente concedendo-lhe o tão esperado tempo para visitar sua família.",al={"por que grish quer a carta","por que a carta de dispensa é procurada","por que precisar da carta de dispensa de maggran"}}},fp="24,172,17.346.0,48.187.0,21.101.0,27.158.0,30.114.0"}
P.entries["item:magma-core-classic"] = {n="Núcleo de Magma",s="O Núcleo de Magma é o coração de Magma Lord Bokk, um elemental nas Estepes Ardentes. Mux Zoamana precisa de seu calor constante para alimentar um revelador extradimensional de fantasmas.",h="O Núcleo de Magma é o coração de Magma Lord Bokk, um elemental nas Estepes Ardentes.",kw={"bokk","estepes ardentes","ectoplasma","geringontzan","revelador de fantasmas","núcleo de magma","magma lord bokk","mux zoamana","fonte de energia portátil"},ang={["profession:Engineering"]="Como engenheiro, você talvez entenda por que Mux quer uma fonte portátil de energia: ele pretende usar o Núcleo de Magma para alimentar um revelador extradimensional de fantasmas."},sec={{t="Um coração ardente",b="Magma Lord Bokk vive nas Estepes Ardentes, ao sul da Montanha Rocha Negra. Seu Núcleo de Magma guarda uma fonte inesgotável de calor. Mux Zoamana, em Geringontzan, procura o núcleo para manter o ectoplasma ativo e alimentar um revelador extradimensional de fantasmas."}},faq={{q="O que é o Núcleo de Magma?",a="O Núcleo de Magma é o coração de Magma Lord Bokk, um poderoso elemental nas Estepes Ardentes. Ele guarda uma poderosa fonte de calor.",al={"núcleo de magma","coração de bokk"}},{q="Quem quer o Núcleo de Magma?",a="Mux Zoamana, em Geringontzan, quer o Núcleo de Magma para alimentar um revelador extradimensional de fantasmas.",al={"quem precisa do núcleo de magma","fonte de energia de mux"}},{q="Onde fica Magma Lord Bokk?",a="Magma Lord Bokk pode ser encontrado nas Estepes Ardentes, ao sul da Montanha Rocha Negra.",al={"onde fica bokk","localização de bokk"}},{q="Por que Mux precisa dele?",a="Mux precisa de uma fonte de energia estável e portátil para manter o ectoplasma ativo e alimentar seu revelador extradimensional de fantasmas.",al={"por que o núcleo de magma","energia para revelador de fantasmas"}}},fp="10,170,15.235.0,23.126.0,25.97.0,25.81.0,21.118.0"}
P.entries["item:maiden-s-folly-charts"] = {n="Maiden's Folly Charts",s="Os mapas da Maiden's Folly são registros de navegação recuperados de um naufrágio no Planalto Arathi. O Primeiro Oficial Nadaliso quer protegê-los antes que os navios deixem a enseada.",h="Os mapas da Maiden's Folly são registros de navegação recuperados de um naufrágio no Planalto Arathi.",kw={"planalto arathi","angra do butim","mapas","deep sea salvage","primeiro oficial nadaliso","maiden's folly","mapas da maiden's folly"},sec={{t="Mapas do Naufrágio",b="No Planalto Arathi, a Maiden's Folly está naufragada ao lado do Spirit of Floresta de Pinhaprata. Os mapas e diários registram informações que a tripulação teme que possam cair em mãos inimigas. O Primeiro Oficial Nadaliso pede que você recupere os mapas, inclusive os da Maiden's Folly, e os leve de volta à Angra do Butim."}},faq={{q="O que são os mapas da Maiden's Folly?",a="São mapas de navegação que pertenciam à Maiden's Folly, agora naufragada no Planalto Arathi.",al={"mapas da maiden's folly","mapas da folly","quais mapas"}},{q="Onde posso encontrar os mapas?",a="A Maiden's Folly está naufragada em uma enseada no Planalto Arathi.",al={"onde estão os mapas","encontrar mapas da folly","localização dos mapas"}},{q="Quem quer que os mapas sejam recuperados?",a="O Primeiro Oficial Nadaliso pede que você recupere os mapas da Maiden's Folly e os outros registros dos navios.",al={"quem os quer","mapas de nadaliso","primeiro oficial"}},{q="Por que é preciso proteger os mapas?",a="A tripulação teme que os mapas e diários caiam em mãos inimigas, e o Mestre de Frota Chifre do Mar os responsabilizaria.",al={"por que recuperar os mapas","mãos inimigas","por que os mapas importam"}},{q="Para onde irão os mapas?",a="Os mapas recuperados serão enviados ao comando na Angra do Butim.",al={"para onde devolver os mapas","mapas da angra do butim","destino dos mapas"}}},fp="21,165,21.292.0,35.102.0,28.66.0,31.94.0,31.117.0,25.60.0"}
P.entries["item:maiden-s-folly-log"] = {n="Maiden's Folly Log",s="O Diário da Maiden's Folly é o registro do capitão de um navio naufragado em Arathi. Suas páginas e cartas náuticas contêm informações que Mestre de Frota Chifre do Mar quer manter longe de olhares curiosos.",h="O Diário da Maiden's Folly é o registro do capitão de um navio naufragado em Arathi.",kw={"arathi","angra do butim","diário do capitão","deep sea salvage","diário","maiden's folly","nilzlix","recife","seahorn","templo"},sec={{t="Registro de um naufrágio",b="Primeiro Oficial Nadaliso busca o diário da Maiden's Folly, naufragada junto ao Spirit of Floresta de Pinhaprata. Os navios encalharam em um templo nos recifes quando a maré começou a baixar e afundaram rapidamente. Seus registros são importantes para o comando em Angra do Butim, que teme que as informações caiam em mãos inimigas."}},faq={{q="O que é o Diário da Maiden's Folly?",a="É o diário do capitão da Maiden's Folly, um dos navios naufragados nos recifes de Arathi.",al={"diário da maiden's folly","diário do capitão","diário de bordo"}},{q="Onde a Maiden's Folly afundou?",a="A Maiden's Folly encalhou em um templo nos recifes de Arathi e afundou.",al={"onde fica o naufrágio","localização da maiden's folly","navio naufragado em arathi"}},{q="Por que Primeiro Oficial Nadaliso quer o diário?",a="Primeiro Oficial Nadaliso quer recuperar o diário e as cartas náuticas da Maiden's Folly antes que as informações caiam em mãos inimigas.",al={"por que recuperar o diário","o que nilzlix quer","por que pegar o livro"}},{q="O que aconteceu com a Maiden's Folly?",a="A maré começou a baixar quando a Maiden's Folly se aproximava de uma enseada, e o navio encalhou em um templo nos recifes antes de afundar.",al={"naufrágio da maiden's folly","como afundou","o que aconteceu com o navio"}},{q="Quem quer manter os registros em segurança?",a="O comando de Mestre de Frota Chifre do Mar em Angra do Butim quer manter os diários e as cartas náuticas longe de olhares curiosos.",al={"quem quer as cartas náuticas","mestre de frota chifre do mar","registros de angra do butim"}}},fp="18,172,16.292.0,31.91.0,34.67.0,41.119.0,36.122.0,32.92.0"}
P.entries["item:malem-pendant"] = {n="Pingente de Malem",s="O Pingente de Malem está em uma carroça na Desolação. Vahlarriel Matademônios, em Nijel’s Point, precisa dele e de notícias sobre rastros que seguem para o sul.",h="O Pingente de Malem está em uma carroça na Desolação.",kw={"desolação","pegadas","forte","malem","pingente de malem","posto do nijel","vahlarriel matademônios","carroça"},sec={{t="Um sinal na carroça",b="Pegadas seguem para o sul a partir da carroça onde você encontra o Pingente de Malem. Fumaça sobe de um forte próximo, e o fogo constante sugere que há pessoas lá. Vahlarriel Matademônios, em Nijel’s Point, precisa ver o pingente e ouvir o que você encontrou."}},faq={{q="Onde devo levar o Pingente de Malem?",a="Leve o Pingente de Malem para Vahlarriel Matademônios, em Nijel’s Point, na Desolação.",al={"onde levar o pingente","entregar o pingente","onde encontrar o pingente de malem"}},{q="Onde o pingente foi encontrado?",a="Você encontra o Pingente de Malem em uma carroça na Desolação.",al={"onde está o pingente","localização do pingente","encontrar o pingente de malem"}},{q="Que pistas havia perto do pingente?",a="Pegadas seguem para o sul a partir da carroça, e fumaça sobe de um forte próximo.",al={"rastros e fumaça","quais são as pistas","pistas na carroça"}},{q="Por que Vahlarriel precisa ouvir sobre o forte?",a="Vahlarriel está procurando os Malems, e os rastros e a fumaça sugerem que eles podem ter sido levados para o forte.",al={"por que contar a vahlarriel","notícias do forte","do que vahlarriel precisa"}}},fp="13,143,19.241.0,34.80.0,28.50.0,33.73.0,48.114.1"}
P.entries["item:mangy-claw"] = {n="Pata Sarnenta",s="A Pata Sarnenta é uma pata decepada retirada do grande urso garra-de-gelo Mangeclaw em Dun Morogh. Ela serve como uma prova sombria de que a fera mortal responsável por matar um piloto anão isolado foi finalmente abatida.",h="A Pata Sarnenta é uma pata decepada retirada do grande urso garra-de-gelo Mangeclaw em Dun Morogh.",kw={"dun morogh","hildelve","urso garra-de-gelo","mangeclaw","pata sarnenta","piloto pisafundo","siege brigade"},ang={["class:Hunter"]="Rastrear um predador notório como Mangeclaw nas nevascas implacáveis da montanha coloca à prova a habilidade de um caçador de abater feras perigosas e territoriais.",["race:Dwarf"]="Para os anões, honrar o último desejo de um camarada tombado e vingar um membro da Siege Brigade de Altaforja é uma questão de profunda honra pessoal e de clã."},sec={{t="O Último Desejo de um Piloto",b="Quando o tanque a vapor do Pilot Hildelve quebrou nas colinas congeladas de Dun Morogh, ele continuou sua busca por minério a pé, apenas para enfrentar a vastidão selvagem das montanhas sozinho. Conforme registrado em seu diário recuperado, Hildelve conseguiu repelir o ataque inicial de um monstruoso urso garra-de-gelo chamado Mangeclaw, embora tenha sido brutalmente estraçalhado no confronto. A fera retornou mais tarde para acabar com o piloto enfraquecido. O último registro escrito de Hildelve implorava por vingança contra o predador, uma tarefa cumprida ao recolher a Pata Sarnenta do urso derrotado."},{t="Vingança pela Siege Brigade",b="Levar a Pata Sarnenta ao Piloto Pisafundo traz alívio para a Siege Brigade de Altaforja. Pisafundo havia despachado grupos de busca pelos montes de neve na esperança de encontrar seu amigo com vida, apenas para descobrir seu trágico destino. Apresentar tanto o Diário de Hildelve quanto a pata decepada do predador prova que o último desejo de Hildelve foi honrado, garantindo seu descanso e assegurando a gratidão dos pilotos de Altaforja."}},faq={{q="O que é a Pata Sarnenta?",a="É um troféu decepado de Mangeclaw, um urso garra-de-gelo selvagem que espreita em Dun Morogh. Serve como prova física de que a fera foi caçada e abatida.",al={"para que serve a pata sarnenta","o que e esta pata","item mangeclaw"}},{q="Quem deseja a Pata Sarnenta?",a="O Piloto Pisafundo, estacionado perto das passagens montanhosas de Dun Morogh, busca a pata junto ao diário de seu falecido amigo Hildelve para confirmar que o urso assassino está morto.",al={"quem aceita a pata sarnenta","entregar pata sarnenta","entrega piloto pisafundo"}},{q="Por que Mangeclaw precisava ser caçado?",a="Um piloto anão chamado Hildelve, que procurava minério a pé depois que seu tanque a vapor quebrou, foi estraçalhado e por fim morto por Mangeclaw. O último desejo de Hildelve, escrito em seu diário pessoal, era que alguém se vingasse da fera.",al={"por que matar mangeclaw","quem morreu para mangeclaw","historia hildelve"}},{q="Por onde vaga a fera Mangeclaw?",a="Mangeclaw ronda os cumes e colinas nevadas de Dun Morogh, não muito longe de onde os restos mortais do Pilot Hildelve foram encontrados.",al={"localizacao mangeclaw","onde fica mangeclaw","mangeclaw dun morogh"}}},fx={["554d85fa"]={q="De onde vem a Pata Sarnenta?",a="A Pata Sarnenta é retirada diretamente de Mangeclaw, um urso-garra-de-gelo selvagem que ronda a natureza congelada de Dun Morogh. Não é um artefato fabricado, mas um troféu físico horripilante arrancado da besta após ser morta.",al={"origem da pata sarnenta","onde a pata sarnenta cai","quem tem a pata sarnenta"}}},fp="10,173,20.396.0,31.302.1,23.125.0,25.184.0,36.192.0,36.105.0"}
P.entries["item:maraudine-key-fragment"] = {n="Maraudine Key Fragment",s="Maraudine Key Fragment está com Khan Hratha, na Desolação. Gelkis e Magram o buscam em sua luta contra os Maraudinos.",h="Maraudine Key Fragment está com Khan Hratha, na Desolação.",kw={"gelkis","khan hratha","magram","maraudino","maraudine key fragment","uthek, a sábia","vale das lanças","warug"},sec={{t="Um Pedaço de uma Chave",b="Khan Hratha carrega Maraudine Key Fragment no Vale das Lanças. Gelkis pede o fragmento depois que ele é morto, e Magram faz a mesma exigência. Cada clã busca o fragmento como parte de sua luta contra os Maraudinos."}},faq={{q="Quem está com Maraudine Key Fragment?",a="Khan Hratha está com Maraudine Key Fragment no Vale das Lanças.",al={"quem está com o fragmento","pedaço da chave de hratha","fragmento maraudino"}},{q="Quem quer o fragmento?",a="Uthek, a Sábia, pede o fragmento na Aldeia Gelkis, enquanto Warug o pede na Aldeia Magram.",al={"quem quer a chave","gelkis ou magram","onde levar o fragmento"}},{q="Por que Gelkis quer o fragmento?",a="Gelkis pede que você leve o fragmento até lá depois que Khan Hratha for morto.",al={"gelkis quer o fragmento","pedaço da chave de uthek","por que gelkis precisa da chave"}},{q="Por que Magram quer o fragmento?",a="Magram pede que você leve o fragmento até lá depois que Khan Hratha for morto.",al={"magram quer o fragmento","pedaço da chave de warug","por que magram precisa da chave"}}},fp="22,133,16.225.0,35.69.0,23.98.0,26.73.1,26.68.1"}
P.entries["item:margol-s-gigantic-horn"] = {n="Margol's Gigantic Horn",s="Margol’s Gigantic Horn é um troféu surrado da Garganta Abrasadora. O Montanhista Pedrabrita precisa dele antes de considerar abrir a Galeria Lapidada.",h="Margol’s Gigantic Horn é um troféu surrado da Garganta Abrasadora.",kw={"cabeça de machado quebrada","loch modan","margol","margol the rager","margol’s gigantic horn","montanhista pedrabrita","garganta abrasadora","galeria lapidada"},sec={{t="Um troféu tosco",b="Na Garganta Abrasadora, Margol’s Gigantic Horn é um achado curioso para quem busca uma passagem pela Galeria Lapidada. Arranhões e rachaduras marcam sua superfície áspera, e um pedaço incomum de metal está preso nele. Quem quer ver o chifre é o Montanhista Pedrabrita."}},faq={{q="Quem quer o chifre de Margol?",a="O Montanhista Pedrabrita quer ver Margol’s Gigantic Horn. Ele está na passagem entre Loch Modan e a Garganta Abrasadora.",al={"quem quer","chifre de pedrabrita","onde levar o chifre"}},{q="Onde posso encontrar o chifre?",a="Margol’s Gigantic Horn vem de Margol the Rager, na Garganta Abrasadora.",al={"local do chifre","encontrar chifre de margol","onde fica o chifre"}},{q="Por que Pedrabrita precisa do chifre?",a="Pedrabrita pede para ver Margol’s Gigantic Horn antes de considerar abrir a Galeria Lapidada entre Loch Modan e a Garganta Abrasadora.",al={"por que pedrabrita quer","para que serve o chifre","por que levar o chifre"}},{q="O que está preso no chifre?",a="Uma cabeça de machado quebrada está presa na superfície áspera. No metal, estão gravadas as palavras “Propriedade do Montanhista Pedrabrita”.",al={"metal no chifre","o que está preso nele","cabeça de machado"}},{q="Por que Pedrabrita diz que é falso?",a="Pedrabrita insiste que o chifre é pequeno demais para ser de Margol, afirmando que o chifre de Margol é pelo menos oito vezes maior.",al={"chifre falso","pedrabrita diz que é falso","é verdadeiro"}}},fp="22,149,14.266.0,26.118.0,26.70.0,35.136.0,27.118.1,34.116.1"}
P.entries["item:marshal-haggard-s-badge"] = {n="Distintivo do Delegado Fadigas",s="O Distintivo do Delegado Fadigas é um símbolo de patente e autoridade que já foi portado pelo Delegado Fadigas durante seu serviço ao reino de Ventobravo. Após ser roubado pelo bandido Défias Diogo Dente-podre por meio de um ardil, o distintivo representa uma ameaça perigosa como ferramenta para se passar por autoridades da cidade.",h="O Distintivo do Delegado Fadigas é um símbolo de patente e autoridade que já foi portado pelo Delegado...",kw={"diogo dente-podre","défias","floresta de elwynn","delegado durão","delegado fadigas","distintivo do delegado fadigas","ventobravo","cofre"},ang={["class:Warrior"]="Recuperar o distintivo de Fadigas prova o seu valor a um veterano do exército de Ventobravo, que recompensa combatentes promissores com armas sobressalentes e bem conservadas de seus tempos de luta.",["faction:Alliance"]="Recuperar o distintivo preserva a integridade do comando militar de Ventobravo e impede que a Irmandade Défias sabote as defesas locais por dentro."},sec={{t="Uma Insígnia Roubada",b="Embora o Delegado Fadigas tenha se aposentado há muito tempo em sua pequena fazenda nas colinas da Floresta de Elwynn, seu antigo distintivo de Delegado de Ventobravo ainda possui peso oficial. Sob o manto da noite, um ladino Défias chamado Diogo Dente-podre vestiu um tabardo de Ventobravo e se passou pelo Delegado Durão, o comandante da guarnição de Vila d'Ouro. Enganado ao acreditar que seus antigos colegas precisavam da insígnia para assuntos oficiais, o idoso Fadigas a entregou sem suspeitar de nada. Diogo fugiu para a floresta antes que o oficial aposentado percebesse o golpe. Nas mãos da Irmandade Défias, esse emblema da autoridade de Ventobravo poderia permitir que foras da lei passassem por postos de controle ou semeassem confusão entre as patrulhas locais."}},faq={{q="O que é o Distintivo do Delegado Fadigas?",a="É uma insígnia oficial de patente da época em que o Delegado Fadigas serviu ao reino de Ventobravo. Mesmo na aposentadoria, manter tal distintivo simboliza uma posição militar passada e carrega autoridade genuína.",al={"distintivo de fadigas","distintivo de delegado","distintivo do delegado fadigas"}},{q="Como Diogo Dente-podre conseguiu o distintivo?",a="Diogo Dente-podre aproximou-se da casa do Delegado Fadigas sob o manto da escuridão usando um tabardo de Ventobravo. Na penumbra, Fadigas o confundiu com o Delegado Durão, de Vila d'Ouro, e entregou o distintivo quando solicitado.",al={"como o distintivo foi roubado","quem roubou o distintivo","truque de diogo dente-podre"}},{q="Por que o distintivo é perigoso nas mãos dos Défias?",a="Com um distintivo autêntico de Delegado e um disfarce, um agente Défias poderia se passar por oficiais de alto escalão de Ventobravo para contornar sentinelas, infiltrar-se em guarnições ou emitir ordens falsas aos guardas da cidade.",al={"por que diogo quer o distintivo","uso do distintivo pelos défias","perigo do distintivo"}},{q="Onde o distintivo está guardado?",a="Diogo Dente-podre trancou o distintivo roubado dentro de seu cofre, escondido em seu acampamento localizado ao sul da fazenda do Delegado Fadigas, na Floresta de Elwynn.",al={"localizacao do distintivo","onde encontrar o distintivo","cofre de diogo dente-podre"}}},fp="23,205,17.489.0,32.160.0,38.185.0,54.192.0,24.115.0"}
P.entries["item:mary-s-looking-glass"] = {n="Espelho de Maria",s="Na Floresta do Crepúsculo, o espelho descartado de Maria passa de um carniçal a um observador das estrelas.",h="Na Floresta do Crepúsculo, o espelho descartado de Maria passa de um carniçal a um observador das estrelas.",kw={"maria cega","vila sombria","floresta do crepúsculo","insane ghoul","look to the stars","espelho de mão","espelho de maria","cemitério jardins da paz","vitório prismado"},ang={["faction:Alliance"]="Recuperar relíquias dos horrores do Cemitério Jardins da Paz traz algum alívio aos cidadãos aflitos de Vila Sombria e ajuda nos projetos da cidade.",["profession:Engineering"]="Engenheiros podem apreciar como Viktori reaproveita um antigo espelho doméstico como refletor óptico em um aparelho para observar as estrelas."},sec={{t="Um Tesouro dos Renegados",b="Maria Cega já prezou muito o espelho polido. Após sua morte e a perda dos olhos, seu reflexo se tornou uma lembrança angustiante do que perdera. Ela jogou o espelho fora atrás de seu celeiro, onde a escuridão da Floresta do Crepúsculo se fechava ao redor. Um Insane Ghoul o encontrou entre as ruínas nos arredores e o levou para o sul, até as criptas do Cemitério Jardins da Paz."},{t="Olhos para os Céus",b="Em Vila Sombria, o observador das estrelas Vitório Prismado sonha em enxergar através do crepúsculo eterno da Floresta do Crepúsculo e ver o céu límpido acima. Seu telescópio precisa de lentes ópticas especiais e vidro refletor. Maria envia aventureiros atrás dos mortos-vivos selvagens na capela em ruínas do cemitério para recuperar seu espelho. Viktori precisa dele como refletor em sua máquina para observar as estrelas."}},faq={{q="Por que Maria jogou o espelho fora?",a="O espelho já foi um dos maiores tesouros de Maria, mas ela o jogou atrás do celeiro após um incidente que não descreve por completo. Em outro encontro, ela explica que arrancou os próprios olhos porque não suportava a própria aparência.",al={"por que maria jogou fora","por que descartar espelho","história do espelho de maria cega"}},{q="Quem ficou com o espelho depois que Maria o descartou?",a="Um Insane Ghoul que vagava pelos bosques atrás da antiga propriedade rural de Maria encontrou o espelho descartado. A criatura morta-viva acabou se instalando na capela abandonada do Cemitério Jardins da Paz.",al={"quem está com o espelho","quem derruba o espelho","onde está o espelho"}},{q="Por que Vitório Prismado quer o espelho de Maria?",a="Viktori está construindo um telescópio elaborado para atravessar a escuridão da Floresta do Crepúsculo e estudar as estrelas. Ele precisa de uma superfície refletora de qualidade para direcionar a luz pelo aparelho, e o espelho de Maria se encaixa no projeto.",al={"por que vitório precisa do espelho","uso do espelho de vitório","espelho do telescópio"}},{q="Onde o Insane Ghoul que está com o espelho pode ser encontrado?",a="O Insane Ghoul espreita no extremo sudeste da Floresta do Crepúsculo, assombrando a capela de pedra em ruínas do Cemitério Jardins da Paz.",al={"localização do insane ghoul","onde fica o insane ghoul","carniçal de jardins da paz"}}},fx={afb2ba8d={q="O que é o Espelho de Maria?",a="O Espelho de Maria é um espelho de mão refletor que pertenceu a Maria Cega antes que a tragédia a atingisse. Considerado por Maria como um de seus mais preciosos tesouros pessoais, ela acabou por jogá-lo fora atrás de seu celeiro após um terrível incidente. Mais tarde, ele caiu nas garras de um carniçal morto-vivo errante na Floresta do Crepúsculo.",al={"o que e o espelho de maria","item espelho de maria","espelho de maria cega"}}},fp="20,79,19.356.0,19.366.0,42.247.0,53.196.0,56.195.0,55.124.0"}
P.entries["item:mathystra-relic"] = {n="Relíquia de Mathistra",s="As Relíquias de Mathistra são artefatos antigos dos elfos noturnos espalhados pelas ruínas tomadas pela vegetação de Mathystra, no norte de Costa Negra. Embora sejam vestígios de um antigo bastião élfico, elas retêm fragmentos adormecidos de magia que atraíram o interesse do culto do Martelo do Crepúsculo.",h="As Relíquias de Mathistra são artefatos antigos dos elfos noturnos espalhados pelas ruínas tomadas pela...",kw={"costa negra","bosque dos ancientes","glaive do mestre","mathystra","relíquia de mathistra","onu","ruínas de mathistra","martelo do crepúsculo"},ang={["class:Druid"]="Trabalhando em estreita colaboração com ancientes como Onu, os druidas ajudam a proteger o delicado equilíbrio de Costa Negra, garantindo que resquícios mágicos esquecidos não alimentem invocações sombrias.",["race:NightElf"]="Para os Kaldorei, recuperar essas relíquias é tanto uma questão de salvaguardar arcanos antigos perigosos do Martelo do Crepúsculo quanto de honrar o legado de uma cidade perdida para a Cisão."},sec={{t="Vestígios de um Bastião Caído",b="Antes da Grande Cisão, Mathystra erguia-se como uma cidade orgulhosa e bastião da civilização élfica ao longo da costa de Kalimdor. Hoje, suas colunas derrubadas e pedras rachadas jazem semienterradas pelo mato e pela névoa marinha, assombradas por espíritos inquietos e feras à espreita. Espalhadas pelas ruínas estão relíquias antigas que remontam àquela era de ouro. Embora desgastados por dez mil anos de abandono, esses artefatos ainda guardam tênues vestígios do ofício arcano élfico, tornando-se prêmios perigosos se deixados sem vigilância."},{t="Um Perigo Iminente",b="O anciente da tradição, Onu, procura essas relíquias após descobrir que o sinistro culto do Martelo do Crepúsculo está tentando transformar em armas antigos escritos élficos desenterrados na Glaive do Mestre. Os cultistas buscam canalizar a antiga magia kaldorei para acelerar o retorno de seus mestres sombrios. Ao estudar esses remanescentes dispersos, Onu e os guardiões de Costa Negra esperam desvendar as intenções do culto e proteger o poder esvaecido de Mathystra de ser usado para fins nefastos."}},faq={{q="O que são as Relíquias de Mathistra?",a="São fragmentos e artefatos deixados para trás da antiga cidade dos elfos noturnos de Mathystra. Apesar de terem milhares de anos, ainda preservam resquícios do artesanato mágico da civilização élfica anterior à Cisão.",al={"o que é relíquia de mathistra","relíquias élficas mathistra","o que são essas relíquias"}},{q="Onde essas relíquias são encontradas?",a="Elas jazem espalhadas em meio às pedras quebradas, pilares caídos e grama alta dentro das Ruínas de Mathistra, localizadas nas partes ao norte de Costa Negra.",al={"localização da relíquia de mathistra","onde encontrar relíquias","locais das relíquias"}},{q="Quem quer as Relíquias de Mathistra?",a="O Anciente da Tradição chamado Onu, que reside no Bosque dos Ancientes, no sul de Costa Negra, pede aos viajantes que as reúnam para estudo.",al={"quem precisa das relíquias","para quem levo as relíquias","onu relíquias"}},{q="Por que o Martelo do Crepúsculo tem interesse nelas?",a="O culto tem decifrado textos élficos antigos descobertos nas proximidades, na Glaive do Mestre. Eles buscam distorcer e explorar os segredos mágicos dos antigos elfos para auxiliar na invocação de seus mestres sombrios para o mundo.",al={"por que martelo do crepúsculo quer relíquias","martelo do crepúsculo mathistra"}}},fx={bddb4f1c={q="De onde vêm as Mathystra Relics e quem as fez?",a="Esses artefatos vêm da antiga cidade élfica noturna de Mathystra, criados há muito tempo durante uma era em que o grande bastião brilhava em toda a Costa Negra. Deixados para trás depois que o antigo assentamento desmoronou em ruínas, eles ainda guardam fragmentos persistentes de magia élfica.",al={"origem das mathystra relics","quem fez as mathystra relics","de onde vêm as mathystra relics"}}},fp="15,130,28.460.0,15.426.1,30.195.0,29.128.0,31.132.0,48.180.0"}
P.entries["item:maury-s-clubbed-foot"] = {n="Pé-de-clava do Maury",s="Maury “Club Foot” Wilkins deve uma dívida que Sea Wolf MacKinley pretende cobrar em Angra do Butim. Seu pé torto esconde algo que MacKinley considera valioso.",h="Maury “Club Foot” Wilkins deve uma dívida que Sea Wolf MacKinley pretende cobrar em Angra do Butim.",kw={"angra do butim","club foot","clubbed foot","maury","maury wilkins","ruínas de aboraz","sea wolf mackinley","voodoo dues"},sec={{t="Uma dívida na selva",b="Entre os devedores citados por MacKinley, Maury “Club Foot” Wilkins vagueia pelas ruínas da selva com Jon-Jon the Crow e Chucky “Ten Thumbs”. As dívidas deles estão em aberto há meses, e MacKinley envia você para encontrá-los nas Ruínas de Aboraz e nas Ruínas de Jubuwal. O pé torto de Maury está entre os objetos de valor que ele quer ver de volta em Angra do Butim."},{t="O preço de MacKinley",b="Quando você devolve os três objetos de valor, MacKinley diz que pode conseguir um bom preço por eles. Ele fala do que há dentro do pé de Maury e depois avisa que os três deveriam ter escolhido melhor com quem apostar."}},faq={{q="Quem é Maury “Club Foot” Wilkins?",a="Maury “Club Foot” Wilkins é um devedor de Sea Wolf MacKinley que vagueia pelas ruínas da selva.",al={"quem é maury","maury club foot","maury wilkins"}},{q="Por que MacKinley quer o pé de Maury?",a="MacKinley quer o Maury’s Clubbed Foot entre os objetos de valor que recolhe dos devedores.",al={"por que o pé","pé de maury","o que mackinley quer"}},{q="O que há dentro do pé de Maury?",a="MacKinley diz que há algo dentro do pé de Maury que pode vender por um bom preço.",al={"dentro do pé","segredo do pé de maury","o que há no pé"}},{q="Onde Maury pode ser encontrado?",a="Maury vagueia pelas ruínas da selva perto das Ruínas de Aboraz e das Ruínas de Jubuwal.",al={"onde está maury","localização de maury","onde club foot"}},{q="Quem mais deve a MacKinley?",a="Jon-Jon the Crow e Chucky “Ten Thumbs” também estão entre os devedores de MacKinley.",al={"outros devedores","jon-jon e chucky","quem deve a sea wolf"}}},fp="20,169,20.345.0,19.207.1,37.93.0,39.88.0,30.90.1,25.81.0,24.82.0"}
P.entries["item:maury-s-key"] = {n="Maury's Key"}
P.entries["item:melenas-head"] = {n="Cabeça de Málinus",s="A Cabeça de Málinus é a recompensa decapitada obtida de Lord Melenas, um comandante sátiro acampado dentro de Pedra Vil. Trazido de volta como prova absoluta de sua morte, o troféu marca a eliminação discreta de uma ameaça demoníaca persistente nos galhos de Teldrassil.",h="A Cabeça de Málinus é a recompensa decapitada obtida de Lord Melenas, um comandante sátiro acampado dentro de...",kw={"pedra vil","grell","lorde málinus","cabeça de málinus","sátiro","teldrassil","twisted hatred"},ang={["class:Warrior"]="Carregar a cabeça decepada de um senhor da guerra inimigo oferece uma prova inequívoca e primitiva de que um adversário perigoso e seu bando de grells foram derrotados.",["race:NightElf"]="Os sátiros representam uma trágica perversão demoníaca da antiga linhagem dos elfos noturnos, tornando a execução silenciosa de Lord Melenas um ato tanto de necessidade quanto de vergonha cultural."},sec={{t="Uma Desgraça Oculta",b="Para os elfos noturnos que guardam Umbravale e as regiões ao redor de Teldrassil, a mera existência de sátiros em sua nova Árvore do Mundo é uma amarga desgraça. Lord Melenas optou por fazer seu covil dentro das cavernas retorcidas de Pedra Vil, logo ao norte dos assentamentos élficos, reunindo guerreiros grell agressivos sob seu estandarte. Como os kaldorei prezam a discrição ao lidar com corrupções tão próximas de suas terras centrais, este troféu sangrento serve como prova privada de que suas maquinações foram frustradas antes que sua influência pudesse se espalhar."}},faq={{q="Quem foi Lord Melenas?",a="Lord Melenas era um comandante sátiro à espreita dentro da caverna conhecida como Pedra Vil em Teldrassil. Ele reuniu um bando de guerra de grells sob seu comando para conspirar contra os postos avançados kaldorei próximos.",al={"história de lorde málinus","quem é málinus","história de málinus"}},{q="Por que a morte dele deve permanecer em silêncio?",a="A presença de sátiros — antigos e amaldiçoados elfos noturnos corrompidos por mácula demoníaca — tão perto dos galhos sagrados de Teldrassil é vista como uma profunda vergonha pelas autoridades kaldorei. Lidar com ele de forma rápida e silenciosa evita o pânico e minimiza a vergonha.",al={"por que o segredo","segredo de twisted hatred","por que em silêncio"}},{q="De onde a Cabeça de Málinus foi retirada?",a="A cabeça é recuperada nas profundezas de Pedra Vil, uma caverna corrompida localizada logo ao norte de Dolanaar, no centro de Teldrassil.",al={"onde encontrar málinus","localização de pedra vil","localização de málinus"}}},fx={b9c077d0={q="Por que Tallonkai quer a Cabeça de Málinus?",a="Tallonkai Radicélere busca a cabeça como prova absoluta da morte do Lorde Málinus. A presença de um sátiro tão perto de Umbravale é considerada uma humilhação perigosa para os elfos noturnos. Entregar sua cabeça garante que o mentor maligno tenha sido silenciado rápida e silenciosamente antes que seus planos pudessem se espalhar ainda mais por Teldrassil.",al={"por que trazer a cabeça de málinus","quem quer a cabeça de málinus","por que tallonkai quer a cabeça"}},["05bed8f4"]={q="O que é a Cabeça de Málinus?",a="É a cabeça decepada de Lorde Melenas, um sátiro vil que fez seu covil dentro da Pedra Vil, logo ao norte de Dolanaar. Melenas reuniu grells agressivos ao seu lado e tramou atos sombrios desconfortavelmente perto do lar sagrado dos elfos noturnos, tornando sua cabeça decepada uma prova incontestável de que sua influência corrupta foi extinta.",al={"o que e a cabeca de malinus","item cabeca de malinus","de quem e esta cabeca"}}},fp="13,141,20.426.0,21.159.0,32.242.0,35.110.0"}
P.entries["item:menethil-statuette"] = {n="Estatueta de Menethil",s="A Estatueta de Menethil é uma rara estatueta prateada que retrata o falecido Rei Terenas Menethil II como um jovem paladino com um martelo de guerra erguido. Perdida em um naufrágio na costa do Pantanal, é um memorial excepcionalmente raro do soberano caído de Lordaeron.",h="A Estatueta de Menethil é uma rara estatueta prateada que retrata o falecido Rei Terenas Menethil II como um...",kw={"blind princess","bluegill","bolvar fordragon","catedral da luz","lorde grayson quebrassombra","estatueta de menethil","terenas menethil","pantanal"},ang={["class:Paladin"]="A estatueta mostra o falecido Rei Terenas como um jovem guerreiro da Luz de martelo erguido, um retrato profundamente comovente para os cavaleiros sagrados que lamentam a queda do reino.",["faction:Alliance"]="Terenas foi o líder unificador que fundou a Grande Aliança, tornando qualquer memorial preservado dele um tesouro inspirador em um mundo fraturado."},sec={{t="Uma Rara Relíquia de Lordaeron",b="A estatueta retrata o Rei Terenas Menethil II em seus primeiros anos, apresentado como um paladino de cabelos compridos erguendo um martelo em direção aos céus. Terenas era notoriamente humilde durante seu reinado e não gostava de monumentos pessoais, o que significa que poucas estátuas ou representações foram encomendadas em sua honra. Após o colapso do Reino de Lordaeron para o Flagelo, quase todas as relíquias desse tipo foram obliteradas, tornando esta efígie sobrevivente extraordinariamente valiosa para a Aliança."},{t="Perda nos Pântanos",b="A estatueta era parte da carga a bordo do navio mercante Blind Princess, com destino ao porto da Aliança de Menethil. Quando o navio foi atacado por agressivos murlocs Bluegill na costa pantanosa, a carga se espalhou e a estatueta acabou presa em um barril semienterrado na praia. Com ameaças locais como os orcs Dragonmaw rondando por perto, os defensores locais se apressaram em enviar o ícone recuperado para o sul, para Ventobravo, onde o Grão-lorde Bolvar Fordragon o confiou à Catedral da Luz."}},faq={{q="Quem está representado na estatueta?",a="Ela retrata o Rei Terenas Menethil II, o antigo governante de Lordaeron e artífice da Aliança original. Ele é mostrado não como um monarca idoso, mas em sua juventude como um paladino brandindo um martelo de guerra.",al={"quem está na estátua","o que a estatueta retrata","quem é a estatueta de menethil"}},{q="Como a estatueta foi perdida?",a="Ela estava sendo transportada através de O Grande Oceano a bordo do navio mercante Blind Princess. Quando o navio foi atacado por murlocs Bluegill no Pantanal, sua carga foi levada pelas águas até a costa e ficou enterrada na lama.",al={"como foi perdida","quem perdeu a estatueta","naufrágio pantanal estátua"}},{q="Por que as representações do Rei Terenas são tão raras?",a="O Rei Terenas era um governante modesto que ativamente rejeitava memoriais de autoengrandecimento, de modo que pouquíssimas estátuas suas foram esculpidas. Quase todos os retratos e figuras restantes no norte foram destruídos durante a devastação de Lordaeron pelo Flagelo.",al={"por que há poucas estátuas de terenas","memoriais de terenas"}},{q="Onde a estatueta vai parar?",a="Após ser recuperada no Pantanal, ela é levada ao Grão-lorde Bolvar Fordragon em Bastilha Ventobravo. Bolvar reconhece que a Luz se coalesceu dentro da relíquia e ordena que ela seja guardada por Lorde Grayson Quebrassombra dentro da Catedral da Luz.",al={"onde levo a estatueta","quem guarda a estatueta","estatueta catedral"}}},fx={["00c7d589"]={q="O que é a Estatueta de Menethil?",a="A Estatueta de Menethil é uma estatueta prateada que retrata o Rei Terenas Menethil II em sua juventude como um paladino de cabelos longos com seu martelo erguido. Além de ser uma imagem requintada do monarca caído de Lordaeron, a relíquia parece ter a própria Luz convergindo dentro dela, tornando-a um precioso monumento histórico e um objeto sagrado abençoado.",al={"o que é a estatueta de menethil","estátua de menethil","o que é a estatueta"}},["0d8a0354"]={q="Por que a Estatueta de Menethil é tão procurada?",a="O Rei Terenas desprezava monumentos e memoriais pessoais, deixando extraordinariamente poucas imagens dele para trás, quase todas as quais foram destruídas quando Lordaeron caiu para o Flagelo. Sua raridade, Luz sagrada e profundo vínculo sentimental com o fundador da Aliança fazem dela uma herança insubstituível, que inimigos como os orcs Dragonmaw locais profanariam ou saqueariam alegremente se deixada sem vigilância.",al={"por que as pessoas querem a estatueta de menethil","por que a estatueta é valiosa","quem quer a estatueta"}}},fp="18,131,25.338.0,16.448.0,30.162.0,27.169.0,43.200.0,32.222.1"}
P.entries["item:meridith-s-love-letter"] = {n="Meridith's Love Letter",s="Meridith's Love Letter leva uma mensagem de Meridith para Narain Suavestilo, em Tanaris. É um pequeno apelo nascido de um encontro após a queda de uma máquina voadora.",h="Meridith's Love Letter leva uma mensagem de Meridith para Narain Suavestilo, em Tanaris.",kw={"peixe","máquina voadora","gnomo","carta de amor","meridith","narain suavestilo","tanaris"},ang={["race:Gnome"]="Como gnomo, você leva os sentimentos de Meridith a Narain Suavestilo, outro gnomo que fica surpreso com a mensagem dela."},sec={{t="Uma mensagem para Narain",b="Depois de resgatar Narain Suavestilo de uma máquina voadora acidentada, Meridith pede que você leve a carta dela até ele. Ela se apaixonou pelo gnomo e espera que ele escute o que sente."},{t="A resposta de Narain",b="Narain se espanta ao descobrir quem enviou a carta. Meridith é um peixe, protesta ele, e ele é um gnomo; não vê como esse amor poderia dar certo."}},faq={{q="Quem escreveu Meridith's Love Letter?",a="Meridith escreveu a carta para Narain Suavestilo, o gnomo que ela resgatou de uma máquina voadora acidentada.",al={"quem escreveu a carta","carta de meridith","autor da carta de amor"}},{q="Para quem é a carta?",a="A carta é para Narain Suavestilo, um gnomo de Tanaris.",al={"quem recebe a carta","carta para narain","entregar para quem"}},{q="Por que Meridith enviou uma carta?",a="Meridith acredita que se apaixonou por Narain e quer que ele saiba o que ela sente.",al={"por que enviar carta","por quem meridith se apaixonou","mensagem de meridith"}},{q="Como Meridith conheceu Narain?",a="Meridith resgatou Narain dos destroços de uma máquina voadora acidentada.",al={"onde eles se conheceram","destroços de narain","máquina voadora acidentada"}},{q="O que Narain diz sobre a carta?",a="Narain diz que Meridith é um peixe e ele é um gnomo, então acredita que eles nunca poderiam ficar juntos.",al={"reação de narain","narain ama meridith","peixe e gnomo"}}},fp="22,158,20.184.0,14.140.1,33.101.0,22.56.0,32.89.0,29.70.0,38.94.1"}
P.entries["item:merrin-s-letter"] = {n="Carta de Marina",s="A Carta de Marina é uma mensagem urgente escrita por Marina Tecepedra, uma arqueóloga encurralada no sítio de escavação no Pantanal. Ela relata a invasão catastrófica de sua expedição arqueológica por raptores ferozes e garante aos seus entes queridos sua sobrevivência imediata.",h="A Carta de Marina é uma mensagem urgente escrita por Marina Tecepedra, uma arqueóloga encurralada no sítio de...",kw={"explorers' league","marina tecepedra","carta de marina","mottled raptors","tarrel tecepedra","pantanal","sítio de escavação de whelgar"},ang={["faction:Alliance"]="Entregar esta nota traz informações vitais e um consolo agridoce aos sentinelas da Aliança que vigiam a estrada do Pantanal.",["race:Dwarf"]="A carta ressalta o alto custo pessoal que a Explorers' League paga para desenterrar a história antiga pelas selvas perigosas de Khaz Modan."},sec={{t="Um Despacho das Ruínas",b="Enquanto escavava enormes fósseis pré-históricos e relíquias no Sítio de Escavação de Whelgar no Pantanal, a expedição dos anões perturbou um ninho de ferozes Mottled Raptors. As feras invadiram as trincheiras, massacrando vários trabalhadores e cortando a rota de fuga dos pesquisadores sobreviventes. Escrevendo este bilhete em meio ao caos, Marina Tecepedra escreveu para informar seu marido Tarrel de volta ao Porto de Menethil que, embora a escavação esteja em ruínas, ela, o Prospector Whelgar e Ormer Trançaferro conseguiram sobreviver atrás de um abrigo barricado."}},faq={{q="Quem escreveu a Carta de Marina?",a="A carta foi escrita por Marina Tecepedra, uma exploradora que participava da expedição arqueológica no sítio de escavação a leste do Porto de Menethil, no Pantanal.",al={"autor de carta de marina","quem é marina"}},{q="A quem a carta é endereçada?",a="Ela é endereçada a Tarrel Tecepedra, que aguarda ansiosamente por notícias na ponte no Porto de Menethil.",al={"destinatário de carta de marina","quem recebe carta de marina"}},{q="O que aconteceu com a equipe de escavação?",a="Enquanto desenterrava ossos fossilizados gigantescos, a equipe arqueológica foi emboscada e subjugada por um bando de Mottled Raptors. Muitos trabalhadores anões foram mortos, restando apenas um pequeno punhado de sobreviventes barricados em um acampamento improvisado.",al={"o que aconteceu com a escavação","por que a expedição fracassou"}},{q="Quem ajudou Marina a sobreviver ao ataque?",a="Ormer Trançaferro lutou bravamente para defender Marina e o prospector-chefe, permitindo que eles recuassem e buscassem abrigo enquanto o restante da escavação caía perante os raptores.",al={"quem salvou marina","ormer trançaferro"}}},fx={bce088a8={q="O que é a Carta de Marina?",a="A Carta de Marina é uma mensagem urgente escrita por Marina Tecepedra, uma sobrevivente do ataque catastrófico de raptores ao local de escavação do Pantanal. Endereçada ao seu amado Tarrel Tecepedra, o bilhete relata o desastre que se abateu sobre sua equipe de escavação e confirma que ela, o Prospector Whelgar e Ormer Trançaferro escaparam por pouco com vida.",al={"carta de marina","o que é a carta de marina","bilhete de marina"}},ded8799c={q="Por que Tarrel quer a Carta de Marina?",a="Tarrel Tecepedra enviou você aos perigosos pântanos especificamente em busca de notícias de sua amada e do destino da equipe de escavação desaparecida. A Carta de Marina fornece a ele a confirmação vital de que ela ainda está viva, enquanto detalha a perda trágica do local de escavação e seu refúgio desesperado dos raptores ao redor.",al={"por que entregar a carta de marina","por que tarrel quer a carta","objetivo da carta de marina"}}},fp="15,152,25.471.0,26.142.0,31.112.0,37.190.0,37.183.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Parte do Meio da Chave de Gelkak",s="A Parte do Meio da Chave de Gelkak é um fragmento de metal quebrado pertencente ao pirata gnomo náufrago Gelkak Giramastro. Depois que sua embarcação afundou na costa de Costa Negra, esta seção central foi levada por saqueadores entre os murlocs Greymist locais.",h="A Parte do Meio da Chave de Gelkak é um fragmento de metal quebrado pertencente ao pirata gnomo náufrago...",kw={"mecanismo de corda","costa negra","gelkak giramastro","greymist","parte do meio da chave de gelkak","murloc","naufragio"},ang={["profession:Engineering"]="A chave é um componente mecânico personalizado, projetado para dar corda e operar um primeiro-imediato de corda, exibindo a clássica engenhosidade gnômica mesmo em mãos de piratas."},sec={{t="Um Fragmento no Lodo",b="Quando o navio de Gelkak Giramastro foi arrastado para o fundo das ondas por threshadons selvagens, o pirata gnomo foi parar na praia com seus pertences mais preciosos despedaçados nos bancos de rocha. Em meio aos destroços, estava uma chave de corda especializada feita para o seu primeiro-imediato mecânico. A chave se partiu em três fragmentos distintos durante a catástrofe, espalhando-se pela praia. Enquanto a parte superior e a inferior foram levadas por feras costeiras, a seção do meio chamou a atenção dos murlocs Greymist que rondavam a arrebentação de Costa Negra, os quais rapidamente acumularam a peça metálica brilhante em seus acampamentos e pilhas de destroços."}},faq={{q="Para que serve a Parte do Meio da Chave de Gelkak?",a="É um dos três fragmentos necessários para o pirata náufrago Gelkak Giramastro na costa de Costa Negra. Depois de reunida com as partes superior e inferior, a chave completa é usada para reativar seu primeiro-imediato mecânico.",al={"o que a chave de gelkak faz","uso da parte do meio da chave de gelkak","por que preciso desta chave"}},{q="Onde essa parte da chave foi parar?",a="O fragmento do meio foi recolhido pela tribo de murlocs Greymist. Ele pode ser obtido de saqueadores, oráculos, lanceiros de rede, caçadores de maré e outros membros da tribo Greymist que vagam pelas praias e pelos naufrágios de Costa Negra.",al={"quem tem a chave do meio","onde encontrar a parte do meio da chave de gelkak","chave do meio saqueada de"}},{q="Por que a chave quebrou em primeiro lugar?",a="O navio de Gelkak foi afundado perto da costa por threshadons agressivos. Quando o gnomo foi parar na praia em meio aos destroços despedaçados, a chave se chocou contra as rochas costeiras e se quebrou em três pedaços antes que saqueadores locais os levassem.",al={"como a chave quebrou","por que esta em pedacos"}}},fx={d3714d13={q="O que é a Parte do Meio da Chave de Gelkak?",a="É a seção central de uma chave de três peças pertencente ao pirata gnomo náufrago Gelkak Giramastro. Quando seu navio afundou na costa da Costa Negra e ele foi levado pela maré, a chave quebrou nas rochas pontiagudas, deixando este fragmento entre os destroços.",al={"parte do meio da chave de gelkak","peça do meio da chave de gelkak","o que é esta peça da chave"}},["55a592b4"]={q="De onde vem a Parte do Meio da Chave de Gelkak e quem a fez?",a="A chave pertence a Gelkak Giramastro, trazida a bordo de sua embarcação antes de ser destruída por threshadons na costa da Costa Negra. Embora Gelkak possuísse a chave para operar seu primeiro imediato mecânico, seu fabricante exato é desconhecido.",al={"quem fez a chave de gelkak","origem da peça do meio da chave","de onde veio a chave"}},["7cf04b1b"]={q="Por que Gelkak Giramastro quer a parte do meio da chave?",a="Gelkak Giramastro precisa desta peça central junto com as outras duas para remontar a chave inteira. Sem a chave completa, ele não pode dar corda e reativar seu primeiro imediato mecânico para se vingar das feras da costa local.",al={"por que gelkak quer esta chave","quem quer a chave de gelkak","por que a chave é necessária"}}},fp="22,138,22.481.0,44.163.0,32.176.0,42.190.0"}
P.entries["item:milly-s-harvest"] = {n="Colheita da Madel",s="A Colheita da Madel consiste em caixotes e baldes de uvas recém-colhidas por Madel Quintana nos Vinhedos de Vila Norte. Quando bandidos Défias invadiram os campos, a colheita foi abandonada, deixando as frutas em risco de serem roubadas por ladrões ou esmagadas sob as botas dos guardas da abadia.",h="A Colheita da Madel consiste em caixotes e baldes de uvas recém-colhidas por Madel Quintana nos Vinhedos de...",kw={"defias","floresta de elwynn","uvas","madel quintana","colheita da madel","abadia de vila norte","vinhedos de vila norte"},ang={["faction:Alliance"]="A ameaça aos simples fazendeiros de Vila Norte destaca o quanto a guarnição militar de Ventobravo ficou desfalcada, deixando os cidadãos comuns dependentes de aventureiros que passam pelo local para proteger seu sustento.",["race:Human"]="Para os humanos que começam sua jornada em Vila Norte, recuperar a colheita de Madel costuma ser o primeiro encontro direto com a crescente criminalidade da Irmandade Défias em solo natal."},sec={{t="Uma Safra Frágil",b="O solo fértil do Vale de Vila Norte produz uvas vitais para os vinicultores locais e para a comunidade da abadia. Quando a época da colheita chegou, Madel Quintana trabalhou nas videiras para recolher as frutas frescas em baldes de armazenamento. Seu trabalho foi violentamente interrompido quando bandidos armados usando máscaras vermelhas avançaram sobre os vinhedos, forçando-a a fugir de volta para os terrenos da abadia, deixando sua safra espalhada entre as fileiras."},{t="Dano Colateral",b="Embora os guardas de Ventobravo vigiem a entrada do vale, a escassez de contingente deixou Vila Norte vulnerável. Embora a guarnição tenha prometido expulsar os Défias, Madel temia que qualquer confronto prolongado entre guardas de armadura e ladrões implacáveis resultasse na destruição completa do seu trabalho. Recuperar os caixotes antes que sejam pisoteados ou levados como provisões garante que uma das poucas colheitas pacíficas de Vila Norte não seja perdida."}},faq={{q="O que é a Colheita da Madel?",a="É uma reunião de uvas recém-colhidas guardadas em caixotes e baldes, deixadas para trás por Madel Quintana quando capangas Défias tomaram os Vinhedos de Vila Norte.",al={"colheita da madel","o que e a colheita","uvas de madel quintana"}},{q="Por que os caixotes foram deixados para trás no vinhedo?",a="Bandidos Défias atacaram os vinhedos bem no meio do trabalho de colheita de Madel, forçando-a a abandonar os frutos e fugir para salvar a própria vida em direção à segurança da Abadia de Vila Norte.",al={"por que abandonada","por que madel deixou as uvas","por que deixar a colheita"}},{q="Por que os guardas de Vila Norte não puderam recuperar a colheita?",a="Os guardas em Vila Norte já estão sobrecarregados lidando com as incursões Défias e ameaças locais. Madel também temia que, mesmo se os guardas expulsassem os bandidos, suas botas em combate pisoteassem e destruíssem as uvas delicadas.",al={"por que nao os guardas","por que os guardas nao pegam","guardas de ventobravo vila norte"}},{q="Quem são os bandidos que ameaçam a colheita?",a="Os invasores são capangas pertencentes à Irmandade Défias, um bando de foras da lei e bandoleiros que causa agitação generalizada por toda a Floresta de Elwynn.",al={"quem tomou os vinhedos","quem esta atacando o vinhedo","bandidos do vinhedo"}}},fx={["1d7cbab4"]={q="Por que Milly quer que sua colheita seja recuperada?",a="Milly Osworth colheu a safra ela mesma e depende dela para seu sustento, mas teve que abandoná-la quando bandidos da Defias invadiram o vinhedo. Ela teme que, se os ladrões não fugirem com as frutas primeiro, os guardas da Abadia pisotearão as uvas frágeis na terra enquanto expulsam os salteadores.",al={"por que milly quer a colheita","por que recuperar a colheita de milly","por que as uvas são importantes"}}},fp="15,174,15.261.0,17.328.0,24.138.0,48.128.0,56.161.0,44.141.0"}
P.entries["item:mind-s-eye"] = {n="Olho da Mente",s="O Mind’s Eye é um artefato que está nas mãos de Mai’Zoth, um mago ogro da Selva do Espinhaço. Sua magia é temida por corromper e fortalecer quem a usa.",h="O Mind’s Eye é um artefato que está nas mãos de Mai’Zoth, um mago ogro da Selva do Espinhaço.",kw={"irmão nimetz","kin'weelay","kurzen","mai'zoth","olho da mente","mosh’ogg","mago ogro","selva do espinhaço","yennikan"},ang={["faction:Horde"]="Como membro da Horda, o Mind’s Eye diz respeito ao esforço dos Lançanegra para salvar Yennikan, o filho do chefe."},sec={{t="O mago ogro",b="Irmão Nimetz acredita que Mai’Zoth usou o Mind’s Eye para corromper Kurzen. O mago ogro mantém o artefato dentro do monte ogro de Mosh’Ogg, no leste da Selva do Espinhaço. Nimetz teme que sua influência também possa corromper outras pessoas."},{t="Uma escolha pelo Olho",b="Kin’weelay busca o Mind’s Eye como a única esperança de salvar Yennikan. Depois de recuperá-lo, Kin’weelay pretende direcionar seu poder às necessidades dos Lançanegra. Irmão Nimetz planeja estudar o artefato e decidir se ele pode ser usado para o bem ou se deve ser destruído."}},faq={{q="O que é o Mind’s Eye?",a="O Mind’s Eye é um artefato que está nas mãos de Mai’Zoth, um mago ogro. Dizem que sua magia fortalece o poder dele e corrompe outras pessoas.",al={"mind’s eye","o que é mind’s eye","o olho"}},{q="Quem está com o Mind’s Eye?",a="Mai’Zoth, um mago ogro, mantém o Mind’s Eye nas profundezas do monte ogro de Mosh’Ogg, na Selva do Espinhaço.",al={"quem está com o olho","olho de mai’zoth","quem tem o mind’s eye"}},{q="O que o Mind’s Eye fez com Kurzen?",a="Irmão Nimetz acredita que Mai’Zoth usou o Mind’s Eye para corromper Kurzen. Ele teme que sua influência também possa corromper outras pessoas.",al={"corrupção de kurzen","por que kurzen é mau","mind’s eye e kurzen"}},{q="Por que Kin’weelay quer o Mind’s Eye?",a="Kin’weelay busca o Mind’s Eye como a única esperança de salvar Yennikan, filho do chefe dos Lançanegra.",al={"mind’s eye de kin’weelay","salvar yennikan","por que o olho"}},{q="O que Irmão Nimetz fará com ele?",a="Irmão Nimetz planeja estudar o Mind’s Eye e decidir se ele pode ser usado para o bem ou se deve ser destruído.",al={"nimetz e o olho","destruir mind’s eye","estudar o olho"}},{q="Onde fica Mai’Zoth?",a="Mai’Zoth vive no monte ogro de Mosh’Ogg, no leste da Selva do Espinhaço.",al={"localização de mai’zoth","monte de mosh’ogg","onde fica o mago ogro"}}},fp="10,160,13.229.0,20.267.0,25.133.0,25.109.0,39.120.0,44.100.0,36.111.0,20.81.0"}
P.entries["item:miners-gear"] = {n="Equipamento de Mineração",s="O Equipamento de Mineração consiste em picaretas, pás e ferramentas de escavação anãs resistentes armazenadas na Mina da Prata. Após uma infestação de pragas, a Miners' League encarregou aventureiros de recuperar esses valiosos instrumentos antes que os guardas locais iniciassem um ataque.",h="O Equipamento de Mineração consiste em picaretas, pás e ferramentas de escavação anãs resistentes armazenadas...",kw={"filthy paws","kobold","loch modan","equipamento de mineracao","miners league","montanhista lançatroz","mina da prata"},ang={["profession:Mining"]="Todo minerador conhece o valor do ferro anão bem forjado; deixar picaretas e pás de alta qualidade nas mãos de carniceiros que usam velas é considerado uma pequena tragédia.",["race:Dwarf"]="Para os anões, kobolds pondo suas patas imundas em obras anãs é um insulto intolerável que justifica limpar a mina imediatamente."},sec={{t="Suprimentos da Miners' League",b="Quando o minério da Mina da Prata, no norte de Loch Modan, se esgotou, a Miners' League transformou os túneis tranquilos em um depósito subterrâneo para equipamentos de mineração. Infelizmente, kobolds que habitam túneis rapidamente tomaram o complexo, fugindo com os bens armazenados e fazendo ninhos entre os caixotes. Temendo que o valioso equipamento anão fosse destruído em um ataque total dos Mountaineers ou arruinado pelos carniceiros, a liga depende de aventureiros destemidos para se aventurarem no local e levarem os caixotes de volta à segurança."}},faq={{q="O que é o Equipamento de Mineração?",a="O Equipamento de Mineração refere-se a caixotes de ferramentas de escavação anãs — como picaretas e pás — pertencentes à Miners' League, guardados nos túneis secos da Mina da Prata.",al={"o que e equipamento de mineracao","itens de equipamento de mineracao","equipamento de mineracao loch modan"}},{q="Por que o equipamento foi deixado na mina?",a="Depois que o minério da Mina da Prata se esgotou, a Miners' League converteu os túneis vazios em um depósito. Ele permaneceu lá até que kobolds infestaram inesperadamente os poços.",al={"por que o equipamento esta na mina da prata","por que deixar equipamento la"}},{q="Quem quer a recuperação deste equipamento?",a="O Montanhista Lançatroz coordena os esforços de recuperação em nome da Miners' League. Ele busca resgatar as ferramentas antes que seus companheiros guerreiros marchem para exterminar os kobolds.",al={"quem quer equipamento de mineracao","quem precisa do equipamento","equipamento do montanhista lancatroz"}},{q="Onde o Equipamento de Mineração é encontrado?",a="O equipamento está empacotado em Miners' League Crates espalhados pelos poços da Mina da Prata, localizada nas colinas do norte de Loch Modan, a leste da Estação Algaz.",al={"localizacao do equipamento de mineracao","onde encontrar equipamento de mineracao","localizacao dos caixotes da miners league"}}},fp="12,184,30.382.0,21.149.0,34.167.0,30.152.0,32.128.0"}
P.entries["item:miners-union-card"] = {n="Carteira do Sindicato dos Mineradores",s="Uma Carteira do Sindicato dos Mineradores é uma credencial de identificação que era carregada por trabalhadores que operavam nos ricos veios subterrâneos sob Arroio da Lua. Após um desmoronamento catastrófico que selou uma ala dos túneis, esses itens agora permanecem com os cadáveres esqueléticos inquietos que vagam pelos túneis escuros.",h="Uma Carteira do Sindicato dos Mineradores é uma credencial de identificação que era carregada por...",kw={"desmoronamento","collecting memories","minas mortas","carteira do sindicato dos mineradores","arroio da lua","minerador esquelético","ventobravo","carteira do sindicato"},ang={["faction:Alliance"]="Recuperar esses itens perdidos proporciona um desfecho para famílias por todo o reino de Ventobravo que nunca souberam o verdadeiro destino de seus parentes trabalhadores.",["profession:Mining"]="Para garimpeiros e portadores de picareta, os cartões servem como um lembrete sombrio dos riscos mortais de desmoronamentos subterrâneos e poços de mina sem gestão."},sec={{t="Tragédia nas Profundezas",b="Muito antes de a Irmandade Défias assumir o controle absoluto de Arroio da Lua, os trabalhadores labutavam no subsolo sob a bandeira da guilda dos mineradores, extraindo minério valioso para o reino. Isso acabou em desastre quando um colapso severo no túnel esmagou um poço principal, prendendo e matando dezenas de trabalhadores sob toneladas de rocha. Em vez de encontrar uma sepultura tranquila, aqueles que pereceram se levantaram novamente como mineradores, escavadores e dinamitadores esqueléticos. As carteiras do sindicato agarradas em seus bolsos ósseos são a única prova sobrevivente de suas identidades, procuradas por colegas sobreviventes em Ventobravo que esperam trazer um desfecho para as famílias em luto."}},faq={{q="O que é uma Carteira do Sindicato dos Mineradores?",a="É um cartão de identificação oficial pertencente a um membro da guilda que certa vez escavou as minas de Arroio da Lua. Trabalhadores sobreviventes usam esses cartões para confirmar quem pereceu no desastre subterrâneo.",al={"o que é carteira do sindicato","carteira de minerador","carteira do sindicato"}},{q="De onde vêm esses cartões?",a="Eles são recuperados dos trabalhadores mortos-vivos — como mineradores esqueléticos, escavadores mortos-vivos e dinamitadores mortos-vivos — que assombram os túneis colapsados dentro das Minas Mortas sob Arroio da Lua.",al={"onde encontrar carteiras do sindicato","quem deixa cair carteiras de minerador","local de obtenção da carteira"}},{q="Por que os mineradores são mortos-vivos?",a="Um desmoronamento catastrófico os selou em um poço profundo. O que os reanimou como mortos-vivos não é explicado; seus restos mortais agora assombram os túneis colapsados sob Arroio da Lua.",al={"por que mineradores esqueléticos","como os mineradores morreram","mortos-vivos de minas mortas"}},{q="Quem quer que esses cartões sejam devolvidos?",a="Colegas de trabalho sobreviventes que escaparam do desmoronamento agora residem em Ventobravo, coletando os cartões para que possam notificar as famílias dos caídos e conceder-lhes paz.",al={"quem recebe as carteiras do sindicato","doador da missão collecting memories","entregar carteiras do sindicato"}}},fp="18,179,19.484.0,29.152.0,31.150.0,26.147.0,31.173.0"}
P.entries["item:miniaturization-residue"] = {n="Miniaturization Residue",s="O Resíduo de Miniaturização fica nos gigantes de Feralas encolhidos pelo aparelho de Zorbin Cegasvista. Ele o estuda para aprimorar seu raio encolhedor e pede mais nos cais da Costa Esquecida.",h="O Resíduo de Miniaturização fica nos gigantes de Feralas encolhidos pelo aparelho de Zorbin Cegasvista.",kw={"engenharia","feralas","costa esquecida","gigantes","resíduo de miniaturização","cartel bondebico","zorbin cegasvista","ultra-shrinker do zorpin"},ang={["profession:Engineering"]="Como engenheiro, você talvez reconheça no interesse de Zorbin pelo resíduo uma forma de aprimorar seus dispositivos de encolhimento."},sec={{t="Resíduo dos Gigantes",b="Na Costa Esquecida, Zorbin Cegasvista procura resíduos de gigantes encolhidos com seu Ultra-Shrinker. Cliff Giants, Deep Striders, Land Walkers, Shore Striders e Wave Striders deixam resíduos depois que o aparelho é usado. Zorbin diz que o resíduo ajuda a impedir que seus outros zappers explodam nas mãos de quem os usa."}},faq={{q="O que é o Resíduo de Miniaturização?",a="O Resíduo de Miniaturização é encontrado em gigantes de Feralas depois que eles são encolhidos com o Ultra-Shrinker de Zorbin.",al={"resíduo de miniaturização","o que é esse resíduo","resíduo de gigante"}},{q="Quem quer o resíduo?",a="Zorbin Cegasvista, nos cais da Costa Esquecida, pede Resíduo de Miniaturização.",al={"quem quer o resíduo","resíduo de zorbin","para quem devo levar"}},{q="Por que Zorbin precisa dele?",a="Zorbin estuda o resíduo para ajudar a garantir que seus outros dispositivos de encolhimento não explodam nas mãos de quem os usa.",al={"por que resíduo","para que serve o resíduo","pesquisa sobre zappers"}},{q="Quais gigantes têm o resíduo?",a="Cliff Giants, Deep Striders, Land Walkers, Shore Striders e Wave Striders de Feralas podem deixar resíduos depois de serem encolhidos.",al={"de quais gigantes vem o resíduo","quais gigantes","gigantes de feralas"}}},fp="23,179,19.310.0,32.110.0,22.88.0,24.100.0,21.124.0"}
P.entries["item:minshina-s-skull"] = {n="Crânio de Minshina",s="O crânio de Minshina contém a alma aprisionada do troll Lançanegra Minshina, irmão do Mestre Gadrin. Preso pelo pérfido médico bruxo Zalazane nas Ilhas do Eco, o crânio serve como um receptáculo sombrio usado para alimentar magias rituais profanas.",h="O crânio de Minshina contém a alma aprisionada do troll Lançanegra Minshina, irmão do Mestre Gadrin.",kw={"círculo de poder","lançanegra","ilhas do eco","gadrin","minshina","aldeia sen'jin","crânio","zalazane"},ang={["faction:Horde"]="Recuperar o crânio desfere um golpe inicial contra o domínio perverso de Zalazane sobre as Ilhas do Eco, bem perto da costa de Durotar.",["race:Troll"]="Para os Lançanegra, a profanação de Minshina por Zalazane é uma afronta gravíssima à tradição ancestral, tornando a recuperação de seu crânio uma questão vital de honra tribal."},sec={{t="Um espírito aprisionado",b="Quando Zalazane tomou o controle das Ilhas do Eco e expulsou a tribo Lançanegra, Minshina esteve entre os capturados e mortos. Em vez de permitir que sua vítima descansasse na morte, o médico bruxo traidor vinculou a alma de Minshina ao seu próprio crânio decepado. Colocado dentro de um círculo de poder fétido na ilha mais ao sul, o crânio tornou-se um elo de escravização mágica. O Mestre Gadrin, guiado por visões atormentadas de seu irmão chamando por ele em sonhos, busca viajantes corajosos dispostos a se aventurar nas ilhas ocupadas, recuperar a relíquia e quebrar o domínio de Zalazane sobre o espírito de seu irmão."}},faq={{q="Quem foi Minshina?",a="Minshina era um troll Lançanegra e irmão do Mestre Gadrin da Aldeia Sen'jin. Ele foi assassinado durante o caos que cercou a traição de Zalazane nas Ilhas do Eco.",al={"história de minshina","quem é minshina","irmão do mestre gadrin"}},{q="Por que a alma de Minshina está presa em seu crânio?",a="Zalazane usou magias sombrias para vincular o espírito de Minshina diretamente à sua cabeça decepada. Disposta dentro de um círculo ritualístico de poder na ilha principal, a alma aprisionada permaneceu subjugada à vontade de Zalazane em vez de seguir rumo aos ancestrais.",al={"por que prender a alma","ritual de crânio de zalazane","alma presa no crânio"}},{q="Onde o crânio está localizado?",a="O crânio é encontrado na maior e mais meridional ilha das Ilhas do Eco. Ele repousa no topo de uma colina dentro de um círculo de poder adornado com velas, marcos rituais e outros crânios protegidos pelos servos de Zalazane.",al={"onde fica o crânio de minshina","localização do círculo de poder","localização do crânio ilhas do eco"}},{q="O que acontece quando o crânio é levado ao Mestre Gadrin?",a="Devolver o crânio ao Mestre Gadrin na Aldeia Sen'jin quebra o encantamento sombrio. Com o elo profano rompido, a forma espectral de Minshina se manifesta brevemente, curva-se em gratidão e parte em paz para o reino dos ancestrais.",al={"libertar minshina","recompensa crânio gadrin","o que acontece com minshina"}}},fx={["5c3b75e4"]={q="O que é o Crânio de Minshina?",a="O Crânio de Minshina são os restos físicos de Minshina, um troll Lançanegra caído e irmão do Mestre Gadrin. Em vez de descansar pacificamente na morte, Minshina teve sua própria alma presa em seu crânio decepado através de vodu sombrio, deixando-o preso e clamando por libertação.",al={"o que é o crânio de minshina","identidade do crânio de minshina","o que é este crânio"}},["1b71ee0f"]={q="De onde vem o Crânio de Minshina e quem o fez?",a="O crânio pertencia a Minshina, que foi capturado e morto pelo bruxo traidor Zalazane nas Ilhas do Eco. Usando feitiçaria vil, Zalazane decepou a cabeça e prendeu o espírito de Minshina diretamente ao osso, colocando-o dentro de um círculo de poder junto com outros restos mortais para alimentar seus rituais sombrios.",al={"de onde veio o crânio de minshina","quem fez o crânio de minshina","origem do crânio de minshina"}},b6c5f4d1={q="Por que alguém quer o Crânio de Minshina?",a="Mestre Gadrin busca o crânio para resgatar o espírito atormentado de seu irmão. Minshina clama constantemente por Gadrin em seus sonhos, incapaz de encontrar descanso enquanto está aprisionado pela magia de Zalazane. Recuperar o crânio do círculo de poder nas Ilhas do Eco é a única maneira de quebrar o vínculo e conceder liberdade à sua alma.",al={"por que querer o crânio de minshina","por que coletar o crânio de minshina","quem quer o crânio de minshina"}}},fp="16,242,16.507.0,17.142.0,44.206.0,27.192.0,56.206.1"}
P.entries["item:mirefin-head"] = {n="Mirefin Head"}
P.entries["item:mirror-lake-water-sample"] = {n="Amostra de Água do Lago Espelhado",s="A Amostra de Água do Lago Espelhado é um frasco de água fresca do lago coletada na base da cachoeira na Floresta de Elwynn. Recolhida por magos novatos em nome de Jana Catão no Distrito dos Magos de Ventobravo, ela é usada para investigar se correntes arcanas alteradas estão se infiltrando no abastecimento de água local.",h="A Amostra de Água do Lago Espelhado é um frasco de água fresca do lago coletada na base da cachoeira na...",kw={"impureza arcana","floresta de elwynn","frasco","jana catão","lago espelhado","ventobravo","amostra de água","sacrário dos teurgos"},ang={["class:Mage"]="Buscar a amostra é um dever inicial para os magos da Aliança em treinamento no Sacrário dos Teurgos, ensinando-os a monitorar linhas de força ambientais e a reconhecer infiltrações mágicas selvagens."},sec={{t="Testando as Águas de Elwynn",b="Após conflitos globais catastróficos que desviaram os canais místicos do mundo de seus cursos estáveis, os magos do Sacrário dos Teurgos em Ventobravo ficaram profundamente preocupados com a perturbação arcana residual. Jana Catão encarrega aprendizes promissores de encher um frasco especialmente preparado na base da cachoeira do Lago Espelhado, localizada logo a sudoeste do Portão de Ventobravo. Ao analisar esta amostra de água, os magos procuram detectar se impurezas mágicas dispersas se infiltraram nos cursos d'água naturais dos quais depende a população do entorno."}},faq={{q="O que é a Amostra de Água do Lago Espelhado?",a="É um frasco com água retirada da cachoeira no Lago Espelhado, na Floresta de Elwynn, contida no Frasco de Jennea. Magos novatos a coletam para que o Sacrário dos Teurgos possa testar a presença de contaminação mágica.",al={"amostra do lago espelhado","item amostra de água","água da jana"}},{q="Por que Jana Catão quer esta amostra de água?",a="Convulsões místicas recentes por toda Azeroth perturbaram as correntes mágicas estáveis. Jana Catão teme que a energia mágica descontrolada possa estar alterando o ambiente natural e envenenando a água potável local.",al={"por que testar lago espelhado","objetivo jana catão","água com impureza mágica"}},{q="Onde a amostra é coletada?",a="Ela é coletada na base da cachoeira que deságua no Lago Espelhado, localizada a sudoeste do Portão de Ventobravo na Floresta de Elwynn.",al={"onde pegar a amostra","localização lago espelhado","amostra cachoeira"}},{q="O que acontece se a água estiver magicamente corrompida?",a="Jana Catão teme que qualquer pessoa que beba do Lago Espelhado por períodos prolongados possa sofrer efeitos mágicos adversos se as linhas de força tiverem contaminado o suprimento de água.",al={"efeitos da água contaminada","lago espelhado envenenado"}}},fx={["935f4959"]={q="De onde vem a Amostra de Água do Lago Espelhado e quem a coletou?",a="A amostra é coletada diretamente da base da cachoeira que deságua no Lago Espelhado, logo a sudoeste dos portões de Ventobravo na Floresta de Elwynn. Usando um frasco vazio fornecido pela instrutora de Mago, Jana Catão, você mesmo coleta a água em nome dos conjuradores de Ventobravo para que eles possam examinar o estado das correntes selvagens ao redor.",al={"de onde vem a amostra de água do lago espelhado","quem fez a amostra de água do lago espelhado","origem da amostra de água do lago espelhado"}}},fp="24,166,28.411.0,37.151.0,46.177.0,30.123.0,60.154.0"}
P.entries["item:miscellaneous-goblin-supplies"] = {n="Miscellaneous Goblin Supplies",s="Suprimentos variados dos goblins são entregas regulares destinadas ao acampamento do Tenente Doren, perto da entrada da Selva do Espinhaço. Eles contêm minas terrestres para defender o local de Kurzen e seus homens.",h="Suprimentos variados dos goblins são entregas regulares destinadas ao acampamento do Tenente Doren, perto da...",kw={"floresta do crepúsculo","suprimentos dos goblins","kurzen","minas terrestres","tenente doren","suprimentos variados dos goblins","recruta turgo","selva do espinhaço"},sec={{t="Uma entrega necessária",b="O Recruta Turgo recebe os suprimentos no acampamento do Tenente Doren, a noroeste da estrada que vai da Floresta do Crepúsculo à Selva do Espinhaço. Ataques de Troll atrasaram a entrega regular, e os seguidores de Doren precisam dela. Turgo pode estar no acampamento ou patrulhando ao sul. As minas devem ajudar a defender o acampamento de Kurzen e seus homens."}},faq={{q="O que são os suprimentos dos goblins?",a="São minas terrestres fornecidas pelos goblins para o acampamento do Tenente Doren.",al={"suprimentos dos goblins","suprimentos variados","o que há no pacote"}},{q="Quem precisa desses suprimentos?",a="O Recruta Turgo recebe os suprimentos para os seguidores do Tenente Doren no acampamento deles.",al={"quem recebe os suprimentos","quem precisa deles","entregar para quem"}},{q="Onde fica o acampamento de Doren?",a="O acampamento fica a noroeste da estrada, na entrada da Selva do Espinhaço, vindo da Floresta do Crepúsculo.",al={"localização do acampamento de doren","onde fica o acampamento","acampamento perto da selva do espinhaço"}},{q="Por que as minas são necessárias?",a="As minas ajudarão a defender o acampamento de Doren de Kurzen e seus homens.",al={"por que minas","para que servem as minas","defesa contra kurzen"}}},fp="29,183,17.333.0,29.74.0,25.87.0,24.88.0,25.66.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Baú do Véu das Brumas",s="O Baú do Véu das Brumas é uma caixa-forte resistente que repousa nos destroços submersos da embarcação dos elfos noturnos Véu das Brumas, na costa de Costa Negra. Ele contém o diário de bordo e os pertences pessoais do capitão, perdidos quando o navio foi emboscado e afundado por murlocs costeiros.",h="O Baú do Véu das Brumas é uma caixa-forte resistente que repousa nos destroços submersos da embarcação dos...",kw={"auberdine","costa negra","gorbold manácero","baú","véu das brumas","murloc","naufrágio","silver dawning"},ang={["faction:Alliance"]="Recuperar este baú homenageia a tripulação caída e ajuda a combalida comunidade marítima estabelecida em Auberdine.",["race:NightElf"]="O capitão caído era um respeitado marinheiro elfo noturno, e resgatar seu diário de bordo ajuda a trazer paz a um espírito valoroso nas águas de Costa Negra."},sec={{t="Perdido nas Profundezas",b="A embarcação dos elfos noturnos Mist Veil encontrou seu fim enquanto navegava pelas traiçoeiras águas costeiras em direção a Auberdine. Emboscado por murlocs hostis ao lado de seu navio-irmão, o Silver Dawning, o navio foi subjugado e mandado para o fundo do oceano. Seu capitão pereceu durante o ataque, deixando para trás seu diário de bordo e pertences pessoais valiosos selados dentro deste baú. Repousando no porão inundado, o baú permanece como um troféu sombrio cercado pelas mesmas criaturas responsáveis pela catástrofe."},{t="Descanso para a Tripulação",b="Para os marinheiros sobreviventes que conseguiram chegar a Auberdine, a perda de sua embarcação e de seu comandante continua sendo uma ferida aberta. Gorbold Manácero busca a recuperação do Baú do Véu das Brumas para que os últimos pertences do capitão possam ser devidamente homenageados e descansem em paz. Desbravar as ruínas inundadas para resgatar o baú oferece algum alívio aos sobreviventes aflitos e ilhados no continente."}},faq={{q="O que há dentro do Baú do Véu das Brumas?",a="O baú contém o diário de bordo e pertences pessoais do capitão. O capitão pereceu quando o navio afundou, e a tripulação sobrevivente em Auberdine deseja que essas lembranças sejam devolvidas para homenagear seu líder caído.",al={"conteúdo do baú do véu das brumas","o que o baú contém","o que há na caixa"}},{q="Como o Mist Veil afundou?",a="O Mist Veil foi emboscado por murlocs costeiros enquanto navegava pelas águas em direção a Auberdine. Subjugado pelas criaturas, o navio naufragou e afundou até o leito marinho ao lado de sua embarcação companheira, o Silver Dawning.",al={"por que o navio naufragou","quem afundou o véu das brumas","o que aconteceu com o véu das brumas"}},{q="Onde o baú é encontrado?",a="Ele fica submerso na costa de Costa Negra, ao norte de Auberdine. A caixa-forte repousa dentro do casco inundado dos destroços naufragados do Mist Veil, que está densamente infestado de murlocs.",al={"onde fica o baú do véu das brumas","localização do véu das brumas","localização do baú"}},{q="Quem deseja a recuperação do baú?",a="Gorbold Manácero, em Auberdine, busca o baú em nome dos membros sobreviventes da tripulação, na esperança de trazer um desfecho e paz à memória do capitão caído.",al={"quem recebe o baú","quem dá a missão","missão do baú de gorbold"}}},fx={fab3edd7={q="O que é o Baú do Véu das Brumas?",a="É o baú do capitão recuperado da embarcação afundada Mist Veil, que repousa sob as ondas na costa de Costa Negra, ao norte de Auberdine. Mantido em segurança a bordo da embarcação até que os murlocs afundassem o navio, ele preserva os registros, diários e pertences privados do falecido capitão elfo noturno da viagem arruinada.",al={"o que é o baú do véu das brumas","baú do véu das brumas","o que é o baú"}}},fp="19,179,18.284.0,17.291.0,35.199.0,27.152.0,27.131.0,32.131.0"}
P.entries["item:mo-grosh-crystal"] = {n="Cristal Mo'grosh",s="Os Cristais Mo'grosh são formações minerais raras extraídas e acumuladas pelos ogros Mo'grosh no nordeste de Loch Modan. Valorizados por suas propriedades alquímicas incomuns, eles servem como um componente vital na neutralização de materiais de demolição dos Ferro Negro.",h="Os Cristais Mo'grosh são formações minerais raras extraídas e acumuladas pelos ogros Mo'grosh no nordeste de...",kw={"uma ameaça sombria se aproxima","hinderweir","loch modan","cristal mo'grosh","mo'grosh","dique lapidado"},ang={["profession:Mining"]="Embora extraídos nas profundezas do território dos ogros, esses espécimes minerais brutos demonstram uma reatividade química única quando combinados com reagentes orgânicos.",["race:Dwarf"]="A defesa do Dique Lapidado depende da engenhosidade dos anões, transformando o tesouro minerado de um clã de ogros em uma salvaguarda contra a traição dos Ferro Negro."},sec={{t="Uma Mercadoria Rara dos Ogros",b="Escondidos nos penhascos do nordeste de Loch Modan, os ogros Mo'grosh escavam esses cristais distintos de sua fortaleza. Embora os ogros de força bruta raramente se especializem em metalurgia delicada, os Cristais Mo'grosh são tesouros valiosos entre seu clã, carregados tanto por executores comuns quanto por xamãs místicos e seus líderes imponentes. Os cristais são relativamente incomuns, tornando-os uma posse fortemente guardada dentro da Fortaleza Mo'grosh."},{t="Combatendo a Ameaça Ferro Negro",b="Quando informações revelam que sabotadores Ferro Negro estão conspirando contra o Dique Lapidado, o Engenheiro-chefe Hinderweir busca um Cristal Mo'grosh juntamente com peçonha de tocaieiro e lágrimas de crocolisco. Ao combinar o mineral cristalino com esses reagentes reativos, os engenheiros anões podem preparar um composto especializado capaz de desarmar e desativar explosivos voláteis dos Ferro Negro antes que o vale possa ser inundado."}},faq={{q="De onde vêm os Cristais Mo'grosh?",a="Eles são extraídos e mantidos pelos ogros Mo'grosh no nordeste de Loch Modan. Qualquer membro do clã dentro da Fortaleza Mo'grosh — incluindo místicos, brutamontes, executores e xamãs — pode estar carregando um.",al={"localização do cristal mo'grosh","onde encontrar cristal mo'grosh","quem saqueia cristal mo'grosh"}},{q="Para que o cristal é usado?",a="O Engenheiro-chefe Hinderweir no Dique Lapidado precisa do cristal para preparar uma mistura neutralizante. Misturado com peçonha de tocaieiro e lágrimas de crocolisco, ele serve para desarmar explosivos dos Ferro Negro destinados a sabotar o dique.",al={"o que o cristal mo'grosh faz","uso do cristal mo'grosh","por que hinderweir quer o cristal"}},{q="Por que os ogros estão minerando esses cristais?",a="Os ogros Mo'grosh extraem os cristais nas colinas ao redor de sua fortaleza e, mesmo entre os ogros, os cristais são uma mercadoria muito rara. Para o que os próprios ogros os utilizam não há registro.",al={"por que os ogros têm cristais","história do cristal dos ogros"}}},fx={["1713c585"]={q="O que é um Cristal Mo'grosh?",a="Um Cristal Mo'grosh é um mineral excepcionalmente raro minerado pelos ogros Mo'grosh em sua fortaleza a nordeste de Loch Modan. Valorizado por suas propriedades incomuns, o Engenheiro-chefe Hinderweir o identifica como um componente essencial para preparar uma mistura especializada destinada a desativar os explosivos dos Ferro Negro que ameaçam o Dique Lapidado.",al={"o que é cristal mo'grosh","tradição do cristal mo'grosh","identidade do cristal mo'grosh"}}},fp="16,170,23.326.0,31.326.1,37.180.0,29.200.0,40.119.0"}
P.entries["item:modr-fragment"] = {n="Fragmento de Modr",s="O Fragmento de Modr é um dos quatro pedaços que se soltaram da antiga Pedra de Goaz, uma relíquia desenterrada no Pantanal. Descoberto em meio a relíquias e terra solta dentro do Whelgar Excavation Site, ele traz inscrições antigas dos Titãs, vitais para reunir uma profecia esquecida.",h="O Fragmento de Modr é um dos quatro pedaços que se soltaram da antiga Pedra de Goaz, uma relíquia...",kw={"ados","escavação","pedra de goaz","golm","fragmento de modr","neru","deuses antigos","titã","pantanal","whelgar"},ang={["faction:Alliance"]="Viajantes da Aliança ajudam o Prospector Whelgar a desafiar a escavação tomada para preservar uma pesquisa histórica inestimável para Altaforja.",["race:Dwarf"]="Para a Dwarven Explorers' League, recuperar peças perdidas como o Fragmento de Modr é essencial para decifrar a herança dos Titãs e desvendar a profunda história de seu povo."},sec={{t="Um Pedaço da Pedra de Goaz",b="Antes que raptores cruéis expulsassem a Explorers' League de sua escavação no Pantanal, o Prospector Whelgar descobriu a Pedra de Goaz — uma enorme tábua com inscrições antigas dos Titãs. O texto traduzido foi interrompido abruptamente por quatro lacunas distintas, ocultando avisos de um plano divino e de uma profecia fadada ao fracasso. O Fragmento de Modr é um desses quatro pedaços perdidos, deixado para trás entre relíquias antigas e terra revolvida quando os escavadores foram forçados a fugir para salvar suas vidas."},{t="Segredos Sob a Terra",b="Reunir o Fragmento de Modr junto com os fragmentos de Ados, Golm e Neru permite que o Prospector Whelgar finalmente reconstrua a inscrição completa. O texto traduzido revela uma história surpreendente dos primórdios do mundo, referindo-se especificamente a 'Deuses Antigos... Acorrentados Sob a Terra'. O que começou como uma simples escavação arqueológica nos Pântanos expôs, em vez disso, os vestígios de uma luta primordial aprisionada sob o solo."}},faq={{q="O que é o Fragmento de Modr?",a="É um fragmento de pedra com inscrições que se soltou da Pedra de Goaz, uma antiga Relíquia Titânica descoberta no Whelgar Excavation Site, no Pantanal.",al={"fragmento de modr","o que é modr","relíquia de modr"}},{q="Quem está procurando por este fragmento?",a="O Prospector Whelgar, um arqueólogo da Explorers' League posicionado na borda do local de escavação infestado de raptores, procura por ele para completar o texto que falta na tábua.",al={"quem quer o fragmento de modr","missão do fragmento de whelgar"}},{q="O que acontece quando todos os quatro fragmentos são reunidos?",a="Reunir o Fragmento de Modr com os fragmentos de Ados, Golm e Neru permite que o Prospector Whelgar restaure a Pedra de Goaz. Ao ler a escrita titânica completa, ele descobre menções sinistras a 'Deuses Antigos... Acorrentados Sob a Terra'.",al={"pedra de goaz completa","final de uncovering the past","o que diz a pedra de goaz"}},{q="Onde o fragmento é encontrado?",a="Ele está espalhado pelo Whelgar Excavation Site a leste do Porto de Menethil, no Pantanal, escondido dentro de potes de relíquias antigas ou pedaços de terra solta protegidos por raptores agressivos.",al={"localização do fragmento de modr","onde encontrar modr"}}},fx={c1df2f2b={q="De onde vem o Fragmento de Modr e quem o fez?",a="O Fragmento de Modr é um pedaço da Pedra de Goaz, uma relíquia antiga descoberta no sítio de escavação a leste do Porto de Menethil, no Pantanal. Com inscrições na escrita dos Titãs, a pedra é um artefato dos Titãs, que moldaram o mundo nos tempos primordiais e deixaram para trás registros misteriosos de seu plano divino e profecias de destruição.",al={"origem do fragmento de modr","quem fez o fragmento de modr","de onde veio o fragmento de modr"}}},fp="13,167,25.455.0,25.315.1,26.164.0,33.181.0,50.181.1,28.194.0"}
P.entries["item:moldy-tome"] = {n="Tomo Mofado",s="O Tomo Mofado é um remanescente resgatado e danificado pela água que contém metade do Tomo do Conluio original. Perdido em um naufrágio na costa do Contraforte de Eira dos Montes, ele guarda rituais esotéricos sombrios cobiçados por bruxos que buscam dominar invocações demoníacas.",h="O Tomo Mofado é um remanescente resgatado e danificado pela água que contém metade do Tomo do Conluio...",kw={"veioazul","caçador vil","eira dos montes","tomo mofado","costa sul","manuscrito rasgado","tomo do conluio","bruxo"},ang={["class:Warlock"]="Recuperar este grimório encharcado é um rito de passagem crucial para bruxos que buscam juntar as partes dos rituais necessários para dominar um caçador vil."},sec={{t="Perdido nas Ondas",b="O Tomo do Conluio era um tratado único e insubstituível sobre artes sombrias que outrora esteve no reino de Lordaeron. Em algum momento de sua história obscura, o grimório foi impiedosamente vandalizado e dividido em dois. A parte agora designada como o Tomo Mofado estava sendo transportada para o sul por navio em direção ao Porto de Menethil e Altaforja. A embarcação nunca chegou ao seu destino, sucumbindo às águas traiçoeiras a oeste de Costa Sul. Arrastada para a costa ao sul da Mina Veioazul, a metade sobrevivente permaneceu arruinada pela umidade e pela arrebentação em meio aos murlocs carniceiros que rondam o litoral de Eira dos Montes."},{t="Recuperando a Obra Sombria",b="Apesar de seu velino mofado e apodrecido, o Tomo Mofado retém um potente conhecimento demoníaco. Praticantes das artes sombrias — guiados por mentores como Krom Braçoforte em Altaforja ou Jonas Anísio na Cidade Baixa — enfrentam os acampamentos costeiros para recuperá-lo. Reunido com sua contraparte, o Manuscrito Rasgado encontrado nas cavernas poeirentas de Mil Agulhas, a obra restaurada fornece os encantamentos exatos necessários para invocar e aprisionar um caçador vil."}},faq={{q="O que é o Tomo Mofado?",a="É metade do raro Tomo do Conluio, um grimório ocultista contendo rituais para invocação demoníaca. Encharcado e deteriorado, representa a parte naufragada do texto original.",al={"livro mofado","o que é este item","história do tomo mofado"}},{q="Onde o Tomo Mofado foi parar?",a="Ele foi levado pelas águas até a costa do Contraforte de Eira dos Montes, a oeste de Costa Sul e ao sul da Mina Veioazul. Acabou nas mãos de murlocs costeiros locais, que o guardam em seu acampamento.",al={"localização do tomo mofado","onde fica o tomo mofado","onde encontrar tomo mofado"}},{q="Por que o tomo estava em um navio?",a="Originalmente preservada em Lordaeron, esta parte foi despachada em um navio com destino ao Porto de Menethil para chegar aos estudiosos de Altaforja. A embarcação afundou na costa de Eira dos Montes e nunca completou sua viagem.",al={"por que foi perdido no mar","tomo de naufrágio","transporte do tomo"}},{q="O que é necessário para completar o Tomo do Conluio?",a="O Tomo Mofado deve ser reunido com o Manuscrito Rasgado, a outra metade rasgada do livro que acabou sendo levada para longe, até o Castelo do Casco Fendido em Mil Agulhas.",al={"outra metade do tomo","páginas perdidas","partes do tomo do conluio"}}},fx={f96f31c9={q="De onde vem o Tomo Mofado?",a="O Tomo Mofado era originalmente parte de um volume único e singular conhecido como Tome of the Cabal, outrora preservado dentro dos grandes salões de Lordaeron. Há muito tempo, o grimório foi vandalizado e uma parte substancial de seu pergaminho foi arrancada da encadernação. A parte sobrevivente do livro estava destinada a ser enviada para o sul, de Eira dos Montes pelo mar até o Porto de Menethil e Altaforja, mas a embarcação que o transportava naufragou ao longo da costa a oeste de Costa Sul, deixando as páginas úmidas apodrecerem nas águas rasas.",al={"origem do tomo mofado","quem fez o tomo mofado","onde o tomo mofado era mantido","história do tomo mofado"}},["53a1a6b9"]={q="Por que alguém quer o Tomo Mofado?",a="Estudiosos e praticantes das artes sombrias o procuram porque apenas uma única cópia do Tome of the Cabal foi escrita. Suas passagens arcanas contêm tradições raras e zelosamente guardadas de bruxos, incluindo segredos essenciais para dominar a convocação e a vinculação de cães vis. Estudiosos como Krom Braçoforte em Altaforja e Jonas Anísio na Cidade Baixa cobiçam até mesmo um breve vislumbre de seu texto proibido, tornando a recuperação deste remanescente encharcado vital para reunir a obra completa.",al={"por que encontrar o tomo mofado","quem quer o tomo mofado","por que o tomo mofado é importante","por que bruxos querem o tomo mofado"}}},fp="10,171,17.420.0,24.412.1,23.159.0,32.145.0,27.166.0,49.169.0"}
P.entries["item:monstrous-crawler-leg"] = {n="Monstrous Crawler Leg",s="Uma Pata de Rastejante Monstruoso vem dos enormes rastejantes da costa do Pântano das Mágoas. Dar procura dez para clientes em Orgrimmar, que apreciam a carne.",h="Uma Pata de Rastejante Monstruoso vem dos enormes rastejantes da costa do Pântano das Mágoas.",kw={"carne de rastejante","dar","monstrous crawler","pata de rastejante monstruoso","orgrimmar","pântano das mágoas"},sec={{t="Iguaria costeira",b="Dar, no Pântano das Mágoas, quer dez Patas de Rastejante Monstruoso para clientes em Orgrimmar. As criaturas correm pelas praias a leste e pelo fundo do mar. Sua carne é apreciada pelo sabor suculento, e Dar pretende enviá-la para o norte."}},faq={{q="De onde vêm as Patas de Rastejante Monstruoso?",a="As Patas de Rastejante Monstruoso vêm dos Monstrous Crawlers que vivem nas praias e no fundo do mar junto à costa do Pântano das Mágoas.",al={"origem das patas de rastejante","onde encontrar patas monstruosas"}},{q="Quem quer essas patas?",a="Dar, no Pântano das Mágoas, quer dez Patas de Rastejante Monstruoso para enviar a clientes em Orgrimmar.",al={"quem quer patas de rastejante","patas de dar"}},{q="Por que Dar as quer?",a="Os clientes de Dar apreciam o sabor suculento da carne de rastejante, especialmente a dos Monstrous Crawlers.",al={"por que patas de rastejante","para que servem as patas"}},{q="Onde fica a costa?",a="A costa fica a leste de Dar, no Pântano das Mágoas. Monstrous Crawlers correm pelas praias e pelo fundo do mar.",al={"direção da costa do pântano","praia dos rastejantes"}}},fp="21,148,12.239.0,42.120.0,21.95.0,23.103.0,19.116.0"}
P.entries["item:moonpetal-lily"] = {n="Lírio Lunapétala",s="Lírios Lunapétala são grandes plantas luminosas nativas de Teldrassil que florescem ao redor de poças de água doce. Renomadas por suas potentes qualidades restauradoras, suas pétalas são valorizadas como ingredientes essenciais em remédios naturais e poções de cura.",h="Lírios Lunapétala são grandes plantas luminosas nativas de Teldrassil que florescem ao redor de poças de água...",kw={"aldrassil","antídoto","dirânia pratafulge","iverron","lunapétala","lírio lunapétala","umbravale","teldrassil"},ang={["profession:Herbalism"]="Embora sejam colhidos diretamente à mão durante crises urgentes, os Lírios Lunapétala servem como uma demonstração clara do rico potencial botânico restaurador de Teldrassil.",["race:NightElf"]="Para os jovens kaldorei em treinamento em Umbravale, aprender as propriedades restauradoras de plantas nativas como o Lírio Lunapétala é uma lição inicial vital para viver em harmonia com a natureza."},sec={{t="Flora das Poças",b="Lírios Lunapétala crescem exclusivamente ao longo das margens úmidas de poças e lagoas de água doce, concentrando-se principalmente ao longo do lado noroeste de Aldrassil, em Umbravale. Assim como grande parte da vegetação que floresce no topo da recém-crescida Árvore do Mundo, eles absorvem a essência única dos bosques protegidos de Teldrassil. Suas pétalas largas são suaves e radiantes, fáceis de avistar contornando as margens das águas tranquilas onde a umidade natural lhes permite prosperar."},{t="Antídotos Naturais",b="Curadores e herboristas elfos noturnos valorizam o Lírio Lunapétala por suas propriedades curativas extraordinárias. Quando combinado com outras plantas da floresta, como os Hyacinth Mushrooms, o lírio atua como um poderoso agente suavizante e estabilizador. Essa qualidade restauradora o torna um componente essencial no preparo de antídotos para neutralizar toxinas letais, notadamente o veneno virulento produzido pelas aranhas Lenhateia que espreitam dentro da Caverna Fionumbra."}},faq={{q="Onde crescem os Lírios Lunapétala?",a="Eles crescem ao longo das margens das duas lagoas de água doce situadas no lado noroeste de Aldrassil, em Umbravale, em Teldrassil.",al={"onde encontrar lírios lunapétala","localização do lírio lunapétala","locais de lírios"}},{q="Para que são usados os Lírios Lunapétala?",a="Os lírios possuem notáveis propriedades restauradoras e de cura. Em Umbravale, Dirânia Pratafulge os utiliza junto com Hyacinth Mushrooms e Linfa de Lenhateia para preparar um potente antídoto contra o veneno de aranha.",al={"usos do lírio lunapétala","o que faz o lírio lunapétala"}},{q="Quem precisa de um antídoto feito com esses lírios?",a="Um elfo noturno chamado Iverron, que foi vítima da picada venenosa das aranhas Lenhateia perto da Caverna Fionumbra, precisa de um antídoto preparado com Lírios Lunapétala para sobreviver.",al={"para quem é o antídoto","veneno de iverron"}},{q="Lírios Lunapétala podem ser colhidos fora de Teldrassil?",a="Eles estão diretamente ligados às poças isoladas de Teldrassil e são conhecidos localmente dentro dos galhos protegidos de Umbravale.",al={"os lírios crescem em outros lugares","lírio lunapétala em outras zonas"}}},fx={["1aae6896"]={q="O que é um Lírio Lunapétala?",a="O Lírio Lunapétala é uma flor aquática grande, nativa das águas tranquilas de Teldrassil. Reconhecido por suas potentes propriedades curativas naturais, ele floresce em solo úmido ao longo das bordas de poças e lagos sombreados da floresta, como aqueles situados perto de Aldrassil em Umbravale.",al={"o que é lírio lunapétala","informações do lírio lunapétala","sobre o lírio lunapétala"}}},fp="14,156,18.314.0,17.289.0,31.114.0,35.186.0,45.132.0,55.110.0"}
P.entries["item:moonstalker-fang"] = {n="Presa de Espreitaluna",s="Moonstalker Fangs são caninos afiados obtidos dos predadores moonstalkers que vagam pelos bosques enevoados de Costa Negra. Eles são coletados por viajantes que ajudam Xafetim Manigiro na manutenção de seus dispositivos automatizados de amostragem.",h="Moonstalker Fangs são caninos afiados obtidos dos predadores moonstalkers que vagam pelos bosques enevoados...",kw={"caixazorra 323","costa negra","moonstalker","presa de espreitaluna","shadowclaw","xafetim manigiro"},ang={["class:Hunter"]="Derrubar moonstalkers exige manter os sentidos apurados contra predadores de emboscada que se camuflam naturalmente sob a copa escura da costa.",["race:Gnome"]="Os excêntricos dispositivos de comunicação remota de Xafetim Manigiro demonstram a clássica engenharia gnômica, mesmo que sua fala arrastada e suas escolhas bizarras de amostragem causem estranheza."},sec={{t="Um Mecanismo de Trituração",b="Os moonstalkers são felinos-de-sabre furtivos que assombram as orlas florestais de Costa Negra, espreitando presas entre os pinheiros sombrios. Suas presas alongadas servem como armas de caça formidáveis, capazes de dilacerar carne e osso. Para o excêntrico engenhoqueiro gnomo Xafetim Manigiro, no entanto, os dentes têm uma finalidade mecânica muito diferente. Posicionada ao norte de Auberdine, perto da ponte, sua engenhoca automatizada conhecida como Caixazorra 323 é calibrada especificamente para triturar essas presas resistentes até virarem pó, como parte de seus erráticos levantamentos ecológicos."}},faq={{q="De onde vêm os Moonstalker Fangs?",a="Eles são obtidos dos vários moonstalkers nativos de Costa Negra, incluindo moonstalker runts, adultos, sires, matriarcas e o esquivo predador conhecido como Shadowclaw.",al={"onde conseguir moonstalker fangs","quem saqueia moonstalker fangs","fonte de presas"}},{q="Quem quer Moonstalker Fangs?",a="O engenheiro gnomo Xafetim Manigiro precisa de seis dessas presas para alimentar a Caixazorra 323, um dispositivo de monitoramento automatizado localizado ao norte de Auberdine, perto da ponte do rio.",al={"quem precisa de presas","qual missao usa presas","entrega da caixazorra 323"}},{q="O que acontece com as presas dentro da máquina?",a="Ao serem colocadas na Caixazorra 323, engrenagens internas são ativadas e trituram imediatamente as presas duras em pó fino, fazendo avançar os experimentos de campo peculiares de Xafetim.",al={"o que a caixazorra 323 faz","por que triturar presas"}}},fx={fbcb9ad4={q="O que é uma Presa de Espreitaluna?",a="Uma Presa de Espreitaluna é um dente canino predador afiado retirado dos espreitalunas predadores que vagam pelas florestas enevoadas de Costa Negra. Esses gatos-sabres noturnos usam suas presas formidáveis para caçar presas da floresta, tornando-as troféus valiosos e materiais surpreendentemente duráveis para engenhocas locais peculiares.",al={"presa de espreitaluna","o que são presas de espreitaluna","dentes de espreitaluna"}}},fp="16,140,20.312.0,37.125.0,28.138.0,45.88.0"}
P.entries["item:moonwell-water-tube"] = {n="Tubo de Água do Poço Lunar",s="Um frasco cheio de água consagrada retirada do poço lunar em Auberdine. Sua potente e purificadora magia da natureza é usada para testar e reagir com um misterioso cristal vermelho incrustado ao longo das cristas orientais da Costa Negra.",h="Um frasco cheio de água consagrada retirada do poço lunar em Auberdine.",kw={"as water cascades","auberdine","costa negra","tubo de água vazio","selva maleva","tubo de água do poço lunar","cristal vermelho"},ang={["class:Druid"]="Os druidas reconhecem a água do poço lunar como um conduto vital do Balance of Nature, perfeitamente adequado para combater a corrupção não natural.",["race:NightElf"]="Usar as águas abençoadas de um poço lunar para investigar corrupção externa reflete a confiança dos kaldorei em Elune's Grace para revelar verdades ocultas."},sec={{t="Um Recipiente de Águas Purificadoras",b="Retirado diretamente do poço lunar reluzente situado em Auberdine, o Tubo de Água do Poço Lunar contém líquido impregnado com as energias abençoadas de Elune. Os poços lunares servem aos assentamentos de elfos noturnos como reservatórios sagrados de magia restauradora e pureza, tornando até mesmo um pequeno frasco notavelmente potente contra corrupção ou fenômenos místicos desconhecidos."},{t="Investigando o Red Crystal",b="O tubo foi preparado especificamente para testar um enorme e estranho cristal vermelho que surgiu junto aos penhascos orientais da Costa Negra. Como as alturas corrompidas de Selva Maleva se erguem diretamente acima da muralha de montanhas, os pesquisadores temiam que a formação carmesim compartilhasse uma origem sombria. Quando a água abençoada cascateia pelas facetas do cristal, a magia força a pedra opaca a ficar brevemente transparente, revelando os mistérios vibrantes trancados em seu interior."}},faq={{q="De onde a água é retirada?",a="A água é colhida diretamente do sagrado poço lunar localizado no refúgio de elfos noturnos de Auberdine, na costa ocidental da Costa Negra.",al={"onde encher o tubo","fonte do tubo de água","água do poço lunar de auberdine"}},{q="Por que usar água do poço lunar no cristal vermelho?",a="A água do poço lunar contém magia natural e lunar concentrada. Despejá-la sobre o bizarro cristal vermelho testa sua composição mística, desencadeando uma reação etérea que torna a superfície mineral opaca momentaneamente transparente.",al={"por que água do poço lunar","propósito do tubo de água","o que a água faz"}},{q="Por que os pesquisadores estão preocupados com o cristal?",a="O cristal repousa diretamente sob as montanhas orientais que fazem fronteira com Selva Maleva. Dada a profunda mácula demoníaca de Selva Maleva, os estudiosos temem que a estranha formação possa ser uma extensão dessa corrupção infiltrando-se na Costa Negra.",al={"por que testar o cristal","perigo do cristal vermelho","conexão com selva maleva"}}},fx={f51af5d3={q="O que é o Tubo de Água do Poço Lunar?",a="O Tubo de Água do Poço Lunar é um simples frasco de vidro cheio de água abençoada retirada diretamente do poço lunar em Auberdine. Poços Lunares contêm magia sagrada e potente cultivada por druidas e sacerdotisas elfos noturnos, tornando o líquido dentro dele muito mais do que água de nascente comum. Carregá-lo permite que pesquisadores levem uma pequena medida concentrada do poder purificador de Eluna para o campo para testar fenômenos desconhecidos.",al={"o que é o tubo de água do poço lunar","item tubo de água do poço lunar","o que é este tubo de água"}},["21e1d317"]={q="Por que o Tubo de Água do Poço Lunar é necessário?",a="Investigadores em Auberdine precisam do Tubo de Água do Poço Lunar para analisar um cristal vermelho ameaçador embutido ao longo das montanhas orientais de Costa Negra. Como suspeita-se que o cristal compartilhe uma conexão sombria com a Selva Maleva corrompida bem acima, os pesquisadores acreditam que derramar a magia pura e potente do poço lunar sobre sua superfície reagirá com segurança com a pedra e revelará sua composição interna.",al={"por que preciso do tubo de água do poço lunar","por que querer água do poço lunar","propósito do tubo de água do poço lunar"}}},fp="19,146,28.203.0,29.339.1,30.106.0,42.174.0,52.175.0"}
P.entries["item:mossy-tumor"] = {n="Tumor Musguento",s="Um tumor musguento é uma excrecência fétida e venenosa arrancada da casca e da carne de timberlings corrompidos em Teldrassil. Encontrados principalmente ao redor do Lago Olho-d'Água, esses crescimentos servem como sinais visíveis de uma malevolência desconcertante que se espalha pela recém-cultivada Árvore do Mundo.",h="Um tumor musguento é uma excrecência fétida e venenosa arrancada da casca e da carne de timberlings...",kw={"corrupção","darnassus","tumor musguento","rellian spiraverde","teldrassil","timberling","lago olho-d'água"},ang={["class:Druid"]="Para os druidas dedicados ao equilíbrio da natureza, ver guardiões vegetais como os timberlings brotando com tumores tóxicos é um sinal alarmante de que algo está profundamente errado com Teldrassil.",["race:NightElf"]="Os elfos noturnos plantaram Teldrassil para restaurar sua ligação perdida com a natureza, tornando o rápido surgimento de excrecências doentias em seu novo lar um presságio perturbador."},sec={{t="Um sintoma do mal-estar de Teldrassil",b="Os timberlings de Teldrassil foram criados para nutrir e cuidar dos ramos da grande árvore, mas muitos se tornaram hostis e doentes. Esses tumores musguentos são manifestações físicas dessa enfermidade interna. Fortemente carregadas de toxinas, essas protuberâncias brotam pelos corpos de Mire Beasts, Tramplers e Elder Timberlings que rondam o Lago Olho-d'Água. Rellian Spiraverde e os guardiões em Darnassus encarregaram viajantes de extirpar os tumores para que possam ser completamente queimados, impedindo que seu veneno crie raízes mais profundas no solo da ilha."}},faq={{q="O que é um Tumor Musguento?",a="É uma formação doentia colhida dos corpos de timberlings maculados. Repletos de veneno fétido, os tumores demonstram que os espíritos da natureza de Teldrassil estão sofrendo de uma corrupção não natural.",al={"tumor musguento","o que é este tumor","tumor de timberling"}},{q="Onde encontrar Tumores Musguentos?",a="Eles são obtidos de timberlings corrompidos — como Timberling Tramplers, Mire Beasts e Elder Timberlings — que vagam ao redor do Lago Olho-d'Água, no norte de Teldrassil.",al={"onde conseguir tumores","saque de tumor musguento","localização de timberlings"}},{q="Por que Rellian Spiraverde quer esses tumores?",a="Rellian busca conter a corrupção que assola Teldrassil. Ao coletar os tumores e reduzi-los a cinzas, ele garante que o veneno concentrado em seu interior não possa infiltrar-se novamente no solo e na água.",al={"tumores de rellian spiraverde","por que queimar tumores"}},{q="Por que os timberlings estão ficando doentes?",a="Uma malevolência sombria começou a se instalar por toda Teldrassil, deformando seus zeladores e criaturas selvagens. Enquanto os elfos noturnos investigam ativamente a verdadeira origem da enfermidade, os timberlings que exibem tumores visíveis são considerados além de qualquer salvação.",al={"por que os timberlings estão doentes","corrupção de timberling"}}},fp="11,189,33.427.0,22.149.0,31.164.0,46.184.0,42.220.0"}
P.entries["item:mountain-lion-blood"] = {n="Sangue de Leão da Montanha",s="Sangue de Leão da Montanha é um reagente coletado dos predadores à espreita no Contraforte de Eira dos Montes e nas encostas nevadas de Alterac. O Boticário Lindolfo da Serraria Tarren busca esse sangue fresco para formular o temido Elixir da dor da Real Sociedade de Boticários.",h="Sangue de Leão da Montanha é um reagente coletado dos predadores à espreita no Contraforte de Eira dos Montes...",kw={"alterac","boticário lindolfo","elixir da dor","eira dos montes","sangue de leão da montanha","real sociedade de boticários","serraria tarren"},ang={["faction:Horde"]="Coletar reagentes de feras nos arredores da Serraria Tarren fortalece diretamente a presença consolidada da Horda contra os enclaves humanos hostis em Eira dos Montes.",["race:Undead"]="Cada frasco coletado ajuda a Real Sociedade de Boticários a desenvolver armas biológicas devastadoras para assegurar Lordaeron para os Renegados."},sec={{t="Reagente dos Montes",b="As terras altas e os contrafortes que cercam Eira dos Montes e Alterac são rondados por leões da montanha ferozes e famintos. Enquanto caçadores comuns buscam esses predadores por suas peles e garras, os Renegados da Real Sociedade de Boticários encontram valor naquilo que corre em suas veias. O sangue fresco de leão da montanha possui propriedades biológicas específicas que o Boticário Lindolfo, na Serraria Tarren, acredita que servirão como base para uma nova e potente mistura tóxica criada para levar miséria aos vivos."},{t="Alimentando a Nova Praga",b="Os experimentos do Boticário Lindolfo na Serraria Tarren contribuem diretamente para a missão primordial da Real Sociedade de Boticários: aperfeiçoar a Nova Praga dos Renegados. Ao extrair o sangue de feras selvagens vigorosas, Lindolfo busca refinar uma beberagem que ele chama de Elixir da dor, testando a eficácia com que compostos orgânicos locais podem ser transformados em armas contra os inimigos da Dama Sombria."}},faq={{q="Para que serve o Sangue de Leão da Montanha?",a="O Boticário Lindolfo na Serraria Tarren precisa de dez frascos de Sangue de Leão da Montanha para destilar uma mistura letal conhecida como Elixir da dor, parte das pesquisas da Real Sociedade de Boticários sobre novas doenças.",al={"para que serve sangue de leao da montanha","quem precisa de sangue de leao","sangue elixir da dor"}},{q="Onde o Sangue de Leão da Montanha pode ser coletado?",a="Ele é obtido de leões da montanha que caçam pelo Contraforte de Eira dos Montes e até os penhascos nevados vizinhos das Montanhas de Alterac.",al={"onde encontrar sangue de leao da montanha","localizacao sangue de leao da montanha","quais leoes dropam sangue"}},{q="Por que o Boticário Lindolfo quer especificamente sangue de felinos selvagens?",a="Lindolfo acredita que os fluidos vitais dos agressivos e resistentes leões da montanha oferecem a base biológica ideal para a criação de uma mistura tóxica particularmente agonizante, voltada contra os habitantes vivos de Eira dos Montes.",al={"por que sangue de leao","por que lindolfo quer sangue de leao"}},{q="O Sangue de Leão da Montanha serve para receitas de criação de alquimia?",a="Não. Trata-se exclusivamente de um reagente de pesquisa experimental coletado para o trabalho pessoal do Boticário Lindolfo, não sendo um ingrediente na profissão de alquimia comum.",al={"alquimistas podem usar sangue de leao da montanha","sangue de leao serve para alquimia"}}},fx={dcf44a54={q="O que é Sangue de Leão da Montanha?",a="É sangue fresco colhido dos leões da montanha predadores que rondam as encostas escarpadas de Contraforte de Eira dos Montes e das Montanhas de Alterac. Embora inútil para alquimistas comuns ou comerciantes, possui qualidades biológicas valorizadas pela Real Sociedade de Boticários para seus experimentos alquímicos letais.",al={"o que é sangue de leão da montanha","tradição do sangue de leão da montanha","o que é este sangue"}},["7c379830"]={q="De onde vem o Sangue de Leão da Montanha e quem o fez?",a="Ele não é criado ou fabricado, mas retirado diretamente dos gatos selvagens indígenas do norte de Lordaeron. Os leões da montanha que vagam pelas terras altas entre Eira dos Montes e Alterac são caçados e sangrados por agentes que trabalham em nome dos boticários Renegados estacionados na Serraria Tarren.",al={"de onde vem o sangue de leão da montanha","fonte do sangue de leão da montanha","quem fez o sangue de leão da montanha"}}},fp="19,159,20.341.0,22.323.0,37.145.0,43.138.0,59.159.0,59.128.0"}
P.entries["item:muddy-journal-pages"] = {n="Páginas de Diário Enlameadas",s="Estas folhas desgastadas e manchadas de terra foram recuperadas da cena de um assassinato brutal anos atrás na Floresta do Crepúsculo. Preservadas por muito tempo pelo Taberneiro Oseias sem prova de autoria, elas permanecem uma peça fundamental de evidência em uma investigação local não resolvida.",h="Estas folhas desgastadas e manchadas de terra foram recuperadas da cena de um assassinato brutal anos atrás...",kw={"vila sombria","ebanez","haggard","lenda de stalvan","páginas de diário enlameadas","smitts","stalvan"},ang={["class:Rogue"]="Juntar amostras de caligrafia esquecidas e retalhos de diário desgastados demonstra o trabalho forense metódico necessário antes de eliminar um assassino oculto.",["faction:Alliance"]="Desvendar o mistério por trás do massacre dos nobres de Ventobravo traz um encerramento tardio para um caso antigo e não resolvido nos assentamentos sitiados da Floresta do Crepúsculo."},sec={{t="A Evidência do Massacre",b="Anos antes dos perigos atuais dominarem a Floresta do Crepúsculo, uma comitiva de nobres visitantes foi brutalmente massacrada na natureza. O Taberneiro Oseias acompanhou o investigador Haggard até a cena sangrenta e salvou estas Páginas de Diário Enlameadas da lama. Na época, a cidade não possuía amostras de caligrafia e registros corroborados necessários para vincular o texto diretamente a qualquer suspeito. Oseias reteve silenciosamente as páginas na taverna de Vila Sombria, esperando que um investigador descobrisse registros espalhados o suficiente pelos reinos do sul para associar a escrita ao recluso que vivia nas profundezas da floresta."}},faq={{q="Onde as páginas de diário enlameadas foram encontradas?",a="Elas foram descobertas pelo Taberneiro Oseias e Haggard vários anos atrás na cena onde uma família de nobres visitantes foi massacrada na floresta da Floresta do Crepúsculo.",al={"onde smitts encontrou as páginas","origem das páginas enlameadas","localização do diário enlameado"}},{q="Por que Oseias não pôde usar as páginas quando as encontrou pela primeira vez?",a="Embora as páginas tenham sido recuperadas da cena do crime, os investigadores locais não tinham como verificar a caligrafia. Sem amostras de escrita para comparar, a guarda da cidade não pôde vincular as páginas a nenhum suspeito.",al={"por que manter as páginas em segredo","por que smitts não as entregou","problema de evidência de smitts"}},{q="Quem precisa ver estas páginas?",a="Elas devem ser levadas diretamente à Comandante Aldora Ebanez, líder da The Night Watch em Vila Sombria, para relatar oficialmente a conclusão da investigação sobre o massacre dos nobres visitantes.",al={"a quem entrego as páginas enlameadas","entregar páginas de diário enlameadas","ebanez páginas enlameadas"}},{q="A que crime estas páginas estão conectadas?",a="Elas estão conectadas ao massacre de um grupo de nobres visitantes na floresta da Floresta do Crepúsculo vários anos atrás, um crime que Vila Sombria nunca pôde atribuir a ninguém na época.",al={"qual massacre","o que stalvan fez","nobres visitantes massacrados"}}},fx={["7e79311d"]={q="O que são as Páginas de Diário Enlameadas?",a="São folhas de diário sujas e rasgadas recuperadas anos atrás do local de um brutal massacre de nobres visitantes na Floresta do Crepúsculo. Escritas por Galvão Brumanto, elas documentam sua queda e fornecem a tão buscada prova escrita de sua presença e loucura na cena do massacre.",al={"o que são páginas de diário enlameadas","páginas de diário enlameadas","o que é este item"}},bcc5553e={q="De onde vêm as Páginas de Diário Enlameadas e quem as escreveu?",a="Elas foram escritas por Galvão Brumanto e deixadas na lama quando os nobres foram assassinados. O Taberneiro Oseias e Haggard as descobriram enquanto investigavam o banho de sangue, mas Oseias as manteve por anos porque lhe faltavam amostras de caligrafia para confirmar quem as tinha escrito.",al={"quem escreveu as páginas de diário enlameadas","de onde vieram as páginas enlameadas","autor das páginas de diário enlameadas"}},f7c3dc88={q="Por que a Comandante Aldora Ebanez precisa das Páginas de Diário Enlameadas?",a="A Comandante Aldora Ebanez supervisiona a defesa de Vila Sombria e requer prova definitiva antes de agir contra a ameaça na floresta. Combinadas com a evidência de caligrafia que você reuniu por todo o reino, essas páginas estabelecem a culpa de Galvão sem sombra de dúvida e instam a The Night Watch a finalmente lidar com ele.",al={"por que levar as páginas para ebanez","quem quer as páginas de diário enlameadas","por que as páginas enlameadas são importantes"}}},fp="30,305,24.661.1,57.177.0,81.235.0,32.203.1,45.196.0"}
P.entries["item:muddy-note"] = {n="Muddy Note",s="Uma nota enlameada e quase ilegível, encontrada entre os objetos de valor de um cofre. Os detalhes sobre as patrulhas do Recruta Turgo podem ajudar o Tenente Doren a descobrir um traidor no Acampamento dos Rebeldes.",h="Uma nota enlameada e quase ilegível, encontrada entre os objetos de valor de um cofre.",kw={"tenente doren","nota enlameada","recruta turgo","acampamento dos rebeldes","selva do espinhaço","cofre","traidor"},sec={{t="O Bilhete Rabiscado",b="As rotas de patrulha e os hábitos do Recruta Turgo estão registrados em uma nota enlameada encontrada em um cofre na Selva do Espinhaço. Ela também registra com quem ele conversa entre os rebeldes. A escrita é difícil de ler, mas o Tenente Doren precisa da nota para encontrar o traidor."}},faq={{q="O que diz a nota enlameada?",a="A nota registra as rotas de patrulha do Recruta Turgo, suas conversas e como ele passa o tempo com os rebeldes. A escrita está quase ilegível.",al={"o que diz a nota","detalhes da nota enlameada","nota do turgo"}},{q="Onde devo levar a nota?",a="Leve a nota enlameada ao Tenente Doren, no Acampamento dos Rebeldes.",al={"quem quer a nota","onde levá-la","nota do doren"}},{q="Quem escreveu a nota?",a="A nota está assinada apenas com a letra M. Ela não identifica o autor pelo nome.",al={"quem assinou","autor da nota","quem é m"}},{q="Por que a nota é importante?",a="A nota mostra que seu autor conhecia a rotina e os contatos do Recruta Turgo. O Tenente Doren precisa dela como pista para encontrar o traidor entre os rebeldes.",al={"por que doren precisa dela","pista sobre o traidor","para que serve a nota"}}},fp="10,172,18.252.0,29.145.0,25.54.0,19.85.0,26.152.0"}
P.entries["item:mudsnout-blossom"] = {n="Mudsnout Blossom",s="Os Cogumelos Fuçalama são formações fúngicas acres e tóxicas encontradas brotando no Sítio de Nethander, no Contraforte de Eira dos Montes. Protegidos por gnolls locais e colhidos pela Real Sociedade de Boticários, esses cogumelos fétidos são usados na pesquisa de elixires do Boticário Lindolfo.",h="Os Cogumelos Fuçalama são formações fúngicas acres e tóxicas encontradas brotando no Sítio de Nethander, no...",kw={"boticário lindolfo","elixir of agony","contraforte de eira dos montes","mudsnout blossom","gnolls fuçalama","sítio de nethander","serraria tarren"},ang={["profession:Herbalism"]="Embora botânicos e herboristas possam confundir seu nome com o de uma flor comum, o Mudsnout Blossom é, na verdade, um fungo volátil e malcheiroso, valorizado por toxicologistas e alquimistas sombrios.",["race:Undead"]="Os Renegados fazem amplo uso das propriedades tóxicas do cogumelo, colhendo-o para refinar armas bioquímicas para a Real Sociedade de Boticários."},sec={{t="Um Fungo Tóxico",b="Apesar de seu nome floral, os Cogumelos Fuçalama são, na verdade, grandes cogumelos malcheirosos que proliferam principalmente na terra suja do Sítio de Nethander, ao sul da Serraria Tarren. Eles crescem em meio aos acampamentos dos gnolls Fuçalama locais, que defendem o território ferozmente. Para organismos vivos, os esporos e a carne do cogumelo atuam como um veneno virulento, causando agonia e rápida deterioração biológica."},{t="Combustível para a Real Sociedade de Boticários",b="Na Serraria Tarren, o Boticário Lindolfo busca Cogumelos Fuçalama como matéria-prima para seus experimentos químicos. Sob o mandato da Grande Dama Sylvana Correventos, a Real Sociedade de Boticários trabalha incansavelmente para criar uma nova praga capaz de erradicar tanto o Flagelo quanto a humanidade viva. As propriedades cáusticas e atrofiadoras de carne desses cogumelos fazem deles um componente básico ideal para a infusão de Lindolfo, o infame Elixir of Agony."}},faq={{q="O que é um Mudsnout Blossom?",a="Apesar de ser chamado de flor, trata-se de um cogumelo grande, acre e tóxico encontrado no solo úmido do Contraforte de Eira dos Montes.",al={"história de mudsnout blossom","mudsnout blossom é uma flor","que tipo de planta é mudsnout blossom"}},{q="Onde os Cogumelos Fuçalama crescem?",a="Eles crescem por todo o Sítio de Nethander, uma propriedade rural abandonada ao sul da Serraria Tarren e a leste do rio que passa pela Costa Sul. A área é fortemente infestada por gnolls Fuçalama.",al={"localização de mudsnout blossom","onde encontrar cogumelos fuçalama","cogumelos do sítio de nethander"}},{q="Por que a Real Sociedade de Boticários os está coletando?",a="O Boticário Lindolfo, na Serraria Tarren, precisa deles para preparar o Elixir of Agony. Os Renegados estão pesquisando toxinas para ajudar na criação de uma nova praga capaz de exterminar tanto os vivos quanto o Flagelo.",al={"por que lindolfo quer cogumelos fuçalama","ingredientes de elixir of agony","cogumelo do boticário lindolfo"}},{q="Para que a Real Sociedade de Boticários usa os cogumelos?",a="O Boticário Lindolfo recolhe os cogumelos malcheirosos para o seu próximo elixir, como parte da pesquisa dos Renegados sobre doenças e venenos.",al={"experimentos com mudsnout blossom","uso de mudsnout blossom em elixir"}}},fx={f0998bd9={q="De onde vêm os Mudsnout Blossoms?",a="Os Mudsnout Blossoms são cogumelos grandes e de cheiro fétido que brotam nos campos do Sítio de Nethander, no sul de Contraforte de Eira dos Montes. Eles prosperam ao redor dos gnolls Fuçalama locais que habitam o local e guardam ferozmente o canteiro, embora não se saiba se os gnolls cultivam intencionalmente os fungos pungentes ou apenas fazem ninhos entre eles.",al={"origem do mudsnout blossom","de onde vieram os mudsnout blossoms","quem fez o mudsnout blossom"}}},fp="16,166,14.327.0,37.322.1,27.124.0,32.184.0,52.183.0,60.137.0"}
P.entries["item:mudsnout-composite"] = {n="Composto Fuçalama",s="O Composto Fuçalama é uma pasta alquímica preparada pelo Boticário Lindolfo na Serraria Tarren a partir de Cogumelos Fuçalama colhidos. Ele serve como um ingrediente-base essencial levado até Cidade Baixa para as pesquisas da Real Sociedade de Boticários sobre uma nova peste.",h="O Composto Fuçalama é uma pasta alquímica preparada pelo Boticário Lindolfo na Serraria Tarren a partir de...",kw={"boticarium","boticário lindolfo","o elixir da agonia","mestre-boticário faranello","mudsnout blossom","composto fuçalama","real sociedade de boticários"},ang={["profession:Herbalism"]="Os Cogumelos Fuçalama provam que até mesmo a humilde flora nativa pode ser esmagada e transformada em arma sob o olhar experiente de um boticário.",["race:Undead"]="Cada remessa como este composto contribui diretamente para a ordem da Dama Sombria: assegurar o futuro dos Renegados desenvolvendo uma peste para destruir tanto os vivos quanto o Flagelo."},sec={{t="Uma base para a decomposição",b="Criado em campo pelo Boticário Lindolfo, este fino composto é derivado diretamente de Cogumelos Fuçalama colhidos no Contraforte de Eira dos Montes. Embora nociva por si só, a pasta requer um colóide de decomposição especializado — preparado pelo próprio Mestre-boticário Faranello — para ativar suas qualidades mais letais. Uma vez combinada, a mistura forma um componente químico fundamental no desenvolvimento do Elixir da Agonia da Dama Sombria."},{t="Correspondência de boticários",b="O transporte do composto da Serraria Tarren para o Boticarium de Cidade Baixa reflete a natureza descentralizada e iterativa da alquimia dos Renegados. Pesquisadores de campo colhem constantemente reagentes regionais e enviam amostras de volta para os mestres da capital realizarem o refinamento. Apesar das grandes exigências de Lady Sylvana para apressar os resultados tanto contra humanos vivos quanto contra o Flagelo, Faranello elogia o composto como uma base engenhosa em direção ao objetivo principal deles."}},faq={{q="Para que serve o Composto Fuçalama?",a="É uma pasta intermediária criada a partir de Cogumelos Fuçalama. Ela foi feita para ser tratada com um colóide de decomposição pelo Mestre-boticário Faranello em Cidade Baixa, ajudando a formular o Elixir da Agonia.",al={"para que serve o composto fuçalama","o que faz o composto fuçalama"}},{q="Quem criou o composto?",a="O Boticário Lindolfo, um pesquisador dos Renegados instalado na Serraria Tarren, no Contraforte de Eira dos Montes, esmagou cogumelos frescos para misturar a pasta antes de enviá-la para o norte.",al={"quem fez o composto fuçalama","criador do composto fuçalama"}},{q="Por que o Mestre-boticário Faranello precisa dele?",a="Faranello supervisiona o grande trabalho da Real Sociedade de Boticários na criação de uma nova peste. O composto de Lindolfo fornece a base vegetal específica necessária para avançar as pesquisas deles em toxinas letais.",al={"por que levar para faranello","faranello fuçalama"}}},fx={["432a2438"]={q="O que é Composto Fuçalama?",a="Composto Fuçalama é uma mistura refinada preparada pelo Boticário Lindolfo na Serraria Tarren. Criada moendo os raros Mudsnout Blossoms encontrados em Contraforte de Eira dos Montes, esta substância potente serve como uma base alquímica essencial na pesquisa da Real Sociedade de Boticários para projetar uma nova praga devastadora para os Renegados.",al={"composto fuçalama","o que é composto fuçalama","mistura fuçalama"}}},fp="18,193,16.326.0,25.385.1,40.176.0,26.148.0,44.174.0"}
P.entries["item:mudsnout-mixture"] = {n="Mistura Fuçalama",s="A Mistura Fuçalama é uma base alquímica tóxica criada pelo Mestre-boticário Faranello na Cidade Baixa. Produzida pela combinação de um composto fuçalama com um coloide alquímico de decomposição, ela serve como a base para o letal O elixir da agonia da Real Sociedade de Boticários.",h="A Mistura Fuçalama é uma base alquímica tóxica criada pelo Mestre-boticário Faranello na Cidade Baixa.",kw={"boticário","coloide de decomposição","o elixir da agonia","faranello","eira dos montes","lindolfo","mistura fuçalama","cidade baixa"},ang={["faction:Horde"]="Aventureiros da Horda que operam na Serraria Tarren atuam como mensageiros e agentes de campo, transportando concoctos tóxicos por Lordaeron para assegurar o domínio dos Renegados em Eira dos Montes.",["race:Undead"]="A mistura demonstra a engenhosidade impiedosa da Real Sociedade de Boticários, refinando ingredientes selvagens brutos em armas químicas projetadas para eliminar os vivos."},sec={{t="Um Coloide de Decomposição",b="Quando o Boticário Lindolfo na Serraria Tarren busca criar uma nova e virulenta arma biológica, ele envia para o norte até a Cidade Baixa um composto base de Cogumelos Fuçalama, cogumelos tóxicos do Sítio de Nethander dominado pelos gnolls. Impressionado com o potencial do composto, o Mestre-boticário Faranello adiciona seu próprio coloide de decomposição à mistura, gerando a volátil Mistura Fuçalama. A solução estabiliza o preparado de cogumelos enquanto prepara suas propriedades virulentas para um refinamento catalítico adicional de volta às colinas."},{t="Catalisando a Agonia",b="Embora potente por si só, a Mistura Fuçalama permanece inerte sem catalisadores essenciais para ativar seus agentes contaminantes. Faranello encarrega mensageiros de levarem o frasco de volta à Serraria Tarren junto com um Elixir de Sangue de Troll Forte, escamas venenosas de naga Daggerspine e olhos de murloc Torn Fin. Uma vez catalisada por Lindolfo, essa mistura forma o letal O elixir da agonia — um veneno característico destinado a espalhar a ruína entre os inimigos vivos dos Renegados."}},faq={{q="Para que serve a Mistura Fuçalama?",a="Ela serve como base química intermediária para O elixir da agonia, um veneno experimental que está sendo aperfeiçoado pelo Boticário Lindolfo na Serraria Tarren para exterminar os inimigos dos Renegados.",al={"objetivo da mistura fuçalama","o que faz a mistura fuçalama","uso da mistura fuçalama"}},{q="Quem cria a Mistura Fuçalama?",a="O Mestre-boticário Faranello, líder da Real Sociedade de Boticários residente no Boticarium da Cidade Baixa, cria a mistura infundindo um composto fuçalama bruto com seu próprio coloide de decomposição.",al={"quem faz a mistura fuçalama","criador da mistura fuçalama"}},{q="Por que ela requer componentes de gnoll?",a="Ela não requer, apesar do nome. O composto é feito de Cogumelos Fuçalama, cogumelos tóxicos que crescem no Sítio de Nethander entre os gnolls Fuçalama; o Boticário Lindolfo os mistura em um composto antes de Faranello adicionar seu coloide de decomposição.",al={"por que fuçalama","história do veneno dos gnolls"}},{q="Como a mistura é ativada?",a="Para despertar os agentes contaminantes dormentes na mistura, o Boticário Lindolfo necessita de um Elixir de Sangue de Troll Forte, juntamente com escamas de naga Daggerspine e olhos de murloc Torn Fin colhidos na costa de Eira dos Montes.",al={"ativar mistura fuçalama","reagentes do elixir da agonia"}}},fx={f656f7cb={q="O que é Mistura Fuçalama?",a="É uma mistura alquímica experimental formulada pela Real Sociedade de Boticários. Construída em torno de um composto de Mudsnout Blossoms, cogumelos tóxicos do Sítio de Nethander, a mistura incorpora o próprio coloide de decomposição do Mestre-boticário Faranello para servir como uma base volátil para a pesquisa da praga dos boticários.",al={"o que é mistura fuçalama","mistura fuçalama","composto fuçalama"}},ac01c76e={q="Por que o Boticário Lindolfo quer Mistura Fuçalama?",a="O Boticário Lindolfo na Serraria Tarren precisa dela para sintetizar o Elixir of Agony, uma mistura experimental destinada a espalhar doenças e morte aos inimigos dos Renegados. Ao ativar seus agentes contaminantes com sangue de troll e reagentes costeiros, ele pretende avançar na pesquisa da praga da Real Sociedade de Boticários.",al={"por que a mistura fuçalama é necessária","por que lindolfo quer mistura fuçalama","para que serve a mistura fuçalama"}}},fp="16,147,18.462.0,20.418.1,38.170.0,33.127.0,37.241.0,29.181.0"}
P.entries["item:murloc-head"] = {n="Cabeça de Murloc",s="Cabeças de Murloc são troféus macabros decepados das criaturas anfíbias que rondam a Praia Ocidental no Contraforte de Eira dos Montes. O Tenente Fárrio Orinelle da Costa Sul exige-as como prova física da eliminação de ameaças para satisfazer seu superior, o Delegado Trilharrubra.",h="Cabeças de Murloc são troféus macabros decepados das criaturas anfíbias que rondam a Praia Ocidental no...",kw={"tenente fárrio orinelle","farren's proof","contraforte de eira dos montes","delegado trilharrubra","murloc","cabeça de murloc","costa sul","praia ocidental"},ang={["faction:Alliance"]="Limpar a Praia Ocidental protege a frágil economia pesqueira da Costa Sul e assegura a costa para um reduto vulnerável da Aliança em Lordaeron."},sec={{t="Um Tipo de Prova Mais Macabro",b="A Costa Sul enfrenta perigos de todas as direções, mas os murlocs agressivos que se reúnem ao longo da Praia Ocidental são uma ameaça imediata aos pescadores locais e viajantes costeiros. Embora aventureiros da Aliança frequentemente vasculhem as praias para eliminar as criaturas, o Delegado Marcus Redpath exige verificação inegável antes de aprovar relatórios defensivos. Para satisfazer a burocracia, o Tenente Fárrio Orinelle depende de combatentes contratados para trazer cabeças de murloc frias e pingando—uma tarefa desagradável que Fárrio, ele próprio, considera totalmente repulsiva, especialmente por causa de como a visão acabou completamente com seu apetite pelos frutos do mar locais da Costa Sul."}},faq={{q="Por que Fárrio Orinelle quer cabeças de murloc?",a="O Delegado Marcus Redpath não ficou satisfeito com simples relatórios de murlocs sendo eliminados das praias. Para verificar se a ameaça foi genuinamente reduzida, ele exigiu evidências físicas, forçando o Tenente Fárrio a coletar cabeças decepadas como prova.",al={"prova de fárrio","por que cabeças de murloc","quem quer cabeças de murloc na costa sul"}},{q="Onde esses murlocs são encontrados?",a="Eles são reunidos das tribos de murlocs que infestam a Praia Ocidental, a costa que se estende a oeste da Costa Sul no Contraforte de Eira dos Montes.",al={"localização de cabeça de murloc","onde conseguir cabeças de murloc eira dos montes","murlocs da praia ocidental"}},{q="Por que Fárrio sente tanto nojo deles?",a="Fárrio acha peixes que andam inerentemente não naturais e revoltantes. A visão de cabeças decepadas, viscosas e sangrentas pingando no chão o enoja tanto que ele se recusa a comer peixe, que é um alimento básico importante em uma cidade portuária como a Costa Sul.",al={"reação de fárrio","fárrio comendo peixe"}},{q="Coletar as cabeças resolve o problema de murlocs da Costa Sul?",a="As cabeças fornecem a prova que o Delegado Trilharrubra solicitou. Ele aceita a entrega e então direciona Fárrio a voltar sua atenção para as ameaças na Praia Oriental.",al={"os murlocs param de atacar","cadeia de missões de fárrio"}}},fx={ab7abae9={q="O que é uma Cabeça de Murloc?",a="É o crânio recém-cortado de um murloc morto ao longo da costa de Contraforte de Eira dos Montes. Fria, viscosa e escorrendo fluidos fétidos, serve como prova física inegável de uma besta abatida na defesa de Costa Sul.",al={"o que é cabeça de murloc","informações da cabeça de murloc","item cabeça de murloc"}},["598cfa24"]={q="De onde vêm as Cabeças de Murloc?",a="Elas são cortadas diretamente dos corpos dos murlocs que rondam a Praia Ocidental, logo a oeste de Costa Sul. Mais do que bens criados, são troféus macabros tirados dos invasores da costa que incomodam a guarnição da Aliança.",al={"onde as cabeças de murloc caem","quem fez a cabeça de murloc","fonte da cabeça de murloc"}}},fp="11,228,24.399.0,43.164.0,30.100.0,35.155.0,60.131.0"}
P.entries["item:musquash-root"] = {n="Raiz Almiscarada",s="A Raiz Almiscarada é um espécime botânico raro encontrado apenas no solo úmido sob as enormes quedas d'água do Dique Lapidado, nos Pantanal. Ela serve como um componente vital em uma mistura preparada por cultistas escondidos sob Ventobravo.",h="A Raiz Almiscarada é um espécime botânico raro encontrado apenas no solo úmido sob as enormes quedas d'água...",kw={"uma bebida para poucos","lord wishock","raiz almiscarada","dique lapidado","lágrima de tirsa","pantanal","malvino"},ang={["class:Warlock"]="Para bruxos operando sob a The Slaughtered Lamb, obter esta raiz é essencial para silenciar nobres curiosos e proteger seu frágil santuário dentro da cidade.",["profession:Herbalism"]="Embora não seja uma erva de comércio padrão, a raiz demonstra como microclimas específicos, como a base do Dique Lapidado, podem nutrir flora única e perigosa."},sec={{t="Um Ingrediente Raro",b="A Raiz Almiscarada prospera no solo perpetuamente encharcado de névoa onde a cascata do Dique Lapidado deságua nos Pantanal. Seu habitat isolado e úmido a torna extremamente difícil de colher. Embora herboristas comuns raramente a procurem, certos praticantes das artes sombrias valorizam a raiz por suas potentes propriedades químicas e alquímicas."},{t="O Esquema do Bruxo",b="Sob as ruas de Ventobravo, nas entranhas sombrias conhecidas como The Slaughtered Lamb, Malvino da Garra Preta busca esta raiz junto com a Lágrima de Tirsa. Juntas, essas raras flores formam a base de uma poção sutil projetada para neutralizar Lord Wishock, um membro da House of Nobles que começou a enfiar o nariz no coven secreto de bruxos da cidade."}},faq={{q="Onde encontrar a Raiz Almiscarada?",a="A Raiz Almiscarada cresce exclusivamente nos Pantanal, repousando exatamente no pé das grandes quedas d'água sob o Dique Lapidado.",al={"onde fica a raiz almiscarada","localização da raiz almiscarada","como encontrar a raiz almiscarada"}},{q="Para que serve a Raiz Almiscarada?",a="Malvino da Garra Preta a solicita junto com a Lágrima de Tirsa para uma poção destinada a manter Lord Wishock ocupado e interromper seu ímpeto por uma investigação sobre o coven de bruxos de Ventobravo.",al={"o que a raiz almiscarada faz","propósito da raiz almiscarada","por que preciso da raiz almiscarada"}},{q="Quem quer que esta raiz seja colhida?",a="Malvino da Garra Preta, um bruxo residente nas catacumbas abaixo da The Slaughtered Lamb no Bairro dos Magos de Ventobravo, direciona agentes para recuperá-la.",al={"quem precisa da raiz almiscarada","quem dá a missão da raiz almiscarada","quem pede a raiz almiscarada"}},{q="Quem é Lord Wishock?",a="Lord Wishock é um membro da House of Nobles de Ventobravo que descobriu sobre o coven de bruxos operando dentro da cidade e começou a pressionar o conselho por uma investigação formal.",al={"quem é wishock","lord wishock"}}},fx={["32cf7ee1"]={q="O que é a Raiz Almiscarada?",a="A Raiz Almiscarada é um espécime botânico raro que cresce especificamente na névoa úmida na base da cachoeira abaixo do Dique Lapidado no Pantanal. Conhecida entre boticários sombrios e bruxos por suas potentes propriedades naturais, ela serve como um reagente crucial no preparo de poções enganosas e venenos quando combinada com outras floras raras.",al={"o que é a raiz almiscarada","história da raiz almiscarada","informações sobre a raiz almiscarada"}},d9341dd1={q="De onde vem a Raiz Almiscarada e quem a criou?",a="A Raiz Almiscarada é uma planta de ocorrência natural, e não uma criação artificial. Ela floresce exclusivamente no Pantanal, enraizada na pedra molhada e no solo saturado ao pé das quedas d'água logo abaixo do grande Dique Lapidado.",al={"origem da raiz almiscarada","onde a raiz almiscarada cresce","quem criou a raiz almiscarada"}}},fp="13,142,17.226.0,20.283.1,29.90.0,31.201.0,30.158.0,20.160.0"}
P.entries["item:mysterious-artifact-searing-gorge"] = {n="Artefato Misterioso",s="O Artefato Misterioso é uma relíquia guardada pelos Twilight's Hammer na Garganta Abrasadora. Ela é procurada para o Altar of Suntara, no Fosso de Lava.",h="O Artefato Misterioso é uma relíquia guardada pelos Twilight's Hammer na Garganta Abrasadora.",kw={"altar of suntara","idolaters","artefato misterioso","garganta abrasadora","fosso de lava","artefato twilight","twilight's hammer"},sec={{t="Uma Relíquia nas Colinas",b="Acima de uma caverna nas colinas a noroeste da Garganta Abrasadora, os Twilight's Hammer Idolaters guardam o Artefato Misterioso. O Altar of Suntara espera vazio no Fosso de Lava. O arqueólogo moribundo pede que você leve a relíquia até lá e a coloque sobre o altar."}},faq={{q="Onde está o Artefato Misterioso?",a="Os Twilight's Hammer Idolaters guardam o Artefato Misterioso nas colinas a noroeste da Garganta Abrasadora, acima de uma caverna.",al={"local do artefato","onde fica a relíquia"}},{q="Quem guarda o artefato?",a="Os Twilight's Hammer Idolaters guardam o Artefato Misterioso nas colinas da Garganta Abrasadora.",al={"quem está com ele","relíquia dos twilight hammer"}},{q="Para onde ele deve ser levado?",a="O Artefato Misterioso deve ficar no Altar of Suntara, no Fosso de Lava.",al={"local do altar","para onde levar o artefato"}},{q="Por que procuram o artefato?",a="O arqueólogo moribundo pede que você recupere a relíquia e a coloque no Altar of Suntara.",al={"para que serve","por que procurar a relíquia"}}},fp="19,136,20.247.0,33.112.0,24.88.0,25.72.0,27.92.0"}
P.entries["item:mysterious-fossil"] = {n="Fóssil Misterioso",s="O Fóssil Misterioso é um espécime antigo desenterrado ao longo da costa de Costa Negra pelo Prospector Trilheiro. Suas características peculiares despertaram a intensa curiosidade da Liga dos Exploradores dos anões, levando estudiosos a transportá-lo através do mar para desvendar seus segredos ocultos.",h="O Fóssil Misterioso é um espécime antigo desenterrado ao longo da costa de Costa Negra pelo Prospector...",kw={"costa negra","liga dos exploradores","pançacheia","suiçagris","porto de menethil","fóssil misterioso","trilheiro"},ang={["faction:Alliance"]="A transferência da relíquia destaca a vital cadeia logística que une os postos avançados da Aliança, conectando batedores em Costa Negra a estudiosos em Darnassus e no Porto de Menethil.",["race:Dwarf"]="Para os anões, este fóssil representa outra peça que faltava na busca contínua da Liga dos Exploradores para remontar a antiga herança dos titãs e desenterrar mistérios esquecidos."},sec={{t="Uma Descoberta Curiosa",b="Enquanto realizava trabalho de campo pelas praias selvagens de Costa Negra, o Prospector Trilheiro descobriu um fóssil diferente das pedras petrificadas comuns espalhadas por Kalimdor. Julgando-o de monumental importância histórica, Trilheiro providenciou para que o espécime fosse entregue a estudiosos anões em vez de deixá-lo abandonado na natureza. Ao ser levada diante do Arqueólogo-chefe Suiçagris em Darnassus, a relíquia destacou-se imediatamente como um achado extraordinário."},{t="Laços Através do Oceano",b="O Arqueólogo-chefe Suiçagris observou que o espécime guardava uma semelhança impressionante com outro fóssil raro exibido certa vez em uma reunião da Liga dos Exploradores em Altaforja. Essa peça anterior havia sido estudada pelo Arqueólogo Pançacheia, que suspeitava que a pedra possuía um poder latente à espera de ser despertado. Para confirmar suas origens e desvendar seus potenciais segredos, Suiçagris ordenou que mensageiros levassem o fóssil através do oceano até Pançacheia, que aguarda transporte na Taberna Aguafunda, no Porto de Menethil."}},faq={{q="Onde o Fóssil Misterioso foi encontrado?",a="O fóssil foi descoberto em Costa Negra pelo Prospector Trilheiro durante seu trabalho de campo ao longo do antigo litoral norte de Kalimdor.",al={"localização do fóssil","onde é encontrado","origem do fóssil"}},{q="Por que a Liga dos Exploradores quer este fóssil?",a="A Liga dos Exploradores dedica-se ao estudo de artefatos antigos e das origens do mundo. O Arqueólogo-chefe Suiçagris acredita que este espécime está ligado a pesquisas apresentadas pelo Arqueólogo Pançacheia, que teorizou que tais fósseis poderiam conter um poder que pode ser desbloqueado.",al={"por que os anões o querem","interesse da liga dos exploradores","o que o fóssil faz"}},{q="Quem é o Arqueólogo Pançacheia?",a="O Arqueólogo Pançacheia é um pesquisador da Liga dos Exploradores. Conhecido por estudar relíquias petrificadas semelhantes, ele está atualmente hospedado na Taberna Aguafunda, no Porto de Menethil, enquanto aguarda escolta para o Whelgar Excavation Site em Pantanal.",al={"quem é pançacheia","localização de pançacheia","onde fica pançacheia"}},{q="Quem é o Arqueólogo-chefe Suiçagris?",a="O Arqueólogo-chefe Suiçagris é o representante sênior da Liga dos Exploradores estabelecido em Darnassus, supervisionando pesquisas anãs e esforços arqueológicos por todo o norte de Kalimdor.",al={"suiçagris","quem é suiçagris","arqueólogo anão de darnassus"}}},fx={dc519f37={q="O que é o Fóssil Misterioso?",a="O Fóssil Misterioso é uma relíquia antiga desenterrada na natureza de Costa Negra pelo anão Prospector Trilheiro. Diferente de restos petrificados mundanos, este espécime tem uma semelhança notável com um artefato extraordinário anteriormente exibido à Liga dos Expedicionários em Altaforja. Sua natureza peculiar sugere que ele guarda segredos latentes ou um poder à espera de ser desbloqueado por um arqueólogo experiente.",al={"lore do fóssil misterioso","o que é este fóssil","info do fóssil misterioso"}}},fp="17,134,19.267.0,21.388.1,38.104.0,48.171.0,31.232.0,39.182.0"}
P.entries["item:mysterious-relic"] = {n="Relíquia Misteriosa",s="A Relíquia Misteriosa é um artefato desconhecido encontrado numa escavação naga na Ilha do Medo. O Domínio de Plumaluna quer estudá-la para descobrir o que é.",h="A Relíquia Misteriosa é um artefato desconhecido encontrado numa escavação naga na Ilha do Medo.",kw={"domínio de plumaluna","ilha do medo","latrônicus lunalança","lorde shalzaru","relíquia misteriosa","escavação naga","relíquia","véstia lançaluna"},sec={{t="Uma descoberta estranha",b="Batedores rastrearam a escavação de Lorde Shalzaru até uma caverna ao sul das ruínas principais na Ilha do Medo. O lorde naga encontrou ali a Relíquia Misteriosa, e Latrônicus Lunalança pediu que a levassem ao Domínio de Plumaluna para estudo.\n\nLatrônicus pouco conseguiu descobrir sobre o artefato, então o enviou à esposa, Véstia Lançaluna, sacerdotisa e estudiosa. Ela percebeu que ele era diferente dos objetos comuns das ruínas e também não era obra dos naga. Sua natureza continua incerta enquanto ela o estuda."}},faq={{q="Onde a Relíquia Misteriosa foi encontrada?",a="Lorde Shalzaru encontrou a Relíquia Misteriosa numa caverna de escavação naga ao sul das ruínas principais na Ilha do Medo.",al={"localização da relíquia","onde está a relíquia","relíquia da ilha do medo"}},{q="Quem quer a relíquia?",a="Latrônicus Lunalança pediu que levassem a Relíquia Misteriosa ao Domínio de Plumaluna para que fosse estudada.",al={"quem precisa da relíquia","relíquia de latrônicus","relíquia para quem"}},{q="Quem estuda a Relíquia Misteriosa?",a="Véstia Lançaluna, esposa de Latrônicus e sacerdotisa e estudiosa, estuda a Relíquia Misteriosa.",al={"véstia lançaluna","quem estuda a relíquia","estudiosa da relíquia"}},{q="O que é a Relíquia Misteriosa?",a="Véstia diz que a Relíquia Misteriosa é diferente dos objetos das Ruínas de Solarsal e não foi criada pelos naga. Ela precisa de tempo para estudá-la.",al={"o que é a relíquia","artefato estranho","significado da relíquia"}},{q="Os naga criaram a relíquia?",a="Véstia diz que a Relíquia Misteriosa não foi criada pelos naga, mas seu criador continua desconhecido.",al={"relíquia naga","foi criada pelos naga","quem criou a relíquia"}}},fp="16,158,14.461.0,37.116.0,20.115.0,33.96.0,29.134.0,28.89.0"}
P.entries["item:nak-s-skull"] = {n="Crânio de Nak",s="O Crânio de Nak é um macabro troféu de caça arrancado de Nak, um dos três proeminentes comandantes javatuscos Razormane que lideravam bandos de guerra nos Sertões Meridionais. Coletado como prova da derrota do saqueador, ele é procurado pelo javatusco cativo Denterroto para vingar uma amarga traição tribal.",h="O Crânio de Nak é um macabro troféu de caça arrancado de Nak, um dos três proeminentes comandantes javatuscos...",kw={"sertoes","betrayal from within","acampamento taurajo","kuz","lok orcbane","denterroto","nak","crânio de nak","quilboar","razormane"},ang={["faction:Horde"]="Arrancar a cabeça de senhores da guerra Razormane como Nak alivia a imensa pressão sobre as rotas de suprimentos da Horda que conectam o Acampamento Taurajo e a Encruzilhada."},sec={{t="Um Símbolo de Vingança",b="Surgindo do Urzal dos Tuscos, o trio formado por Nak, Kuz e Lok Orcbane desferiu ataques violentos contra povoados e estradas da Horda por todos os Sertões. Sem que os defensores da Encruzilhada soubessem, esses senhores da guerra arquitetavam ofensivas muito mais astutas do que as costumeiras escaramuças tribais. Quando o prisioneiro Razormane Denterroto foi abandonado para morrer em uma jaula no Acampamento Taurajo, sua sede de retaliação voltou-se contra seus antigos irmãos. Exigindo uma prova física da morte de Nak, Denterroto pede aos aventureiros da Horda que entreguem o crânio decepado junto aos de seus comparsas para quebrar a espinha dorsal dos grupos de saque do sul."}},faq={{q="Quem foi Nak?",a="Nak era um astuto líder javatusco Razormane que emergiu do Urzal dos Tuscos ao lado de Kuz e Lok Orcbane. Juntos, os três comandaram escaramuças e ataques letais contra viajantes e povoados da Horda por todos os Sertões Meridionais.",al={"quem e nak","historia de nak","nak sertoes"}},{q="Quem deseja o Crânio de Nak?",a="O crânio é exigido por Denterroto, um javatusco Razormane mantido cativo em uma jaula de madeira no Acampamento Taurajo. Amargurado por ter sido abandonado à própria sorte por sua própria gente, Denterroto busca vingança sangrenta contra os líderes que o traíram.",al={"quem quer o cranio","a quem entregar o cranio de nak","cranio denterroto"}},{q="Por que Denterroto quer os crânios de seu próprio povo?",a="Nak, Kuz e Lok Orcbane deram as costas a Denterroto e o abandonaram para morrer no cativeiro. Em retaliação à traição, Denterroto ajuda a Horda revelando o paradeiro deles e exigindo suas cabeças decepadas como prova de sua destruição.",al={"por que trair a propria tribo","motivo de denterroto","por que denterroto quer cranios"}},{q="Coletar o Crânio de Nak ajuda a proteger a Encruzilhada?",a="Sim. De acordo com Denterroto, Nak e seus parceiros eram as mentes astutas por trás dos agressivos ataques Razormane que pressionavam a Encruzilhada e as rotas comerciais centrais. Eliminá-los desfere um golpe devastador na capacidade de guerra coordenada da tribo.",al={"a encruzilhada segura","deter ataques de javatuscos"}}},fx={["96a0c2b0"]={q="De onde vem o Crânio de Nak?",a="O crânio é retirado diretamente dos restos mortais de Nak, um importante javatusco Razormane que saiu do Urzal dos Tuscos. Nak e seus irmãos viajaram até os confins do sul dos Sertões para coordenar ataques implacáveis contra acampamentos da Horda. Quando você caça Nak entre os espinheiros do sul e o derrota, seu crânio decepado serve como prova incontestável de que esse perigoso saqueador javatusco foi eliminado.",al={"origem do crânio de nak","de onde vem o crânio de nak","quem tem o crânio de nak"}}},fp="11,169,20.535.0,12.191.0,22.158.0,55.148.0,56.172.0"}
P.entries["item:nek-rosh-s-head"] = {n="Cabeça do Nek'rosh",s="A Cabeça do Nek'rosh é a prova macabra da queda do Chefe Nek'rosh, líder do clã Dragonmaw em Pantanal. Obtido por aventureiros da Aliança, este troféu é entregue ao Capitão Punhoforte para confirmar que a ameaça orca que pairava sobre o Porto de Menethil foi destruída.",h="A Cabeça do Nek'rosh é a prova macabra da queda do Chefe Nek'rosh, líder do clã Dragonmaw em Pantanal.",kw={"capitão punhoforte","chefe","dragonmaw","menethil","nek'rosh","nekrosh","pantanal"},ang={["faction:Alliance"]="Apresentar este troféu sombrio ao Capitão Punhoforte protege o Porto de Menethil de um ataque iminente e concede grande prestígio junto ao Reino de Altaforja.",["race:Dwarf"]="Os Dragonmaw assolam Khaz Modan desde a Segunda Guerra; carregar a cabeça decepada do chefe traz uma justiça há muito aguardada aos defensores dos pântanos."},sec={{t="Um Golpe Decisivo",b="O clã Dragonmaw representa um perigo constante por todos os pântanos, reunindo forças e armas de cerco contra o porto da Aliança no Porto de Menethil. Após queimar suas catapultas, a defesa do porto depende da eliminação do próprio Chefe Nek'rosh. Cortar sua cabeça fornece uma prova irrefutável ao Capitão Punhoforte e às autoridades de Altaforja de que o domínio do senhor da guerra sobre Pantanal foi quebrado."}},faq={{q="Quem foi Nek'rosh?",a="Nek'rosh era o chefe que comandava os remanescentes do clã Dragonmaw atuando em Pantanal, orquestrando ataques e esforços de guerra voltados contra os territórios vizinhos da Aliança.",al={"quem é nek'rosh","chefe nek'rosh","quem foi nekrosh"}},{q="Quem quer a Cabeça do Nek'rosh?",a="O Capitão Punhoforte, o comandante responsável pela defesa do Porto de Menethil, exige a cabeça como prova física de que o chefe caiu antes de recompensar o campeão em nome de Altaforja.",al={"quem recebe a cabeça","onde entregar cabeça de nekrosh","onde levar a cabeça do nek'rosh"}},{q="Por que Nek'rosh foi marcado para morrer?",a="Nek'rosh liderava as forças Dragonmaw que ameaçavam o Porto de Menethil. Ao destruir suas armas de cerco e eliminar seu chefe, a Aliança pretendia desferir um golpe devastador na presença do clã na região.",al={"por que matar nekrosh","por que derrotar nek'rosh"}}},fx={e464fcda={q="O que é a Cabeça do Nek'rosh?",a="É a cabeça decepada do Chefe Nek'rosh, o senhor da guerra que comanda o clã Presa do Dragão no Pantanal. Ela serve como prova macabra e inegável de que o maior inimigo local dos Montanheses de Altaforja finalmente foi morto.",al={"o que é a cabeça do nek'rosh","item cabeça do nek'rosh","cabeça decepada do nek'rosh"}},["160e4c8d"]={q="De onde vem a Cabeça do Nek'rosh e quem a fez?",a="Ela é tirada diretamente do Chefe Nek'rosh depois que você o derrota no acampamento Presa do Dragão no Pantanal. Ela não foi criada ou fabricada, mas sim decepada do chefe orc caído como um troféu e confirmação de sua morte.",al={"de onde vem a cabeça do nek'rosh","como obter a cabeça do nek'rosh","origem da cabeça do nek'rosh"}},ce210494={q="Por que o Capitão Punhoforte quer a Cabeça do Nek'rosh?",a="O Capitão Punhoforte precisa de uma prova indiscutível de que o líder do clã Presa do Dragão caiu. Com Nek'rosh morto e suas catapultas de guerra destruídas, Punhoforte sabe que o Presa do Dragão terá dificuldades para se recuperar, garantindo que Porto de Menethil e o Pantanal estejam finalmente a salvo de ataques organizados.",al={"por que o punhoforte quer a cabeça do nek'rosh","por que eles querem a cabeça do nek'rosh","propósito da cabeça do nek'rosh"}}},fp="15,176,17.341.0,17.130.0,26.160.0,36.191.0"}
P.entries["item:neru-fragment"] = {n="Fragmento Neru",s="O Fragmento Neru é um dos quatro pedaços antigos de pedra esculpida pertencentes à Pedra de Goaz, uma relíquia descoberta no Sítio de Escavação de Whelgar dentro do Pantanal. Desenterrado da terra revolvida, ele contém um trecho de escrita titânica antiga detalhando a história primordial de Azeroth.",h="O Fragmento Neru é um dos quatro pedaços antigos de pedra esculpida pertencentes à Pedra de Goaz, uma...",kw={"escavação","pedra de goaz","terra fofa","fragmento neru","prospector whelgar","uncovering the past","pantanal"},ang={["race:Dwarf"]="Para a Liga dos Exploradores, recuperar pedaços de tabuleta como o Fragmento Neru é vital para desenterrar segredos dos Titãs e juntar as peças das origens da raça dos anões."},sec={{t="Pedaço da Pedra de Goaz",b="Descoberta pela expedição arqueológica dos anões liderada pelo Prospector Whelgar, a Pedra de Goaz se partiu em quatro fragmentos distintos: os fragmentos Ados, Modr, Golm e Neru. Quando raptores invadiram o sítio de escavação, o trabalho foi paralisado, deixando o Fragmento Neru enterrado sob a terra fofa em meio às feras agressivas. Recuperar este fragmento é crucial para remontar a tabuleta, permitindo que os estudiosos anões decifrem um registro esquecido cujas palavras sobreviventes mencionam um plano divino e uma profecia fadada à ruína."},{t="Lendo a Tabuleta Restaurada",b="Uma vez que os quatro fragmentos restauram a Pedra de Goaz, o Prospector Whelgar continua traduzindo sua escrita titânica. As palavras recém-legíveis falam de Deuses Antigos acorrentados sob a terra."}},faq={{q="O que é o Fragmento Neru?",a="É um pedaço antigo de pedra quebrado de uma relíquia maior chamada Pedra de Goaz. Ele foi descoberto pela expedição dos anões no Pantanal antes que raptores invadissem a escavação.",al={"história do fragmento neru","o que é fragmento neru","pedaço da tabuleta neru"}},{q="Onde o fragmento é encontrado?",a="Ele jaz espalhado no Sítio de Escavação de Whelgar infestado de raptores a leste do Porto de Menethil no Pantanal, tipicamente enterrado sob a terra fofa ou escondido entre artefatos abandonados.",al={"onde encontrar fragmento neru","localização do fragmento neru","como obter fragmento neru"}},{q="O que acontece quando todos os quatro fragmentos são reunidos?",a="O Prospector Whelgar junta os pedaços da Pedra de Goaz para poder continuar traduzindo sua escrita titânica e investigar o mistério sugerido por seu texto sobrevivente.",al={"pedra de goaz completa","o que diz a pedra de goaz","final de uncovering the past"}}},fx={["1f660d59"]={q="De onde vem o Fragmento Neru e quem o fez?",a="O fragmento vem da antiga Pedra de Goaz descoberta na Escavação de Whelgar no Pantanal. Sua inscrição usa a escrita dos Titãs, mas o texto da missão recuperado não identifica seu criador.",al={"origem do fragmento neru","quem fez o fragmento neru","de onde veio o fragmento neru"}},b6f45f31={q="Por que o Prospector Whelgar quer o Fragmento Neru?",a="O Prospector Whelgar desenterrou a Pedra de Goaz logo antes de o local de escavação ser invadido por raptores, mas descobriu que a inscrição se quebrou em quatro partes distintas. Ele precisa urgentemente do Fragmento Neru junto com as outras três peças para montar a tabuleta e continuar decifrando as referências a um plano divino e a uma profecia condenada.",al={"por que encontrar o fragmento neru","por que whelgar precisa do fragmento neru","propósito do fragmento neru"}}},fp="13,161,23.442.0,27.190.1,26.162.0,28.175.0,50.193.1"}
P.entries["item:nessa-s-collection"] = {n="Coleção de Nessa",s="A Coleção de Nessa é um pacote de espinhas e escamas de peixe recolhidas das águas que cercam a Vila de Rut'theran. Preparado para estudo pelo vendedor de peixes Laird em Auberdine, ele ilustra o tamanho extraordinariamente gigantesco da vida aquática que prospera ao redor das raízes de Teldrassil.",h="A Coleção de Nessa é um pacote de espinhas e escamas de peixe recolhidas das águas que cercam a Vila de...",kw={"auberdine","espinhas de peixe","laird","nessa cantonegro","coleção de nessa","vila de rut'theran","teldrassil","vesprystus"},ang={["race:NightElf"]="A coleção oferece aos elfos noturnos sua primeira visão da natureza extraordinariamente vigorosa das águas que cercam Teldrassil à medida que transitam de seu lar insular para o continente."},sec={{t="A Fartura da Árvore do Mundo",b="Nessa Cantonegro, uma pescadora que reside na Vila de Rut'theran, na base de Teldrassil, reuniu esta coleção de espinhas e escamas de peixe para comparar a vida marinha da ilha com a do continente de Kalimdor. As águas que banham a Grande Árvore rendem pescarias de proporções impressionantes, levando Nessa a enviar provas físicas através do mar para Laird, um comerciante de peixes que trabalha nas docas de Auberdine. Transportada pelo mestre de hipogrifos da vila, Vesprystus, a encomenda serve como evidência prática da vitalidade florescente de Teldrassil."},{t="Uma Comparação Curiosa",b="Ao inspecionar o conteúdo em Costa Negra, Laird descobre que os espécimes superam em muito seus equivalentes do continente. A coleção contém mandíbulas com quase o dobro do tamanho das dos peixes nativos da costa de Costa Negra, além de escamas individuais do tamanho de um punho fechado. Para os elfos noturnos da costa, o pacote oferece uma visão clara de quão drasticamente as águas ao redor de Teldrassil diferem das margens sombrias do norte de Kalimdor."}},faq={{q="O que há dentro da Coleção de Nessa?",a="A coleção consiste em espinhas de peixe, mandíbulas enormes e escamas do tamanho de punhos colhidas de peixes capturados nas águas da Vila de Rut'theran.",al={"conteúdo da coleção de nessa","o que está no pacote","encomenda de espinhas de peixe"}},{q="Para quem a coleção está sendo enviada?",a="Ela é enviada para Laird, um vendedor de peixes elfo noturno que atua na vila portuária de Auberdine, na costa de Costa Negra.",al={"quem recebe a coleção de nessa","quem é laird","destino da entrega"}},{q="Por que Nessa reuniu esses espécimes de peixe?",a="Nessa queria comparar os peixes notavelmente grandes que prosperam ao redor de Teldrassil com a vida marinha encontrada ao longo do continente de Kalimdor.",al={"por que enviar espinhas de peixe","comparação de peixes de nessa","motivo da fartura de teldrassil"}},{q="Como a coleção chega a Auberdine?",a="Um viajante leva o pacote até o mestre de hipogrifos de Rut'theran, Vesprystus, que organiza a passagem sobre as águas até Auberdine para que a encomenda possa ser entregue a Laird.",al={"como é entregue","entrega de vesprystus","encomenda de hipogrifo"}}},fx={["6bde19ac"]={q="O que é a Coleção de Nessa?",a="A Coleção de Nessa é um pacote de espinhas e escamas de peixe reunidas das águas ao redor da Vila de Rut'theran. Ela representa a incomum recompensa marinha que prospera na base da Árvore do Mundo, Teldrassil, embalada com segurança para transporte através do mar até o continente de Kalimdor.",al={"o que é a coleção de nessa","coleção de nessa","item coleção de nessa"}},eb414ab6={q="De onde vem a Coleção de Nessa e quem a fez?",a="A coleção foi montada por Nessa Shadowsong, uma elfa noturna que reside na Vila de Rut'theran na base sul de Teldrassil. Aproveitando-se das capturas notavelmente grandes trazidas pelos pescadores locais da ilha, ela reuniu espécimes escolhidos para enviar ao exterior.",al={"quem fez a coleção de nessa","de onde vem a coleção de nessa","origem da coleção de nessa"}},d01c5154={q="Por que alguém quer a Coleção de Nessa?",a="Um vendedor de peixes chamado Laird em Auberdine aguarda os espécimes para que possa estudá-los. Nessa espera comparar o tamanho e o vigor surpreendentes das capturas de Rut'theran com os peixes do continente, e Laird está ansioso para examinar mandíbulas duas vezes maiores que o normal e escamas do tamanho de um punho.",al={"por que laird quer a coleção de nessa","por que entregar a coleção de nessa","propósito da coleção de nessa"}}},fp="18,132,24.419.0,20.355.0,34.237.0,36.98.0,42.120.0,40.145.0"}
P.entries["item:nether-gem"] = {n="Gema Etérea",s="A Gema Etérea é uma pedra arcana encantada confiada por uma figura enigmática do Lago Águas Claras. Imbuída de poder mágico, ela age como um canal de longa distância que permite ao seu mestre manifestar uma projeção arcana e se comunicar diretamente com Boanerges Stalactus na Cidade Baixa, embora a natureza completa da conexão entre eles ainda precise ser descoberta.",h="A Gema Etérea é uma pedra arcana encantada confiada por uma figura enigmática do Lago Águas Claras.",kw={"boanerges stalactus","lago águas claras","tertuliano arcanus","gema etérea","prodigal lich","cidade baixa"},ang={["class:Mage"]="Para praticantes do arcano, a Gema Etérea demonstra como mestres magos superam vastas distâncias por meio de clarividência mágica e projeções visuais em vez de se arriscarem em viagens.",["race:Undead"]="A entrega da pedra marca um grande triunfo diplomático para os Renegados, garantindo o poderoso Tertuliano Arcanus como um aliado contra o Flagelo e a Cruzada Escarlate."},sec={{t="Um Canal de Comunhão Arcana",b="Forjada ou encantada por Tertuliano Arcanus em sua ilha solitária no Lago Águas Claras, a Gema Etérea serve como um elo místico através das Clareiras de Tirisfal. Tertuliano, tendo se libertado do controle do Lich Rei por pura força de vontade, evitou por muito tempo a jovem nação dos Renegados por desconfiança. Após receber seu livro de feitiços perdido, ele confia a gema a um emissário como um gesto de boa vontade. Uma vez levada a Boanerges Stalactus no topo do Distrito da Magia na Cidade Baixa, a pedra canaliza a imagem mágica de Tertuliano diretamente diante do líder da Guilda dos Magos, abrindo o caminho para que o mago solitário se alinhe a Lady Sylvanas e aos Renegados."}},faq={{q="O que a Gema Etérea faz?",a="A Gema Etérea permite que Tertuliano Arcanus se comunique através de longas distâncias com Boanerges Stalactus. Quando Boanerges canaliza magia para dentro da pedra na Cidade Baixa, ela projeta uma imagem etérea de Tertuliano, permitindo que os dois poderosos magos conversem diretamente.",al={"propósito da gema etérea","o que é a gema etérea","o que a gema etérea faz"}},{q="Quem criou a Gema Etérea?",a="A gema é fornecida por Tertuliano Arcanus, um formidável necromante que habita uma ilha no Lago Águas Claras. Ele a entrega a um aventureiro para ser levada ao seu antigo camarada Boanerges após a recuperação do seu livro de feitiços perdido.",al={"quem fez a gema etérea","de onde vem a gema etérea","gema de tertuliano"}},{q="Por que a Gema Etérea é importante para os Renegados?",a="Ela serve como o instrumento que integra com sucesso Tertuliano Arcanus às fileiras dos Renegados. Tertuliano originalmente desconfiava de outros mortos-vivos, temendo que ainda fossem servos do Flagelo; a gema permite que ele restabeleça o contato com Boanerges Stalactus e jure lealdade a Lady Sylvanas.",al={"por que a gema etérea é importante","tertuliano renegados","renegados gema etérea"}}},fx={aa73e2cb={q="O que é a Gema Etérea?",a="A Gema Etérea é um foco mágico confiado a você por Tertuliano Arcanus, um poderoso mago morto-vivo que reside em uma ilha no Lago Águas Claras. Carregada com energias arcanas místicas, ela age como um conduto mágico que permite que Tertuliano se comunique através de grandes distâncias e projete sua imagem diretamente para seu antigo aliado Boanerges Stalactus na Cidade Baixa.",al={"o que é a gema etérea","lore da gema etérea","item gema etérea"}}},fp="10,160,29.595.1,28.211.0,27.175.1,50.228.1"}
P.entries["item:nether-wing"] = {n="Nether Wing",s="Uma Nether Wing é a asa de um demônio procurada pela Reclaimers Inc. em Desolação. Kreldig Ungor precisa de dez para os experimentos de um mago, junto com outros reagentes perigosos.",h="Uma Nether Wing é a asa de um demônio procurada pela Reclaimers Inc.",kw={"desolação","kreldig ungor","nether maiden","nether sister","nether sorceress","nether wing","nether wings","reagentes para reclaimers inc"},sec={{t="Uma asa de demônio",b="Nether Maidens, Nether Sorceresses e Nether Sisters em Desolação têm as asas que Kreldig Ungor procura. Ele pede dez como parte de uma coleção de reagentes para os experimentos de um mago. O trabalho também exige Felhound Brains e frascos de Doomwarder Blood, tornando essa coleta perigosa."}},faq={{q="Quem quer Nether Wings?",a="Kreldig Ungor, em Desolação, procura dez Nether Wings para os experimentos de um mago.",al={"quem precisa de nether wing","nether wings para quem"}},{q="De quem vêm as Nether Wings?",a="As Nether Wings vêm de Nether Maidens, Nether Sorceresses e Nether Sisters em Desolação.",al={"de onde vêm nether wings","origem de nether wing"}},{q="Por que Kreldig Ungor precisa delas?",a="Kreldig Ungor reúne Nether Wings como reagentes para os experimentos de um mago.",al={"por que nether wings","para que servem as asas"}},{q="Quais outros reagentes são necessários?",a="A coleção também exige Felhound Brains e frascos de Doomwarder Blood.",al={"outros reagentes","o que mais kreldig precisa"}}},fp="11,160,14.287.0,23.76.0,27.90.0,33.74.0,31.75.0"}
P.entries["item:nezzliok-s-head"] = {n="Nezzliok's Head"}
P.entries["item:ng-5"] = {n="NG-5",s="NG-5 é a designação abreviada de Nitromirglyceronium, um composto químico notoriamente volátil. Obtido para o engenhoqueiro gnomo Gaxim Deuxabu na Cordilheira das Torres de Pedra, ele serve como o catalisador essencial para seus planos explosivos de engenharia.",h="NG-5 é a designação abreviada de Nitromirglyceronium, um composto químico notoriamente volátil.",kw={"dinamite","explosivos","gaxim deuxabu","gnomo","ng-5","ng5","nitromirglyceronium","cordilheira das torres de pedra"},ang={["profession:Engineering"]="Engenheiros reconhecerão o NG-5 como Nitromirglyceronium, um catalisador químico temperamental estimado por engenhoqueiros quando a pólvora negra comum não tem a força necessária para detonar artilharia pesada.",["race:Gnome"]="Usar uma solução química instável para explodir vagões inteiros de dinamite para uma simples distração é a clássica resolução de problemas gnômica de alto risco em seu ápice."},sec={{t="Um Reagente Volátil",b="Conhecido formalmente como Nitromirglyceronium, o NG-5 é uma solução química excepcionalmente perigosa, manipulada apenas com extrema cautela — ou com o entusiasmo imprudente dos gnomos. Gaxim Deuxabu, um agente alocado na Cordilheira das Torres de Pedra, precisa da substância como um composto de ignição crítico. De acordo com Gaxim, o NG-5 fornece a reação exata necessária para detonar vagões inteiros carregados com dinamite, orquestrando uma explosão colossal destinada a servir de distração caótica contra seus adversários na região."}},faq={{q="O que é o NG-5?",a="NG-5 significa Nitromirglyceronium, uma mistura química altamente instável e volátil usada principalmente como reagente de ignição explosiva em demolições avançadas e engenharia gnômica.",al={"o que e ng5","o que e nitromirglyceronium","item ng 5"}},{q="Quem quer o NG-5 e por quê?",a="O engenheiro gnomo Gaxim Deuxabu, na Cordilheira das Torres de Pedra, precisa do produto químico. Ele serve como o componente vital necessário para detonar com precisão vários vagões lotados de dinamite, servindo de distração espetacular.",al={"quem precisa de ng-5","gaxim deuxabu ng-5","por que pegar ng5"}},{q="É perigoso manusear o NG-5?",a="Extremamente perigoso. O fornecedor alerta os mensageiros para manusearem o composto com cuidado absoluto, brincando que qualquer um que não seja aliado de Gaxim provavelmente acabará se explodindo em pedacinhos.",al={"ng5 e seguro","explosivo ng-5","ng5 vai explodir"}}},fx={["43a87313"]={q="De onde vem o NG-5 e quem o fez?",a="NG-5, também conhecido como Nitromirglyceronium, é obtido de um conhecido de Gaxim Deuxabu que fabrica compostos químicos especializados. É uma mistura alquímica extremamente volátil criada especificamente para reações explosivas, entregue apenas com advertências severas sobre a facilidade com que pode explodir um mensageiro desavisado em pedaços.",al={"quem fez o ng-5","onde você obtém o ng-5","criador do ng5"}}},fp="4,190,18.319.0,13.115.0,23.170.0,28.183.0"}
P.entries["item:nida-s-necklace"] = {n="Colar da Hilária",s="O Colar da Hilária é uma preciosa lembrança de infância perdida nas profundezas do Lago Plácido, nas Montanhas Cristarrubra. Presente de seu pai, o colar da pequena Hilary caiu nas águas turvas do lago enquanto as crianças de Vila Plácida pescavam nas docas.",h="O Colar da Hilária é uma preciosa lembrança de infância perdida nas profundezas do Lago Plácido, nas...",kw={"Vinteum","Lama Irisada","Hilária","Lago Plácido","Vila Plácida","Nida","Colar da Nida","Montanhas Cristarrubra","Shawn","Hilary","Colar da Hilária"},ang={["faction:Alliance"]="Os defensores de Vila Plácida estão sobrecarregados com as ameaças que cercam a cidade, deixando pequenos gestos de bondade, como ajudar as crianças da região a recuperar lembranças perdidas, nas mãos dos aventureiros da Aliança que passam por lá."},sec={{t="Perdido nas Profundezas",b="Enquanto pescava às margens de Vila Plácida com seu amigo Shawn, a pequena Hilary deixou cair acidentalmente seu precioso colar no Lago Plácido. O colar tem um imenso valor sentimental para a menina, pois foi um presente de seu pai. O medo das feras ferozes e dos murlocs agressivos que habitam as profundezas do lago mantém as crianças da região em segurança nas docas. Assim, o colar permanece afundado e enterrado no lodo do fundo do lago, à espera de um aventureiro disposto a mergulhar nas águas turvas para recuperá-lo."}},faq={{q="A quem pertence este colar?",a="O colar pertence a Hilary, uma garotinha que mora em Vila Plácida, nas Montanhas Cristarrubra. Foi um presente especial que ela ganhou de seu pai.",al={"a quem pertence o colar","Nida é a dona do colar","de quem é este colar","Hilary é a dona do colar"}},{q="Como o colar foi parar no Lago Plácido?",a="Hilary estava passando o dia pescando perto da água com seu amigo Shawn quando o colar se soltou e afundou no Lago Plácido, indo parar em um monte de lama reluzente no fundo do lago.",al={"como o colar foi parar no lago","por que o colar está na água","como o colar foi perdido"}},{q="Por que as crianças não mergulharam para recuperar o colar?",a="Os pais proíbem terminantemente que as crianças nadem no Lago Plácido. Suas águas profundas abrigam predadores aquáticos perigosos e murlocs agressivos, que representam uma ameaça mortal aos moradores da região.",al={"por que Nida não nadou para recuperar o colar","por que Shawn não pode recuperar o colar","por que Nida não nadou para recuperá-lo","por que Hilary não nadou para recuperar o colar","por que Hilary não nadou para recuperá-lo"}},{q="Quem é Vinteum?",a="Vinteum é o gatinho de estimação de Hilary, que está sempre ao lado dela em Vila Plácida e recebe alegremente a volta do colar junto com sua jovem dona.",al={"quem é o gatinho","gato de Nida","gato de Hilária","gato de Hilary"}}},fx={a22bd4db={q="Onde Hilary conseguiu o colar?",a="O colar foi um presente do pai de Hilary. Embora tenha pouca importância histórica ou mágica, é uma estimada lembrança de família dada a uma menina que vive em Vila Plácida.",al={"quem fez o colar da hilária","de onde veio o colar da hilária","quem deu o colar a hilary"}},["14f3017c"]={q="Por que estão procurando o Colar da Hilária?",a="Hilary perdeu o colar enquanto pescava nas docas do Lago Plácido. Como os pais dela proíbem as crianças de mergulhar nas águas infestadas de monstros, o amigo Shawn pede que aventureiros de passagem enfrentem as profundezas do lago e recuperem a estimada lembrança para ela.",al={"por que encontrar o colar da hilária","quem quer o colar da hilária","por que hilary quer seu colar de volta"}}},fp="17,165,18.314.0,33.106.0,46.102.0,47.157.0,14.120.0"}
P.entries["item:nightmare-shard"] = {n="Lasca de Pesadelo",s="A Lasca de Pesadelo é uma relíquia cristalina entregue a mensageiros por Falla Vento Sábio após ela examinar um Estilhaço Chamejante maculado recuperado da Caverna Ululante. Contendo a essência pura e perturbada do Sonho Esmeralda, ela carrega uma visão inquietante que incita alertas imediatos e sigilo entre os druidas de alta patente em Darnassus e no Penhasco do Trovão.",h="A Lasca de Pesadelo é uma relíquia cristalina entregue a mensageiros por Falla Vento Sábio após ela examinar...",kw={"sonho esmeralda","falla vento sábio","estilhaço chamejante","hamuul runa totem","em pesadelos","mathrengyl ursivagus","lasca de pesadelo","caverna ululante"},ang={["class:Druid"]="Para os druidas, a lasca é uma revelação assustadora de que seu santuário sagrado, o Sonho Esmeralda, não está mais a salvo da corrupção, validando preocupações sobre o destino de Naralex na Caverna Ululante.",["faction:Horde"]="A lasca traz notícias graves diretamente ao Platô dos Anciãos no Penhasco do Trovão, onde Hamuul Runa Totem se esforça para consolidar o lugar dos taurens dentro da ampla irmandade cenariana."},sec={{t="Uma Visão Corrompida",b="Quando Falla Vento Sábio inspeciona o misterioso Estilhaço Chamejante descoberto nas profundezas da Caverna Ululante, ela percebe que sua energia é muito mais sombria do que o previsto. Em vez de refletir a serenidade vital do Sonho Esmeralda, o fragmento reflete uma aflição retorcida e não natural: um pesadelo acordado. Temendo o que sua presença insinua, ela vincula essa essência maculada à Lasca de Pesadelo e ordena que seja levada diretamente aos líderes mais velhos do Círculo Cenariano sem demora."},{t="Presságios Silenciosos",b="Ao ser entregue ao Arquidruida Hamuul Runa Totem no Platô dos Anciãos ou a Mathrengyl Ursivagus em Darnassus, ambos os mestres reagem com perplexidade e consternação ao perscrutar suas profundezas. A visão contida ali abala sua compostura, confirmando suas suspeitas silenciosas de que algo deu terrivelmente errado dentro do próprio Sonho. Relutantes em semear pânico entre o público, os druidas rapidamente confiscam a lasca e advertem o mensageiro para não falar mais nada sobre o que testemunhou."}},faq={{q="O que é a Lasca de Pesadelo?",a="É uma lasca confiada a aventureiros por Falla Vento Sábio que contém a essência capturada do Sonho Esmeralda, derivada de um artefato trazido da Caverna Ululante. Em vez de energias pacíficas da natureza, ela emana uma visão onírica sombria e corruptora.",al={"o que é lasca de pesadelo","história da lasca de pesadelo"}},{q="Quem criou a Lasca de Pesadelo?",a="Falla Vento Sábio fornece a lasca ao mensageiro após analisar um fragmento chamejante trazido da Caverna Ululante. Ao perceber a gravidade e a corrupção de sua natureza, ela encarrega o mensageiro de levá-la diretamente a druidas seniores para estudo.",al={"quem fez a lasca de pesadelo","de onde vem a lasca"}},{q="Por que os líderes druidas estão tão alarmados com ela?",a="Olhar para o interior da lasca revela a Hamuul Runa Totem e Mathrengyl Ursivagus que o Sonho Esmeralda está sendo ativamente distorcido por um pesadelo. Devido ao perigo e ao potencial pânico que essa revelação poderia causar, ambos os anciãos silenciam imediatamente qualquer discussão adicional e mantêm o assunto estritamente entre membros seniores do Círculo Cenariano.",al={"por que hamuul está preocupado","por que mathrengyl esconde a lasca"}},{q="Para onde a lasca precisa ser entregue?",a="Aventureiros da Horda são instruídos a entregá-la ao Arquidruida Hamuul Runa Totem no Platô dos Anciãos, no Penhasco do Trovão, enquanto viajantes da Aliança a levam para Mathrengyl Ursivagus no Círculo Cenariano em Darnassus.",al={"para quem levo a lasca","onde entregar lasca de pesadelo"}}},fp="15,214,18.327.0,12.369.1,28.241.0,32.186.0,43.240.1,42.205.0"}
P.entries["item:nightsaber-fang"] = {n="Presa de Sabre-da-noite",s="Um dente afiado extraído dos predatórios sabres-da-noite que vagam pelos galhos selvagens de Teldrassil. Embora seja um troféu comum de caça, essas presas também são procuradas como reagentes brutos por habitantes locais da floresta com intenções duvidosas.",h="Um dente afiado extraído dos predatórios sabres-da-noite que vagam pelos galhos selvagens de Teldrassil.",kw={"dolanaar","presa","sabre-da-noite","reagente","sátiro","teldrassil","zenn cascovil"},ang={["class:Hunter"]="Abater um sabre-da-noite e pegar sua presa comprova seu domínio básico sobre a natureza, embora fornecer partes de feras para espíritos corrompidos da floresta distorça o próprio espírito da caça.",["race:NightElf"]="Os sabres-da-noite são companheiros queridos e símbolos da deusa Eluna, tornando profundamente vergonhosa a caça a esses predadores sagrados a mando de um sátiro traiçoeiro."},sec={{t="Troféu da Caçada",b="Os sabres-da-noite estão entre os predadores naturais mais letais nativos do norte de Kalimdor, reverenciados pelos elfos noturnos por sua agilidade, ferocidade e profunda ligação espiritual com Eluna. Pelos grandes galhos de Teldrassil, essas feras felinas caçam nas sombras sob a copa das árvores. Abater um deles rende presas afiadas que servem como prova inegável da perícia de um caçador, embora certas figuras escusas na floresta as procurem para propósitos rituais bem menos nobres."},{t="O Reagente de um Sátiro",b="Fora do povoado de Dolanaar espreita Zenn Cascovil, um sátiro ardiloso que se aproveita de viajantes ansiosos e inexperientes. Alegando precisar de reagentes da floresta, Zenn persuade aventureiros novatos a recolherem presas de sabre-da-noite junto com penas de estrigídeo e seda de aranha. Entregar tais reagentes predatórios ajuda diretamente o trapaceiro, que zomba abertamente do herói ingênuo na entrega."}},faq={{q="De onde vêm as Presas de Sabre-da-noite?",a="As Presas de Sabre-da-noite são obtidas dos predatórios sabres-da-noite que rondam a natureza selvagem de Teldrassil, principalmente por toda a floresta ao redor de Dolanaar.",al={"onde conseguir presas de sabre-da-noite","quem dropa presas de sabre-da-noite","fonte de presa de sabre-da-noite"}},{q="Quem quer Presas de Sabre-da-noite em Teldrassil?",a="Zenn Cascovil, um sátiro que espreita à beira da estrada principal nos arredores de Dolanaar, pede esses itens como parte de uma tarefa dada a aventureiros que passam por ali.",al={"quem precisa de presas de sabre-da-noite","entrega de presa de sabre-da-noite","quem compra presas de sabre-da-noite"}},{q="Por que Zenn Cascovil quer Presas de Sabre-da-noite?",a="Zenn alega precisar de reagentes de animais para realizar seus assuntos na floresta, embora mantenha em segredo a verdadeira natureza de seu trabalho e sinta prazer em enganar viajantes ingênuos para que o sirvam.",al={"por que zenn quer presas","proposito do reagente de zenn cascovil","motivo do pedido de zenn"}},{q="Que outros reagentes Zenn pede junto com as presas?",a="Junto com duas presas de sabre-da-noite, Zenn exige duas penas de coruja estrigídea e duas amostras de Seda de Aranha Lenhateia.",al={"o que mais zenn precisa","itens do pedido de zenn","outros reagentes para zenn"}}},fx={bc504af2={q="O que é uma Presa de Sabre-da-noite?",a="Uma Presa de Sabre-da-noite é um dente canino afiado tirado dos sabres-da-noite que rondam as florestas de Teldrassil. Embora seja apenas uma parte natural desses grandes felinos predadores, tais presas são procuradas por praticantes de artes das trevas que as valorizam como reagentes brutos para rituais clandestinos e poções não autorizadas.",al={"o que é uma presa de sabre-da-noite","lore da presa de sabre-da-noite","sobre presas de sabre-da-noite"}}},fp="15,118,18.331.0,17.310.1,36.115.0,41.98.0,45.138.1,58.112.0"}
P.entries["item:nimboya-s-pike"] = {n="Nimboya's Pike",s="Nimboya’s Pike é uma arma que Nimboya empresta para levar uma mensagem sombria aos trolls Witherbark das Terras Agrestes. A traição deles a Thrall despertou a ira da Horda contra suas aldeias.",h="Nimboya’s Pike é uma arma que Nimboya empresta para levar uma mensagem sombria aos trolls Witherbark das...",kw={"grim message","terras agrestes","horda","laden pike","nimboya","nimboya’s pike","lança","thrall","witherbark"},ang={["faction:Horde"]="A lança carrega a ira da Horda contra os Witherbarks por terem traído Thrall, seu antigo aliado."},sec={{t="Uma Mensagem Sombria",b="Na Selva do Espinhaço, Nimboya lhe entrega sua lança e envia você para o norte, às Terras Agrestes. Os trolls Witherbark já estiveram ao lado da Horda, mas traíram Thrall. Nimboya quer que eles vejam que essa traição terá resposta. Ele cita Hiri’watha e Zun’watha como lugares onde sua mensagem pode ser deixada."}},faq={{q="Para quem é Nimboya’s Pike?",a="Nimboya empresta a lança para que você leve sua mensagem aos trolls Witherbark nas Terras Agrestes.",al={"nimboya’s pike","para quem é a lança"}},{q="Por que Nimboya quer punir os Witherbarks?",a="Os trolls Witherbark já foram aliados da Horda, mas traíram Thrall.",al={"por que punir witherbark","traição dos witherbark"}},{q="Onde devo levar a lança?",a="Nimboya envia você às Terras Agrestes, a nordeste da Serraria Tarren, para deixar a mensagem em Hiri’watha ou Zun’watha.",al={"para onde levar a lança","lança das terras agrestes"}},{q="O que é Nimboya’s Laden Pike?",a="É Nimboya’s Pike com crânios de Witherbark, feita para ser colocada em uma de suas aldeias como uma mensagem sombria.",al={"laden pike","lança com crânios"}}},fp="14,182,14.292.0,28.96.0,48.78.0,29.116.0,31.112.1"}
P.entries["item:nissa-s-remains"] = {n="Restos Mortais de Nissa",s="Os Restos Mortais de Nissa são os despojos terrenos recuperados de Nissa Agamand, uma nobre da outrora rica dinastia Agamand no norte das Clareiras de Tirisfal. Morta e erguida como serva irracional do Flagelo durante a Terceira Guerra, ela e sua família agora são caçadas por antigos trabalhadores em busca de vingança.",h="Os Restos Mortais de Nissa são os despojos terrenos recuperados de Nissa Agamand, uma nobre da outrora rica...",kw={"moinhos dos agamand","montalvo","eurico palhares","mortes na família","nissa agamand","restos mortais de nissa","clareiras de tirisfal"},ang={["faction:Horde"]="Abater os Agamand reanimados e limpar seus moinhos protege o norte das Clareiras de Tirisfal contra focos remanescentes do Flagelo que ameaçam Montalvo e a Cidade Baixa.",["race:Undead"]="Para os Renegados, recuperar Tirisfal significa purgar tanto seus antigos opressores do Flagelo quanto os aristocratas ricos que condenaram trabalhadores comuns à morte-viva devido ao seu orgulho tolo."},sec={{t="Um Legado de Orgulho",b="Antes da Terceira Guerra, a família Agamand era a dinastia mais rica e influente das Clareiras de Tirisfal, operando moinhos prósperos pelas colinas do norte. Quando a Praga da Morte-viva se espalhou por Lordaeron, os patriarcas da família recusaram-se teimosamente a evacuar. Em vez disso, fortificaram suas propriedades e convenceram seus servos e trabalhadores a resistir. Essa arrogância custou a vida de todos. Os Agamand sucumbiram ao Flagelo, erguendo-se não com sua orgulhosa independência intacta, mas como servos trôpegos e irracionais subjugados à vontade do Lich Rei."},{t="Retribuição Amarga",b="No vilarejo de Montalvo, sobreviventes que mais tarde se libertaram sob a liderança da Rainha Sylvana Correventos não se esqueceram do orgulho fatal da família. Eurico Palhares, um antigo trabalhador nos Moinhos dos Agamand, guarda um rancor amargo contra seus antigos senhores por terem atraído os trabalhadores para as garras da morte-viva. Ele encarrega aventureiros de abater os Agamand reanimados e recuperar seus restos físicos, como os de Nissa. Para Palhares e outros entre os Renegados, queimar ou destruir essas relíquias oferece uma sensação sombria de desfecho e vingança rancorosa."}},faq={{q="Quem foi Nissa Agamand?",a="Nissa era membro da família Agamand, nobres de Lordaeron proprietários dos extensos Moinhos dos Agamand nas Clareiras de Tirisfal. Quando o Flagelo varreu Lordaeron, ela pereceu ao lado de seus parentes e foi ressuscitada como uma lacaia morta-viva sob o controle do Lich Rei.",al={"quem e nissa","historia de nissa","nissa agamand"}},{q="Por que Eurico Palhares quer os restos mortais de Nissa?",a="Eurico Palhares trabalhou nos Moinhos dos Agamand em vida. Ele ressente amargamente a família porque a recusa arrogante de fugir convenceu trabalhadores leais a permanecerem e morrerem. Coletar os restos mortais permite que ele se vingue de seus antigos senhores.",al={"por que eurico quer restos mortais","por que matar os agamand","motivo de eurico palhares"}},{q="Onde esses restos mortais são obtidos?",a="Nissa Agamand assombra as ruínas dos Moinhos dos Agamand nos confins do norte das Clareiras de Tirisfal, vagando entre as casas de fazenda decrépitas ao lado de seus parentes reanimados e lacaios irracionais do Flagelo.",al={"onde encontrar nissa","localizacao de nissa agamand"}},{q="Nissa manteve seu livre-arbítrio como os Renegados?",a="Não. Diferente dos Renegados que se libertaram do Lich Rei, Nissa e sua família continuaram escravizadas pelo Flagelo como mortos-vivos irracionais, desprovidos da consciência e da liberdade encontradas nos cidadãos da Cidade Baixa.",al={"nissa e uma renegada","nissa tinha livre arbitrio","nissa e do flagelo"}}},fx={a9aa03e3={q="O que são os Restos Mortais de Nissa?",a="Estes são os restos físicos de Nissa Agamand, um membro da rica dinastia Agamand que outrora possuía os moinhos nas Clareiras de Tirisfal do norte. Quando o Flagelo varreu Lordaeron, a família fortificou sua propriedade e convenceu seus trabalhadores a resistirem. Como o resto de seus parentes, Nissa caiu para a Praga e ergueu-se como uma serva sem mente a serviço do Lich Rei.",al={"o que são os restos mortais de nissa","restos mortais de nissa","a quem pertencem os restos mortais de nissa"}},["4cb46b58"]={q="De onde vêm os Restos Mortais de Nissa e quem os fez?",a="Eles são recuperados diretamente do cadáver destruído de Nissa Agamand nos Moinhos dos Agamand. Outrora uma aristocrata orgulhosa, ela sucumbiu à Praga da Morte-viva e permaneceu em suas terras ancestrais como uma criatura morta-viva. Os restos mortais são o que você salva após colocar sua forma de Flagelo sem mente para descansar.",al={"onde você obtém os restos mortais de nissa","como obter os restos mortais de nissa","quem derrubou os restos mortais de nissa"}}},fp="15,240,17.460.0,18.437.0,22.243.0,47.228.0,33.176.0,49.195.0"}
P.entries["item:nitroglycerin"] = {n="Nitroglicerina",s="A nitroglicerina é uma substância química volátil carregada por soldados e oficiais anões guarnecidos em Bael Modan, nos Sertões Meridionais. Ela serve como um agente explosivo industrial para as operações de escavação deles, embora também possa ser usada contra eles.",h="A nitroglicerina é uma substância química volátil carregada por soldados e oficiais anões guarnecidos em Bael...",kw={"bael modan","bael'dun","sertões","explosivos","gann agulha de pedra","nitroglicerina","revenge of gann"},ang={["profession:Engineering"]="Engenheiros reconhecerão imediatamente a nitroglicerina como um explosivo composto clássico, tornado estável e detonável quando absorvido em polpa de madeira porosa junto com um oxidante como o nitrato de sódio.",["race:Tauren"]="Os produtos químicos voláteis usados para marcar a terra ao redor de Bael Modan servem como um lembrete amargo da destruição industrial imposta à tribo Agulha de Pedra."},sec={{t="Demolição Industrial",b="Os anões Bael'dun despedaçaram as terras ancestrais dos tauren Agulha de Pedra usando perfuratrizes mecânicas pesadas e química volátil. Para abrir buracos profundos no solo e despedaçar as colinas, o pessoal anão no local de escavação de Bael Modan e em seu forte fortificado mantém estoques de nitroglicerina bruta à mão. Tanto soldados da linha de frente quanto oficiais como Lorde Cyrik Blackforge carregam frascos do fluido volátil consigo para alimentar a escavação destrutiva em curso."},{t="O Feitiço Virando Contra o Feiticeiro",b="Após a morte do Prospector Khazgorm, o bravo tauren deslocado Gann Agulha de Pedra buscou desmontar completamente a fortaleza anã invasora. Ao examinar os planos de engenharia anões, Gann percebeu que combinar nitroglicerina confiscada com polpa de madeira e nitrato de sódio cria uma carga explosiva potente o suficiente para revidar contra a guarnição militar fortificada de Bael Modan."}},faq={{q="De onde vem a nitroglicerina?",a="A nitroglicerina é carregada pelas forças anãs estacionadas em Bael Modan, nos Sertões Meridionais, incluindo Soldados Bael'dun, Atiradores de Elite, Oficiais e Lorde Cyrik Blackforge dentro do forte.",al={"onde encontrar nitroglicerina","quem deixa cair nitroglicerina","fonte de nitroglicerina"}},{q="Para que a nitroglicerina é usada?",a="Gann Agulha de Pedra a usa junto com polpa de madeira e nitrato de sódio para fabricar uma carga explosiva poderosa, voltando as próprias técnicas de demolição dos anões contra sua fortificação militar em Bael Modan.",al={"para que serve a nitroglicerina","propósito da nitroglicerina","ingredientes de revenge of gann"}},{q="Por que os anões estavam carregando isso para começo de conversa?",a="Os prospectores e a guarnição de Bael Modan dependem fortemente de explosivos, motores a vapor e produtos químicos voláteis para abrir a terra e escavar seu local de escavação arqueológica.",al={"por que os anões têm nitroglicerina","explosivos de bael modan"}},{q="Quem é Gann Agulha de Pedra?",a="Gann Agulha de Pedra é um guerreiro tauren exilado que perdeu suas terras ancestrais quando os anões estabeleceram o local de escavação e o forte em Bael Modan, expulsando sua tribo por meio da destruição industrial.",al={"quem é gann","gann agulha de pedra"}}},fx={["9ba54f78"]={q="O que é Nitroglicerina?",a="Nitroglicerina é uma substância química volátil carregada pelas forças anãs entrincheiradas em Bael Modan nos Sertões Meridionais. A expedição Bael'dun depende de engenharia pesada e materiais explosivos para escavar terras ancestrais dos tauren e abrir a terra. Em misturas voláteis, ela serve como um componente crítico na construção de cargas explosivas de alto rendimento.",al={"o que é nitroglicerina","lore do item nitroglicerina","o que a nitroglicerina faz"}}},fp="13,181,21.348.0,29.333.1,35.166.0,35.138.0,52.142.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Carta Comum",s="A Carta Comum é uma missiva selada e sem identificação confiada aos Renegados recém-despertados que deixam Plangemortis. Entregue por Calvino Mourão sob o pretexto de uma incumbência, ela orienta o portador a seguir pela estrada até a Estalajadeira Geni na Taberna Finda Forca em Montalvo.",h="A Carta Comum é uma missiva selada e sem identificação confiada aos Renegados recém-despertados que deixam...",kw={"a rogue's deal","montalvo","calvino mourão","plangemortis","estalajadeira geni","carta comum","geni"},ang={["class:Rogue"]="A postura suspeita de Calvino Mourão e a mudança abrupta no comportamento de Geni carregam todas as marcas de intrigas de ladinos de baixo escalão e de comunicação codificada do submundo.",["race:Undead"]="Para os Renegados recém-erguidos, levar esta carta é um dos primeiros incentivos para deixar os limites de Plangemortis e explorar os assentamentos mais amplos das Clareiras de Tirisfal."},sec={{t="A Incumbência de um Mensageiro",b="Renegados recém-erguidos que pretendem se aventurar além de Plangemortis são abordados por Calvino Mourão, um ladino suspeito que vaga pelo perímetro do vilarejo. Afirmando estar exausto de lutar contra zumbis irracionais e aracnídeos, Calvino pede aos viajantes que levem um envelope simples e sem marcas pela estrada a leste até Montalvo. Endereçada informalmente a uma estalajadeira chamada Geni, a carta serve como uma desculpa para impulsionar os viajantes para fora do vale e em direção à Taberna Finda Forca, embora as promessas de Calvino sobre uma rica compensação soem vazias desde o início."},{t="Correspondência Suspeita",b="Ao ser feita a entrega em Montalvo, a Estalajadeira Geni tenta inicialmente uma farsa alegre e exagerada, alegando que a carta deve ser uma doce notícia de sua santa mãe em Plangemortis. Quando percebe que o mensageiro nota sua atuação desajeitada, sua postura agradável desaparece em uma irritação aguda. Ela toma a carta bruscamente, recusa-se a revelar quem realmente a enviou ou o que ela contém, e ordena asperamente que o portador se afaste, a menos que pretenda pagar por um quarto."}},faq={{q="O que é a Carta Comum?",a="É um envelope simples e desadornado entregue a novos aventureiros Renegados por Calvino Mourão em Plangemortis, destinado à entrega para a Estalajadeira Geni em Montalvo.",al={"carta comum","o que é esta carta","carta de calvino"}},{q="Quem envia a carta e quem a recebe?",a="Calvino Mourão, um ladino situado em Plangemortis, entrega a carta a mensageiros. Ela é endereçada à Estalajadeira Geni na Taberna Finda Forca em Montalvo.",al={"quem enviou a carta","quem recebe a carta","remetente da carta"}},{q="O que a carta realmente diz?",a="O conteúdo específico da carta não é revelado ao jogador. Ao ser questionada, a Estalajadeira Geni abandona sua fachada alegre e lhe diz com irritação que as origens e o conteúdo da carta não são da sua conta.",al={"o que a carta diz","conteúdo da carta","é possível ler a carta"}},{q="Por que Calvino Mourão quer que ela seja entregue?",a="Calvino afirma que está ocupado demais combatendo zumbis e aranhas locais para fazer a entrega ele mesmo. Na prática, a entrega direciona os viajantes para fora de Plangemortis e os apresenta às comodidades e aos locais de descanso disponíveis em Montalvo.",al={"por que enviar a carta","motivo de calvino","por que montalvo"}}},fp="18,205,18.327.0,25.323.1,31.146.0,42.131.0,34.163.0,43.190.0"}
P.entries["item:nori-s-mug"] = {n="Caneca de Nóri",s="A Caneca de Nóri é o recipiente pessoal de Nóri Fluiorgulho, usado para entregar cerveja matinal escaldante através dos montes gélidos de Dun Morogh. Após entregar uma bebida quente para afastar o frio cortante dos Alpes, os viajantes recebem a tarefa de devolver o copo vazio ao seu dono econômico.",h="A Caneca de Nóri é o recipiente pessoal de Nóri Fluiorgulho, usado para entregar cerveja matinal escaldante...",kw={"bring back the mug","dun morogh","durnan cortapelo","cerveja matinal","nóri fluiorgulho","caneca de nóri"},ang={["race:Dwarf"]="Para os anões que enfrentam as tempestades de Dun Morogh, compartilhar uma bebida quente é algo natural, mas deixar utensílios de taverna bons se perderem em um monte de neve é um desperdício imperdoável."},sec={{t="O Retorno do Mensageiro",b="Nas passagens montanhosas congelantes de Dun Morogh, uma caneca de cerveja matinal fumegante é um dos poucos confortos capazes de combater o frio amargo. Nóri Fluiorgulho confia sua caneca a viajantes que entregam uma dose fresca e fumegante a Durnan Cortapelo em Sidermar. Uma vez vazia, o recipiente resistente deve fazer a jornada de volta. Como Nóri observa, canecas não nascem em árvores, e manter o controle de louças anãs duráveis é um negócio essencial quando a hospitalidade encontra o ermo nevado."}},faq={{q="Para que serve a Caneca de Nóri?",a="Ela serve como o recipiente para entregar cerveja matinal fumegante e escaldante para Durnan Cortapelo em Sidermar. Assim que Durnan bebe o suficiente para se aquecer, a caneca vazia deve ser levada de volta para Nóri Fluiorgulho.",al={"objetivo da caneca de nori","o que havia na caneca","copo de nori"}},{q="Quem é o dono desta caneca?",a="A caneca pertence a Nóri Fluiorgulho, um anão estacionado em Dun Morogh que valoriza suas posses e insiste que os mensageiros devolvam suas canecas em vez de deixá-las espalhadas pela neve.",al={"quem é nori","dono da caneca","de quem é a caneca"}},{q="Por que Nóri insiste em receber a caneca de volta?",a="Louças de barro boas e canecas resistentes são suprimentos práticos no clima montanhoso rigoroso. Como Nóri observa francamente, canecas não nascem em árvores, tornando um ponto de orgulho e praticidade garantir que cada copo emprestado retorne à sua posse.",al={"por que devolver a caneca","por que nori a quer de volta","canecas não nascem em árvores"}},{q="O que foi bebido da caneca?",a="Ela continha cerveja matinal escaldante, uma bebida quente e encorpada apreciada pelos anões em Dun Morogh para afastar o frio cortante e aquecer a alma.",al={"o que havia no copo","o que é cerveja matinal","bebida cerveja matinal"}}},fp="10,154,18.339.0,28.137.0,18.103.0,45.128.0,28.88.0"}
